                    <td className="px-6 py-4 text-center">
                      <span className="bg-slate-100 px-2 py-1 rounded text-xs font-bold text-slate-600">
                        {sale.items.length} items
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right font-bold text-slate-800">
                      ${sale.total.toFixed(2)}
                    </td>
                    <td className="px-6 py-4 text-center">
                      {sale.status === 'voided' ? (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-red-100 text-red-700">
                          <Ban className="w-3 h-3 mr-1" /> Voided
                        </span>
                      ) : (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-green-100 text-green-700">
                          <CheckCircle className="w-3 h-3 mr-1" /> Completed
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => setSelectedSale(sale)}
                        className="p-2 bg-slate-100 text-slate-600 rounded hover:bg-slate-200 transition-colors"
                      >
                        <Eye className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Sale Detail Modal */}
      {selectedSale && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg max-h-[90vh] flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <div>
                 <h3 className="text-xl font-bold text-slate-800">Invoice Details</h3>
                 <p className="text-sm text-slate-500 font-mono">#{selectedSale.id}</p>
              </div>
              <div className="flex items-center space-x-2">
                 {selectedSale.status === 'voided' && (
                    <span className="px-3 py-1 bg-red-100 text-red-700 rounded-full text-xs font-bold uppercase tracking-wide flex items-center">
                       <RotateCcw className="w-3 h-3 mr-1" /> Stock Restored
                    </span>
                 )}
                 <button onClick={() => setSelectedSale(null)} className="text-slate-400 hover:text-slate-600">
                   <XCircle className="w-6 h-6" />
                 </button>
              </div>
            </div>

            <div className="p-6 overflow-y-auto flex-1">
               <div className="flex justify-between mb-4 text-sm">
                  <div className="text-slate-500">
                     <p>Date: <span className="font-medium text-slate-700">{new Date(selectedSale.date).toLocaleString()}</span></p>
                     <p>Customer: <span className="font-medium text-slate-700">{selectedSale.customerName || 'Walk-in'}</span></p>
                  </div>
                  <div className="text-right text-slate-500">
                     <p>Payment: <span className="font-medium text-slate-700 capitalize">{selectedSale.paymentMethod}</span></p>
                  </div>
               </div>

               <div className="border rounded-lg overflow-hidden mb-6">
                  <table className="w-full text-sm">
                     <thead className="bg-slate-50 text-slate-500">
                        <tr>
                           <th className="px-4 py-2 text-left">Item</th>
                           <th className="px-4 py-2 text-right">Qty</th>
                           <th className="px-4 py-2 text-right">Price</th>
                           <th className="px-4 py-2 text-right">Total</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-100">
                        {selectedSale.items.map((item, idx) => (
                           <tr key={idx}>
                              <td className="px-4 py-2">
                                 <div className="font-medium text-slate-800">{item.name}</div>
                                 {item.selectedVariantId && <div className="text-xs text-slate-400">Variant</div>}
                              </td>
                              <td className="px-4 py-2 text-right">{item.quantity}</td>
                              <td className="px-4 py-2 text-right">${item.sellPrice.toFixed(2)}</td>
                              <td className="px-4 py-2 text-right font-bold">${(item.sellPrice * item.quantity).toFixed(2)}</td>
                           </tr>
                        ))}
                     </tbody>
                     <tfoot className="bg-slate-50 font-bold text-slate-800">
                        <tr>
                           <td colSpan={3} className="px-4 py-3 text-right">Subtotal</td>
                           <td className="px-4 py-3 text-right">${(selectedSale.subtotal || selectedSale.total).toFixed(2)}</td>
                        </tr>
                        {selectedSale.discountAmount && selectedSale.discountAmount > 0 && (
                           <tr className="text-green-600">
                              <td colSpan={3} className="px-4 py-1 text-right">Discount</td>
                              <td className="px-4 py-1 text-right">-${selectedSale.discountAmount.toFixed(2)}</td>
                           </tr>
                        )}
                        <tr className="border-t border-slate-200">
                           <td colSpan={3} className="px-4 py-3 text-right text-lg">Grand Total</td>
                           <td className="px-4 py-3 text-right text-lg">${selectedSale.total.toFixed(2)}</td>
                        </tr>
                     </tfoot>
                  </table>
               </div>

               {selectedSale.status !== 'voided' && isAdminOrManager && (
                  <div className="bg-red-50 p-4 rounded-lg border border-red-200 flex items-start">
                     <AlertTriangle className="w-5 h-5 text-red-600 mr-3 mt-0.5" />
                     <div>
                        <h4 className="font-bold text-red-800 text-sm">Void Transaction</h4>
                        <p className="text-xs text-red-600 mt-1">
                           Voiding this sale will automatically return all items to inventory. The invoice will be marked as Cancelled.
                        </p>
                        <button 
                           onClick={handleVoid}
                           className="mt-3 px-4 py-2 bg-red-600 text-white rounded-lg text-xs font-bold uppercase tracking-wide hover:bg-red-700 shadow-sm"
                        >
                           Void & Restore Stock
                        </button>
                     </div>
                  </div>
               )}
            </div>

            <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 rounded-b-xl">
               <button 
                  onClick={handlePrint}
                  className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50 flex items-center shadow-sm"
               >
                  <Printer className="w-4 h-4 mr-2" />
                  Reprint Bill
               </button>
               <button 
                  onClick={() => setSelectedSale(null)}
                  className="px-4 py-2 bg-slate-800 text-white font-medium rounded-lg hover:bg-slate-900"
               >
                  Close
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export enum Category {
  CEMENT = 'Cement & Concrete',
  STEEL = 'Steel & Metal',
  WOOD = 'Wood & Lumber',
  PAINT = 'Paints & Finishes',
  TOOLS = 'Tools & Hardware',
  PLUMBING = 'Plumbing',
  ELECTRICAL = 'Electrical',
  CONSUMABLES = 'General Consumables'
}

export type UnitCategory = 'Weight' | 'Length' | 'Quantity';

export interface UnitDefinition {
  id: string;
  name: string;      // e.g. Kilogram
  symbol: string;    // e.g. kg
  category: UnitCategory;
  baseFactor: number; // 1 for base unit (e.g. g), 1000 for kg
  isBase: boolean;   // True if this is the reference unit
}

export interface CategoryItem {
  id: string;
  name: string;
  parentId: string | null; // null for root categories
  description?: string;
}

export interface ProductVariant {
  id: string;
  name: string;      // e.g., 'Piece', 'Small', 'Red'
  code: string;      // SKU/Code for the variant
  barcode: string;   // Barcode for the variant
  conversionFactor: number; // How many variants in the main unit (e.g. 12 pieces in 1 box)
  price: number;     // Price per variant
}

export interface ProductInventory {
  warehouseId: string;
  quantity: number;
}

export interface BranchPrice {
  branchId: string;
  price: number;
}

export interface ProductPhysical {
  weight?: number; // kg
  width?: number;  // cm
  height?: number; // cm
  depth?: number;  // cm (length)
}

export interface Product {
  id: string;
  name: string;
  category: Category | string; 
  price: number;     // Base Price (Global)
  branchPrices?: BranchPrice[]; // Overrides per branch
  stock: number;     // Stock count in MAIN units (Aggregate Total)
  minStock?: number; // Minimum stock threshold for alerts
  warehouseInventory?: ProductInventory[]; // Breakdown by warehouse
  unit: string;      // Name of the MAIN unit (e.g., 'bag', 'box')
  physical?: ProductPhysical; // New: Physical attributes
  imageUrl?: string;
  sku: string;       // SKU of MAIN unit
  barcode: string;   // Barcode of MAIN unit
  variants?: ProductVariant[]; // List of sub-products/variants
}

export interface CartItem extends Product {
  quantity: number;
  // Handling multi-unit/variant logic
  selectedVariantId?: string; // null if main unit, string if variant
  sellPrice: number; 
  sellUnit: string;  
  sellConversionFactor: number; // 1 for main, X for variant
}

export interface Sale {
  id: string;
  items: CartItem[];
  subtotal?: number; // Raw total before discount/tax
  discountAmount?: number; // Deduction amount
  total: number; // Final payable amount
  date: string;
  paymentMethod: 'cash' | 'card' | 'transfer' | 'qr';
  amountReceived?: number; // Amount given by customer
  change?: number; // Change returned
  status: 'completed' | 'voided'; // New status field
  syncStatus?: 'synced' | 'pending' | 'failed'; // Track sync state
  customerId?: string; // Link to customer
  customerName?: string; // Snapshot of name
}

export interface EstimateRequest {
  query: string;
}

export interface EstimateResultItem {
  productName: string;
  estimatedQuantity: number;
  unit: string;
  reasoning: string;
  matchedProductId?: string; // If found in inventory
}

// --- AI Inventory Analysis Types ---
export interface ReorderSuggestion {
  productId: string;
  productName: string;
  currentStock: number;
  suggestedReorderQty: number;
  priority: 'High' | 'Medium' | 'Low';
  reasoning: string;
}

export interface NewProductSuggestion {
  name: string;
  categoryName: string;
  estimatedPrice: number;
  reasoning: string;
  suggestedUnit: string;
}

export interface BundleSuggestion {
  bundleName: string;
  components: string[];
  estimatedPrice: number;
  reasoning: string;
  targetAudience: string;
}

export interface InventoryAnalysisResult {
  reorders: ReorderSuggestion[];
  newProducts: NewProductSuggestion[];
  bundles: BundleSuggestion[];
}

export interface Branch {
  id: string;
  name: string;
  address: string;
  phone: string;
  manager: string;
  isActive: boolean;
}

export interface PosMachine {
  id: string;
  branchId: string;
  machineNumber: string; // e.g., POS-01
  status: 'active' | 'maintenance' | 'inactive';
  lastActive?: string;
}

export interface Warehouse {
  id: string;
  branchId: string;
  name: string;
  code: string; // e.g., WH-01
  type: 'General' | 'Cold Storage' | 'Hazardous' | 'Showroom';
  description?: string;
}

export interface StorageLocation {
  id: string;
  warehouseId: string;
  zone: string;   // e.g., Zone A
  rack: string;   // e.g., Rack 01
  shelf: string;  // e.g., Shelf 03 (Level)
  bin: string;    // e.g., Bin B (Slot)
  fullCode: string; // Helper: A-01-03-B
  type?: 'Pallet' | 'Shelf' | 'Floor';
}

// --- Customer Types ---
export interface CustomerLevel {
  id: string;
  name: string;
  discountPercentage: number;
  color?: string;
}

export interface Customer {
  id: string;
  code: string; // Membership ID or Code
  name: string;
  phone: string;
  taxId?: string;
  address?: string;
  email?: string;
  loyaltyPoints: number;
  notes?: string;
  levelId?: string;
  level?: CustomerLevel;
}

// --- Stock Management Types ---

export type DocumentStatus = 'Draft' | 'Approved' | 'Completed' | 'Cancelled';

export interface StockItem {
  productId: string;
  variantId?: string; // Optional: if specific variant
  productName: string;
  unit: string;
  quantity: number;
  note?: string;
}

// 1. Transfer Request (ใบขอโอนย้ายสินค้า)
export interface StockTransfer {
  id: string;
  date: string;
  sourceWarehouseId: string;
  targetWarehouseId: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 2. Stock Count (ใบตรวจนับสินค้า)
export interface StockCountItem extends StockItem {
  systemQuantity: number; // Snapshot of system stock
  countedQuantity: number; // Actual count
  diff: number; // Calculated diff
}

export interface StockCount {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockCountItem[];
  referenceNo: string;
  counterName: string; // Who counted
  reason: string; // Mandatory reason for adjustment
}

// 3. Stock Reservation (ใบจองสินค้า)
export interface StockReservation {
  id: string;
  date: string;
  expiryDate: string;
  warehouseId: string;
  customerName: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 4. Goods Receipt (ใบเพิ่มสินค้า / รับเข้าจากผู้ขาย)
export interface StockReceiptItem extends StockItem {
  costPrice: number; // Cost per unit
}

export interface StockReceipt {
  id: string;
  date: string;
  warehouseId: string;
  vendorName: string;
  vendorInvoiceNo?: string;
  status: DocumentStatus;
  items: StockReceiptItem[];
  referenceNo: string;
  totalCost: number;
}

// 5. Stock Adjustment (ใบปรับปรุงยอดสินค้า)
export interface StockAdjustment {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockItem[]; // Quantity can be negative (decrease) or positive (increase)
  referenceNo: string;
  reason: string; // Mandatory
}

// --- Sync Types ---
export interface SyncLog {
  id: string;
  timestamp: string;
  type: 'Auto' | 'Manual' | 'Push' | 'Pull';
  status: 'Success' | 'Failed' | 'Partial';
  details: string; // e.g., "5 Sales uploaded, 0 Products updated"
  durationMs: number;
}

// --- User & Roles ---

export type UserRole = 'Admin' | 'Manager' | 'Staff' | 'Cashier';

export interface User {
  id: string;
  username: string;
  password?: string; // Added for login
  email?: string;    // Optional
  name: string;
  role: UserRole;
  avatarUrl?: string;
  department?: string;
  branchId?: string;
}

// --- Shift Management ---
// Actual working record (Time Clock)
export interface Shift {
  id: string;
  userId: string;
  branchId: string;
  startTime: string;
  endTime?: string;
  startCash: number;
  endCash?: number;
  notes?: string;
  status: 'Open' | 'Closed';
  userName?: string; // Optional helper
  branchName?: string; // Optional helper
}

// Planned Schedule (Roster)
export interface ShiftSchedule {
  id: string;
  userId: string;
  branchId: string;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:mm (24hr)
  endTime: string; // HH:mm (24hr)
  note?: string;
}

// --- Settings ---
export type Language = 'en' | 'th' | 'lo';

export interface LocalDatabaseConfig {
  enabled: boolean;
  type: 'postgresql' | 'sqlite' | 'mysql';
  host: string;
  port: string;
  databaseName: string;
  username: string;
  password: string;
}

export interface TaxSettings {
  enabled: boolean;             // Calculate Tax/VAT?
  rate: number;                 // e.g. 7.0 for 7%
  calculationMode: 'included' | 'excluded'; // 'included' (Price has VAT) or 'excluded' (Price + VAT)
  displayOnReceipt: boolean;    // Show tax line on UI/Receipt
}

export interface SystemSettings {
  // Company Info
  companyName: string;
  taxId: string;
  address: string;
  phone: string;

  // Localization
  language: Language;
  currencySymbol: string;

  // Interface
  defaultItemsPerPage: number;

  // Tax / VAT
  tax: TaxSettings;

  // Receipt & Print
  receiptHeader: string;
  receiptFooter: string;
  receiptLogoUrl?: string;
  receiptQrCodeUrl?: string; // Bank QR Code for receipt
  receiptPaperSize: '58mm' | '80mm' | 'A4';
  receiptAutoPrint: boolean;
  receiptShowTaxId: boolean;
  receiptShowCashier: boolean;
  receiptCopies: number;

  // Device Configuration
  currentBranchId?: string;
  currentPosId?: string;
  deviceRole?: 'Master' | 'Slave';

  // Local Database (For Slave offline mode)
  localDatabase?: LocalDatabaseConfig;

  // Synchronization (Master/Slave)
  masterApiUrl?: string; // e.g., http://192.168.1.100:3000
  autoSyncInterval?: number; // In minutes, 0 for manual
  lastSyncTime?: string;
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { 
  Product, Sale, CartItem, UnitDefinition, CategoryItem, Branch, PosMachine, 
  Warehouse, StorageLocation, StockTransfer, StockCount, StockReservation, 
  StockReceipt, StockAdjustment, DocumentStatus, User, SystemSettings, SyncLog, Customer, Shift, CustomerLevel, ShiftSchedule
} from '../types';
import { 
  INITIAL_SETTINGS, INITIAL_USERS, INITIAL_PRODUCTS, INITIAL_CATEGORIES_TREE, 
  INITIAL_UNITS, INITIAL_BRANCHES, INITIAL_POS_MACHINES, INITIAL_WAREHOUSES, 
  INITIAL_LOCATIONS, INITIAL_CUSTOMERS, INITIAL_CUSTOMER_LEVELS, INITIAL_SHIFT_SCHEDULES, INITIAL_SALES, INITIAL_SYNC_LOGS, INITIAL_TRANSFERS, INITIAL_COUNTS
} from '../services/data';
import { translations } from '../services/translations';

interface GlobalContextType {
  currentUser: User | null;
  setCurrentUser: (user: User | null) => void;
  users: User[];
  settings: SystemSettings;
  updateSettings: (s: SystemSettings) => void;
  products: Product[];
  sales: Sale[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  branches: Branch[];
  posMachines: PosMachine[];
  warehouses: Warehouse[];
  locations: StorageLocation[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  syncLogs: SyncLog[];
  customers: Customer[];
  customerLevels: CustomerLevel[];
  shifts: Shift[];
  shiftSchedules: ShiftSchedule[];

  // Translation Helper
  t: (key: string) => string;

  // Handlers
  processSale: (
    cartItems: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr',
    amountReceived?: number,
    change?: number
  ) => Promise<Sale>;
  handleVoidSale: (id: string) => Promise<void>;

  addProduct: (p: Product) => Promise<void>;
  updateProduct: (p: Product) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addUnit: (u: UnitDefinition) => Promise<void>;
  updateUnit: (u: UnitDefinition) => Promise<void>;
  deleteUnit: (id: string) => Promise<void>;

  addCategory: (c: CategoryItem) => Promise<void>;
  updateCategory: (c: CategoryItem) => Promise<void>;
  deleteCategory: (id: string) => Promise<void>;

  addBranch: (b: Branch) => Promise<void>;
  updateBranch: (b: Branch) => Promise<void>;
  deleteBranch: (id: string) => Promise<void>;

  addPos: (p: PosMachine) => Promise<void>;
  updatePos: (p: PosMachine) => Promise<void>;
  deletePos: (id: string) => Promise<void>;

  addWarehouse: (w: Warehouse) => Promise<void>;
  updateWarehouse: (w: Warehouse) => Promise<void>;
  deleteWarehouse: (id: string) => Promise<void>;

  addLocation: (l: StorageLocation) => Promise<void>;
  updateLocation: (l: StorageLocation) => Promise<void>;
  deleteLocation: (id: string) => Promise<void>;

  addUser: (u: User) => Promise<void>;
  updateUser: (u: User) => Promise<void>;
  deleteUser: (id: string) => Promise<void>;

  addCustomer: (c: Customer) => Promise<void>;
  updateCustomer: (c: Customer) => Promise<void>;
  deleteCustomer: (id: string) => Promise<void>;

  addCustomerLevel: (l: CustomerLevel) => Promise<void>;
  updateCustomerLevel: (l: CustomerLevel) => Promise<void>;
  deleteCustomerLevel: (id: string) => Promise<void>;

  updateTransfer: (t: StockTransfer) => Promise<void>;
  deleteTransfer: (id: string) => Promise<void>;
  updateCount: (c: StockCount) => Promise<void>;
  deleteCount: (id: string) => Promise<void>;
  updateReservation: (r: StockReservation) => Promise<void>;
  deleteReservation: (id: string) => Promise<void>;
  updateReceipt: (r: StockReceipt) => Promise<void>;
  deleteReceipt: (id: string) => Promise<void>;
  updateAdjustment: (a: StockAdjustment) => Promise<void>;
  deleteAdjustment: (id: string) => Promise<void>;
  handleStockStatusChange: (type: string, id: string, status: DocumentStatus) => Promise<void>;

  handleSyncOperation: (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => void;

  startShift: (branchId: string, startCash: number, notes?: string) => Promise<void>;
  endShift: (shiftId: string, endCash: number, notes?: string) => Promise<void>;
  addShiftSchedule: (schedule: ShiftSchedule) => Promise<void>;
  deleteShiftSchedule: (id: string) => Promise<void>;
}

const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // Initialize with Static Data for Client-Side Mode
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [settings, setSettings] = useState<SystemSettings>(INITIAL_SETTINGS);

  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [sales, setSales] = useState<Sale[]>(INITIAL_SALES);
  const [units, setUnits] = useState<UnitDefinition[]>(INITIAL_UNITS);
  const [categories, setCategories] = useState<CategoryItem[]>(INITIAL_CATEGORIES_TREE);
  const [branches, setBranches] = useState<Branch[]>(INITIAL_BRANCHES);
  const [posMachines, setPosMachines] = useState<PosMachine[]>(INITIAL_POS_MACHINES);
  const [warehouses, setWarehouses] = useState<Warehouse[]>(INITIAL_WAREHOUSES);
  const [locations, setLocations] = useState<StorageLocation[]>(INITIAL_LOCATIONS);
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [customerLevels, setCustomerLevels] = useState<CustomerLevel[]>(INITIAL_CUSTOMER_LEVELS);

  const [transfers, setTransfers] = useState<StockTransfer[]>(INITIAL_TRANSFERS);
  const [counts, setCounts] = useState<StockCount[]>(INITIAL_COUNTS);
  const [reservations, setReservations] = useState<StockReservation[]>([]);
  const [receipts, setReceipts] = useState<StockReceipt[]>([]);
  const [adjustments, setAdjustments] = useState<StockAdjustment[]>([]);
  const [syncLogs, setSyncLogs] = useState<SyncLog[]>(INITIAL_SYNC_LOGS);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [shiftSchedules, setShiftSchedules] = useState<ShiftSchedule[]>(INITIAL_SHIFT_SCHEDULES);

  // Load User from LocalStorage on mount
  useEffect(() => {
    const savedUser = localStorage.getItem('buildmaster_user');
    if (savedUser) {
      try {
        setCurrentUser(JSON.parse(savedUser));
      } catch (e) {
        localStorage.removeItem('buildmaster_user');
      }
    }
  }, []);

  // Update LocalStorage when user changes
  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('buildmaster_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('buildmaster_user');
    }
  }, [currentUser]);

  // Mock API Call simulation
  const mockApiCall = async <T,>(data: T): Promise<T> => {
    return new Promise((resolve) => {
      setTimeout(() => resolve(data), 300); // Simulate 300ms latency
    });
  };

  const t = (key: string): string => {
    const lang = settings.language || 'en';
    const keys = key.split('.');
    let value: any = translations[lang as keyof typeof translations];

    for (const k of keys) {
      if (value && typeof value === 'object' && k in value) {
        value = value[k];
      } else {
        return key; // Return key if translation missing
      }
    }
    return value as string;
  };

  const processSale = async (
    cartItems: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' = 'cash',
    amountReceived?: number,
    change?: number
  ): Promise<Sale> => {

    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items: cartItems,
      total,
      subtotal,
      discountAmount,
      paymentMethod,
      amountReceived,
      change,
      date: new Date().toISOString(),
      status: 'completed',
      syncStatus: 'pending',
      customerId,
      customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined
    };

    // Optimistically update Sales
    setSales(prev => [newSale, ...prev]);

    // Optimistically update Product Stock
    setProducts(prevProducts => {
      const updatedProducts = [...prevProducts];

      cartItems.forEach(item => {
        const productIndex = updatedProducts.findIndex(p => p.id === item.id);
        if (productIndex > -1) {
          const product = { ...updatedProducts[productIndex] };

          // Calculate deduction logic
          let deduction = item.quantity;

          product.stock = Math.max(0, product.stock - deduction);

          // Update warehouse specific inventory if available (simplified to first warehouse)
          if (product.warehouseInventory && product.warehouseInventory.length > 0) {
             product.warehouseInventory[0].quantity = Math.max(0, product.warehouseInventory[0].quantity - deduction);
          }

          updatedProducts[productIndex] = product;
        }
      });
      return updatedProducts;
    });

    await mockApiCall(null);
    return newSale;
  };

  const handleVoidSale = async (id: string) => {
    // 1. Find the sale
    const saleToVoid = sales.find(s => s.id === id);
    if (!saleToVoid) return;
    if (saleToVoid.status === 'voided') return; // Prevent double voiding

    // 2. Update Sale Status
    setSales(prev => prev.map(s => {
      if (s.id === id) {
        return { ...s, status: 'voided' };
      }
      return s;
    }));

    // 3. RESTORE Stock (Logic added)
    setProducts(prevProducts => {
      const updatedProducts = [...prevProducts];

      saleToVoid.items.forEach(item => {
        const productIndex = updatedProducts.findIndex(p => p.id === item.id);
        if (productIndex > -1) {
          const product = { ...updatedProducts[productIndex] };

          // Add quantity back to stock
          const qtyToRestore = item.quantity;
          product.stock += qtyToRestore;

          // Add back to default warehouse inventory
          if (product.warehouseInventory && product.warehouseInventory.length > 0) {
             product.warehouseInventory[0].quantity += qtyToRestore;
          }

          updatedProducts[productIndex] = product;
        }
      });

      return updatedProducts;
    });

    await mockApiCall(null);
  };

  const addProduct = async (p: Product) => {
    const newProduct = { ...p, id: `P-${Date.now()}` };
    setProducts(prev => [...prev, newProduct]);
    await mockApiCall(null);
  };
  const updateProduct = async (p: Product) => {
    setProducts(prev => prev.map(item => item.id === p.id ? p : item));
    await mockApiCall(null);
  };
  const deleteProduct = async (id: string) => {
    setProducts(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addUnit = async (u: UnitDefinition) => {
    setUnits(prev => [...prev, { ...u, id: `u-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateUnit = async (u: UnitDefinition) => {
    setUnits(prev => prev.map(item => item.id === u.id ? u : item));
    await mockApiCall(null);
  };
  const deleteUnit = async (id: string) => {
    setUnits(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addCategory = async (c: CategoryItem) => {
    setCategories(prev => [...prev, { ...c, id: `c-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateCategory = async (c: CategoryItem) => {
    setCategories(prev => prev.map(item => item.id === c.id ? c : item));
    await mockApiCall(null);
  };
  const deleteCategory = async (id: string) => {
    setCategories(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const updateSettings = async (s: SystemSettings) => {
    setSettings(s);
    await mockApiCall(null);
  };

  const addBranch = async (b: Branch) => {
    setBranches(prev => [...prev, { ...b, id: `b-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateBranch = async (b: Branch) => {
    setBranches(prev => prev.map(item => item.id === b.id ? b : item));
    await mockApiCall(null);
  };
  const deleteBranch = async (id: string) => {
    setBranches(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addPos = async (p: PosMachine) => {
    setPosMachines(prev => [...prev, p]);
    await mockApiCall(null);
  };
  const updatePos = async (p: PosMachine) => {
    setPosMachines(prev => prev.map(item => item.id === p.id ? p : item));
    await mockApiCall(null);
  }; 
  const deletePos = async (id: string) => {
    setPosMachines(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addWarehouse = async (w: Warehouse) => {
    setWarehouses(prev => [...prev, { ...w, id: `wh-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateWarehouse = async (w: Warehouse) => {
    setWarehouses(prev => prev.map(item => item.id === w.id ? w : item));
    await mockApiCall(null);
  };
  const deleteWarehouse = async (id: string) => {
    setWarehouses(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addLocation = async (l: StorageLocation) => {
    setLocations(prev => [...prev, { ...l, id: `loc-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateLocation = async (l: StorageLocation) => {
    setLocations(prev => prev.map(item => item.id === l.id ? l : item));
    await mockApiCall(null);
  };
  const deleteLocation = async (id: string) => {
    setLocations(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addUser = async (u: User) => {
    setUsers(prev => [...prev, { ...u, id: `u-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateUser = async (u: User) => {
    setUsers(prev => prev.map(item => item.id === u.id ? u : item));
    await mockApiCall(null);
  };
  const deleteUser = async (id: string) => {
    setUsers(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addCustomer = async (c: Customer) => {
    setCustomers(prev => [...prev, { ...c, id: `cust-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateCustomer = async (c: Customer) => {
    setCustomers(prev => prev.map(item => item.id === c.id ? c : item));
    await mockApiCall(null);
  };
  const deleteCustomer = async (id: string) => {
    setCustomers(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addCustomerLevel = async (l: CustomerLevel) => {
    setCustomerLevels(prev => [...prev, { ...l, id: `lvl-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateCustomerLevel = async (l: CustomerLevel) => {
    setCustomerLevels(prev => prev.map(item => item.id === l.id ? l : item));
    await mockApiCall(null);
  };
  const deleteCustomerLevel = async (id: string) => {
    setCustomerLevels(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  // Stock Documents Mock Logic
  const upsertDoc = (list: any[], setList: any, item: any) => {
    setList((prev: any[]) => {
      const idx = prev.findIndex(i => i.id === item.id);
      if (idx > -1) {
        const newArr = [...prev];
        newArr[idx] = item;
        return newArr;
      }
      return [item, ...prev];
    });
  };

  const deleteDoc = (setList: any, id: string) => {
    setList((prev: any[]) => prev.filter(i => i.id !== id));
  };

  const updateTransfer = async (t: StockTransfer) => { upsertDoc(transfers, setTransfers, t); await mockApiCall(null); };
  const deleteTransfer = async (id: string) => { deleteDoc(setTransfers, id); await mockApiCall(null); };

  const updateCount = async (c: StockCount) => { upsertDoc(counts, setCounts, c); await mockApiCall(null); };
  const deleteCount = async (id: string) => { deleteDoc(setCounts, id); await mockApiCall(null); };

  const updateReservation = async (r: StockReservation) => { upsertDoc(reservations, setReservations, r); await mockApiCall(null); };
  const deleteReservation = async (id: string) => { deleteDoc(setReservations, id); await mockApiCall(null); };

  const updateReceipt = async (r: StockReceipt) => { upsertDoc(receipts, setReceipts, r); await mockApiCall(null); };
  const deleteReceipt = async (id: string) => { deleteDoc(setReceipts, id); await mockApiCall(null); };

  const updateAdjustment = async (a: StockAdjustment) => { upsertDoc(adjustments, setAdjustments, a); await mockApiCall(null); };
  const deleteAdjustment = async (id: string) => { deleteDoc(setAdjustments, id); await mockApiCall(null); };

  const handleStockStatusChange = async (type: string, id: string, status: DocumentStatus) => {
    // 1. Update Document Status
    switch (type) {
      case 'transfer':
        setTransfers(prev => prev.map(d => d.id === id ? { ...d, status } : d));
        // Logic to move stock if Approved/Completed
        if (status === 'Approved') {
           const doc = transfers.find(d => d.id === id);
           if (doc) {
             console.log("Mock Stock Movement: ", doc);
           }
        }
        break;
      case 'count':
        setCounts(prev => prev.map(d => d.id === id ? { ...d, status } : d));
        break;
      case 'reservation':
        setReservations(prev => prev.map(d => d.id === id ? { ...d, status } : d));
        break;
      case 'receipt':
        setReceipts(prev => prev.map(d => d.id === id ? { ...d, status } : d));
        break;
      case 'adjustment':
        setAdjustments(prev => prev.map(d => d.id === id ? { ...d, status } : d));
        break;
    }
    await mockApiCall(null);
  };

  const handleSyncOperation = async (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
    const log: SyncLog = {
      id: `log-${Date.now()}`,
      timestamp: new Date().toISOString(),
      type,
      status: 'Success',
      details: 'Mock Data Sync Completed (Simulated)',
      durationMs: 750
    };
    setSyncLogs(prev => [log, ...prev]);
    await mockApiCall(null);
  };

  const startShift = async (branchId: string, startCash: number, notes?: string) => {
    if (!currentUser) return;
    const newShift: Shift = {
      id: `sh-${Date.now()}`,
      userId: currentUser.id,
      branchId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open'
    };
    setShifts(prev => [newShift, ...prev]);
    await mockApiCall(null);
  };

  const endShift = async (shiftId: string, endCash: number, notes?: string) => {
    setShifts(prev => prev.map(s => {
      if (s.id === shiftId) {
        return {
          ...s,
          endTime: new Date().toISOString(),
          endCash,
          notes,
          status: 'Closed'
        };
      }
      return s;
    }));
    await mockApiCall(null);
  };

  const addShiftSchedule = async (schedule: ShiftSchedule) => {
    setShiftSchedules(prev => [...prev, schedule]);
    await mockApiCall(null);
  };

  const deleteShiftSchedule = async (id: string) => {
    setShiftSchedules(prev => prev.filter(s => s.id !== id));
    await mockApiCall(null);
  };

  return (
    <GlobalContext.Provider value={{
      currentUser, setCurrentUser,
      users, settings, updateSettings,
      products, sales, units, categories, branches, posMachines, warehouses, locations, customers, customerLevels,
      transfers, counts, reservations, receipts, adjustments, syncLogs, shifts, shiftSchedules,

      t, 

      processSale, handleVoidSale,
      addProduct, updateProduct, deleteProduct,
      addUnit, updateUnit, deleteUnit,
      addCategory, updateCategory, deleteCategory,
      addBranch, updateBranch, deleteBranch,
      addPos, updatePos, deletePos,
      addWarehouse, updateWarehouse, deleteWarehouse,
      addLocation, updateLocation, deleteLocation,
      addUser, updateUser, deleteUser,
      addCustomer, updateCustomer, deleteCustomer,
      addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,

      updateTransfer, deleteTransfer,
      updateCount, deleteCount,
      updateReservation, deleteReservation,
      updateReceipt, deleteReceipt,
      updateAdjustment, deleteAdjustment,
      handleStockStatusChange,

      handleSyncOperation,
      startShift, endShift,
      addShiftSchedule, deleteShiftSchedule
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

import React, { useState, useMemo } from 'react';
import { Product, CartItem, Category, EstimateResultItem, SystemSettings, Customer, Sale } from '../types';
import { 
  Search, ShoppingCart, Plus, Minus, Trash2, CreditCard, Banknote, Sparkles, Box, 
  ArrowLeft, ScanBarcode, Layers, User, X, Percent, Star, QrCode, ArrowRight, Printer, CheckCircle
} from 'lucide-react';
import { AiAssistant } from './AiAssistant';
import { useGlobal } from '../context/GlobalContext';
import { useCartStore } from '../store/useCartStore';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr',
    amountReceived?: number,
    change?: number
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t } = useGlobal();
  const { cart, addToCart, removeFromCart, updateQuantity, clearCart } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);

  // Checkout & Payment State
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  // Receipt State
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);

  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [customerSearch, setCustomerSearch] = useState('');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) ||
        v.barcode.includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  const filteredCustomers = useMemo(() => {
    return customers.filter(c => 
      c.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      c.phone.includes(customerSearch) ||
      c.code.toLowerCase().includes(customerSearch.toLowerCase())
    );
  }, [customers, customerSearch]);

  // Determine Customer Level
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const handleBarcodeScan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;

    const mainMatch = products.find(p => p.barcode === searchTerm || p.sku === searchTerm);
    if (mainMatch) {
      addToCart(mainMatch, 1, undefined);
      setSearchTerm(''); 
      return;
    }

    for (const p of products) {
      if (p.variants) {
        const variantMatch = p.variants.find(v => v.barcode === searchTerm || v.code === searchTerm);
        if (variantMatch) {
          addToCart(p, 1, variantMatch.id);
          setSearchTerm('');
          return;
        }
      }
    }
  };

  const handleAiItemsAdded = (items: EstimateResultItem[]) => {
    items.forEach(est => {
      if (est.matchedProductId) {
        const product = products.find(p => p.id === est.matchedProductId);
        if (product) {
          addToCart(product, Math.ceil(est.estimatedQuantity), undefined);
        }
      }
    });
  };

  // --- Calculations ---
  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);

  // 1. Apply Discount
  let discountAmount = 0;
  let discountedSubtotal = rawSubtotal;

  if (customerLevel && customerLevel.discountPercentage > 0) {
    discountAmount = rawSubtotal * (customerLevel.discountPercentage / 100);
    discountedSubtotal = rawSubtotal - discountAmount;
  }

  // 2. Apply Tax
  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       // Tax added on top of discounted price
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       // Tax included in price, back-calculate from discounted price
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       // Subtotal for display is usually net of tax in this case
       // But keeping simple logic: finalTotal IS the discounted price
       finalTotal = discountedSubtotal;
    }
  }

  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - finalTotal);
  const remaining = Math.max(0, finalTotal - receivedAmount);

  const handleCheckoutClick = () => {
    setReceivedAmountStr('');
    setPaymentMethod('cash');
    setIsCheckoutOpen(true);
  };

  const handleProcessPayment = async () => {
    if (paymentMethod === 'cash' && receivedAmount < finalTotal) {
      alert("Insufficient amount received!");
      return;
    }

    setIsProcessing(true);

    // For non-cash methods, assume full payment
    const finalReceived = paymentMethod === 'cash' ? receivedAmount : finalTotal;
    const finalChange = paymentMethod === 'cash' ? change : 0;

    try {
      const sale = await onProcessSale(
        cart, 
        finalTotal, 
        selectedCustomer?.id, 
        discountAmount, 
        rawSubtotal,
        paymentMethod,
        finalReceived,
        finalChange
      );

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleNumPadClick = (val: string) => {
    if (val === 'C') {
      setReceivedAmountStr('');
    } else if (val === 'BS') {
      setReceivedAmountStr(prev => prev.slice(0, -1));
    } else if (val === '.') {
      if (!receivedAmountStr.includes('.')) setReceivedAmountStr(prev => prev + '.');
    } else {
      setReceivedAmountStr(prev => prev + val);
    }
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <div className="flex flex-col lg:flex-row h-full gap-6 relative">
      <div className="flex-1 flex flex-col min-w-0 h-full">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-slate-800">{t('pos.newOrder')}</h2>
          <div className="flex space-x-2">
             <button 
              onClick={() => setIsCustomerModalOpen(true)}
              className={`flex items-center px-4 py-2 rounded-lg shadow-sm transition-all duration-200 font-medium text-sm border ${
                selectedCustomer 
                  ? 'bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100' 
                  : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
              }`}
            >
              <User className="w-4 h-4 mr-2" />
              {selectedCustomer ? (
                <span className="flex items-center">
                  {selectedCustomer.name}
                  {customerLevel && (
                    <span className="ml-2 flex items-center bg-white/50 px-1.5 py-0.5 rounded text-[10px] border border-blue-200">
                      <Star className="w-3 h-3 mr-1 fill-current text-yellow-500" />
                      {customerLevel.name}
                    </span>
                  )}
                </span>
              ) : t('pos.selectCustomer')}
            </button>
            <button 
              onClick={() => setIsAiModalOpen(true)}
              className="flex items-center px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-lg shadow-md hover:shadow-lg transition-all duration-200 font-medium text-sm"
            >
              <Sparkles className="w-4 h-4 mr-2" />
              <span className="hidden md:inline">{t('pos.aiEstimate')}</span>
              <span className="md:hidden">AI</span>
            </button>
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 space-y-4">
          <form onSubmit={handleBarcodeScan} className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input
              type="text"
              placeholder={t('pos.scanPlaceholder')}
              className="w-full pl-10 pr-12 py-3 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 bg-slate-50 font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              autoFocus
            />
            <button type="submit" className="absolute right-2 top-1/2 transform -translate-y-1/2 p-1.5 bg-slate-200 rounded text-slate-600 hover:bg-slate-300">
               <ScanBarcode className="w-4 h-4" />
            </button>
          </form>

          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide -mx-1 px-1">
            <button
              onClick={() => setSelectedCategory('all')}
              className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors flex-shrink-0 ${
                selectedCategory === 'all' 
                  ? 'bg-slate-800 text-white' 
                  : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
              }`}
            >
              {t('pos.allItems')}
            </button>
            {Object.values(Category).map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors flex-shrink-0 ${
                  selectedCategory === cat 
                    ? 'bg-construction-orange text-white' 
                    : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto pr-1">
          {filteredProducts.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-slate-400">
              <Box className="w-12 h-12 mb-4 opacity-50" />
              <p>No products found.</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-20 md:pb-0">
              {filteredProducts.map((product) => {
                const hasVariants = product.variants && product.variants.length > 0;

                return (
                  <div 
                    key={product.id} 
                    onClick={() => !hasVariants && addToCart(product)}
                    className={`bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow flex flex-col ${!hasVariants ? 'cursor-pointer' : ''}`}
                  >
                    <div className="h-32 bg-slate-100 relative overflow-hidden">
                      {product.imageUrl ? (
                        <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                          <Box className="w-12 h-12" />
                        </div>
                      )}
                      <div className="absolute top-2 right-2 bg-white/90 backdrop-blur-sm px-2 py-1 rounded text-xs font-bold text-slate-700 shadow-sm">
                        {product.stock} {product.unit}
                      </div>
                      {product.sku && (
                         <div className="absolute bottom-2 left-2 bg-black/50 backdrop-blur-sm px-2 py-0.5 rounded text-[10px] text-white font-mono">
                           {product.sku}
                         </div>
                      )}
                    </div>
                    <div className="p-4 flex-1 flex flex-col">
                      <h3 className="font-bold text-slate-800 line-clamp-2 text-sm mb-1">{product.name}</h3>
                      <p className="text-xs text-slate-500 mb-3 line-clamp-1">{product.category}</p>

                      <div className="mt-auto">
                        <div className="flex justify-between items-center mb-3">
                          <span className="text-lg font-bold text-primary-600">${product.price.toFixed(2)}</span>
                        </div>

                        {hasVariants ? (
                          <div className="space-y-1">
                             <button
                                onClick={(e) => { e.stopPropagation(); addToCart(product); }}
                                className="w-full py-1.5 bg-slate-100 text-slate-700 rounded text-xs font-medium hover:bg-slate-200 transition-colors flex justify-between px-3"
                              >
                                <span>{product.unit}</span>
                                <span>${product.price}</span>
                              </button>
                             {product.variants!.map(v => (
                               <button
                                key={v.id}
                                onClick={(e) => { e.stopPropagation(); addToCart(product, 1, v.id); }}
                                className="w-full py-1.5 bg-orange-50 text-orange-700 rounded text-xs font-medium hover:bg-orange-100 transition-colors flex justify-between px-3"
                              >
                                <span>{v.name}</span>
                                <span>${v.price}</span>
                              </button>
                             ))}
                          </div>
                        ) : (
                          <button className="w-full py-2 bg-slate-800 text-white rounded-lg text-sm font-medium hover:bg-slate-900 transition-colors flex items-center justify-center">
                            <Plus className="w-4 h-4 mr-1" /> {t('common.add')}
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {cartItemCount > 0 && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="lg:hidden fixed bottom-4 right-4 left-4 bg-slate-900 text-white p-4 rounded-xl shadow-2xl flex justify-between items-center z-30"
        >
          <div className="flex items-center">
            <div className="bg-orange-500 rounded-full w-8 h-8 flex items-center justify-center font-bold text-sm mr-3">
              {cartItemCount}
            </div>
            <span className="font-bold">{t('pos.viewCart')}</span>
          </div>
          <span className="font-bold text-lg">${finalTotal.toFixed(2)}</span>
        </button>
      )}

      <div className={`
        fixed inset-y-0 right-0 z-40 w-full md:w-[400px] bg-white shadow-2xl transform transition-transform duration-300 ease-in-out lg:relative lg:translate-x-0 lg:shadow-none lg:w-[380px] lg:border-l lg:border-slate-200 flex flex-col
        ${isCartOpen ? 'translate-x-0' : 'translate-x-full'}
      `}>
        <div className="p-5 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
          <div className="flex items-center">
            <ShoppingCart className="w-5 h-5 text-slate-700 mr-2" />
            <h3 className="font-bold text-slate-800 text-lg">{t('pos.currentOrder')}</h3>
          </div>
          <button 
            onClick={() => setIsCartOpen(false)}
            className="lg:hidden p-2 text-slate-500 hover:bg-slate-200 rounded-full"
          >
            <X className="w-6 h-6" />
          </button>
          <div className="hidden lg:block bg-slate-200 text-slate-600 px-2 py-1 rounded text-xs font-bold">
            {cartItemCount} {t('common.items')}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-4">
              <ShoppingCart className="w-16 h-16 opacity-20" />
              <p className="text-sm font-medium">{t('pos.emptyCart')}</p>
              <p className="text-xs text-center max-w-[200px]">{t('pos.emptyCartDesc')}</p>
            </div>
          ) : (
            cart.map((item, index) => (
              <div key={`${item.id}-${item.selectedVariantId || 'main'}`} className="flex items-center bg-white p-3 rounded-lg border border-slate-100 shadow-sm animate-fade-in">
                <div className="flex-1 min-w-0">
                  <h4 className="font-bold text-slate-800 text-sm truncate">{item.name}</h4>
                  <div className="flex items-center text-xs text-slate-500 mt-1">
                    <span className="bg-slate-100 px-1.5 py-0.5 rounded mr-2">{item.sellUnit}</span>
                    <span>${item.sellPrice.toFixed(2)}</span>
                  </div>
                </div>

                <div className="flex items-center space-x-3 mx-3">
                  <button 
                    onClick={() => updateQuantity(index, -1)}
                    className="p-1 rounded bg-slate-100 hover:bg-slate-200 text-slate-600 transition-colors"
                  >
                    <Minus className="w-3 h-3" />
                  </button>
                  <span className="font-bold text-slate-800 w-6 text-center text-sm">{item.quantity}</span>
                  <button 
                    onClick={() => updateQuantity(index, 1)}
                    className="p-1 rounded bg-slate-100 hover:bg-slate-200 text-slate-600 transition-colors"
                  >
                    <Plus className="w-3 h-3" />
                  </button>
                </div>

                <div className="text-right min-w-[60px]">
                  <p className="font-bold text-slate-800 text-sm">${(item.sellPrice * item.quantity).toFixed(2)}</p>
                  <button 
                    onClick={() => removeFromCart(index)}
                    className="text-xs text-red-400 hover:text-red-600 mt-1"
                  >
                    {t('common.delete')}
                  </button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-200 space-y-3">
          {selectedCustomer && (
             <div className="flex justify-between items-center p-3 bg-blue-50 border border-blue-100 rounded-lg text-sm text-blue-900 mb-2">
                <div className="flex items-center">
                   <User className="w-4 h-4 mr-2 text-blue-600" />
                   <div>
                      <span className="font-bold block">{selectedCustomer.name}</span>
                      {customerLevel && (
                        <span className="text-xs text-blue-600 flex items-center">
                           <Star className="w-3 h-3 mr-1 fill-current" />
                           {customerLevel.name} ({customerLevel.discountPercentage}% Off)
                        </span>
                      )}
                   </div>
                </div>
                <button onClick={() => setSelectedCustomer(null)} className="text-blue-400 hover:text-blue-600">
                   <X className="w-4 h-4" />
                </button>
             </div>
          )}

          <div className="space-y-2 text-sm text-slate-600">
            <div className="flex justify-between">
              <span>{t('pos.subtotal')}</span>
              <span>${rawSubtotal.toFixed(2)}</span>
            </div>

            {discountAmount > 0 && (
               <div className="flex justify-between text-green-600 font-medium">
                 <span className="flex items-center"><Percent className="w-3 h-3 mr-1" /> Discount ({customerLevel?.discountPercentage}%)</span>
                 <span>-${discountAmount.toFixed(2)}</span>
               </div>
            )}

            {taxConfig?.enabled && (
              <div className="flex justify-between text-slate-500">
                <span>{t('pos.tax')} ({taxConfig.rate}%)</span>
                <span>${taxAmount.toFixed(2)}</span>
              </div>
            )}
          </div>

          <div className="flex justify-between items-end pt-3 border-t border-slate-200">
            <span className="text-slate-800 font-bold">{t('common.total')}</span>
            <span className="text-3xl font-bold text-slate-900">${finalTotal.toFixed(2)}</span>
          </div>

          <div className="grid grid-cols-2 gap-3 pt-2">
            <button 
              disabled={cart.length === 0}
              onClick={handleCheckoutClick}
              className="col-span-2 py-3 bg-slate-900 text-white rounded-xl font-bold text-lg hover:bg-slate-800 transition-colors shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
            >
              <Banknote className="w-5 h-5 mr-2" />
              {t('pos.payCash')}
            </button>
          </div>
        </div>
      </div>

      <AiAssistant 
        isOpen={isAiModalOpen} 
        onClose={() => setIsAiModalOpen(false)}
        inventory={products}
        onAddItemsToCart={handleAiItemsAdded}
      />

      {/* Customer Modal */}
      {isCustomerModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
           <div className="bg-white rounded-xl shadow-2xl w-full max-w-md max-h-[80vh] flex flex-col">
              <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
                 <h3 className="font-bold text-slate-800">{t('pos.selectCustomer')}</h3>
                 <button onClick={() => setIsCustomerModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                    <X className="w-5 h-5" />
                 </button>
              </div>
              <div className="p-4">
                 <div className="relative mb-4">
                    <Search className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                    <input
                       type="text"
                       placeholder={t('common.search')}
                       className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                       value={customerSearch}
                       onChange={e => setCustomerSearch(e.target.value)}
                       autoFocus
                    />
                 </div>
                 <div className="space-y-2 overflow-y-auto max-h-[400px]">
                    {filteredCustomers.map(cust => {
                       const level = customerLevels.find(l => l.id === cust.levelId);
                       return (
                          <button
                             key={cust.id}
                             onClick={() => {
                                setSelectedCustomer(cust);
                                setIsCustomerModalOpen(false);
                             }}
                             className="w-full flex items-center justify-between p-3 rounded-lg border border-slate-100 hover:bg-blue-50 hover:border-blue-200 transition-colors text-left group"
                          >
                             <div>
                                <div className="font-bold text-slate-800 group-hover:text-blue-700">{cust.name}</div>
                                <div className="text-xs text-slate-500">{cust.code} • {cust.phone}</div>
                             </div>
                             <div className="flex flex-col items-end">
                                {level && (
                                   <span 
                                      className="text-[10px] font-bold text-white px-2 py-0.5 rounded-full mb-1 shadow-sm"
                                      style={{ backgroundColor: level.color || '#94a3b8' }}
                                   >
                                      {level.name}
                                   </span>
                                )}
                                {cust.loyaltyPoints > 0 && (
                                   <span className="text-xs font-bold text-yellow-600 bg-yellow-50 px-2 py-0.5 rounded-full border border-yellow-100">
                                      {cust.loyaltyPoints} pts
                                   </span>
                                )}
                             </div>
                          </button>
                       );
                    })}
                    {filteredCustomers.length === 0 && (
                       <div className="text-center py-8 text-slate-400">
                          No customers found.
                       </div>
                    )}
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Checkout Modal */}
      {isCheckoutOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl flex flex-col md:flex-row overflow-hidden h-[80vh] md:h-[600px]">
            {/* Left: Payment Method Selection */}
            <div className="w-full md:w-1/3 bg-slate-50 border-r border-slate-200 p-6 flex flex-col">
              <h3 className="text-lg font-bold text-slate-800 mb-6">Payment Method</h3>
              <div className="space-y-3 flex-1">
                <button
                  onClick={() => setPaymentMethod('cash')}
                  className={`w-full flex items-center p-4 rounded-xl border-2 transition-all ${
                    paymentMethod === 'cash' 
                      ? 'border-primary-500 bg-primary-50 text-primary-700 shadow-md' 
                      : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'
                  }`}
                >
                  <Banknote className="w-6 h-6 mr-3" />
                  <span className="font-bold text-lg">Cash</span>
                </button>
                <button
                  onClick={() => setPaymentMethod('qr')}
                  className={`w-full flex items-center p-4 rounded-xl border-2 transition-all ${
                    paymentMethod === 'qr' 
                      ? 'border-primary-500 bg-primary-50 text-primary-700 shadow-md' 
                      : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'
                  }`}
                >
                  <QrCode className="w-6 h-6 mr-3" />
                  <span className="font-bold text-lg">OnePay / QR</span>
                </button>
                <button
                  onClick={() => setPaymentMethod('card')}
                  className={`w-full flex items-center p-4 rounded-xl border-2 transition-all ${
                    paymentMethod === 'card' 
                      ? 'border-primary-500 bg-primary-50 text-primary-700 shadow-md' 
                      : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'
                  }`}
                >
                  <CreditCard className="w-6 h-6 mr-3" />
                  <span className="font-bold text-lg">Card / Transfer</span>
                </button>
              </div>
              <div className="pt-6 border-t border-slate-200">
                <div className="flex justify-between items-center text-slate-600 mb-2">
                  <span>Total Due</span>
                  <span className="font-bold text-xl">${finalTotal.toFixed(2)}</span>
                </div>
              </div>
            </div>

            {/* Right: Payment Details & Numpad */}
            <div className="flex-1 p-6 flex flex-col relative">
              <button 
                onClick={() => setIsCheckoutOpen(false)} 
                className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"
              >
                <X className="w-6 h-6" />
              </button>

              <h3 className="text-xl font-bold text-slate-800 mb-6">
                {paymentMethod === 'cash' ? 'Cash Payment' : paymentMethod === 'qr' ? 'Scan QR Code' : 'Card Payment'}
              </h3>

              {paymentMethod === 'cash' ? (
                <div className="flex-1 flex flex-col">
                  {/* Amount Input Display */}
                  <div className="bg-slate-100 p-4 rounded-xl mb-4 text-right border border-slate-200">
                    <p className="text-sm text-slate-500 mb-1">Amount Received</p>
                    <div className="text-4xl font-bold text-slate-800 tracking-tight">
                      {receivedAmountStr ? `$${receivedAmountStr}` : <span className="text-slate-300">$0.00</span>}
                    </div>
                  </div>

                  {/* Change Calculation */}
                  <div className="flex justify-between items-center mb-6 px-2">
                    <div>
                      <p className="text-sm text-slate-500">Change Due</p>
                      <p className={`text-2xl font-bold ${change > 0 ? 'text-green-600' : 'text-slate-400'}`}>
                        ${change.toFixed(2)}
                      </p>
                    </div>
                    {remaining > 0 && (
                      <div className="text-right">
                        <p className="text-sm text-slate-500">Remaining</p>
                        <p className="text-xl font-bold text-red-500">${remaining.toFixed(2)}</p>
                      </div>
                    )}
                  </div>

                  {/* Numpad & Quick Cash */}
                  <div className="flex gap-4 flex-1">
                    <div className="flex-1 grid grid-cols-3 gap-3">
                      {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'BS'].map((num) => (
                        <button
                          key={num}
                          onClick={() => handleNumPadClick(num.toString())}
                          className="bg-white border border-slate-200 rounded-lg text-xl font-semibold text-slate-700 hover:bg-slate-50 active:bg-slate-100 transition-colors shadow-sm flex items-center justify-center"
                        >
                          {num === 'BS' ? <ArrowLeft className="w-6 h-6" /> : num}
                        </button>
                      ))}
                    </div>
                    <div className="w-1/3 flex flex-col gap-3">
                      <button onClick={() => handleQuickCash(Math.ceil(finalTotal))} className="flex-1 bg-blue-50 text-blue-700 font-bold rounded-lg hover:bg-blue-100 border border-blue-100 transition-colors">Exact</button>
                      <button onClick={() => handleQuickCash(10)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$10</button>
                      <button onClick={() => handleQuickCash(20)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$20</button>
                      <button onClick={() => handleQuickCash(50)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$50</button>
                      <button onClick={() => handleQuickCash(100)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$100</button>
                    </div>
                  </div>
                </div>
              ) : paymentMethod === 'qr' ? (
                <div className="flex-1 flex flex-col items-center justify-center text-center">
                  <div className="bg-white p-4 rounded-xl border-2 border-slate-200 shadow-sm mb-4">
                    <img 
                      src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=Payment_OnePay_${finalTotal}`} 
                      alt="Payment QR" 
                      className="w-48 h-48 object-contain"
                    />
                  </div>
                  <p className="font-bold text-slate-800 text-lg">Scan to Pay ${finalTotal.toFixed(2)}</p>
                  <p className="text-slate-500 text-sm mt-2">Use OnePay or compatible banking app</p>
                </div>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                  <div className="w-24 h-24 bg-blue-50 rounded-full flex items-center justify-center text-blue-500 mb-2">
                    <CreditCard className="w-12 h-12" />
                  </div>
                  <h4 className="text-xl font-bold text-slate-800">Ready for Card Payment</h4>
                  <p className="text-slate-500 max-w-xs">Please insert or swipe card on the terminal. Ensure the amount <strong className="text-slate-800">${finalTotal.toFixed(2)}</strong> is correct.</p>
                </div>
              )}

              <button
                onClick={handleProcessPayment}
                disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < finalTotal)}
                className="w-full py-4 mt-6 bg-construction-orange text-white rounded-xl font-bold text-xl hover:bg-orange-600 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg flex items-center justify-center"
              >
                {isProcessing ? (
                  <span className="flex items-center"><Sparkles className="w-5 h-5 animate-spin mr-2" /> Processing...</span>
                ) : (
                  <>
                    <CheckCircle className="w-6 h-6 mr-2" /> 
                    {paymentMethod === 'cash' && change > 0 
                      ? `Confirm & Return $${change.toFixed(2)}` 
                      : `Confirm Payment $${finalTotal.toFixed(2)}`}
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Receipt Modal */}
      {isReceiptOpen && lastSale && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm flex flex-col overflow-hidden">
            <div className="p-4 bg-slate-800 text-white flex justify-between items-center">
              <h3 className="font-bold flex items-center"><CheckCircle className="w-5 h-5 mr-2 text-green-400" /> Sale Completed</h3>
              <button onClick={() => setIsReceiptOpen(false)} className="text-slate-400 hover:text-white"><X className="w-5 h-5" /></button>
            </div>

            {/* Receipt Preview */}
            <div className="p-6 bg-slate-50 flex-1 overflow-y-auto max-h-[60vh]">
              <div className="bg-white p-4 shadow-sm border border-slate-200 text-xs font-mono text-slate-700">
                <div className="text-center mb-4">
                  <h2 className="text-lg font-bold text-slate-900 mb-1">{settings?.companyName || 'BuildMaster Store'}</h2>
                  <p>{settings?.address || '123 Main St'}</p>
                  <p>Tel: {settings?.phone || '012-345-6789'}</p>
                  <p className="mt-2 text-slate-500">#{lastSale.id}</p>
                  <p>{new Date(lastSale.date).toLocaleString()}</p>
                </div>

                <div className="border-b border-dashed border-slate-300 my-2"></div>

                <div className="space-y-1 mb-2">
                  {lastSale.items.map((item, i) => (
                    <div key={i} className="flex justify-between">
                      <span className="truncate w-32">{item.name}</span>
                      <span className="text-right">
                        {item.quantity} x {item.sellPrice.toFixed(2)}
                      </span>
                      <span className="font-bold text-right w-16">
                        {(item.quantity * item.sellPrice).toFixed(2)}
                      </span>
                    </div>
                  ))}
                </div>

                <div className="border-b border-dashed border-slate-300 my-2"></div>

                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span>Subtotal</span>
                    <span>${(lastSale.subtotal || lastSale.total).toFixed(2)}</span>
                  </div>
                  {lastSale.discountAmount ? (
                    <div className="flex justify-between text-green-600">
                      <span>Discount</span>
                      <span>-${lastSale.discountAmount.toFixed(2)}</span>
                    </div>
                  ) : null}
                  <div className="flex justify-between font-bold text-sm mt-1 pt-1 border-t border-slate-100">
                    <span>Total</span>
                    <span>${lastSale.total.toFixed(2)}</span>
                  </div>
                </div>

                <div className="border-b border-dashed border-slate-300 my-3"></div>

                <div className="space-y-1 text-slate-600">
                  <div className="flex justify-between">
                    <span className="capitalize">Paid via {lastSale.paymentMethod}</span>
                    <span>${(lastSale.amountReceived || lastSale.total).toFixed(2)}</span>
                  </div>
                  {lastSale.change !== undefined && lastSale.change > 0 && (
                    <div className="flex justify-between font-bold text-slate-900">
                      <span>Change</span>
                      <span>${lastSale.change.toFixed(2)}</span>
                    </div>
                  )}
                </div>

                <div className="mt-6 text-center text-slate-400 italic">
                  Thank you for shopping!
                </div>
              </div>
            </div>

            <div className="p-4 bg-white border-t border-slate-100 flex gap-3">
              <button 
                onClick={() => window.print()}
                className="flex-1 py-3 bg-white border border-slate-300 text-slate-700 rounded-lg font-bold hover:bg-slate-50 flex items-center justify-center transition-colors"
              >
                <Printer className="w-5 h-5 mr-2" /> Print
              </button>
              <button 
                onClick={() => setIsReceiptOpen(false)}
                className="flex-1 py-3 bg-slate-900 text-white rounded-lg font-bold hover:bg-slate-800 flex items-center justify-center transition-colors"
              >
                <Plus className="w-5 h-5 mr-2" /> New Order
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export enum Category {
  CEMENT = 'Cement & Concrete',
  STEEL = 'Steel & Metal',
  WOOD = 'Wood & Lumber',
  PAINT = 'Paints & Finishes',
  TOOLS = 'Tools & Hardware',
  PLUMBING = 'Plumbing',
  ELECTRICAL = 'Electrical',
  CONSUMABLES = 'General Consumables'
}

export type UnitCategory = 'Weight' | 'Length' | 'Quantity';

export interface UnitDefinition {
  id: string;
  name: string;      // e.g. Kilogram
  symbol: string;    // e.g. kg
  category: UnitCategory;
  baseFactor: number; // 1 for base unit (e.g. g), 1000 for kg
  isBase: boolean;   // True if this is the reference unit
}

export interface CategoryItem {
  id: string;
  name: string;
  parentId: string | null; // null for root categories
  description?: string;
}

export interface ProductVariant {
  id: string;
  name: string;      // e.g., 'Piece', 'Small', 'Red'
  code: string;      // SKU/Code for the variant
  barcode: string;   // Barcode for the variant
  conversionFactor: number; // How many variants in the main unit (e.g. 12 pieces in 1 box)
  price: number;     // Price per variant
}

export interface ProductInventory {
  warehouseId: string;
  quantity: number;
}

export interface BranchPrice {
  branchId: string;
  price: number;
}

export interface ProductPhysical {
  weight?: number; // kg
  width?: number;  // cm
  height?: number; // cm
  depth?: number;  // cm (length)
}

export interface Product {
  id: string;
  name: string;
  category: Category | string; 
  price: number;     // Base Price (Global)
  branchPrices?: BranchPrice[]; // Overrides per branch
  stock: number;     // Stock count in MAIN units (Aggregate Total)
  minStock?: number; // Minimum stock threshold for alerts
  warehouseInventory?: ProductInventory[]; // Breakdown by warehouse
  unit: string;      // Name of the MAIN unit (e.g., 'bag', 'box')
  physical?: ProductPhysical; // New: Physical attributes
  imageUrl?: string;
  sku: string;       // SKU of MAIN unit
  barcode: string;   // Barcode of MAIN unit
  variants?: ProductVariant[]; // List of sub-products/variants
}

export interface CartItem extends Product {
  quantity: number;
  // Handling multi-unit/variant logic
  selectedVariantId?: string; // null if main unit, string if variant
  sellPrice: number; 
  sellUnit: string;  
  sellConversionFactor: number; // 1 for main, X for variant
}

export interface Sale {
  id: string;
  items: CartItem[];
  subtotal?: number; // Raw total before discount/tax
  discountAmount?: number; // Deduction amount
  total: number; // Final payable amount
  date: string;
  paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit';
  paymentStatus: 'paid' | 'unpaid' | 'partial'; // Track debt status
  amountReceived?: number; // Amount given by customer
  change?: number; // Change returned
  remainingAmount?: number; // Amount left to pay (for credit/partial)
  status: 'completed' | 'voided'; // Order status
  syncStatus?: 'synced' | 'pending' | 'failed'; // Track sync state
  customerId?: string; // Link to customer
  customerName?: string; // Snapshot of name
}

export interface EstimateRequest {
  query: string;
}

export interface EstimateResultItem {
  productName: string;
  estimatedQuantity: number;
  unit: string;
  reasoning: string;
  matchedProductId?: string; // If found in inventory
}

// --- AI Inventory Analysis Types ---
export interface ReorderSuggestion {
  productId: string;
  productName: string;
  currentStock: number;
  suggestedReorderQty: number;
  priority: 'High' | 'Medium' | 'Low';
  reasoning: string;
}

export interface NewProductSuggestion {
  name: string;
  categoryName: string;
  estimatedPrice: number;
  reasoning: string;
  suggestedUnit: string;
}

export interface BundleSuggestion {
  bundleName: string;
  components: string[];
  estimatedPrice: number;
  reasoning: string;
  targetAudience: string;
}

export interface InventoryAnalysisResult {
  reorders: ReorderSuggestion[];
  newProducts: NewProductSuggestion[];
  bundles: BundleSuggestion[];
}

export interface Branch {
  id: string;
  name: string;
  address: string;
  phone: string;
  manager: string;
  isActive: boolean;
}

export interface PosMachine {
  id: string;
  branchId: string;
  machineNumber: string; // e.g., POS-01
  status: 'active' | 'maintenance' | 'inactive';
  lastActive?: string;
}

export interface Warehouse {
  id: string;
  branchId: string;
  name: string;
  code: string; // e.g., WH-01
  type: 'General' | 'Cold Storage' | 'Hazardous' | 'Showroom';
  description?: string;
}

export interface StorageLocation {
  id: string;
  warehouseId: string;
  zone: string;   // e.g., Zone A
  rack: string;   // e.g., Rack 01
  shelf: string;  // e.g., Shelf 03 (Level)
  bin: string;    // e.g., Bin B (Slot)
  fullCode: string; // Helper: A-01-03-B
  type?: 'Pallet' | 'Shelf' | 'Floor';
}

// --- Customer Types ---
export interface CustomerLevel {
  id: string;
  name: string;
  discountPercentage: number;
  color?: string;
}

export interface Customer {
  id: string;
  code: string; // Membership ID or Code
  name: string;
  phone: string;
  taxId?: string;
  address?: string;
  email?: string;
  loyaltyPoints: number;
  notes?: string;
  levelId?: string;
  level?: CustomerLevel;
}

// --- Stock Management Types ---

export type DocumentStatus = 'Draft' | 'Approved' | 'Completed' | 'Cancelled';

export interface StockItem {
  productId: string;
  variantId?: string; // Optional: if specific variant
  productName: string;
  unit: string;
  quantity: number;
  note?: string;
}

// 1. Transfer Request (ใบขอโอนย้ายสินค้า)
export interface StockTransfer {
  id: string;
  date: string;
  sourceWarehouseId: string;
  targetWarehouseId: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 2. Stock Count (ใบตรวจนับสินค้า)
export interface StockCountItem extends StockItem {
  systemQuantity: number; // Snapshot of system stock
  countedQuantity: number; // Actual count
  diff: number; // Calculated diff
}

export interface StockCount {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockCountItem[];
  referenceNo: string;
  counterName: string; // Who counted
  reason: string; // Mandatory reason for adjustment
}

// 3. Stock Reservation (ใบจองสินค้า)
export interface StockReservation {
  id: string;
  date: string;
  expiryDate: string;
  warehouseId: string;
  customerName: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 4. Goods Receipt (ใบเพิ่มสินค้า / รับเข้าจากผู้ขาย)
export interface StockReceiptItem extends StockItem {
  costPrice: number; // Cost per unit
}

export interface StockReceipt {
  id: string;
  date: string;
  warehouseId: string;
  vendorName: string;
  vendorInvoiceNo?: string;
  status: DocumentStatus;
  items: StockReceiptItem[];
  referenceNo: string;
  totalCost: number;
}

// 5. Stock Adjustment (ใบปรับปรุงยอดสินค้า)
export interface StockAdjustment {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockItem[]; // Quantity can be negative (decrease) or positive (increase)
  referenceNo: string;
  reason: string; // Mandatory
}

// --- Sync Types ---
export interface SyncLog {
  id: string;
  timestamp: string;
  type: 'Auto' | 'Manual' | 'Push' | 'Pull';
  status: 'Success' | 'Failed' | 'Partial';
  details: string; // e.g., "5 Sales uploaded, 0 Products updated"
  durationMs: number;
}

// --- User & Roles ---

export type UserRole = 'Admin' | 'Manager' | 'Staff' | 'Cashier';

export interface User {
  id: string;
  username: string;
  password?: string; // Added for login
  email?: string;    // Optional
  name: string;
  role: UserRole;
  avatarUrl?: string;
  department?: string;
  branchId?: string;
}

// --- Shift Management ---
// Actual working record (Time Clock)
export interface Shift {
  id: string;
  userId: string;
  branchId: string;
  startTime: string;
  endTime?: string;
  startCash: number;
  endCash?: number;
  notes?: string;
  status: 'Open' | 'Closed';
  userName?: string; // Optional helper
  branchName?: string; // Optional helper
}

// Planned Schedule (Roster)
export interface ShiftSchedule {
  id: string;
  userId: string;
  branchId: string;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:mm (24hr)
  endTime: string; // HH:mm (24hr)
  note?: string;
}

// --- Settings ---
export type Language = 'en' | 'th' | 'lo';

export interface LocalDatabaseConfig {
  enabled: boolean;
  type: 'postgresql' | 'sqlite' | 'mysql';
  host: string;
  port: string;
  databaseName: string;
  username: string;
  password: string;
}

export interface TaxSettings {
  enabled: boolean;             // Calculate Tax/VAT?
  rate: number;                 // e.g. 7.0 for 7%
  calculationMode: 'included' | 'excluded'; // 'included' (Price has VAT) or 'excluded' (Price + VAT)
  displayOnReceipt: boolean;    // Show tax line on UI/Receipt
}

export interface SystemSettings {
  // Company Info
  companyName: string;
  taxId: string;
  address: string;
  phone: string;

  // Localization
  language: Language;
  currencySymbol: string;

  // Interface
  defaultItemsPerPage: number;

  // Tax / VAT
  tax: TaxSettings;

  // Receipt & Print
  receiptHeader: string;
  receiptFooter: string;
  receiptLogoUrl?: string;
  receiptQrCodeUrl?: string; // Bank QR Code for receipt
  receiptPaperSize: '58mm' | '80mm' | 'A4';
  receiptAutoPrint: boolean;
  receiptShowTaxId: boolean;
  receiptShowCashier: boolean;
  receiptCopies: number;

  // Device Configuration
  currentBranchId?: string;
  currentPosId?: string;
  deviceRole?: 'Master' | 'Slave';

  // Local Database (For Slave offline mode)
  localDatabase?: LocalDatabaseConfig;

  // Synchronization (Master/Slave)
  masterApiUrl?: string; // e.g., http://192.168.1.100:3000
  autoSyncInterval?: number; // In minutes, 0 for manual
  lastSyncTime?: string;
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { 
  Product, Sale, CartItem, UnitDefinition, CategoryItem, Branch, PosMachine, 
  Warehouse, StorageLocation, StockTransfer, StockCount, StockReservation, 
  StockReceipt, StockAdjustment, DocumentStatus, User, SystemSettings, SyncLog, Customer, Shift, CustomerLevel, ShiftSchedule
} from '../types';
import { 
  INITIAL_SETTINGS, INITIAL_USERS, INITIAL_PRODUCTS, INITIAL_CATEGORIES_TREE, 
  INITIAL_UNITS, INITIAL_BRANCHES, INITIAL_POS_MACHINES, INITIAL_WAREHOUSES, 
  INITIAL_LOCATIONS, INITIAL_CUSTOMERS, INITIAL_CUSTOMER_LEVELS, INITIAL_SHIFT_SCHEDULES, INITIAL_SALES, INITIAL_SYNC_LOGS, INITIAL_TRANSFERS, INITIAL_COUNTS
} from '../services/data';
import { translations } from '../services/translations';

interface GlobalContextType {
  currentUser: User | null;
  setCurrentUser: (user: User | null) => void;
  users: User[];
  settings: SystemSettings;
  updateSettings: (s: SystemSettings) => void;
  products: Product[];
  sales: Sale[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  branches: Branch[];
  posMachines: PosMachine[];
  warehouses: Warehouse[];
  locations: StorageLocation[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  syncLogs: SyncLog[];
  customers: Customer[];
  customerLevels: CustomerLevel[];
  shifts: Shift[];
  shiftSchedules: ShiftSchedule[];

  // Translation Helper
  t: (key: string) => string;

  // Handlers
  processSale: (
    cartItems: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number
  ) => Promise<Sale>;

  settleSaleDebt: (saleId: string, amount: number, method: 'cash' | 'card' | 'transfer') => Promise<void>;
  handleVoidSale: (id: string) => Promise<void>;

  addProduct: (p: Product) => Promise<void>;
  updateProduct: (p: Product) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addUnit: (u: UnitDefinition) => Promise<void>;
  updateUnit: (u: UnitDefinition) => Promise<void>;
  deleteUnit: (id: string) => Promise<void>;

  addCategory: (c: CategoryItem) => Promise<void>;
  updateCategory: (c: CategoryItem) => Promise<void>;
  deleteCategory: (id: string) => Promise<void>;

  addBranch: (b: Branch) => Promise<void>;
  updateBranch: (b: Branch) => Promise<void>;
  deleteBranch: (id: string) => Promise<void>;

  addPos: (p: PosMachine) => Promise<void>;
  updatePos: (p: PosMachine) => Promise<void>;
  deletePos: (id: string) => Promise<void>;

  addWarehouse: (w: Warehouse) => Promise<void>;
  updateWarehouse: (w: Warehouse) => Promise<void>;
  deleteWarehouse: (id: string) => Promise<void>;

  addLocation: (l: StorageLocation) => Promise<void>;
  updateLocation: (l: StorageLocation) => Promise<void>;
  deleteLocation: (id: string) => Promise<void>;

  addUser: (u: User) => Promise<void>;
  updateUser: (u: User) => Promise<void>;
  deleteUser: (id: string) => Promise<void>;

  addCustomer: (c: Customer) => Promise<void>;
  updateCustomer: (c: Customer) => Promise<void>;
  deleteCustomer: (id: string) => Promise<void>;

  addCustomerLevel: (l: CustomerLevel) => Promise<void>;
  updateCustomerLevel: (l: CustomerLevel) => Promise<void>;
  deleteCustomerLevel: (id: string) => Promise<void>;

  updateTransfer: (t: StockTransfer) => Promise<void>;
  deleteTransfer: (id: string) => Promise<void>;
  updateCount: (c: StockCount) => Promise<void>;
  deleteCount: (id: string) => Promise<void>;
  updateReservation: (r: StockReservation) => Promise<void>;
  deleteReservation: (id: string) => Promise<void>;
  updateReceipt: (r: StockReceipt) => Promise<void>;
  deleteReceipt: (id: string) => Promise<void>;
  updateAdjustment: (a: StockAdjustment) => Promise<void>;
  deleteAdjustment: (id: string) => Promise<void>;
  handleStockStatusChange: (type: string, id: string, status: DocumentStatus) => Promise<void>;

  handleSyncOperation: (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => void;

  startShift: (branchId: string, startCash: number, notes?: string) => Promise<void>;
  endShift: (shiftId: string, endCash: number, notes?: string) => Promise<void>;
  addShiftSchedule: (schedule: ShiftSchedule) => Promise<void>;
  deleteShiftSchedule: (id: string) => Promise<void>;
}

const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // Initialize with Static Data for Client-Side Mode
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [settings, setSettings] = useState<SystemSettings>(INITIAL_SETTINGS);

  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [sales, setSales] = useState<Sale[]>(INITIAL_SALES);
  const [units, setUnits] = useState<UnitDefinition[]>(INITIAL_UNITS);
  const [categories, setCategories] = useState<CategoryItem[]>(INITIAL_CATEGORIES_TREE);
  const [branches, setBranches] = useState<Branch[]>(INITIAL_BRANCHES);
  const [posMachines, setPosMachines] = useState<PosMachine[]>(INITIAL_POS_MACHINES);
  const [warehouses, setWarehouses] = useState<Warehouse[]>(INITIAL_WAREHOUSES);
  const [locations, setLocations] = useState<StorageLocation[]>(INITIAL_LOCATIONS);
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [customerLevels, setCustomerLevels] = useState<CustomerLevel[]>(INITIAL_CUSTOMER_LEVELS);

  const [transfers, setTransfers] = useState<StockTransfer[]>(INITIAL_TRANSFERS);
  const [counts, setCounts] = useState<StockCount[]>(INITIAL_COUNTS);
  const [reservations, setReservations] = useState<StockReservation[]>([]);
  const [receipts, setReceipts] = useState<StockReceipt[]>([]);
  const [adjustments, setAdjustments] = useState<StockAdjustment[]>([]);
  const [syncLogs, setSyncLogs] = useState<SyncLog[]>(INITIAL_SYNC_LOGS);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [shiftSchedules, setShiftSchedules] = useState<ShiftSchedule[]>(INITIAL_SHIFT_SCHEDULES);

  // Load User from LocalStorage on mount
  useEffect(() => {
    const savedUser = localStorage.getItem('buildmaster_user');
    if (savedUser) {
      try {
        setCurrentUser(JSON.parse(savedUser));
      } catch (e) {
        localStorage.removeItem('buildmaster_user');
      }
    }
  }, []);

  // Update LocalStorage when user changes
  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('buildmaster_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('buildmaster_user');
    }
  }, [currentUser]);

  // Mock API Call simulation
  const mockApiCall = async <T,>(data: T): Promise<T> => {
    return new Promise((resolve) => {
      setTimeout(() => resolve(data), 300); // Simulate 300ms latency
    });
  };

  const t = (key: string): string => {
    const lang = settings.language || 'en';
    const keys = key.split('.');
    let value: any = translations[lang as keyof typeof translations];

    for (const k of keys) {
      if (value && typeof value === 'object' && k in value) {
        value = value[k];
      } else {
        return key; // Return key if translation missing
      }
    }
    return value as string;
  };

  const processSale = async (
    cartItems: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit' = 'cash',
    amountReceived?: number,
    change?: number
  ): Promise<Sale> => {

    const isCredit = paymentMethod === 'credit';
    const paymentStatus = isCredit ? 'unpaid' : 'paid';
    const remainingAmount = isCredit ? total : 0;

    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items: cartItems,
      total,
      subtotal,
      discountAmount,
      paymentMethod,
      paymentStatus,
      amountReceived: isCredit ? 0 : amountReceived,
      remainingAmount,
      change,
      date: new Date().toISOString(),
      status: 'completed',
      syncStatus: 'pending',
      customerId,
      customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined
    };

    // Optimistically update Sales
    setSales(prev => [newSale, ...prev]);

    // Optimistically update Product Stock
    setProducts(prevProducts => {
      const updatedProducts = [...prevProducts];

      cartItems.forEach(item => {
        const productIndex = updatedProducts.findIndex(p => p.id === item.id);
        if (productIndex > -1) {
          const product = { ...updatedProducts[productIndex] };

          // Calculate deduction logic
          let deduction = item.quantity;

          product.stock = Math.max(0, product.stock - deduction);

          // Update warehouse specific inventory if available (simplified to first warehouse)
          if (product.warehouseInventory && product.warehouseInventory.length > 0) {
             product.warehouseInventory[0].quantity = Math.max(0, product.warehouseInventory[0].quantity - deduction);
          }

          updatedProducts[productIndex] = product;
        }
      });
      return updatedProducts;
    });

    await mockApiCall(null);
    return newSale;
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: 'cash' | 'card' | 'transfer') => {
    setSales(prev => prev.map(s => {
      if (s.id === saleId) {
        const newRemaining = Math.max(0, (s.remainingAmount || s.total) - amount);
        const newStatus = newRemaining <= 0.01 ? 'paid' : 'partial';
        // In a real system, we would log a separate "PaymentTransaction" record here
        return {
          ...s,
          paymentStatus: newStatus,
          remainingAmount: newRemaining
        };
      }
      return s;
    }));
    await mockApiCall(null);
  };

  const handleVoidSale = async (id: string) => {
    // 1. Find the sale
    const saleToVoid = sales.find(s => s.id === id);
    if (!saleToVoid) return;
    if (saleToVoid.status === 'voided') return; // Prevent double voiding

    // 2. Update Sale Status
    setSales(prev => prev.map(s => {
      if (s.id === id) {
        return { ...s, status: 'voided', paymentStatus: 'paid' }; // Void implies no debt left
      }
      return s;
    }));

    // 3. RESTORE Stock (Logic added)
    setProducts(prevProducts => {
      const updatedProducts = [...prevProducts];

      saleToVoid.items.forEach(item => {
        const productIndex = updatedProducts.findIndex(p => p.id === item.id);
        if (productIndex > -1) {
          const product = { ...updatedProducts[productIndex] };

          // Add quantity back to stock
          const qtyToRestore = item.quantity;
          product.stock += qtyToRestore;

          // Add back to default warehouse inventory
          if (product.warehouseInventory && product.warehouseInventory.length > 0) {
             product.warehouseInventory[0].quantity += qtyToRestore;
          }

          updatedProducts[productIndex] = product;
        }
      });

      return updatedProducts;
    });

    await mockApiCall(null);
  };

  const addProduct = async (p: Product) => {
    const newProduct = { ...p, id: `P-${Date.now()}` };
    setProducts(prev => [...prev, newProduct]);
    await mockApiCall(null);
  };
  const updateProduct = async (p: Product) => {
    setProducts(prev => prev.map(item => item.id === p.id ? p : item));
    await mockApiCall(null);
  };
  const deleteProduct = async (id: string) => {
    setProducts(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addUnit = async (u: UnitDefinition) => {
    setUnits(prev => [...prev, { ...u, id: `u-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateUnit = async (u: UnitDefinition) => {
    setUnits(prev => prev.map(item => item.id === u.id ? u : item));
    await mockApiCall(null);
  };
  const deleteUnit = async (id: string) => {
    setUnits(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addCategory = async (c: CategoryItem) => {
    setCategories(prev => [...prev, { ...c, id: `c-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateCategory = async (c: CategoryItem) => {
    setCategories(prev => prev.map(item => item.id === c.id ? c : item));
    await mockApiCall(null);
  };
  const deleteCategory = async (id: string) => {
    setCategories(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const updateSettings = async (s: SystemSettings) => {
    setSettings(s);
    await mockApiCall(null);
  };

  const addBranch = async (b: Branch) => {
    setBranches(prev => [...prev, { ...b, id: `b-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateBranch = async (b: Branch) => {
    setBranches(prev => prev.map(item => item.id === b.id ? b : item));
    await mockApiCall(null);
  };
  const deleteBranch = async (id: string) => {
    setBranches(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addPos = async (p: PosMachine) => {
    setPosMachines(prev => [...prev, p]);
    await mockApiCall(null);
  };
  const updatePos = async (p: PosMachine) => {
    setPosMachines(prev => prev.map(item => item.id === p.id ? p : item));
    await mockApiCall(null);
  }; 
  const deletePos = async (id: string) => {
    setPosMachines(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addWarehouse = async (w: Warehouse) => {
    setWarehouses(prev => [...prev, { ...w, id: `wh-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateWarehouse = async (w: Warehouse) => {
    setWarehouses(prev => prev.map(item => item.id === w.id ? w : item));
    await mockApiCall(null);
  };
  const deleteWarehouse = async (id: string) => {
    setWarehouses(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addLocation = async (l: StorageLocation) => {
    setLocations(prev => [...prev, { ...l, id: `loc-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateLocation = async (l: StorageLocation) => {
    setLocations(prev => prev.map(item => item.id === l.id ? l : item));
    await mockApiCall(null);
  };
  const deleteLocation = async (id: string) => {
    setLocations(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addUser = async (u: User) => {
    setUsers(prev => [...prev, { ...u, id: `u-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateUser = async (u: User) => {
    setUsers(prev => prev.map(item => item.id === u.id ? u : item));
    await mockApiCall(null);
  };
  const deleteUser = async (id: string) => {
    setUsers(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addCustomer = async (c: Customer) => {
    setCustomers(prev => [...prev, { ...c, id: `cust-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateCustomer = async (c: Customer) => {
    setCustomers(prev => prev.map(item => item.id === c.id ? c : item));
    await mockApiCall(null);
  };
  const deleteCustomer = async (id: string) => {
    setCustomers(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addCustomerLevel = async (l: CustomerLevel) => {
    setCustomerLevels(prev => [...prev, { ...l, id: `lvl-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateCustomerLevel = async (l: CustomerLevel) => {
    setCustomerLevels(prev => prev.map(item => item.id === l.id ? l : item));
    await mockApiCall(null);
  };
  const deleteCustomerLevel = async (id: string) => {
    setCustomerLevels(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  // Stock Documents Mock Logic
  const upsertDoc = (list: any[], setList: any, item: any) => {
    setList((prev: any[]) => {
      const idx = prev.findIndex(i => i.id === item.id);
      if (idx > -1) {
        const newArr = [...prev];
        newArr[idx] = item;
        return newArr;
      }
      return [item, ...prev];
    });
  };

  const deleteDoc = (setList: any, id: string) => {
    setList((prev: any[]) => prev.filter(i => i.id !== id));
  };

  const updateTransfer = async (t: StockTransfer) => { upsertDoc(transfers, setTransfers, t); await mockApiCall(null); };
  const deleteTransfer = async (id: string) => { deleteDoc(setTransfers, id); await mockApiCall(null); };

  const updateCount = async (c: StockCount) => { upsertDoc(counts, setCounts, c); await mockApiCall(null); };
  const deleteCount = async (id: string) => { deleteDoc(setCounts, id); await mockApiCall(null); };

  const updateReservation = async (r: StockReservation) => { upsertDoc(reservations, setReservations, r); await mockApiCall(null); };
  const deleteReservation = async (id: string) => { deleteDoc(setReservations, id); await mockApiCall(null); };

  const updateReceipt = async (r: StockReceipt) => { upsertDoc(receipts, setReceipts, r); await mockApiCall(null); };
  const deleteReceipt = async (id: string) => { deleteDoc(setReceipts, id); await mockApiCall(null); };

  const updateAdjustment = async (a: StockAdjustment) => { upsertDoc(adjustments, setAdjustments, a); await mockApiCall(null); };
  const deleteAdjustment = async (id: string) => { deleteDoc(setAdjustments, id); await mockApiCall(null); };

  const handleStockStatusChange = async (type: string, id: string, status: DocumentStatus) => {
    // 1. Update Document Status
    switch (type) {
      case 'transfer':
        setTransfers(prev => prev.map(d => d.id === id ? { ...d, status } : d));
        // Logic to move stock if Approved/Completed
        if (status === 'Approved') {
           const doc = transfers.find(d => d.id === id);
           if (doc) {
             console.log("Mock Stock Movement: ", doc);
           }
        }
        break;
      case 'count':
        setCounts(prev => prev.map(d => d.id === id ? { ...d, status } : d));
        break;
      case 'reservation':
        setReservations(prev => prev.map(d => d.id === id ? { ...d, status } : d));
        break;
      case 'receipt':
        setReceipts(prev => prev.map(d => d.id === id ? { ...d, status } : d));
        break;
      case 'adjustment':
        setAdjustments(prev => prev.map(d => d.id === id ? { ...d, status } : d));
        break;
    }
    await mockApiCall(null);
  };

  const handleSyncOperation = async (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
    const log: SyncLog = {
      id: `log-${Date.now()}`,
      timestamp: new Date().toISOString(),
      type,
      status: 'Success',
      details: 'Mock Data Sync Completed (Simulated)',
      durationMs: 750
    };
    setSyncLogs(prev => [log, ...prev]);
    await mockApiCall(null);
  };

  const startShift = async (branchId: string, startCash: number, notes?: string) => {
    if (!currentUser) return;
    const newShift: Shift = {
      id: `sh-${Date.now()}`,
      userId: currentUser.id,
      branchId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open'
    };
    setShifts(prev => [newShift, ...prev]);
    await mockApiCall(null);
  };

  const endShift = async (shiftId: string, endCash: number, notes?: string) => {
    setShifts(prev => prev.map(s => {
      if (s.id === shiftId) {
        return {
          ...s,
          endTime: new Date().toISOString(),
          endCash,
          notes,
          status: 'Closed'
        };
      }
      return s;
    }));
    await mockApiCall(null);
  };

  const addShiftSchedule = async (schedule: ShiftSchedule) => {
    setShiftSchedules(prev => [...prev, schedule]);
    await mockApiCall(null);
  };

  const deleteShiftSchedule = async (id: string) => {
    setShiftSchedules(prev => prev.filter(s => s.id !== id));
    await mockApiCall(null);
  };

  return (
    <GlobalContext.Provider value={{
      currentUser, setCurrentUser,
      users, settings, updateSettings,
      products, sales, units, categories, branches, posMachines, warehouses, locations, customers, customerLevels,
      transfers, counts, reservations, receipts, adjustments, syncLogs, shifts, shiftSchedules,

      t, 

      processSale, handleVoidSale, settleSaleDebt,
      addProduct, updateProduct, deleteProduct,
      addUnit, updateUnit, deleteUnit,
      addCategory, updateCategory, deleteCategory,
      addBranch, updateBranch, deleteBranch,
      addPos, updatePos, deletePos,
      addWarehouse, updateWarehouse, deleteWarehouse,
      addLocation, updateLocation, deleteLocation,
      addUser, updateUser, deleteUser,
      addCustomer, updateCustomer, deleteCustomer,
      addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,

      updateTransfer, deleteTransfer,
      updateCount, deleteCount,
      updateReservation, deleteReservation,
      updateReceipt, deleteReceipt,
      updateAdjustment, deleteAdjustment,
      handleStockStatusChange,

      handleSyncOperation,
      startShift, endShift,
      addShiftSchedule, deleteShiftSchedule
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

import React, { useState, useMemo } from 'react';
import { Product, CartItem, Category, EstimateResultItem, SystemSettings, Customer, Sale } from '../types';
import { 
  Search, ShoppingCart, Plus, Minus, Trash2, CreditCard, Banknote, Sparkles, Box, 
  ArrowLeft, ScanBarcode, Layers, User, X, Percent, Star, QrCode, ArrowRight, Printer, CheckCircle, FileText
} from 'lucide-react';
import { AiAssistant } from './AiAssistant';
import { useGlobal } from '../context/GlobalContext';
import { useCartStore } from '../store/useCartStore';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t } = useGlobal();
  const { cart, addToCart, removeFromCart, updateQuantity, clearCart } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);

  // Checkout & Payment State
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  // Receipt State
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);

  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [customerSearch, setCustomerSearch] = useState('');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) ||
        v.barcode.includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  const filteredCustomers = useMemo(() => {
    return customers.filter(c => 
      c.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      c.phone.includes(customerSearch) ||
      c.code.toLowerCase().includes(customerSearch.toLowerCase())
    );
  }, [customers, customerSearch]);

  // Determine Customer Level
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const handleBarcodeScan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;

    const mainMatch = products.find(p => p.barcode === searchTerm || p.sku === searchTerm);
    if (mainMatch) {
      addToCart(mainMatch, 1, undefined);
      setSearchTerm(''); 
      return;
    }

    for (const p of products) {
      if (p.variants) {
        const variantMatch = p.variants.find(v => v.barcode === searchTerm || v.code === searchTerm);
        if (variantMatch) {
          addToCart(p, 1, variantMatch.id);
          setSearchTerm('');
          return;
        }
      }
    }
  };

  const handleAiItemsAdded = (items: EstimateResultItem[]) => {
    items.forEach(est => {
      if (est.matchedProductId) {
        const product = products.find(p => p.id === est.matchedProductId);
        if (product) {
          addToCart(product, Math.ceil(est.estimatedQuantity), undefined);
        }
      }
    });
  };

  // --- Calculations ---
  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);

  // 1. Apply Discount
  let discountAmount = 0;
  let discountedSubtotal = rawSubtotal;

  if (customerLevel && customerLevel.discountPercentage > 0) {
    discountAmount = rawSubtotal * (customerLevel.discountPercentage / 100);
    discountedSubtotal = rawSubtotal - discountAmount;
  }

  // 2. Apply Tax
  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       // Tax added on top of discounted price
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       // Tax included in price, back-calculate from discounted price
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       // Subtotal for display is usually net of tax in this case
       // But keeping simple logic: finalTotal IS the discounted price
       finalTotal = discountedSubtotal;
    }
  }

  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - finalTotal);
  const remaining = Math.max(0, finalTotal - receivedAmount);

  const handleCheckoutClick = () => {
    setReceivedAmountStr('');
    setPaymentMethod('cash');
    setIsCheckoutOpen(true);
  };

  const handleProcessPayment = async () => {
    if (paymentMethod === 'cash' && receivedAmount < finalTotal) {
      alert("Insufficient amount received!");
      return;
    }

    if (paymentMethod === 'credit' && !selectedCustomer) {
      alert("Credit payment requires a registered customer!");
      return;
    }

    setIsProcessing(true);

    // For non-cash methods, assume full payment
    const finalReceived = paymentMethod === 'cash' ? receivedAmount : (paymentMethod === 'credit' ? 0 : finalTotal);
    const finalChange = paymentMethod === 'cash' ? change : 0;

    try {
      const sale = await onProcessSale(
        cart, 
        finalTotal, 
        selectedCustomer?.id, 
        discountAmount, 
        rawSubtotal,
        paymentMethod,
        finalReceived,
        finalChange
      );

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleNumPadClick = (val: string) => {
    if (val === 'C') {
      setReceivedAmountStr('');
    } else if (val === 'BS') {
      setReceivedAmountStr(prev => prev.slice(0, -1));
    } else if (val === '.') {
      if (!receivedAmountStr.includes('.')) setReceivedAmountStr(prev => prev + '.');
    } else {
      setReceivedAmountStr(prev => prev + val);
    }
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <div className="flex flex-col lg:flex-row h-full gap-6 relative">
      <div className="flex-1 flex flex-col min-w-0 h-full">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-slate-800">{t('pos.newOrder')}</h2>
          <div className="flex space-x-2">
             <button 
              onClick={() => setIsCustomerModalOpen(true)}
              className={`flex items-center px-4 py-2 rounded-lg shadow-sm transition-all duration-200 font-medium text-sm border ${
                selectedCustomer 
                  ? 'bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100' 
                  : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
              }`}
            >
              <User className="w-4 h-4 mr-2" />
              {selectedCustomer ? (
                <span className="flex items-center">
                  {selectedCustomer.name}
                  {customerLevel && (
                    <span className="ml-2 flex items-center bg-white/50 px-1.5 py-0.5 rounded text-[10px] border border-blue-200">
                      <Star className="w-3 h-3 mr-1 fill-current text-yellow-500" />
                      {customerLevel.name}
                    </span>
                  )}
                </span>
              ) : t('pos.selectCustomer')}
            </button>
            <button 
              onClick={() => setIsAiModalOpen(true)}
              className="flex items-center px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-lg shadow-md hover:shadow-lg transition-all duration-200 font-medium text-sm"
            >
              <Sparkles className="w-4 h-4 mr-2" />
              <span className="hidden md:inline">{t('pos.aiEstimate')}</span>
              <span className="md:hidden">AI</span>
            </button>
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 space-y-4">
          <form onSubmit={handleBarcodeScan} className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input
              type="text"
              placeholder={t('pos.scanPlaceholder')}
              className="w-full pl-10 pr-12 py-3 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 bg-slate-50 font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              autoFocus
            />
            <button type="submit" className="absolute right-2 top-1/2 transform -translate-y-1/2 p-1.5 bg-slate-200 rounded text-slate-600 hover:bg-slate-300">
               <ScanBarcode className="w-4 h-4" />
            </button>
          </form>

          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide -mx-1 px-1">
            <button
              onClick={() => setSelectedCategory('all')}
              className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors flex-shrink-0 ${
                selectedCategory === 'all' 
                  ? 'bg-slate-800 text-white' 
                  : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
              }`}
            >
              {t('pos.allItems')}
            </button>
            {Object.values(Category).map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors flex-shrink-0 ${
                  selectedCategory === cat 
                    ? 'bg-construction-orange text-white' 
                    : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto pr-1">
          {filteredProducts.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-slate-400">
              <Box className="w-12 h-12 mb-4 opacity-50" />
              <p>No products found.</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-20 md:pb-0">
              {filteredProducts.map((product) => {
                const hasVariants = product.variants && product.variants.length > 0;

                return (
                  <div 
                    key={product.id} 
                    onClick={() => !hasVariants && addToCart(product)}
                    className={`bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow flex flex-col ${!hasVariants ? 'cursor-pointer' : ''}`}
                  >
                    <div className="h-32 bg-slate-100 relative overflow-hidden">
                      {product.imageUrl ? (
                        <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                          <Box className="w-12 h-12" />
                        </div>
                      )}
                      <div className="absolute top-2 right-2 bg-white/90 backdrop-blur-sm px-2 py-1 rounded text-xs font-bold text-slate-700 shadow-sm">
                        {product.stock} {product.unit}
                      </div>
                      {product.sku && (
                         <div className="absolute bottom-2 left-2 bg-black/50 backdrop-blur-sm px-2 py-0.5 rounded text-[10px] text-white font-mono">
                           {product.sku}
                         </div>
                      )}
                    </div>
                    <div className="p-4 flex-1 flex flex-col">
                      <h3 className="font-bold text-slate-800 line-clamp-2 text-sm mb-1">{product.name}</h3>
                      <p className="text-xs text-slate-500 mb-3 line-clamp-1">{product.category}</p>

                      <div className="mt-auto">
                        <div className="flex justify-between items-center mb-3">
                          <span className="text-lg font-bold text-primary-600">${product.price.toFixed(2)}</span>
                        </div>

                        {hasVariants ? (
                          <div className="space-y-1">
                             <button
                                onClick={(e) => { e.stopPropagation(); addToCart(product); }}
                                className="w-full py-1.5 bg-slate-100 text-slate-700 rounded text-xs font-medium hover:bg-slate-200 transition-colors flex justify-between px-3"
                              >
                                <span>{product.unit}</span>
                                <span>${product.price}</span>
                              </button>
                             {product.variants!.map(v => (
                               <button
                                key={v.id}
                                onClick={(e) => { e.stopPropagation(); addToCart(product, 1, v.id); }}
                                className="w-full py-1.5 bg-orange-50 text-orange-700 rounded text-xs font-medium hover:bg-orange-100 transition-colors flex justify-between px-3"
                              >
                                <span>{v.name}</span>
                                <span>${v.price}</span>
                              </button>
                             ))}
                          </div>
                        ) : (
                          <button className="w-full py-2 bg-slate-800 text-white rounded-lg text-sm font-medium hover:bg-slate-900 transition-colors flex items-center justify-center">
                            <Plus className="w-4 h-4 mr-1" /> {t('common.add')}
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {cartItemCount > 0 && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="lg:hidden fixed bottom-4 right-4 left-4 bg-slate-900 text-white p-4 rounded-xl shadow-2xl flex justify-between items-center z-30"
        >
          <div className="flex items-center">
            <div className="bg-orange-500 rounded-full w-8 h-8 flex items-center justify-center font-bold text-sm mr-3">
              {cartItemCount}
            </div>
            <span className="font-bold">{t('pos.viewCart')}</span>
          </div>
          <span className="font-bold text-lg">${finalTotal.toFixed(2)}</span>
        </button>
      )}

      <div className={`
        fixed inset-y-0 right-0 z-40 w-full md:w-[400px] bg-white shadow-2xl transform transition-transform duration-300 ease-in-out lg:relative lg:translate-x-0 lg:shadow-none lg:w-[380px] lg:border-l lg:border-slate-200 flex flex-col
        ${isCartOpen ? 'translate-x-0' : 'translate-x-full'}
      `}>
        <div className="p-5 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
          <div className="flex items-center">
            <ShoppingCart className="w-5 h-5 text-slate-700 mr-2" />
            <h3 className="font-bold text-slate-800 text-lg">{t('pos.currentOrder')}</h3>
          </div>
          <button 
            onClick={() => setIsCartOpen(false)}
            className="lg:hidden p-2 text-slate-500 hover:bg-slate-200 rounded-full"
          >
            <X className="w-6 h-6" />
          </button>
          <div className="hidden lg:block bg-slate-200 text-slate-600 px-2 py-1 rounded text-xs font-bold">
            {cartItemCount} {t('common.items')}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-4">
              <ShoppingCart className="w-16 h-16 opacity-20" />
              <p className="text-sm font-medium">{t('pos.emptyCart')}</p>
              <p className="text-xs text-center max-w-[200px]">{t('pos.emptyCartDesc')}</p>
            </div>
          ) : (
            cart.map((item, index) => (
              <div key={`${item.id}-${item.selectedVariantId || 'main'}`} className="flex items-center bg-white p-3 rounded-lg border border-slate-100 shadow-sm animate-fade-in">
                <div className="flex-1 min-w-0">
