              ) : paymentMethod === 'credit' ? (
                 <div className="flex-1 flex flex-col">
                    <div className="bg-orange-50 p-4 rounded-xl mb-4 border border-orange-100 flex justify-between items-center">
                       <div>
                          <p className="text-xs text-orange-700 font-bold uppercase mb-1">Customer</p>
                          <p className="font-bold text-slate-800">{selectedCustomer?.name}</p>
                       </div>
                       <User className="w-5 h-5 text-orange-400" />
                    </div>

                    <div className="bg-white p-4 rounded-xl mb-4 text-right border border-slate-200">
                       <p className="text-sm text-slate-500 mb-1">Initial Deposit / Pay Now</p>
                       <div className="text-4xl font-bold text-slate-800 tracking-tight">
                          ${receivedAmountStr || '0'}
                       </div>
                    </div>

                    <div className="flex justify-between items-center mb-6 px-2">
                       <div>
                          <p className="text-sm text-slate-500">Total Bill</p>
                          <p className="text-lg font-bold text-slate-800">${finalTotal.toFixed(2)}</p>
                       </div>
                       <div className="text-right">
                          <p className="text-sm text-slate-500">Remaining Debt</p>
                          <p className="text-xl font-bold text-red-600">${remainingDebt.toFixed(2)}</p>
                       </div>
                    </div>

                    {/* Numpad for Deposit */}
                    <div className="flex gap-4 flex-1">
                       <div className="flex-1 grid grid-cols-3 gap-3">
                          {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'BS'].map((num) => (
                             <button
                                key={num}
                                onClick={() => handleNumPadClick(num.toString())}
                                className="bg-white border border-slate-200 rounded-lg text-xl font-semibold text-slate-700 hover:bg-slate-50 active:bg-slate-100 transition-colors shadow-sm flex items-center justify-center"
                             >
                                {num === 'BS' ? <ArrowLeft className="w-6 h-6" /> : num}
                             </button>
                          ))}
                       </div>
                       <div className="w-1/3 flex flex-col gap-3">
                          <button onClick={() => setReceivedAmountStr('0')} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">No Deposit</button>
                          <button onClick={() => handleQuickCash(Math.ceil(finalTotal * 0.1))} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">10%</button>
                          <button onClick={() => handleQuickCash(Math.ceil(finalTotal * 0.5))} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">50%</button>
                       </div>
                    </div>
                 </div>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                  <div className="w-24 h-24 bg-blue-50 rounded-full flex items-center justify-center text-blue-500 mb-2">
                    <CreditCard className="w-12 h-12" />
                  </div>
                  <h4 className="text-xl font-bold text-slate-800">Ready for Card Payment</h4>
                  <p className="text-slate-500 max-w-xs">Please insert or swipe card on the terminal. Ensure the amount <strong className="text-slate-800">${finalTotal.toFixed(2)}</strong> is correct.</p>
                </div>
              )}

              <button
                onClick={handleProcessPayment}
                disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < finalTotal) || (paymentMethod === 'credit' && receivedAmount > finalTotal)}
                className={`w-full py-4 mt-6 text-white rounded-xl font-bold text-xl disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg flex items-center justify-center ${
                   paymentMethod === 'credit' ? 'bg-orange-600 hover:bg-orange-700' : 'bg-slate-900 hover:bg-slate-800'
                }`}
              >
                {isProcessing ? (
                  <span className="flex items-center"><Sparkles className="w-5 h-5 animate-spin mr-2" /> Processing...</span>
                ) : (
                  <>
                    <CheckCircle className="w-6 h-6 mr-2" /> 
                    {paymentMethod === 'cash' && change > 0 
                      ? `Confirm & Return $${change.toFixed(2)}` 
                      : paymentMethod === 'credit' 
                        ? `Confirm Debt $${remainingDebt.toFixed(2)}`
                        : `Confirm Payment $${finalTotal.toFixed(2)}`}
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Receipt Modal */}
      {isReceiptOpen && lastSale && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm flex flex-col overflow-hidden">
            <div className="p-4 bg-slate-800 text-white flex justify-between items-center">
              <h3 className="font-bold flex items-center"><CheckCircle className="w-5 h-5 mr-2 text-green-400" /> Sale Completed</h3>
              <button onClick={() => setIsReceiptOpen(false)} className="text-slate-400 hover:text-white"><X className="w-5 h-5" /></button>
            </div>

            {/* Receipt Preview */}
            <div className="p-6 bg-slate-50 flex-1 overflow-y-auto max-h-[60vh]">
              <div className="bg-white p-4 shadow-sm border border-slate-200 text-xs font-mono text-slate-700">
                <div className="text-center mb-4">
                  <h2 className="text-lg font-bold text-slate-900 mb-1">{settings?.companyName || 'BuildMaster Store'}</h2>
                  <p>{settings?.address || '123 Main St'}</p>
                  <p>Tel: {settings?.phone || '012-345-6789'}</p>
                  <p className="mt-2 text-slate-500">#{lastSale.id}</p>
                  <p>{new Date(lastSale.date).toLocaleString()}</p>
                </div>

                <div className="border-b border-dashed border-slate-300 my-2"></div>

                <div className="space-y-1 mb-2">
                  {lastSale.items.map((item, i) => (
                    <div key={i} className="flex justify-between">
                      <span className="truncate w-32">{item.name}</span>
                      <span className="text-right">
                        {item.quantity} x {item.sellPrice.toFixed(2)}
                      </span>
                      <span className="font-bold text-right w-16">
                        {(item.quantity * item.sellPrice).toFixed(2)}
                      </span>
                    </div>
                  ))}
                </div>

                <div className="border-b border-dashed border-slate-300 my-2"></div>

                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span>Subtotal</span>
                    <span>${(lastSale.subtotal || lastSale.total).toFixed(2)}</span>
                  </div>
                  {lastSale.discountAmount ? (
                    <div className="flex justify-between text-green-600">
                      <span>Discount</span>
                      <span>-${lastSale.discountAmount.toFixed(2)}</span>
                    </div>
                  ) : null}
                  <div className="flex justify-between font-bold text-sm mt-1 pt-1 border-t border-slate-100">
                    <span>Total</span>
                    <span>${lastSale.total.toFixed(2)}</span>
                  </div>
                </div>

                <div className="border-b border-dashed border-slate-300 my-3"></div>

                <div className="space-y-1 text-slate-600">
                  <div className="flex justify-between">
                    <span className="capitalize">Paid via {lastSale.paymentMethod}</span>
                    <span>${(lastSale.amountReceived && lastSale.amountReceived > 0 ? lastSale.amountReceived : 0).toFixed(2)}</span>
                  </div>

                  {(lastSale.paymentStatus === 'unpaid' || lastSale.paymentStatus === 'partial') && (
                     <>
                        <div className="flex justify-between font-bold text-red-600 mt-1">
                           <span>Balance Due</span>
                           <span>${(lastSale.remainingAmount || 0).toFixed(2)}</span>
                        </div>
                     </>
                  )}

                  {lastSale.change !== undefined && lastSale.change > 0 && (
                    <div className="flex justify-between font-bold text-slate-900">
                      <span>Change</span>
                      <span>${lastSale.change.toFixed(2)}</span>
                    </div>
                  )}
                </div>

                <div className="mt-6 text-center text-slate-400 italic">
                  Thank you for shopping!
                </div>
              </div>
            </div>

            <div className="p-4 bg-white border-t border-slate-100 flex gap-3">
              <button 
                onClick={() => window.print()}
                className="flex-1 py-3 bg-white border border-slate-300 text-slate-700 rounded-lg font-bold hover:bg-slate-50 flex items-center justify-center transition-colors"
              >
                <Printer className="w-5 h-5 mr-2" /> Print
              </button>
              <button 
                onClick={() => setIsReceiptOpen(false)}
                className="flex-1 py-3 bg-slate-900 text-white rounded-lg font-bold hover:bg-slate-800 flex items-center justify-center transition-colors"
              >
                <Plus className="w-5 h-5 mr-2" /> New Order
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

'use client';

import React, { useEffect, useState } from 'react';
import { ShoppingCart, Star, CheckCircle, QrCode, Store, Lock, Image as ImageIcon } from 'lucide-react';
import { CartItem, Customer, CustomerDisplaySettings } from '../../types';

// Define the data structure received from the POS
interface DisplayData {
  type: 'UPDATE' | 'CHECKOUT' | 'SUCCESS' | 'RESET';
  cart: CartItem[];
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
  customer?: Customer | null;
  paymentMethod?: string;
  amountReceived?: number;
  change?: number;
  companyName?: string;
  settings?: CustomerDisplaySettings;
}

export default function CustomerDisplayPage() {
  const [data, setData] = useState<DisplayData>({
    type: 'RESET',
    cart: [],
    subtotal: 0,
    discount: 0,
    tax: 0,
    total: 0,
    companyName: 'BuildMaster'
  });

  const [currentPromoIndex, setCurrentPromoIndex] = useState(0);

  useEffect(() => {
    // Connect to the broadcast channel
    const channel = new BroadcastChannel('customer_display_channel');

    channel.onmessage = (event) => {
      if (event.data) {
        setData(prev => ({
          ...prev,
          ...event.data,
          // Preserve settings if not provided in update (though POS usually sends it)
          settings: event.data.settings || prev.settings 
        }));
      }
    };

    return () => {
      channel.close();
    };
  }, []);

  // Carousel Logic
  useEffect(() => {
    if (data.settings?.promotionImages && data.settings.promotionImages.length > 1) {
      const interval = setInterval(() => {
        setCurrentPromoIndex(prev => (prev + 1) % data.settings!.promotionImages.length);
      }, (data.settings.promotionInterval || 5) * 1000);
      return () => clearInterval(interval);
    }
  }, [data.settings?.promotionImages, data.settings?.promotionInterval]);

  // Disabled State
  if (data.settings && data.settings.enabled === false) {
    return (
      <div className="h-screen bg-slate-900 flex flex-col items-center justify-center text-slate-500 p-8 text-center">
        <Lock className="w-16 h-16 mb-4 opacity-50" />
        <h1 className="text-2xl font-bold">Display Closed</h1>
      </div>
    );
  }

  // Idle State (Welcome Screen / Promotions)
  if (data.cart.length === 0 && data.type === 'RESET') {
    const hasPromos = data.settings?.promotionImages && data.settings.promotionImages.length > 0;

    return (
      <div className="h-screen bg-slate-900 relative overflow-hidden">
        {hasPromos ? (
          <div className="absolute inset-0 z-0">
             {data.settings!.promotionImages.map((img, idx) => (
                <div 
                  key={idx}
                  className={`absolute inset-0 bg-cover bg-center transition-opacity duration-1000 ease-in-out ${idx === currentPromoIndex ? 'opacity-50' : 'opacity-0'}`}
                  style={{ backgroundImage: `url(${img})` }}
                />
             ))}
             <div className="absolute inset-0 bg-black/40" /> {/* Overlay */}
          </div>
        ) : (
          <div className="absolute inset-0 flex items-center justify-center opacity-10">
             <Store className="w-96 h-96 text-white" />
          </div>
        )}

        <div className="relative z-10 h-full flex flex-col items-center justify-center text-white p-12 text-center">
          <div className="w-32 h-32 bg-orange-500 rounded-full flex items-center justify-center mb-8 shadow-2xl animate-bounce-slow">
            <Store className="w-16 h-16 text-white" />
          </div>
          <h1 className="text-6xl font-bold mb-6 drop-shadow-lg tracking-tight">
            {data.companyName}
          </h1>
          <p className="text-2xl text-slate-200 max-w-2xl leading-relaxed drop-shadow-md">
            {data.settings?.welcomeMessage || "Welcome! We are ready to serve you."}
          </p>
        </div>
      </div>
    );
  }

  // Success State
  if (data.type === 'SUCCESS') {
    return (
      <div className="h-screen bg-green-600 flex flex-col items-center justify-center text-white p-8 text-center">
        <div className="w-32 h-32 bg-white rounded-full flex items-center justify-center mb-8 shadow-2xl">
          <CheckCircle className="w-20 h-20 text-green-600" />
        </div>
        <h1 className="text-6xl font-bold mb-4">Thank You!</h1>
        <p className="text-2xl text-green-100 mb-8">Payment Successful</p>

        <div className="bg-white/20 backdrop-blur-md rounded-2xl p-8 min-w-[400px]">
           <div className="flex justify-between text-xl mb-2">
             <span>Total Paid</span>
             <span className="font-bold">${data.total.toFixed(2)}</span>
           </div>
           {data.change !== undefined && data.change > 0 && (
             <div className="flex justify-between text-3xl font-bold mt-4 pt-4 border-t border-white/30">
               <span>Change Due</span>
               <span>${data.change.toFixed(2)}</span>
             </div>
           )}
        </div>
      </div>
    );
  }

  // Active Transaction State
  return (
    <div className="h-screen bg-slate-50 flex flex-col md:flex-row overflow-hidden">
      {/* Left: Cart Items */}
      <div className="flex-1 flex flex-col h-full border-r border-slate-200 bg-white">
        <div className="p-6 bg-slate-800 text-white flex justify-between items-center shadow-md">
          <h2 className="text-2xl font-bold flex items-center">
            <ShoppingCart className="w-6 h-6 mr-3" />
            Your Order
          </h2>
          <span className="bg-orange-500 px-3 py-1 rounded-full text-sm font-bold">
            {data.cart.reduce((acc, item) => acc + item.quantity, 0)} Items
          </span>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {data.cart.map((item, index) => (
            <div key={`${item.id}-${index}`} className="flex justify-between items-center p-4 bg-slate-50 rounded-xl border border-slate-100 shadow-sm animate-fade-in">
              <div className="flex-1">
                <h3 className="text-xl font-bold text-slate-800">{item.name}</h3>
                <p className="text-slate-500">
                  {item.quantity} {item.sellUnit} x ${item.sellPrice.toFixed(2)}
                </p>
              </div>
              <div className="text-xl font-bold text-slate-900">
                ${(item.quantity * item.sellPrice).toFixed(2)}
              </div>
            </div>
          ))}
        </div>

        {/* Customer Info footer if exists */}
        {data.customer && (
          <div className="p-4 bg-blue-50 border-t border-blue-100 flex items-center justify-between text-blue-900">
             <div className="flex items-center">
                <Star className="w-5 h-5 mr-2 text-yellow-500 fill-current" />
                <span className="font-bold text-lg">{data.customer.name}</span>
             </div>
             {data.customer.level && (
               <span className="bg-blue-200 px-2 py-1 rounded text-xs font-bold text-blue-800">
                 {data.customer.level.name} Member
               </span>
             )}
          </div>
        )}
      </div>

      {/* Right: Totals & Checkout Status */}
      <div className="w-full md:w-[450px] bg-slate-100 flex flex-col p-6 shadow-xl z-10">
        <div className="flex-1 flex flex-col justify-center space-y-6">
           {data.type === 'CHECKOUT' ? (
             <div className="bg-white p-8 rounded-3xl shadow-lg border-2 border-orange-100 text-center animate-fade-in">
                {data.paymentMethod === 'qr' ? (
                   <>
                     <h3 className="text-2xl font-bold text-slate-800 mb-4">Scan to Pay</h3>
                     <div className="bg-slate-900 p-4 rounded-xl inline-block mb-4">
                        <img 
                          src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=Payment_OnePay_${data.total}`} 
                          alt="QR Code" 
                          className="w-48 h-48 object-contain rounded-lg bg-white"
                        />
                     </div>
                     <p className="text-slate-500">OnePay / Banking App</p>
                   </>
                ) : (
                   <>
                     <h3 className="text-2xl font-bold text-slate-800 mb-2">Payment Processing</h3>
                     <p className="text-slate-500 mb-6">Please follow the instructions on the terminal</p>
                     <div className="text-5xl font-bold text-slate-900 mb-2">${data.total.toFixed(2)}</div>
                     <div className="text-lg font-medium text-orange-600 uppercase tracking-wide">
                        Paying via {data.paymentMethod || 'Cash'}
                     </div>
                   </>
                )}
             </div>
           ) : (
             <div className="text-center space-y-4">
                <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center mx-auto shadow-sm">
                   <Store className="w-12 h-12 text-slate-300" />
                </div>
                <h3 className="text-xl font-medium text-slate-400">Total Amount Due</h3>
             </div>
           )}
        </div>

        <div className="bg-white rounded-3xl p-8 shadow-lg border border-slate-200">
          <div className="space-y-3 mb-6 text-lg">
            <div className="flex justify-between text-slate-600">
              <span>Subtotal</span>
              <span>${data.subtotal.toFixed(2)}</span>
            </div>
            {data.discount > 0 && (
              <div className="flex justify-between text-green-600 font-medium">
                <span>Discount</span>
                <span>-${data.discount.toFixed(2)}</span>
              </div>
            )}
            {data.tax > 0 && (
              <div className="flex justify-between text-slate-500">
                <span>Tax</span>
                <span>${data.tax.toFixed(2)}</span>
              </div>
            )}
          </div>
          <div className="pt-6 border-t-2 border-dashed border-slate-200">
            <div className="flex justify-between items-end">
              <span className="text-xl font-bold text-slate-700">Total</span>
              <span className="text-6xl font-bold text-slate-900 tracking-tight">${data.total.toFixed(2)}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export enum Category {
  CEMENT = 'Cement & Concrete',
  STEEL = 'Steel & Metal',
  WOOD = 'Wood & Lumber',
  PAINT = 'Paints & Finishes',
  TOOLS = 'Tools & Hardware',
  PLUMBING = 'Plumbing',
  ELECTRICAL = 'Electrical',
  CONSUMABLES = 'General Consumables'
}

export type UnitCategory = 'Weight' | 'Length' | 'Quantity';

export interface UnitDefinition {
  id: string;
  name: string;      // e.g. Kilogram
  symbol: string;    // e.g. kg
  category: UnitCategory;
  baseFactor: number; // 1 for base unit (e.g. g), 1000 for kg
  isBase: boolean;   // True if this is the reference unit
}

export interface CategoryItem {
  id: string;
  name: string;
  parentId: string | null; // null for root categories
  description?: string;
}

export interface ProductVariant {
  id: string;
  name: string;      // e.g., 'Piece', 'Small', 'Red'
  code: string;      // SKU/Code for the variant
  barcode: string;   // Barcode for the variant
  conversionFactor: number; // How many variants in the main unit (e.g. 12 pieces in 1 box)
  price: number;     // Price per variant
}

export interface ProductInventory {
  warehouseId: string;
  quantity: number;
}

export interface BranchPrice {
  branchId: string;
  price: number;
}

export interface ProductPhysical {
  weight?: number; // kg
  width?: number;  // cm
  height?: number; // cm
  depth?: number;  // cm (length)
}

export interface Product {
  id: string;
  name: string;
  category: Category | string; 
  price: number;     // Base Price (Global)
  branchPrices?: BranchPrice[]; // Overrides per branch
  stock: number;     // Stock count in MAIN units (Aggregate Total)
  minStock?: number; // Minimum stock threshold for alerts
  warehouseInventory?: ProductInventory[]; // Breakdown by warehouse
  unit: string;      // Name of the MAIN unit (e.g., 'bag', 'box')
  physical?: ProductPhysical; // New: Physical attributes
  imageUrl?: string;
  sku: string;       // SKU of MAIN unit
  barcode: string;   // Barcode of MAIN unit
  variants?: ProductVariant[]; // List of sub-products/variants
}

export interface CartItem extends Product {
  quantity: number;
  // Handling multi-unit/variant logic
  selectedVariantId?: string; // null if main unit, string if variant
  sellPrice: number; 
  sellUnit: string;  
  sellConversionFactor: number; // 1 for main, X for variant
}

export interface Sale {
  id: string;
  items: CartItem[];
  subtotal?: number; // Raw total before discount/tax
  discountAmount?: number; // Deduction amount
  total: number; // Final payable amount
  date: string;
  paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit';
  paymentStatus: 'paid' | 'unpaid' | 'partial'; // Track debt status
  amountReceived?: number; // Amount given by customer
  change?: number; // Change returned
  remainingAmount?: number; // Amount left to pay (for credit/partial)
  status: 'completed' | 'voided'; // Order status
  syncStatus?: 'synced' | 'pending' | 'failed'; // Track sync state
  customerId?: string; // Link to customer
  customerName?: string; // Snapshot of name
}

export interface EstimateRequest {
  query: string;
}

export interface EstimateResultItem {
  productName: string;
  estimatedQuantity: number;
  unit: string;
  reasoning: string;
  matchedProductId?: string; // If found in inventory
}

// --- AI Inventory Analysis Types ---
export interface ReorderSuggestion {
  productId: string;
  productName: string;
  currentStock: number;
  suggestedReorderQty: number;
  priority: 'High' | 'Medium' | 'Low';
  reasoning: string;
}

export interface NewProductSuggestion {
  name: string;
  categoryName: string;
  estimatedPrice: number;
  reasoning: string;
  suggestedUnit: string;
}

export interface BundleSuggestion {
  bundleName: string;
  components: string[];
  estimatedPrice: number;
  reasoning: string;
  targetAudience: string;
}

export interface InventoryAnalysisResult {
  reorders: ReorderSuggestion[];
  newProducts: NewProductSuggestion[];
  bundles: BundleSuggestion[];
}

export interface Branch {
  id: string;
  name: string;
  address: string;
  phone: string;
  manager: string;
  isActive: boolean;
}

export interface PosMachine {
  id: string;
  branchId: string;
  machineNumber: string; // e.g., POS-01
  status: 'active' | 'maintenance' | 'inactive';
  lastActive?: string;
}

export interface Warehouse {
  id: string;
  branchId: string;
  name: string;
  code: string; // e.g., WH-01
  type: 'General' | 'Cold Storage' | 'Hazardous' | 'Showroom';
  description?: string;
}

export interface StorageLocation {
  id: string;
  warehouseId: string;
  zone: string;   // e.g., Zone A
  rack: string;   // e.g., Rack 01
  shelf: string;  // e.g., Shelf 03 (Level)
  bin: string;    // e.g., Bin B (Slot)
  fullCode: string; // Helper: A-01-03-B
  type?: 'Pallet' | 'Shelf' | 'Floor';
}

// --- Customer Types ---
export interface CustomerLevel {
  id: string;
  name: string;
  discountPercentage: number;
  color?: string;
}

export interface Customer {
  id: string;
  code: string; // Membership ID or Code
  name: string;
  phone: string;
  taxId?: string;
  address?: string;
  email?: string;
  loyaltyPoints: number;
  notes?: string;
  levelId?: string;
  level?: CustomerLevel;
}

// --- Stock Management Types ---

export type DocumentStatus = 'Draft' | 'Approved' | 'Completed' | 'Cancelled';

export interface StockItem {
  productId: string;
  variantId?: string; // Optional: if specific variant
  productName: string;
  unit: string;
  quantity: number;
  note?: string;
}

// 1. Transfer Request (ใบขอโอนย้ายสินค้า)
export interface StockTransfer {
  id: string;
  date: string;
  sourceWarehouseId: string;
  targetWarehouseId: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 2. Stock Count (ใบตรวจนับสินค้า)
export interface StockCountItem extends StockItem {
  systemQuantity: number; // Snapshot of system stock
  countedQuantity: number; // Actual count
  diff: number; // Calculated diff
}

export interface StockCount {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockCountItem[];
  referenceNo: string;
  counterName: string; // Who counted
  reason: string; // Mandatory reason for adjustment
}

// 3. Stock Reservation (ใบจองสินค้า)
export interface StockReservation {
  id: string;
  date: string;
  expiryDate: string;
  warehouseId: string;
  customerName: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 4. Goods Receipt (ใบเพิ่มสินค้า / รับเข้าจากผู้ขาย)
export interface StockReceiptItem extends StockItem {
  costPrice: number; // Cost per unit
}

export interface StockReceipt {
  id: string;
  date: string;
  warehouseId: string;
  vendorName: string;
  vendorInvoiceNo?: string;
  status: DocumentStatus;
  items: StockReceiptItem[];
  referenceNo: string;
  totalCost: number;
}

// 5. Stock Adjustment (ใบปรับปรุงยอดสินค้า)
export interface StockAdjustment {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockItem[]; // Quantity can be negative (decrease) or positive (increase)
  referenceNo: string;
  reason: string; // Mandatory
}

// --- Sync Types ---
export interface SyncLog {
  id: string;
  timestamp: string;
  type: 'Auto' | 'Manual' | 'Push' | 'Pull';
  status: 'Success' | 'Failed' | 'Partial';
  details: string; // e.g., "5 Sales uploaded, 0 Products updated"
  durationMs: number;
}

// --- User & Roles ---

export type UserRole = 'Admin' | 'Manager' | 'Staff' | 'Cashier';

export interface User {
  id: string;
  username: string;
  password?: string; // Added for login
  email?: string;    // Optional
  name: string;
  role: UserRole;
  avatarUrl?: string;
  department?: string;
  branchId?: string;
}

// --- Shift Management ---
// Actual working record (Time Clock)
export interface Shift {
  id: string;
  userId: string;
  branchId: string;
  startTime: string;
  endTime?: string;
  startCash: number;
  endCash?: number;
  notes?: string;
  status: 'Open' | 'Closed';
  userName?: string; // Optional helper
  branchName?: string; // Optional helper
}

// Planned Schedule (Roster)
export interface ShiftSchedule {
  id: string;
  userId: string;
  branchId: string;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:mm (24hr)
  endTime: string; // HH:mm (24hr)
  note?: string;
}

// --- Settings & Promotions ---
export type Language = 'en' | 'th' | 'lo';

export interface Promotion {
  id: string;
  title: string;
  imageUrl: string;
  isActive: boolean;
  order?: number;
}

export interface LocalDatabaseConfig {
  enabled: boolean;
  type: 'postgresql' | 'sqlite' | 'mysql';
  host: string;
  port: string;
  databaseName: string;
  username: string;
  password: string;
