'use client';

import React, { useEffect, useState } from 'react';
import { ShoppingCart, Star, CheckCircle, QrCode, Store, Lock, Image as ImageIcon } from 'lucide-react';
import { CartItem, Customer, CustomerDisplaySettings, Promotion } from '../../types';

// Define the data structure received from the POS
interface DisplayData {
  type: 'UPDATE' | 'CHECKOUT' | 'SUCCESS' | 'RESET';
  cart: CartItem[];
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
  customer?: Customer | null;
  paymentMethod?: string;
  amountReceived?: number;
  change?: number;
  companyName?: string;
  settings?: CustomerDisplaySettings;
  activePromotions?: Promotion[];
}

export default function CustomerDisplayPage() {
  const [data, setData] = useState<DisplayData>({
    type: 'RESET',
    cart: [],
    subtotal: 0,
    discount: 0,
    tax: 0,
    total: 0,
    companyName: 'BuildMaster'
  });

  const [currentPromoIndex, setCurrentPromoIndex] = useState(0);

  useEffect(() => {
    // Connect to the broadcast channel
    const channel = new BroadcastChannel('customer_display_channel');

    channel.onmessage = (event) => {
      if (event.data) {
        setData(prev => ({
          ...prev,
          ...event.data,
          // Preserve settings if not provided in update
          settings: event.data.settings || prev.settings,
          activePromotions: event.data.activePromotions || prev.activePromotions
        }));
      }
    };

    return () => {
      channel.close();
    };
  }, []);

  // Carousel Logic
  useEffect(() => {
    if (data.activePromotions && data.activePromotions.length > 1) {
      const interval = setInterval(() => {
        setCurrentPromoIndex(prev => (prev + 1) % data.activePromotions!.length);
      }, (data.settings?.promotionInterval || 5) * 1000);
      return () => clearInterval(interval);
    }
  }, [data.activePromotions, data.settings?.promotionInterval]);

  // Disabled State
  if (data.settings && data.settings.enabled === false) {
    return (
      <div className="h-screen bg-slate-900 flex flex-col items-center justify-center text-slate-500 p-8 text-center">
        <Lock className="w-16 h-16 mb-4 opacity-50" />
        <h1 className="text-2xl font-bold">Display Closed</h1>
      </div>
    );
  }

  // Idle State (Welcome Screen / Promotions)
  if (data.cart.length === 0 && data.type === 'RESET') {
    const hasPromos = data.activePromotions && data.activePromotions.length > 0;

    return (
      <div className="h-screen bg-slate-900 relative overflow-hidden">
        {hasPromos ? (
          <div className="absolute inset-0 z-0">
             {data.activePromotions!.map((promo, idx) => (
                <div 
                  key={promo.id}
                  className={`absolute inset-0 bg-cover bg-center transition-opacity duration-1000 ease-in-out ${idx === currentPromoIndex ? 'opacity-50' : 'opacity-0'}`}
                  style={{ backgroundImage: `url(${promo.imageUrl})` }}
                />
             ))}
             <div className="absolute inset-0 bg-black/40" /> {/* Overlay */}
          </div>
        ) : (
          <div className="absolute inset-0 flex items-center justify-center opacity-10">
             <Store className="w-96 h-96 text-white" />
          </div>
        )}

        <div className="relative z-10 h-full flex flex-col items-center justify-center text-white p-12 text-center">
          <div className="w-32 h-32 bg-orange-500 rounded-full flex items-center justify-center mb-8 shadow-2xl animate-bounce-slow">
            <Store className="w-16 h-16 text-white" />
          </div>
          <h1 className="text-6xl font-bold mb-6 drop-shadow-lg tracking-tight">
            {data.companyName}
          </h1>
          <p className="text-2xl text-slate-200 max-w-2xl leading-relaxed drop-shadow-md">
            {data.settings?.welcomeMessage || "Welcome! We are ready to serve you."}
          </p>
        </div>
      </div>
    );
  }

  // Success State
  if (data.type === 'SUCCESS') {
    return (
      <div className="h-screen bg-green-600 flex flex-col items-center justify-center text-white p-8 text-center">
        <div className="w-32 h-32 bg-white rounded-full flex items-center justify-center mb-8 shadow-2xl">
          <CheckCircle className="w-20 h-20 text-green-600" />
        </div>
        <h1 className="text-6xl font-bold mb-4">Thank You!</h1>
        <p className="text-2xl text-green-100 mb-8">Payment Successful</p>

        <div className="bg-white/20 backdrop-blur-md rounded-2xl p-8 min-w-[400px]">
           <div className="flex justify-between text-xl mb-2">
             <span>Total Paid</span>
             <span className="font-bold">${data.total.toFixed(2)}</span>
           </div>
           {data.change !== undefined && data.change > 0 && (
             <div className="flex justify-between text-3xl font-bold mt-4 pt-4 border-t border-white/30">
               <span>Change Due</span>
               <span>${data.change.toFixed(2)}</span>
             </div>
           )}
        </div>
      </div>
    );
  }

  // Active Transaction State
  return (
    <div className="h-screen bg-slate-50 flex flex-col md:flex-row overflow-hidden">
      {/* Left: Cart Items */}
      <div className="flex-1 flex flex-col h-full border-r border-slate-200 bg-white">
        <div className="p-6 bg-slate-800 text-white flex justify-between items-center shadow-md">
          <h2 className="text-2xl font-bold flex items-center">
            <ShoppingCart className="w-6 h-6 mr-3" />
            Your Order
          </h2>
          <span className="bg-orange-500 px-3 py-1 rounded-full text-sm font-bold">
            {data.cart.reduce((acc, item) => acc + item.quantity, 0)} Items
          </span>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {data.cart.map((item, index) => (
            <div key={`${item.id}-${index}`} className="flex justify-between items-center p-4 bg-slate-50 rounded-xl border border-slate-100 shadow-sm animate-fade-in">
              <div className="flex-1">
                <h3 className="text-xl font-bold text-slate-800">{item.name}</h3>
                <p className="text-slate-500">
                  {item.quantity} {item.sellUnit} x ${item.sellPrice.toFixed(2)}
                </p>
              </div>
              <div className="text-xl font-bold text-slate-900">
                ${(item.quantity * item.sellPrice).toFixed(2)}
              </div>
            </div>
          ))}
        </div>

        {/* Customer Info footer if exists */}
        {data.customer && (
          <div className="p-4 bg-blue-50 border-t border-blue-100 flex items-center justify-between text-blue-900">
             <div className="flex items-center">
                <Star className="w-5 h-5 mr-2 text-yellow-500 fill-current" />
                <span className="font-bold text-lg">{data.customer.name}</span>
             </div>
             {data.customer.level && (
               <span className="bg-blue-200 px-2 py-1 rounded text-xs font-bold text-blue-800">
                 {data.customer.level.name} Member
               </span>
             )}
          </div>
        )}
      </div>

      {/* Right: Totals & Checkout Status */}
      <div className="w-full md:w-[450px] bg-slate-100 flex flex-col p-6 shadow-xl z-10">
        <div className="flex-1 flex flex-col justify-center space-y-6">
           {data.type === 'CHECKOUT' ? (
             <div className="bg-white p-8 rounded-3xl shadow-lg border-2 border-orange-100 text-center animate-fade-in">
                {data.paymentMethod === 'qr' ? (
                   <>
                     <h3 className="text-2xl font-bold text-slate-800 mb-4">Scan to Pay</h3>
                     <div className="bg-slate-900 p-4 rounded-xl inline-block mb-4">
                        <img 
                          src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=Payment_OnePay_${data.total}`} 
                          alt="QR Code" 
                          className="w-48 h-48 object-contain rounded-lg bg-white"
                        />
                     </div>
                     <p className="text-slate-500">OnePay / Banking App</p>
                   </>
                ) : (
                   <>
                     <h3 className="text-2xl font-bold text-slate-800 mb-2">Payment Processing</h3>
                     <p className="text-slate-500 mb-6">Please follow the instructions on the terminal</p>
                     <div className="text-5xl font-bold text-slate-900 mb-2">${data.total.toFixed(2)}</div>
                     <div className="text-lg font-medium text-orange-600 uppercase tracking-wide">
                        Paying via {data.paymentMethod || 'Cash'}
                     </div>
                   </>
                )}
             </div>
           ) : (
             <div className="text-center space-y-4">
                <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center mx-auto shadow-sm">
                   <Store className="w-12 h-12 text-slate-300" />
                </div>
                <h3 className="text-xl font-medium text-slate-400">Total Amount Due</h3>
             </div>
           )}
        </div>

        <div className="bg-white rounded-3xl p-8 shadow-lg border border-slate-200">
          <div className="space-y-3 mb-6 text-lg">
            <div className="flex justify-between text-slate-600">
              <span>Subtotal</span>
              <span>${data.subtotal.toFixed(2)}</span>
            </div>
            {data.discount > 0 && (
              <div className="flex justify-between text-green-600 font-medium">
                <span>Discount</span>
                <span>-${data.discount.toFixed(2)}</span>
              </div>
            )}
            {data.tax > 0 && (
              <div className="flex justify-between text-slate-500">
                <span>Tax</span>
                <span>${data.tax.toFixed(2)}</span>
              </div>
            )}
          </div>
          <div className="pt-6 border-t-2 border-dashed border-slate-200">
            <div className="flex justify-between items-end">
              <span className="text-xl font-bold text-slate-700">Total</span>
              <span className="text-6xl font-bold text-slate-900 tracking-tight">${data.total.toFixed(2)}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { 
  LayoutDashboard, 
  ShoppingCart, 
  Package, 
  Hammer, 
  LogOut,
  Menu,
  Scale,
  FolderTree,
  Store,
  Container,
  ClipboardList,
  FileCheck,
  UserCircle,
  Users,
  Settings,
  RefreshCw,
  Contact,
  Clock,
  Tv
} from 'lucide-react';
import { User, UserRole } from '../types';
import { useGlobal } from '../context/GlobalContext';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  onTabChange: (tab: string) => void;
  currentUser: User | null;
  onLogout: () => void;
}

interface NavItemConfig {
  id: string;
  icon: any;
  label: string;
  allowedRoles: UserRole[];
}

const NAV_ITEMS: NavItemConfig[] = [
  { id: 'dashboard', icon: LayoutDashboard, label: 'Dashboard', allowedRoles: ['Admin', 'Manager'] },
  { id: 'pos', icon: ShoppingCart, label: 'Point of Sale', allowedRoles: ['Admin', 'Manager', 'Staff', 'Cashier'] },
  { id: 'shifts', icon: Clock, label: 'My Shift', allowedRoles: ['Admin', 'Manager', 'Staff', 'Cashier'] },
  { id: 'inventory', icon: Package, label: 'Inventory', allowedRoles: ['Admin', 'Manager', 'Staff'] },
  { id: 'stock', icon: ClipboardList, label: 'Stock Mgmt', allowedRoles: ['Admin', 'Manager', 'Staff'] },
  { id: 'customers', icon: Contact, label: 'Customers', allowedRoles: ['Admin', 'Manager', 'Cashier'] },
  { id: 'approvals', icon: FileCheck, label: 'Approvals', allowedRoles: ['Admin', 'Manager'] },
  { id: 'promotions', icon: Tv, label: 'Promotions', allowedRoles: ['Admin', 'Manager'] },
  { id: 'sync', icon: RefreshCw, label: 'Data Sync', allowedRoles: ['Admin', 'Manager'] },
  { id: 'categories', icon: FolderTree, label: 'Categories', allowedRoles: ['Admin'] },
  { id: 'units', icon: Scale, label: 'Unit Mgmt', allowedRoles: ['Admin'] },
  { id: 'branches', icon: Store, label: 'Branches & POS', allowedRoles: ['Admin'] },
  { id: 'warehouses', icon: Container, label: 'Warehouse (WMS)', allowedRoles: ['Admin'] },
  { id: 'users', icon: Users, label: 'Users & Roles', allowedRoles: ['Admin'] },
  { id: 'settings', icon: Settings, label: 'Settings', allowedRoles: ['Admin', 'Manager'] },
];

export const Layout: React.FC<LayoutProps> = ({ children, activeTab, onTabChange, currentUser, onLogout }) => {
  const { t } = useGlobal();
  const [mobileMenuOpen, setMobileMenuOpen] = React.useState(false);

  // Filter nav items based on user role
  const visibleNavItems = NAV_ITEMS.filter(item => 
    currentUser && item.allowedRoles.includes(currentUser.role)
  );

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden">
      {/* Sidebar - Desktop */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 text-white transform transition-transform duration-300 ease-in-out
        md:relative md:translate-x-0
        ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="flex items-center justify-center h-20 border-b border-slate-800">
          <div className="flex items-center space-x-2">
            <div className="bg-construction-orange p-2 rounded-lg">
              <Hammer className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold tracking-tight">{t('app.name')}</h1>
          </div>
        </div>

        {/* User Profile Mini-Card */}
        {currentUser && (
          <div className="p-4 border-b border-slate-800 bg-slate-800/50">
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center overflow-hidden border-2 border-slate-600">
                {currentUser.avatarUrl ? (
                  <img src={currentUser.avatarUrl} alt={currentUser.name} className="w-full h-full object-cover" />
                ) : (
                  <UserCircle className="w-6 h-6 text-slate-400" />
                )}
              </div>
              <div className="overflow-hidden">
                <p className="text-sm font-semibold text-white truncate">{currentUser.name}</p>
                <span className={`text-xs px-2 py-0.5 rounded-full inline-block mt-1 font-bold tracking-wide ${
                  currentUser.role === 'Admin' ? 'bg-purple-500/20 text-purple-300' : 
                  currentUser.role === 'Manager' ? 'bg-indigo-500/20 text-indigo-300' :
                  currentUser.role === 'Staff' ? 'bg-blue-500/20 text-blue-300' :
                  'bg-green-500/20 text-green-300'
                }`}>
                  {currentUser.role}
                </span>
              </div>
            </div>
          </div>
        )}

        <nav className="p-4 mt-2 overflow-y-auto max-h-[calc(100vh-220px)] scrollbar-hide">
          {visibleNavItems.map(item => {
            const Icon = item.icon;
            return (
              <button
                key={item.id}
                onClick={() => {
                  onTabChange(item.id);
                  setMobileMenuOpen(false);
                }}
                className={`flex items-center w-full px-4 py-3 mb-2 rounded-lg transition-colors duration-200 ${
                  activeTab === item.id 
                    ? 'bg-primary-600 text-white shadow-md' 
                    : 'text-slate-400 hover:bg-slate-800 hover:text-white'
                }`}
              >
                <Icon className="w-5 h-5 mr-3" />
                <span className="font-medium">{t(`nav.${item.id}`)}</span>
              </button>
            );
          })}
        </nav>

        <div className="absolute bottom-0 w-full p-4 border-t border-slate-800">
          <button 
            onClick={onLogout}
            className="flex items-center w-full px-4 py-3 text-slate-400 hover:text-red-400 hover:bg-slate-800 rounded-lg transition-colors"
          >
            <LogOut className="w-5 h-5 mr-3" />
            <span>{t('nav.logout')}</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between p-4 bg-white border-b border-slate-200 shadow-sm z-10">
          <div className="flex items-center space-x-2">
            <Hammer className="w-6 h-6 text-construction-orange" />
            <span className="font-bold text-slate-800">{t('app.name')}</span>
          </div>
          <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="p-2 text-slate-600">
            <Menu className="w-6 h-6" />
          </button>
        </header>

        {/* Content Area */}
        <main className="flex-1 overflow-y-auto p-4 md:p-6 bg-slate-50 relative">
          {children}
        </main>
      </div>

      {/* Overlay for mobile menu */}
      {mobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 z-40 md:hidden"
          onClick={() => setMobileMenuOpen(false)}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { Inventory } from './components/Inventory';
import { PosTerminal } from './components/PosTerminal';
import { UnitManagement } from './components/UnitManagement';
import { CategoryManagement } from './components/CategoryManagement';
import { BranchManagement } from './components/BranchManagement';
import { WarehouseManagement } from './components/WarehouseManagement';
import { StockManagement } from './components/StockManagement';
import { ApprovalManagement } from './components/ApprovalManagement';
import { UserManagement } from './components/UserManagement';
import { Settings } from './components/Settings';
import { SyncManagement } from './components/SyncManagement';
import { CustomerManagement } from './components/CustomerManagement';
import { ShiftManagement } from './components/ShiftManagement';
import { PromotionsManagement } from './components/PromotionsManagement';
import LoginPage from './app/page';
import { useGlobal } from './context/GlobalContext';

function App() {
  const {
    currentUser, setCurrentUser,
    users,
    products, sales, units, categories, branches, posMachines, warehouses, locations,
    transfers, counts, reservations, receipts, adjustments, syncLogs, customers, shifts, shiftSchedules, promotions,
    processSale, addProduct, updateProduct, deleteProduct,
    addUnit, updateUnit, deleteUnit, addCategory, updateCategory, deleteCategory,
    addBranch, updateBranch, deleteBranch, addPos, updatePos, deletePos,
    addWarehouse, updateWarehouse, deleteWarehouse, addLocation, updateLocation, deleteLocation,
    addUser, updateUser, deleteUser, addCustomer, updateCustomer, deleteCustomer,
    updateTransfer, deleteTransfer, updateCount, deleteCount, updateReservation, deleteReservation,
    updateReceipt, deleteReceipt, updateAdjustment, deleteAdjustment,
    handleStockStatusChange, handleSyncOperation,
    startShift, endShift,
    addPromotion, updatePromotion, deletePromotion,
    settings, updateSettings,
    t
  } = useGlobal();

  const [activeTab, setActiveTab] = useState('dashboard');

  // Effect to redirect/set active tab based on role upon login
  useEffect(() => {
    if (currentUser) {
      if (currentUser.role === 'Cashier') {
        setActiveTab('pos');
      } else if (currentUser.role === 'Staff') {
        setActiveTab('inventory');
      } else {
        setActiveTab('dashboard');
      }
    }
  }, [currentUser]);

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveTab('dashboard');
  };

  // --- Render Login via app/page ---
  if (!currentUser) {
    return <LoginPage />;
  }

  // --- Main Render ---
  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={setActiveTab}
      currentUser={currentUser}
      onLogout={handleLogout}
    >
      {activeTab === 'dashboard' && <Dashboard sales={sales} products={products} />}

      {activeTab === 'pos' && (
        <PosTerminal 
          products={products} 
          onProcessSale={processSale} 
          settings={settings}
        />
      )}

      {activeTab === 'shifts' && (
        <ShiftManagement 
          shifts={shifts}
          branches={branches}
          users={users}
          currentUser={currentUser}
          onStartShift={startShift}
          onEndShift={endShift}
        />
      )}

      {activeTab === 'inventory' && (
        <Inventory 
          products={products} 
          units={units} 
          categories={categories}
          warehouses={warehouses}
          sales={sales}
          onAddProduct={addProduct}
          onUpdateProduct={updateProduct}
          onDeleteProduct={deleteProduct}
        />
      )}

      {activeTab === 'stock' && (
        <StockManagement 
          warehouses={warehouses}
          products={products}
          transfers={transfers}
          counts={counts}
          reservations={reservations}
          receipts={receipts}
          adjustments={adjustments}
          defaultItemsPerPage={settings.defaultItemsPerPage}
          onUpdateTransfer={updateTransfer}
          onUpdateCount={updateCount}
          onUpdateReservation={updateReservation}
          onUpdateReceipt={updateReceipt}
          onUpdateAdjustment={updateAdjustment}
          onDeleteTransfer={deleteTransfer}
          onDeleteCount={deleteCount}
          onDeleteReservation={deleteReservation}
          onDeleteReceipt={deleteReceipt}
          onDeleteAdjustment={deleteAdjustment}
          onStatusChange={handleStockStatusChange}
        />
      )}

      {activeTab === 'approvals' && (
        <ApprovalManagement 
          transfers={transfers}
          counts={counts}
          reservations={reservations}
          receipts={receipts}
          adjustments={adjustments}
          warehouses={warehouses}
          onStatusChange={handleStockStatusChange}
        />
      )}

      {activeTab === 'promotions' && (
        <PromotionsManagement 
          promotions={promotions}
          onAddPromotion={addPromotion}
          onUpdatePromotion={updatePromotion}
          onDeletePromotion={deletePromotion}
        />
      )}

      {activeTab === 'customers' && (
        <CustomerManagement
          customers={customers}
          onAddCustomer={addCustomer}
          onUpdateCustomer={updateCustomer}
          onDeleteCustomer={deleteCustomer}
        />
      )}

      {activeTab === 'sync' && (
        <SyncManagement 
          settings={settings}
          logs={syncLogs}
          sales={sales}
          onSync={handleSyncOperation}
        />
      )}

      {activeTab === 'units' && (
        <UnitManagement 
          units={units} 
          onAddUnit={addUnit}
          onUpdateUnit={updateUnit} 
          onDeleteUnit={deleteUnit} 
        />
      )}

      {activeTab === 'categories' && (
        <CategoryManagement 
          categories={categories}
          onAddCategory={addCategory}
          onUpdateCategory={updateCategory}
          onDeleteCategory={deleteCategory}
        />
      )}

      {activeTab === 'branches' && (
        <BranchManagement
          branches={branches}
          posMachines={posMachines}
          onAddBranch={addBranch}
          onUpdateBranch={updateBranch}
          onDeleteBranch={deleteBranch}
          onAddPosMachine={addPos}
          onUpdatePosMachine={updatePos}
          onDeletePosMachine={deletePos}
        />
      )}

      {activeTab === 'warehouses' && (
        <WarehouseManagement
           branches={branches}
           warehouses={warehouses}
           locations={locations}
           onAddWarehouse={addWarehouse}
           onUpdateWarehouse={updateWarehouse}
           onDeleteWarehouse={deleteWarehouse}
           onAddLocation={addLocation}
           onUpdateLocation={updateLocation}
           onDeleteLocation={deleteLocation}
        />
      )}

      {activeTab === 'users' && (
        <UserManagement
          users={users}
          onAddUser={addUser}
          onUpdateUser={updateUser}
          onDeleteUser={deleteUser}
        />
      )}

      {activeTab === 'settings' && (
        <Settings 
          settings={settings} 
          onUpdateSettings={updateSettings} 
          branches={branches}
          posMachines={posMachines}
        />
      )}
    </Layout>
  );
}

export default App;

export enum Category {
  CEMENT = 'Cement & Concrete',
  STEEL = 'Steel & Metal',
  WOOD = 'Wood & Lumber',
  PAINT = 'Paints & Finishes',
  TOOLS = 'Tools & Hardware',
  PLUMBING = 'Plumbing',
  ELECTRICAL = 'Electrical',
  CONSUMABLES = 'General Consumables'
}

export type UnitCategory = 'Weight' | 'Length' | 'Quantity';

export interface UnitDefinition {
  id: string;
  name: string;      // e.g. Kilogram
  symbol: string;    // e.g. kg
  category: UnitCategory;
  baseFactor: number; // 1 for base unit (e.g. g), 1000 for kg
  isBase: boolean;   // True if this is the reference unit
}

export interface CategoryItem {
  id: string;
  name: string;
  parentId: string | null; // null for root categories
  description?: string;
}

export interface ProductVariant {
  id: string;
  name: string;      // e.g., 'Piece', 'Small', 'Red'
  code: string;      // SKU/Code for the variant
  barcode: string;   // Barcode for the variant
  conversionFactor: number; // How many variants in the main unit (e.g. 12 pieces in 1 box)
  price: number;     // Price per variant
}

export interface ProductInventory {
  warehouseId: string;
  quantity: number;
}

export interface BranchPrice {
  branchId: string;
  price: number;
}

export interface ProductPhysical {
  weight?: number; // kg
  width?: number;  // cm
  height?: number; // cm
  depth?: number;  // cm (length)
}

export interface Product {
  id: string;
  name: string;
  category: Category | string; 
  price: number;     // Base Price (Global)
  branchPrices?: BranchPrice[]; // Overrides per branch
  stock: number;     // Stock count in MAIN units (Aggregate Total)
  minStock?: number; // Minimum stock threshold for alerts
  warehouseInventory?: ProductInventory[]; // Breakdown by warehouse
  unit: string;      // Name of the MAIN unit (e.g., 'bag', 'box')
  physical?: ProductPhysical; // New: Physical attributes
  imageUrl?: string;
  sku: string;       // SKU of MAIN unit
  barcode: string;   // Barcode of MAIN unit
  variants?: ProductVariant[]; // List of sub-products/variants
}

export interface CartItem extends Product {
  quantity: number;
  // Handling multi-unit/variant logic
  selectedVariantId?: string; // null if main unit, string if variant
  sellPrice: number; 
  sellUnit: string;  
  sellConversionFactor: number; // 1 for main, X for variant
}

export interface Sale {
  id: string;
  items: CartItem[];
  subtotal?: number; // Raw total before discount/tax
  discountAmount?: number; // Deduction amount
  total: number; // Final payable amount
  date: string;
  paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit';
  paymentStatus: 'paid' | 'unpaid' | 'partial'; // Track debt status
  amountReceived?: number; // Amount given by customer
  change?: number; // Change returned
  remainingAmount?: number; // Amount left to pay (for credit/partial)
  status: 'completed' | 'voided'; // Order status
  syncStatus?: 'synced' | 'pending' | 'failed'; // Track sync state
  customerId?: string; // Link to customer
  customerName?: string; // Snapshot of name
}

export interface EstimateRequest {
  query: string;
}

export interface EstimateResultItem {
  productName: string;
  estimatedQuantity: number;
  unit: string;
  reasoning: string;
  matchedProductId?: string; // If found in inventory
}

// --- AI Inventory Analysis Types ---
export interface ReorderSuggestion {
  productId: string;
  productName: string;
  currentStock: number;
  suggestedReorderQty: number;
  priority: 'High' | 'Medium' | 'Low';
  reasoning: string;
}

export interface NewProductSuggestion {
  name: string;
  categoryName: string;
  estimatedPrice: number;
  reasoning: string;
  suggestedUnit: string;
}

export interface BundleSuggestion {
  bundleName: string;
  components: string[];
  estimatedPrice: number;
  reasoning: string;
