import React, { useState } from 'react';
import { Promotion } from '../types';
import { 
  Plus, 
  Trash2, 
  Image as ImageIcon, 
  X, 
  Edit2, 
  Check, 
  Eye, 
  EyeOff,
  Calendar,
  Clock
} from 'lucide-react';

interface PromotionsManagementProps {
  promotions: Promotion[];
  onAddPromotion: (promo: Promotion) => void;
  onUpdatePromotion: (promo: Promotion) => void;
  onDeletePromotion: (id: string) => void;
}

export const PromotionsManagement: React.FC<PromotionsManagementProps> = ({ 
  promotions, 
  onAddPromotion, 
  onUpdatePromotion, 
  onDeletePromotion 
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<Partial<Promotion>>({
    title: '',
    imageUrl: '',
    isActive: true,
    startDate: '',
    endDate: ''
  });

  const handleOpenModal = (promo?: Promotion) => {
    if (promo) {
      setEditingId(promo.id);
      setFormData(promo);
    } else {
      setEditingId(null);
      setFormData({
        title: '',
        imageUrl: '',
        isActive: true,
        startDate: '',
        endDate: ''
      });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.imageUrl) return;

    if (editingId) {
      onUpdatePromotion({ ...formData, id: editingId } as Promotion);
    } else {
      onAddPromotion({ ...formData, id: `promo-${Date.now()}` } as Promotion);
    }
    setIsModalOpen(false);
  };

  const handleToggleActive = (promo: Promotion) => {
    onUpdatePromotion({ ...promo, isActive: !promo.isActive });
  };

  const getStatusInfo = (promo: Promotion) => {
    const now = new Date();
    // Normalize today to start of day for easier comparison if needed, 
    // but typically strict timestamp is better for "Expires at midnight"

    if (!promo.isActive) return { label: 'Inactive', color: 'bg-slate-100 text-slate-500', icon: EyeOff };

    if (promo.endDate) {
      const end = new Date(promo.endDate);
      end.setHours(23, 59, 59, 999); // End of the day
      if (now > end) return { label: 'Expired', color: 'bg-red-100 text-red-600', icon: Clock };
    }

    if (promo.startDate) {
      const start = new Date(promo.startDate);
      if (now < start) return { label: 'Scheduled', color: 'bg-blue-100 text-blue-600', icon: Calendar };
    }

    return { label: 'Active', color: 'bg-green-100 text-green-600', icon: Check };
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Promotions Management</h2>
          <p className="text-slate-500">Manage banners, schedule ads, and customer display content.</p>
        </div>
        <button 
          onClick={() => handleOpenModal()}
          className="flex items-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium shadow-sm"
        >
          <Plus className="w-4 h-4 mr-2" />
          Add Promotion
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 overflow-y-auto pb-4">
        {promotions.length === 0 ? (
          <div className="col-span-full flex flex-col items-center justify-center p-12 bg-white rounded-xl border border-dashed border-slate-300 text-slate-400">
            <ImageIcon className="w-12 h-12 mb-4 opacity-50" />
            <p>No promotions active.</p>
            <button 
              onClick={() => handleOpenModal()}
              className="mt-4 text-primary-600 hover:underline font-medium"
            >
              Create your first promotion
            </button>
          </div>
        ) : (
          promotions.map((promo) => {
            const status = getStatusInfo(promo);
            const StatusIcon = status.icon;

            return (
              <div key={promo.id} className={`group bg-white rounded-xl shadow-sm border overflow-hidden flex flex-col transition-all ${promo.isActive ? 'border-slate-200' : 'border-slate-100 opacity-75'}`}>
                <div className="relative aspect-video bg-slate-100 overflow-hidden">
                  <img 
                    src={promo.imageUrl} 
                    alt={promo.title} 
                    className="w-full h-full object-cover transition-transform group-hover:scale-105" 
                  />
                  <div className="absolute top-2 left-2">
                     <span className={`flex items-center px-2 py-1 rounded-md text-xs font-bold shadow-sm backdrop-blur-md ${status.color.includes('bg-') ? status.color.replace('bg-', 'bg-white/90 text-') : 'bg-white/90 text-slate-600'}`}>
                        <StatusIcon className="w-3 h-3 mr-1" /> {status.label}
                     </span>
                  </div>

                  <div className="absolute top-2 right-2 flex space-x-2 opacity-0 group-hover:opacity-100 transition-opacity">
                     <button 
                        onClick={() => handleOpenModal(promo)}
                        className="p-2 bg-white text-slate-600 rounded-full hover:text-primary-600 shadow-sm"
                     >
                        <Edit2 className="w-4 h-4" />
                     </button>
                     <button 
                        onClick={() => {
                           if(confirm('Delete this promotion?')) onDeletePromotion(promo.id);
                        }}
                        className="p-2 bg-white text-slate-600 rounded-full hover:text-red-600 shadow-sm"
                     >
                        <Trash2 className="w-4 h-4" />
                     </button>
                  </div>
                </div>

                <div className="p-4 flex items-center justify-between">
                  <div className="flex-1 min-w-0 pr-4">
                    <h3 className="font-bold text-slate-800 truncate" title={promo.title}>{promo.title || 'Untitled Promotion'}</h3>
                    {promo.startDate || promo.endDate ? (
                       <div className="text-xs text-slate-500 mt-1 flex items-center">
                          <Calendar className="w-3 h-3 mr-1" />
                          {promo.startDate ? new Date(promo.startDate).toLocaleDateString() : 'Now'} 
                          {' - '} 
                          {promo.endDate ? new Date(promo.endDate).toLocaleDateString() : 'Forever'}
                       </div>
                    ) : (
                       <p className="text-xs text-slate-400 mt-1">Always Active</p>
                    )}
                  </div>
                  <button
                    onClick={() => handleToggleActive(promo)}
                    className={`relative inline-flex items-center h-6 rounded-full w-11 transition-colors focus:outline-none shrink-0 ${promo.isActive ? 'bg-green-500' : 'bg-slate-300'}`}
                  >
                    <span className={`inline-block w-4 h-4 transform bg-white rounded-full transition-transform ${promo.isActive ? 'translate-x-6' : 'translate-x-1'}`} />
                  </button>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-md animate-fade-in">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <h3 className="text-xl font-bold text-slate-800">
                {editingId ? 'Edit Promotion' : 'Add New Promotion'}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Title (Optional)</label>
                <input
                  type="text"
                  value={formData.title}
                  onChange={e => setFormData({...formData, title: e.target.value})}
                  className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                  placeholder="e.g. Summer Sale 50% Off"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Image URL *</label>
                <input
                  required
                  type="text"
                  value={formData.imageUrl}
                  onChange={e => setFormData({...formData, imageUrl: e.target.value})}
                  className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                  placeholder="https://example.com/banner.jpg"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Start Date</label>
                    <input
                      type="date"
                      value={formData.startDate || ''}
                      onChange={e => setFormData({...formData, startDate: e.target.value})}
                      className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                 </div>
                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">End Date</label>
                    <input
                      type="date"
                      value={formData.endDate || ''}
                      onChange={e => setFormData({...formData, endDate: e.target.value})}
                      className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                 </div>
              </div>

              <div className="flex items-center space-x-2 pt-2">
                <input 
                  type="checkbox" 
                  id="isActive"
                  checked={formData.isActive}
                  onChange={e => setFormData({...formData, isActive: e.target.checked})}
                  className="w-4 h-4 text-primary-600 rounded border-slate-300 focus:ring-primary-500"
                />
                <label htmlFor="isActive" className="text-sm font-medium text-slate-700">Set as Active</label>
              </div>

              {formData.imageUrl && (
                 <div className="mt-4 rounded-lg overflow-hidden border border-slate-200 bg-slate-50 aspect-video flex items-center justify-center relative">
                    <img 
                      src={formData.imageUrl} 
                      alt="Preview" 
                      className="max-w-full max-h-full object-contain"
                      onError={(e) => (e.currentTarget.src = 'https://via.placeholder.com/400x225?text=Invalid+Image+URL')}
                    />
                    <div className="absolute bottom-2 right-2 bg-black/50 text-white text-[10px] px-2 py-1 rounded">Preview</div>
                 </div>
              )}

              <div className="flex justify-end pt-4 space-x-3">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-6 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm flex items-center"
                >
                  <Check className="w-4 h-4 mr-2" />
                  Save Promotion
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, CartItem, Category, EstimateResultItem, SystemSettings, Customer, Sale } from '../types';
import { 
  Search, ShoppingCart, Plus, Minus, Trash2, CreditCard, Banknote, Sparkles, Box, 
  ArrowLeft, ScanBarcode, Layers, User, X, Percent, Star, QrCode, ArrowRight, Printer, CheckCircle, FileText,
  Monitor
} from 'lucide-react';
import { AiAssistant } from './AiAssistant';
import { useGlobal } from '../context/GlobalContext';
import { useCartStore } from '../store/useCartStore';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t, promotions } = useGlobal();
  const { cart, addToCart, removeFromCart, updateQuantity, clearCart } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);

  // Checkout & Payment State
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  // Receipt State
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);

  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [customerSearch, setCustomerSearch] = useState('');

  // --- Calculations ---
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);

  // 1. Apply Discount
  let discountAmount = 0;
  let discountedSubtotal = rawSubtotal;

  if (customerLevel && customerLevel.discountPercentage > 0) {
    discountAmount = rawSubtotal * (customerLevel.discountPercentage / 100);
    discountedSubtotal = rawSubtotal - discountAmount;
  }

  // 2. Apply Tax
  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       // Tax added on top of discounted price
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       // Tax included in price, back-calculate from discounted price
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       // Subtotal for display is usually net of tax in this case
       // But keeping simple logic: finalTotal IS the discounted price
       finalTotal = discountedSubtotal;
    }
  }

  const receivedAmount = parseFloat(receivedAmountStr) || 0;

  // For Cash: Change = Received - Total
  // For Credit: Remaining Debt = Total - Received (Deposit)
  const change = Math.max(0, receivedAmount - finalTotal);
  const remainingCash = Math.max(0, finalTotal - receivedAmount);
  const remainingDebt = Math.max(0, finalTotal - receivedAmount);

  // --- Broadcast Channel for Customer Display ---
  useEffect(() => {
    if (settings?.customerDisplay?.enabled) {
      const channel = new BroadcastChannel('customer_display_channel');

      const now = new Date();
      const activePromotions = promotions?.filter(p => {
        if (!p.isActive) return false;

        // Date Check
        const start = p.startDate ? new Date(p.startDate) : null;
        const end = p.endDate ? new Date(p.endDate) : null;
        if (end) end.setHours(23, 59, 59, 999); // End of day

        if (start && now < start) return false;
        if (end && now > end) return false;

        return true;
      }) || [];

      const payload = {
        type: isCheckoutOpen ? 'CHECKOUT' : (cart.length === 0 ? 'RESET' : 'UPDATE'),
        cart: cart,
        subtotal: rawSubtotal,
        discount: discountAmount,
        tax: taxAmount,
        total: finalTotal,
        customer: selectedCustomer,
        paymentMethod: paymentMethod,
        amountReceived: receivedAmount,
        change: change,
        companyName: settings?.companyName,
        settings: settings?.customerDisplay,
        activePromotions: activePromotions // Send filtered active ads
      };

      channel.postMessage(payload);

      return () => {
        channel.close();
      };
    }
  }, [cart, rawSubtotal, discountAmount, taxAmount, finalTotal, selectedCustomer, isCheckoutOpen, paymentMethod, receivedAmount, change, settings, promotions]);

  const handleOpenCustomerDisplay = () => {
    window.open('/customer-display', 'CustomerDisplay', 'width=1024,height=768,menubar=no,toolbar=no,location=no,status=no');
  };

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) ||
        v.barcode.includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  const filteredCustomers = useMemo(() => {
    return customers.filter(c => 
      c.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      c.phone.includes(customerSearch) ||
      c.code.toLowerCase().includes(customerSearch.toLowerCase())
    );
  }, [customers, customerSearch]);

  const handleBarcodeScan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;

    const mainMatch = products.find(p => p.barcode === searchTerm || p.sku === searchTerm);
    if (mainMatch) {
      addToCart(mainMatch, 1, undefined);
      setSearchTerm(''); 
      return;
    }

    for (const p of products) {
      if (p.variants) {
        const variantMatch = p.variants.find(v => v.barcode === searchTerm || v.code === searchTerm);
        if (variantMatch) {
          addToCart(p, 1, variantMatch.id);
          setSearchTerm('');
          return;
        }
      }
    }
  };

  const handleAiItemsAdded = (items: EstimateResultItem[]) => {
    items.forEach(est => {
      if (est.matchedProductId) {
        const product = products.find(p => p.id === est.matchedProductId);
        if (product) {
          addToCart(product, Math.ceil(est.estimatedQuantity), undefined);
        }
      }
    });
  };

  const handleCheckoutClick = () => {
    setReceivedAmountStr('');
    setPaymentMethod('cash');
    setIsCheckoutOpen(true);
  };

  const handlePaymentMethodChange = (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => {
    if (method === 'credit' && !selectedCustomer) {
      alert("Please select a customer first to use Credit/Debt.");
      return;
    }
    setPaymentMethod(method);
    setReceivedAmountStr(''); // Reset input on method switch
  };

  const handleProcessPayment = async () => {
    if (paymentMethod === 'cash' && receivedAmount < finalTotal) {
      alert("Insufficient amount received!");
      return;
    }

    if (paymentMethod === 'credit') {
        if (!selectedCustomer) {
            alert("Credit payment requires a registered customer!");
            return;
        }
        if (receivedAmount > finalTotal) {
            alert("Deposit cannot be more than the total amount.");
            return;
        }
    }

    setIsProcessing(true);

    // For non-cash methods, assume full payment unless credit
    let finalReceived = 0;
    let finalChange = 0;

    if (paymentMethod === 'cash') {
        finalReceived = receivedAmount;
        finalChange = change;
    } else if (paymentMethod === 'credit') {
        finalReceived = receivedAmount; // Can be 0 or deposit
        finalChange = 0;
    } else {
        finalReceived = finalTotal;
        finalChange = 0;
    }

    try {
      const sale = await onProcessSale(
        cart, 
        finalTotal, 
        selectedCustomer?.id, 
        discountAmount, 
        rawSubtotal,
        paymentMethod,
        finalReceived,
        finalChange
      );

      // Notify Customer Display of Success
      if (settings?.customerDisplay?.enabled) {
        const channel = new BroadcastChannel('customer_display_channel');
        channel.postMessage({
          type: 'SUCCESS',
          total: finalTotal,
          change: finalChange,
          paymentMethod: paymentMethod,
          companyName: settings?.companyName
        });
        setTimeout(() => channel.close(), 100);
      }

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleNumPadClick = (val: string) => {
    if (val === 'C') {
      setReceivedAmountStr('');
    } else if (val === 'BS') {
      setReceivedAmountStr(prev => prev.slice(0, -1));
    } else if (val === '.') {
      if (!receivedAmountStr.includes('.')) {
        setReceivedAmountStr(prev => (prev === '' ? '0' : prev) + '.');
      }
    } else {
      setReceivedAmountStr(prev => {
        if (prev === '0') return val; // Prevent leading zeros like "01", "05"
        return prev + val;
      });
    }
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <div className="flex flex-col lg:flex-row h-full gap-6 relative">
      <div className="flex-1 flex flex-col min-w-0 h-full">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-slate-800">{t('pos.newOrder')}</h2>
          <div className="flex space-x-2">
             {settings?.customerDisplay?.enabled && (
               <button 
                 onClick={handleOpenCustomerDisplay}
                 className="flex items-center px-3 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors shadow-sm text-sm font-medium"
                 title="Open Customer Facing Display"
               >
                 <Monitor className="w-4 h-4 mr-2" />
                 <span className="hidden xl:inline">Customer Screen</span>
               </button>
             )}
             <button 
              onClick={() => setIsCustomerModalOpen(true)}
              className={`flex items-center px-4 py-2 rounded-lg shadow-sm transition-all duration-200 font-medium text-sm border ${
                selectedCustomer 
                  ? 'bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100' 
                  : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
              }`}
            >
              <User className="w-4 h-4 mr-2" />
              {selectedCustomer ? (
                <span className="flex items-center">
                  {selectedCustomer.name}
                  {customerLevel && (
                    <span className="ml-2 flex items-center bg-white/50 px-1.5 py-0.5 rounded text-[10px] border border-blue-200">
                      <Star className="w-3 h-3 mr-1 fill-current text-yellow-500" />
                      {customerLevel.name}
                    </span>
                  )}
                </span>
              ) : t('pos.selectCustomer')}
            </button>
            <button 
              onClick={() => setIsAiModalOpen(true)}
              className="flex items-center px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-lg shadow-md hover:shadow-lg transition-all duration-200 font-medium text-sm"
            >
              <Sparkles className="w-4 h-4 mr-2" />
              <span className="hidden md:inline">{t('pos.aiEstimate')}</span>
              <span className="md:hidden">AI</span>
            </button>
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 space-y-4">
          <form onSubmit={handleBarcodeScan} className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input
              type="text"
              placeholder={t('pos.scanPlaceholder')}
              className="w-full pl-10 pr-12 py-3 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 bg-slate-50 font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              autoFocus
            />
            <button type="submit" className="absolute right-2 top-1/2 transform -translate-y-1/2 p-1.5 bg-slate-200 rounded text-slate-600 hover:bg-slate-300">
               <ScanBarcode className="w-4 h-4" />
            </button>
          </form>

          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide -mx-1 px-1">
            <button
              onClick={() => setSelectedCategory('all')}
              className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors flex-shrink-0 ${
                selectedCategory === 'all' 
                  ? 'bg-slate-800 text-white' 
                  : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
              }`}
            >
              {t('pos.allItems')}
            </button>
            {Object.values(Category).map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors flex-shrink-0 ${
                  selectedCategory === cat 
                    ? 'bg-construction-orange text-white' 
                    : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto pr-1">
          {filteredProducts.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-slate-400">
              <Box className="w-12 h-12 mb-4 opacity-50" />
              <p>No products found.</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-20 md:pb-0">
              {filteredProducts.map((product) => {
                const hasVariants = product.variants && product.variants.length > 0;

                return (
                  <div 
                    key={product.id} 
                    onClick={() => !hasVariants && addToCart(product)}
                    className={`bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow flex flex-col ${!hasVariants ? 'cursor-pointer' : ''}`}
                  >
                    <div className="h-32 bg-slate-100 relative overflow-hidden">
                      {product.imageUrl ? (
                        <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                          <Box className="w-12 h-12" />
                        </div>
                      )}
                      <div className="absolute top-2 right-2 bg-white/90 backdrop-blur-sm px-2 py-1 rounded text-xs font-bold text-slate-700 shadow-sm">
                        {product.stock} {product.unit}
                      </div>
                      {product.sku && (
                         <div className="absolute bottom-2 left-2 bg-black/50 backdrop-blur-sm px-2 py-0.5 rounded text-[10px] text-white font-mono">
                           {product.sku}
                         </div>
                      )}
                    </div>
                    <div className="p-4 flex-1 flex flex-col">
                      <h3 className="font-bold text-slate-800 line-clamp-2 text-sm mb-1">{product.name}</h3>
                      <p className="text-xs text-slate-500 mb-3 line-clamp-1">{product.category}</p>

                      <div className="mt-auto">
                        <div className="flex justify-between items-center mb-3">
                          <span className="text-lg font-bold text-primary-600">${product.price.toFixed(2)}</span>
                        </div>

                        {hasVariants ? (
                          <div className="space-y-1">
                             <button
                                onClick={(e) => { e.stopPropagation(); addToCart(product); }}
                                className="w-full py-1.5 bg-slate-100 text-slate-700 rounded text-xs font-medium hover:bg-slate-200 transition-colors flex justify-between px-3"
                              >
                                <span>{product.unit}</span>
                                <span>${product.price}</span>
                              </button>
                             {product.variants!.map(v => (
                               <button
                                key={v.id}
                                onClick={(e) => { e.stopPropagation(); addToCart(product, 1, v.id); }}
                                className="w-full py-1.5 bg-orange-50 text-orange-700 rounded text-xs font-medium hover:bg-orange-100 transition-colors flex justify-between px-3"
                              >
                                <span>{v.name}</span>
                                <span>${v.price}</span>
                              </button>
                             ))}
                          </div>
                        ) : (
                          <button className="w-full py-2 bg-slate-800 text-white rounded-lg text-sm font-medium hover:bg-slate-900 transition-colors flex items-center justify-center">
                            <Plus className="w-4 h-4 mr-1" /> {t('common.add')}
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {cartItemCount > 0 && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="lg:hidden fixed bottom-4 right-4 left-4 bg-slate-900 text-white p-4 rounded-xl shadow-2xl flex justify-between items-center z-30"
        >
          <div className="flex items-center">
            <div className="bg-orange-500 rounded-full w-8 h-8 flex items-center justify-center font-bold text-sm mr-3">
              {cartItemCount}
            </div>
            <span className="font-bold">{t('pos.viewCart')}</span>
          </div>
          <span className="font-bold text-lg">${finalTotal.toFixed(2)}</span>
        </button>
      )}

      <div className={`
        fixed inset-y-0 right-0 z-40 w-full md:w-[400px] bg-white shadow-2xl transform transition-transform duration-300 ease-in-out lg:relative lg:translate-x-0 lg:shadow-none lg:w-[380px] lg:border-l lg:border-slate-200 flex flex-col
        ${isCartOpen ? 'translate-x-0' : 'translate-x-full'}
      `}>
        <div className="p-5 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
          <div className="flex items-center">
            <ShoppingCart className="w-5 h-5 text-slate-700 mr-2" />
            <h3 className="font-bold text-slate-800 text-lg">{t('pos.currentOrder')}</h3>
          </div>
          <button 
            onClick={() => setIsCartOpen(false)}
            className="lg:hidden p-2 text-slate-500 hover:bg-slate-200 rounded-full"
          >
            <X className="w-6 h-6" />
          </button>
          <div className="hidden lg:block bg-slate-200 text-slate-600 px-2 py-1 rounded text-xs font-bold">
            {cartItemCount} {t('common.items')}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-4">
              <ShoppingCart className="w-16 h-16 opacity-20" />
              <p className="text-sm font-medium">{t('pos.emptyCart')}</p>
              <p className="text-xs text-center max-w-[200px]">{t('pos.emptyCartDesc')}</p>
            </div>
          ) : (
            cart.map((item, index) => (
              <div key={`${item.id}-${item.selectedVariantId || 'main'}`} className="flex items-center bg-white p-3 rounded-lg border border-slate-100 shadow-sm animate-fade-in">
                <div className="flex-1 min-w-0">
                  <h4 className="font-bold text-slate-800 text-sm truncate">{item.name}</h4>
                  <div className="flex items-center text-xs text-slate-500 mt-1">
                    <span className="bg-slate-100 px-1.5 py-0.5 rounded mr-2">{item.sellUnit}</span>
                    <span>${item.sellPrice.toFixed(2)}</span>
                  </div>
                </div>

                <div className="flex items-center space-x-3 mx-3">
                  <button 
                    onClick={() => updateQuantity(index, -1)}
                    className="p-1 rounded bg-slate-100 hover:bg-slate-200 text-slate-600 transition-colors"
                  >
                    <Minus className="w-3 h-3" />
                  </button>
                  <span className="font-bold text-slate-800 w-6 text-center text-sm">{item.quantity}</span>
                  <button 
                    onClick={() => updateQuantity(index, 1)}
                    className="p-1 rounded bg-slate-100 hover:bg-slate-200 text-slate-600 transition-colors"
                  >
                    <Plus className="w-3 h-3" />
                  </button>
                </div>

                <div className="text-right min-w-[60px]">
                  <p className="font-bold text-slate-800 text-sm">${(item.sellPrice * item.quantity).toFixed(2)}</p>
                  <button 
                    onClick={() => removeFromCart(index)}
                    className="text-xs text-red-400 hover:text-red-600 mt-1"
                  >
                    {t('common.delete')}
                  </button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-200 space-y-3">
          {selectedCustomer && (
             <div className="flex justify-between items-center p-3 bg-blue-50 border border-blue-100 rounded-lg text-sm text-blue-900 mb-2">
                <div className="flex items-center">
                   <User className="w-4 h-4 mr-2 text-blue-600" />
                   <div>
                      <span className="font-bold block">{selectedCustomer.name}</span>
                      {customerLevel && (
                        <span className="text-xs text-blue-600 flex items-center">
                           <Star className="w-3 h-3 mr-1 fill-current" />
                           {customerLevel.name} ({customerLevel.discountPercentage}% Off)
                        </span>
                      )}
                   </div>
                </div>
                <button onClick={() => setSelectedCustomer(null)} className="text-blue-400 hover:text-blue-600">
                   <X className="w-4 h-4" />
                </button>
             </div>
          )}

          <div className="space-y-2 text-sm text-slate-600">
            <div className="flex justify-between">
              <span>{t('pos.subtotal')}</span>
              <span>${rawSubtotal.toFixed(2)}</span>
            </div>

            {discountAmount > 0 && (
               <div className="flex justify-between text-green-600 font-medium">
                 <span className="flex items-center"><Percent className="w-3 h-3 mr-1" /> Discount ({customerLevel?.discountPercentage}%)</span>
                 <span>-${discountAmount.toFixed(2)}</span>
               </div>
            )}

            {taxConfig?.enabled && (
              <div className="flex justify-between text-slate-500">
                <span>{t('pos.tax')} ({taxConfig.rate}%)</span>
                <span>${taxAmount.toFixed(2)}</span>
              </div>
            )}
          </div>

          <div className="flex justify-between items-end pt-3 border-t border-slate-200">
            <span className="text-slate-800 font-bold">{t('common.total')}</span>
            <span className="text-3xl font-bold text-slate-900">${finalTotal.toFixed(2)}</span>
          </div>

          <div className="grid grid-cols-2 gap-3 pt-2">
            <button 
              disabled={cart.length === 0}
              onClick={handleCheckoutClick}
              className="col-span-2 py-3 bg-slate-900 text-white rounded-xl font-bold text-lg hover:bg-slate-800 transition-colors shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
            >
              <Banknote className="w-5 h-5 mr-2" />
              {t('pos.payCash')}
            </button>
          </div>
        </div>
      </div>

      <AiAssistant 
        isOpen={isAiModalOpen} 
        onClose={() => setIsAiModalOpen(false)}
        inventory={products}
        onAddItemsToCart={handleAiItemsAdded}
      />

      {/* Customer Modal */}
      {isCustomerModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
           <div className="bg-white rounded-xl shadow-2xl w-full max-w-md max-h-[80vh] flex flex-col">
              <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
                 <h3 className="font-bold text-slate-800">{t('pos.selectCustomer')}</h3>
                 <button onClick={() => setIsCustomerModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                    <X className="w-5 h-5" />
                 </button>
              </div>
              <div className="p-4">
                 <div className="relative mb-4">
                    <Search className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                    <input
                       type="text"
                       placeholder={t('common.search')}
                       className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                       value={customerSearch}
                       onChange={e => setCustomerSearch(e.target.value)}
                       autoFocus
                    />
                 </div>
                 <div className="space-y-2 overflow-y-auto max-h-[400px]">
                    {filteredCustomers.map(cust => {
                       const level = customerLevels.find(l => l.id === cust.levelId);
                       return (
                          <button
                             key={cust.id}
                             onClick={() => {
                                setSelectedCustomer(cust);
                                setIsCustomerModalOpen(false);
                             }}
                             className="w-full flex items-center justify-between p-3 rounded-lg border border-slate-100 hover:bg-blue-50 hover:border-blue-200 transition-colors text-left group"
                          >
                             <div>
                                <div className="font-bold text-slate-800 group-hover:text-blue-700">{cust.name}</div>
                                <div className="text-xs text-slate-500">{cust.code} • {cust.phone}</div>
                             </div>
                             <div className="flex flex-col items-end">
                                {level && (
                                   <span 
                                      className="text-[10px] font-bold text-white px-2 py-0.5 rounded-full mb-1 shadow-sm"
                                      style={{ backgroundColor: level.color || '#94a3b8' }}
                                   >
                                      {level.name}
                                   </span>
                                )}
                                {cust.loyaltyPoints > 0 && (
                                   <span className="text-xs font-bold text-yellow-600 bg-yellow-50 px-2 py-0.5 rounded-full border border-yellow-100">
                                      {cust.loyaltyPoints} pts
                                   </span>
                                )}
                             </div>
                          </button>
                       );
                    })}
                    {filteredCustomers.length === 0 && (
                       <div className="text-center py-8 text-slate-400">
                          No customers found.
                       </div>
                    )}
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Checkout Modal */}
      {isCheckoutOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl flex flex-col md:flex-row overflow-hidden h-[80vh] md:h-[600px]">
            {/* Left: Payment Method Selection */}
            <div className="w-full md:w-1/3 bg-slate-50 border-r border-slate-200 p-6 flex flex-col">
              <h3 className="text-lg font-bold text-slate-800 mb-6">Payment Method</h3>
              <div className="space-y-3 flex-1 overflow-y-auto">
                <button
                  onClick={() => handlePaymentMethodChange('cash')}
                  className={`w-full flex items-center p-4 rounded-xl border-2 transition-all ${
                    paymentMethod === 'cash' 
                      ? 'border-primary-500 bg-primary-50 text-primary-700 shadow-md' 
                      : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'
                  }`}
                >
                  <Banknote className="w-6 h-6 mr-3" />
                  <span className="font-bold text-lg">Cash</span>
                </button>
                <button
                  onClick={() => handlePaymentMethodChange('qr')}
                  className={`w-full flex items-center p-4 rounded-xl border-2 transition-all ${
                    paymentMethod === 'qr' 
                      ? 'border-primary-500 bg-primary-50 text-primary-700 shadow-md' 
                      : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'
                  }`}
                >
                  <QrCode className="w-6 h-6 mr-3" />
                  <span className="font-bold text-lg">OnePay / QR</span>
                </button>
                <button
                  onClick={() => handlePaymentMethodChange('card')}
                  className={`w-full flex items-center p-4 rounded-xl border-2 transition-all ${
                    paymentMethod === 'card' 
                      ? 'border-primary-500 bg-primary-50 text-primary-700 shadow-md' 
                      : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'
                  }`}
                >
                  <CreditCard className="w-6 h-6 mr-3" />
                  <span className="font-bold text-lg">Card / Transfer</span>
                </button>
                <button
                  onClick={() => handlePaymentMethodChange('credit')}
                  className={`w-full flex items-center p-4 rounded-xl border-2 transition-all ${
                    paymentMethod === 'credit' 
                      ? 'border-orange-500 bg-orange-50 text-orange-700 shadow-md' 
                      : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'
                  } ${!selectedCustomer ? 'opacity-50 cursor-not-allowed' : ''}`}
                >
                  <FileText className="w-6 h-6 mr-3" />
                  <div className="text-left">
                     <span className="font-bold text-lg block">Credit / ຕິດໜີ້</span>
                     <span className="text-xs text-slate-500">Members Only</span>
                  </div>
                </button>
              </div>
              <div className="pt-6 border-t border-slate-200">
                <div className="flex justify-between items-center text-slate-600 mb-2">
                  <span>Total Due</span>
                  <span className="font-bold text-xl">${finalTotal.toFixed(2)}</span>
                </div>
              </div>
            </div>

            {/* Right: Payment Details & Numpad */}
            <div className="flex-1 p-6 flex flex-col relative">
              <button 
                onClick={() => setIsCheckoutOpen(false)} 
                className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"
              >
                <X className="w-6 h-6" />
              </button>

              <h3 className="text-xl font-bold text-slate-800 mb-6">
                {paymentMethod === 'cash' ? 'Cash Payment' : 
                 paymentMethod === 'qr' ? 'Scan QR Code' : 
                 paymentMethod === 'credit' ? 'Credit Sale (Pay Later)' :
                 'Card Payment'}
              </h3>

              {paymentMethod === 'cash' ? (
                <div className="flex-1 flex flex-col">
                  {/* Amount Input Display */}
                  <div className="bg-slate-100 p-4 rounded-xl mb-4 text-right border border-slate-200">
                    <p className="text-sm text-slate-500 mb-1">Amount Received</p>
                    <div className="text-4xl font-bold text-slate-800 tracking-tight">
                      {receivedAmountStr ? `$${receivedAmountStr}` : <span className="text-slate-300">$0.00</span>}
                    </div>
                  </div>

                  {/* Change Calculation */}
                  <div className="flex justify-between items-center mb-6 px-2">
                    <div>
                      <p className="text-sm text-slate-500">Change Due</p>
                      <p className={`text-2xl font-bold ${change > 0 ? 'text-green-600' : 'text-slate-400'}`}>
                        ${change.toFixed(2)}
                      </p>
                    </div>
                    {remainingCash > 0 && (
                      <div className="text-right">
                        <p className="text-sm text-slate-500">Remaining</p>
                        <p className="text-xl font-bold text-red-500">${remainingCash.toFixed(2)}</p>
                      </div>
                    )}
                  </div>

                  {/* Numpad & Quick Cash */}
                  <div className="flex gap-4 flex-1">
                    <div className="flex-1 grid grid-cols-3 gap-3">
                      {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'BS'].map((num) => (
                        <button
                          key={num}
                          onClick={() => handleNumPadClick(num.toString())}
                          className="bg-white border border-slate-200 rounded-lg text-xl font-semibold text-slate-700 hover:bg-slate-50 active:bg-slate-100 transition-colors shadow-sm flex items-center justify-center"
                        >
                          {num === 'BS' ? <ArrowLeft className="w-6 h-6" /> : num}
                        </button>
                      ))}
                    </div>
                    <div className="w-1/3 flex flex-col gap-3">
                      <button onClick={() => handleQuickCash(Math.ceil(finalTotal))} className="flex-1 bg-blue-50 text-blue-700 font-bold rounded-lg hover:bg-blue-100 border border-blue-100 transition-colors">Exact</button>
                      <button onClick={() => handleQuickCash(10)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$10</button>
                      <button onClick={() => handleQuickCash(20)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$20</button>
                      <button onClick={() => handleQuickCash(50)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$50</button>
                      <button onClick={() => handleQuickCash(100)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$100</button>
                    </div>
                  </div>
                </div>
              ) : paymentMethod === 'qr' ? (
                <div className="flex-1 flex flex-col items-center justify-center text-center">
                  <div className="bg-white p-4 rounded-xl border-2 border-slate-200 shadow-sm mb-4">
                    <img 
                      src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=Payment_OnePay_${finalTotal}`} 
                      alt="Payment QR" 
                      className="w-48 h-48 object-contain"
                    />
                  </div>
                  <p className="font-bold text-slate-800 text-lg">Scan to Pay ${finalTotal.toFixed(2)}</p>
                  <p className="text-slate-500 text-sm mt-2">Use OnePay or compatible banking app</p>
                </div>
              ) : paymentMethod === 'credit' ? (
                 <div className="flex-1 flex flex-col">
                    <div className="bg-orange-50 p-4 rounded-xl mb-4 border border-orange-100 flex justify-between items-center">
                       <div>
                          <p className="text-xs text-orange-700 font-bold uppercase mb-1">Customer</p>
                          <p className="font-bold text-slate-800">{selectedCustomer?.name}</p>
                       </div>
                       <User className="w-5 h-5 text-orange-400" />
                    </div>

                    <div className="bg-white p-4 rounded-xl mb-4 text-right border border-slate-200">
                       <p className="text-sm text-slate-500 mb-1">Initial Deposit / Pay Now</p>
                       <div className="text-4xl font-bold text-slate-800 tracking-tight">
                          ${receivedAmountStr || '0'}
                       </div>
                    </div>

                    <div className="flex justify-between items-center mb-6 px-2">
                       <div>
                          <p className="text-sm text-slate-500">Total Bill</p>
                          <p className="text-lg font-bold text-slate-800">${finalTotal.toFixed(2)}</p>
                       </div>
                       <div className="text-right">
                          <p className="text-sm text-slate-500">Remaining Debt</p>
                          <p className="text-xl font-bold text-red-600">${remainingDebt.toFixed(2)}</p>
                       </div>
                    </div>

                    {/* Numpad for Deposit */}
                    <div className="flex gap-4 flex-1">
                       <div className="flex-1 grid grid-cols-3 gap-3">
                          {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'BS'].map((num) => (
                             <button
                                key={num}
                                onClick={() => handleNumPadClick(num.toString())}
                                className="bg-white border border-slate-200 rounded-lg text-xl font-semibold text-slate-700 hover:bg-slate-50 active:bg-slate-100 transition-colors shadow-sm flex items-center justify-center"
                             >
                                {num === 'BS' ? <ArrowLeft className="w-6 h-6" /> : num}
                             </button>
                          ))}
                       </div>
                       <div className="w-1/3 flex flex-col gap-3">
                          <button onClick={() => setReceivedAmountStr('0')} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">No Deposit</button>
                          <button onClick={() => handleQuickCash(Math.ceil(finalTotal * 0.1))} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">10%</button>
                          <button onClick={() => handleQuickCash(Math.ceil(finalTotal * 0.5))} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">50%</button>
                       </div>
                    </div>
                 </div>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
                  <div className="w-24 h-24 bg-blue-50 rounded-full flex items-center justify-center text-blue-500 mb-2">
                    <CreditCard className="w-12 h-12" />
                  </div>
                  <h4 className="text-xl font-bold text-slate-800">Ready for Card Payment</h4>
                  <p className="text-slate-500 max-w-xs">Please insert or swipe card on the terminal. Ensure the amount <strong className="text-slate-800">${finalTotal.toFixed(2)}</strong> is correct.</p>
                </div>
              )}

              <button
                onClick={handleProcessPayment}
                disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < finalTotal) || (paymentMethod === 'credit' && receivedAmount > finalTotal)}
                className={`w-full py-4 mt-6 text-white rounded-xl font-bold text-xl disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg flex items-center justify-center ${
                   paymentMethod === 'credit' ? 'bg-orange-600 hover:bg-orange-700' : 'bg-slate-900 hover:bg-slate-800'
                }`}
              >
                {isProcessing ? (
                  <span className="flex items-center"><Sparkles className="w-5 h-5 animate-spin mr-2" /> Processing...</span>
                ) : (
                  <>
                    <CheckCircle className="w-6 h-6 mr-2" /> 
                    {paymentMethod === 'cash' && change > 0 
                      ? `Confirm & Return $${change.toFixed(2)}` 
                      : paymentMethod === 'credit' 
                        ? `Confirm Debt $${remainingDebt.toFixed(2)}`
                        : `Confirm Payment $${finalTotal.toFixed(2)}`}
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Receipt Modal */}
      {isReceiptOpen && lastSale && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm flex flex-col overflow-hidden">
            <div className="p-4 bg-slate-800 text-white flex justify-between items-center">
              <h3 className="font-bold flex items-center"><CheckCircle className="w-5 h-5 mr-2 text-green-400" /> Sale Completed</h3>
              <button onClick={() => setIsReceiptOpen(false)} className="text-slate-400 hover:text-white"><X className="w-5 h-5" /></button>
            </div>

            {/* Receipt Preview */}
            <div className="p-6 bg-slate-50 flex-1 overflow-y-auto max-h-[60vh]">
              <div className="bg-white p-4 shadow-sm border border-slate-200 text-xs font-mono text-slate-700">
                <div className="text-center mb-4">
                  <h2 className="text-lg font-bold text-slate-900 mb-1">{settings?.companyName || 'BuildMaster Store'}</h2>
                  <p>{settings?.address || '123 Main St'}</p>
                  <p>Tel: {settings?.phone || '012-345-6789'}</p>
                  <p className="mt-2 text-slate-500">#{lastSale.id}</p>
                  <p>{new Date(lastSale.date).toLocaleString()}</p>
                </div>

                <div className="border-b border-dashed border-slate-300 my-2"></div>

                <div className="space-y-1 mb-2">
                  {lastSale.items.map((item, i) => (
                    <div key={i} className="flex justify-between">
                      <span className="truncate w-32">{item.name}</span>
                      <span className="text-right">
                        {item.quantity} x {item.sellPrice.toFixed(2)}
                      </span>
                      <span className="font-bold text-right w-16">
                        {(item.quantity * item.sellPrice).toFixed(2)}
                      </span>
                    </div>
                  ))}
                </div>

                <div className="border-b border-dashed border-slate-300 my-2"></div>

                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span>Subtotal</span>
                    <span>${(lastSale.subtotal || lastSale.total).toFixed(2)}</span>
                  </div>
                  {lastSale.discountAmount ? (
                    <div className="flex justify-between text-green-600">
                      <span>Discount</span>
                      <span>-${lastSale.discountAmount.toFixed(2)}</span>
                    </div>
                  ) : null}
                  <div className="flex justify-between font-bold text-sm mt-1 pt-1 border-t border-slate-100">
                    <span>Total</span>
                    <span>${lastSale.total.toFixed(2)}</span>
                  </div>
                </div>

                <div className="border-b border-dashed border-slate-300 my-3"></div>

                <div className="space-y-1 text-slate-600">
                  <div className="flex justify-between">
                    <span className="capitalize">Paid via {lastSale.paymentMethod}</span>
                    <span>${(lastSale.amountReceived && lastSale.amountReceived > 0 ? lastSale.amountReceived : 0).toFixed(2)}</span>
                  </div>

                  {(lastSale.paymentStatus === 'unpaid' || lastSale.paymentStatus === 'partial') && (
                     <>
                        <div className="flex justify-between font-bold text-red-600 mt-1">
                           <span>Balance Due</span>
                           <span>${(lastSale.remainingAmount || 0).toFixed(2)}</span>
                        </div>
                     </>
                  )}

                  {lastSale.change !== undefined && lastSale.change > 0 && (
                    <div className="flex justify-between font-bold text-slate-900">
                      <span>Change</span>
                      <span>${lastSale.change.toFixed(2)}</span>
                    </div>
                  )}
                </div>

                <div className="mt-6 text-center text-slate-400 italic">
                  Thank you for shopping!
                </div>
              </div>
            </div>

            <div className="p-4 bg-white border-t border-slate-100 flex gap-3">
              <button 
                onClick={() => window.print()}
                className="flex-1 py-3 bg-white border border-slate-300 text-slate-700 rounded-lg font-bold hover:bg-slate-50 flex items-center justify-center transition-colors"
              >
                <Printer className="w-5 h-5 mr-2" /> Print
              </button>
              <button 
                onClick={() => setIsReceiptOpen(false)}
                className="flex-1 py-3 bg-slate-900 text-white rounded-lg font-bold hover:bg-slate-800 flex items-center justify-center transition-colors"
              >
                <Plus className="w-5 h-5 mr-2" /> New Order
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Promotion } from '../types';
import { 
  Plus, 
  Trash2, 
  Image as ImageIcon, 
  X, 
  Edit2, 
  Check, 
  Eye, 
  EyeOff,
  Calendar,
  Clock,
  Upload,
  AlertCircle
} from 'lucide-react';

interface PromotionsManagementProps {
  promotions: Promotion[];
  onAddPromotion: (promo: Promotion) => void;
  onUpdatePromotion: (promo: Promotion) => void;
  onDeletePromotion: (id: string) => void;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const PromotionsManagement: React.FC<PromotionsManagementProps> = ({ 
  promotions, 
  onAddPromotion, 
  onUpdatePromotion, 
  onDeletePromotion 
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Promotion>>({
    title: '',
    imageUrl: '',
    isActive: true,
    startDate: '',
    endDate: ''
  });

  const handleOpenModal = (promo?: Promotion) => {
    if (promo) {
      setEditingId(promo.id);
      setFormData(promo);
    } else {
      setEditingId(null);
      setFormData({
        title: '',
        imageUrl: '',
        isActive: true,
        startDate: '',
        endDate: ''
      });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.imageUrl) return;

    if (editingId) {
      onUpdatePromotion({ ...formData, id: editingId } as Promotion);
    } else {
      onAddPromotion({ ...formData, id: `promo-${Date.now()}` } as Promotion);
    }
    setIsModalOpen(false);
  };

  const handleToggleActive = (promo: Promotion) => {
    onUpdatePromotion({ ...promo, isActive: !promo.isActive });
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // 1. Check File Size
    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      // Reset input value to allow re-selecting the same file if needed
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    // 2. Check File Type (Optional extra safety)
    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    // 3. Convert to Base64
    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, imageUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const getStatusInfo = (promo: Promotion) => {
    const now = new Date();

    if (!promo.isActive) return { label: 'Inactive', color: 'bg-slate-100 text-slate-500', icon: EyeOff };

    if (promo.endDate) {
      const end = new Date(promo.endDate);
      end.setHours(23, 59, 59, 999); // End of the day
      if (now > end) return { label: 'Expired', color: 'bg-red-100 text-red-600', icon: Clock };
    }

    if (promo.startDate) {
      const start = new Date(promo.startDate);
      if (now < start) return { label: 'Scheduled', color: 'bg-blue-100 text-blue-600', icon: Calendar };
    }

    return { label: 'Active', color: 'bg-green-100 text-green-600', icon: Check };
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Promotions Management</h2>
          <p className="text-slate-500">Manage banners, schedule ads, and customer display content.</p>
        </div>
        <button 
          onClick={() => handleOpenModal()}
          className="flex items-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium shadow-sm"
        >
          <Plus className="w-4 h-4 mr-2" />
          Add Promotion
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 overflow-y-auto pb-4">
        {promotions.length === 0 ? (
          <div className="col-span-full flex flex-col items-center justify-center p-12 bg-white rounded-xl border border-dashed border-slate-300 text-slate-400">
            <ImageIcon className="w-12 h-12 mb-4 opacity-50" />
            <p>No promotions active.</p>
            <button 
              onClick={() => handleOpenModal()}
              className="mt-4 text-primary-600 hover:underline font-medium"
            >
              Create your first promotion
            </button>
          </div>
        ) : (
          promotions.map((promo) => {
            const status = getStatusInfo(promo);
            const StatusIcon = status.icon;

            return (
              <div key={promo.id} className={`group bg-white rounded-xl shadow-sm border overflow-hidden flex flex-col transition-all ${promo.isActive ? 'border-slate-200' : 'border-slate-100 opacity-75'}`}>
                <div className="relative aspect-video bg-slate-100 overflow-hidden">
                  <img 
                    src={promo.imageUrl} 
                    alt={promo.title} 
                    className="w-full h-full object-cover transition-transform group-hover:scale-105" 
                  />
                  <div className="absolute top-2 left-2">
                     <span className={`flex items-center px-2 py-1 rounded-md text-xs font-bold shadow-sm backdrop-blur-md ${status.color.includes('bg-') ? status.color.replace('bg-', 'bg-white/90 text-') : 'bg-white/90 text-slate-600'}`}>
                        <StatusIcon className="w-3 h-3 mr-1" /> {status.label}
                     </span>
                  </div>

                  <div className="absolute top-2 right-2 flex space-x-2 opacity-0 group-hover:opacity-100 transition-opacity">
                     <button 
                        onClick={() => handleOpenModal(promo)}
                        className="p-2 bg-white text-slate-600 rounded-full hover:text-primary-600 shadow-sm"
                     >
                        <Edit2 className="w-4 h-4" />
                     </button>
                     <button 
                        onClick={() => {
                           if(confirm('Delete this promotion?')) onDeletePromotion(promo.id);
                        }}
                        className="p-2 bg-white text-slate-600 rounded-full hover:text-red-600 shadow-sm"
                     >
                        <Trash2 className="w-4 h-4" />
                     </button>
                  </div>
                </div>

                <div className="p-4 flex items-center justify-between">
                  <div className="flex-1 min-w-0 pr-4">
                    <h3 className="font-bold text-slate-800 truncate" title={promo.title}>{promo.title || 'Untitled Promotion'}</h3>
                    {promo.startDate || promo.endDate ? (
                       <div className="text-xs text-slate-500 mt-1 flex items-center">
                          <Calendar className="w-3 h-3 mr-1" />
                          {promo.startDate ? new Date(promo.startDate).toLocaleDateString() : 'Now'} 
                          {' - '} 
                          {promo.endDate ? new Date(promo.endDate).toLocaleDateString() : 'Forever'}
                       </div>
                    ) : (
                       <p className="text-xs text-slate-400 mt-1">Always Active</p>
                    )}
                  </div>
                  <button
                    onClick={() => handleToggleActive(promo)}
                    className={`relative inline-flex items-center h-6 rounded-full w-11 transition-colors focus:outline-none shrink-0 ${promo.isActive ? 'bg-green-500' : 'bg-slate-300'}`}
                  >
                    <span className={`inline-block w-4 h-4 transform bg-white rounded-full transition-transform ${promo.isActive ? 'translate-x-6' : 'translate-x-1'}`} />
                  </button>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-md animate-fade-in">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <h3 className="text-xl font-bold text-slate-800">
                {editingId ? 'Edit Promotion' : 'Add New Promotion'}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Title (Optional)</label>
                <input
                  type="text"
                  value={formData.title}
                  onChange={e => setFormData({...formData, title: e.target.value})}
                  className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                  placeholder="e.g. Summer Sale 50% Off"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-2">Promotion Image *</label>

                {/* Upload Area */}
                {!formData.imageUrl ? (
                  <div 
                    onClick={() => fileInputRef.current?.click()}
                    className="w-full h-40 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 flex flex-col items-center justify-center cursor-pointer hover:bg-slate-100 hover:border-primary-400 transition-colors"
                  >
                    <div className="p-3 bg-white rounded-full shadow-sm mb-3">
                      <Upload className="w-6 h-6 text-primary-600" />
                    </div>
                    <span className="text-sm font-medium text-slate-700">Click to upload image</span>
                    <span className="text-xs text-slate-400 mt-1">Max file size: {MAX_FILE_SIZE_MB}MB</span>
                  </div>
                ) : (
                  <div className="relative rounded-xl overflow-hidden border border-slate-200 bg-slate-50 aspect-video group">
                    <img 
                      src={formData.imageUrl} 
                      alt="Preview" 
                      className="w-full h-full object-contain"
                    />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                       <button
                          type="button"
                          onClick={handleRemoveImage}
                          className="bg-white text-red-600 px-4 py-2 rounded-lg font-bold shadow-sm flex items-center hover:bg-red-50"
                       >
                          <Trash2 className="w-4 h-4 mr-2" /> Remove
                       </button>
                    </div>
                  </div>
                )}

                {/* Hidden File Input */}
                <input 
                  type="file"
                  ref={fileInputRef}
                  accept="image/*"
                  onChange={handleImageUpload}
                  className="hidden"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Start Date</label>
                    <input
                      type="date"
                      value={formData.startDate || ''}
                      onChange={e => setFormData({...formData, startDate: e.target.value})}
                      className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                 </div>
                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">End Date</label>
                    <input
                      type="date"
                      value={formData.endDate || ''}
                      onChange={e => setFormData({...formData, endDate: e.target.value})}
                      className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                 </div>
              </div>

              <div className="flex items-center space-x-2 pt-2">
                <input 
                  type="checkbox" 
                  id="isActive"
                  checked={formData.isActive}
                  onChange={e => setFormData({...formData, isActive: e.target.checked})}
                  className="w-4 h-4 text-primary-600 rounded border-slate-300 focus:ring-primary-500"
                />
                <label htmlFor="isActive" className="text-sm font-medium text-slate-700">Set as Active</label>
              </div>

              <div className="flex justify-end pt-4 space-x-3">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={!formData.imageUrl}
                  className="px-6 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm flex items-center disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <Check className="w-4 h-4 mr-2" />
                  Save Promotion
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, UnitDefinition, CategoryItem, Warehouse, InventoryAnalysisResult, Sale, Branch } from '../types';
import { Search, Plus, Edit2, Trash2, X, Check, Layers, Box, ArrowRight, ArrowLeftRight, RefreshCw, Info, Building2, AlertTriangle, Bell, Sparkles, Loader2, TrendingUp, AlertCircle, PackagePlus, Scale, DollarSign, Store, ChevronLeft, ChevronRight, ShoppingBag, Image as ImageIcon, Upload } from 'lucide-react';
import { analyzeInventory } from '../services/geminiService';
import { useGlobal } from '../context/GlobalContext';

interface InventoryProps {
  products: Product[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  warehouses?: Warehouse[];
  sales: Sale[];
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onAddProduct: (product: Product) => void;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const Inventory: React.FC<InventoryProps> = ({ products, units, categories, warehouses = [], sales, onUpdateProduct, onDeleteProduct, onAddProduct }) => {
  const { branches, settings, t } = useGlobal();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = settings.defaultItemsPerPage || 10;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'general' | 'physical' | 'pricing' | 'variants'>('general');
  const [editingId, setEditingId] = useState<string | null>(null);

  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiResult, setAiResult] = useState<InventoryAnalysisResult | null>(null);
  const [activeAiTab, setActiveAiTab] = useState<'reorder' | 'new' | 'bundles'>('reorder');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    sku: '',
    barcode: '',
    category: '',
    price: 0,
    stock: 0,
    minStock: 20,
    unit: '',
    physical: { weight: 0, width: 0, height: 0, depth: 0 },
    branchPrices: [],
    imageUrl: ''
  });

  const [variants, setVariants] = useState<Partial<ProductVariant>[]>([]);

  const getFlattenedCategories = () => {
    const options: { id: string; name: string; level: number }[] = [];
    const buildOptions = (parentId: string | null, level: number) => {
      const children = categories.filter(c => c.parentId === parentId);
      children.forEach(c => {
        options.push({ id: c.id, name: c.name, level });
        buildOptions(c.id, level + 1);
      });
    };
    buildOptions(null, 0);
    return options;
  };

  const categoryOptions = getFlattenedCategories();

  const getCategoryName = (idOrName: string) => {
    const cat = categories.find(c => c.id === idOrName);
    return cat ? cat.name : idOrName; 
  };

  const filteredProducts = products.filter(p => {
    const searchLower = searchTerm.toLowerCase();
    const matchesSearch = 
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) || 
      p.barcode?.includes(searchLower) ||
      (p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      ));

    const pCatName = getCategoryName(p.category);
    const filterCatName = filterCategory === 'all' ? 'all' : getCategoryName(filterCategory);
    const matchesCategory = filterCategory === 'all' || p.category === filterCategory || pCatName === filterCatName;

    return matchesSearch && matchesCategory;
  });

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory]);

  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedProducts = filteredProducts.slice(startIndex, startIndex + itemsPerPage);

  const unitsByCategory = units.reduce((acc, unit) => {
    if (!acc[unit.category]) acc[unit.category] = [];
    acc[unit.category].push(unit);
    return acc;
  }, {} as Record<string, UnitDefinition[]>);

  const handleOpenAddModal = () => {
    setEditingId(null);
    setActiveTab('general');
    setFormData({
      name: '',
      sku: '',
      barcode: '',
      category: categoryOptions[0]?.id || '',
      price: 0,
      stock: 0,
      minStock: 20,
      unit: units[0]?.symbol || 'pc',
      physical: { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: [],
      imageUrl: ''
    });
    setVariants([]);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (product: Product) => {
    setEditingId(product.id);
    setActiveTab('general');
    setFormData({
      name: product.name,
      sku: product.sku,
      barcode: product.barcode,
      category: product.category,
      price: product.price,
      stock: product.stock,
      minStock: product.minStock || 20,
      unit: product.unit,
      physical: product.physical || { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: product.branchPrices || [],
      imageUrl: product.imageUrl || ''
    });
    setVariants(product.variants ? product.variants.map(v => ({...v})) : []);
    setIsModalOpen(true);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, imageUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  useEffect(() => {
    if (isAiModalOpen && !aiResult && !aiLoading) {
      const performAnalysis = async () => {
        setAiLoading(true);
        const result = await analyzeInventory(products, sales);
        setAiResult(result);
        setAiLoading(false);
      };
      performAnalysis();
    }
  }, [isAiModalOpen, products, sales, aiResult, aiLoading]);

  const handleOpenAiInsights = () => setIsAiModalOpen(true);

  const handleAddSuggestedProduct = (suggestion: any) => {
    setIsAiModalOpen(false);
    setEditingId(null);
    setActiveTab('general');

    const matchedCat = categories.find(c => c.name.toLowerCase().includes(suggestion.categoryName?.toLowerCase() || ''))?.id || '';
    const unitSearch = suggestion.suggestedUnit?.toLowerCase();
    let matchedUnit = units.find(u => u.symbol.toLowerCase() === unitSearch || u.name.toLowerCase() === unitSearch)?.symbol;
    if (!matchedUnit && unitSearch === 'set') matchedUnit = 'set'; 
    if (!matchedUnit) matchedUnit = 'pc';

    let productName = suggestion.name || suggestion.bundleName;
    if (suggestion.components && Array.isArray(suggestion.components) && suggestion.components.length > 0) {
       productName = `${productName} (Includes: ${suggestion.components.join(', ')})`;
    }

    setFormData({
      name: productName,
      sku: '',
      barcode: '',
      category: matchedCat,
      price: suggestion.estimatedPrice,
      stock: 0,
      minStock: 20,
      unit: matchedUnit,
      physical: { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: [],
      imageUrl: ''
    });
    setVariants([]);
    setIsModalOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const isNum = ['price', 'stock', 'minStock'].includes(name);

    setFormData(prev => ({
      ...prev,
      [name]: isNum ? (parseFloat(value) || 0) : value
    }));

    if (name === 'price') {
      const newMainPrice = parseFloat(value) || 0;
      setVariants(prev => prev.map(v => {
         const factor = v.conversionFactor || 1;
         return { ...v, price: factor !== 0 ? newMainPrice / factor : 0 };
      }));
    }
  };

  const handlePhysicalChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev,
      physical: {
        ...prev.physical,
        [field]: parseFloat(value) || 0
      }
    }));
  };

  const handleBranchPriceChange = (branchId: string, priceStr: string) => {
    const price = parseFloat(priceStr);
    setFormData(prev => {
      const currentPrices = prev.branchPrices ? [...prev.branchPrices] : [];
      const index = currentPrices.findIndex(bp => bp.branchId === branchId);

      if (index > -1) {
        if (!priceStr) {
           currentPrices.splice(index, 1);
        } else {
           currentPrices[index].price = price;
        }
      } else if (priceStr) {
        currentPrices.push({ branchId, price });
      }
      return { ...prev, branchPrices: currentPrices };
    });
  };

  const generateVariantCodes = (index: number) => {
    const suffix = (index + 1).toString().padStart(3, '0');
    const skuBase = formData.sku || 'SKU';
    return { code: `${skuBase}-${suffix}`, barcode: formData.barcode ? `${formData.barcode}${suffix}` : '' };
  };

  const handleAddVariant = () => {
    const { code, barcode } = generateVariantCodes(variants.length);
    setVariants(prev => [...prev, {
      id: `v-${Date.now()}`,
      name: '', 
      code,
      barcode,
      conversionFactor: 1, 
      price: formData.price
    }]);
  };

  const handleRemoveVariant = (index: number) => setVariants(prev => prev.filter((_, i) => i !== index));

  const handleVariantChange = (index: number, field: keyof ProductVariant, value: any) => {
    setVariants(prev => {
      const newVariants = [...prev];
      let updatedVariant = { ...newVariants[index], [field]: value };

      if (field === 'name') {
        const mainUnitDef = units.find(u => u.symbol === formData.unit);
        const variantUnitDef = units.find(u => u.symbol === value);
        if (mainUnitDef && variantUnitDef && mainUnitDef.category === variantUnitDef.category) {
          const factor = mainUnitDef.baseFactor / variantUnitDef.baseFactor;
          updatedVariant.conversionFactor = factor;
          updatedVariant.price = (formData.price || 0) / factor;
        }
      }
      if (field === 'price' || field === 'conversionFactor') {
        updatedVariant[field] = parseFloat(value) || 0;
      }
      newVariants[index] = updatedVariant;
      return newVariants;
    });
  };

  const handleVariantRelationChange = (index: number, ratio: number, mode: 'sub' | 'bundle') => {
    const factor = mode === 'sub' ? ratio : (1 / ratio);
    setVariants(prev => {
      const newVariants = [...prev];
      newVariants[index] = { 
        ...newVariants[index], 
        conversionFactor: factor,
        price: factor !== 0 ? ((formData.price || 0) / factor) : 0
      };
      return newVariants;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.unit) {
      const productData: Product = {
        id: editingId || `P-${Date.now()}`,
        name: formData.name!,
        category: formData.category || 'Uncategorized',
        price: formData.price || 0,
        stock: formData.stock || 0,
        minStock: formData.minStock || 20,
        unit: formData.unit!,
        sku: formData.sku || '',
        barcode: formData.barcode || '',
        physical: formData.physical,
        branchPrices: formData.branchPrices,
        variants: variants.length > 0 ? variants as ProductVariant[] : undefined,
        warehouseInventory: editingId 
          ? products.find(p => p.id === editingId)?.warehouseInventory 
          : [{ warehouseId: 'wh1', quantity: formData.stock || 0 }],
        imageUrl: formData.imageUrl
      };

      if (editingId) onUpdateProduct(productData);
      else onAddProduct(productData);
      setIsModalOpen(false);
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col relative">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">{t('inventory.title')}</h2>
          <p className="text-slate-500">{t('inventory.subtitle')}</p>
        </div>
        <div className="flex space-x-2">
          <button 
            onClick={handleOpenAiInsights}
            className="flex items-center justify-center px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-lg hover:shadow-lg transition-all font-medium shadow-sm"
          >
            <Sparkles className="w-4 h-4 mr-2" />
            {t('inventory.aiInsights')}
          </button>
          <button 
            onClick={handleOpenAddModal}
            className="flex items-center justify-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium shadow-sm"
          >
            <Plus className="w-4 h-4 mr-2" />
            {t('inventory.addProduct')}
          </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
          <input
            type="text"
            placeholder={t('inventory.searchPlaceholder')}
            className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <select
          value={filterCategory}
          onChange={(e) => setFilterCategory(e.target.value)}
          className="px-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 bg-white"
        >
          <option value="all">{t('inventory.allCategories')}</option>
          {categoryOptions.map(cat => (
             <option key={cat.id} value={cat.id}>
                {'\u00A0'.repeat(cat.level * 3)}{cat.name}
             </option>
          ))}
        </select>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="overflow-x-auto flex-1">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 sticky top-0 z-10">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">{t('inventory.productName')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">{t('inventory.sku')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">{t('inventory.category')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-right">{t('inventory.price')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-right">{t('inventory.stock')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-center">{t('common.actions')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {paginatedProducts.map((product) => {
                const isLowStock = product.stock < (product.minStock || 20);
                return (
                  <tr key={product.id} className={`hover:bg-slate-50 transition-colors group ${isLowStock ? 'bg-red-50 border-l-4 border-red-500' : ''}`}>
                    <td className="px-6 py-4">
                      <div className="flex items-center space-x-3">
                        {product.imageUrl && (
                          <div className="w-10 h-10 rounded-lg overflow-hidden border border-slate-200 bg-white shrink-0">
                            <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                          </div>
                        )}
                        <div>
                          <div className="font-medium text-slate-800">{product.name}</div>
                          <div className="text-xs text-slate-400 mt-0.5">ID: {product.id}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="mb-2">
                         <div className="flex items-center text-xs">
                           <span className="w-10 text-slate-400 font-semibold uppercase">{product.unit}</span>
                           <span className="font-mono bg-slate-100 px-1.5 rounded text-slate-600 mr-2">{product.sku}</span>
                           <span className="font-mono text-slate-500">{product.barcode}</span>
                         </div>
                      </div>
                      {product.variants?.map((v) => (
                        <div key={v.id} className="flex items-center text-xs pl-2 border-l-2 border-construction-orange/30 mb-1">
                           <span className="w-12 text-construction-orange font-semibold uppercase truncate" title={v.name}>{v.name}</span>
                           <span className="font-mono bg-orange-50 px-1.5 rounded text-orange-700 mr-2">{v.code}</span>
                           <span className="font-mono text-orange-600">{v.barcode}</span>
                         </div>
                      ))}
                    </td>
                    <td className="px-6 py-4">
                      <span className="px-2 py-1 text-xs font-medium bg-slate-100 text-slate-600 rounded-full">
                        {getCategoryName(product.category)}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right font-medium text-slate-700">
                       <div className="text-sm">${product.price.toFixed(2)} <span className="text-slate-400 text-xs">/{product.unit}</span></div>
                       {product.branchPrices && product.branchPrices.length > 0 && (
                         <div className="text-[10px] text-blue-600 mt-1 flex items-center justify-end">
                           <Store className="w-3 h-3 mr-1" />
                           Multi-price
                         </div>
                       )}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex flex-col items-end">
                        <div className={`font-bold flex items-center justify-end ${isLowStock ? 'text-red-600' : 'text-slate-700'}`}>
                          {isLowStock && (
                            <div className="flex items-center mr-2 bg-red-100 text-red-700 px-1.5 py-0.5 rounded text-[10px] uppercase font-bold tracking-wide shadow-sm">
                              <AlertTriangle className="w-3 h-3 mr-1" />
                              Low
                            </div>
                          )}
                          {product.stock} <span className="text-xs font-normal text-slate-500 ml-1">{product.unit}s</span>
                        </div>
                        <span className="text-[10px] text-slate-400">Min: {product.minStock || 20}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex items-center justify-center space-x-2 opacity-50 group-hover:opacity-100 transition-opacity">
                        <button 
                          onClick={() => handleOpenEditModal(product)}
                          className="p-1.5 text-slate-500 hover:text-primary-600 hover:bg-primary-50 rounded transition-colors"
                        >
                          <Edit2 className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => onDeleteProduct(product.id)}
                          className="p-1.5 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {paginatedProducts.length === 0 && (
                <tr>
                  <td colSpan={6} className="text-center py-8 text-slate-400">
                    No products found matching your filters.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {filteredProducts.length > 0 && (
          <div className="p-4 border-t border-slate-200 bg-slate-50 flex items-center justify-between">
            <div className="text-sm text-slate-500">
              Showing <span className="font-medium">{startIndex + 1}</span> to <span className="font-medium">{Math.min(startIndex + itemsPerPage, filteredProducts.length)}</span> of <span className="font-medium">{filteredProducts.length}</span> results
            </div>
            <div className="flex items-center space-x-2">
              <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="p-2 border border-slate-300 rounded-lg hover:bg-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronLeft className="w-4 h-4 text-slate-600" />
              </button>
              <div className="flex items-center space-x-1">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  let p = i + 1;
                  if (totalPages > 5 && currentPage > 3) {
                     p = currentPage - 2 + i;
                  }
                  if (p > totalPages) return null;

                  return (
                    <button
                      key={p}
                      onClick={() => setCurrentPage(p)}
                      className={`w-8 h-8 rounded-lg text-sm font-medium transition-colors ${
                        currentPage === p 
                          ? 'bg-construction-orange text-white' 
                          : 'text-slate-600 hover:bg-slate-200'
                      }`}
                    >
                      {p}
                    </button>
                  );
                })}
              </div>
              <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="p-2 border border-slate-300 rounded-lg hover:bg-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronRight className="w-4 h-4 text-slate-600" />
              </button>
            </div>
          </div>
        )}
      </div>

      {isAiModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          {/* AI Modal Content ... (Same as before) */}
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[85vh] flex flex-col overflow-hidden animate-fade-in">
            <div className="bg-gradient-to-r from-slate-900 to-slate-800 p-6 flex items-center justify-between shrink-0">
              <div className="flex items-center space-x-3">
                <div className="p-2 bg-gradient-to-br from-purple-500 to-indigo-500 rounded-lg shadow-lg">
                  <Sparkles className="w-6 h-6 text-white" />
                </div>
                <div>
                  <h3 className="text-xl font-bold text-white">AI Inventory Intelligence</h3>
                  <p className="text-slate-400 text-xs mt-0.5">Powered by Gemini AI Analysis</p>
                </div>
              </div>
              <button 
                onClick={() => setIsAiModalOpen(false)}
                className="text-slate-400 hover:text-white transition-colors p-1 rounded-full hover:bg-white/10"
              >
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="flex-1 overflow-hidden flex flex-col bg-slate-50 relative">
              {aiLoading ? (
                <div className="flex-1 flex flex-col items-center justify-center p-12">
                  <div className="relative">
                    <div className="absolute inset-0 bg-purple-500 blur-xl opacity-20 rounded-full animate-pulse"></div>
                    <Loader2 className="w-16 h-16 text-purple-600 animate-spin relative z-10" />
                  </div>
                  <h4 className="mt-6 text-lg font-semibold text-slate-700">Analyzing Sales & Stock Patterns...</h4>
                  <p className="text-slate-500 text-sm mt-2 max-w-md text-center">
                    Reviewing inventory levels, sales velocity, and historical trends to generate actionable insights.
                  </p>
                </div>
              ) : !aiResult ? (
                <div className="flex-1 flex flex-col items-center justify-center p-12 text-center">
                  <AlertTriangle className="w-12 h-12 text-slate-300 mb-4" />
                  <p className="text-slate-500">Analysis could not be generated. Please try again later.</p>
                </div>
              ) : (
                <div className="flex flex-col h-full">
                  <div className="flex border-b border-slate-200 bg-white shrink-0">
                    <button
                      onClick={() => setActiveAiTab('reorder')}
                      className={`flex-1 py-4 text-sm font-medium flex items-center justify-center transition-all ${
                        activeAiTab === 'reorder' 
                          ? 'border-b-2 border-red-500 text-red-600 bg-red-50/50' 
                          : 'text-slate-500 hover:bg-slate-50'
                      }`}
                    >
                      <AlertCircle className="w-4 h-4 mr-2" />
                      Restock Alerts ({aiResult.reorders.length})
                    </button>
                    <button
                      onClick={() => setActiveAiTab('new')}
                      className={`flex-1 py-4 text-sm font-medium flex items-center justify-center transition-all ${
                        activeAiTab === 'new' 
                          ? 'border-b-2 border-blue-500 text-blue-600 bg-blue-50/50' 
                          : 'text-slate-500 hover:bg-slate-50'
                      }`}
                    >
                      <TrendingUp className="w-4 h-4 mr-2" />
                      New Product Ideas ({aiResult.newProducts.length})
                    </button>
                    <button
                      onClick={() => setActiveAiTab('bundles')}
                      className={`flex-1 py-4 text-sm font-medium flex items-center justify-center transition-all ${
                        activeAiTab === 'bundles' 
                          ? 'border-b-2 border-purple-500 text-purple-600 bg-purple-50/50' 
                          : 'text-slate-500 hover:bg-slate-50'
                      }`}
                    >
                      <Layers className="w-4 h-4 mr-2" />
                      Smart Bundles ({aiResult.bundles.length})
                    </button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-6">

                    {activeAiTab === 'reorder' && (
                      <div className="space-y-4 animate-fade-in">
                        {aiResult.reorders.length === 0 ? (
                          <div className="text-center py-10 text-slate-500 bg-white rounded-xl border border-slate-200">
                            <Check className="w-12 h-12 text-green-500 mx-auto mb-3" />
                            <p className="font-medium">Inventory looks healthy!</p>
                            <p className="text-sm text-slate-400">No critical stock shortages detected.</p>
                          </div>
                        ) : (
                          <div className="grid grid-cols-1 gap-3">
                            {aiResult.reorders.map((item, idx) => (
                              <div key={idx} className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-4">
                                <div className="flex items-start space-x-3">
                                  <div className={`p-2 rounded-lg mt-1 ${item.priority === 'High' ? 'bg-red-100 text-red-600' : 'bg-orange-100 text-orange-600'}`}>
                                    <AlertTriangle className="w-5 h-5" />
                                  </div>
                                  <div>
                                    <div className="flex items-center">
                                      <h4 className="font-bold text-slate-800">{item.productName}</h4>
                                      <span className={`ml-2 text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wide ${
                                        item.priority === 'High' ? 'bg-red-100 text-red-700' : 'bg-orange-100 text-orange-700'
                                      }`}>
                                        {item.priority} Priority
                                      </span>
                                    </div>
                                    <p className="text-sm text-slate-600 mt-1">{item.reasoning}</p>
                                    <div className="flex items-center mt-2 text-xs font-mono text-slate-500 bg-slate-50 px-2 py-1 rounded w-fit">
                                      <span>Current: {item.currentStock}</span>
                                      <ArrowRight className="w-3 h-3 mx-2 text-slate-400" />
                                      <span className="font-bold text-slate-800">Suggested Order: +{item.suggestedReorderQty}</span>
                                    </div>
                                  </div>
                                </div>
                                <button className="shrink-0 px-4 py-2 bg-slate-800 text-white rounded-lg text-sm font-medium hover:bg-slate-900 transition-colors">
                                  Create PO
                                </button>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    )}

                    {activeAiTab === 'new' && (
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                        {aiResult.newProducts.map((item, idx) => (
                          <div key={idx} className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow flex flex-col h-full">
                            <div className="flex items-start justify-between mb-2">
                              <div className="p-2 bg-blue-50 text-blue-600 rounded-lg">
                                <PackagePlus className="w-5 h-5" />
                              </div>
                              <span className="bg-slate-100 text-slate-600 text-xs px-2 py-1 rounded font-medium">
                                {item.categoryName}
                              </span>
                            </div>
                            <h4 className="font-bold text-slate-800 text-lg mb-1">{item.name}</h4>
                            <p className="text-sm text-slate-500 mb-4 flex-1">{item.reasoning}</p>

                            <div className="mt-auto pt-4 border-t border-slate-100 flex items-center justify-between">
                              <div className="text-sm font-bold text-slate-700">
                                Est. ${item.estimatedPrice} <span className="text-xs font-normal text-slate-400">/ {item.suggestedUnit}</span>
                              </div>
                              <button 
                                onClick={() => handleAddSuggestedProduct(item)}
                                className="px-3 py-1.5 bg-blue-600 text-white text-xs font-bold uppercase tracking-wide rounded-lg hover:bg-blue-700 transition-colors"
                              >
                                Create Product
                              </button>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}

                    {activeAiTab === 'bundles' && (
                      <div className="space-y-4 animate-fade-in">
                        {aiResult.bundles.map((bundle, idx) => (
                          <div key={idx} className="bg-gradient-to-br from-white to-purple-50 p-5 rounded-xl border border-purple-100 shadow-sm">
                            <div className="flex flex-col md:flex-row gap-6">
                              <div className="flex-1">
                                <div className="flex items-center mb-2">
                                  <div className="p-1.5 bg-purple-100 text-purple-600 rounded-md mr-2">
                                    <ShoppingBag className="w-4 h-4" />
                                  </div>
                                  <h4 className="font-bold text-purple-900 text-lg">{bundle.bundleName}</h4>
                                </div>
                                <p className="text-sm text-purple-800/70 mb-3 italic">"{bundle.reasoning}"</p>
                                <div className="flex flex-wrap gap-2 mb-3">
                                  {bundle.components.map((comp, cIdx) => (
                                    <span key={cIdx} className="bg-white border border-purple-200 text-purple-700 px-2 py-1 rounded text-xs font-medium">
                                      {comp}
                                    </span>
                                  ))}
                                </div>
                                <div className="text-xs text-slate-500">
                                  <span className="font-semibold">Target:</span> {bundle.targetAudience}
                                </div>
                              </div>
                              <div className="flex flex-col justify-center items-end border-l border-purple-200 pl-6 border-dashed">
                                <div className="text-2xl font-bold text-slate-800 mb-1">${bundle.estimatedPrice}</div>
                                <div className="text-xs text-slate-400 mb-3">Target Price</div>
                                <button 
                                  onClick={() => handleAddSuggestedProduct(bundle)}
                                  className="px-4 py-2 bg-purple-600 text-white text-sm font-bold rounded-lg hover:bg-purple-700 transition-colors shadow-sm whitespace-nowrap"
                                >
                                  Create Bundle
                                </button>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}

                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
              <h3 className="text-xl font-bold text-slate-800">
                {editingId ? t('common.edit') : t('common.add')} Product
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="flex border-b border-slate-200 bg-white">
               {[
                 { id: 'general', label: 'General Info', icon: Box },
                 { id: 'physical', label: 'Physical & Units', icon: Scale },
                 { id: 'pricing', label: 'Pricing & Branches', icon: DollarSign },
                 { id: 'variants', label: 'Variants', icon: Layers },
               ].map(tab => {
                 const Icon = tab.icon;
                 return (
                   <button
                     key={tab.id}
                     onClick={() => setActiveTab(tab.id as any)}
                     className={`flex items-center px-6 py-3 text-sm font-medium transition-colors ${
                       activeTab === tab.id 
                         ? 'border-b-2 border-construction-orange text-construction-orange bg-orange-50/50' 
                         : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'
                     }`}
                   >
                     <Icon className="w-4 h-4 mr-2" />
                     {tab.label}
                   </button>
                 );
               })}
            </div>

            <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 bg-slate-50/50">
              {/* Tabs Content Implementation */}
              {activeTab === 'general' && (
                <div className="space-y-6 animate-fade-in">
                   <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* Image Upload Section */}
                        <div className="md:col-span-2 mb-2">
                          <label className="block text-sm font-medium text-slate-700 mb-2">Product Image</label>
                          <div className="flex items-center space-x-6">
                            <div 
                                onClick={() => fileInputRef.current?.click()}
                                className="w-32 h-32 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 flex flex-col items-center justify-center cursor-pointer hover:bg-slate-100 hover:border-primary-400 transition-colors relative overflow-hidden group"
                            >
                              {formData.imageUrl ? (
                                <>
                                  <img src={formData.imageUrl} alt="Preview" className="w-full h-full object-cover" />
                                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                     <div className="bg-white/20 p-2 rounded-full backdrop-blur-sm">
                                        <Edit2 className="w-5 h-5 text-white" />
                                     </div>
                                  </div>
                                </>
                              ) : (
                                <>
                                  <ImageIcon className="w-8 h-8 text-slate-400 mb-2" />
                                  <span className="text-xs text-slate-500 font-medium">Upload</span>
                                </>
                              )}
                            </div>

                            <div className="flex-1">
                               <p className="text-sm text-slate-600 mb-2">
                                 Upload a product image to display in POS and Catalog.
                               </p>
                               <div className="flex space-x-3">
                                  <button
                                    type="button"
                                    onClick={() => fileInputRef.current?.click()}
                                    className="px-4 py-2 bg-white border border-slate-300 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-50 shadow-sm"
                                  >
                                    Choose File
                                  </button>
                                  {formData.imageUrl && (
                                    <button
                                      type="button"
                                      onClick={handleRemoveImage}
                                      className="px-4 py-2 bg-red-50 border border-red-200 rounded-lg text-sm font-medium text-red-600 hover:bg-red-100"
                                    >
                                      Remove
                                    </button>
                                  )}
                               </div>
                               <p className="text-xs text-slate-400 mt-2">Max 5MB. Formats: JPG, PNG, WEBP</p>
                            </div>
                            <input 
                              type="file" 
                              ref={fileInputRef} 
                              className="hidden" 
                              accept="image/*"
                              onChange={handleImageUpload}
                            />
                          </div>
                        </div>

                        <div className="md:col-span-2">
                          <label className="block text-sm font-medium text-slate-700 mb-1">{t('inventory.productName')} *</label>
                          <input
                            type="text"
                            name="name"
                            required
                            value={formData.name}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">{t('inventory.category')} *</label>
                          <select
                            name="category"
                            required
                            value={formData.category}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white"
                          >
                             <option value="">Select</option>
                             {categoryOptions.map(cat => (
                               <option key={cat.id} value={cat.id}>
                                  {'\u00A0'.repeat(cat.level * 3)}{cat.name}
                               </option>
                             ))}
                          </select>
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">{t('inventory.sku')}</label>
                           <input
                            type="text"
                            name="sku"
                            value={formData.sku}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-mono"
                          />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">Barcode</label>
                           <input
                            type="text"
                            name="barcode"
                            value={formData.barcode}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-mono"
                          />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">{t('inventory.stock')}</label>
                           <input
                            type="number"
                            name="stock"
                            min="0"
                            value={formData.stock}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                          />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">Min Stock</label>
                           <input
                            type="number"
                            name="minStock"
                            min="0"
                            value={formData.minStock}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                          />
                        </div>
                      </div>
                   </div>
                </div>
              )}

              {/* Other tabs remain largely the same, just wrapped in the form context */}
              {activeTab === 'physical' && (
                <div className="space-y-6 animate-fade-in">
                   <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                      <h4 className="font-bold text-slate-800 mb-4 flex items-center">
                         <Scale className="w-5 h-5 mr-2 text-slate-500" />
                         Unit Configuration
                      </h4>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Main Unit *</label>
                         <select
                            name="unit"
                            required
                            value={formData.unit}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white"
                          >
                            <option value="">Select Unit</option>
                            {Object.entries(unitsByCategory).map(([cat, catUnits]) => (
                              <optgroup key={cat} label={cat}>
                                {(catUnits as UnitDefinition[]).map(u => (
                                  <option key={u.id} value={u.symbol}>
                                    {u.name} ({u.symbol})
                                  </option>
                                ))}
                              </optgroup>
                            ))}
                          </select>
                      </div>
                   </div>
                </div>
              )}

              {activeTab === 'pricing' && (
                <div className="space-y-6 animate-fade-in">
                   <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                      <div className="mb-6">
                         <label className="block text-sm font-bold text-slate-800 mb-2">{t('inventory.price')}</label>
                         <div className="relative max-w-xs">
                            <span className="absolute left-3 top-2.5 text-slate-400 font-bold">$</span>
                            <input
                              type="number"
                              name="price"
                              required
                              min="0"
                              step="0.01"
                              value={formData.price}
                              onChange={handleInputChange}
                              className="w-full pl-8 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 text-lg font-bold text-slate-800"
                            />
                         </div>
                      </div>
                   </div>
                </div>
              )}

              {activeTab === 'variants' && (
                <div className="space-y-6 animate-fade-in">
                   <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                      <div className="flex justify-between items-center mb-4">
                        <h4 className="font-bold text-slate-800">Product Variants</h4>
                        <button 
                          type="button" 
                          onClick={handleAddVariant}
                          className="text-sm flex items-center text-primary-600 font-medium hover:text-primary-700 bg-primary-50 px-3 py-1.5 rounded-lg transition-colors"
                        >
                          <Plus className="w-4 h-4 mr-1" /> {t('common.add')} Variant
                        </button>
                      </div>

                      {variants.length === 0 ? (
                        <div className="text-center py-8 text-slate-400 border-2 border-dashed border-slate-100 rounded-lg">
                          No variants added.
                        </div>
                      ) : (
                        <div className="space-y-4">
                           {variants.map((variant, index) => {
                              const factor = variant.conversionFactor || 1;
                              const isBundle = factor > 0 && factor < 1;
                              const displayRatio = isBundle ? Math.round(1/factor) : factor;

                              return (
                                <div key={index} className="bg-slate-50 p-4 rounded-xl border border-slate-200 relative group">
                                   <button 
                                      type="button"
                                      onClick={() => handleRemoveVariant(index)}
                                      className="absolute top-2 right-2 p-1 text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                    >
                                      <Trash2 className="w-4 h-4" />
                                    </button>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-3">
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Variant Unit</label>
                                          <select
                                            value={variant.name}
                                            onChange={e => handleVariantChange(index, 'name', e.target.value)}
                                            className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm bg-white"
                                          >
                                            <option value="">Select</option>
                                            {Object.entries(unitsByCategory).map(([cat, catUnits]) => (
                                              <optgroup key={cat} label={cat}>
                                                {(catUnits as UnitDefinition[]).map(u => (
                                                  <option key={u.id} value={u.symbol}>{u.name} ({u.symbol})</option>
                                                ))}
                                              </optgroup>
                                            ))}
                                          </select>
                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Price</label>
                                          <input
                                            type="number"
                                            value={variant.price}
                                            onChange={e => {
                                               const newVars = [...variants];
                                               newVars[index].price = parseFloat(e.target.value) || 0;
                                               setVariants(newVars);
                                            }}
                                            className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm"
                                          />
                                       </div>
                                    </div>
                                    <div className="bg-white p-3 rounded border border-slate-200 flex items-center text-sm">
                                       <span className="text-slate-500 mr-2">Ratio:</span>
                                       <select
                                          value={isBundle ? 'bundle' : 'sub'}
                                          onChange={(e) => handleVariantRelationChange(index, displayRatio, e.target.value as 'bundle' | 'sub')}
                                          className="px-2 py-1 text-xs border rounded bg-slate-50 mr-2"
                                        >
                                          <option value="sub">Sub-unit</option>
                                          <option value="bundle">Bundle</option>
                                        </select>
                                        <input 
                                          type="number" 
                                          min="1"
                                          value={displayRatio}
                                          onChange={(e) => handleVariantRelationChange(index, parseFloat(e.target.value) || 1, isBundle ? 'bundle' : 'sub')}
                                          className="w-16 px-1 py-0.5 border rounded text-center font-bold mx-1"
                                        />
                                    </div>
                                </div>
                              );
                           })}
                        </div>
                      )}
                   </div>
                </div>
              )}

            </form>

            <div className="p-4 border-t border-slate-100 flex justify-end items-center bg-white shrink-0 space-x-3">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-5 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  {t('common.cancel')}
                </button>
                <button
                  type="button"
                  onClick={handleSubmit}
                  className="px-5 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm flex items-center"
                >
                  <Check className="w-4 h-4 mr-2" />
                  {t('common.save')}
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export enum Category {
  CEMENT = 'Cement & Concrete',
  STEEL = 'Steel & Metal',
  WOOD = 'Wood & Lumber',
  PAINT = 'Paints & Finishes',
  TOOLS = 'Tools & Hardware',
  PLUMBING = 'Plumbing',
  ELECTRICAL = 'Electrical',
  CONSUMABLES = 'General Consumables'
}

export type UnitCategory = 'Weight' | 'Length' | 'Quantity';

export interface UnitDefinition {
  id: string;
  name: string;      // e.g. Kilogram
  symbol: string;    // e.g. kg
  category: UnitCategory;
  baseFactor: number; // 1 for base unit (e.g. g), 1000 for kg
  isBase: boolean;   // True if this is the reference unit
}

export interface CategoryItem {
  id: string;
  name: string;
  parentId: string | null; // null for root categories
  description?: string;
}

export interface ProductVariant {
  id: string;
  name: string;      // e.g., 'Piece', 'Small', 'Red' (Unit Name or Variant Name)
  code: string;      // SKU/Code for the variant
  barcode: string;   // Barcode for the variant
  conversionFactor: number; // How many variants in the main unit
  price: number;     // Price per variant
  color?: string;    // New: Color specification (e.g., 'Red', '#FF0000')
  size?: string;     // New: Size specification (e.g., 'XL', '10mm')
}

export interface ProductInventory {
  warehouseId: string;
  quantity: number;
}

export interface BranchPrice {
  branchId: string;
  price: number;
}

export interface ProductPhysical {
  weight?: number; // kg
  width?: number;  // cm
  height?: number; // cm
  depth?: number;  // cm (length)
}

export interface Product {
  id: string;
  name: string;
  category: Category | string; 
  price: number;     // Base Price (Global)
  branchPrices?: BranchPrice[]; // Overrides per branch
  stock: number;     // Stock count in MAIN units (Aggregate Total)
  minStock?: number; // Minimum stock threshold for alerts
  warehouseInventory?: ProductInventory[]; // Breakdown by warehouse
  unit: string;      // Name of the MAIN unit (e.g., 'bag', 'box')
  physical?: ProductPhysical; // New: Physical attributes
  imageUrl?: string;
  sku: string;       // SKU of MAIN unit
  barcode: string;   // Barcode of MAIN unit
  variants?: ProductVariant[]; // List of sub-products/variants
}

export interface CartItem extends Product {
  quantity: number;
  // Handling multi-unit/variant logic
  selectedVariantId?: string; // null if main unit, string if variant
  sellPrice: number; 
  sellUnit: string;  
  sellConversionFactor: number; // 1 for main, X for variant
}

export interface Sale {
  id: string;
  items: CartItem[];
  subtotal?: number; // Raw total before discount/tax
  discountAmount?: number; // Deduction amount
  total: number; // Final payable amount
  date: string;
  paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit';
  paymentStatus: 'paid' | 'unpaid' | 'partial'; // Track debt status
  amountReceived?: number; // Amount given by customer
  change?: number; // Change returned
  remainingAmount?: number; // Amount left to pay (for credit/partial)
  status: 'completed' | 'voided'; // Order status
  syncStatus?: 'synced' | 'pending' | 'failed'; // Track sync state
  customerId?: string; // Link to customer
  customerName?: string; // Snapshot of name
}

export interface EstimateRequest {
  query: string;
}

export interface EstimateResultItem {
  productName: string;
  estimatedQuantity: number;
  unit: string;
  reasoning: string;
  matchedProductId?: string; // If found in inventory
}

// --- AI Inventory Analysis Types ---
export interface ReorderSuggestion {
  productId: string;
  productName: string;
  currentStock: number;
  suggestedReorderQty: number;
  priority: 'High' | 'Medium' | 'Low';
  reasoning: string;
}

export interface NewProductSuggestion {
  name: string;
  categoryName: string;
  estimatedPrice: number;
  reasoning: string;
  suggestedUnit: string;
}

export interface BundleSuggestion {
  bundleName: string;
  components: string[];
  estimatedPrice: number;
  reasoning: string;
  targetAudience: string;
}

export interface InventoryAnalysisResult {
  reorders: ReorderSuggestion[];
  newProducts: NewProductSuggestion[];
  bundles: BundleSuggestion[];
}

export interface Branch {
  id: string;
  name: string;
  address: string;
  phone: string;
  manager: string;
  isActive: boolean;
}

export interface PosMachine {
  id: string;
  branchId: string;
  machineNumber: string; // e.g., POS-01
  status: 'active' | 'maintenance' | 'inactive';
  lastActive?: string;
}

export interface Warehouse {
  id: string;
  branchId: string;
  name: string;
  code: string; // e.g., WH-01
  type: 'General' | 'Cold Storage' | 'Hazardous' | 'Showroom';
  description?: string;
}

export interface StorageLocation {
  id: string;
  warehouseId: string;
  zone: string;   // e.g., Zone A
  rack: string;   // e.g., Rack 01
  shelf: string;  // e.g., Shelf 03 (Level)
  bin: string;    // e.g., Bin B (Slot)
  fullCode: string; // Helper: A-01-03-B
  type?: 'Pallet' | 'Shelf' | 'Floor';
}

// --- Customer Types ---
export interface CustomerLevel {
  id: string;
  name: string;
  discountPercentage: number;
  color?: string;
}

export interface Customer {
  id: string;
  code: string; // Membership ID or Code
  name: string;
  phone: string;
  taxId?: string;
  address?: string;
  email?: string;
  loyaltyPoints: number;
  notes?: string;
  levelId?: string;
  level?: CustomerLevel;
}

// --- Stock Management Types ---

export type DocumentStatus = 'Draft' | 'Approved' | 'Completed' | 'Cancelled';

export interface StockItem {
  productId: string;
  variantId?: string; // Optional: if specific variant
  productName: string;
  unit: string;
  quantity: number;
  note?: string;
}

// 1. Transfer Request (ใบขอโอนย้ายสินค้า)
export interface StockTransfer {
  id: string;
  date: string;
  sourceWarehouseId: string;
  targetWarehouseId: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 2. Stock Count (ใบตรวจนับสินค้า)
export interface StockCountItem extends StockItem {
  systemQuantity: number; // Snapshot of system stock
  countedQuantity: number; // Actual count
  diff: number; // Calculated diff
}

export interface StockCount {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockCountItem[];
  referenceNo: string;
  counterName: string; // Who counted
  reason: string; // Mandatory reason for adjustment
}

// 3. Stock Reservation (ใบจองสินค้า)
export interface StockReservation {
  id: string;
  date: string;
  expiryDate: string;
  warehouseId: string;
  customerName: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

