                              <optgroup key={cat} label={cat}>
                                {(catUnits as UnitDefinition[]).map(u => (
                                  <option key={u.id} value={u.symbol}>
                                    {u.name} ({u.symbol})
                                  </option>
                                ))}
                              </optgroup>
                            ))}
                          </select>
                      </div>
                   </div>
                </div>
              )}

              {activeTab === 'pricing' && (
                <div className="space-y-6 animate-fade-in">
                   <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                      <div className="mb-6">
                         <label className="block text-sm font-bold text-slate-800 mb-2">{t('inventory.price')}</label>
                         <div className="relative max-w-xs">
                            <span className="absolute left-3 top-2.5 text-slate-400 font-bold">$</span>
                            <input
                              type="number"
                              name="price"
                              required
                              min="0"
                              step="0.01"
                              value={formData.price}
                              onChange={handleInputChange}
                              className="w-full pl-8 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 text-lg font-bold text-slate-800"
                            />
                         </div>
                      </div>
                   </div>
                </div>
              )}

              {activeTab === 'variants' && (
                <div className="space-y-6 animate-fade-in">
                   <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                      <div className="flex justify-between items-center mb-4">
                        <h4 className="font-bold text-slate-800">Product Variants</h4>
                        <button 
                          type="button" 
                          onClick={handleAddVariant}
                          className="text-sm flex items-center text-primary-600 font-medium hover:text-primary-700 bg-primary-50 px-3 py-1.5 rounded-lg transition-colors"
                        >
                          <Plus className="w-4 h-4 mr-1" /> {t('common.add')} Variant
                        </button>
                      </div>

                      {variants.length === 0 ? (
                        <div className="text-center py-8 text-slate-400 border-2 border-dashed border-slate-100 rounded-lg">
                          No variants added.
                        </div>
                      ) : (
                        <div className="space-y-4">
                           {variants.map((variant, index) => {
                              const factor = variant.conversionFactor || 1;
                              const isBundle = factor > 0 && factor < 1;
                              const displayRatio = isBundle ? Math.round(1/factor) : factor;

                              return (
                                <div key={index} className="bg-slate-50 p-4 rounded-xl border border-slate-200 relative group">
                                   <button 
                                      type="button"
                                      onClick={() => handleRemoveVariant(index)}
                                      className="absolute top-2 right-2 p-1 text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                    >
                                      <Trash2 className="w-4 h-4" />
                                    </button>

                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-3">
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Variant Unit</label>
                                          <select
                                            value={variant.name}
                                            onChange={e => handleVariantChange(index, 'name', e.target.value)}
                                            className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm bg-white"
                                          >
                                            <option value="">Select</option>
                                            {Object.entries(unitsByCategory).map(([cat, catUnits]) => (
                                              <optgroup key={cat} label={cat}>
                                                {(catUnits as UnitDefinition[]).map(u => (
                                                  <option key={u.id} value={u.symbol}>{u.name} ({u.symbol})</option>
                                                ))}
                                              </optgroup>
                                            ))}
                                          </select>
                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1 flex items-center"><Ruler className="w-3 h-3 mr-1"/> Size (Optional)</label>
                                          <input
                                            type="text"
                                            value={variant.size || ''}
                                            placeholder="e.g. XL, 10mm"
                                            onChange={e => handleVariantChange(index, 'size', e.target.value)}
                                            className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm"
                                          />
                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1 flex items-center"><Palette className="w-3 h-3 mr-1"/> Color (Optional)</label>
                                          <div className="relative">
                                            <input
                                              type="text"
                                              value={variant.color || ''}
                                              placeholder="e.g. Red, #FF0000"
                                              onChange={e => handleVariantChange(index, 'color', e.target.value)}
                                              className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm pl-8"
                                            />
                                            <div 
                                              className="absolute left-2 top-1/2 transform -translate-y-1/2 w-4 h-4 rounded-full border border-slate-300 shadow-sm"
                                              style={{ backgroundColor: variant.color || 'transparent' }}
                                            />
                                          </div>
                                       </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">
                                       <div className="bg-white p-2 rounded border border-slate-200 flex items-center text-sm">
                                          <span className="text-slate-500 mr-2 text-xs uppercase font-bold">Ratio:</span>
                                          <select
                                              value={isBundle ? 'bundle' : 'sub'}
                                              onChange={(e) => handleVariantRelationChange(index, displayRatio, e.target.value as 'bundle' | 'sub')}
                                              className="px-2 py-1 text-xs border rounded bg-slate-50 mr-2"
                                            >
                                              <option value="sub">Sub-unit</option>
                                              <option value="bundle">Bundle</option>
                                            </select>
                                            <input 
                                              type="number" 
                                              min="1"
                                              value={displayRatio}
                                              onChange={(e) => handleVariantRelationChange(index, parseFloat(e.target.value) || 1, isBundle ? 'bundle' : 'sub')}
                                              className="w-16 px-1 py-0.5 border rounded text-center font-bold mx-1"
                                            />
                                       </div>
                                       <div>
                                          <div className="relative">
                                            <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 text-xs">$</span>
                                            <input
                                              type="number"
                                              value={variant.price}
                                              onChange={e => {
                                                 const newVars = [...variants];
                                                 newVars[index].price = parseFloat(e.target.value) || 0;
                                                 setVariants(newVars);
                                              }}
                                              className="w-full pl-6 px-3 py-1.5 border border-slate-300 rounded text-sm font-bold text-slate-700"
                                              placeholder="Price"
                                            />
                                          </div>
                                       </div>
                                    </div>
                                </div>
                              );
                           })}
                        </div>
                      )}
                   </div>
                </div>
              )}

            </form>

            <div className="p-4 border-t border-slate-100 flex justify-end items-center bg-white shrink-0 space-x-3">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-5 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  {t('common.cancel')}
                </button>
                <button
                  type="button"
                  onClick={handleSubmit}
                  className="px-5 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm flex items-center"
                >
                  <Check className="w-4 h-4 mr-2" />
                  {t('common.save')}
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { User, UserRole } from '../types';
import { 
  Users, 
  Plus, 
  Edit2, 
  Trash2, 
  X, 
  ShieldCheck, 
  UserCircle,
  Mail,
  Lock,
  CheckCircle,
  Store,
  LayoutDashboard,
  ClipboardList,
  Package,
  Building2,
  Briefcase,
  Upload,
  Image as ImageIcon
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: User) => void;
  onUpdateUser: (user: User) => void;
  onDeleteUser: (id: string) => void;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const UserManagement: React.FC<UserManagementProps> = ({
  users,
  onAddUser,
  onUpdateUser,
  onDeleteUser
}) => {
  const { branches } = useGlobal();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<User>>({
    username: '',
    password: '',
    name: '',
    email: '',
    role: 'Cashier',
    avatarUrl: '',
    department: '',
    branchId: ''
  });

  const handleOpenModal = (user?: User) => {
    if (user) {
      setEditingId(user.id);
      setFormData({ 
        username: user.username,
        name: user.name,
        email: user.email || '',
        role: user.role,
        avatarUrl: user.avatarUrl || '',
        password: '', // Don't pre-fill password for editing security
        department: user.department || '',
        branchId: user.branchId || ''
      });
    } else {
      setEditingId(null);
      setFormData({
        username: '',
        password: '',
        name: '',
        email: '',
        role: 'Cashier',
        avatarUrl: '',
        department: '',
        branchId: ''
      });
    }
    setIsModalOpen(true);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, avatarUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, avatarUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Basic Validation
    if (!formData.username || !formData.name || !formData.role) return;
    if (!editingId && !formData.password) {
        alert("Password is required for new users.");
        return;
    }

    const userData: any = {
      username: formData.username,
      name: formData.name,
      email: formData.email,
      role: formData.role,
      avatarUrl: formData.avatarUrl,
      department: formData.department,
      branchId: formData.branchId
    };

    // Only update password if provided
    if (formData.password) {
      userData.password = formData.password;
    }

    if (editingId) {
      // For updates, preserve old password if new one isn't provided
      const existingUser = users.find(u => u.id === editingId);
      if (existingUser && !userData.password) {
          userData.password = existingUser.password;
      }
      onUpdateUser({ ...userData, id: editingId });
    } else {
      onAddUser({ ...userData, id: `u-${Date.now()}` });
    }
    setIsModalOpen(false);
  };

  // Permission Visualizer
  const getRolePermissions = (role: UserRole) => {
    switch (role) {
      case 'Admin':
        return [
          { label: 'Dashboard Access', access: true },
          { label: 'POS Terminal', access: true },
          { label: 'Inventory Management', access: true },
          { label: 'Stock Operations', access: true },
          { label: 'Approvals', access: true },
          { label: 'System Settings', access: true },
        ];
      case 'Manager':
        return [
          { label: 'Dashboard Access', access: true },
          { label: 'POS Terminal', access: true },
          { label: 'Inventory Management', access: true },
          { label: 'Stock Operations', access: true },
          { label: 'Approvals', access: true },
          { label: 'System Settings', access: false },
        ];
      case 'Staff':
        return [
          { label: 'Dashboard Access', access: false },
          { label: 'POS Terminal', access: true },
          { label: 'Inventory Management', access: true },
          { label: 'Stock Operations', access: true },
          { label: 'Approvals', access: false },
          { label: 'System Settings', access: false },
        ];
      case 'Cashier':
      default:
        return [
          { label: 'Dashboard Access', access: false },
          { label: 'POS Terminal', access: true },
          { label: 'Inventory Management', access: false },
          { label: 'Stock Operations', access: false },
          { label: 'Approvals', access: false },
          { label: 'System Settings', access: false },
        ];
    }
  };

  const permissions = getRolePermissions(formData.role as UserRole || 'Cashier');

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">User Management</h2>
          <p className="text-slate-500">Manage system users, roles, and access permissions.</p>
        </div>
        <button 
          onClick={() => handleOpenModal()}
          className="flex items-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium shadow-sm"
        >
          <Plus className="w-4 h-4 mr-2" />
          Add User
        </button>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-4 font-semibold text-slate-500 text-sm">User</th>
                <th className="px-6 py-4 font-semibold text-slate-500 text-sm">Role</th>
                <th className="px-6 py-4 font-semibold text-slate-500 text-sm">Branch & Dept</th>
                <th className="px-6 py-4 font-semibold text-slate-500 text-sm text-center">Status</th>
                <th className="px-6 py-4 font-semibold text-slate-500 text-sm text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {users.map((user) => (
                <tr key={user.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center overflow-hidden border border-slate-200">
                         {user.avatarUrl ? (
                           <img src={user.avatarUrl} alt={user.name} className="w-full h-full object-cover" />
                         ) : (
                           <UserCircle className="w-6 h-6 text-slate-400" />
                         )}
                      </div>
                      <div>
                        <div className="font-bold text-slate-800">{user.name}</div>
                        <div className="text-xs text-slate-500">@{user.username}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold border ${
                      user.role === 'Admin' ? 'bg-purple-50 text-purple-700 border-purple-200' :
                      user.role === 'Manager' ? 'bg-indigo-50 text-indigo-700 border-indigo-200' :
                      user.role === 'Staff' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                      'bg-green-50 text-green-700 border-green-200'
                    }`}>
                      {user.role === 'Admin' && <ShieldCheck className="w-3 h-3 mr-1"/>}
                      {user.role === 'Manager' && <LayoutDashboard className="w-3 h-3 mr-1"/>}
                      {user.role === 'Staff' && <ClipboardList className="w-3 h-3 mr-1"/>}
                      {user.role === 'Cashier' && <Store className="w-3 h-3 mr-1"/>}
                      {user.role}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-600">
                    <div className="flex flex-col space-y-1">
                      {user.branchId ? (
                        <div className="flex items-center text-xs text-slate-700 font-medium">
                          <Building2 className="w-3 h-3 mr-1.5 text-slate-400"/>
                          {branches.find(b => b.id === user.branchId)?.name || 'Unknown Branch'}
                        </div>
                      ) : (
                        <span className="text-xs text-slate-400 italic">No branch assigned</span>
                      )}
                      {user.department && (
                        <div className="flex items-center text-xs text-slate-500">
                          <Briefcase className="w-3 h-3 mr-1.5 text-slate-400"/>
                          {user.department}
                        </div>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center">
                     <span className="inline-block w-2 h-2 bg-green-500 rounded-full mr-2"></span>
                     <span className="text-sm text-slate-600">Active</span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end space-x-2">
                       <button onClick={() => handleOpenModal(user)} className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-slate-100 rounded transition-colors">
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={() => {
                           if(confirm(`Are you sure you want to delete ${user.name}?`)) onDeleteUser(user.id);
                        }} 
                        className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-slate-100 rounded transition-colors"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <h3 className="text-xl font-bold text-slate-800">
                {editingId ? 'Edit User' : 'Add New User'}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Left Column: Form Fields */}
                <div className="space-y-4">
                  {/* Avatar Upload */}
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-2">Profile Avatar</label>
                    <div className="flex items-center space-x-4">
                      <div 
                        onClick={() => fileInputRef.current?.click()}
                        className="relative w-16 h-16 rounded-full border-2 border-dashed border-slate-300 bg-slate-50 flex items-center justify-center cursor-pointer hover:bg-slate-100 hover:border-primary-400 transition-colors overflow-hidden group"
                      >
                        {formData.avatarUrl ? (
                          <>
                            <img src={formData.avatarUrl} alt="Preview" className="w-full h-full object-cover" />
                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                               <Edit2 className="w-4 h-4 text-white" />
                            </div>
                          </>
                        ) : (
                          <UserCircle className="w-8 h-8 text-slate-400" />
                        )}
                      </div>

                      <div className="flex-1">
                         <div className="flex space-x-2">
                            <button
                              type="button"
                              onClick={() => fileInputRef.current?.click()}
                              className="px-3 py-1.5 bg-white border border-slate-300 rounded-md text-xs font-medium text-slate-700 hover:bg-slate-50"
                            >
                              Upload
                            </button>
                            {formData.avatarUrl && (
                              <button
                                type="button"
                                onClick={handleRemoveImage}
                                className="px-3 py-1.5 bg-white border border-red-200 rounded-md text-xs font-medium text-red-600 hover:bg-red-50"
                              >
                                Remove
                              </button>
                            )}
                         </div>
                         <p className="text-[10px] text-slate-400 mt-1">Max 5MB. Formats: JPG, PNG</p>
                      </div>
                      <input 
                        type="file" 
                        ref={fileInputRef} 
                        className="hidden" 
                        accept="image/*"
                        onChange={handleImageUpload}
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Full Name</label>
                    <div className="relative">
                      <UserCircle className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                      <input
                        required
                        type="text"
                        value={formData.name}
                        onChange={e => setFormData({...formData, name: e.target.value})}
                        className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                        placeholder="John Doe"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Username</label>
                    <input
                      required
                      type="text"
                      value={formData.username}
                      onChange={e => setFormData({...formData, username: e.target.value})}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-slate-50"
                      placeholder="username"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">
                      Password {editingId && <span className="text-xs font-normal text-slate-400">(Leave blank to keep current)</span>}
                    </label>
                    <div className="relative">
                       <Lock className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                       <input
                        required={!editingId}
                        type="password"
                        value={formData.password}
                        onChange={e => setFormData({...formData, password: e.target.value})}
                        className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                        placeholder="••••••••"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Email <span className="text-slate-400 font-normal">(Optional)</span></label>
                    <div className="relative">
                       <Mail className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                       <input
                        type="email"
                        value={formData.email}
                        onChange={e => setFormData({...formData, email: e.target.value})}
                        className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                        placeholder="john@example.com"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Department</label>
                    <div className="relative">
                       <Briefcase className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                       <input
                        type="text"
                        value={formData.department}
                        onChange={e => setFormData({...formData, department: e.target.value})}
                        className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                        placeholder="e.g. Sales, Warehouse"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Branch</label>
                    <div className="relative">
                       <Building2 className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                       <select
                        value={formData.branchId || ''}
                        onChange={e => setFormData({...formData, branchId: e.target.value})}
                        className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white"
                      >
                        <option value="">Select Branch</option>
                        {branches.map(b => (
                          <option key={b.id} value={b.id}>{b.name}</option>
                        ))}
                      </select>
