  const [counts, setCounts] = useState<StockCount[]>(INITIAL_COUNTS);
  const [reservations, setReservations] = useState<StockReservation[]>([]);
  const [receipts, setReceipts] = useState<StockReceipt[]>([]);
  const [adjustments, setAdjustments] = useState<StockAdjustment[]>([]);
  const [syncLogs, setSyncLogs] = useState<SyncLog[]>(INITIAL_SYNC_LOGS);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [shiftSchedules, setShiftSchedules] = useState<ShiftSchedule[]>(INITIAL_SHIFT_SCHEDULES);
  const [promotions, setPromotions] = useState<Promotion[]>(INITIAL_PROMOTIONS);

  // Load User from LocalStorage on mount
  useEffect(() => {
    const savedUser = localStorage.getItem('buildmaster_user');
    if (savedUser) {
      try {
        setCurrentUser(JSON.parse(savedUser));
      } catch (e) {
        localStorage.removeItem('buildmaster_user');
      }
    }
  }, []);

  // Update LocalStorage when user changes
  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('buildmaster_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('buildmaster_user');
    }
  }, [currentUser]);

  // Mock API Call simulation
  const mockApiCall = async <T,>(data: T): Promise<T> => {
    return new Promise((resolve) => {
      setTimeout(() => resolve(data), 300); // Simulate 300ms latency
    });
  };

  const t = (key: string): string => {
    const lang = settings.language || 'en';
    const keys = key.split('.');
    let value: any = translations[lang as keyof typeof translations];

    for (const k of keys) {
      if (value && typeof value === 'object' && k in value) {
        value = value[k];
      } else {
        return key; // Return key if translation missing
      }
    }
    return value as string;
  };

  // ---------------- STOCK MOVEMENT LOGIC ----------------
  const applyStockChanges = (doc: any, type: string) => {
    setProducts(prevProducts => {
        const nextProducts = [...prevProducts];

        doc.items.forEach((item: any) => {
            const pIndex = nextProducts.findIndex(p => p.id === item.productId);
            if (pIndex === -1) return;

            const product = { ...nextProducts[pIndex] };
            // Ensure warehouseInventory exists
            if (!product.warehouseInventory) product.warehouseInventory = [];

            // Helper to get/create warehouse record
            const getWhInv = (whId: string) => {
                let whInv = product.warehouseInventory!.find(w => w.warehouseId === whId);
                if (!whInv) {
                    whInv = { warehouseId: whId, quantity: 0 };
                    product.warehouseInventory!.push(whInv);
                }
                return whInv;
            };

            if (type === 'receipt') {
                const whInv = getWhInv(doc.warehouseId);
                const qty = item.quantity || 0;
                whInv.quantity += qty;
                product.stock += qty;
            } else if (type === 'adjustment') {
                const whInv = getWhInv(doc.warehouseId);
                const qty = item.quantity || 0; // can be negative
                whInv.quantity += qty;
                product.stock += qty;
            } else if (type === 'transfer') {
                const qty = item.quantity || 0;
                const sourceInv = getWhInv(doc.sourceWarehouseId);
                const targetInv = getWhInv(doc.targetWarehouseId);

                sourceInv.quantity = Math.max(0, sourceInv.quantity - qty);
                targetInv.quantity += qty;
                // Total aggregate stock doesn't change
            } else if (type === 'count') {
                const whInv = getWhInv(doc.warehouseId);
                // Difference applied to total
                const counted = item.countedQuantity || 0;
                const currentSystem = whInv.quantity; // Or snapshot from item.systemQuantity
                const diff = counted - currentSystem;

                whInv.quantity = counted;
                product.stock += diff;
            }

            nextProducts[pIndex] = product;
        });

        return nextProducts;
    });
  };

  const processSale = async (
    cartItems: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit' = 'cash',
    amountReceived?: number,
    change?: number
  ): Promise<Sale> => {

    let finalPaymentStatus: 'paid' | 'unpaid' | 'partial' = 'paid';
    let finalRemaining = 0;

    if (paymentMethod === 'credit') {
        const received = amountReceived || 0;
        finalRemaining = Math.max(0, total - received);

        if (finalRemaining <= 0.01) {
             finalPaymentStatus = 'paid';
             finalRemaining = 0;
        } else if (received > 0) {
             finalPaymentStatus = 'partial';
        } else {
             finalPaymentStatus = 'unpaid';
        }
    }

    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items: cartItems,
      total,
      subtotal,
      discountAmount,
      paymentMethod,
      paymentStatus: finalPaymentStatus,
      amountReceived: amountReceived || 0,
      remainingAmount: finalRemaining,
      change: change || 0,
      date: new Date().toISOString(),
      status: 'completed',
      syncStatus: 'pending',
      customerId,
      customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined
    };

    // Optimistically update Sales
    setSales(prev => [newSale, ...prev]);

    // Optimistically update Product Stock
    setProducts(prevProducts => {
      const updatedProducts = [...prevProducts];

      cartItems.forEach(item => {
        const productIndex = updatedProducts.findIndex(p => p.id === item.id);
        if (productIndex > -1) {
          const product = { ...updatedProducts[productIndex] };

          // Calculate deduction logic
          let deduction = item.quantity;
          // Apply variant conversion if needed (for simplicity assuming basic units for now or already converted)
          // If selling 'box' (12pcs) and stock is 'pcs', deduction should be 12.
          if (item.sellConversionFactor && item.sellConversionFactor > 0) {
             // Logic depends on how stock is tracked. Here assuming Stock is tracked in Base Unit.
             deduction = item.quantity * item.sellConversionFactor;
          }

          product.stock = Math.max(0, product.stock - deduction);

          // Update warehouse specific inventory if available (simplified to first warehouse)
          if (product.warehouseInventory && product.warehouseInventory.length > 0) {
             product.warehouseInventory[0].quantity = Math.max(0, product.warehouseInventory[0].quantity - deduction);
          }

          updatedProducts[productIndex] = product;
        }
      });
      return updatedProducts;
    });

    await mockApiCall(null);
    return newSale;
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: 'cash' | 'card' | 'transfer') => {
    setSales(prev => prev.map(s => {
      if (s.id === saleId) {
        const currentRemaining = s.remainingAmount || s.total;
        const newRemaining = Math.max(0, currentRemaining - amount);
        const newStatus = newRemaining <= 0.01 ? 'paid' : 'partial';
        const newAmountReceived = (s.amountReceived || 0) + amount;

        // In a real system, we would log a separate "PaymentTransaction" record here
        return {
          ...s,
          paymentStatus: newStatus,
          remainingAmount: newRemaining,
          amountReceived: newAmountReceived
        };
      }
      return s;
    }));
    await mockApiCall(null);
  };

  const handleVoidSale = async (id: string) => {
    // 1. Find the sale
    const saleToVoid = sales.find(s => s.id === id);
    if (!saleToVoid) return;
    if (saleToVoid.status === 'voided') return; // Prevent double voiding

    // 2. Update Sale Status
    setSales(prev => prev.map(s => {
      if (s.id === id) {
        return { ...s, status: 'voided', paymentStatus: 'paid', remainingAmount: 0 }; // Void implies no debt left to collect
      }
      return s;
    }));

    // 3. RESTORE Stock (Logic added)
    setProducts(prevProducts => {
      const updatedProducts = [...prevProducts];

      saleToVoid.items.forEach(item => {
        const productIndex = updatedProducts.findIndex(p => p.id === item.id);
        if (productIndex > -1) {
          const product = { ...updatedProducts[productIndex] };

          // Add quantity back to stock
          let qtyToRestore = item.quantity;
          if (item.sellConversionFactor && item.sellConversionFactor > 0) {
             qtyToRestore = item.quantity * item.sellConversionFactor;
          }

          product.stock += qtyToRestore;

          // Add back to default warehouse inventory
          if (product.warehouseInventory && product.warehouseInventory.length > 0) {
             product.warehouseInventory[0].quantity += qtyToRestore;
          }

          updatedProducts[productIndex] = product;
        }
      });

      return updatedProducts;
    });

    await mockApiCall(null);
  };

  const addProduct = async (p: Product) => {
    const newProduct = { ...p, id: `P-${Date.now()}` };
    setProducts(prev => [...prev, newProduct]);
    await mockApiCall(null);
  };
  const updateProduct = async (p: Product) => {
    setProducts(prev => prev.map(item => item.id === p.id ? p : item));
    await mockApiCall(null);
  };
  const deleteProduct = async (id: string) => {
    setProducts(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addUnit = async (u: UnitDefinition) => {
    setUnits(prev => [...prev, { ...u, id: `u-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateUnit = async (u: UnitDefinition) => {
    setUnits(prev => prev.map(item => item.id === u.id ? u : item));
    await mockApiCall(null);
  };
  const deleteUnit = async (id: string) => {
    setUnits(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addCategory = async (c: CategoryItem) => {
    setCategories(prev => [...prev, { ...c, id: `c-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateCategory = async (c: CategoryItem) => {
    setCategories(prev => prev.map(item => item.id === c.id ? c : item));
    await mockApiCall(null);
  };
  const deleteCategory = async (id: string) => {
    setCategories(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const updateSettings = async (s: SystemSettings) => {
    setSettings(s);
    await mockApiCall(null);
  };

  const addBranch = async (b: Branch) => {
    setBranches(prev => [...prev, { ...b, id: `b-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateBranch = async (b: Branch) => {
    setBranches(prev => prev.map(item => item.id === b.id ? b : item));
    await mockApiCall(null);
  };
  const deleteBranch = async (id: string) => {
    setBranches(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addPos = async (p: PosMachine) => {
    setPosMachines(prev => [...prev, p]);
    await mockApiCall(null);
  };
  const updatePos = async (p: PosMachine) => {
    setPosMachines(prev => prev.map(item => item.id === p.id ? p : item));
    await mockApiCall(null);
  }; 
  const deletePos = async (id: string) => {
    setPosMachines(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addWarehouse = async (w: Warehouse) => {
    setWarehouses(prev => [...prev, { ...w, id: `wh-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateWarehouse = async (w: Warehouse) => {
    setWarehouses(prev => prev.map(item => item.id === w.id ? w : item));
    await mockApiCall(null);
  };
  const deleteWarehouse = async (id: string) => {
    setWarehouses(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addLocation = async (l: StorageLocation) => {
    setLocations(prev => [...prev, { ...l, id: `loc-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateLocation = async (l: StorageLocation) => {
    setLocations(prev => prev.map(item => item.id === l.id ? l : item));
    await mockApiCall(null);
  };
  const deleteLocation = async (id: string) => {
    setLocations(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addUser = async (u: User) => {
    setUsers(prev => [...prev, { ...u, id: `u-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateUser = async (u: User) => {
    setUsers(prev => prev.map(item => item.id === u.id ? u : item));
    await mockApiCall(null);
  };
  const deleteUser = async (id: string) => {
    setUsers(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addCustomer = async (c: Customer) => {
    setCustomers(prev => [...prev, { ...c, id: `cust-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateCustomer = async (c: Customer) => {
    setCustomers(prev => prev.map(item => item.id === c.id ? c : item));
    await mockApiCall(null);
  };
  const deleteCustomer = async (id: string) => {
    setCustomers(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  const addCustomerLevel = async (l: CustomerLevel) => {
    setCustomerLevels(prev => [...prev, { ...l, id: `lvl-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updateCustomerLevel = async (l: CustomerLevel) => {
    setCustomerLevels(prev => prev.map(item => item.id === l.id ? l : item));
    await mockApiCall(null);
  };
  const deleteCustomerLevel = async (id: string) => {
    setCustomerLevels(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  // Stock Documents Mock Logic
  const upsertDoc = (list: any[], setList: any, item: any) => {
    // Check if status changed to approved/completed from NOT approved/completed
    const prevItem = list.find(i => i.id === item.id);
    const isNew = !prevItem;
    const wasDraft = prevItem && (prevItem.status !== 'Completed');
    const isNowFinal = item.status === 'Completed';

    if ((isNew && isNowFinal) || (wasDraft && isNowFinal)) {
       // Trigger Stock Update Logic
       // determine type by checking properties or passing it?
       // We can infer type from keys
       let type = '';
       if (item.sourceWarehouseId) type = 'transfer';
       else if (item.totalCost !== undefined) type = 'receipt'; // Receipt has totalCost
       else if (item.reason && item.counterName) type = 'count';
       else if (item.reason) type = 'adjustment'; // Adjustment has reason but no counterName
       // Reservation doesn't move stock in this simple model

       if (type) applyStockChanges(item, type);
    }

    setList((prev: any[]) => {
      const idx = prev.findIndex(i => i.id === item.id);
      if (idx > -1) {
        const newArr = [...prev];
        newArr[idx] = item;
        return newArr;
      }
      return [item, ...prev];
    });
  };

  const deleteDoc = (setList: any, id: string) => {
    setList((prev: any[]) => prev.filter(i => i.id !== id));
  };

  const updateTransfer = async (t: StockTransfer) => { upsertDoc(transfers, setTransfers, t); await mockApiCall(null); };
  const deleteTransfer = async (id: string) => { deleteDoc(setTransfers, id); await mockApiCall(null); };

  const updateCount = async (c: StockCount) => { upsertDoc(counts, setCounts, c); await mockApiCall(null); };
  const deleteCount = async (id: string) => { deleteDoc(setCounts, id); await mockApiCall(null); };

  const updateReservation = async (r: StockReservation) => { upsertDoc(reservations, setReservations, r); await mockApiCall(null); };
  const deleteReservation = async (id: string) => { deleteDoc(setReservations, id); await mockApiCall(null); };

  const updateReceipt = async (r: StockReceipt) => { upsertDoc(receipts, setReceipts, r); await mockApiCall(null); };
  const deleteReceipt = async (id: string) => { deleteDoc(setReceipts, id); await mockApiCall(null); };

  const updateAdjustment = async (a: StockAdjustment) => { upsertDoc(adjustments, setAdjustments, a); await mockApiCall(null); };
  const deleteAdjustment = async (id: string) => { deleteDoc(setAdjustments, id); await mockApiCall(null); };

  const handleStockStatusChange = async (type: string, id: string, status: DocumentStatus) => {
    // 1. Update Document Status
    let docToUpdate = null;

    switch (type) {
      case 'transfer':
        setTransfers(prev => prev.map(d => {
           if (d.id === id) { docToUpdate = { ...d, status }; return docToUpdate; }
           return d;
        }));
        break;
      case 'count':
        setCounts(prev => prev.map(d => {
           if (d.id === id) { docToUpdate = { ...d, status }; return docToUpdate; }
           return d;
        }));
        break;
      case 'reservation':
        setReservations(prev => prev.map(d => {
           if (d.id === id) { docToUpdate = { ...d, status }; return docToUpdate; }
           return d;
        }));
        break;
      case 'receipt':
        setReceipts(prev => prev.map(d => {
           if (d.id === id) { docToUpdate = { ...d, status }; return docToUpdate; }
           return d;
        }));
        break;
      case 'adjustment':
        setAdjustments(prev => prev.map(d => {
           if (d.id === id) { docToUpdate = { ...d, status }; return docToUpdate; }
           return d;
        }));
        break;
    }

    // Apply Stock Change ONLY if status becomes Completed
    // This supports the flow: Draft -> Approved (Manager) -> Completed (Stock Update)
    if (status === 'Completed' && docToUpdate) {
       applyStockChanges(docToUpdate, type);
    }

    await mockApiCall(null);
  };

  const handleSyncOperation = async (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
    const log: SyncLog = {
      id: `log-${Date.now()}`,
      timestamp: new Date().toISOString(),
      type,
      status: 'Success',
      details: 'Mock Data Sync Completed (Simulated)',
      durationMs: 750
    };
    setSyncLogs(prev => [log, ...prev]);
    await mockApiCall(null);
  };

  const startShift = async (branchId: string, startCash: number, notes?: string) => {
    if (!currentUser) return;
    const newShift: Shift = {
      id: `sh-${Date.now()}`,
      userId: currentUser.id,
      branchId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open'
    };
    setShifts(prev => [newShift, ...prev]);
    await mockApiCall(null);
  };

  const endShift = async (shiftId: string, endCash: number, notes?: string) => {
    setShifts(prev => prev.map(s => {
      if (s.id === shiftId) {
        return {
          ...s,
          endTime: new Date().toISOString(),
          endCash,
          notes,
          status: 'Closed'
        };
      }
      return s;
    }));
    await mockApiCall(null);
  };

  const addShiftSchedule = async (schedule: ShiftSchedule) => {
    setShiftSchedules(prev => [...prev, schedule]);
    await mockApiCall(null);
  };

  const deleteShiftSchedule = async (id: string) => {
    setShiftSchedules(prev => prev.filter(s => s.id !== id));
    await mockApiCall(null);
  };

  const addPromotion = async (p: Promotion) => {
    setPromotions(prev => [...prev, { ...p, id: `promo-${Date.now()}` }]);
    await mockApiCall(null);
  };
  const updatePromotion = async (p: Promotion) => {
    setPromotions(prev => prev.map(item => item.id === p.id ? p : item));
    await mockApiCall(null);
  };
  const deletePromotion = async (id: string) => {
    setPromotions(prev => prev.filter(item => item.id !== id));
    await mockApiCall(null);
  };

  return (
    <GlobalContext.Provider value={{
      currentUser, setCurrentUser,
      users, settings, updateSettings,
      products, sales, units, categories, branches, posMachines, warehouses, locations, customers, customerLevels,
      transfers, counts, reservations, receipts, adjustments, syncLogs, shifts, shiftSchedules, promotions,

      t, 

      processSale, handleVoidSale, settleSaleDebt,
      addProduct, updateProduct, deleteProduct,
      addUnit, updateUnit, deleteUnit,
      addCategory, updateCategory, deleteCategory,
      addBranch, updateBranch, deleteBranch,
      addPos, updatePos, deletePos,
      addWarehouse, updateWarehouse, deleteWarehouse,
      addLocation, updateLocation, deleteLocation,
      addUser, updateUser, deleteUser,
      addCustomer, updateCustomer, deleteCustomer,
      addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,

      updateTransfer, deleteTransfer,
      updateCount, deleteCount,
      updateReservation, deleteReservation,
      updateReceipt, deleteReceipt,
      updateAdjustment, deleteAdjustment,
      handleStockStatusChange,

      handleSyncOperation,
      startShift, endShift,
      addShiftSchedule, deleteShiftSchedule,

      addPromotion, updatePromotion, deletePromotion
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { 
  Warehouse, Product, StockTransfer, StockCount, StockReservation, StockReceipt, StockAdjustment, 
  DocumentStatus, StockItem 
} from '../types';
import { 
  Plus, Edit2, Trash2, ArrowRightLeft, 
  CheckSquare, CalendarClock, Truck, SlidersHorizontal, 
  X, CheckCircle, FileText, PlayCircle
} from 'lucide-react';

interface StockManagementProps {
  warehouses: Warehouse[];
  products: Product[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  defaultItemsPerPage: number;
  onUpdateTransfer: (t: StockTransfer) => void;
  onDeleteTransfer: (id: string) => void;
  onUpdateCount: (c: StockCount) => void;
  onDeleteCount: (id: string) => void;
  onUpdateReservation: (r: StockReservation) => void;
  onDeleteReservation: (id: string) => void;
  onUpdateReceipt: (r: StockReceipt) => void;
  onDeleteReceipt: (id: string) => void;
  onUpdateAdjustment: (a: StockAdjustment) => void;
  onDeleteAdjustment: (id: string) => void;
  onStatusChange: (type: string, id: string, status: DocumentStatus) => void;
}

export const StockManagement: React.FC<StockManagementProps> = ({
  warehouses, products, transfers, counts, reservations, receipts, adjustments, defaultItemsPerPage,
  onUpdateTransfer, onDeleteTransfer,
  onUpdateCount, onDeleteCount,
  onUpdateReservation, onDeleteReservation,
  onUpdateReceipt, onDeleteReceipt,
  onUpdateAdjustment, onDeleteAdjustment,
  onStatusChange
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment'>('transfer');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<any>({}); 

  // Helper to init form based on tab
  const initForm = () => {
    const common = {
      referenceNo: '',
      date: new Date().toISOString().split('T')[0],
      status: 'Draft',
      items: []
    };

    switch(activeTab) {
      case 'transfer': return { ...common, sourceWarehouseId: '', targetWarehouseId: '' };
      case 'count': return { ...common, warehouseId: '', counterName: '', reason: '' };
      case 'reservation': return { ...common, warehouseId: '', customerName: '', expiryDate: '' };
      case 'receipt': return { ...common, warehouseId: '', vendorName: '', vendorInvoiceNo: '', totalCost: 0 };
      case 'adjustment': return { ...common, warehouseId: '', reason: '' };
    }
  };

  const handleOpenModal = (item?: any) => {
    if (item) {
      setEditingId(item.id);
      setFormData({ ...item });
    } else {
      setEditingId(null);
      setFormData(initForm());
    }
    setIsModalOpen(true);
  };

  // Only saves as Draft. Approval flow handles the rest.
  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    if (!window.confirm('Are you sure you want to save this document?')) {
      return;
    }

    const id = editingId || (activeTab === 'transfer' ? `TR-${Date.now()}` : 
                             activeTab === 'count' ? `SC-${Date.now()}` :
                             activeTab === 'reservation' ? `RS-${Date.now()}` :
                             activeTab === 'receipt' ? `RC-${Date.now()}` :
                             `AD-${Date.now()}`);

    // Always save as Draft initially or preserve existing status if editing (though editing is usually restricted to Draft)
    const currentStatus = formData.status === 'Completed' || formData.status === 'Approved' ? formData.status : 'Draft';
    const payload = { ...formData, id, status: currentStatus };

    // Auto-generate Ref No if missing
    if (!payload.referenceNo) {
        payload.referenceNo = `${activeTab.toUpperCase().slice(0,2)}-${new Date().getFullYear()}${new Date().getMonth()+1}-${Math.floor(Math.random()*1000)}`;
    }

    switch (activeTab) {
      case 'transfer': onUpdateTransfer(payload); break;
      case 'count': onUpdateCount(payload); break;
      case 'reservation': onUpdateReservation(payload); break;
      case 'receipt': onUpdateReceipt(payload); break;
      case 'adjustment': onUpdateAdjustment(payload); break;
    }
    setIsModalOpen(false);
  };

  const handleComplete = (item: any) => {
    if (window.confirm(`Are you sure you want to COMPLETE this ${activeTab}? This will update stock levels.`)) {
      onStatusChange(activeTab, item.id, 'Completed');
    }
  };

  const getList = () => {
    switch(activeTab) {
      case 'transfer': return transfers;
      case 'count': return counts;
      case 'reservation': return reservations;
      case 'receipt': return receipts;
      case 'adjustment': return adjustments;
      default: return [];
    }
  };

  const handleDelete = (id: string) => {
    if (!confirm('Delete this document?')) return;
    switch(activeTab) {
      case 'transfer': onDeleteTransfer(id); break;
      case 'count': onDeleteCount(id); break;
      case 'reservation': onDeleteReservation(id); break;
      case 'receipt': onDeleteReceipt(id); break;
      case 'adjustment': onDeleteAdjustment(id); break;
    }
  };

  // Simplified Item Management inside Modal
  const handleAddItem = () => {
    if (!products.length) return;
    const p = products[0];
    const newItem: StockItem = {
      productId: p.id,
      productName: p.name,
      unit: p.unit,
      quantity: 1
    };
    setFormData({ ...formData, items: [...(formData.items || []), newItem] });
  };

  const handleUpdateItem = (index: number, field: string, value: any) => {
    const newItems = [...formData.items];
    if (field === 'productId') {
        const p = products.find(prod => prod.id === value);
        if (p) {
            newItems[index] = { ...newItems[index], productId: p.id, productName: p.name, unit: p.unit };
        }
    } else {
        newItems[index] = { ...newItems[index], [field]: value };
    }
    setFormData({ ...formData, items: newItems });
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...formData.items];
    newItems.splice(index, 1);
    setFormData({ ...formData, items: newItems });
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Stock Management</h2>
          <p className="text-slate-500">Manage stock movements, counts, and adjustments.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium">
          <Plus className="w-4 h-4 mr-2" />
          Create Document
        </button>
      </div>

      {/* Tabs */}
      <div className="flex space-x-1 bg-slate-100 p-1 rounded-lg w-fit">
        {[
          { id: 'transfer', label: 'Transfer', icon: ArrowRightLeft },
          { id: 'receipt', label: 'Receipt (In)', icon: Truck },
          { id: 'adjustment', label: 'Adjustment', icon: SlidersHorizontal },
          { id: 'count', label: 'Count (Audit)', icon: CheckSquare },
          { id: 'reservation', label: 'Reservation', icon: CalendarClock },
        ].map(tab => {
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                activeTab === tab.id ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <Icon className="w-4 h-4 mr-2" />
              {tab.label}
            </button>
          )
        })}
      </div>

      {/* List */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Ref No / Date</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Details</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Items</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Status</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {getList().map((item: any) => (
                <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-800">{item.referenceNo}</div>
                    <div className="text-xs text-slate-500">{new Date(item.date).toLocaleDateString()}</div>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-600">
                    {activeTab === 'transfer' && `From: ${warehouses.find(w => w.id === item.sourceWarehouseId)?.name} To: ${warehouses.find(w => w.id === item.targetWarehouseId)?.name}`}
                    {activeTab === 'receipt' && `Vendor: ${item.vendorName} (Ref: ${item.vendorInvoiceNo})`}
                    {activeTab === 'adjustment' && `Reason: ${item.reason} @ ${warehouses.find(w => w.id === item.warehouseId)?.name}`}
                    {activeTab === 'count' && `Counter: ${item.counterName} @ ${warehouses.find(w => w.id === item.warehouseId)?.name}`}
                    {activeTab === 'reservation' && `Customer: ${item.customerName} (Exp: ${new Date(item.expiryDate).toLocaleDateString()})`}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="bg-slate-100 px-2 py-1 rounded text-xs font-bold text-slate-600">
                      {item.items?.length || 0} items
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold ${
                      item.status === 'Completed' ? 'bg-green-100 text-green-700' : 
                      item.status === 'Approved' ? 'bg-blue-100 text-blue-700' :
                      item.status === 'Cancelled' ? 'bg-red-100 text-red-700' :
                      'bg-orange-100 text-orange-700'
                    }`}>
                      {item.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end space-x-2 items-center">
                      {/* Workflow Actions */}
                      {item.status === 'Approved' && (
                        <button 
                          onClick={() => handleComplete(item)}
                          className="flex items-center px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-bold shadow-sm"
                          title="Execute and Update Stock"
                        >
                          <PlayCircle className="w-3 h-3 mr-1" /> Complete
                        </button>
                      )}

                      {item.status === 'Draft' ? (
                        <>
                          <button onClick={() => handleOpenModal(item)} className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-slate-100 rounded">
                            <Edit2 className="w-4 h-4" />
                          </button>
                          <button onClick={() => handleDelete(item.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-slate-100 rounded">
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </>
                      ) : (
                         <button onClick={() => handleOpenModal(item)} className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-slate-100 rounded" title="View">
                            <FileText className="w-4 h-4" />
                          </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <h3 className="text-xl font-bold text-slate-800 uppercase">
                {editingId ? 'Edit' : 'New'} {activeTab}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSave} className="flex-1 overflow-hidden flex flex-col">
              <div className="p-6 overflow-y-auto flex-1 space-y-4">
                <div className="grid grid-cols-2 gap-4">
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Date</label>
                      <input type="date" required value={formData.date ? new Date(formData.date).toISOString().split('T')[0] : ''} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                   </div>
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Ref No</label>
                      <input type="text" value={formData.referenceNo} onChange={e => setFormData({...formData, referenceNo: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" placeholder="Auto-generated if empty" />
                   </div>
                </div>

                {/* Dynamic Fields based on Type */}
                {activeTab === 'transfer' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Source Warehouse</label>
                         <select required value={formData.sourceWarehouseId} onChange={e => setFormData({...formData, sourceWarehouseId: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white">
                            <option value="">Select Source</option>
                            {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                         </select>
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Target Warehouse</label>
                         <select required value={formData.targetWarehouseId} onChange={e => setFormData({...formData, targetWarehouseId: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white">
                            <option value="">Select Target</option>
                            {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                         </select>
                      </div>
                   </div>
                )}

                {(activeTab === 'adjustment' || activeTab === 'count' || activeTab === 'receipt' || activeTab === 'reservation') && (
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Warehouse</label>
                      <select required value={formData.warehouseId} onChange={e => setFormData({...formData, warehouseId: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white">
                         <option value="">Select Warehouse</option>
                         {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                      </select>
                   </div>
                )}

                {activeTab === 'receipt' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Vendor Name</label>
                         <input type="text" required value={formData.vendorName} onChange={e => setFormData({...formData, vendorName: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Vendor Invoice No</label>
                         <input type="text" value={formData.vendorInvoiceNo} onChange={e => setFormData({...formData, vendorInvoiceNo: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                   </div>
                )}

                {activeTab === 'reservation' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Customer Name</label>
                         <input type="text" required value={formData.customerName} onChange={e => setFormData({...formData, customerName: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Expiry Date</label>
                         <input type="date" required value={formData.expiryDate ? new Date(formData.expiryDate).toISOString().split('T')[0] : ''} onChange={e => setFormData({...formData, expiryDate: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                   </div>
                )}

                {activeTab === 'count' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Counter Name</label>
                         <input type="text" required value={formData.counterName} onChange={e => setFormData({...formData, counterName: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Reason</label>
                         <input type="text" value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                   </div>
                )}

                {activeTab === 'adjustment' && (
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Reason</label>
                      <input type="text" required value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                   </div>
                )}

                <div className="border-t border-slate-100 pt-4">
                   <div className="flex justify-between items-center mb-2">
                      <h4 className="font-bold text-slate-700">Items</h4>
                      <button type="button" onClick={handleAddItem} className="text-sm text-blue-600 hover:underline flex items-center"><Plus className="w-4 h-4 mr-1"/> Add Item</button>
                   </div>
                   <div className="space-y-2">
                      {formData.items?.map((item: any, idx: number) => (
                         <div key={idx} className="flex gap-2 items-center bg-slate-50 p-2 rounded border border-slate-200">
                            <select 
                               value={item.productId} 
                               onChange={e => handleUpdateItem(idx, 'productId', e.target.value)} 
                               className="flex-1 px-2 py-1 border border-slate-300 rounded text-sm bg-white"
                            >
                               {products.map(p => <option key={p.id} value={p.id}>{p.name} ({p.unit})</option>)}
                            </select>

                            {activeTab === 'count' ? (
                               <input 
                                  type="number" 
                                  value={item.countedQuantity || 0} 
                                  onChange={e => handleUpdateItem(idx, 'countedQuantity', parseFloat(e.target.value))} 
                                  className="w-24 px-2 py-1 border border-slate-300 rounded text-sm"
                                  placeholder="Counted"
                               />
                            ) : (
                               <input 
                                  type="number" 
                                  value={item.quantity || 0} 
                                  onChange={e => handleUpdateItem(idx, 'quantity', parseFloat(e.target.value))} 
                                  className="w-24 px-2 py-1 border border-slate-300 rounded text-sm"
                                  placeholder="Qty"
                               />
                            )}

                            <button type="button" onClick={() => handleRemoveItem(idx)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 className="w-4 h-4"/></button>
                         </div>
                      ))}
                      {(!formData.items || formData.items.length === 0) && (
                         <div className="text-center py-4 text-slate-400 text-sm italic">No items added.</div>
                      )}
                   </div>
                </div>
              </div>

              <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 rounded-b-xl">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                {formData.status === 'Draft' && (
                   <button
                      type="submit"
                      className="px-6 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm"
                   >
                      Save Draft
                   </button>
                )}
                {(formData.status !== 'Draft') && (
                   <span className="flex items-center text-slate-500 font-medium px-4">
                      {formData.status === 'Completed' ? <CheckCircle className="w-5 h-5 mr-2 text-green-600" /> : <FileText className="w-5 h-5 mr-2" />} 
                      {formData.status}
                   </span>
                )}
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { 
  Warehouse, Product, StockTransfer, StockCount, StockReservation, StockReceipt, StockAdjustment, 
  DocumentStatus, StockItem 
} from '../types';
import { 
  Plus, Edit2, Trash2, ArrowRightLeft, 
  CheckSquare, CalendarClock, Truck, SlidersHorizontal, 
  X, CheckCircle, FileText, PlayCircle
} from 'lucide-react';

interface StockManagementProps {
  warehouses: Warehouse[];
  products: Product[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  defaultItemsPerPage: number;
  onUpdateTransfer: (t: StockTransfer) => void;
  onDeleteTransfer: (id: string) => void;
  onUpdateCount: (c: StockCount) => void;
  onDeleteCount: (id: string) => void;
  onUpdateReservation: (r: StockReservation) => void;
  onDeleteReservation: (id: string) => void;
  onUpdateReceipt: (r: StockReceipt) => void;
  onDeleteReceipt: (id: string) => void;
  onUpdateAdjustment: (a: StockAdjustment) => void;
  onDeleteAdjustment: (id: string) => void;
  onStatusChange: (type: string, id: string, status: DocumentStatus) => void;
}

export const StockManagement: React.FC<StockManagementProps> = ({
  warehouses, products, transfers, counts, reservations, receipts, adjustments, defaultItemsPerPage,
  onUpdateTransfer, onDeleteTransfer,
  onUpdateCount, onDeleteCount,
  onUpdateReservation, onDeleteReservation,
  onUpdateReceipt, onDeleteReceipt,
  onUpdateAdjustment, onDeleteAdjustment,
  onStatusChange
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment'>('transfer');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<any>({}); 

  // Helper to init form based on tab
  const initForm = () => {
    const common = {
      referenceNo: '',
      date: new Date().toISOString().split('T')[0],
      status: 'Draft',
      items: []
    };

    switch(activeTab) {
      case 'transfer': return { ...common, sourceWarehouseId: '', targetWarehouseId: '' };
      case 'count': return { ...common, warehouseId: '', counterName: '', reason: '' };
      case 'reservation': return { ...common, warehouseId: '', customerName: '', expiryDate: '' };
      case 'receipt': return { ...common, warehouseId: '', vendorName: '', vendorInvoiceNo: '', totalCost: 0 };
      case 'adjustment': return { ...common, warehouseId: '', reason: '' };
    }
  };

  const handleOpenModal = (item?: any) => {
    if (item) {
      setEditingId(item.id);
      setFormData({ ...item });
    } else {
      setEditingId(null);
      setFormData(initForm());
    }
    setIsModalOpen(true);
  };

  const validateForm = () => {
    if (!formData.date) return 'Date is required';

    if (activeTab === 'transfer') {
        if (!formData.sourceWarehouseId) return 'Source Warehouse is required';
        if (!formData.targetWarehouseId) return 'Target Warehouse is required';
        if (formData.sourceWarehouseId === formData.targetWarehouseId) return 'Source and Target warehouses cannot be the same';
    }

    if (['adjustment', 'count', 'receipt', 'reservation'].includes(activeTab)) {
        if (!formData.warehouseId) return 'Warehouse is required';
    }

    if (activeTab === 'receipt' && !formData.vendorName) return 'Vendor Name is required';

    if (activeTab === 'reservation') {
        if (!formData.customerName) return 'Customer Name is required';
        if (!formData.expiryDate) return 'Expiry Date is required';
    }

    if (activeTab === 'count' && !formData.counterName) return 'Counter Name is required';

    if (activeTab === 'adjustment' && !formData.reason) return 'Reason is required';

    return null;
  };

  const handleSave = () => {
    // 1. Validate
    const error = validateForm();
    if (error) {
        alert(error);
        return;
    }

    // 2. Confirm
    if (!window.confirm('Are you sure you want to save this document?')) {
      return;
    }

    const id = editingId || (activeTab === 'transfer' ? `TR-${Date.now()}` : 
                             activeTab === 'count' ? `SC-${Date.now()}` :
                             activeTab === 'reservation' ? `RS-${Date.now()}` :
                             activeTab === 'receipt' ? `RC-${Date.now()}` :
                             `AD-${Date.now()}`);

    // Always save as Draft initially or preserve existing status if editing
    const currentStatus = formData.status === 'Completed' || formData.status === 'Approved' ? formData.status : 'Draft';
    const payload = { ...formData, id, status: currentStatus };

    // Auto-generate Ref No if missing
    if (!payload.referenceNo) {
        payload.referenceNo = `${activeTab.toUpperCase().slice(0,2)}-${new Date().getFullYear()}${new Date().getMonth()+1}-${Math.floor(Math.random()*1000)}`;
    }

    switch (activeTab) {
      case 'transfer': onUpdateTransfer(payload); break;
      case 'count': onUpdateCount(payload); break;
      case 'reservation': onUpdateReservation(payload); break;
      case 'receipt': onUpdateReceipt(payload); break;
      case 'adjustment': onUpdateAdjustment(payload); break;
    }
    setIsModalOpen(false);
  };

  const handleComplete = (item: any) => {
    if (window.confirm(`Are you sure you want to COMPLETE this ${activeTab}? This will update stock levels.`)) {
      onStatusChange(activeTab, item.id, 'Completed');
    }
  };

  const getList = () => {
    switch(activeTab) {
      case 'transfer': return transfers;
      case 'count': return counts;
      case 'reservation': return reservations;
      case 'receipt': return receipts;
      case 'adjustment': return adjustments;
      default: return [];
    }
  };

  const handleDelete = (id: string) => {
    if (!confirm('Delete this document?')) return;
    switch(activeTab) {
      case 'transfer': onDeleteTransfer(id); break;
      case 'count': onDeleteCount(id); break;
      case 'reservation': onDeleteReservation(id); break;
      case 'receipt': onDeleteReceipt(id); break;
      case 'adjustment': onDeleteAdjustment(id); break;
    }
  };

  // Simplified Item Management inside Modal
  const handleAddItem = () => {
    if (!products.length) return;
    const p = products[0];
    const newItem: StockItem = {
      productId: p.id,
      productName: p.name,
      unit: p.unit,
      quantity: 1
    };
    setFormData({ ...formData, items: [...(formData.items || []), newItem] });
  };

  const handleUpdateItem = (index: number, field: string, value: any) => {
    const newItems = [...formData.items];
    if (field === 'productId') {
        const p = products.find(prod => prod.id === value);
        if (p) {
            newItems[index] = { ...newItems[index], productId: p.id, productName: p.name, unit: p.unit };
        }
    } else {
        newItems[index] = { ...newItems[index], [field]: value };
    }
    setFormData({ ...formData, items: newItems });
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...formData.items];
    newItems.splice(index, 1);
    setFormData({ ...formData, items: newItems });
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Stock Management</h2>
          <p className="text-slate-500">Manage stock movements, counts, and adjustments.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium">
          <Plus className="w-4 h-4 mr-2" />
          Create Document
        </button>
      </div>

      {/* Tabs */}
      <div className="flex space-x-1 bg-slate-100 p-1 rounded-lg w-fit">
        {[
          { id: 'transfer', label: 'Transfer', icon: ArrowRightLeft },
          { id: 'receipt', label: 'Receipt (In)', icon: Truck },
          { id: 'adjustment', label: 'Adjustment', icon: SlidersHorizontal },
          { id: 'count', label: 'Count (Audit)', icon: CheckSquare },
          { id: 'reservation', label: 'Reservation', icon: CalendarClock },
        ].map(tab => {
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                activeTab === tab.id ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <Icon className="w-4 h-4 mr-2" />
              {tab.label}
            </button>
          )
        })}
      </div>

      {/* List */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Ref No / Date</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Details</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Items</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Status</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {getList().map((item: any) => (
                <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-800">{item.referenceNo}</div>
                    <div className="text-xs text-slate-500">{new Date(item.date).toLocaleDateString()}</div>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-600">
                    {activeTab === 'transfer' && `From: ${warehouses.find(w => w.id === item.sourceWarehouseId)?.name} To: ${warehouses.find(w => w.id === item.targetWarehouseId)?.name}`}
                    {activeTab === 'receipt' && `Vendor: ${item.vendorName} (Ref: ${item.vendorInvoiceNo})`}
                    {activeTab === 'adjustment' && `Reason: ${item.reason} @ ${warehouses.find(w => w.id === item.warehouseId)?.name}`}
                    {activeTab === 'count' && `Counter: ${item.counterName} @ ${warehouses.find(w => w.id === item.warehouseId)?.name}`}
                    {activeTab === 'reservation' && `Customer: ${item.customerName} (Exp: ${new Date(item.expiryDate).toLocaleDateString()})`}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="bg-slate-100 px-2 py-1 rounded text-xs font-bold text-slate-600">
                      {item.items?.length || 0} items
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold ${
                      item.status === 'Completed' ? 'bg-green-100 text-green-700' : 
                      item.status === 'Approved' ? 'bg-blue-100 text-blue-700' :
                      item.status === 'Cancelled' ? 'bg-red-100 text-red-700' :
                      'bg-orange-100 text-orange-700'
                    }`}>
                      {item.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end space-x-2 items-center">
                      {/* Workflow Actions */}
                      {item.status === 'Approved' && (
                        <button 
                          onClick={() => handleComplete(item)}
                          className="flex items-center px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-bold shadow-sm"
                          title="Execute and Update Stock"
                        >
                          <PlayCircle className="w-3 h-3 mr-1" /> Complete
                        </button>
                      )}

                      {item.status === 'Draft' ? (
                        <>
                          <button onClick={() => handleOpenModal(item)} className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-slate-100 rounded">
                            <Edit2 className="w-4 h-4" />
                          </button>
                          <button onClick={() => handleDelete(item.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-slate-100 rounded">
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </>
                      ) : (
                         <button onClick={() => handleOpenModal(item)} className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-slate-100 rounded" title="View">
                            <FileText className="w-4 h-4" />
                          </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <h3 className="text-xl font-bold text-slate-800 uppercase">
                {editingId ? 'Edit' : 'New'} {activeTab}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="flex-1 overflow-hidden flex flex-col">
              <div className="p-6 overflow-y-auto flex-1 space-y-4">
                <div className="grid grid-cols-2 gap-4">
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Date *</label>
                      <input type="date" required value={formData.date ? new Date(formData.date).toISOString().split('T')[0] : ''} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                   </div>
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Ref No</label>
                      <input type="text" value={formData.referenceNo} onChange={e => setFormData({...formData, referenceNo: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" placeholder="Auto-generated if empty" />
                   </div>
                </div>

                {/* Dynamic Fields based on Type */}
                {activeTab === 'transfer' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Source Warehouse *</label>
                         <select required value={formData.sourceWarehouseId} onChange={e => setFormData({...formData, sourceWarehouseId: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white">
                            <option value="">Select Source</option>
                            {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                         </select>
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Target Warehouse *</label>
                         <select required value={formData.targetWarehouseId} onChange={e => setFormData({...formData, targetWarehouseId: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white">
                            <option value="">Select Target</option>
                            {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                         </select>
                      </div>
                   </div>
                )}

                {(activeTab === 'adjustment' || activeTab === 'count' || activeTab === 'receipt' || activeTab === 'reservation') && (
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Warehouse *</label>
                      <select required value={formData.warehouseId} onChange={e => setFormData({...formData, warehouseId: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white">
                         <option value="">Select Warehouse</option>
                         {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                      </select>
                   </div>
                )}

                {activeTab === 'receipt' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Vendor Name *</label>
                         <input type="text" required value={formData.vendorName} onChange={e => setFormData({...formData, vendorName: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Vendor Invoice No</label>
                         <input type="text" value={formData.vendorInvoiceNo} onChange={e => setFormData({...formData, vendorInvoiceNo: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                   </div>
                )}

                {activeTab === 'reservation' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Customer Name *</label>
                         <input type="text" required value={formData.customerName} onChange={e => setFormData({...formData, customerName: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Expiry Date *</label>
                         <input type="date" required value={formData.expiryDate ? new Date(formData.expiryDate).toISOString().split('T')[0] : ''} onChange={e => setFormData({...formData, expiryDate: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                   </div>
                )}

                {activeTab === 'count' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Counter Name *</label>
                         <input type="text" required value={formData.counterName} onChange={e => setFormData({...formData, counterName: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Reason</label>
                         <input type="text" value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                   </div>
                )}

                {activeTab === 'adjustment' && (
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Reason *</label>
                      <input type="text" required value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                   </div>
                )}

                <div className="border-t border-slate-100 pt-4">
                   <div className="flex justify-between items-center mb-2">
                      <h4 className="font-bold text-slate-700">Items</h4>
                      <button type="button" onClick={handleAddItem} className="text-sm text-blue-600 hover:underline flex items-center"><Plus className="w-4 h-4 mr-1"/> Add Item</button>
                   </div>
                   <div className="space-y-2">
                      {formData.items?.map((item: any, idx: number) => (
                         <div key={idx} className="flex gap-2 items-center bg-slate-50 p-2 rounded border border-slate-200">
                            <select 
                               value={item.productId} 
                               onChange={e => handleUpdateItem(idx, 'productId', e.target.value)} 
                               className="flex-1 px-2 py-1 border border-slate-300 rounded text-sm bg-white"
                            >
                               {products.map(p => <option key={p.id} value={p.id}>{p.name} ({p.unit})</option>)}
                            </select>

                            {activeTab === 'count' ? (
                               <input 
                                  type="number" 
                                  value={item.countedQuantity || 0} 
                                  onChange={e => handleUpdateItem(idx, 'countedQuantity', parseFloat(e.target.value))} 
                                  className="w-24 px-2 py-1 border border-slate-300 rounded text-sm"
                                  placeholder="Counted"
                               />
                            ) : (
                               <input 
                                  type="number" 
                                  value={item.quantity || 0} 
                                  onChange={e => handleUpdateItem(idx, 'quantity', parseFloat(e.target.value))} 
                                  className="w-24 px-2 py-1 border border-slate-300 rounded text-sm"
                                  placeholder="Qty"
                               />
                            )}

                            <button type="button" onClick={() => handleRemoveItem(idx)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 className="w-4 h-4"/></button>
                         </div>
                      ))}
                      {(!formData.items || formData.items.length === 0) && (
                         <div className="text-center py-4 text-slate-400 text-sm italic">No items added.</div>
                      )}
                   </div>
                </div>
              </div>

              <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 rounded-b-xl">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                {formData.status === 'Draft' && (
                   <button
                      type="button"
                      onClick={handleSave}
                      className="px-6 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm"
                   >
                      Save Draft
                   </button>
                )}
                {(formData.status !== 'Draft') && (
                   <span className="flex items-center text-slate-500 font-medium px-4">
                      {formData.status === 'Completed' ? <CheckCircle className="w-5 h-5 mr-2 text-green-600" /> : <FileText className="w-5 h-5 mr-2" />} 
                      {formData.status}
                   </span>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { 
  Warehouse, Product, StockTransfer, StockCount, StockReservation, StockReceipt, StockAdjustment, 
  DocumentStatus, StockItem 
} from '../types';
import { 
  Plus, Edit2, Trash2, ArrowRightLeft, 
  CheckSquare, CalendarClock, Truck, SlidersHorizontal, 
  X, CheckCircle, FileText, PlayCircle, AlertCircle
} from 'lucide-react';

interface StockManagementProps {
  warehouses: Warehouse[];
  products: Product[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  defaultItemsPerPage: number;
  onUpdateTransfer: (t: StockTransfer) => void;
  onDeleteTransfer: (id: string) => void;
  onUpdateCount: (c: StockCount) => void;
  onDeleteCount: (id: string) => void;
  onUpdateReservation: (r: StockReservation) => void;
  onDeleteReservation: (id: string) => void;
  onUpdateReceipt: (r: StockReceipt) => void;
  onDeleteReceipt: (id: string) => void;
  onUpdateAdjustment: (a: StockAdjustment) => void;
  onDeleteAdjustment: (id: string) => void;
  onStatusChange: (type: string, id: string, status: DocumentStatus) => void;
}

export const StockManagement: React.FC<StockManagementProps> = ({
  warehouses, products, transfers, counts, reservations, receipts, adjustments, defaultItemsPerPage,
  onUpdateTransfer, onDeleteTransfer,
  onUpdateCount, onDeleteCount,
  onUpdateReservation, onDeleteReservation,
  onUpdateReceipt, onDeleteReceipt,
  onUpdateAdjustment, onDeleteAdjustment,
  onStatusChange
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment'>('transfer');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<any>({}); 
  const [error, setError] = useState<string | null>(null);

  // Helper to init form based on tab
  const initForm = () => {
    const common = {
      referenceNo: '',
      date: new Date().toISOString().split('T')[0],
      status: 'Draft',
      items: []
    };

    switch(activeTab) {
      case 'transfer': return { ...common, sourceWarehouseId: '', targetWarehouseId: '' };
      case 'count': return { ...common, warehouseId: '', counterName: '', reason: '' };
      case 'reservation': return { ...common, warehouseId: '', customerName: '', expiryDate: '' };
      case 'receipt': return { ...common, warehouseId: '', vendorName: '', vendorInvoiceNo: '', totalCost: 0 };
      case 'adjustment': return { ...common, warehouseId: '', reason: '' };
    }
  };

  const handleOpenModal = (item?: any) => {
    setError(null);
    if (item) {
      setEditingId(item.id);
      setFormData({ ...item });
    } else {
      setEditingId(null);
      setFormData(initForm());
    }
    setIsModalOpen(true);
  };

  const validateForm = () => {
    if (!formData.date) return 'Date is required';

    if (activeTab === 'transfer') {
        if (!formData.sourceWarehouseId) return 'Source Warehouse is required';
        if (!formData.targetWarehouseId) return 'Target Warehouse is required';
        if (formData.sourceWarehouseId === formData.targetWarehouseId) return 'Source and Target warehouses cannot be the same';
    }

    if (['adjustment', 'count', 'receipt', 'reservation'].includes(activeTab)) {
        if (!formData.warehouseId) return 'Warehouse is required';
    }

    if (activeTab === 'receipt' && !formData.vendorName) return 'Vendor Name is required';

    if (activeTab === 'reservation') {
        if (!formData.customerName) return 'Customer Name is required';
        if (!formData.expiryDate) return 'Expiry Date is required';
    }

    if (activeTab === 'count' && !formData.counterName) return 'Counter Name is required';

    if (activeTab === 'adjustment' && !formData.reason) return 'Reason is required';

    return null;
  };

  const handleSave = () => {
    // 1. Validate
    setError(null);
    const validationError = validateForm();
    if (validationError) {
        setError(validationError);
        return;
    }

    const id = editingId || (activeTab === 'transfer' ? `TR-${Date.now()}` : 
                             activeTab === 'count' ? `SC-${Date.now()}` :
                             activeTab === 'reservation' ? `RS-${Date.now()}` :
                             activeTab === 'receipt' ? `RC-${Date.now()}` :
                             `AD-${Date.now()}`);

    // Always save as Draft initially or preserve existing status if editing
    const currentStatus = formData.status === 'Completed' || formData.status === 'Approved' ? formData.status : 'Draft';
    const payload = { ...formData, id, status: currentStatus };

    // Auto-generate Ref No if missing
    if (!payload.referenceNo) {
        payload.referenceNo = `${activeTab.toUpperCase().slice(0,2)}-${new Date().getFullYear()}${new Date().getMonth()+1}-${Math.floor(Math.random()*1000)}`;
    }

    switch (activeTab) {
      case 'transfer': onUpdateTransfer(payload); break;
      case 'count': onUpdateCount(payload); break;
      case 'reservation': onUpdateReservation(payload); break;
      case 'receipt': onUpdateReceipt(payload); break;
      case 'adjustment': onUpdateAdjustment(payload); break;
    }
    setIsModalOpen(false);
  };

  const handleComplete = (item: any) => {
    if (window.confirm(`Are you sure you want to COMPLETE this ${activeTab}? This will update stock levels.`)) {
      onStatusChange(activeTab, item.id, 'Completed');
    }
  };

  const getList = () => {
    switch(activeTab) {
      case 'transfer': return transfers;
      case 'count': return counts;
      case 'reservation': return reservations;
      case 'receipt': return receipts;
      case 'adjustment': return adjustments;
      default: return [];
    }
  };

  const handleDelete = (id: string) => {
    if (!confirm('Delete this document?')) return;
    switch(activeTab) {
      case 'transfer': onDeleteTransfer(id); break;
      case 'count': onDeleteCount(id); break;
      case 'reservation': onDeleteReservation(id); break;
      case 'receipt': onDeleteReceipt(id); break;
      case 'adjustment': onDeleteAdjustment(id); break;
    }
  };

  // Simplified Item Management inside Modal
  const handleAddItem = () => {
    if (!products.length) return;
    const p = products[0];
    const newItem: StockItem = {
      productId: p.id,
      productName: p.name,
      unit: p.unit,
      quantity: 1
    };
    setFormData({ ...formData, items: [...(formData.items || []), newItem] });
  };

  const handleUpdateItem = (index: number, field: string, value: any) => {
    const newItems = [...formData.items];
    if (field === 'productId') {
        const p = products.find(prod => prod.id === value);
        if (p) {
            newItems[index] = { ...newItems[index], productId: p.id, productName: p.name, unit: p.unit };
        }
    } else {
        newItems[index] = { ...newItems[index], [field]: value };
    }
    setFormData({ ...formData, items: newItems });
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...formData.items];
    newItems.splice(index, 1);
    setFormData({ ...formData, items: newItems });
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Stock Management</h2>
          <p className="text-slate-500">Manage stock movements, counts, and adjustments.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium">
          <Plus className="w-4 h-4 mr-2" />
          Create Document
        </button>
      </div>

      {/* Tabs */}
      <div className="flex space-x-1 bg-slate-100 p-1 rounded-lg w-fit">
        {[
          { id: 'transfer', label: 'Transfer', icon: ArrowRightLeft },
          { id: 'receipt', label: 'Receipt (In)', icon: Truck },
          { id: 'adjustment', label: 'Adjustment', icon: SlidersHorizontal },
          { id: 'count', label: 'Count (Audit)', icon: CheckSquare },
          { id: 'reservation', label: 'Reservation', icon: CalendarClock },
        ].map(tab => {
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                activeTab === tab.id ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <Icon className="w-4 h-4 mr-2" />
              {tab.label}
            </button>
          )
        })}
      </div>

      {/* List */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Ref No / Date</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Details</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Items</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Status</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {getList().map((item: any) => (
                <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-800">{item.referenceNo}</div>
                    <div className="text-xs text-slate-500">{new Date(item.date).toLocaleDateString()}</div>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-600">
                    {activeTab === 'transfer' && `From: ${warehouses.find(w => w.id === item.sourceWarehouseId)?.name} To: ${warehouses.find(w => w.id === item.targetWarehouseId)?.name}`}
                    {activeTab === 'receipt' && `Vendor: ${item.vendorName} (Ref: ${item.vendorInvoiceNo})`}
                    {activeTab === 'adjustment' && `Reason: ${item.reason} @ ${warehouses.find(w => w.id === item.warehouseId)?.name}`}
                    {activeTab === 'count' && `Counter: ${item.counterName} @ ${warehouses.find(w => w.id === item.warehouseId)?.name}`}
                    {activeTab === 'reservation' && `Customer: ${item.customerName} (Exp: ${new Date(item.expiryDate).toLocaleDateString()})`}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="bg-slate-100 px-2 py-1 rounded text-xs font-bold text-slate-600">
                      {item.items?.length || 0} items
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold ${
                      item.status === 'Completed' ? 'bg-green-100 text-green-700' : 
                      item.status === 'Approved' ? 'bg-blue-100 text-blue-700' :
                      item.status === 'Cancelled' ? 'bg-red-100 text-red-700' :
                      'bg-orange-100 text-orange-700'
                    }`}>
                      {item.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end space-x-2 items-center">
                      {/* Workflow Actions */}
                      {item.status === 'Approved' && (
                        <button 
                          onClick={() => handleComplete(item)}
                          className="flex items-center px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-bold shadow-sm"
                          title="Execute and Update Stock"
                        >
                          <PlayCircle className="w-3 h-3 mr-1" /> Complete
                        </button>
                      )}

                      {item.status === 'Draft' ? (
                        <>
                          <button onClick={() => handleOpenModal(item)} className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-slate-100 rounded">
                            <Edit2 className="w-4 h-4" />
                          </button>
                          <button onClick={() => handleDelete(item.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-slate-100 rounded">
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </>
                      ) : (
                         <button onClick={() => handleOpenModal(item)} className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-slate-100 rounded" title="View">
                            <FileText className="w-4 h-4" />
                          </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal - High Z-Index to avoid overlap issues */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[60] p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <h3 className="text-xl font-bold text-slate-800 uppercase">
                {editingId ? 'Edit' : 'New'} {activeTab}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="flex-1 overflow-hidden flex flex-col">
              <div className="p-6 overflow-y-auto flex-1 space-y-4">

                {error && (
                  <div className="p-3 bg-red-50 border border-red-100 rounded-lg text-red-600 text-sm flex items-center">
                    <AlertCircle className="w-4 h-4 mr-2 flex-shrink-0" />
                    {error}
                  </div>
                )}

                <div className="grid grid-cols-2 gap-4">
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Date *</label>
                      <input type="date" required value={formData.date ? new Date(formData.date).toISOString().split('T')[0] : ''} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                   </div>
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Ref No</label>
                      <input type="text" value={formData.referenceNo} onChange={e => setFormData({...formData, referenceNo: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" placeholder="Auto-generated if empty" />
                   </div>
                </div>

                {/* Dynamic Fields based on Type */}
                {activeTab === 'transfer' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Source Warehouse *</label>
                         <select required value={formData.sourceWarehouseId} onChange={e => setFormData({...formData, sourceWarehouseId: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white">
                            <option value="">Select Source</option>
                            {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                         </select>
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Target Warehouse *</label>
                         <select required value={formData.targetWarehouseId} onChange={e => setFormData({...formData, targetWarehouseId: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white">
                            <option value="">Select Target</option>
                            {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                         </select>
                      </div>
                   </div>
                )}

                {(activeTab === 'adjustment' || activeTab === 'count' || activeTab === 'receipt' || activeTab === 'reservation') && (
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Warehouse *</label>
                      <select required value={formData.warehouseId} onChange={e => setFormData({...formData, warehouseId: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg bg-white">
                         <option value="">Select Warehouse</option>
                         {warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                      </select>
                   </div>
                )}

                {activeTab === 'receipt' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Vendor Name *</label>
                         <input type="text" required value={formData.vendorName} onChange={e => setFormData({...formData, vendorName: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Vendor Invoice No</label>
                         <input type="text" value={formData.vendorInvoiceNo} onChange={e => setFormData({...formData, vendorInvoiceNo: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                   </div>
                )}

                {activeTab === 'reservation' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Customer Name *</label>
                         <input type="text" required value={formData.customerName} onChange={e => setFormData({...formData, customerName: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Expiry Date *</label>
                         <input type="date" required value={formData.expiryDate ? new Date(formData.expiryDate).toISOString().split('T')[0] : ''} onChange={e => setFormData({...formData, expiryDate: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                   </div>
                )}

                {activeTab === 'count' && (
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Counter Name *</label>
                         <input type="text" required value={formData.counterName} onChange={e => setFormData({...formData, counterName: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Reason</label>
                         <input type="text" value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                      </div>
                   </div>
                )}

                {activeTab === 'adjustment' && (
                   <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Reason *</label>
                      <input type="text" required value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                   </div>
                )}

                <div className="border-t border-slate-100 pt-4">
                   <div className="flex justify-between items-center mb-2">
                      <h4 className="font-bold text-slate-700">Items</h4>
                      <button type="button" onClick={handleAddItem} className="text-sm text-blue-600 hover:underline flex items-center"><Plus className="w-4 h-4 mr-1"/> Add Item</button>
                   </div>
                   <div className="space-y-2">
                      {formData.items?.map((item: any, idx: number) => (
                         <div key={idx} className="flex gap-2 items-center bg-slate-50 p-2 rounded border border-slate-200">
                            <select 
                               value={item.productId} 
                               onChange={e => handleUpdateItem(idx, 'productId', e.target.value)} 
                               className="flex-1 px-2 py-1 border border-slate-300 rounded text-sm bg-white"
                            >
                               {products.map(p => <option key={p.id} value={p.id}>{p.name} ({p.unit})</option>)}
                            </select>

                            {activeTab === 'count' ? (
                               <input 
                                  type="number" 
                                  value={item.countedQuantity || 0} 
                                  onChange={e => handleUpdateItem(idx, 'countedQuantity', parseFloat(e.target.value))} 
                                  className="w-24 px-2 py-1 border border-slate-300 rounded text-sm"
                                  placeholder="Counted"
                               />
                            ) : (
                               <input 
                                  type="number" 
                                  value={item.quantity || 0} 
                                  onChange={e => handleUpdateItem(idx, 'quantity', parseFloat(e.target.value))} 
                                  className="w-24 px-2 py-1 border border-slate-300 rounded text-sm"
                                  placeholder="Qty"
                               />
                            )}

                            <button type="button" onClick={() => handleRemoveItem(idx)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 className="w-4 h-4"/></button>
                         </div>
                      ))}
                      {(!formData.items || formData.items.length === 0) && (
                         <div className="text-center py-4 text-slate-400 text-sm italic">No items added.</div>
                      )}
                   </div>
                </div>
              </div>

              <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 rounded-b-xl">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                {formData.status === 'Draft' && (
                   <button
                      type="button"
                      onClick={handleSave}
                      className="px-6 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm"
                   >
                      Save Draft
                   </button>
                )}
                {(formData.status !== 'Draft') && (
                   <span className="flex items-center text-slate-500 font-medium px-4">
                      {formData.status === 'Completed' ? <CheckCircle className="w-5 h-5 mr-2 text-green-600" /> : <FileText className="w-5 h-5 mr-2" />} 
                      {formData.status}
                   </span>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { 
  Warehouse, Product, StockTransfer, StockCount, StockReservation, StockReceipt, StockAdjustment, 
  DocumentStatus, StockItem 
} from '../types';
import { 
  Plus, Edit2, Trash2, ArrowRightLeft, 
  CheckSquare, CalendarClock, Truck, SlidersHorizontal, 
  X, CheckCircle, FileText, PlayCircle, AlertCircle
} from 'lucide-react';

interface StockManagementProps {
  warehouses: Warehouse[];
  products: Product[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  defaultItemsPerPage: number;
  onUpdateTransfer: (t: StockTransfer) => void;
  onDeleteTransfer: (id: string) => void;
  onUpdateCount: (c: StockCount) => void;
  onDeleteCount: (id: string) => void;
  onUpdateReservation: (r: StockReservation) => void;
  onDeleteReservation: (id: string) => void;
  onUpdateReceipt: (r: StockReceipt) => void;
  onDeleteReceipt: (id: string) => void;
  onUpdateAdjustment: (a: StockAdjustment) => void;
  onDeleteAdjustment: (id: string) => void;
  onStatusChange: (type: string, id: string, status: DocumentStatus) => void;
}

export const StockManagement: React.FC<StockManagementProps> = ({
  warehouses, products, transfers, counts, reservations, receipts, adjustments, defaultItemsPerPage,
  onUpdateTransfer, onDeleteTransfer,
  onUpdateCount, onDeleteCount,
  onUpdateReservation, onDeleteReservation,
  onUpdateReceipt, onDeleteReceipt,
  onUpdateAdjustment, onDeleteAdjustment,
  onStatusChange
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment'>('transfer');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<any>({}); 
  const [error, setError] = useState<string | null>(null);

  // Helper to init form based on tab
  const initForm = () => {
    const common = {
      referenceNo: '',
      date: new Date().toISOString().split('T')[0],
      status: 'Draft',
      items: []
    };

    switch(activeTab) {
      case 'transfer': return { ...common, sourceWarehouseId: '', targetWarehouseId: '' };
      case 'count': return { ...common, warehouseId: '', counterName: '', reason: '' };
      case 'reservation': return { ...common, warehouseId: '', customerName: '', expiryDate: '' };
      case 'receipt': return { ...common, warehouseId: '', vendorName: '', vendorInvoiceNo: '', totalCost: 0 };
      case 'adjustment': return { ...common, warehouseId: '', reason: '' };
    }
  };

  const handleOpenModal = (item?: any) => {
    setError(null);
    if (item) {
      setEditingId(item.id);
      setFormData({ ...item });
    } else {
      setEditingId(null);
      setFormData(initForm());
    }
    setIsModalOpen(true);
  };

  const validateForm = () => {
    if (!formData.date) return 'Date is required';

    if (activeTab === 'transfer') {
        if (!formData.sourceWarehouseId) return 'Source Warehouse is required';
        if (!formData.targetWarehouseId) return 'Target Warehouse is required';
        if (formData.sourceWarehouseId === formData.targetWarehouseId) return 'Source and Target warehouses cannot be the same';
    }

    if (['adjustment', 'count', 'receipt', 'reservation'].includes(activeTab)) {
        if (!formData.warehouseId) return 'Warehouse is required';
    }

    if (activeTab === 'receipt' && !formData.vendorName) return 'Vendor Name is required';

    if (activeTab === 'reservation') {
        if (!formData.customerName) return 'Customer Name is required';
        if (!formData.expiryDate) return 'Expiry Date is required';
    }

    if (activeTab === 'count' && !formData.counterName) return 'Counter Name is required';

    if (activeTab === 'adjustment' && !formData.reason) return 'Reason is required';

    return null;
  };

  const handleSave = () => {
    // 1. Validate
    setError(null);
    const validationError = validateForm();
    if (validationError) {
        setError(validationError);
        return;
    }

    const id = editingId || (activeTab === 'transfer' ? `TR-${Date.now()}` : 
                             activeTab === 'count' ? `SC-${Date.now()}` :
                             activeTab === 'reservation' ? `RS-${Date.now()}` :
                             activeTab === 'receipt' ? `RC-${Date.now()}` :
                             `AD-${Date.now()}`);

    // Always save as Draft initially or preserve existing status if editing
    const currentStatus = formData.status === 'Completed' || formData.status === 'Approved' ? formData.status : 'Draft';
    const payload = { ...formData, id, status: currentStatus };

    // Auto-generate Ref No if missing
    if (!payload.referenceNo) {
        payload.referenceNo = `${activeTab.toUpperCase().slice(0,2)}-${new Date().getFullYear()}${new Date().getMonth()+1}-${Math.floor(Math.random()*1000)}`;
    }

    switch (activeTab) {
      case 'transfer': onUpdateTransfer(payload); break;
      case 'count': onUpdateCount(payload); break;
      case 'reservation': onUpdateReservation(payload); break;
      case 'receipt': onUpdateReceipt(payload); break;
      case 'adjustment': onUpdateAdjustment(payload); break;
    }
    setIsModalOpen(false);
  };

  const handleComplete = (item: any) => {
    if (window.confirm(`Are you sure you want to COMPLETE this ${activeTab}? This will update stock levels.`)) {
      onStatusChange(activeTab, item.id, 'Completed');
    }
  };

  const getList = () => {
    switch(activeTab) {
      case 'transfer': return transfers;
      case 'count': return counts;
      case 'reservation': return reservations;
      case 'receipt': return receipts;
      case 'adjustment': return adjustments;
      default: return [];
    }
  };

  const handleDelete = (id: string) => {
    if (!confirm('Delete this document?')) return;
    switch(activeTab) {
      case 'transfer': onDeleteTransfer(id); break;
      case 'count': onDeleteCount(id); break;
      case 'reservation': onDeleteReservation(id); break;
      case 'receipt': onDeleteReceipt(id); break;
      case 'adjustment': onDeleteAdjustment(id); break;
    }
  };

  // Simplified Item Management inside Modal
  const handleAddItem = () => {
    if (!products.length) return;
    const p = products[0];
    const newItem: StockItem = {
      productId: p.id,
      productName: p.name,
      unit: p.unit,
      quantity: 1
    };
    setFormData({ ...formData, items: [...(formData.items || []), newItem] });
  };

  const handleUpdateItem = (index: number, field: string, value: any) => {
    const newItems = [...formData.items];
    if (field === 'productId') {
        const p = products.find(prod => prod.id === value);
        if (p) {
            newItems[index] = { ...newItems[index], productId: p.id, productName: p.name, unit: p.unit };
        }
    } else {
        newItems[index] = { ...newItems[index], [field]: value };
    }
    setFormData({ ...formData, items: newItems });
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...formData.items];
    newItems.splice(index, 1);
    setFormData({ ...formData, items: newItems });
  };

  const isReadOnly = formData.status !== 'Draft';

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Stock Management</h2>
          <p className="text-slate-500">Manage stock movements, counts, and adjustments.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium">
          <Plus className="w-4 h-4 mr-2" />
          Create Document
        </button>
      </div>

      {/* Tabs */}
      <div className="flex space-x-1 bg-slate-100 p-1 rounded-lg w-fit">
        {[
          { id: 'transfer', label: 'Transfer', icon: ArrowRightLeft },
          { id: 'receipt', label: 'Receipt (In)', icon: Truck },
          { id: 'adjustment', label: 'Adjustment', icon: SlidersHorizontal },
          { id: 'count', label: 'Count (Audit)', icon: CheckSquare },
          { id: 'reservation', label: 'Reservation', icon: CalendarClock },
        ].map(tab => {
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                activeTab === tab.id ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <Icon className="w-4 h-4 mr-2" />
              {tab.label}
            </button>
          )
        })}
      </div>

      {/* List */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Ref No / Date</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Details</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Items</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Status</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Actions</th>
              </tr>
