                                  onChange={e => handleUpdateItem(idx, 'countedQuantity', parseFloat(e.target.value))} 
                                  className="w-24 px-2 py-1 border border-slate-300 rounded text-sm disabled:bg-slate-100"
                                  placeholder="Counted"
