                            ) : (
                               <input 
                                  disabled={isReadOnly}
                                  type="number" 
                                  value={item.quantity || 0} 
                                  onChange={e => handleUpdateItem(idx, 'quantity', parseFloat(e.target.value))} 
                                  className="w-24 px-2 py-1 border border-slate-300 rounded text-sm disabled:bg-slate-100"
                                  placeholder="Qty"
                               />
