const handleStockStatusChange = async (type: string, id: string, status: DocumentStatus) => {
  // 1. Identify the document and prepare update
  let currentDoc: any = null;
  switch (type) {
    case 'transfer': currentDoc = transfers.find(d => d.id === id); break;
    case 'count': currentDoc = counts.find(d => d.id === id); break;
    case 'reservation': currentDoc = reservations.find(d => d.id === id); break;
    case 'receipt': currentDoc = receipts.find(d => d.id === id); break;
    case 'adjustment': currentDoc = adjustments.find(d => d.id === id); break;
  }

  if (!currentDoc) return;

  const docToUpdate = { ...currentDoc, status };

  // 2. Update the specific list state
  const updateList = (prev: any[]) => prev.map(d => d.id === id ? docToUpdate : d);

  switch (type) {
    case 'transfer': setTransfers(updateList); break;
    case 'count': setCounts(updateList); break;
    case 'reservation': setReservations(updateList); break;
    case 'receipt': setReceipts(updateList); break;
    case 'adjustment': setAdjustments(updateList); break;
  }

  // 3. Apply Stock Change ONLY if status becomes Completed
  // This supports the flow: Draft -> Approved (Manager) -> Completed (Stock Update)
  if (status === 'Completed') {
     applyStockChanges(docToUpdate, type);
  }

  await mockApiCall(null);
};

