  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [sales, setSales] = useState<Sale[]>(INITIAL_SALES);
  const [units, setUnits] = useState<UnitDefinition[]>(INITIAL_UNITS);
  const [categories, setCategories] = useState<CategoryItem[]>(INITIAL_CATEGORIES_TREE);
  const [branches, setBranches] = useState<Branch[]>(INITIAL_BRANCHES);
  const [posMachines, setPosMachines] = useState<PosMachine[]>(INITIAL_POS_MACHINES);
  const [warehouses, setWarehouses] = useState<Warehouse[]>(INITIAL_WAREHOUSES);
  const [locations, setLocations] = useState<StorageLocation[]>(INITIAL_LOCATIONS);
  const [transfers, setTransfers] = useState<StockTransfer[]>(INITIAL_TRANSFERS);
  const [counts, setCounts] = useState<StockCount[]>(INITIAL_COUNTS);
  const [reservations, setReservations] = useState<StockReservation[]>(INITIAL_RESERVATIONS);
  const [receipts, setReceipts] = useState<StockReceipt[]>(INITIAL_RECEIPTS);
  const [adjustments, setAdjustments] = useState<StockAdjustment[]>(INITIAL_ADJUSTMENTS);
  const [syncLogs, setSyncLogs] = useState<SyncLog[]>(INITIAL_SYNC_LOGS);
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [customerLevels, setCustomerLevels] = useState<CustomerLevel[]>(INITIAL_CUSTOMER_LEVELS);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [shiftSchedules, setShiftSchedules] = useState<ShiftSchedule[]>(INITIAL_SHIFT_SCHEDULES);
  const [promotions, setPromotions] = useState<Promotion[]>(INITIAL_PROMOTIONS);
  const [settings, setSettings] = useState<SystemSettings>(INITIAL_SETTINGS);

  // Helper for translations
  const t = (key: string): string => {
    const keys = key.split('.');
    let value: any = translations[settings.language] || translations['en'];
    for (const k of keys) {
      value = value?.[k];
    }
    return value || key;
  };

  // --- CRUD Functions ---

  // Products
  const addProduct = (product: Product) => setProducts(prev => [...prev, product]);
  const updateProduct = (product: Product) => setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  const deleteProduct = (id: string) => setProducts(prev => prev.filter(p => p.id !== id));

  // Units
  const addUnit = (unit: UnitDefinition) => setUnits(prev => [...prev, unit]);
  const updateUnit = (unit: UnitDefinition) => setUnits(prev => prev.map(u => u.id === unit.id ? unit : u));
  const deleteUnit = (id: string) => setUnits(prev => prev.filter(u => u.id !== id));

  // Categories
  const addCategory = (category: CategoryItem) => setCategories(prev => [...prev, category]);
  const updateCategory = (category: CategoryItem) => setCategories(prev => prev.map(c => c.id === category.id ? category : c));
  const deleteCategory = (id: string) => setCategories(prev => prev.filter(c => c.id !== id));

  // Branches & POS
  const addBranch = (branch: Branch) => setBranches(prev => [...prev, branch]);
  const updateBranch = (branch: Branch) => setBranches(prev => prev.map(b => b.id === branch.id ? branch : b));
  const deleteBranch = (id: string) => setBranches(prev => prev.filter(b => b.id !== id));

  const addPos = (pos: PosMachine) => setPosMachines(prev => [...prev, pos]);
  const updatePos = (pos: PosMachine) => setPosMachines(prev => prev.map(p => p.id === pos.id ? pos : p));
  const deletePos = (id: string) => setPosMachines(prev => prev.filter(p => p.id !== id));

  // Warehouse & Location
  const addWarehouse = (wh: Warehouse) => setWarehouses(prev => [...prev, wh]);
  const updateWarehouse = (wh: Warehouse) => setWarehouses(prev => prev.map(w => w.id === wh.id ? wh : w));
  const deleteWarehouse = (id: string) => setWarehouses(prev => prev.filter(w => w.id !== id));

  const addLocation = (loc: StorageLocation) => setLocations(prev => [...prev, loc]);
  const updateLocation = (loc: StorageLocation) => setLocations(prev => prev.map(l => l.id === loc.id ? loc : l));
  const deleteLocation = (id: string) => setLocations(prev => prev.filter(l => l.id !== id));

  // Users
  const addUser = (user: User) => setUsers(prev => [...prev, user]);
  const updateUser = (user: User) => setUsers(prev => prev.map(u => u.id === user.id ? user : u));
  const deleteUser = (id: string) => setUsers(prev => prev.filter(u => u.id !== id));

  // Customers
  const addCustomer = (customer: Customer) => setCustomers(prev => [...prev, customer]);
  const updateCustomer = (customer: Customer) => setCustomers(prev => prev.map(c => c.id === customer.id ? customer : c));
  const deleteCustomer = (id: string) => setCustomers(prev => prev.filter(c => c.id !== id));

  const addCustomerLevel = (level: CustomerLevel) => setCustomerLevels(prev => [...prev, level]);
  const updateCustomerLevel = (level: CustomerLevel) => setCustomerLevels(prev => prev.map(l => l.id === level.id ? level : l));
  const deleteCustomerLevel = (id: string) => setCustomerLevels(prev => prev.filter(l => l.id !== id));

  // Stock Documents
  const updateTransfer = (transfer: StockTransfer) => setTransfers(prev => prev.map(t => t.id === transfer.id ? transfer : t));
  const deleteTransfer = (id: string) => setTransfers(prev => prev.filter(t => t.id !== id));

  const updateCount = (count: StockCount) => setCounts(prev => prev.map(c => c.id === count.id ? count : c));
  const deleteCount = (id: string) => setCounts(prev => prev.filter(c => c.id !== id));

  const updateReservation = (res: StockReservation) => setReservations(prev => prev.map(r => r.id === res.id ? res : r));
  const deleteReservation = (id: string) => setReservations(prev => prev.filter(r => r.id !== id));

  const updateReceipt = (receipt: StockReceipt) => setReceipts(prev => prev.map(r => r.id === receipt.id ? receipt : r));
  const deleteReceipt = (id: string) => setReceipts(prev => prev.filter(r => r.id !== id));

  const updateAdjustment = (adj: StockAdjustment) => setAdjustments(prev => prev.map(a => a.id === adj.id ? adj : a));
  const deleteAdjustment = (id: string) => setAdjustments(prev => prev.filter(a => a.id !== id));

  // Shift Management
  const startShift = (branchId: string, startCash: number, notes?: string) => {
    if (!currentUser) return;
    const newShift: Shift = {
      id: `sh-${Date.now()}`,
      userId: currentUser.id,
      branchId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open'
    };
    setShifts(prev => [newShift, ...prev]);
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
    setShifts(prev => prev.map(s => {
      if (s.id === shiftId) {
        return {
          ...s,
          endTime: new Date().toISOString(),
          endCash,
          notes: notes || s.notes,
          status: 'Closed'
        };
      }
      return s;
    }));
  };

  const addShiftSchedule = (schedule: ShiftSchedule) => setShiftSchedules(prev => [...prev, schedule]);
  const deleteShiftSchedule = (id: string) => setShiftSchedules(prev => prev.filter(s => s.id !== id));

  // Promotions
  const addPromotion = (promo: Promotion) => setPromotions(prev => [...prev, promo]);
  const updatePromotion = (promo: Promotion) => setPromotions(prev => prev.map(p => p.id === promo.id ? promo : p));
  const deletePromotion = (id: string) => setPromotions(prev => prev.filter(p => p.id !== id));

  // Settings
  const updateSettings = (newSettings: SystemSettings) => setSettings(newSettings);

  // --- Complex Actions ---

  const processSale = async (items: CartItem[], total: number, customerId?: string, discountAmount?: number, subtotal?: number, paymentMethod: string = 'cash', amountReceived: number = 0, change: number = 0): Promise<Sale> => {
    const sale: Sale = {
      id: `S-${Date.now()}`,
      items,
      total,
      subtotal,
      discountAmount,
      date: new Date().toISOString(),
      paymentMethod: paymentMethod as any,
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      amountReceived,
      change,
      remainingAmount: paymentMethod === 'credit' ? (total - amountReceived) : 0,
      status: 'completed',
      syncStatus: 'pending',
      customerId,
      customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined
    };

    setSales(prev => [sale, ...prev]);

    // Update Stock
    items.forEach(item => {
      // Simplified: Just reducing from main stock for now
      // In real app, check variant conversion and reduce
      const reduceQty = item.quantity * (item.sellConversionFactor || 1);

      setProducts(prev => prev.map(p => {
        if (p.id === item.id) {
          const newStock = Math.max(0, p.stock - reduceQty);
          return { ...p, stock: newStock };
        }
        return p;
      }));
    });

    // Update Customer Loyalty
    if (customerId) {
      const points = Math.floor(total / 10); // 1 point per $10
      setCustomers(prev => prev.map(c => 
        c.id === customerId 
          ? { ...c, loyaltyPoints: c.loyaltyPoints + points } 
          : c
      ));
    }

    return sale;
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
    setSales(prev => prev.map(sale => {
      if (sale.id === saleId) {
        return {
          ...sale,
          paymentStatus: 'paid',
          remainingAmount: 0,
          amountReceived: (sale.amountReceived || 0) + amount
        };
      }
      return sale;
    }));
  };

  const handleVoidSale = (id: string) => {
    const saleToVoid = sales.find(s => s.id === id);
    if (!saleToVoid) return;

    setSales(prev => prev.map(s => s.id === id ? { ...s, status: 'voided' } : s));

    // Restore Stock
    saleToVoid.items.forEach(item => {
      const restoreQty = item.quantity * (item.sellConversionFactor || 1);
      setProducts(prev => prev.map(p => {
        if (p.id === item.id) {
          return { ...p, stock: p.stock + restoreQty };
        }
        return p;
      }));
    });
  };

  const handleStockStatusChange = (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => {
    const updateList = (list: any[], setList: any) => {
      setList(list.map((item: any) => item.id === id ? { ...item, status } : item));
    };

    switch (type) {
      case 'transfer': updateList(transfers, setTransfers); break;
      case 'count': updateList(counts, setCounts); break;
      case 'reservation': updateList(reservations, setReservations); break;
      case 'receipt': updateList(receipts, setReceipts); break;
      case 'adjustment': updateList(adjustments, setAdjustments); break;
    }

    // Execution Logic (if Completed/Approved)
    if ((status === 'Completed' || status === 'Approved') && type !== 'reservation') {
      // Find the document
      let doc: any;
      if (type === 'transfer') doc = transfers.find(t => t.id === id);
      else if (type === 'count') doc = counts.find(c => c.id === id);
      else if (type === 'receipt') doc = receipts.find(r => r.id === id);
      else if (type === 'adjustment') doc = adjustments.find(a => a.id === id);

      if (doc) {
        doc.items.forEach((item: any) => {
          setProducts(prev => prev.map(p => {
            if (p.id === item.productId) {
              let change = 0;
              if (type === 'transfer') {
                 // Complex handling for multi-warehouse needed, simplified here:
                 // In single global stock view, transfer doesn't change total stock unless we track per warehouse in Product
                 // But we do track p.warehouseInventory. 
                 // Updating global stock only makes sense if we sum warehouseInventory.
                 // For now, let's assume we update the specific warehouse entries in `p.warehouseInventory`
              } else if (type === 'count') {
                 if (item.countedQuantity !== undefined) {
                    // This is an absolute set, hard to do with simple delta.
                    // Simplified: We assume `stock` is aggregate.
                    // Real logic needs per-warehouse stock update.
                 }
              } else if (type === 'receipt') {
                 change = item.quantity;
              } else if (type === 'adjustment') {
                 change = item.quantity;
              }

              if (change !== 0) {
                 return { ...p, stock: p.stock + change };
              }
            }
            return p;
          }));
        });
      }
    }
  };

  const handleSyncOperation = (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
    const newLog: SyncLog = {
      id: `log-${Date.now()}`,
      timestamp: new Date().toISOString(),
      type,
      status: 'Success',
      details: type === 'Push' ? `Uploaded ${sales.filter(s => s.syncStatus === 'pending').length} sales` : 'Synced successfully',
      durationMs: Math.floor(Math.random() * 1000) + 200
    };
    setSyncLogs(prev => [newLog, ...prev]);

    if (type === 'Push' || type === 'Manual') {
       setSales(prev => prev.map(s => ({ ...s, syncStatus: 'synced' })));
    }
  };

  return (
    <GlobalContext.Provider value={{
      currentUser, setCurrentUser,
      users, products, sales, units, categories, branches, posMachines, warehouses, locations,
      transfers, counts, reservations, receipts, adjustments, syncLogs, customers, customerLevels,
      shifts, shiftSchedules, promotions, settings,
      processSale, settleSaleDebt, handleVoidSale,
      addProduct, updateProduct, deleteProduct,
      addUnit, updateUnit, deleteUnit,
      addCategory, updateCategory, deleteCategory,
      addBranch, updateBranch, deleteBranch,
      addPos, updatePos, deletePos,
      addWarehouse, updateWarehouse, deleteWarehouse,
      addLocation, updateLocation, deleteLocation,
      addUser, updateUser, deleteUser,
      addCustomer, updateCustomer, deleteCustomer,
      addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,
      updateTransfer, deleteTransfer,
      updateCount, deleteCount,
      updateReservation, deleteReservation,
      updateReceipt, deleteReceipt,
      updateAdjustment, deleteAdjustment,
      handleStockStatusChange, handleSyncOperation,
      startShift, endShift, addShiftSchedule, deleteShiftSchedule,
      addPromotion, updatePromotion, deletePromotion,
      updateSettings, t
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { Warehouse, Product, StockTransfer, StockCount, StockReservation, StockReceipt, StockAdjustment, DocumentStatus } from '../types';
