  INITIAL_CUSTOMER_LEVELS 
} from '../services/data';
import { translations } from '../services/translations';

interface GlobalContextType {
  // State
  currentUser: User | null;
  users: User[];
  products: Product[];
  sales: Sale[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  branches: Branch[];
  posMachines: PosMachine[];
  warehouses: Warehouse[];
  locations: StorageLocation[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  syncLogs: SyncLog[];
  customers: Customer[];
  customerLevels: CustomerLevel[];
  shifts: Shift[];
  shiftSchedules: ShiftSchedule[];
  promotions: Promotion[];
  settings: SystemSettings;

  // Setters
  setCurrentUser: (user: User | null) => void;

  // Actions
  processSale: (items: CartItem[], total: number, customerId?: string, discountAmount?: number, subtotal?: number, paymentMethod?: any, amountReceived?: number, change?: number) => Promise<Sale>;
  settleSaleDebt: (saleId: string, amount: number, method: string) => Promise<void>;
  handleVoidSale: (id: string) => void;

  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;

  addUnit: (unit: UnitDefinition) => void;
  updateUnit: (unit: UnitDefinition) => void;
  deleteUnit: (id: string) => void;

  addCategory: (category: CategoryItem) => void;
  updateCategory: (category: CategoryItem) => void;
  deleteCategory: (id: string) => void;

  addBranch: (branch: Branch) => void;
  updateBranch: (branch: Branch) => void;
  deleteBranch: (id: string) => void;

  addPos: (pos: PosMachine) => void;
  updatePos: (pos: PosMachine) => void;
  deletePos: (id: string) => void;

  addWarehouse: (wh: Warehouse) => void;
  updateWarehouse: (wh: Warehouse) => void;
  deleteWarehouse: (id: string) => void;

  addLocation: (loc: StorageLocation) => void;
  updateLocation: (loc: StorageLocation) => void;
  deleteLocation: (id: string) => void;

  addUser: (user: User) => void;
  updateUser: (user: User) => void;
  deleteUser: (id: string) => void;

  addCustomer: (customer: Customer) => void;
  updateCustomer: (customer: Customer) => void;
  deleteCustomer: (id: string) => void;

  addCustomerLevel: (level: CustomerLevel) => void;
  updateCustomerLevel: (level: CustomerLevel) => void;
  deleteCustomerLevel: (id: string) => void;

  updateTransfer: (t: StockTransfer) => void;
  deleteTransfer: (id: string) => void;

  updateCount: (c: StockCount) => void;
  deleteCount: (id: string) => void;

  updateReservation: (r: StockReservation) => void;
  deleteReservation: (id: string) => void;

  updateReceipt: (r: StockReceipt) => void;
  deleteReceipt: (id: string) => void;

  updateAdjustment: (a: StockAdjustment) => void;
  deleteAdjustment: (id: string) => void;

  handleStockStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;

  handleSyncOperation: (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => void;

  startShift: (branchId: string, startCash: number, notes?: string) => void;
  endShift: (shiftId: string, endCash: number, notes?: string) => void;

  addShiftSchedule: (schedule: ShiftSchedule) => void;
  deleteShiftSchedule: (id: string) => void;

  addPromotion: (promo: Promotion) => void;
  updatePromotion: (promo: Promotion) => void;
  deletePromotion: (id: string) => void;

  updateSettings: (settings: SystemSettings) => void;

  t: (key: string) => string;
}

const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

export const GlobalProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // State
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [sales, setSales] = useState<Sale[]>(INITIAL_SALES);
  const [units, setUnits] = useState<UnitDefinition[]>(INITIAL_UNITS);
  const [categories, setCategories] = useState<CategoryItem[]>(INITIAL_CATEGORIES_TREE);
  const [branches, setBranches] = useState<Branch[]>(INITIAL_BRANCHES);
  const [posMachines, setPosMachines] = useState<PosMachine[]>(INITIAL_POS_MACHINES);
  const [warehouses, setWarehouses] = useState<Warehouse[]>(INITIAL_WAREHOUSES);
  const [locations, setLocations] = useState<StorageLocation[]>(INITIAL_LOCATIONS);
  const [transfers, setTransfers] = useState<StockTransfer[]>(INITIAL_TRANSFERS);
  const [counts, setCounts] = useState<StockCount[]>(INITIAL_COUNTS);
  const [reservations, setReservations] = useState<StockReservation[]>(INITIAL_RESERVATIONS);
  const [receipts, setReceipts] = useState<StockReceipt[]>(INITIAL_RECEIPTS);
  const [adjustments, setAdjustments] = useState<StockAdjustment[]>(INITIAL_ADJUSTMENTS);
  const [syncLogs, setSyncLogs] = useState<SyncLog[]>(INITIAL_SYNC_LOGS);
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [customerLevels, setCustomerLevels] = useState<CustomerLevel[]>(INITIAL_CUSTOMER_LEVELS);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [shiftSchedules, setShiftSchedules] = useState<ShiftSchedule[]>(INITIAL_SHIFT_SCHEDULES);
  const [promotions, setPromotions] = useState<Promotion[]>(INITIAL_PROMOTIONS);
  const [settings, setSettings] = useState<SystemSettings>(INITIAL_SETTINGS);

  // Translation Helper
  const t = (key: string) => {
    const keys = key.split('.');
    let value: any = translations[settings.language as keyof typeof translations] || translations['en'];
    for (const k of keys) {
      if (value && value[k]) {
        value = value[k];
      } else {
        return key;
      }
    }
    return value as string;
  };

  // Actions
  const processSale = async (items: CartItem[], total: number, customerId?: string, discountAmount?: number, subtotal?: number, paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit', amountReceived?: number, change?: number): Promise<Sale> => {
    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items: items,
      total: total,
      subtotal: subtotal || total,
      discountAmount: discountAmount || 0,
      customerId: customerId,
      customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined,
      date: new Date().toISOString(),
      paymentMethod: paymentMethod || 'cash',
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      amountReceived,
      change,
      remainingAmount: paymentMethod === 'credit' ? (total - (amountReceived || 0)) : 0,
      status: 'completed',
      syncStatus: 'pending'
    };

    setSales(prev => [newSale, ...prev]);

    // Update Stock
    setProducts(prevProducts => {
      return prevProducts.map(product => {
        const cartItem = items.find(item => item.id === product.id);
        if (cartItem) {
          // Simplistic stock deduction. In reality, consider variants and warehouse specifics.
          // Deduct from total stock for now.
          let deduction = cartItem.quantity;
          if (cartItem.selectedVariantId) {
             const variant = product.variants?.find(v => v.id === cartItem.selectedVariantId);
             if (variant && variant.conversionFactor) {
                deduction = cartItem.quantity * variant.conversionFactor;
             }
          }
          return { ...product, stock: Math.max(0, product.stock - deduction) };
        }
        return product;
      });
    });

    // Update Customer Loyalty
    if (customerId) {
       setCustomers(prev => prev.map(c => {
          if (c.id === customerId) {
             return { ...c, loyaltyPoints: c.loyaltyPoints + Math.floor(total / 10) }; // 1 pt per $10
          }
          return c;
       }));
    }

    return newSale;
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
     setSales(prev => prev.map(sale => {
        if (sale.id === saleId) {
           const newRemaining = (sale.remainingAmount || 0) - amount;
           const newStatus = newRemaining <= 0.01 ? 'paid' : 'partial'; // float tolerance
           return { 
              ...sale, 
              remainingAmount: Math.max(0, newRemaining), 
              paymentStatus: newStatus,
              amountReceived: (sale.amountReceived || 0) + amount 
           };
        }
        return sale;
     }));
  };

  const handleVoidSale = (id: string) => {
    const saleToVoid = sales.find(s => s.id === id);
    if (!saleToVoid) return;

    setSales(prev => prev.map(s => s.id === id ? { ...s, status: 'voided' } : s));

    // Restore Stock
    setProducts(prevProducts => {
      return prevProducts.map(product => {
        const cartItem = saleToVoid.items.find(item => item.id === product.id);
        if (cartItem) {
          let restoration = cartItem.quantity;
          if (cartItem.selectedVariantId) {
             const variant = product.variants?.find(v => v.id === cartItem.selectedVariantId);
             if (variant && variant.conversionFactor) {
                restoration = cartItem.quantity * variant.conversionFactor;
             }
          }
          return { ...product, stock: product.stock + restoration };
        }
        return product;
      });
    });
  };

  // CRUD Implementations
  const addProduct = (product: Product) => setProducts(prev => [...prev, product]);
  const updateProduct = (product: Product) => setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  const deleteProduct = (id: string) => setProducts(prev => prev.filter(p => p.id !== id));

  const addUnit = (unit: UnitDefinition) => setUnits(prev => [...prev, unit]);
  const updateUnit = (unit: UnitDefinition) => setUnits(prev => prev.map(u => u.id === unit.id ? unit : u));
  const deleteUnit = (id: string) => setUnits(prev => prev.filter(u => u.id !== id));

  const addCategory = (category: CategoryItem) => setCategories(prev => [...prev, category]);
  const updateCategory = (category: CategoryItem) => setCategories(prev => prev.map(c => c.id === category.id ? category : c));
  const deleteCategory = (id: string) => setCategories(prev => prev.filter(c => c.id !== id));

  const addBranch = (branch: Branch) => setBranches(prev => [...prev, branch]);
  const updateBranch = (branch: Branch) => setBranches(prev => prev.map(b => b.id === branch.id ? branch : b));
  const deleteBranch = (id: string) => setBranches(prev => prev.filter(b => b.id !== id));

  const addPos = (pos: PosMachine) => setPosMachines(prev => [...prev, pos]);
  const updatePos = (pos: PosMachine) => setPosMachines(prev => prev.map(p => p.id === pos.id ? pos : p));
  const deletePos = (id: string) => setPosMachines(prev => prev.filter(p => p.id !== id));

  const addWarehouse = (wh: Warehouse) => setWarehouses(prev => [...prev, wh]);
  const updateWarehouse = (wh: Warehouse) => setWarehouses(prev => prev.map(w => w.id === wh.id ? wh : w));
  const deleteWarehouse = (id: string) => setWarehouses(prev => prev.filter(w => w.id !== id));

  const addLocation = (loc: StorageLocation) => setLocations(prev => [...prev, loc]);
  const updateLocation = (loc: StorageLocation) => setLocations(prev => prev.map(l => l.id === loc.id ? loc : l));
  const deleteLocation = (id: string) => setLocations(prev => prev.filter(l => l.id !== id));

  const addUser = (user: User) => setUsers(prev => [...prev, user]);
  const updateUser = (user: User) => setUsers(prev => prev.map(u => u.id === user.id ? user : u));
  const deleteUser = (id: string) => setUsers(prev => prev.filter(u => u.id !== id));

  const addCustomer = (customer: Customer) => setCustomers(prev => [...prev, customer]);
  const updateCustomer = (customer: Customer) => setCustomers(prev => prev.map(c => c.id === customer.id ? customer : c));
  const deleteCustomer = (id: string) => setCustomers(prev => prev.filter(c => c.id !== id));

  const addCustomerLevel = (level: CustomerLevel) => setCustomerLevels(prev => [...prev, level]);
  const updateCustomerLevel = (level: CustomerLevel) => setCustomerLevels(prev => prev.map(l => l.id === level.id ? level : l));
  const deleteCustomerLevel = (id: string) => setCustomerLevels(prev => prev.filter(l => l.id !== id));

  const updateTransfer = (t: StockTransfer) => {
    if (transfers.some(tr => tr.id === t.id)) {
      setTransfers(prev => prev.map(tr => tr.id === t.id ? t : tr));
    } else {
      setTransfers(prev => [t, ...prev]);
    }
  };
  const deleteTransfer = (id: string) => setTransfers(prev => prev.filter(t => t.id !== id));

  const updateCount = (c: StockCount) => {
    if (counts.some(cnt => cnt.id === c.id)) {
      setCounts(prev => prev.map(cnt => cnt.id === c.id ? c : cnt));
    } else {
      setCounts(prev => [c, ...prev]);
    }
  };
  const deleteCount = (id: string) => setCounts(prev => prev.filter(c => c.id !== id));

  const updateReservation = (r: StockReservation) => {
    if (reservations.some(res => res.id === r.id)) {
      setReservations(prev => prev.map(res => res.id === r.id ? r : res));
    } else {
      setReservations(prev => [r, ...prev]);
    }
  };
  const deleteReservation = (id: string) => setReservations(prev => prev.filter(r => r.id !== id));

  const updateReceipt = (r: StockReceipt) => {
    if (receipts.some(rec => rec.id === r.id)) {
      setReceipts(prev => prev.map(rec => rec.id === r.id ? r : rec));
    } else {
      setReceipts(prev => [r, ...prev]);
    }
  };
  const deleteReceipt = (id: string) => setReceipts(prev => prev.filter(r => r.id !== id));

  const updateAdjustment = (a: StockAdjustment) => {
    if (adjustments.some(adj => adj.id === a.id)) {
      setAdjustments(prev => prev.map(adj => adj.id === a.id ? a : adj));
    } else {
      setAdjustments(prev => [a, ...prev]);
    }
  };
  const deleteAdjustment = (id: string) => setAdjustments(prev => prev.filter(a => a.id !== id));

  const handleStockStatusChange = (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => {
    const updateStateList = (setList: React.Dispatch<React.SetStateAction<any[]>>) => {
      setList(prev => prev.map(item => item.id === id ? { ...item, status } : item));
    };

    switch (type) {
      case 'transfer': updateStateList(setTransfers); break;
      case 'count': updateStateList(setCounts); break;
      case 'reservation': updateStateList(setReservations); break;
      case 'receipt': updateStateList(setReceipts); break;
      case 'adjustment': updateStateList(setAdjustments); break;
    }

    if ((status === 'Completed' || status === 'Approved') && type !== 'reservation') {
       let doc: any = null;
       if (type === 'transfer') doc = transfers.find(t => t.id === id);
       else if (type === 'count') doc = counts.find(c => c.id === id);
       else if (type === 'receipt') doc = receipts.find(r => r.id === id);
       else if (type === 'adjustment') doc = adjustments.find(a => a.id === id);

       if (doc) {
        doc.items.forEach((item: any) => {
          setProducts(prev => prev.map(p => {
            if (p.id === item.productId) {
              let change = 0;
              if (type === 'transfer') {
                 // No global stock change if moving between warehouses in this simple model (unless tracking by WH specifically in Product object)
              } else if (type === 'count') {
                 // For simple demo, if difference exists, adjust
                 if (item.diff !== undefined) {
                    change = item.diff; 
                 }
              } else if (type === 'receipt') {
                 change = item.quantity;
              } else if (type === 'adjustment') {
                 change = item.quantity;
              }

              if (change !== 0) {
                 return { ...p, stock: p.stock + change };
              }
            }
            return p;
          }));
        });
      }
    }
  };

  const handleSyncOperation = (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
    const log: SyncLog = {
      id: `log-${Date.now()}`,
      timestamp: new Date().toISOString(),
      type,
      status: 'Success',
      details: type === 'Pull' ? 'Downloaded updates from master' : 'Uploaded pending transactions',
      durationMs: Math.floor(Math.random() * 1000) + 200
    };
    setSyncLogs(prev => [log, ...prev]);

    if (type === 'Push' || type === 'Auto') {
       setSales(prev => prev.map(s => ({...s, syncStatus: 'synced'})));
    }
  };

  const startShift = (branchId: string, startCash: number, notes?: string) => {
    if (!currentUser) return;
    const newShift: Shift = {
      id: `sh-${Date.now()}`,
      userId: currentUser.id,
      branchId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open'
    };
    setShifts(prev => [newShift, ...prev]);
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
    setShifts(prev => prev.map(s => {
      if (s.id === shiftId) {
        return {
          ...s,
          endTime: new Date().toISOString(),
          endCash,
          notes: notes || s.notes,
          status: 'Closed'
        };
      }
      return s;
    }));
  };

  const addShiftSchedule = (schedule: ShiftSchedule) => setShiftSchedules(prev => [...prev, schedule]);
  const deleteShiftSchedule = (id: string) => setShiftSchedules(prev => prev.filter(s => s.id !== id));

  const addPromotion = (promo: Promotion) => setPromotions(prev => [...prev, promo]);
  const updatePromotion = (promo: Promotion) => setPromotions(prev => prev.map(p => p.id === promo.id ? promo : p));
  const deletePromotion = (id: string) => setPromotions(prev => prev.filter(p => p.id !== id));

  const updateSettings = (newSettings: SystemSettings) => setSettings(newSettings);

  return (
    <GlobalContext.Provider value={{
      currentUser, setCurrentUser, users, products, sales, units, categories, branches, posMachines,
      warehouses, locations, transfers, counts, reservations, receipts, adjustments, syncLogs,
      customers, customerLevels, shifts, shiftSchedules, promotions, settings,

      processSale, settleSaleDebt, handleVoidSale,
      addProduct, updateProduct, deleteProduct,
      addUnit, updateUnit, deleteUnit,
      addCategory, updateCategory, deleteCategory,
      addBranch, updateBranch, deleteBranch,
      addPos, updatePos, deletePos,
      addWarehouse, updateWarehouse, deleteWarehouse,
      addLocation, updateLocation, deleteLocation,
      addUser, updateUser, deleteUser,
      addCustomer, updateCustomer, deleteCustomer,
      addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,
      updateTransfer, deleteTransfer,
      updateCount, deleteCount,
      updateReservation, deleteReservation,
      updateReceipt, deleteReceipt,
      updateAdjustment, deleteAdjustment,
      handleStockStatusChange,
      handleSyncOperation,
      startShift, endShift,
      addShiftSchedule, deleteShiftSchedule,
      addPromotion, updatePromotion, deletePromotion,
      updateSettings,
      t
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { 
  Warehouse, Product, StockTransfer, StockCount, StockReservation, StockReceipt, StockAdjustment, 
  DocumentStatus, StockItem 
} from '../types';
import { 
  Plus, Edit2, Trash2, ArrowRightLeft, 
  CheckSquare, CalendarClock, Truck, SlidersHorizontal, 
  X, CheckCircle, FileText, PlayCircle, AlertCircle
} from 'lucide-react';

interface StockManagementProps {
  warehouses: Warehouse[];
  products: Product[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  defaultItemsPerPage: number;
  onUpdateTransfer: (t: StockTransfer) => void;
  onDeleteTransfer: (id: string) => void;
  onUpdateCount: (c: StockCount) => void;
  onDeleteCount: (id: string) => void;
  onUpdateReservation: (r: StockReservation) => void;
  onDeleteReservation: (id: string) => void;
  onUpdateReceipt: (r: StockReceipt) => void;
  onDeleteReceipt: (id: string) => void;
  onUpdateAdjustment: (a: StockAdjustment) => void;
  onDeleteAdjustment: (id: string) => void;
  onStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
}

export const StockManagement: React.FC<StockManagementProps> = ({
  warehouses, products, transfers, counts, reservations, receipts, adjustments, defaultItemsPerPage,
  onUpdateTransfer, onDeleteTransfer,
  onUpdateCount, onDeleteCount,
  onUpdateReservation, onDeleteReservation,
  onUpdateReceipt, onDeleteReceipt,
  onUpdateAdjustment, onDeleteAdjustment,
  onStatusChange
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment'>('transfer');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<any>({}); 
  const [error, setError] = useState<string | null>(null);

  // Helper to init form based on tab
  const initForm = () => {
    const common = {
      referenceNo: '',
      date: new Date().toISOString().split('T')[0],
      status: 'Draft',
      items: []
    };

    switch(activeTab) {
      case 'transfer': return { ...common, sourceWarehouseId: '', targetWarehouseId: '' };
      case 'count': return { ...common, warehouseId: '', counterName: '', reason: '' };
      case 'reservation': return { ...common, warehouseId: '', customerName: '', expiryDate: '' };
      case 'receipt': return { ...common, warehouseId: '', vendorName: '', vendorInvoiceNo: '', totalCost: 0 };
      case 'adjustment': return { ...common, warehouseId: '', reason: '' };
    }
  };

  const handleOpenModal = (item?: any) => {
    setError(null);
    if (item) {
      setEditingId(item.id);
      setFormData({ ...item });
    } else {
      setEditingId(null);
      setFormData(initForm());
    }
    setIsModalOpen(true);
  };

  const validateForm = () => {
    if (!formData.date) return 'Date is required';

    if (activeTab === 'transfer') {
        if (!formData.sourceWarehouseId) return 'Source Warehouse is required';
        if (!formData.targetWarehouseId) return 'Target Warehouse is required';
        if (formData.sourceWarehouseId === formData.targetWarehouseId) return 'Source and Target warehouses cannot be the same';
    }

    if (['adjustment', 'count', 'receipt', 'reservation'].includes(activeTab)) {
        if (!formData.warehouseId) return 'Warehouse is required';
    }

    if (activeTab === 'receipt' && !formData.vendorName) return 'Vendor Name is required';

    if (activeTab === 'reservation') {
        if (!formData.customerName) return 'Customer Name is required';
        if (!formData.expiryDate) return 'Expiry Date is required';
    }

    if (activeTab === 'count' && !formData.counterName) return 'Counter Name is required';

    if (activeTab === 'adjustment' && !formData.reason) return 'Reason is required';

    return null;
  };

  const handleSave = () => {
    // 1. Validate
    setError(null);
    const validationError = validateForm();
    if (validationError) {
        setError(validationError);
        return;
    }

    const id = editingId || (activeTab === 'transfer' ? `TR-${Date.now()}` : 
                             activeTab === 'count' ? `SC-${Date.now()}` :
                             activeTab === 'reservation' ? `RS-${Date.now()}` :
                             activeTab === 'receipt' ? `RC-${Date.now()}` :
                             `AD-${Date.now()}`);

    // Always save as Draft initially or preserve existing status if editing
    const currentStatus = formData.status === 'Completed' || formData.status === 'Approved' ? formData.status : 'Draft';
    const payload = { ...formData, id, status: currentStatus };

    // Auto-generate Ref No if missing
    if (!payload.referenceNo) {
        payload.referenceNo = `${activeTab.toUpperCase().slice(0,2)}-${new Date().getFullYear()}${new Date().getMonth()+1}-${Math.floor(Math.random()*1000)}`;
    }

    switch (activeTab) {
      case 'transfer': onUpdateTransfer(payload); break;
      case 'count': onUpdateCount(payload); break;
      case 'reservation': onUpdateReservation(payload); break;
      case 'receipt': onUpdateReceipt(payload); break;
      case 'adjustment': onUpdateAdjustment(payload); break;
    }
    setIsModalOpen(false);
  };

  const handleComplete = (item: any) => {
    // Removed window.confirm for better responsiveness as requested.
    // The action is reversible via admin tools or explicitly separate cancel flow if needed,
    // but for this UI, direct action feels better.
    onStatusChange(activeTab, item.id, 'Completed');
  };

  const getList = () => {
    switch(activeTab) {
      case 'transfer': return transfers;
      case 'count': return counts;
      case 'reservation': return reservations;
      case 'receipt': return receipts;
      case 'adjustment': return adjustments;
      default: return [];
    }
  };

  const handleDelete = (id: string) => {
    if (!confirm('Delete this document?')) return;
    switch(activeTab) {
      case 'transfer': onDeleteTransfer(id); break;
      case 'count': onDeleteCount(id); break;
      case 'reservation': onDeleteReservation(id); break;
      case 'receipt': onDeleteReceipt(id); break;
      case 'adjustment': onDeleteAdjustment(id); break;
    }
  };

  // Simplified Item Management inside Modal
  const handleAddItem = () => {
    if (!products.length) return;
    const p = products[0];
    const newItem: StockItem = {
      productId: p.id,
      productName: p.name,
      unit: p.unit,
      quantity: 1
    };
    setFormData({ ...formData, items: [...(formData.items || []), newItem] });
  };

