}

const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // Data State
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [sales, setSales] = useState<Sale[]>(INITIAL_SALES);
  const [units, setUnits] = useState<UnitDefinition[]>(INITIAL_UNITS);
  const [categories, setCategories] = useState<CategoryItem[]>(INITIAL_CATEGORIES_TREE);
  const [branches, setBranches] = useState<Branch[]>(INITIAL_BRANCHES);
  const [posMachines, setPosMachines] = useState<PosMachine[]>(INITIAL_POS_MACHINES);
  const [warehouses, setWarehouses] = useState<Warehouse[]>(INITIAL_WAREHOUSES);
  const [locations, setLocations] = useState<StorageLocation[]>(INITIAL_LOCATIONS);

  // Stock Docs
  const [transfers, setTransfers] = useState<StockTransfer[]>(INITIAL_TRANSFERS);
  const [counts, setCounts] = useState<StockCount[]>(INITIAL_COUNTS);
  const [reservations, setReservations] = useState<StockReservation[]>(INITIAL_RESERVATIONS);
  const [receipts, setReceipts] = useState<StockReceipt[]>(INITIAL_RECEIPTS);
  const [adjustments, setAdjustments] = useState<StockAdjustment[]>(INITIAL_ADJUSTMENTS);

  const [syncLogs, setSyncLogs] = useState<SyncLog[]>(INITIAL_SYNC_LOGS);
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [customerLevels, setCustomerLevels] = useState<CustomerLevel[]>(INITIAL_CUSTOMER_LEVELS);

  const [shifts, setShifts] = useState<Shift[]>([]);
  const [shiftSchedules, setShiftSchedules] = useState<ShiftSchedule[]>(INITIAL_SHIFT_SCHEDULES);
  const [promotions, setPromotions] = useState<Promotion[]>(INITIAL_PROMOTIONS);
  const [settings, setSettingsState] = useState<SystemSettings>(INITIAL_SETTINGS);

  const t = (key: string): string => {
    const keys = key.split('.');
    let current: any = translations[settings.language] || translations['en'];

    for (const k of keys) {
      if (current[k] === undefined) return key;
      current = current[k];
    }
    return typeof current === 'string' ? current : key;
  };

  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number, 
    paymentMethod: any = 'cash',
    amountReceived?: number,
    change?: number
  ): Promise<Sale> => {
    const sale: Sale = {
      id: `S-${Date.now()}`,
      items,
      total,
      subtotal,
      discountAmount,
      date: new Date().toISOString(),
      paymentMethod,
      amountReceived,
      change,
      customerId,
      customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined,
      status: 'completed',
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      remainingAmount: paymentMethod === 'credit' ? Math.max(0, total - (amountReceived || 0)) : 0,
      syncStatus: 'pending'
    };

    setSales(prev => [sale, ...prev]);

    // Update Inventory
    setProducts(prevProducts => {
      return prevProducts.map(product => {
        const cartItem = items.find(item => item.id === product.id);
        if (cartItem) {
          // Simplistic deduction from total stock
          // In real app, deduct from specific warehouse based on session context
          return {
            ...product,
            stock: product.stock - cartItem.quantity
          };
        }
        return product;
      });
    });

    // Update Customer Loyalty
    if (customerId) {
       setCustomers(prev => prev.map(c => {
          if (c.id === customerId) {
             const pointsEarned = Math.floor(total / 10); // 1 point per $10
             return { ...c, loyaltyPoints: c.loyaltyPoints + pointsEarned };
          }
          return c;
       }));
    }

    return sale;
  };

  const handleVoidSale = (saleId: string) => {
     setSales(prev => prev.map(s => {
        if (s.id === saleId) {
           return { ...s, status: 'voided' };
        }
        return s;
     }));

     // Restore Inventory
     const sale = sales.find(s => s.id === saleId);
     if (sale && sale.status !== 'voided') {
        setProducts(prevProducts => {
           return prevProducts.map(product => {
              const cartItem = sale.items.find(item => item.id === product.id);
              if (cartItem) {
                 return { ...product, stock: product.stock + cartItem.quantity };
              }
              return product;
           });
        });
     }
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
     setSales(prev => prev.map(s => {
        if (s.id === saleId) {
           return {
              ...s,
              paymentStatus: 'paid',
              remainingAmount: 0,
              amountReceived: (s.amountReceived || 0) + amount
           };
        }
        return s;
     }));
  };

  // CRUD Helpers
  const addProduct = (p: Product) => setProducts(prev => [...prev, p]);
  const updateProduct = (p: Product) => setProducts(prev => prev.map(item => item.id === p.id ? p : item));
  const deleteProduct = (id: string) => setProducts(prev => prev.filter(item => item.id !== id));

  const addUnit = (u: UnitDefinition) => setUnits(prev => [...prev, u]);
  const updateUnit = (u: UnitDefinition) => setUnits(prev => prev.map(item => item.id === u.id ? u : item));
  const deleteUnit = (id: string) => setUnits(prev => prev.filter(item => item.id !== id));

  const addCategory = (c: CategoryItem) => setCategories(prev => [...prev, c]);
  const updateCategory = (c: CategoryItem) => setCategories(prev => prev.map(item => item.id === c.id ? c : item));
  const deleteCategory = (id: string) => setCategories(prev => prev.filter(item => item.id !== id));

  const addBranch = (b: Branch) => setBranches(prev => [...prev, b]);
  const updateBranch = (b: Branch) => setBranches(prev => prev.map(item => item.id === b.id ? b : item));
  const deleteBranch = (id: string) => setBranches(prev => prev.filter(item => item.id !== id));

  const addPos = (p: PosMachine) => setPosMachines(prev => [...prev, p]);
  const updatePos = (p: PosMachine) => setPosMachines(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePos = (id: string) => setPosMachines(prev => prev.filter(item => item.id !== id));

  const addWarehouse = (w: Warehouse) => setWarehouses(prev => [...prev, w]);
  const updateWarehouse = (w: Warehouse) => setWarehouses(prev => prev.map(item => item.id === w.id ? w : item));
  const deleteWarehouse = (id: string) => setWarehouses(prev => prev.filter(item => item.id !== id));

  const addLocation = (l: StorageLocation) => setLocations(prev => [...prev, l]);
  const updateLocation = (l: StorageLocation) => setLocations(prev => prev.map(item => item.id === l.id ? l : item));
  const deleteLocation = (id: string) => setLocations(prev => prev.filter(item => item.id !== id));

  const addUser = (u: User) => setUsers(prev => [...prev, u]);
  const updateUser = (u: User) => setUsers(prev => prev.map(item => item.id === u.id ? u : item));
  const deleteUser = (id: string) => setUsers(prev => prev.filter(item => item.id !== id));

  const addCustomer = (c: Customer) => setCustomers(prev => [...prev, c]);
  const updateCustomer = (c: Customer) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item));
  const deleteCustomer = (id: string) => setCustomers(prev => prev.filter(item => item.id !== id));

  const addCustomerLevel = (l: CustomerLevel) => setCustomerLevels(prev => [...prev, l]);
  const updateCustomerLevel = (l: CustomerLevel) => setCustomerLevels(prev => prev.map(item => item.id === l.id ? l : item));
  const deleteCustomerLevel = (id: string) => setCustomerLevels(prev => prev.filter(item => item.id !== id));

  const updateTransfer = (t: StockTransfer) => {
     const exists = transfers.find(item => item.id === t.id);
     if (exists) setTransfers(prev => prev.map(item => item.id === t.id ? t : item));
     else setTransfers(prev => [t, ...prev]);
  };
  const deleteTransfer = (id: string) => setTransfers(prev => prev.filter(item => item.id !== id));

  const updateCount = (c: StockCount) => {
     const exists = counts.find(item => item.id === c.id);
     if (exists) setCounts(prev => prev.map(item => item.id === c.id ? c : item));
     else setCounts(prev => [c, ...prev]);
  };
  const deleteCount = (id: string) => setCounts(prev => prev.filter(item => item.id !== id));

  const updateReservation = (r: StockReservation) => {
     const exists = reservations.find(item => item.id === r.id);
     if (exists) setReservations(prev => prev.map(item => item.id === r.id ? r : item));
     else setReservations(prev => [r, ...prev]);
  };
  const deleteReservation = (id: string) => setReservations(prev => prev.filter(item => item.id !== id));

  const updateReceipt = (r: StockReceipt) => {
     const exists = receipts.find(item => item.id === r.id);
     if (exists) setReceipts(prev => prev.map(item => item.id === r.id ? r : item));
     else setReceipts(prev => [r, ...prev]);
  };
  const deleteReceipt = (id: string) => setReceipts(prev => prev.filter(item => item.id !== id));

  const updateAdjustment = (a: StockAdjustment) => {
     const exists = adjustments.find(item => item.id === a.id);
     if (exists) setAdjustments(prev => prev.map(item => item.id === a.id ? a : item));
     else setAdjustments(prev => [a, ...prev]);
  };
  const deleteAdjustment = (id: string) => setAdjustments(prev => prev.filter(item => item.id !== id));

  const updateSettings = (s: SystemSettings) => setSettingsState(s);

  // Status Change Logic
  const handleStockStatusChange = (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => {
    const updateStateList = (setList: React.Dispatch<React.SetStateAction<any[]>>) => {
      setList(prev => prev.map(item => item.id === id ? { ...item, status } : item));
    };

    switch (type) {
      case 'transfer': updateStateList(setTransfers); break;
      case 'count': updateStateList(setCounts); break;
      case 'reservation': updateStateList(setReservations); break;
      case 'receipt': updateStateList(setReceipts); break;
      case 'adjustment': updateStateList(setAdjustments); break;
    }

    if ((status === 'Completed' || status === 'Approved') && type !== 'reservation') {
       let doc: any = null;
       if (type === 'transfer') doc = transfers.find(t => t.id === id);
       else if (type === 'count') doc = counts.find(c => c.id === id);
       else if (type === 'receipt') doc = receipts.find(r => r.id === id);
       else if (type === 'adjustment') doc = adjustments.find(a => a.id === id);

       if (doc) {
        doc.items.forEach((item: any) => {
          setProducts(prev => prev.map(p => {
            if (p.id === item.productId) {
              let change = 0;
              let newWarehouseInventory = p.warehouseInventory ? [...p.warehouseInventory] : [];

              if (type === 'transfer') {
                 // Decrement Source
                 const sourceInvIndex = newWarehouseInventory.findIndex(inv => inv.warehouseId === doc.sourceWarehouseId);
                 if (sourceInvIndex > -1) {
                    newWarehouseInventory[sourceInvIndex] = {
                       ...newWarehouseInventory[sourceInvIndex],
                       quantity: Math.max(0, newWarehouseInventory[sourceInvIndex].quantity - item.quantity)
                    };
                 }

                 // Increment Target
                 const targetInvIndex = newWarehouseInventory.findIndex(inv => inv.warehouseId === doc.targetWarehouseId);
                 if (targetInvIndex > -1) {
                    newWarehouseInventory[targetInvIndex] = {
                       ...newWarehouseInventory[targetInvIndex],
                       quantity: newWarehouseInventory[targetInvIndex].quantity + item.quantity
                    };
                 } else {
                    newWarehouseInventory.push({ warehouseId: doc.targetWarehouseId, quantity: item.quantity });
                 }

                 return { ...p, warehouseInventory: newWarehouseInventory };

              } else if (type === 'count') {
                 if (item.diff !== undefined) {
                    change = item.diff; 
                 } else if (item.countedQuantity !== undefined) {
                    return { ...p, stock: item.countedQuantity };
                 }
              } else if (type === 'receipt') {
                 change = item.quantity;
                 if (doc.warehouseId) {
                    const targetInvIndex = newWarehouseInventory.findIndex(inv => inv.warehouseId === doc.warehouseId);
                    if (targetInvIndex > -1) {
                        newWarehouseInventory[targetInvIndex].quantity += item.quantity;
                    } else {
                        newWarehouseInventory.push({ warehouseId: doc.warehouseId, quantity: item.quantity });
                    }
                    return { ...p, stock: p.stock + change, warehouseInventory: newWarehouseInventory };
                 }
              } else if (type === 'adjustment') {
                 change = item.quantity;
              }

              if (change !== 0) {
                 return { ...p, stock: p.stock + change };
              }
            }
            return p;
          }));
        });
      }
    }
  };

  const handleSyncOperation = (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
     const newLog: SyncLog = {
        id: `log-${Date.now()}`,
        timestamp: new Date().toISOString(),
        type,
        status: 'Success',
        details: type === 'Push' ? 'Uploaded 2 pending items' : type === 'Pull' ? 'Downloaded updates' : 'Synced successfully',
        durationMs: Math.floor(Math.random() * 1000) + 200
     };
     setSyncLogs(prev => [newLog, ...prev]);
  };

  const startShift = (branchId: string, startCash: number, notes?: string) => {
     if (!currentUser) return;
     const newShift: Shift = {
        id: `shift-${Date.now()}`,
        userId: currentUser.id,
        branchId,
        startTime: new Date().toISOString(),
        startCash,
        notes,
        status: 'Open'
     };
     setShifts(prev => [newShift, ...prev]);
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
     setShifts(prev => prev.map(s => {
        if (s.id === shiftId) {
           return {
              ...s,
              endTime: new Date().toISOString(),
              endCash,
              status: 'Closed',
              notes: notes || s.notes
           };
        }
        return s;
     }));
  };

  const addShiftSchedule = (s: ShiftSchedule) => setShiftSchedules(prev => [...prev, s]);
  const deleteShiftSchedule = (id: string) => setShiftSchedules(prev => prev.filter(s => s.id !== id));

  const addPromotion = (p: Promotion) => setPromotions(prev => [...prev, p]);
  const updatePromotion = (p: Promotion) => setPromotions(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePromotion = (id: string) => setPromotions(prev => prev.filter(item => item.id !== id));

  return (
    <GlobalContext.Provider value={{
      currentUser, setCurrentUser,
      users, products, sales, units, categories, branches, posMachines, warehouses, locations,
      transfers, counts, reservations, receipts, adjustments, syncLogs, customers, customerLevels,
      shifts, shiftSchedules, promotions, settings,
      processSale, addProduct, updateProduct, deleteProduct,
      addUnit, updateUnit, deleteUnit, addCategory, updateCategory, deleteCategory,
      addBranch, updateBranch, deleteBranch, addPos, updatePos, deletePos,
      addWarehouse, updateWarehouse, deleteWarehouse, addLocation, updateLocation, deleteLocation,
      addUser, updateUser, deleteUser, addCustomer, updateCustomer, deleteCustomer,
      addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,
      updateTransfer, deleteTransfer, updateCount, deleteCount, updateReservation, deleteReservation,
      updateReceipt, deleteReceipt, updateAdjustment, deleteAdjustment,
      handleStockStatusChange, handleSyncOperation,
      startShift, endShift, addShiftSchedule, deleteShiftSchedule,
      addPromotion, updatePromotion, deletePromotion,
      updateSettings, settleSaleDebt, handleVoidSale, t
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

import React, { useMemo } from 'react';
import { 
  StockTransfer, 
  StockCount, 
  StockReservation, 
  StockReceipt, 
  StockAdjustment,
  DocumentStatus,
  Warehouse
} from '../types';
import { 
  ArrowRightLeft, 
  CheckSquare, 
  CalendarClock, 
  Truck, 
  CheckCircle, 
  XCircle, 
  Clock,
  ShieldAlert,
  SlidersHorizontal
} from 'lucide-react';

interface ApprovalManagementProps {
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  warehouses: Warehouse[];
  onStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
}

export const ApprovalManagement: React.FC<ApprovalManagementProps> = ({
  transfers,
  counts,
  reservations,
  receipts,
  adjustments,
  warehouses,
  onStatusChange
}) => {

  const getWarehouseName = (id: string) => warehouses.find(w => w.id === id)?.name || id;

  // Flatten and normalize data for the list
  const pendingItems = useMemo(() => {
    const list: any[] = [];

    // 1. Transfers
    transfers.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'transfer',
        typeLabel: 'Stock Transfer',
        icon: ArrowRightLeft,
        description: `${item.items.length} items from ${getWarehouseName(item.sourceWarehouseId)} to ${getWarehouseName(item.targetWarehouseId)}`,
        color: 'text-blue-600 bg-blue-50 border-blue-100'
      });
    });

    // 2. Stock Counts
    counts.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'count',
        typeLabel: 'Stock Audit',
        icon: CheckSquare,
        description: `Audit at ${getWarehouseName(item.warehouseId)} by ${item.counterName}`,
        color: 'text-purple-600 bg-purple-50 border-purple-100'
      });
    });

    // 3. Reservations
    reservations.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'reservation',
        typeLabel: 'Reservation',
        icon: CalendarClock,
        description: `For ${item.customerName} (Exp: ${new Date(item.expiryDate).toLocaleDateString()})`,
        color: 'text-orange-600 bg-orange-50 border-orange-100'
      });
    });

    // 4. Receipts
    receipts.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'receipt',
        typeLabel: 'Goods Receipt',
        icon: Truck,
        description: `From ${item.vendorName} (Ref: ${item.vendorInvoiceNo})`,
        color: 'text-green-600 bg-green-50 border-green-100'
      });
    });

    // 5. Adjustments
    adjustments.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'adjustment',
        typeLabel: 'Stock Adjustment',
        icon: SlidersHorizontal,
        description: `${item.reason} at ${getWarehouseName(item.warehouseId)}`,
        color: 'text-pink-600 bg-pink-50 border-pink-100'
      });
    });

    // Sort by date (newest first)
    return list.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transfers, counts, reservations, receipts, adjustments, warehouses]);

  const handleApprove = (e: React.MouseEvent, item: any) => {
    e.stopPropagation();
    // Only Approve. Execution happens in Stock Management via 'Complete'.
    onStatusChange(item.type, item.id, 'Approved');
  };

  const handleReject = (e: React.MouseEvent, item: any) => {
    e.stopPropagation();
    onStatusChange(item.type, item.id, 'Cancelled');
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Approval Center</h2>
          <p className="text-slate-500">Review and approve pending document requests.</p>
        </div>
        <div className="flex items-center space-x-2 bg-white px-4 py-2 rounded-lg shadow-sm border border-slate-200">
          <Clock className="w-5 h-5 text-orange-500" />
          <span className="font-bold text-slate-700">{pendingItems.length}</span>
          <span className="text-slate-500">Pending Requests</span>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        {pendingItems.length === 0 ? (
          <div className="flex flex-col items-center justify-center flex-1 text-slate-400 p-8">
            <div className="bg-slate-50 p-6 rounded-full mb-4">
              <ShieldAlert className="w-12 h-12 text-slate-300" />
            </div>
            <h3 className="text-lg font-medium text-slate-600">All caught up!</h3>
            <p>No pending approvals found.</p>
          </div>
        ) : (
          <div className="overflow-y-auto flex-1">
            <div className="grid grid-cols-1 divide-y divide-slate-100">
              {pendingItems.map((item) => {
                const Icon = item.icon;
                return (
                  <div key={item.id} className="p-6 hover:bg-slate-50 transition-colors flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div className="flex items-start space-x-4">
                      <div className={`p-3 rounded-xl border ${item.color}`}>
                        <Icon className="w-6 h-6" />
                      </div>
                      <div>
                        <div className="flex items-center space-x-2 mb-1">
                          <span className={`px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider rounded-full border bg-white ${item.color.replace('text-', 'border-').replace('bg-', '')}`}>
                            {item.typeLabel}
                          </span>
                          <span className="text-sm text-slate-400 font-mono">
                            {new Date(item.date).toLocaleDateString()}
                          </span>
                        </div>
                        <h3 className="font-bold text-slate-800 text-lg">
                          {item.referenceNo || 'No Reference'}
                        </h3>
                        <p className="text-slate-600 mt-1">
                          {item.description}
                        </p>

                        {/* Items Preview */}
                        <div className="mt-3 flex flex-wrap gap-2">
                           {item.items.slice(0, 3).map((prod: any, idx: number) => {
                             const displayQty = item.type === 'count' ? prod.countedQuantity : prod.quantity;
                             const prefix = (item.type === 'adjustment' && prod.quantity > 0) ? '+' : '';

                             return (
                               <span key={idx} className="inline-flex items-center px-2 py-1 bg-slate-100 text-slate-600 text-xs rounded border border-slate-200">
                                 {prod.productName} 
                                 <span className={`ml-1 font-semibold ${item.type === 'adjustment' && prod.quantity < 0 ? 'text-red-600' : 'text-slate-800'}`}>
                                   x{prefix}{displayQty}
                                 </span>
                               </span>
                             );
                           })}
                           {item.items.length > 3 && (
                             <span className="inline-flex items-center px-2 py-1 bg-slate-100 text-slate-500 text-xs rounded border border-slate-200">
                               +{item.items.length - 3} more
                             </span>
                           )}
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center space-x-3 pl-14 md:pl-0">
                      <button 
                        onClick={(e) => handleReject(e, item)}
                        className="flex items-center px-4 py-2 border border-slate-200 text-slate-600 rounded-lg hover:bg-red-50 hover:text-red-600 hover:border-red-200 transition-colors font-medium text-sm"
                      >
                        <XCircle className="w-4 h-4 mr-2" />
                        Reject
                      </button>
                      <button 
                        onClick={(e) => handleApprove(e, item)}
                        className="flex items-center px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors font-medium shadow-sm hover:shadow-md text-sm"
                      >
                        <CheckCircle className="w-4 h-4 mr-2" />
                        Approve
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { 
  StockTransfer, 
  StockCount, 
  StockReservation, 
  StockReceipt, 
  StockAdjustment,
  DocumentStatus,
  Warehouse
} from '../types';
import { 
  ArrowRightLeft, 
  CheckSquare, 
  CalendarClock, 
  Truck, 
  CheckCircle, 
  XCircle, 
  Clock,
  ShieldAlert,
  SlidersHorizontal
} from 'lucide-react';

interface ApprovalManagementProps {
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  warehouses: Warehouse[];
  onStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
}

export const ApprovalManagement: React.FC<ApprovalManagementProps> = ({
  transfers,
  counts,
  reservations,
  receipts,
  adjustments,
  warehouses,
  onStatusChange
}) => {

  const getWarehouseName = (id: string) => warehouses.find(w => w.id === id)?.name || id;

  // Flatten and normalize data for the list
  const pendingItems = useMemo(() => {
    const list: any[] = [];

    // 1. Transfers
    transfers.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'transfer',
        typeLabel: 'Stock Transfer',
        icon: ArrowRightLeft,
        description: `${item.items.length} items from ${getWarehouseName(item.sourceWarehouseId)} to ${getWarehouseName(item.targetWarehouseId)}`,
        color: 'text-blue-600 bg-blue-50 border-blue-100'
      });
    });

    // 2. Stock Counts
    counts.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'count',
        typeLabel: 'Stock Audit',
        icon: CheckSquare,
        description: `Audit at ${getWarehouseName(item.warehouseId)} by ${item.counterName}`,
        color: 'text-purple-600 bg-purple-50 border-purple-100'
      });
    });

    // 3. Reservations
    reservations.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'reservation',
        typeLabel: 'Reservation',
        icon: CalendarClock,
        description: `For ${item.customerName} (Exp: ${new Date(item.expiryDate).toLocaleDateString()})`,
        color: 'text-orange-600 bg-orange-50 border-orange-100'
      });
    });

    // 4. Receipts
    receipts.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'receipt',
        typeLabel: 'Goods Receipt',
        icon: Truck,
        description: `From ${item.vendorName} (Ref: ${item.vendorInvoiceNo})`,
        color: 'text-green-600 bg-green-50 border-green-100'
      });
    });

    // 5. Adjustments
    adjustments.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'adjustment',
        typeLabel: 'Stock Adjustment',
        icon: SlidersHorizontal,
        description: `${item.reason} at ${getWarehouseName(item.warehouseId)}`,
        color: 'text-pink-600 bg-pink-50 border-pink-100'
      });
    });

    // Sort by date (newest first)
    return list.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transfers, counts, reservations, receipts, adjustments, warehouses]);

  const handleApprove = (e: React.MouseEvent, item: any) => {
    e.stopPropagation();
    // Only Approve. Execution happens in Stock Management via 'Complete'.
    if (window.confirm('Are you sure you want to Approve this request?')) {
      onStatusChange(item.type, item.id, 'Approved');
    }
  };

  const handleReject = (e: React.MouseEvent, item: any) => {
    e.stopPropagation();
    if (window.confirm('Are you sure you want to Reject this request?')) {
      onStatusChange(item.type, item.id, 'Cancelled');
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Approval Center</h2>
          <p className="text-slate-500">Review and approve pending document requests.</p>
        </div>
        <div className="flex items-center space-x-2 bg-white px-4 py-2 rounded-lg shadow-sm border border-slate-200">
          <Clock className="w-5 h-5 text-orange-500" />
          <span className="font-bold text-slate-700">{pendingItems.length}</span>
          <span className="text-slate-500">Pending Requests</span>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        {pendingItems.length === 0 ? (
          <div className="flex flex-col items-center justify-center flex-1 text-slate-400 p-8">
            <div className="bg-slate-50 p-6 rounded-full mb-4">
              <ShieldAlert className="w-12 h-12 text-slate-300" />
            </div>
            <h3 className="text-lg font-medium text-slate-600">All caught up!</h3>
            <p>No pending approvals found.</p>
          </div>
        ) : (
          <div className="overflow-y-auto flex-1">
            <div className="grid grid-cols-1 divide-y divide-slate-100">
              {pendingItems.map((item) => {
                const Icon = item.icon;
                return (
                  <div key={item.id} className="p-6 hover:bg-slate-50 transition-colors flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div className="flex items-start space-x-4">
                      <div className={`p-3 rounded-xl border ${item.color}`}>
                        <Icon className="w-6 h-6" />
                      </div>
                      <div>
                        <div className="flex items-center space-x-2 mb-1">
                          <span className={`px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider rounded-full border bg-white ${item.color.replace('text-', 'border-').replace('bg-', '')}`}>
                            {item.typeLabel}
                          </span>
                          <span className="text-sm text-slate-400 font-mono">
                            {new Date(item.date).toLocaleDateString()}
                          </span>
                        </div>
                        <h3 className="font-bold text-slate-800 text-lg">
                          {item.referenceNo || 'No Reference'}
                        </h3>
                        <p className="text-slate-600 mt-1">
                          {item.description}
                        </p>

                        {/* Items Preview */}
                        <div className="mt-3 flex flex-wrap gap-2">
                           {item.items.slice(0, 3).map((prod: any, idx: number) => {
                             const displayQty = item.type === 'count' ? prod.countedQuantity : prod.quantity;
                             const prefix = (item.type === 'adjustment' && prod.quantity > 0) ? '+' : '';

                             return (
                               <span key={idx} className="inline-flex items-center px-2 py-1 bg-slate-100 text-slate-600 text-xs rounded border border-slate-200">
                                 {prod.productName} 
                                 <span className={`ml-1 font-semibold ${item.type === 'adjustment' && prod.quantity < 0 ? 'text-red-600' : 'text-slate-800'}`}>
                                   x{prefix}{displayQty}
                                 </span>
                               </span>
                             );
                           })}
                           {item.items.length > 3 && (
                             <span className="inline-flex items-center px-2 py-1 bg-slate-100 text-slate-500 text-xs rounded border border-slate-200">
                               +{item.items.length - 3} more
                             </span>
                           )}
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center space-x-3 pl-14 md:pl-0">
                      <button 
                        onClick={(e) => handleReject(e, item)}
                        className="flex items-center px-4 py-2 border border-slate-200 text-slate-600 rounded-lg hover:bg-red-50 hover:text-red-600 hover:border-red-200 transition-colors font-medium text-sm"
                      >
                        <XCircle className="w-4 h-4 mr-2" />
                        Reject
                      </button>
                      <button 
                        onClick={(e) => handleApprove(e, item)}
                        className="flex items-center px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors font-medium shadow-sm hover:shadow-md text-sm"
                      >
                        <CheckCircle className="w-4 h-4 mr-2" />
                        Approve
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { 
  Warehouse, Product, StockTransfer, StockCount, StockReservation, StockReceipt, StockAdjustment, 
  DocumentStatus, StockItem 
} from '../types';
import { 
  Plus, Edit2, Trash2, ArrowRightLeft, 
  CheckSquare, CalendarClock, Truck, SlidersHorizontal, 
  X, CheckCircle, FileText, PlayCircle, AlertCircle
} from 'lucide-react';

interface StockManagementProps {
  warehouses: Warehouse[];
  products: Product[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  defaultItemsPerPage: number;
  onUpdateTransfer: (t: StockTransfer) => void;
  onDeleteTransfer: (id: string) => void;
  onUpdateCount: (c: StockCount) => void;
  onDeleteCount: (id: string) => void;
  onUpdateReservation: (r: StockReservation) => void;
  onDeleteReservation: (id: string) => void;
  onUpdateReceipt: (r: StockReceipt) => void;
  onDeleteReceipt: (id: string) => void;
  onUpdateAdjustment: (a: StockAdjustment) => void;
  onDeleteAdjustment: (id: string) => void;
  onStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
}

export const StockManagement: React.FC<StockManagementProps> = ({
  warehouses, products, transfers, counts, reservations, receipts, adjustments, defaultItemsPerPage,
  onUpdateTransfer, onDeleteTransfer,
  onUpdateCount, onDeleteCount,
  onUpdateReservation, onDeleteReservation,
  onUpdateReceipt, onDeleteReceipt,
  onUpdateAdjustment, onDeleteAdjustment,
  onStatusChange
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment'>('transfer');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<any>({}); 
  const [error, setError] = useState<string | null>(null);

  // Helper to init form based on tab
  const initForm = () => {
    const common = {
      referenceNo: '',
      date: new Date().toISOString().split('T')[0],
      status: 'Draft',
      items: []
    };

    switch(activeTab) {
      case 'transfer': return { ...common, sourceWarehouseId: '', targetWarehouseId: '' };
      case 'count': return { ...common, warehouseId: '', counterName: '', reason: '' };
      case 'reservation': return { ...common, warehouseId: '', customerName: '', expiryDate: '' };
      case 'receipt': return { ...common, warehouseId: '', vendorName: '', vendorInvoiceNo: '', totalCost: 0 };
      case 'adjustment': return { ...common, warehouseId: '', reason: '' };
    }
  };

  const handleOpenModal = (item?: any) => {
    setError(null);
    if (item) {
      setEditingId(item.id);
      setFormData({ ...item });
    } else {
      setEditingId(null);
      setFormData(initForm());
    }
    setIsModalOpen(true);
  };

  const validateForm = () => {
    if (!formData.date) return 'Date is required';

    if (activeTab === 'transfer') {
        if (!formData.sourceWarehouseId) return 'Source Warehouse is required';
        if (!formData.targetWarehouseId) return 'Target Warehouse is required';
        if (formData.sourceWarehouseId === formData.targetWarehouseId) return 'Source and Target warehouses cannot be the same';
    }

    if (['adjustment', 'count', 'receipt', 'reservation'].includes(activeTab)) {
        if (!formData.warehouseId) return 'Warehouse is required';
    }

    if (activeTab === 'receipt' && !formData.vendorName) return 'Vendor Name is required';

    if (activeTab === 'reservation') {
        if (!formData.customerName) return 'Customer Name is required';
        if (!formData.expiryDate) return 'Expiry Date is required';
    }

    if (activeTab === 'count' && !formData.counterName) return 'Counter Name is required';

    if (activeTab === 'adjustment' && !formData.reason) return 'Reason is required';

    return null;
  };

  const handleSave = () => {
    // 1. Validate
    setError(null);
    const validationError = validateForm();
    if (validationError) {
        setError(validationError);
        return;
    }

    const id = editingId || (activeTab === 'transfer' ? `TR-${Date.now()}` : 
                             activeTab === 'count' ? `SC-${Date.now()}` :
                             activeTab === 'reservation' ? `RS-${Date.now()}` :
                             activeTab === 'receipt' ? `RC-${Date.now()}` :
                             `AD-${Date.now()}`);

    // Always save as Draft initially or preserve existing status if editing
    const currentStatus = formData.status === 'Completed' || formData.status === 'Approved' ? formData.status : 'Draft';
    const payload = { ...formData, id, status: currentStatus };

    // Auto-generate Ref No if missing
    if (!payload.referenceNo) {
        payload.referenceNo = `${activeTab.toUpperCase().slice(0,2)}-${new Date().getFullYear()}${new Date().getMonth()+1}-${Math.floor(Math.random()*1000)}`;
    }

    switch (activeTab) {
      case 'transfer': onUpdateTransfer(payload); break;
      case 'count': onUpdateCount(payload); break;
      case 'reservation': onUpdateReservation(payload); break;
      case 'receipt': onUpdateReceipt(payload); break;
      case 'adjustment': onUpdateAdjustment(payload); break;
    }
    setIsModalOpen(false);
  };

  const handleComplete = (item: any) => {
    if (window.confirm('Confirm completion? This will update stock levels permanently.')) {
      onStatusChange(activeTab, item.id, 'Completed');
    }
  };

  const getList = () => {
    switch(activeTab) {
      case 'transfer': return transfers;
      case 'count': return counts;
      case 'reservation': return reservations;
      case 'receipt': return receipts;
      case 'adjustment': return adjustments;
      default: return [];
    }
  };

  const handleDelete = (id: string) => {
    if (!confirm('Delete this document?')) return;
    switch(activeTab) {
      case 'transfer': onDeleteTransfer(id); break;
      case 'count': onDeleteCount(id); break;
      case 'reservation': onDeleteReservation(id); break;
      case 'receipt': onDeleteReceipt(id); break;
      case 'adjustment': onDeleteAdjustment(id); break;
    }
  };

  // Simplified Item Management inside Modal
  const handleAddItem = () => {
    if (!products.length) return;
    const p = products[0];
    const newItem: StockItem = {
      productId: p.id,
      productName: p.name,
      unit: p.unit,
      quantity: 1
    };
    setFormData({ ...formData, items: [...(formData.items || []), newItem] });
  };

  const handleUpdateItem = (index: number, field: string, value: any) => {
    const newItems = [...formData.items];
    if (field === 'productId') {
        const p = products.find(prod => prod.id === value);
        if (p) {
            newItems[index] = { ...newItems[index], productId: p.id, productName: p.name, unit: p.unit };
        }
    } else {
        newItems[index] = { ...newItems[index], [field]: value };
    }
    setFormData({ ...formData, items: newItems });
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...formData.items];
    newItems.splice(index, 1);
    setFormData({ ...formData, items: newItems });
  };

  const isReadOnly = formData.status !== 'Draft';

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Stock Management</h2>
          <p className="text-slate-500">Manage stock movements, counts, and adjustments.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="flex items-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium">
          <Plus className="w-4 h-4 mr-2" />
          Create Document
        </button>
      </div>

      {/* Tabs */}
      <div className="flex space-x-1 bg-slate-100 p-1 rounded-lg w-fit">
        {[
          { id: 'transfer', label: 'Transfer', icon: ArrowRightLeft },
          { id: 'receipt', label: 'Receipt (In)', icon: Truck },
          { id: 'adjustment', label: 'Adjustment', icon: SlidersHorizontal },
          { id: 'count', label: 'Count (Audit)', icon: CheckSquare },
          { id: 'reservation', label: 'Reservation', icon: CalendarClock },
        ].map(tab => {
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                activeTab === tab.id ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <Icon className="w-4 h-4 mr-2" />
              {tab.label}
            </button>
          )
        })}
      </div>

      {/* List */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Ref No / Date</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Details</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Items</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Status</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {getList().map((item: any) => (
                <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-800">{item.referenceNo}</div>
                    <div className="text-xs text-slate-500">{new Date(item.date).toLocaleDateString()}</div>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-600">
                    {activeTab === 'transfer' && `From: ${warehouses.find(w => w.id === item.sourceWarehouseId)?.name} To: ${warehouses.find(w => w.id === item.targetWarehouseId)?.name}`}
                    {activeTab === 'receipt' && `Vendor: ${item.vendorName} (Ref: ${item.vendorInvoiceNo})`}
                    {activeTab === 'adjustment' && `Reason: ${item.reason} @ ${warehouses.find(w => w.id === item.warehouseId)?.name}`}
                    {activeTab === 'count' && `Counter: ${item.counterName} @ ${warehouses.find(w => w.id === item.warehouseId)?.name}`}
                    {activeTab === 'reservation' && `Customer: ${item.customerName} (Exp: ${new Date(item.expiryDate).toLocaleDateString()})`}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="bg-slate-100 px-2 py-1 rounded text-xs font-bold text-slate-600">
                      {item.items?.length || 0} items
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold ${
                      item.status === 'Completed' ? 'bg-green-100 text-green-700' : 
                      item.status === 'Approved' ? 'bg-blue-100 text-blue-700' :
                      item.status === 'Cancelled' ? 'bg-red-100 text-red-700' :
                      'bg-orange-100 text-orange-700'
                    }`}>
                      {item.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end space-x-2 items-center">
                      {/* Workflow Actions */}
                      {item.status === 'Approved' && (
                        <button 
                          onClick={(e) => {
                            e.stopPropagation();
                            handleComplete(item);
                          }}
                          className="flex items-center px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-bold shadow-sm"
                          title="Execute and Update Stock"
                        >
                          <PlayCircle className="w-3 h-3 mr-1" /> Complete
                        </button>
                      )}

                      <button onClick={(e) => { e.stopPropagation(); handleOpenModal(item); }} className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-slate-100 rounded">
                        {item.status === 'Draft' ? <Edit2 className="w-4 h-4" /> : <FileText className="w-4 h-4" />}
                      </button>

                      {(item.status === 'Draft' || item.status === 'Approved') && (
                        <button onClick={(e) => { e.stopPropagation(); handleDelete(item.id); }} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-slate-100 rounded">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal - High Z-Index to avoid overlap issues */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[60] p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <h3 className="text-xl font-bold text-slate-800 uppercase">
                {editingId ? 'Edit' : 'New'} {activeTab}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="flex-1 overflow-hidden flex flex-col">
              <div className="p-6 overflow-y-auto flex-1 space-y-4">

                {error && (
                  <div className="p-3 bg-red-50 border border-red-100 rounded-lg text-red-600 text-sm flex items-center">
