               <ArrowUpCircle className="w-6 h-6" />
            </div>
            <div>
               <p className="text-sm text-slate-500 font-medium">Pending Uploads</p>
               <h3 className="text-lg font-bold text-slate-800">{pendingSales.length} Sales</h3>
