import React, { useState, useRef } from 'react';
import { User, UserRole } from '../types';
import { 
  Users, 
  Plus, 
  Edit2, 
  Trash2, 
  X, 
  ShieldCheck, 
  UserCircle,
  Mail,
  Lock,
  CheckCircle,
  Store,
  LayoutDashboard,
  ClipboardList,
  Package,
  Building2,
  Briefcase,
  Upload,
  Image as ImageIcon
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: User) => void;
  onUpdateUser: (user: User) => void;
  onDeleteUser: (id: string) => void;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const UserManagement: React.FC<UserManagementProps> = ({
  users,
  onAddUser,
  onUpdateUser,
  onDeleteUser
}) => {
  const { branches } = useGlobal();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<User>>({
    username: '',
    password: '',
    name: '',
    email: '',
    role: 'Cashier',
    avatarUrl: '',
    department: '',
    branchId: ''
  });

  const handleOpenModal = (user?: User) => {
    if (user) {
      setEditingId(user.id);
      setFormData({ 
        username: user.username,
        name: user.name,
        email: user.email || '',
        role: user.role,
        avatarUrl: user.avatarUrl || '',
        password: '', // Don't pre-fill password for editing security
        department: user.department || '',
        branchId: user.branchId || ''
      });
    } else {
      setEditingId(null);
      setFormData({
        username: '',
        password: '',
        name: '',
        email: '',
        role: 'Cashier',
        avatarUrl: '',
        department: '',
        branchId: ''
      });
    }
    setIsModalOpen(true);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, avatarUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, avatarUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Basic Validation
    if (!formData.username || !formData.name || !formData.role) return;
    if (!editingId && !formData.password) {
        alert("Password is required for new users.");
        return;
    }

    const userData: any = {
      username: formData.username,
      name: formData.name,
      email: formData.email,
      role: formData.role,
      avatarUrl: formData.avatarUrl,
      department: formData.department,
      branchId: formData.branchId
    };

    // Only update password if provided
    if (formData.password) {
      userData.password = formData.password;
    }

    if (editingId) {
      // For updates, preserve old password if new one isn't provided
      const existingUser = users.find(u => u.id === editingId);
      if (existingUser && !userData.password) {
          userData.password = existingUser.password;
      }
      onUpdateUser({ ...userData, id: editingId });
    } else {
      onAddUser({ ...userData, id: `u-${Date.now()}` });
    }
    setIsModalOpen(false);
  };

  // Permission Visualizer
  const getRolePermissions = (role: UserRole) => {
    const p = (label: string, access: boolean) => ({ label, access });

    switch (role) {
      case 'Admin':
        return [
          p('Dashboard', true),
          p('Point of Sale (POS)', true),
          p('My Shift', true),
          p('Sales History', true),
          p('Inventory', true),
          p('Stock Management', true),
          p('Customers & Levels', true),
          p('Approvals', true),
          p('Promotions', true),
          p('Data Sync', true),
          p('Categories', true),
          p('Units', true),
          p('Branches', true),
          p('Warehouse (WMS)', true),
          p('User Management', true),
          p('Settings', true),
