          p('Data Sync', true),
          p('Categories', false),
          p('Units', false),
          p('Branches', false),
          p('Warehouse (WMS)', false),
          p('User Management', false),
          p('Settings', true),
        ];
      case 'Staff':
        return [
          p('Dashboard', false),
          p('Point of Sale (POS)', true),
          p('My Shift', true),
