          p('Inventory', true),
          p('Stock Management', true),
          p('Customers & Levels', false),
          p('Approvals', false),
          p('Promotions', false),
          p('Data Sync', false),
          p('Categories', false),
          p('Units', false),
          p('Branches', false),
          p('Warehouse (WMS)', false),
          p('User Management', false),
          p('Settings', false),
        ];
      case 'Cashier':
        return [
          p('Dashboard', false),
          p('Point of Sale (POS)', true),
          p('My Shift', true),
          p('Sales History', true),
          p('Inventory', false),
          p('Stock Management', false),
          p('Customers & Levels', true),
          p('Approvals', false),
          p('Promotions', false),
          p('Data Sync', false),
          p('Categories', false),
          p('Units', false),
          p('Branches', false),
          p('Warehouse (WMS)', false),
          p('User Management', false),
          p('Settings', false),
        ];
      default:
        return [];
    }
  };

  const permissions = getRolePermissions(formData.role as UserRole || 'Cashier');

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
