                      </label>

                      {/* Cashier */}
                      <label className={`flex items-center p-3 rounded-lg border cursor-pointer transition-all ${formData.role === 'Cashier' ? 'bg-white border-primary-500 shadow-sm ring-1 ring-primary-500' : 'border-slate-200 hover:bg-white'}`}>
                        <input 
                          type="radio" 
                          name="role" 
                          value="Cashier" 
                          checked={formData.role === 'Cashier'}
                          onChange={e => setFormData({...formData, role: 'Cashier'})}
                          className="w-4 h-4 text-primary-600 focus:ring-primary-500 border-slate-300"
                        />
                        <div className="ml-3">
                           <span className="block text-sm font-medium text-slate-800">Cashier</span>
                           <span className="block text-xs text-slate-500">POS & Sales only</span>
                        </div>
                      </label>
                    </div>

                    <div className="space-y-2">
                      <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide block mb-2">Access Capabilities</span>
                      <div className="grid grid-cols-2 gap-x-2 gap-y-1">
                        {permissions.map((perm, idx) => (
                          <div key={idx} className="flex items-center text-xs">
                            {perm.access ? (
                              <CheckCircle className="w-3.5 h-3.5 text-green-500 mr-2 flex-shrink-0" />
                            ) : (
                              <X className="w-3.5 h-3.5 text-slate-300 mr-2 flex-shrink-0" />
                            )}
                            <span className={perm.access ? 'text-slate-700 font-medium' : 'text-slate-400'}>
                              {perm.label}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>

                <div className="flex justify-end pt-6 mt-6 border-t border-slate-100 space-x-3">
                  <button
                    type="button"
                    onClick={() => setIsModalOpen(false)}
                    className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="px-6 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm"
                  >
                    {editingId ? 'Update User' : 'Create User'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { 
  LayoutDashboard, 
  ShoppingCart, 
  Package, 
  Hammer, 
  LogOut,
  Menu,
  Scale,
  FolderTree,
  Store,
  Container,
  ClipboardList,
  FileCheck,
  UserCircle,
  Users,
  Settings,
  RefreshCw,
  Contact,
  Clock,
  Tv
} from 'lucide-react';
import { User, UserRole } from '../types';
import { useGlobal } from '../context/GlobalContext';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  onTabChange: (tab: string) => void;
  currentUser: User | null;
  onLogout: () => void;
}

interface NavItemConfig {
  id: string;
  icon: any;
  label: string;
  allowedRoles: UserRole[];
}

const NAV_ITEMS: NavItemConfig[] = [
  { id: 'dashboard', icon: LayoutDashboard, label: 'Dashboard', allowedRoles: ['Admin', 'Manager'] },
  { id: 'pos', icon: ShoppingCart, label: 'Point of Sale', allowedRoles: ['Admin', 'Manager', 'Staff', 'Cashier'] },
  { id: 'shifts', icon: Clock, label: 'My Shift', allowedRoles: ['Admin', 'Manager', 'Staff', 'Cashier'] },
  { id: 'inventory', icon: Package, label: 'Inventory', allowedRoles: ['Admin', 'Manager', 'Staff'] },
  { id: 'stock', icon: ClipboardList, label: 'Stock Mgmt', allowedRoles: ['Admin', 'Manager', 'Staff'] },
  { id: 'customers', icon: Contact, label: 'Customers', allowedRoles: ['Admin', 'Manager', 'Cashier', 'Staff'] },
  { id: 'approvals', icon: FileCheck, label: 'Approvals', allowedRoles: ['Admin', 'Manager'] },
  { id: 'promotions', icon: Tv, label: 'Promotions', allowedRoles: ['Admin', 'Manager', 'Staff'] },
  { id: 'sync', icon: RefreshCw, label: 'Data Sync', allowedRoles: ['Admin', 'Manager'] },
  { id: 'categories', icon: FolderTree, label: 'Categories', allowedRoles: ['Admin', 'Staff'] },
  { id: 'units', icon: Scale, label: 'Unit Mgmt', allowedRoles: ['Admin', 'Staff'] },
  { id: 'branches', icon: Store, label: 'Branches & POS', allowedRoles: ['Admin'] },
  { id: 'warehouses', icon: Container, label: 'Warehouse (WMS)', allowedRoles: ['Admin', 'Staff'] },
  { id: 'users', icon: Users, label: 'Users & Roles', allowedRoles: ['Admin'] },
  { id: 'settings', icon: Settings, label: 'Settings', allowedRoles: ['Admin', 'Manager'] },
];

export const Layout: React.FC<LayoutProps> = ({ children, activeTab, onTabChange, currentUser, onLogout }) => {
  const { t } = useGlobal();
  const [mobileMenuOpen, setMobileMenuOpen] = React.useState(false);

  // Filter nav items based on user role
  const visibleNavItems = NAV_ITEMS.filter(item => 
    currentUser && item.allowedRoles.includes(currentUser.role)
  );

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden">
      {/* Sidebar - Desktop */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 text-white transform transition-transform duration-300 ease-in-out
        md:relative md:translate-x-0
        ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="flex items-center justify-center h-20 border-b border-slate-800">
          <div className="flex items-center space-x-2">
            <div className="bg-construction-orange p-2 rounded-lg">
              <Hammer className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold tracking-tight">{t('app.name')}</h1>
          </div>
        </div>

        {/* User Profile Mini-Card */}
        {currentUser && (
          <div className="p-4 border-b border-slate-800 bg-slate-800/50">
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center overflow-hidden border-2 border-slate-600">
                {currentUser.avatarUrl ? (
                  <img src={currentUser.avatarUrl} alt={currentUser.name} className="w-full h-full object-cover" />
                ) : (
                  <UserCircle className="w-6 h-6 text-slate-400" />
                )}
              </div>
              <div className="overflow-hidden">
                <p className="text-sm font-semibold text-white truncate">{currentUser.name}</p>
                <span className={`text-xs px-2 py-0.5 rounded-full inline-block mt-1 font-bold tracking-wide ${
                  currentUser.role === 'Admin' ? 'bg-purple-500/20 text-purple-300' : 
                  currentUser.role === 'Manager' ? 'bg-indigo-500/20 text-indigo-300' :
                  currentUser.role === 'Staff' ? 'bg-blue-500/20 text-blue-300' :
                  'bg-green-500/20 text-green-300'
                }`}>
                  {currentUser.role}
                </span>
              </div>
            </div>
          </div>
        )}

        <nav className="p-4 mt-2 overflow-y-auto max-h-[calc(100vh-220px)] scrollbar-hide">
          {visibleNavItems.map(item => {
            const Icon = item.icon;
            return (
              <button
                key={item.id}
                onClick={() => {
                  onTabChange(item.id);
                  setMobileMenuOpen(false);
                }}
                className={`flex items-center w-full px-4 py-3 mb-2 rounded-lg transition-colors duration-200 ${
                  activeTab === item.id 
                    ? 'bg-primary-600 text-white shadow-md' 
                    : 'text-slate-400 hover:bg-slate-800 hover:text-white'
                }`}
              >
                <Icon className="w-5 h-5 mr-3" />
                <span className="font-medium">{t(`nav.${item.id}`)}</span>
              </button>
            );
          })}
        </nav>

        <div className="absolute bottom-0 w-full p-4 border-t border-slate-800">
          <button 
            onClick={onLogout}
            className="flex items-center w-full px-4 py-3 text-slate-400 hover:text-red-400 hover:bg-slate-800 rounded-lg transition-colors"
          >
            <LogOut className="w-5 h-5 mr-3" />
            <span>{t('nav.logout')}</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between p-4 bg-white border-b border-slate-200 shadow-sm z-10">
          <div className="flex items-center space-x-2">
            <Hammer className="w-6 h-6 text-construction-orange" />
            <span className="font-bold text-slate-800">{t('app.name')}</span>
          </div>
          <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="p-2 text-slate-600">
            <Menu className="w-6 h-6" />
          </button>
        </header>

        {/* Content Area */}
        <main className="flex-1 overflow-y-auto p-4 md:p-6 bg-slate-50 relative">
          {children}
        </main>
      </div>

      {/* Overlay for mobile menu */}
      {mobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 z-40 md:hidden"
          onClick={() => setMobileMenuOpen(false)}
        />
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { User, UserRole } from '../types';
import { 
  Users, 
  Plus, 
  Edit2, 
  Trash2, 
  X, 
  ShieldCheck, 
  UserCircle, 
  Mail, 
  Lock, 
  CheckCircle, 
  Store, 
  LayoutDashboard, 
  ClipboardList, 
  Package, 
  Building2, 
  Briefcase, 
  Upload, 
  Image as ImageIcon
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: User) => void;
  onUpdateUser: (user: User) => void;
  onDeleteUser: (id: string) => void;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const UserManagement: React.FC<UserManagementProps> = ({
  users,
  onAddUser,
  onUpdateUser,
  onDeleteUser
}) => {
  const { branches } = useGlobal();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<User>>({
    username: '',
    password: '',
    name: '',
    email: '',
    role: 'Cashier',
    avatarUrl: '',
    department: '',
    branchId: ''
  });

  const handleOpenModal = (user?: User) => {
    if (user) {
      setEditingId(user.id);
      setFormData({ 
        username: user.username,
        name: user.name,
        email: user.email || '',
        role: user.role,
        avatarUrl: user.avatarUrl || '',
        password: '', // Don't pre-fill password for editing security
        department: user.department || '',
        branchId: user.branchId || ''
      });
    } else {
      setEditingId(null);
      setFormData({
        username: '',
        password: '',
        name: '',
        email: '',
        role: 'Cashier',
        avatarUrl: '',
        department: '',
        branchId: ''
      });
    }
    setIsModalOpen(true);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, avatarUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, avatarUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Basic Validation
    if (!formData.username || !formData.name || !formData.role) return;
    if (!editingId && !formData.password) {
        alert("Password is required for new users.");
        return;
    }

    const userData: any = {
      username: formData.username,
      name: formData.name,
      email: formData.email,
      role: formData.role,
      avatarUrl: formData.avatarUrl,
      department: formData.department,
      branchId: formData.branchId
    };

    // Only update password if provided
    if (formData.password) {
      userData.password = formData.password;
    }

    if (editingId) {
      // For updates, preserve old password if new one isn't provided
      const existingUser = users.find(u => u.id === editingId);
      if (existingUser && !userData.password) {
          userData.password = existingUser.password;
      }
      onUpdateUser({ ...userData, id: editingId });
    } else {
      onAddUser({ ...userData, id: `u-${Date.now()}` });
