          p('Point of Sale (POS)', true),
          p('My Shift', true),
          p('Sales History', true),
          p('Inventory', true),
          p('Stock Management', true),
          p('Customers & Levels', true),
          p('Approvals', true),
          p('Promotions', true),
          p('Data Sync', true),
          p('Categories', true),
          p('Units', true),
          p('Branches', true),
          p('Warehouse (WMS)', true),
          p('User Management', true),
          p('Settings', false),
        ];
      case 'Staff':
