                        >
                          {connectionStatus === 'testing' ? <RefreshCw className="w-4 h-4 animate-spin mr-2" /> : connectionStatus === 'success' ? <Wifi className="w-4 h-4 mr-2" /> : <Activity className="w-4 h-4 mr-2" />}
