                    <div className="grid grid-cols-3 gap-3">
                      {[
                        { code: 'en', flag: '🇺🇸', label: 'English' },
                        { code: 'th', flag: '🇹🇭', label: 'ไทย' },
                        { code: 'lo', flag: '🇱🇦', label: 'ລາວ' }
