                            <option value="80mm">Thermal 80mm (Standard)</option>
                            <option value="A4">A4 (Full Invoice)</option>
                          </select>
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">Store Logo</label>
