                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                             {level ? (
                               <span 
                                className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold text-white shadow-sm"
                                style={{ backgroundColor: level.color || '#64748b' }}
                               >
                                 <Star className="w-3 h-3 mr-1" fill="currentColor" />
                                 {level.name} ({level.discountPercentage}%)
                               </span>
                             ) : (
                               <span className="text-xs text-slate-400 italic">No Level</span>
                             )}
                          </td>
                          <td className="px-6 py-4 text-center whitespace-nowrap">
                            <div className="inline-flex items-center px-3 py-1 bg-yellow-50 text-yellow-700 rounded-full text-xs font-bold border border-yellow-200">
                              <Award className="w-3 h-3 mr-1" />
                              {customer.loyaltyPoints || 0} pts
                            </div>
                          </td>
                          <td className="px-6 py-4 text-right whitespace-nowrap">
                            <div className="flex justify-end space-x-2">
                              <button onClick={() => handleOpenModal(customer)} className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-slate-100 rounded transition-colors">
                                <Edit2 className="w-4 h-4" />
                              </button>
                              <button 
                                onClick={() => {
                                   if(confirm(`Delete customer ${customer.name}?`)) onDeleteCustomer(customer.id);
                                }} 
                                className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-slate-100 rounded transition-colors"
                              >
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}

      {activeTab === 'levels' && (
        <div className="flex flex-col md:flex-row gap-6 h-full">
           <div className="w-full md:w-1/3 flex flex-col gap-4">
              <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                 <h3 className="font-bold text-slate-800 mb-2">About Membership Levels</h3>
                 <p className="text-sm text-slate-500 mb-4">
                    Create tiers to automatically apply discounts at the POS. Assign customers to tiers to reward loyalty.
                 </p>
                 <button 
                    onClick={() => handleOpenLevelModal()}
                    className="w-full py-3 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors font-medium flex items-center justify-center"
                 >
                    <Plus className="w-4 h-4 mr-2" />
                    Create New Level
                 </button>
              </div>
           </div>

           <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
              <div className="p-4 border-b border-slate-100 bg-slate-50">
                 <h3 className="font-bold text-slate-700">Active Membership Tiers</h3>
              </div>
              <div className="overflow-y-auto flex-1 p-4 space-y-3">
                 {safeLevels.length === 0 ? (
                    <div className="text-center py-10 text-slate-400">
                       <AlertCircle className="w-10 h-10 mx-auto mb-2 opacity-30" />
                       <p>No membership levels defined.</p>
                    </div>
                 ) : (
                    safeLevels.map(level => (
                       <div key={level.id} className="flex items-center justify-between p-4 border border-slate-200 rounded-xl hover:border-blue-300 hover:shadow-sm transition-all bg-white">
                          <div className="flex items-center">
                             <div 
                                className="w-10 h-10 rounded-full flex items-center justify-center text-white font-bold shadow-sm mr-4"
                                style={{ backgroundColor: level.color || '#64748b' }}
                             >
                                {level.discountPercentage}%
                             </div>
                             <div>
                                <h4 className="font-bold text-slate-800">{level.name}</h4>
                                <p className="text-xs text-slate-500">Auto-applies {level.discountPercentage}% discount</p>
                             </div>
                          </div>
                          <div className="flex space-x-2">
                             <button onClick={() => handleOpenLevelModal(level)} className="p-2 text-slate-400 hover:text-blue-600 rounded hover:bg-blue-50">
                                <Edit2 className="w-4 h-4" />
                             </button>
                             <button 
                                onClick={() => {
                                   if(confirm('Delete this level?')) deleteCustomerLevel(level.id);
                                }}
                                className="p-2 text-slate-400 hover:text-red-600 rounded hover:bg-red-50"
                             >
                                <Trash2 className="w-4 h-4" />
                             </button>
                          </div>
                       </div>
                    ))
                 )}
              </div>
           </div>
        </div>
      )}

      {/* Customer Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl shrink-0">
              <h3 className="text-xl font-bold text-slate-800">
                {editingId ? 'Edit Customer' : 'Add New Customer'}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-4 flex-1">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-slate-700 mb-1">Full Name *</label>
                    <input
                      required
                      type="text"
                      value={formData.name}
                      onChange={e => setFormData({...formData, name: e.target.value})}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                 </div>
                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Customer Code *</label>
                    <input
                      required
                      type="text"
                      value={formData.code}
                      onChange={e => setFormData({...formData, code: e.target.value})}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-mono"
                    />
                 </div>
                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Phone</label>
                    <input
                      type="text"
                      value={formData.phone}
                      onChange={e => setFormData({...formData, phone: e.target.value})}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                 </div>
              </div>

              <div>
                 <label className="block text-sm font-medium text-slate-700 mb-1">Email</label>
                 <input
                   type="email"
                   value={formData.email}
                   onChange={e => setFormData({...formData, email: e.target.value})}
                   className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                 />
              </div>

              <div>
                 <label className="block text-sm font-medium text-slate-700 mb-1">Address</label>
                 <textarea
                   value={formData.address}
                   onChange={e => setFormData({...formData, address: e.target.value})}
                   className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 h-20 resize-none"
                 />
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Tax ID</label>
                    <input
                      type="text"
                      value={formData.taxId}
                      onChange={e => setFormData({...formData, taxId: e.target.value})}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                 </div>
                 <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Loyalty Points</label>
                    <input
                      type="number"
                      value={formData.loyaltyPoints}
                      onChange={e => setFormData({...formData, loyaltyPoints: parseInt(e.target.value) || 0})}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                 </div>
              </div>

              <div className="pt-2 border-t border-slate-100 mt-2">
                 <label className="block text-sm font-bold text-slate-700 mb-2">Membership Level</label>
                 <select
                    value={formData.levelId || ''}
                    onChange={e => setFormData({...formData, levelId: e.target.value})}
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white"
                 >
                    <option value="">No Membership Level</option>
                    {safeLevels.map(lvl => (
                       <option key={lvl.id} value={lvl.id}>
                          {lvl.name} ({lvl.discountPercentage}% Off)
                       </option>
                    ))}
                 </select>
              </div>

              <div className="flex justify-end pt-4 space-x-3 mt-auto">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-6 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm"
                >
                  Save Customer
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Level Modal */}
      {isLevelModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <h3 className="text-lg font-bold text-slate-800">
                {editingLevelId ? 'Edit Level' : 'New Level'}
              </h3>
              <button onClick={() => setIsLevelModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleLevelSubmit} className="p-6 space-y-4">
              <div>
                 <label className="block text-sm font-medium text-slate-700 mb-1">Level Name</label>
                 <input
                   required
                   type="text"
                   value={levelForm.name}
                   onChange={e => setLevelForm({...levelForm, name: e.target.value})}
                   className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                   placeholder="e.g. Gold Member"
                 />
              </div>

              <div>
                 <label className="block text-sm font-medium text-slate-700 mb-1">Discount Percentage</label>
                 <div className="relative">
                    <input
                      type="number"
                      min="0"
                      max="100"
                      required
                      value={levelForm.discountPercentage}
                      onChange={e => setLevelForm({...levelForm, discountPercentage: parseFloat(e.target.value) || 0})}
                      className="w-full pl-4 pr-8 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-bold"
                    />
                    <span className="absolute right-3 top-2.5 text-slate-400 font-bold">%</span>
                 </div>
              </div>

              <div>
                 <label className="block text-sm font-medium text-slate-700 mb-2">Badge Color</label>
                 <div className="flex gap-2">
                    {['#64748b', '#eab308', '#94a3b8', '#8b5cf6', '#ef4444', '#22c55e', '#3b82f6'].map(color => (
                       <button
                          key={color}
                          type="button"
                          onClick={() => setLevelForm({...levelForm, color})}
                          className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110 ${levelForm.color === color ? 'border-slate-800 ring-2 ring-slate-300' : 'border-transparent'}`}
                          style={{ backgroundColor: color }}
                       />
                    ))}
                 </div>
              </div>

              <div className="flex justify-end pt-4 space-x-3">
                <button
                  type="button"
                  onClick={() => setIsLevelModalOpen(false)}
                  className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-6 py-2 bg-slate-800 text-white font-medium rounded-lg hover:bg-slate-900 transition-colors shadow-sm"
                >
                  Save Level
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, UnitDefinition, CategoryItem, Warehouse, InventoryAnalysisResult, Sale, Branch } from '../types';
import { Search, Plus, Edit2, Trash2, X, Check, Layers, Box, ArrowRight, ArrowLeftRight, RefreshCw, Info, Building2, AlertTriangle, Bell, Sparkles, Loader2, TrendingUp, AlertCircle, PackagePlus, Scale, DollarSign, Store, ChevronLeft, ChevronRight, ShoppingBag, Image as ImageIcon, Upload, Palette, Ruler } from 'lucide-react';
import { analyzeInventory } from '../services/geminiService';
import { useGlobal } from '../context/GlobalContext';

interface InventoryProps {
  products: Product[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  warehouses?: Warehouse[];
  sales: Sale[];
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onAddProduct: (product: Product) => void;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const Inventory: React.FC<InventoryProps> = ({ products, units, categories, warehouses = [], sales, onUpdateProduct, onDeleteProduct, onAddProduct }) => {
  const { branches, settings, t } = useGlobal();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = settings.defaultItemsPerPage || 10;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'general' | 'physical' | 'pricing' | 'variants'>('general');
  const [editingId, setEditingId] = useState<string | null>(null);

  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiResult, setAiResult] = useState<InventoryAnalysisResult | null>(null);
  const [activeAiTab, setActiveAiTab] = useState<'reorder' | 'new' | 'bundles'>('reorder');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    sku: '',
    barcode: '',
    category: '',
    price: 0,
    stock: 0,
    minStock: 20,
    unit: '',
    physical: { weight: 0, width: 0, height: 0, depth: 0 },
    branchPrices: [],
    imageUrl: ''
  });

  const [variants, setVariants] = useState<Partial<ProductVariant>[]>([]);

  const getFlattenedCategories = () => {
    const options: { id: string; name: string; level: number }[] = [];
    const buildOptions = (parentId: string | null, level: number) => {
      const children = categories.filter(c => c.parentId === parentId);
      children.forEach(c => {
        options.push({ id: c.id, name: c.name, level });
        buildOptions(c.id, level + 1);
      });
    };
    buildOptions(null, 0);
    return options;
  };

  const categoryOptions = getFlattenedCategories();

  const getCategoryName = (idOrName: string) => {
    const cat = categories.find(c => c.id === idOrName);
    return cat ? cat.name : idOrName; 
  };

  const filteredProducts = products.filter(p => {
    const searchLower = searchTerm.toLowerCase();
    const matchesSearch = 
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) || 
      p.barcode?.includes(searchLower) ||
      (p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      ));

    const pCatName = getCategoryName(p.category);
    const filterCatName = filterCategory === 'all' ? 'all' : getCategoryName(filterCategory);
    const matchesCategory = filterCategory === 'all' || p.category === filterCategory || pCatName === filterCatName;

    return matchesSearch && matchesCategory;
  });

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory]);

  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedProducts = filteredProducts.slice(startIndex, startIndex + itemsPerPage);

  const unitsByCategory = units.reduce((acc, unit) => {
    if (!acc[unit.category]) acc[unit.category] = [];
    acc[unit.category].push(unit);
    return acc;
  }, {} as Record<string, UnitDefinition[]>);

  const handleOpenAddModal = () => {
    setEditingId(null);
    setActiveTab('general');
    setFormData({
      name: '',
      sku: '',
      barcode: '',
      category: categoryOptions[0]?.id || '',
      price: 0,
      stock: 0,
      minStock: 20,
      unit: units[0]?.symbol || 'pc',
      physical: { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: [],
      imageUrl: ''
    });
    setVariants([]);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (product: Product) => {
    setEditingId(product.id);
    setActiveTab('general');
    setFormData({
      name: product.name,
      sku: product.sku,
      barcode: product.barcode,
      category: product.category,
      price: product.price,
      stock: product.stock,
      minStock: product.minStock || 20,
      unit: product.unit,
      physical: product.physical || { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: product.branchPrices || [],
      imageUrl: product.imageUrl || ''
    });
    setVariants(product.variants ? product.variants.map(v => ({...v})) : []);
    setIsModalOpen(true);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, imageUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  useEffect(() => {
    if (isAiModalOpen && !aiResult && !aiLoading) {
      const performAnalysis = async () => {
        setAiLoading(true);
        const result = await analyzeInventory(products, sales);
        setAiResult(result);
        setAiLoading(false);
      };
      performAnalysis();
    }
  }, [isAiModalOpen, products, sales, aiResult, aiLoading]);

  const handleOpenAiInsights = () => setIsAiModalOpen(true);

  const handleAddSuggestedProduct = (suggestion: any) => {
    setIsAiModalOpen(false);
    setEditingId(null);
    setActiveTab('general');

    const matchedCat = categories.find(c => c.name.toLowerCase().includes(suggestion.categoryName?.toLowerCase() || ''))?.id || '';
    const unitSearch = suggestion.suggestedUnit?.toLowerCase();
    let matchedUnit = units.find(u => u.symbol.toLowerCase() === unitSearch || u.name.toLowerCase() === unitSearch)?.symbol;
    if (!matchedUnit && unitSearch === 'set') matchedUnit = 'set'; 
    if (!matchedUnit) matchedUnit = 'pc';

    let productName = suggestion.name || suggestion.bundleName;
    if (suggestion.components && Array.isArray(suggestion.components) && suggestion.components.length > 0) {
       productName = `${productName} (Includes: ${suggestion.components.join(', ')})`;
    }

    setFormData({
      name: productName,
      sku: '',
      barcode: '',
      category: matchedCat,
      price: suggestion.estimatedPrice,
      stock: 0,
      minStock: 20,
      unit: matchedUnit,
      physical: { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: [],
      imageUrl: ''
    });
    setVariants([]);
    setIsModalOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const isNum = ['price', 'stock', 'minStock'].includes(name);

    setFormData(prev => ({
      ...prev,
      [name]: isNum ? (parseFloat(value) || 0) : value
    }));

    if (name === 'price') {
      const newMainPrice = parseFloat(value) || 0;
      setVariants(prev => prev.map(v => {
         const factor = v.conversionFactor || 1;
         return { ...v, price: factor !== 0 ? newMainPrice / factor : 0 };
      }));
    }
  };

  const handlePhysicalChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev,
      physical: {
        ...prev.physical,
        [field]: parseFloat(value) || 0
      }
    }));
  };

  const handleBranchPriceChange = (branchId: string, priceStr: string) => {
    const price = parseFloat(priceStr);
    setFormData(prev => {
      const currentPrices = prev.branchPrices ? [...prev.branchPrices] : [];
      const index = currentPrices.findIndex(bp => bp.branchId === branchId);

      if (index > -1) {
        if (!priceStr) {
           currentPrices.splice(index, 1);
        } else {
           currentPrices[index].price = price;
        }
      } else if (priceStr) {
        currentPrices.push({ branchId, price });
      }
      return { ...prev, branchPrices: currentPrices };
    });
  };

  const generateVariantCodes = (index: number) => {
    const suffix = (index + 1).toString().padStart(3, '0');
    const skuBase = formData.sku || 'SKU';
    return { code: `${skuBase}-${suffix}`, barcode: formData.barcode ? `${formData.barcode}${suffix}` : '' };
  };

  const handleAddVariant = () => {
    const { code, barcode } = generateVariantCodes(variants.length);
    setVariants(prev => [...prev, {
      id: `v-${Date.now()}`,
      name: '', 
      code,
      barcode,
      conversionFactor: 1, 
      price: formData.price,
      color: '',
      size: ''
    }]);
  };

  const handleRemoveVariant = (index: number) => setVariants(prev => prev.filter((_, i) => i !== index));

  const handleVariantChange = (index: number, field: keyof ProductVariant, value: any) => {
    setVariants(prev => {
      const newVariants = [...prev];
      let updatedVariant = { ...newVariants[index], [field]: value };

      if (field === 'name') {
        const mainUnitDef = units.find(u => u.symbol === formData.unit);
        const variantUnitDef = units.find(u => u.symbol === value);
        if (mainUnitDef && variantUnitDef && mainUnitDef.category === variantUnitDef.category) {
          const factor = mainUnitDef.baseFactor / variantUnitDef.baseFactor;
          updatedVariant.conversionFactor = factor;
          updatedVariant.price = (formData.price || 0) / factor;
        }
      }
      if (field === 'price' || field === 'conversionFactor') {
        updatedVariant[field] = parseFloat(value) || 0;
      }
      newVariants[index] = updatedVariant;
      return newVariants;
    });
  };

  const handleVariantRelationChange = (index: number, ratio: number, mode: 'sub' | 'bundle') => {
    const factor = mode === 'sub' ? ratio : (1 / ratio);
    setVariants(prev => {
      const newVariants = [...prev];
      newVariants[index] = { 
        ...newVariants[index], 
        conversionFactor: factor,
        price: factor !== 0 ? ((formData.price || 0) / factor) : 0
      };
      return newVariants;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.unit) {
      const productData: Product = {
        id: editingId || `P-${Date.now()}`,
        name: formData.name!,
        category: formData.category || 'Uncategorized',
        price: formData.price || 0,
        stock: formData.stock || 0,
        minStock: formData.minStock || 20,
        unit: formData.unit!,
        sku: formData.sku || '',
        barcode: formData.barcode || '',
        physical: formData.physical,
        branchPrices: formData.branchPrices,
        variants: variants.length > 0 ? variants as ProductVariant[] : undefined,
        warehouseInventory: editingId 
          ? products.find(p => p.id === editingId)?.warehouseInventory 
          : [{ warehouseId: 'wh1', quantity: formData.stock || 0 }],
        imageUrl: formData.imageUrl
      };

      if (editingId) onUpdateProduct(productData);
      else onAddProduct(productData);
      setIsModalOpen(false);
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col relative">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">{t('inventory.title')}</h2>
          <p className="text-slate-500">{t('inventory.subtitle')}</p>
        </div>
        <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 scrollbar-hide">
          <button 
            onClick={handleOpenAiInsights}
            className="flex items-center justify-center px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-lg hover:shadow-lg transition-all font-medium shadow-sm whitespace-nowrap"
          >
            <Sparkles className="w-4 h-4 mr-2" />
            {t('inventory.aiInsights')}
          </button>
          <button 
            onClick={handleOpenAddModal}
            className="flex items-center justify-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium shadow-sm whitespace-nowrap"
          >
            <Plus className="w-4 h-4 mr-2" />
            {t('inventory.addProduct')}
          </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
          <input
            type="text"
            placeholder={t('inventory.searchPlaceholder')}
            className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <select
          value={filterCategory}
          onChange={(e) => setFilterCategory(e.target.value)}
          className="px-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 bg-white"
        >
          <option value="all">{t('inventory.allCategories')}</option>
          {categoryOptions.map(cat => (
             <option key={cat.id} value={cat.id}>
                {'\u00A0'.repeat(cat.level * 3)}{cat.name}
             </option>
          ))}
        </select>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="overflow-x-auto flex-1">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 sticky top-0 z-10">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider whitespace-nowrap">{t('inventory.productName')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider whitespace-nowrap">{t('inventory.sku')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider whitespace-nowrap">{t('inventory.category')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-right whitespace-nowrap">{t('inventory.price')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-right whitespace-nowrap">{t('inventory.stock')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-center whitespace-nowrap">{t('common.actions')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {paginatedProducts.map((product) => {
                const isLowStock = product.stock < (product.minStock || 20);
                return (
                  <tr key={product.id} className={`hover:bg-slate-50 transition-colors group ${isLowStock ? 'bg-red-50 border-l-4 border-red-500' : ''}`}>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center space-x-3">
                        {product.imageUrl && (
                          <div className="w-10 h-10 rounded-lg overflow-hidden border border-slate-200 bg-white shrink-0">
                            <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                          </div>
                        )}
                        <div>
                          <div className="font-medium text-slate-800 truncate max-w-[200px]" title={product.name}>{product.name}</div>
                          <div className="text-xs text-slate-400 mt-0.5">ID: {product.id}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="mb-2">
                         <div className="flex items-center text-xs">
                           <span className="w-10 text-slate-400 font-semibold uppercase">{product.unit}</span>
                           <span className="font-mono bg-slate-100 px-1.5 rounded text-slate-600 mr-2">{product.sku}</span>
                           <span className="font-mono text-slate-500">{product.barcode}</span>
                         </div>
                      </div>
                      {product.variants?.map((v) => (
                        <div key={v.id} className="flex items-center text-xs pl-2 border-l-2 border-construction-orange/30 mb-1">
                           <span className="w-12 text-construction-orange font-semibold uppercase truncate" title={v.name}>{v.name}</span>
                           <span className="font-mono bg-orange-50 px-1.5 rounded text-orange-700 mr-2">{v.code}</span>
                           {v.color && (
                             <span className="inline-block w-3 h-3 rounded-full border border-slate-200 mr-1 shadow-sm" style={{ backgroundColor: v.color }}></span>
                           )}
                           {v.size && (
                             <span className="text-slate-500 mr-1">[{v.size}]</span>
                           )}
                         </div>
                      ))}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="px-2 py-1 text-xs font-medium bg-slate-100 text-slate-600 rounded-full">
                        {getCategoryName(product.category)}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right font-medium text-slate-700 whitespace-nowrap">
                       <div className="text-sm">${product.price.toFixed(2)} <span className="text-slate-400 text-xs">/{product.unit}</span></div>
                       {product.branchPrices && product.branchPrices.length > 0 && (
                         <div className="text-[10px] text-blue-600 mt-1 flex items-center justify-end">
                           <Store className="w-3 h-3 mr-1" />
                           Multi-price
                         </div>
                       )}
                    </td>
                    <td className="px-6 py-4 text-right whitespace-nowrap">
                      <div className="flex flex-col items-end">
                        <div className={`font-bold flex items-center justify-end ${isLowStock ? 'text-red-600' : 'text-slate-700'}`}>
                          {isLowStock && (
                            <div className="flex items-center mr-2 bg-red-100 text-red-700 px-1.5 py-0.5 rounded text-[10px] uppercase font-bold tracking-wide shadow-sm">
                              <AlertTriangle className="w-3 h-3 mr-1" />
                              Low
                            </div>
                          )}
                          {product.stock} <span className="text-xs font-normal text-slate-500 ml-1">{product.unit}s</span>
                        </div>
                        <span className="text-[10px] text-slate-400">Min: {product.minStock || 20}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center whitespace-nowrap">
                      <div className="flex items-center justify-center space-x-2 opacity-50 group-hover:opacity-100 transition-opacity">
                        <button 
                          onClick={() => handleOpenEditModal(product)}
                          className="p-1.5 text-slate-500 hover:text-primary-600 hover:bg-primary-50 rounded transition-colors"
                        >
                          <Edit2 className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => onDeleteProduct(product.id)}
                          className="p-1.5 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {paginatedProducts.length === 0 && (
                <tr>
                  <td colSpan={6} className="text-center py-8 text-slate-400">
                    No products found matching your filters.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {filteredProducts.length > 0 && (
          <div className="p-4 border-t border-slate-200 bg-slate-50 flex flex-col sm:flex-row items-center justify-between gap-4">
            <div className="text-sm text-slate-500 text-center sm:text-left">
              Showing <span className="font-medium">{startIndex + 1}</span> to <span className="font-medium">{Math.min(startIndex + itemsPerPage, filteredProducts.length)}</span> of <span className="font-medium">{filteredProducts.length}</span> results
            </div>
            <div className="flex items-center space-x-2">
              <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="p-2 border border-slate-300 rounded-lg hover:bg-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronLeft className="w-4 h-4 text-slate-600" />
              </button>
              <div className="flex items-center space-x-1">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  let p = i + 1;
                  if (totalPages > 5 && currentPage > 3) {
                     p = currentPage - 2 + i;
                  }
                  if (p > totalPages) return null;

                  return (
                    <button
                      key={p}
                      onClick={() => setCurrentPage(p)}
                      className={`w-8 h-8 rounded-lg text-sm font-medium transition-colors ${
                        currentPage === p 
                          ? 'bg-construction-orange text-white' 
                          : 'text-slate-600 hover:bg-slate-200'
                      }`}
                    >
                      {p}
                    </button>
                  );
                })}
              </div>
              <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="p-2 border border-slate-300 rounded-lg hover:bg-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronRight className="w-4 h-4 text-slate-600" />
              </button>
            </div>
          </div>
        )}
      </div>

      {isAiModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          {/* AI Modal Content ... (Same as before) */}
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[85vh] flex flex-col overflow-hidden animate-fade-in">
            <div className="bg-gradient-to-r from-slate-900 to-slate-800 p-6 flex items-center justify-between shrink-0">
              <div className="flex items-center space-x-3">
                <div className="p-2 bg-gradient-to-br from-purple-500 to-indigo-500 rounded-lg shadow-lg">
                  <Sparkles className="w-6 h-6 text-white" />
                </div>
                <div>
                  <h3 className="text-xl font-bold text-white">AI Inventory Intelligence</h3>
                  <p className="text-slate-400 text-xs mt-0.5">Powered by Gemini AI Analysis</p>
                </div>
              </div>
              <button 
                onClick={() => setIsAiModalOpen(false)}
                className="text-slate-400 hover:text-white transition-colors p-1 rounded-full hover:bg-white/10"
              >
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="flex-1 overflow-hidden flex flex-col bg-slate-50 relative">
              {aiLoading ? (
                <div className="flex-1 flex flex-col items-center justify-center p-12">
                  <div className="relative">
                    <div className="absolute inset-0 bg-purple-500 blur-xl opacity-20 rounded-full animate-pulse"></div>
                    <Loader2 className="w-16 h-16 text-purple-600 animate-spin relative z-10" />
                  </div>
                  <h4 className="mt-6 text-lg font-semibold text-slate-700">Analyzing Sales & Stock Patterns...</h4>
                  <p className="text-slate-500 text-sm mt-2 max-w-md text-center">
                    Reviewing inventory levels, sales velocity, and historical trends to generate actionable insights.
                  </p>
                </div>
              ) : !aiResult ? (
                <div className="flex-1 flex flex-col items-center justify-center p-12 text-center">
                  <AlertTriangle className="w-12 h-12 text-slate-300 mb-4" />
                  <p className="text-slate-500">Analysis could not be generated. Please try again later.</p>
                </div>
              ) : (
                <div className="flex flex-col h-full">
                  <div className="flex border-b border-slate-200 bg-white shrink-0 overflow-x-auto">
                    <button
                      onClick={() => setActiveAiTab('reorder')}
                      className={`px-6 py-4 text-sm font-medium flex items-center justify-center transition-all whitespace-nowrap min-w-fit ${
                        activeAiTab === 'reorder' 
                          ? 'border-b-2 border-red-500 text-red-600 bg-red-50/50' 
                          : 'text-slate-500 hover:bg-slate-50'
                      }`}
                    >
                      <AlertCircle className="w-4 h-4 mr-2" />
                      Restock Alerts ({aiResult.reorders.length})
                    </button>
