import React, { useMemo, useState } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  LineChart,
  Line,
  PieChart,
  Pie,
  Cell,
  Legend,
  AreaChart,
  Area
} from 'recharts';
import { Sale, Product } from '../types';
import { TrendingUp, DollarSign, Package, AlertCircle, AlertTriangle, CalendarRange, Wallet, Calendar, Filter } from 'lucide-react';
import { INITIAL_CATEGORIES_TREE } from '../services/data';
import { useGlobal } from '../context/GlobalContext';

interface DashboardProps {
  sales: Sale[];
  products: Product[];
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d', '#ffc658'];

type TimeRange = '7d' | '30d' | '90d' | 'all';

export const Dashboard: React.FC<DashboardProps> = ({ sales, products }) => {
  const { t } = useGlobal();
  const [timeRange, setTimeRange] = useState<TimeRange>('30d');

  // 1. Filter Sales based on Time Range
  const dashboardMetrics = useMemo(() => {
    const today = new Date();
    let startDate = new Date();

    if (timeRange === '7d') startDate.setDate(today.getDate() - 7);
    else if (timeRange === '30d') startDate.setDate(today.getDate() - 30);
    else if (timeRange === '90d') startDate.setDate(today.getDate() - 90);
    else startDate = new Date(0); // Beginning of time

    // Filter sales strictly by date range and non-voided status
    const filteredSales = sales.filter(s => {
       const saleDate = new Date(s.date);
       return saleDate >= startDate && saleDate <= today && s.status !== 'voided';
    });

    const totalRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const totalOrders = filteredSales.length;

    // Average Order Value
    const aov = totalOrders > 0 ? totalRevenue / totalOrders : 0;

    return { filteredSales, totalRevenue, totalOrders, aov, startDate };
  }, [sales, timeRange]);

  // 2. Dynamic Trend Data
  const trendData = useMemo(() => {
    const dailyMap = new Map<string, number>();
    const today = new Date();

    // Determine number of data points to generate (fill gaps with 0)
    let daysToGenerate = 30;
    if (timeRange === '7d') daysToGenerate = 7;
    else if (timeRange === '90d') daysToGenerate = 90;
    else if (timeRange === 'all') daysToGenerate = 60; // Cap 'all' visual to last 60 active days or aggregate by month (simplified here to daily)

    for(let i = daysToGenerate - 1; i >= 0; i--) {
        const d = new Date(today);
        d.setDate(d.getDate() - i);
        const key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        dailyMap.set(key, 0);
    }

    dashboardMetrics.filteredSales.forEach(sale => {
      const dateStr = new Date(sale.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      // Only set if within our generated view window (for 'all' view specifically)
      if (dailyMap.has(dateStr)) {
        dailyMap.set(dateStr, (dailyMap.get(dateStr) || 0) + sale.total);
      } else if (timeRange === 'all') {
         // dynamic add for all time if strictly needed, but fixed window is usually cleaner for charts
      }
    });

    return Array.from(dailyMap).map(([name, sales]) => ({ name, sales }));
  }, [dashboardMetrics.filteredSales, timeRange]);

  // 3. Category Breakdown
  const categoryData = useMemo(() => {
    const catMap = new Map<string, number>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        let catName = item.category;
        const catObj = INITIAL_CATEGORIES_TREE.find(c => c.id === item.category);
        if (catObj) catName = catObj.name;

        const lineTotal = item.sellPrice * item.quantity;
        catMap.set(catName, (catMap.get(catName) || 0) + lineTotal);
      });
    });

    const result = Array.from(catMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    // Group small categories into "Other" if too many
    if (result.length > 5) {
       const top5 = result.slice(0, 5);
       const others = result.slice(5).reduce((sum, item) => sum + item.value, 0);
       return [...top5, { name: 'Others', value: others }];
    }
    return result;
  }, [dashboardMetrics.filteredSales]);

  // 4. Top Selling Products
  const topProducts = useMemo(() => {
    const prodMap = new Map<string, { name: string; revenue: number; qty: number; unit: string }>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        const existing = prodMap.get(item.id) || { name: item.name, revenue: 0, qty: 0, unit: item.unit };
        existing.revenue += (item.sellPrice * item.quantity);
        existing.qty += (item.quantity / (item.sellConversionFactor || 1));
        prodMap.set(item.id, existing);
      });
    });

    return Array.from(prodMap.values())
      .sort((a, b) => b.revenue - a.revenue)
      .slice(0, 5);
  }, [dashboardMetrics.filteredSales]);

  // Outstanding Debt (Global, not time filtered usually, but useful context)
  const totalOutstanding = useMemo(() => {
     return sales
        .filter(s => s.status !== 'voided' && (s.paymentStatus === 'unpaid' || s.paymentStatus === 'partial'))
        .reduce((acc, s) => acc + (s.remainingAmount || s.total), 0);
  }, [sales]);

  // Low Stock Logic
  const lowStockProducts = products.filter(p => p.stock < (p.minStock || 20)).sort((a, b) => a.stock - b.stock);
  const lowStockCount = lowStockProducts.length;

  const StatCard = ({ title, value, icon: Icon, color, subtext, trend }: any) => (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col justify-between h-full">
      <div className="flex items-start justify-between mb-4">
        <div>
          <p className="text-sm font-medium text-slate-500">{title}</p>
          <h3 className="text-2xl font-bold text-slate-800 mt-1">{value}</h3>
        </div>
        <div className={`p-3 rounded-full ${color}`}>
          <Icon className="w-5 h-5 text-white" />
        </div>
      </div>
      {subtext && (
         <div className="mt-auto pt-2 border-t border-slate-50">
            <p className="text-xs text-slate-400 flex items-center">
               {trend === 'up' && <TrendingUp className="w-3 h-3 mr-1 text-green-500" />}
               {subtext}
            </p>
         </div>
      )}
    </div>
  );

  return (
    <div className="space-y-6 animate-fade-in pb-12">
      {/* Header & Filter */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">{t('dashboard.title')}</h2>
          <p className="text-slate-500 text-sm flex items-center mt-1">
            <CalendarRange className="w-4 h-4 mr-1" />
            Performance Overview
          </p>
        </div>

        <div className="bg-white p-1 rounded-lg border border-slate-200 flex shadow-sm overflow-x-auto">
           {(['7d', '30d', '90d', 'all'] as const).map((range) => (
              <button
                key={range}
                onClick={() => setTimeRange(range)}
                className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all whitespace-nowrap ${
                   timeRange === range 
                   ? 'bg-slate-800 text-white shadow-sm' 
                   : 'text-slate-600 hover:bg-slate-100'
                }`}
              >
                 {range === '7d' ? '7 Days' : range === '30d' ? '30 Days' : range === '90d' ? '3 Months' : 'All Time'}
              </button>
           ))}
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title={t('dashboard.revenue')}
          value={`$${dashboardMetrics.totalRevenue.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`} 
          icon={DollarSign} 
          color="bg-green-500" 
          subtext={`${dashboardMetrics.totalOrders} orders in period`}
          trend="up"
        />
        <StatCard 
          title="Avg. Order Value"
          value={`$${dashboardMetrics.aov.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`} 
          icon={TrendingUp} 
          color="bg-blue-500" 
          subtext="Per transaction average"
        />
        <StatCard 
          title="Outstanding Debt"
          value={`$${totalOutstanding.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`} 
          icon={Wallet} 
          color="bg-orange-500" 
          subtext="Total unpaid (All time)"
        />
        <StatCard 
          title="Low Stock Alerts"
          value={lowStockCount} 
          icon={AlertCircle} 
          color={lowStockCount > 0 ? "bg-red-500" : "bg-slate-400"} 
          subtext={`${products.length} total items`}
        />
      </div>

      {/* Low Stock Alert Section */}
      {lowStockProducts.length > 0 && (
        <div className="bg-red-50 border border-red-200 rounded-xl overflow-hidden shadow-sm">
          <div className="p-4 bg-red-100 border-b border-red-200 flex items-center justify-between">
            <h3 className="text-red-800 font-bold flex items-center text-sm uppercase tracking-wide">
              <AlertTriangle className="w-5 h-5 mr-2" />
              {t('dashboard.critical')} ({lowStockCount})
            </h3>
          </div>
          <div className="p-4 overflow-x-auto">
             <div className="flex space-x-4 pb-2">
               {lowStockProducts.map(p => (
                 <div key={p.id} className="min-w-[200px] bg-white p-3 rounded-lg border border-red-100 shadow-sm flex flex-col group hover:border-red-300 transition-colors cursor-pointer">
                    <div className="flex justify-between items-start mb-2">
                       <span className="font-semibold text-slate-700 truncate w-32 text-sm" title={p.name}>{p.name}</span>
                       <span className="text-[10px] font-mono bg-red-50 text-red-600 px-1.5 py-0.5 rounded border border-red-100">
                          {p.sku}
                       </span>
                    </div>
                    <div className="flex justify-between items-end mt-auto">
                      <div className="flex flex-col">
                        <span className="text-[10px] text-slate-400 uppercase">Current</span>
