                      </div>
                      <div className="flex flex-col items-end">
                         <span className="text-[10px] text-slate-400 mb-0.5">Min: {p.minStock || 20}</span>
                         <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500 uppercase font-bold">
                           {p.unit}
                         </span>
                      </div>
                    </div>
                 </div>
               ))}
             </div>
          </div>
        </div>
      )}

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Sales Trend */}
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center justify-between mb-6">
             <h3 className="text-lg font-bold text-slate-800">{t('dashboard.trend')}</h3>
             <div className="flex items-center text-xs text-slate-500">
                <span className="w-3 h-3 bg-primary-500 rounded-full mr-2"></span> Revenue
