  updateCategory: (c: CategoryItem) => void;
  deleteCategory: (id: string) => void;

  addBranch: (b: Branch) => void;
  updateBranch: (b: Branch) => void;
  deleteBranch: (id: string) => void;

  addPos: (p: PosMachine) => void;
  updatePos: (p: PosMachine) => void;
  deletePos: (id: string) => void;

  addWarehouse: (w: Warehouse) => void;
  updateWarehouse: (w: Warehouse) => void;
  deleteWarehouse: (id: string) => void;

  addLocation: (l: StorageLocation) => void;
  updateLocation: (l: StorageLocation) => void;
  deleteLocation: (id: string) => void;

  addUser: (u: User) => void;
  updateUser: (u: User) => void;
  deleteUser: (id: string) => void;

  addCustomer: (c: Customer) => void;
  updateCustomer: (c: Customer) => void;
  deleteCustomer: (id: string) => void;
  addCustomerLevel: (l: CustomerLevel) => void;
  updateCustomerLevel: (l: CustomerLevel) => void;
  deleteCustomerLevel: (id: string) => void;

  updateTransfer: (t: StockTransfer) => void;
  deleteTransfer: (id: string) => void;

  updateCount: (c: StockCount) => void;
  deleteCount: (id: string) => void;

  updateReservation: (r: StockReservation) => void;
  deleteReservation: (id: string) => void;

  updateReceipt: (r: StockReceipt) => void;
  deleteReceipt: (id: string) => void;

  updateAdjustment: (a: StockAdjustment) => void;
  deleteAdjustment: (id: string) => void;

  handleStockStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
  handleSyncOperation: (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => void;

  startShift: (branchId: string, startCash: number, notes?: string) => void;
  endShift: (shiftId: string, endCash: number, notes?: string) => void;
  addShiftSchedule: (s: ShiftSchedule) => void;
  deleteShiftSchedule: (id: string) => void;

  addPromotion: (p: Promotion) => void;
  updatePromotion: (p: Promotion) => void;
  deletePromotion: (id: string) => void;

  updateSettings: (s: SystemSettings) => void;

  settleSaleDebt: (saleId: string, amount: number, method: string) => Promise<void>;
  handleVoidSale: (saleId: string) => void;

  t: (key: string) => string;
}

const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

// Helper for API calls with silent 404 handling for Demo Mode
const apiRequest = async (url: string, method: string = 'GET', body?: any) => {
  try {
    const options: RequestInit = {
      method,
      headers: { 'Content-Type': 'application/json' },
    };
    if (body) options.body = JSON.stringify(body);

    const res = await fetch(url, options);

    // Gracefully handle 404 (API not present in demo/static env)
    if (res.status === 404) {
      return null;
    }

    if (!res.ok) {
      throw new Error(`API Error: ${res.statusText}`);
    }

    return await res.json();
  } catch (error) {
    // Only log warnings for non-404 errors to keep console clean in demo mode
    // console.warn(`Request failed: ${method} ${url}`, error);
    return null;
  }
};

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Data State initialized with Fallback Data
  // If API fails or DB is empty, these serve as the demo state.
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [sales, setSales] = useState<Sale[]>(INITIAL_SALES);
  const [units, setUnits] = useState<UnitDefinition[]>(INITIAL_UNITS);
  const [categories, setCategories] = useState<CategoryItem[]>(INITIAL_CATEGORIES_TREE);
  const [branches, setBranches] = useState<Branch[]>(INITIAL_BRANCHES);
  const [posMachines, setPosMachines] = useState<PosMachine[]>(INITIAL_POS_MACHINES);
  const [warehouses, setWarehouses] = useState<Warehouse[]>(INITIAL_WAREHOUSES);
  const [locations, setLocations] = useState<StorageLocation[]>(INITIAL_LOCATIONS);

  // Stock Docs
  const [transfers, setTransfers] = useState<StockTransfer[]>(INITIAL_TRANSFERS);
  const [counts, setCounts] = useState<StockCount[]>(INITIAL_COUNTS);
  const [reservations, setReservations] = useState<StockReservation[]>(INITIAL_RESERVATIONS);
  const [receipts, setReceipts] = useState<StockReceipt[]>(INITIAL_RECEIPTS);
  const [adjustments, setAdjustments] = useState<StockAdjustment[]>(INITIAL_ADJUSTMENTS);

  const [syncLogs, setSyncLogs] = useState<SyncLog[]>(INITIAL_SYNC_LOGS);
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [customerLevels, setCustomerLevels] = useState<CustomerLevel[]>(INITIAL_CUSTOMER_LEVELS);

  const [shifts, setShifts] = useState<Shift[]>([]);
  const [shiftSchedules, setShiftSchedules] = useState<ShiftSchedule[]>(INITIAL_SHIFT_SCHEDULES);
  const [promotions, setPromotions] = useState<Promotion[]>(INITIAL_PROMOTIONS);
  const [settings, setSettingsState] = useState<SystemSettings>(INITIAL_SETTINGS);

  // --- Real Data Loading ---
  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        // Parallel fetching of core data
        const [
          fetchedProducts, fetchedSales, fetchedCustomers, fetchedSettings, 
          fetchedBranches, fetchedUsers, fetchedCategories, fetchedUnits, fetchedWarehouses
        ] = await Promise.all([
          apiRequest('/api/products'),
          apiRequest('/api/sales'),
          apiRequest('/api/customers'),
          apiRequest('/api/settings'),
          apiRequest('/api/branches'),
          apiRequest('/api/users'),
          apiRequest('/api/categories'),
          apiRequest('/api/units'),
          apiRequest('/api/warehouses')
        ]);

        if (fetchedProducts && Array.isArray(fetchedProducts)) setProducts(fetchedProducts);
        if (fetchedSales && Array.isArray(fetchedSales)) setSales(fetchedSales);
        if (fetchedCustomers && Array.isArray(fetchedCustomers)) setCustomers(fetchedCustomers);
        if (fetchedSettings && !fetchedSettings.error) setSettingsState(fetchedSettings);
        if (fetchedBranches && Array.isArray(fetchedBranches)) setBranches(fetchedBranches);
        if (fetchedUsers && Array.isArray(fetchedUsers)) setUsers(fetchedUsers);
        if (fetchedCategories && Array.isArray(fetchedCategories)) setCategories(fetchedCategories);
        if (fetchedUnits && Array.isArray(fetchedUnits)) setUnits(fetchedUnits);
        if (fetchedWarehouses && Array.isArray(fetchedWarehouses)) setWarehouses(fetchedWarehouses);

        // Fetch stock documents in background to speed up initial load
        fetchStockDocs();

      } catch (error) {
        console.warn("Using fallback/demo data due to API error:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  const fetchStockDocs = async () => {
    try {
      const [tr, ct, rs, rc, aj] = await Promise.all([
        apiRequest('/api/stock/transfer'),
        apiRequest('/api/stock/count'),
        apiRequest('/api/stock/reservation'),
        apiRequest('/api/stock/receipt'),
        apiRequest('/api/stock/adjustment'),
      ]);
      if (tr) setTransfers(tr);
      if (ct) setCounts(ct);
      if (rs) setReservations(rs);
      if (rc) setReceipts(rc);
      if (aj) setAdjustments(aj);
    } catch (e) {
      // console.warn("Stock docs fetch failed, using local");
    }
  };

  const t = (key: string): string => {
    const keys = key.split('.');
    let current: any = translations[settings.language] || translations['en'];
    for (const k of keys) {
      if (current[k] === undefined) return key;
      current = current[k];
    }
    return typeof current === 'string' ? current : key;
  };

  // --- ACTIONS (API First with Optimistic Updates where safe) ---

  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number, 
    paymentMethod: any = 'cash',
    amountReceived?: number,
    change?: number
  ): Promise<Sale> => {
    // 1. Prepare Payload
    const payload = {
      items: items.map(i => ({
        productId: i.id,
        variantId: i.selectedVariantId,
        quantity: i.quantity,
        sellPrice: i.sellPrice
      })),
      total,
      subtotal,
      discountAmount,
      paymentMethod,
      amountReceived,
      change,
      customerId
    };

    // 2. Call API
    const newSale = await apiRequest('/api/sales', 'POST', payload);

    if (newSale && !newSale.error) {
      // 3. Update Local State (Success)
      setSales(prev => [newSale, ...prev]);

      // Update Inventory Locally (Optimistic)
      setProducts(prevProducts => prevProducts.map(product => {
        const cartItem = items.find(item => item.id === product.id);
        if (cartItem) {
          // Note: In real app, re-fetch product to get exact stock from server logic
          return { ...product, stock: product.stock - cartItem.quantity };
        }
        return product;
      }));

      return newSale;
    } else {
      // Fallback for Demo Mode (if API fails or returns error)
      const fallbackSale: Sale = {
        id: `S-${Date.now()}`,
        items, total, subtotal, discountAmount,
        date: new Date().toISOString(),
        paymentMethod, amountReceived, change, customerId,
        customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined,
        status: 'completed',
        paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
        remainingAmount: paymentMethod === 'credit' ? Math.max(0, total - (amountReceived || 0)) : 0,
        syncStatus: 'pending'
      };
      setSales(prev => [fallbackSale, ...prev]);
      return fallbackSale;
    }
  };

  const handleVoidSale = async (saleId: string) => {
     // API Call
     const res = await apiRequest(`/api/sales/${saleId}`, 'PUT', { status: 'voided' });

     if (res && !res.error) {
       setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: 'voided' } : s));
       // Ideally refresh products here to show restored stock
       const updatedProducts = await apiRequest('/api/products');
       if (updatedProducts) setProducts(updatedProducts);
     } else {
        // Fallback
        setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: 'voided' } : s));
     }
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
     // This would be a new payment endpoint, but for now we update local
     setSales(prev => prev.map(s => {
        if (s.id === saleId) {
           return {
              ...s,
              paymentStatus: 'paid',
              remainingAmount: 0,
              amountReceived: (s.amountReceived || 0) + amount
           };
        }
        return s;
     }));
  };

  // --- CRUD Operations (API Integrated) ---

  const addProduct = async (p: Product) => {
    const res = await apiRequest('/api/products', 'POST', p);
    if (res && !res.error) {
      setProducts(prev => [...prev, res]);
    } else {
      setProducts(prev => [...prev, p]); // Fallback
    }
  };

  const updateProduct = async (p: Product) => {
    const res = await apiRequest(`/api/products/${p.id}`, 'PUT', p);
    if (res && !res.error) {
      setProducts(prev => prev.map(item => item.id === p.id ? res : item));
    } else {
      setProducts(prev => prev.map(item => item.id === p.id ? p : item));
    }
  };

  const deleteProduct = async (id: string) => {
    await apiRequest(`/api/products/${id}`, 'DELETE');
    setProducts(prev => prev.filter(item => item.id !== id));
  };

  // Customers
  const addCustomer = async (c: Customer) => {
    const res = await apiRequest('/api/customers', 'POST', c);
    if (res && !res.error) setCustomers(prev => [...prev, res]);
    else setCustomers(prev => [...prev, c]);
  };

  const updateCustomer = async (c: Customer) => {
    const res = await apiRequest(`/api/customers/${c.id}`, 'PUT', c);
    if (res && !res.error) setCustomers(prev => prev.map(item => item.id === c.id ? res : item));
    else setCustomers(prev => prev.map(item => item.id === c.id ? c : item));
  };

  const deleteCustomer = async (id: string) => {
    await apiRequest(`/api/customers/${id}`, 'DELETE');
    setCustomers(prev => prev.filter(item => item.id !== id));
  };

  // Users
  const addUser = async (u: User) => {
    const res = await apiRequest('/api/users', 'POST', u);
    if (res && !res.error) setUsers(prev => [...prev, res]);
    else setUsers(prev => [...prev, u]);
  };

  const updateUser = async (u: User) => {
    const res = await apiRequest(`/api/users/${u.id}`, 'PUT', u);
    if (res && !res.error) setUsers(prev => prev.map(item => item.id === u.id ? res : item));
    else setUsers(prev => prev.map(item => item.id === u.id ? u : item));
  };

  const deleteUser = async (id: string) => {
    await apiRequest(`/api/users/${id}`, 'DELETE');
    setUsers(prev => prev.filter(item => item.id !== id));
  };

  // Settings
  const updateSettings = async (s: SystemSettings) => {
    setSettingsState(s); // Optimistic update
    await apiRequest('/api/settings', 'POST', s);
  };

  // --- Other CRUDs (Simplified: mostly local fallback or simple API pattern) ---
  // To save space, implementing API pattern for critical ones, local fallback for others until connected

  const addUnit = async (u: UnitDefinition) => {
    const res = await apiRequest('/api/units', 'POST', u);
    setUnits(prev => [...prev, res || u]);
  };
  const updateUnit = async (u: UnitDefinition) => {
    const res = await apiRequest(`/api/units/${u.id}`, 'PUT', u);
    setUnits(prev => prev.map(item => item.id === u.id ? (res || u) : item));
  };
  const deleteUnit = async (id: string) => {
    await apiRequest(`/api/units/${id}`, 'DELETE');
    setUnits(prev => prev.filter(item => item.id !== id));
  };

  const addCategory = async (c: CategoryItem) => {
    const res = await apiRequest('/api/categories', 'POST', c);
    setCategories(prev => [...prev, res || c]);
  };
  const updateCategory = async (c: CategoryItem) => {
    const res = await apiRequest(`/api/categories/${c.id}`, 'PUT', c);
    setCategories(prev => prev.map(item => item.id === c.id ? (res || c) : item));
  };
  const deleteCategory = async (id: string) => {
    await apiRequest(`/api/categories/${id}`, 'DELETE');
    setCategories(prev => prev.filter(item => item.id !== id));
  };

  const addBranch = async (b: Branch) => {
    const res = await apiRequest('/api/branches', 'POST', b);
    setBranches(prev => [...prev, res || b]);
  };
  const updateBranch = async (b: Branch) => {
    const res = await apiRequest(`/api/branches/${b.id}`, 'PUT', b);
    setBranches(prev => prev.map(item => item.id === b.id ? (res || b) : item));
  };
  const deleteBranch = async (id: string) => {
    await apiRequest(`/api/branches/${id}`, 'DELETE');
    setBranches(prev => prev.filter(item => item.id !== id));
  };

  // Simple local updaters for less critical data or not yet API-connected
  const addPos = (p: PosMachine) => setPosMachines(prev => [...prev, p]);
  const updatePos = (p: PosMachine) => setPosMachines(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePos = (id: string) => setPosMachines(prev => prev.filter(item => item.id !== id));

  const addWarehouse = async (w: Warehouse) => {
    const res = await apiRequest('/api/warehouses', 'POST', w);
    setWarehouses(prev => [...prev, res || w]);
  };
  const updateWarehouse = async (w: Warehouse) => {
    const res = await apiRequest(`/api/warehouses/${w.id}`, 'PUT', w);
    setWarehouses(prev => prev.map(item => item.id === w.id ? (res || w) : item));
  };
  const deleteWarehouse = async (id: string) => {
    await apiRequest(`/api/warehouses/${id}`, 'DELETE');
    setWarehouses(prev => prev.filter(item => item.id !== id));
  };

  const addLocation = async (l: StorageLocation) => {
    const res = await apiRequest('/api/locations', 'POST', l);
    setLocations(prev => [...prev, res || l]);
  };
  const updateLocation = async (l: StorageLocation) => {
    const res = await apiRequest(`/api/locations/${l.id}`, 'PUT', l);
    setLocations(prev => prev.map(item => item.id === l.id ? (res || l) : item));
  };
  const deleteLocation = async (id: string) => {
    await apiRequest(`/api/locations/${id}`, 'DELETE');
    setLocations(prev => prev.filter(item => item.id !== id));
  };

  const addCustomerLevel = async (l: CustomerLevel) => {
    const res = await apiRequest('/api/customer-levels', 'POST', l);
    setCustomerLevels(prev => [...prev, res || l]);
  };
  const updateCustomerLevel = async (l: CustomerLevel) => {
    const res = await apiRequest(`/api/customer-levels/${l.id}`, 'PUT', l);
    setCustomerLevels(prev => prev.map(item => item.id === l.id ? (res || l) : item));
  };
  const deleteCustomerLevel = async (id: string) => {
    await apiRequest(`/api/customer-levels/${id}`, 'DELETE');
    setCustomerLevels(prev => prev.filter(item => item.id !== id));
  };

  // Stock Documents (API Integration)
  const updateTransfer = async (t: StockTransfer) => {
    const exists = transfers.find(item => item.id === t.id);
    let res;
    if (exists) res = await apiRequest(`/api/stock/transfer/${t.id}`, 'PUT', t);
    else res = await apiRequest('/api/stock/transfer', 'POST', t);

    if(res && !res.error) {
       // Refresh products if status changed to Approved/Completed as inventory changed
       if (t.status === 'Approved' || t.status === 'Completed') {
          const prods = await apiRequest('/api/products');
          if(prods) setProducts(prods);
       }
       // Update list
       if (exists) setTransfers(prev => prev.map(item => item.id === t.id ? res : item));
       else setTransfers(prev => [res, ...prev]);
    } else {
       if (exists) setTransfers(prev => prev.map(item => item.id === t.id ? t : item));
       else setTransfers(prev => [t, ...prev]);
    }
  };

  const deleteTransfer = async (id: string) => {
    await apiRequest(`/api/stock/transfer/${id}`, 'DELETE');
    setTransfers(prev => prev.filter(item => item.id !== id));
  };

  const updateCount = async (c: StockCount) => {
    const exists = counts.find(item => item.id === c.id);
    let res;
    if (exists) res = await apiRequest(`/api/stock/count/${c.id}`, 'PUT', c);
    else res = await apiRequest('/api/stock/count', 'POST', c);

    if (res && !res.error) {
       if (c.status === 'Completed') {
          const prods = await apiRequest('/api/products');
          if(prods) setProducts(prods);
       }
       if (exists) setCounts(prev => prev.map(item => item.id === c.id ? res : item));
       else setCounts(prev => [res, ...prev]);
    }
  };

  const deleteCount = async (id: string) => {
    await apiRequest(`/api/stock/count/${id}`, 'DELETE');
    setCounts(prev => prev.filter(item => item.id !== id));
  };

  const updateReservation = async (r: StockReservation) => {
    const exists = reservations.find(item => item.id === r.id);
    let res;
    if (exists) res = await apiRequest(`/api/stock/reservation/${r.id}`, 'PUT', r);
    else res = await apiRequest('/api/stock/reservation', 'POST', r);
    if(res) {
       if (exists) setReservations(prev => prev.map(item => item.id === r.id ? res : item));
       else setReservations(prev => [res, ...prev]);
    }
  };

  const deleteReservation = async (id: string) => {
    await apiRequest(`/api/stock/reservation/${id}`, 'DELETE');
    setReservations(prev => prev.filter(item => item.id !== id));
  };

  const updateReceipt = async (r: StockReceipt) => {
    const exists = receipts.find(item => item.id === r.id);
    let res;
    if (exists) res = await apiRequest(`/api/stock/receipt/${r.id}`, 'PUT', r);
    else res = await apiRequest('/api/stock/receipt', 'POST', r);

    if (res && !res.error) {
       if (r.status === 'Completed') {
          const prods = await apiRequest('/api/products');
          if(prods) setProducts(prods);
       }
       if (exists) setReceipts(prev => prev.map(item => item.id === r.id ? res : item));
       else setReceipts(prev => [res, ...prev]);
    }
  };

  const deleteReceipt = async (id: string) => {
    await apiRequest(`/api/stock/receipt/${id}`, 'DELETE');
    setReceipts(prev => prev.filter(item => item.id !== id));
  };

  const updateAdjustment = async (a: StockAdjustment) => {
    const exists = adjustments.find(item => item.id === a.id);
    let res;
    if (exists) res = await apiRequest(`/api/stock/adjustment/${a.id}`, 'PUT', a);
    else res = await apiRequest('/api/stock/adjustment', 'POST', a);

    if (res && !res.error) {
       if (a.status === 'Approved') {
          const prods = await apiRequest('/api/products');
          if(prods) setProducts(prods);
       }
       if (exists) setAdjustments(prev => prev.map(item => item.id === a.id ? res : item));
       else setAdjustments(prev => [res, ...prev]);
    }
  };

  const deleteAdjustment = async (id: string) => {
    await apiRequest(`/api/stock/adjustment/${id}`, 'DELETE');
    setAdjustments(prev => prev.filter(item => item.id !== id));
  };

  // Status Change Logic - Wrapper for specific doc updates
  const handleStockStatusChange = (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => {
    // Find the item and call the appropriate update function
    let item: any;
    switch (type) {
      case 'transfer':
        item = transfers.find(t => t.id === id);
        if (item) updateTransfer({ ...item, status });
        break;
      case 'count':
        item = counts.find(c => c.id === id);
        if (item) updateCount({ ...item, status });
        break;
      case 'reservation':
        item = reservations.find(r => r.id === id);
        if (item) updateReservation({ ...item, status });
        break;
      case 'receipt':
        item = receipts.find(r => r.id === id);
        if (item) updateReceipt({ ...item, status });
        break;
      case 'adjustment':
        item = adjustments.find(a => a.id === id);
        if (item) updateAdjustment({ ...item, status });
        break;
    }
  };

  const handleSyncOperation = async (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
     // In a real app, this would trigger specific sync logic
     // Here we just log it to the backend logs
     const log = {
        type,
        status: 'Success',
        details: type === 'Push' ? 'Uploaded pending items' : 'Synced successfully',
        durationMs: Math.floor(Math.random() * 500) + 100
     };
     const res = await apiRequest('/api/sync/logs', 'POST', log);
     if (res) setSyncLogs(prev => [res, ...prev]);
  };

  const startShift = async (branchId: string, startCash: number, notes?: string) => {
     if (!currentUser) return;
     const res = await apiRequest('/api/shifts', 'POST', {
        userId: currentUser.id,
        branchId,
        startCash,
        notes
     });
     if (res && !res.error) setShifts(prev => [res, ...prev]);
  };

  const endShift = async (shiftId: string, endCash: number, notes?: string) => {
     const res = await apiRequest(`/api/shifts/${shiftId}`, 'PUT', {
        endCash,
        notes
     });
     if (res && !res.error) {
        setShifts(prev => prev.map(s => s.id === shiftId ? res : s));
     }
  };

  const addShiftSchedule = (s: ShiftSchedule) => setShiftSchedules(prev => [...prev, s]);
  const deleteShiftSchedule = (id: string) => setShiftSchedules(prev => prev.filter(s => s.id !== id));

  const addPromotion = (p: Promotion) => setPromotions(prev => [...prev, p]);
  const updatePromotion = (p: Promotion) => setPromotions(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePromotion = (id: string) => setPromotions(prev => prev.filter(item => item.id !== id));

  return (
    <GlobalContext.Provider value={{
      currentUser, setCurrentUser, isLoading,
      users, products, sales, units, categories, branches, posMachines, warehouses, locations,
      transfers, counts, reservations, receipts, adjustments, syncLogs, customers, customerLevels,
      shifts, shiftSchedules, promotions, settings,
      processSale, addProduct, updateProduct, deleteProduct,
      addUnit, updateUnit, deleteUnit, addCategory, updateCategory, deleteCategory,
      addBranch, updateBranch, deleteBranch, addPos, updatePos, deletePos,
      addWarehouse, updateWarehouse, deleteWarehouse, addLocation, updateLocation, deleteLocation,
      addUser, updateUser, deleteUser, addCustomer, updateCustomer, deleteCustomer,
      addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,
      updateTransfer, deleteTransfer, updateCount, deleteCount, updateReservation, deleteReservation,
      updateReceipt, deleteReceipt, updateAdjustment, deleteAdjustment,
      handleStockStatusChange, handleSyncOperation,
      startShift, endShift, addShiftSchedule, deleteShiftSchedule,
      addPromotion, updatePromotion, deletePromotion,
      updateSettings, settleSaleDebt, handleVoidSale, t
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

