const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

// Helper for API calls with silent fallback
const apiRequest = async (url: string, method: string = 'GET', body?: any) => {
  try {
    const options: RequestInit = {
      method,
      headers: { 'Content-Type': 'application/json' },
    };
    if (body) options.body = JSON.stringify(body);

    const res = await fetch(url, options);

    if (res.status === 404) {
      // API route not found (client-only mode)
      return null;
    }

    if (!res.ok) {
      // Other error (500, 400)
      throw new Error(`API Error: ${res.statusText}`);
    }

    return await res.json();
  } catch (error) {
    // console.warn(`Request failed: ${method} ${url}`, error);
    return null;
  }
};

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Data State initialized with Fallback Data
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [sales, setSales] = useState<Sale[]>(INITIAL_SALES);
  const [units, setUnits] = useState<UnitDefinition[]>(INITIAL_UNITS);
  const [categories, setCategories] = useState<CategoryItem[]>(INITIAL_CATEGORIES_TREE);
  const [branches, setBranches] = useState<Branch[]>(INITIAL_BRANCHES);
  const [posMachines, setPosMachines] = useState<PosMachine[]>(INITIAL_POS_MACHINES);
  const [warehouses, setWarehouses] = useState<Warehouse[]>(INITIAL_WAREHOUSES);
  const [locations, setLocations] = useState<StorageLocation[]>(INITIAL_LOCATIONS);

  // Stock Docs
  const [transfers, setTransfers] = useState<StockTransfer[]>(INITIAL_TRANSFERS);
  const [counts, setCounts] = useState<StockCount[]>(INITIAL_COUNTS);
  const [reservations, setReservations] = useState<StockReservation[]>(INITIAL_RESERVATIONS);
  const [receipts, setReceipts] = useState<StockReceipt[]>(INITIAL_RECEIPTS);
  const [adjustments, setAdjustments] = useState<StockAdjustment[]>(INITIAL_ADJUSTMENTS);

  const [syncLogs, setSyncLogs] = useState<SyncLog[]>(INITIAL_SYNC_LOGS);
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [customerLevels, setCustomerLevels] = useState<CustomerLevel[]>(INITIAL_CUSTOMER_LEVELS);

  const [shifts, setShifts] = useState<Shift[]>([]);
  const [shiftSchedules, setShiftSchedules] = useState<ShiftSchedule[]>(INITIAL_SHIFT_SCHEDULES);
  const [promotions, setPromotions] = useState<Promotion[]>(INITIAL_PROMOTIONS);
  const [settings, setSettingsState] = useState<SystemSettings>(INITIAL_SETTINGS);

  // --- Real Data Loading ---
  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        // Parallel fetching
        const [
          fetchedProducts, fetchedSales, fetchedCustomers, fetchedSettings, 
          fetchedBranches, fetchedUsers, fetchedCategories, fetchedUnits, fetchedWarehouses
        ] = await Promise.all([
          apiRequest('/api/products'),
          apiRequest('/api/sales'),
          apiRequest('/api/customers'),
          apiRequest('/api/settings'),
          apiRequest('/api/branches'),
          apiRequest('/api/users'),
          apiRequest('/api/categories'),
          apiRequest('/api/units'),
          apiRequest('/api/warehouses')
        ]);

        if (fetchedProducts && Array.isArray(fetchedProducts)) setProducts(fetchedProducts);
        if (fetchedSales && Array.isArray(fetchedSales)) setSales(fetchedSales);
        if (fetchedCustomers && Array.isArray(fetchedCustomers)) setCustomers(fetchedCustomers);
        if (fetchedSettings && !fetchedSettings.error) setSettingsState(fetchedSettings);
        if (fetchedBranches && Array.isArray(fetchedBranches)) setBranches(fetchedBranches);
        if (fetchedUsers && Array.isArray(fetchedUsers)) setUsers(fetchedUsers);
        if (fetchedCategories && Array.isArray(fetchedCategories)) setCategories(fetchedCategories);
        if (fetchedUnits && Array.isArray(fetchedUnits)) setUnits(fetchedUnits);
        if (fetchedWarehouses && Array.isArray(fetchedWarehouses)) setWarehouses(fetchedWarehouses);

        fetchStockDocs();

      } catch (error) {
        // Silent catch for demo mode
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  const fetchStockDocs = async () => {
    try {
      const [tr, ct, rs, rc, aj] = await Promise.all([
        apiRequest('/api/stock/transfer'),
        apiRequest('/api/stock/count'),
        apiRequest('/api/stock/reservation'),
        apiRequest('/api/stock/receipt'),
        apiRequest('/api/stock/adjustment'),
      ]);
      if (tr) setTransfers(tr);
      if (ct) setCounts(ct);
      if (rs) setReservations(rs);
      if (rc) setReceipts(rc);
      if (aj) setAdjustments(aj);
    } catch (e) {}
  };

  const t = (key: string): string => {
    const keys = key.split('.');
    let current: any = translations[settings.language] || translations['en'];
    for (const k of keys) {
      if (current[k] === undefined) return key;
      current = current[k];
    }
    return typeof current === 'string' ? current : key;
  };

  const formatPrice = (amount: number): string => {
    const symbol = settings.currencySymbol || '$';
    // Simplified formatter. In production, use Intl.NumberFormat based on locale
    return `${symbol}${amount.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  // --- ACTIONS ---

  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number, 
    paymentMethod: any = 'cash',
    amountReceived?: number,
    change?: number
  ): Promise<Sale> => {

    const payload = {
      items: items.map(i => ({
        productId: i.id,
        variantId: i.selectedVariantId,
        quantity: i.quantity,
        sellPrice: i.sellPrice
      })),
      total,
      subtotal,
      discountAmount,
      paymentMethod,
      amountReceived,
      change,
      customerId
    };

    const newSale = await apiRequest('/api/sales', 'POST', payload);

    if (newSale && !newSale.error) {
      setSales(prev => [newSale, ...prev]);
      // Optimistic Inventory update
      setProducts(prevProducts => prevProducts.map(product => {
        const cartItem = items.find(item => item.id === product.id);
        if (cartItem) {
          return { ...product, stock: product.stock - cartItem.quantity };
        }
        return product;
      }));
      return newSale;
    } else {
      // Fallback
      const fallbackSale: Sale = {
        id: `S-${Date.now()}`,
        items, total, subtotal, discountAmount,
        date: new Date().toISOString(),
        paymentMethod, amountReceived, change, customerId,
        customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined,
        status: 'completed',
        paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
        remainingAmount: paymentMethod === 'credit' ? Math.max(0, total - (amountReceived || 0)) : 0,
        syncStatus: 'pending'
      };
      setSales(prev => [fallbackSale, ...prev]);
      return fallbackSale;
    }
  };

  const handleVoidSale = async (saleId: string) => {
     const res = await apiRequest(`/api/sales/${saleId}`, 'PUT', { status: 'voided' });
     if (res && !res.error) {
       setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: 'voided' } : s));
       const updatedProducts = await apiRequest('/api/products');
       if (updatedProducts) setProducts(updatedProducts);
     } else {
        setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: 'voided' } : s));
     }
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
     setSales(prev => prev.map(s => {
        if (s.id === saleId) {
           return {
              ...s,
              paymentStatus: 'paid',
              remainingAmount: 0,
              amountReceived: (s.amountReceived || 0) + amount
           };
        }
        return s;
     }));
  };

  // --- CRUD (Simplified wrapper) ---
  const addProduct = async (p: Product) => {
    const res = await apiRequest('/api/products', 'POST', p);
    setProducts(prev => [...prev, res || p]);
  };
  const updateProduct = async (p: Product) => {
    const res = await apiRequest(`/api/products/${p.id}`, 'PUT', p);
    setProducts(prev => prev.map(item => item.id === p.id ? (res || p) : item));
  };
  const deleteProduct = async (id: string) => {
    await apiRequest(`/api/products/${id}`, 'DELETE');
    setProducts(prev => prev.filter(item => item.id !== id));
  };

  const addCustomer = async (c: Customer) => {
    const res = await apiRequest('/api/customers', 'POST', c);
    setCustomers(prev => [...prev, res || c]);
  };
  const updateCustomer = async (c: Customer) => {
    const res = await apiRequest(`/api/customers/${c.id}`, 'PUT', c);
    setCustomers(prev => prev.map(item => item.id === c.id ? (res || c) : item));
  };
  const deleteCustomer = async (id: string) => {
    await apiRequest(`/api/customers/${id}`, 'DELETE');
    setCustomers(prev => prev.filter(item => item.id !== id));
  };

  const addUser = async (u: User) => {
    const res = await apiRequest('/api/users', 'POST', u);
    setUsers(prev => [...prev, res || u]);
  };
  const updateUser = async (u: User) => {
    const res = await apiRequest(`/api/users/${u.id}`, 'PUT', u);
    setUsers(prev => prev.map(item => item.id === u.id ? (res || u) : item));
  };
  const deleteUser = async (id: string) => {
    await apiRequest(`/api/users/${id}`, 'DELETE');
    setUsers(prev => prev.filter(item => item.id !== id));
  };

  const updateSettings = async (s: SystemSettings) => {
    setSettingsState(s);
    await apiRequest('/api/settings', 'POST', s);
  };

  // ... (Other CRUD wrappers follow similar pattern, using local state as fallback)

  const addUnit = (u: any) => setUnits(p => [...p, u]);
  const updateUnit = (u: any) => setUnits(p => p.map(x => x.id === u.id ? u : x));
  const deleteUnit = (id: string) => setUnits(p => p.filter(x => x.id !== id));

  const addCategory = (c: any) => setCategories(p => [...p, c]);
  const updateCategory = (c: any) => setCategories(p => p.map(x => x.id === c.id ? c : x));
  const deleteCategory = (id: string) => setCategories(p => p.filter(x => x.id !== id));

  const addBranch = (b: any) => setBranches(p => [...p, b]);
  const updateBranch = (b: any) => setBranches(p => p.map(x => x.id === b.id ? b : x));
  const deleteBranch = (id: string) => setBranches(p => p.filter(x => x.id !== id));

  const addPos = (p: any) => setPosMachines(prev => [...prev, p]);
  const updatePos = (p: any) => setPosMachines(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePos = (id: string) => setPosMachines(prev => prev.filter(item => item.id !== id));

  const addWarehouse = (w: any) => setWarehouses(p => [...p, w]);
  const updateWarehouse = (w: any) => setWarehouses(p => p.map(x => x.id === w.id ? w : x));
  const deleteWarehouse = (id: string) => setWarehouses(p => p.filter(x => x.id !== id));

  const addLocation = (l: any) => setLocations(p => [...p, l]);
  const updateLocation = (l: any) => setLocations(p => p.map(x => x.id === l.id ? l : x));
  const deleteLocation = (id: string) => setLocations(p => p.filter(x => x.id !== id));

  const addCustomerLevel = (l: any) => setCustomerLevels(p => [...p, l]);
  const updateCustomerLevel = (l: any) => setCustomerLevels(p => p.map(x => x.id === l.id ? l : x));
  const deleteCustomerLevel = (id: string) => setCustomerLevels(p => p.filter(x => x.id !== id));

  const updateTransfer = (t: any) => setTransfers(p => { const idx = p.findIndex(x => x.id === t.id); return idx >= 0 ? p.map(x => x.id === t.id ? t : x) : [t, ...p]; });
  const deleteTransfer = (id: string) => setTransfers(p => p.filter(x => x.id !== id));

  const updateCount = (c: any) => setCounts(p => { const idx = p.findIndex(x => x.id === c.id); return idx >= 0 ? p.map(x => x.id === c.id ? c : x) : [c, ...p]; });
  const deleteCount = (id: string) => setCounts(p => p.filter(x => x.id !== id));

  const updateReservation = (r: any) => setReservations(p => { const idx = p.findIndex(x => x.id === r.id); return idx >= 0 ? p.map(x => x.id === r.id ? r : x) : [r, ...p]; });
  const deleteReservation = (id: string) => setReservations(p => p.filter(x => x.id !== id));

  const updateReceipt = (r: any) => setReceipts(p => { const idx = p.findIndex(x => x.id === r.id); return idx >= 0 ? p.map(x => x.id === r.id ? r : x) : [r, ...p]; });
  const deleteReceipt = (id: string) => setReceipts(p => p.filter(x => x.id !== id));

  const updateAdjustment = (a: any) => setAdjustments(p => { const idx = p.findIndex(x => x.id === a.id); return idx >= 0 ? p.map(x => x.id === a.id ? a : x) : [a, ...p]; });
  const deleteAdjustment = (id: string) => setAdjustments(p => p.filter(x => x.id !== id));

  const handleStockStatusChange = (type: string, id: string, status: any) => {
     if(type === 'transfer') updateTransfer({ ...transfers.find(t=>t.id===id), status });
     if(type === 'count') updateCount({ ...counts.find(c=>c.id===id), status });
     if(type === 'reservation') updateReservation({ ...reservations.find(r=>r.id===id), status });
     if(type === 'receipt') updateReceipt({ ...receipts.find(r=>r.id===id), status });
     if(type === 'adjustment') updateAdjustment({ ...adjustments.find(a=>a.id===id), status });
  };

  const handleSyncOperation = (type: any) => {
     setSyncLogs(prev => [{ id: `log-${Date.now()}`, type, status: 'Success', timestamp: new Date().toISOString(), details: 'Manual Sync', durationMs: 200 }, ...prev]);
  };

  const startShift = (branchId: string, startCash: number, notes?: string) => {
     if(!currentUser) return;
     const newShift = { id: `shift-${Date.now()}`, userId: currentUser.id, branchId, startCash, startTime: new Date().toISOString(), status: 'Open', notes };
     setShifts(prev => [newShift as any, ...prev]);
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
     setShifts(prev => prev.map(s => s.id === shiftId ? { ...s, endCash, endTime: new Date().toISOString(), status: 'Closed', notes: notes || s.notes } : s));
  };

  const addShiftSchedule = (s: any) => setShiftSchedules(p => [...p, s]);
  const deleteShiftSchedule = (id: string) => setShiftSchedules(p => p.filter(x => x.id !== id));

  const addPromotion = (p: any) => setPromotions(prev => [...prev, p]);
  const updatePromotion = (p: any) => setPromotions(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePromotion = (id: string) => setPromotions(prev => prev.filter(item => item.id !== id));

  return (
    <GlobalContext.Provider value={{
      currentUser, setCurrentUser, isLoading,
      users, products, sales, units, categories, branches, posMachines, warehouses, locations,
      transfers, counts, reservations, receipts, adjustments, syncLogs, customers, customerLevels,
      shifts, shiftSchedules, promotions, settings,
      processSale, addProduct, updateProduct, deleteProduct,
      addUnit, updateUnit, deleteUnit, addCategory, updateCategory, deleteCategory,
      addBranch, updateBranch, deleteBranch, addPos, updatePos, deletePos,
      addWarehouse, updateWarehouse, deleteWarehouse, addLocation, updateLocation, deleteLocation,
      addUser, updateUser, deleteUser, addCustomer, updateCustomer, deleteCustomer,
      addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,
      updateTransfer, deleteTransfer, updateCount, deleteCount, updateReservation, deleteReservation,
      updateReceipt, deleteReceipt, updateAdjustment, deleteAdjustment,
      handleStockStatusChange, handleSyncOperation,
      startShift, endShift, addShiftSchedule, deleteShiftSchedule,
      addPromotion, updatePromotion, deletePromotion,
      updateSettings, settleSaleDebt, handleVoidSale, t, formatPrice
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

import React, { useState, useMemo, useEffect } from 'react';
import { Shift, Branch, User, ShiftSchedule, Sale } from '../types';
import { 
  Clock, 
  DollarSign, 
  MapPin, 
  User as UserIcon, 
  Calendar, 
  CheckCircle, 
  AlertCircle, 
  PlayCircle, 
  StopCircle, 
  History,
  CalendarDays,
  Plus,
  Trash2,
  List,
  X,
  Monitor,
  Printer,
  FileText
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

interface ShiftManagementProps {
  shifts: Shift[];
  branches: Branch[];
  users: User[];
  currentUser: User | null;
  onStartShift: (branchId: string, startCash: number, notes?: string) => void;
  onEndShift: (shiftId: string, endCash: number, notes?: string) => void;
}

interface ZReportData {
  shiftId: string;
  user: string;
  branch: string;
  start: string;
  end: string;
  startCash: number;
  endCash: number;
  totalSales: number;
  salesByMethod: Record<string, number>;
  expectedCash: number;
  discrepancy: number;
  transactionCount: number;
}

export const ShiftManagement: React.FC<ShiftManagementProps> = ({
  shifts, branches, users, currentUser, onStartShift, onEndShift
}) => {
  const { shiftSchedules, addShiftSchedule, deleteShiftSchedule, settings, posMachines, sales, formatPrice } = useGlobal();
  const [activeTab, setActiveTab] = useState<'attendance' | 'planning'>('attendance');

  // --- Attendance State ---
  const [startCash, setStartCash] = useState<string>('0');
  const [endCash, setEndCash] = useState<string>('0');
  const [notes, setNotes] = useState('');
  const [selectedBranchId, setSelectedBranchId] = useState<string>(currentUser?.branchId || '');
  const [confirmEnd, setConfirmEnd] = useState(false);

  // Report State
  const [viewingReport, setViewingReport] = useState<ZReportData | null>(null);

  // Auto-detect branch based on User or Device Settings
  useEffect(() => {
    if (currentUser?.branchId) {
      setSelectedBranchId(currentUser.branchId);
    } else if (settings.currentBranchId) {
      setSelectedBranchId(settings.currentBranchId);
    } else if (branches.length > 0) {
      setSelectedBranchId(branches[0].id);
    }
  }, [currentUser, settings, branches]);

  // --- Planning State ---
  const [planningDate, setPlanningDate] = useState(new Date().toISOString().split('T')[0]);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [scheduleForm, setScheduleForm] = useState<Partial<ShiftSchedule>>({
    userId: '',
    branchId: '',
    date: new Date().toISOString().split('T')[0],
    startTime: '09:00',
    endTime: '18:00',
    note: ''
  });

  // Find active shift for current user
  const activeShift = shifts.find(s => s.userId === currentUser?.id && s.status === 'Open');

  // Filter history (My shifts or all if admin/manager)
  const historyShifts = useMemo(() => {
    let filtered = shifts;
    if (currentUser?.role !== 'Admin' && currentUser?.role !== 'Manager') {
      filtered = filtered.filter(s => s.userId === currentUser?.id);
    }
    return filtered.sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime());
  }, [shifts, currentUser]);

  // Filter schedules based on planning date
  const filteredSchedules = useMemo(() => {
    return shiftSchedules.filter(s => s.date === planningDate);
  }, [shiftSchedules, planningDate]);

  // Permissions
  const canPlanShifts = currentUser?.role === 'Admin' || currentUser?.role === 'Manager';

  // --- Report Logic ---
  const generateZReport = (shift: Shift) => {
    const start = new Date(shift.startTime);
    const end = shift.endTime ? new Date(shift.endTime) : new Date();

    // Filter sales during this shift and by this user (approximation)
    const shiftSales = sales.filter(s => {
      const sDate = new Date(s.date);
      // Strict matching: Sale date is within shift window AND sold by same user (if user tracked on sale, for now assuming shift user)
      // In a real DB, sale would have 'shiftId'
      return sDate >= start && sDate <= end && s.status !== 'voided';
    });

    const salesByMethod: Record<string, number> = {};
    let totalSales = 0;

    shiftSales.forEach(s => {
      const method = s.paymentMethod;
      const amount = s.total; // Or amountReceived if strict cash accounting
      salesByMethod[method] = (salesByMethod[method] || 0) + amount;
      totalSales += amount;
    });

    // Cash Logic: Opening + Cash Sales - Cash Returns (ignored for now) = Expected
    const cashSales = salesByMethod['cash'] || 0;
    const expectedCash = shift.startCash + cashSales;
    const actualEndCash = shift.endCash || 0; // 0 if still open/running view
    const discrepancy = actualEndCash - expectedCash;

    const report: ZReportData = {
      shiftId: shift.id,
      user: users.find(u => u.id === shift.userId)?.name || 'Unknown',
      branch: branches.find(b => b.id === shift.branchId)?.name || 'Unknown',
      start: start.toLocaleString(),
      end: shift.status === 'Open' ? 'Running...' : end.toLocaleString(),
      startCash: shift.startCash,
      endCash: actualEndCash,
      totalSales,
      salesByMethod,
      expectedCash,
      discrepancy,
      transactionCount: shiftSales.length
    };

    setViewingReport(report);
  };

  const handlePrintReport = () => {
    window.print();
  };

  // --- Handlers ---

  const handleStart = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBranchId) {
        alert("Please select a branch.");
        return;
    }
    onStartShift(selectedBranchId, parseFloat(startCash) || 0, notes);
    setStartCash('0');
    setNotes('');
  };

  const handleEnd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeShift) return;
    onEndShift(activeShift.id, parseFloat(endCash) || 0, notes);
    setEndCash('0');
    setNotes('');
    setConfirmEnd(false);
  };

  const handleAddSchedule = (e: React.FormEvent) => {
    e.preventDefault();
    if (!scheduleForm.userId || !scheduleForm.branchId || !scheduleForm.date) return;

    addShiftSchedule({
      ...scheduleForm,
      id: `sch-${Date.now()}`
    } as ShiftSchedule);
    setIsScheduleModalOpen(false);
  };

  // Resolve display names
  const currentBranchName = branches.find(b => b.id === selectedBranchId)?.name || 'Unknown Branch';
  const currentPosName = posMachines.find(p => p.id === settings.currentPosId)?.machineNumber || 'Unknown POS';

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center print:hidden">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Shift Management</h2>
          <p className="text-slate-500">Track working hours and manage staff schedules.</p>
        </div>

        {/* Tab Toggle */}
        <div className="flex bg-slate-100 p-1 rounded-lg">
           <button
             onClick={() => setActiveTab('attendance')}
             className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
               activeTab === 'attendance' 
                 ? 'bg-white text-slate-800 shadow-sm' 
                 : 'text-slate-500 hover:text-slate-700'
             }`}
           >
             <Clock className="w-4 h-4 mr-2" />
             Time Clock
           </button>
           {canPlanShifts && (
             <button
               onClick={() => setActiveTab('planning')}
               className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                 activeTab === 'planning' 
                   ? 'bg-white text-slate-800 shadow-sm' 
                   : 'text-slate-500 hover:text-slate-700'
               }`}
             >
               <CalendarDays className="w-4 h-4 mr-2" />
               Roster / Planning
             </button>
           )}
        </div>
      </div>

      {activeTab === 'attendance' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-fade-in print:hidden">
          {/* Active Shift Card */}
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit">
             <div className="p-6 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
                <h3 className="font-bold text-slate-800 flex items-center">
                   <Clock className="w-5 h-5 mr-2 text-slate-500" />
                   Current Status
                </h3>
                {activeShift ? (
                   <span className="px-3 py-1 bg-green-100 text-green-700 rounded-full text-xs font-bold uppercase tracking-wide flex items-center">
                      <span className="w-2 h-2 bg-green-500 rounded-full mr-2 animate-pulse"></span>
                      On Duty
                   </span>
                ) : (
                   <span className="px-3 py-1 bg-slate-200 text-slate-500 rounded-full text-xs font-bold uppercase tracking-wide">
                      Off Duty
                   </span>
                )}
             </div>

             <div className="p-6">
                {activeShift ? (
                   !confirmEnd ? (
                      <div className="space-y-6">
                         <div className="flex items-center justify-between">
                            <div>
                               <p className="text-sm text-slate-500 mb-1">Started At</p>
                               <p className="text-xl font-bold text-slate-800">
                                  {new Date(activeShift.startTime).toLocaleTimeString()}
                               </p>
                               <p className="text-xs text-slate-400">
                                  {new Date(activeShift.startTime).toLocaleDateString()}
                               </p>
                            </div>
                            <div>
                               <p className="text-sm text-slate-500 mb-1">Opening Cash</p>
                               <p className="text-xl font-bold text-green-600">
                                  {formatPrice(activeShift.startCash)}
                               </p>
                            </div>
                         </div>

                         <div className="p-4 bg-blue-50 rounded-lg border border-blue-100 flex items-start">
                            <MapPin className="w-5 h-5 text-blue-500 mr-3 mt-0.5" />
                            <div>
                               <p className="font-medium text-blue-900">
                                  {branches.find(b => b.id === activeShift.branchId)?.name || 'Unknown Branch'}
                               </p>
                               <p className="text-xs text-blue-700">Currently Active Location</p>
                            </div>
                         </div>

                         <div className="flex gap-3">
                            <button 
                               onClick={() => generateZReport(activeShift)}
                               className="flex-1 py-3 bg-white border border-slate-300 text-slate-700 rounded-xl font-bold hover:bg-slate-50 transition-colors shadow-sm flex items-center justify-center"
                            >
                               <FileText className="w-5 h-5 mr-2" />
                               X-Report (Draft)
                            </button>
                            <button 
                                onClick={() => setConfirmEnd(true)}
                                className="flex-1 py-3 bg-red-600 text-white rounded-xl font-bold hover:bg-red-700 transition-colors shadow-lg flex items-center justify-center"
                            >
                                <StopCircle className="w-6 h-6 mr-2" />
                                End Shift
                            </button>
                         </div>
                      </div>
                   ) : (
                      <form onSubmit={handleEnd} className="space-y-4 animate-fade-in">
                         <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 mb-4">
                            <h4 className="font-bold text-slate-700 mb-2">Closing Register</h4>
                            <p className="text-xs text-slate-500">Please count the cash drawer and enter the total amount.</p>
                         </div>

                         <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">Closing Cash Amount</label>
                            <div className="relative">
                               <DollarSign className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
                               <input 
                                  type="number" 
                                  step="0.01" 
                                  min="0"
                                  required
                                  value={endCash}
                                  onChange={(e) => setEndCash(e.target.value)}
                                  className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-red-500 text-lg font-bold"
                               />
                            </div>
                         </div>

                         <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">Shift Notes</label>
                            <textarea 
                               value={notes}
                               onChange={(e) => setNotes(e.target.value)}
                               className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-red-500 h-24 resize-none"
                               placeholder="Any discrepancies or comments..."
                            />
                         </div>

                         <div className="flex space-x-3 pt-2">
                            <button 
                               type="button"
                               onClick={() => setConfirmEnd(false)}
                               className="flex-1 py-3 border border-slate-300 text-slate-600 rounded-lg font-medium hover:bg-slate-50"
                            >
                               Cancel
                            </button>
                            <button 
                               type="submit"
                               className="flex-1 py-3 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700 shadow-md"
                            >
                               Confirm Clock Out
                            </button>
                         </div>
                      </form>
                   )
                ) : (
                   <form onSubmit={handleStart} className="space-y-4">
                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Location / Branch</label>
                         <div className="relative">
                            <MapPin className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
                            <input 
                               type="text" 
                               disabled
                               value={currentBranchName}
                               className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg bg-slate-100 text-slate-500 font-medium cursor-not-allowed"
                            />
                         </div>
                         <div className="mt-2 flex items-center text-xs text-slate-500 bg-slate-50 p-2 rounded border border-slate-200">
                            <Monitor className="w-3.5 h-3.5 mr-2 text-blue-500" />
                            <span>
                               Configured Device: <span className="font-semibold text-slate-700">{currentPosName}</span>
                            </span>
                         </div>
                      </div>

                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Opening Cash Amount</label>
                         <div className="relative">
                            <DollarSign className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
                            <input 
                               type="number" 
                               step="0.01" 
                               min="0"
                               required
                               value={startCash}
                               onChange={(e) => setStartCash(e.target.value)}
                               className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 font-bold"
                            />
                         </div>
                      </div>

                      <div>
                         <label className="block text-sm font-medium text-slate-700 mb-1">Notes (Optional)</label>
                         <textarea 
                            value={notes}
                            onChange={(e) => setNotes(e.target.value)}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 h-20 resize-none"
                            placeholder="e.g. Register 2"
                         />
                      </div>

                      <button 
                         type="submit"
                         className="w-full py-4 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 transition-colors shadow-lg flex items-center justify-center"
                      >
                         <PlayCircle className="w-6 h-6 mr-2" />
                         Start Shift (Clock In)
                      </button>
                   </form>
                )}
             </div>
          </div>

          {/* Recent History */}
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col overflow-hidden h-[500px]">
             <div className="p-4 border-b border-slate-100 bg-slate-50">
                <h3 className="font-bold text-slate-700 flex items-center">
                   <History className="w-5 h-5 mr-2 text-slate-500" />
                   Recent Shift History
                </h3>
             </div>
             <div className="overflow-y-auto flex-1 p-0">
                {historyShifts.length === 0 ? (
                   <div className="p-8 text-center text-slate-400">No shift history found.</div>
                ) : (
                   <table className="w-full text-left">
                      <thead className="bg-slate-50 text-xs text-slate-500 uppercase font-semibold sticky top-0">
                         <tr>
                            <th className="px-4 py-3">Date / User</th>
                            <th className="px-4 py-3">Duration</th>
                            <th className="px-4 py-3 text-right">Cash Out</th>
                            <th className="px-4 py-3 text-center">Action</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {historyShifts.map(shift => {
                            const start = new Date(shift.startTime);
                            const end = shift.endTime ? new Date(shift.endTime) : null;
                            const duration = end ? 
                               Math.round((end.getTime() - start.getTime()) / (1000 * 60 * 60) * 10) / 10 + ' hrs' : 
                               'Running';

                            const user = users.find(u => u.id === shift.userId);
                            const branch = branches.find(b => b.id === shift.branchId);

                            return (
                               <tr key={shift.id} className="hover:bg-slate-50 transition-colors text-sm">
                                  <td className="px-4 py-3">
                                     <div className="font-medium text-slate-800">{start.toLocaleDateString()}</div>
                                     <div className="text-xs text-slate-500">{user?.name || 'Unknown'}</div>
                                     <div className="text-[10px] text-slate-400">{branch?.name}</div>
                                  </td>
                                  <td className="px-4 py-3 text-slate-600">
                                     {start.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} - 
                                     {end ? end.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : '...'}
                                     <div className="text-xs text-slate-400 mt-0.5">{duration}</div>
                                  </td>
                                  <td className="px-4 py-3 text-right font-mono">
                                     {shift.endCash !== undefined ? formatPrice(shift.endCash) : '-'}
                                  </td>
                                  <td className="px-4 py-3 text-center">
                                     <button 
                                        onClick={() => generateZReport(shift)}
                                        className="text-blue-600 hover:text-blue-800 text-xs font-bold underline"
                                     >
                                        Report
                                     </button>
                                  </td>
                               </tr>
                            );
                         })}
                      </tbody>
                   </table>
                )}
             </div>
          </div>
        </div>
      )}

      {/* Viewing Report Modal */}
      {viewingReport && (
         <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-[60] p-4 backdrop-blur-sm">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg max-h-[90vh] flex flex-col overflow-hidden">
               <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 print:hidden">
                  <h3 className="font-bold text-slate-800">Shift Report (Z-Report)</h3>
                  <button onClick={() => setViewingReport(null)} className="text-slate-400 hover:text-slate-600">
                     <X className="w-6 h-6" />
                  </button>
               </div>

               <div className="flex-1 overflow-y-auto p-6 bg-slate-50">
                  <div className="bg-white p-6 shadow-sm border border-slate-200 text-sm font-mono text-slate-700 mx-auto max-w-sm print:shadow-none print:border-none print:w-full print:max-w-none">
                     <div className="text-center mb-4">
                        <h2 className="text-lg font-bold text-slate-900 mb-1">{settings.companyName}</h2>
                        <p>{viewingReport.branch}</p>
                        <p className="text-xs text-slate-500 mt-1">Z-REPORT / END OF SHIFT</p>
                        <p className="mt-2 text-xs">{new Date().toLocaleString()}</p>
                     </div>

                     <div className="border-b border-dashed border-slate-300 my-3"></div>

                     <div className="space-y-1">
                        <div className="flex justify-between"><span>Shift ID:</span><span>{viewingReport.shiftId.slice(-6)}</span></div>
                        <div className="flex justify-between"><span>User:</span><span>{viewingReport.user}</span></div>
                        <div className="flex justify-between"><span>Start:</span><span>{viewingReport.start}</span></div>
                        <div className="flex justify-between"><span>End:</span><span>{viewingReport.end}</span></div>
                     </div>

                     <div className="border-b border-dashed border-slate-300 my-3"></div>

                     <div className="space-y-2">
                        <div className="flex justify-between font-bold">
                           <span>Total Sales</span>
                           <span>{formatPrice(viewingReport.totalSales)}</span>
                        </div>
                        <div className="text-xs text-slate-500 pl-2 space-y-1">
                           {Object.entries(viewingReport.salesByMethod).map(([method, amount]) => (
                              <div key={method} className="flex justify-between">
                                 <span className="capitalize">{method}</span>
                                 <span>{formatPrice(amount)}</span>
                              </div>
                           ))}
                        </div>
                        <div className="flex justify-between text-xs mt-1">
                           <span>Transactions</span>
                           <span>{viewingReport.transactionCount}</span>
                        </div>
                     </div>

                     <div className="border-b border-dashed border-slate-300 my-3"></div>

                     <div className="space-y-2">
                        <div className="flex justify-between">
                           <span>Opening Cash</span>
                           <span>{formatPrice(viewingReport.startCash)}</span>
                        </div>
                        <div className="flex justify-between">
                           <span>Cash Sales</span>
                           <span>{formatPrice(viewingReport.salesByMethod['cash'] || 0)}</span>
                        </div>
                        <div className="flex justify-between font-bold border-t border-slate-100 pt-1 mt-1">
                           <span>Expected Cash</span>
                           <span>{formatPrice(viewingReport.expectedCash)}</span>
                        </div>
                        <div className="flex justify-between font-bold text-slate-900">
                           <span>Actual Count</span>
                           <span>{formatPrice(viewingReport.endCash)}</span>
                        </div>

                        {viewingReport.discrepancy !== 0 && (
                           <div className={`flex justify-between font-bold pt-1 ${viewingReport.discrepancy < 0 ? 'text-red-600' : 'text-green-600'}`}>
                              <span>Variance</span>
                              <span>{formatPrice(viewingReport.discrepancy)}</span>
                           </div>
                        )}
                     </div>

                     <div className="mt-8 pt-4 border-t border-slate-300 text-center text-xs">
                        <p>_______________________</p>
                        <p className="mt-1">Manager Signature</p>
                     </div>
                  </div>
               </div>

               <div className="p-4 border-t border-slate-100 flex justify-end bg-white print:hidden">
                  <button 
                     onClick={handlePrintReport}
                     className="px-6 py-2 bg-slate-900 text-white rounded-lg hover:bg-slate-800 flex items-center font-bold shadow-sm"
                  >
                     <Printer className="w-4 h-4 mr-2" /> Print Report
                  </button>
               </div>
            </div>
         </div>
      )}

      {activeTab === 'planning' && canPlanShifts && (
        <div className="flex flex-col lg:flex-row gap-6 animate-fade-in h-full print:hidden">
           {/* ... Planning UI (Same as previous) ... */}
           {/* Schedule List */}
           <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col overflow-hidden">
              {/* Content identical to previous, omitted for brevity as no logic change needed here */}
              <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                 <h3 className="font-bold text-slate-700 flex items-center">
                    <List className="w-5 h-5 mr-2 text-slate-500" />
                    Shift Roster for {new Date(planningDate).toLocaleDateString()}
                 </h3>
                 <span className="bg-slate-200 text-slate-600 px-2 py-1 rounded text-xs font-bold">
                    {filteredSchedules.length} Shifts
                 </span>
              </div>
              <div className="overflow-y-auto flex-1 p-4 space-y-3">
                 {filteredSchedules.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-48 text-slate-400">
                       <Calendar className="w-12 h-12 mb-3 opacity-30" />
                       <p>No shifts assigned for this date.</p>
                    </div>
                 ) : (
                    filteredSchedules.map(schedule => {
                       const user = users.find(u => u.id === schedule.userId);
                       const branch = branches.find(b => b.id === schedule.branchId);

                       return (
                          <div key={schedule.id} className="flex items-center justify-between p-4 border border-slate-200 rounded-xl hover:border-blue-300 transition-colors bg-white group">
                             <div className="flex items-center space-x-4">
                                <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 font-bold text-sm">
                                   {user?.name.charAt(0) || 'U'}
                                </div>
                                <div>
                                   <h4 className="font-bold text-slate-800">{user?.name || 'Unknown User'}</h4>
                                   <div className="flex items-center text-xs text-slate-500 mt-1">
                                      <span className="flex items-center mr-3">
                                         <MapPin className="w-3 h-3 mr-1" /> {branch?.name}
                                      </span>
                                      <span className="flex items-center">
                                         <Clock className="w-3 h-3 mr-1" /> {schedule.startTime} - {schedule.endTime}
                                      </span>
                                   </div>
                                </div>
                             </div>

                             <button 
                                onClick={() => deleteShiftSchedule(schedule.id)}
                                className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                             >
                                <Trash2 className="w-4 h-4" />
                             </button>
                          </div>
                       );
                    })
                 )}
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  LineChart,
  Line,
  PieChart,
  Pie,
  Cell,
  Legend,
  AreaChart,
  Area
} from 'recharts';
import { Sale, Product } from '../types';
import { TrendingUp, DollarSign, Package, AlertCircle, AlertTriangle, CalendarRange, Wallet, Calendar, Filter } from 'lucide-react';
import { INITIAL_CATEGORIES_TREE } from '../services/data';
import { useGlobal } from '../context/GlobalContext';

interface DashboardProps {
  sales: Sale[];
  products: Product[];
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d', '#ffc658'];

type TimeRange = '7d' | '30d' | '90d' | 'all';

export const Dashboard: React.FC<DashboardProps> = ({ sales, products }) => {
  const { t, formatPrice } = useGlobal();
  const [timeRange, setTimeRange] = useState<TimeRange>('30d');

  // 1. Filter Sales based on Time Range
  const dashboardMetrics = useMemo(() => {
    const today = new Date();
    let startDate = new Date();

    if (timeRange === '7d') startDate.setDate(today.getDate() - 7);
    else if (timeRange === '30d') startDate.setDate(today.getDate() - 30);
    else if (timeRange === '90d') startDate.setDate(today.getDate() - 90);
    else startDate = new Date(0); // Beginning of time

    // Filter sales strictly by date range and non-voided status
    const filteredSales = sales.filter(s => {
       const saleDate = new Date(s.date);
       return saleDate >= startDate && saleDate <= today && s.status !== 'voided';
    });

    const totalRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const totalOrders = filteredSales.length;

    // Average Order Value
    const aov = totalOrders > 0 ? totalRevenue / totalOrders : 0;

    return { filteredSales, totalRevenue, totalOrders, aov, startDate };
  }, [sales, timeRange]);

  // 2. Dynamic Trend Data
  const trendData = useMemo(() => {
    const dailyMap = new Map<string, number>();
    const today = new Date();

    let daysToGenerate = 30;
    if (timeRange === '7d') daysToGenerate = 7;
    else if (timeRange === '90d') daysToGenerate = 90;
    else if (timeRange === 'all') daysToGenerate = 60; 

    for(let i = daysToGenerate - 1; i >= 0; i--) {
        const d = new Date(today);
        d.setDate(d.getDate() - i);
        const key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        dailyMap.set(key, 0);
    }

    dashboardMetrics.filteredSales.forEach(sale => {
      const dateStr = new Date(sale.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      if (dailyMap.has(dateStr)) {
        dailyMap.set(dateStr, (dailyMap.get(dateStr) || 0) + sale.total);
      }
    });

    return Array.from(dailyMap).map(([name, sales]) => ({ name, sales }));
  }, [dashboardMetrics.filteredSales, timeRange]);

  // 3. Category Breakdown
  const categoryData = useMemo(() => {
    const catMap = new Map<string, number>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        let catName = item.category;
        const catObj = INITIAL_CATEGORIES_TREE.find(c => c.id === item.category);
        if (catObj) catName = catObj.name;

        const lineTotal = item.sellPrice * item.quantity;
        catMap.set(catName, (catMap.get(catName) || 0) + lineTotal);
      });
    });

    const result = Array.from(catMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    if (result.length > 5) {
       const top5 = result.slice(0, 5);
       const others = result.slice(5).reduce((sum, item) => sum + item.value, 0);
       return [...top5, { name: 'Others', value: others }];
    }
    return result;
  }, [dashboardMetrics.filteredSales]);

  // 4. Payment Method Breakdown (New)
  const paymentData = useMemo(() => {
    const payMap = new Map<string, number>();
    dashboardMetrics.filteredSales.forEach(s => {
       const method = s.paymentMethod;
       payMap.set(method, (payMap.get(method) || 0) + s.total);
    });
    return Array.from(payMap).map(([name, value]) => ({ name: name.toUpperCase(), value }));
  }, [dashboardMetrics.filteredSales]);

  // 5. Top Selling Products
  const topProducts = useMemo(() => {
    const prodMap = new Map<string, { name: string; revenue: number; qty: number; unit: string }>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        const existing = prodMap.get(item.id) || { name: item.name, revenue: 0, qty: 0, unit: item.unit };
        existing.revenue += (item.sellPrice * item.quantity);
        existing.qty += (item.quantity / (item.sellConversionFactor || 1));
        prodMap.set(item.id, existing);
      });
    });

    return Array.from(prodMap.values())
      .sort((a, b) => b.revenue - a.revenue)
      .slice(0, 5);
  }, [dashboardMetrics.filteredSales]);

  // Low Stock Logic
  const lowStockProducts = products.filter(p => p.stock < (p.minStock || 20)).sort((a, b) => a.stock - b.stock);
  const lowStockCount = lowStockProducts.length;

  // Outstanding Debt
  const totalOutstanding = useMemo(() => {
     return sales
        .filter(s => s.status !== 'voided' && (s.paymentStatus === 'unpaid' || s.paymentStatus === 'partial'))
        .reduce((acc, s) => acc + (s.remainingAmount || s.total), 0);
  }, [sales]);

  const StatCard = ({ title, value, icon: Icon, color, subtext, trend }: any) => (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col justify-between h-full">
      <div className="flex items-start justify-between mb-4">
        <div>
          <p className="text-sm font-medium text-slate-500">{title}</p>
          <h3 className="text-2xl font-bold text-slate-800 mt-1">{value}</h3>
        </div>
        <div className={`p-3 rounded-full ${color}`}>
          <Icon className="w-5 h-5 text-white" />
        </div>
      </div>
      {subtext && (
         <div className="mt-auto pt-2 border-t border-slate-50">
            <p className="text-xs text-slate-400 flex items-center">
               {trend === 'up' && <TrendingUp className="w-3 h-3 mr-1 text-green-500" />}
               {subtext}
            </p>
         </div>
      )}
    </div>
  );

  return (
    <div className="space-y-6 animate-fade-in pb-12">
      {/* Header & Filter */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">{t('dashboard.title')}</h2>
          <p className="text-slate-500 text-sm flex items-center mt-1">
            <CalendarRange className="w-4 h-4 mr-1" />
            Performance Overview
          </p>
        </div>

        <div className="bg-white p-1 rounded-lg border border-slate-200 flex shadow-sm overflow-x-auto">
           {(['7d', '30d', '90d', 'all'] as const).map((range) => (
              <button
                key={range}
                onClick={() => setTimeRange(range)}
                className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all whitespace-nowrap ${
                   timeRange === range 
                   ? 'bg-slate-800 text-white shadow-sm' 
                   : 'text-slate-600 hover:bg-slate-100'
                }`}
              >
                 {range === '7d' ? '7 Days' : range === '30d' ? '30 Days' : range === '90d' ? '3 Months' : 'All Time'}
              </button>
           ))}
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title={t('dashboard.revenue')}
          value={formatPrice(dashboardMetrics.totalRevenue)}
          icon={DollarSign} 
          color="bg-green-500" 
          subtext={`${dashboardMetrics.totalOrders} orders in period`}
          trend="up"
        />
        <StatCard 
          title="Avg. Order Value"
          value={formatPrice(dashboardMetrics.aov)}
          icon={TrendingUp} 
          color="bg-blue-500" 
          subtext="Per transaction average"
        />
        <StatCard 
          title="Outstanding Debt"
          value={formatPrice(totalOutstanding)}
          icon={Wallet} 
          color="bg-orange-500" 
          subtext="Total unpaid (All time)"
        />
        <StatCard 
          title="Low Stock Alerts"
          value={lowStockCount} 
          icon={AlertCircle} 
          color={lowStockCount > 0 ? "bg-red-500" : "bg-slate-400"} 
          subtext={`${products.length} total items`}
        />
      </div>

      {/* Low Stock Alert Section */}
      {lowStockProducts.length > 0 && (
        <div className="bg-red-50 border border-red-200 rounded-xl overflow-hidden shadow-sm">
          <div className="p-4 bg-red-100 border-b border-red-200 flex items-center justify-between">
            <h3 className="text-red-800 font-bold flex items-center text-sm uppercase tracking-wide">
              <AlertTriangle className="w-5 h-5 mr-2" />
              {t('dashboard.critical')} ({lowStockCount})
            </h3>
          </div>
          <div className="p-4 overflow-x-auto">
             <div className="flex space-x-4 pb-2">
               {lowStockProducts.map(p => (
                 <div key={p.id} className="min-w-[200px] bg-white p-3 rounded-lg border border-red-100 shadow-sm flex flex-col group hover:border-red-300 transition-colors cursor-pointer">
                    <div className="flex justify-between items-start mb-2">
                       <span className="font-semibold text-slate-700 truncate w-32 text-sm" title={p.name}>{p.name}</span>
                       <span className="text-[10px] font-mono bg-red-50 text-red-600 px-1.5 py-0.5 rounded border border-red-100">
                          {p.sku}
                       </span>
                    </div>
                    <div className="flex justify-between items-end mt-auto">
                      <div className="flex flex-col">
                        <span className="text-[10px] text-slate-400 uppercase">Current</span>
                        <span className="text-xl font-bold text-red-600">{p.stock}</span>
                      </div>
                      <div className="flex flex-col items-end">
                         <span className="text-[10px] text-slate-400 mb-0.5">Min: {p.minStock || 20}</span>
                         <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500 uppercase font-bold">
                           {p.unit}
                         </span>
                      </div>
                    </div>
                 </div>
               ))}
             </div>
          </div>
        </div>
      )}

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Sales Trend */}
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center justify-between mb-6">
             <h3 className="text-lg font-bold text-slate-800">{t('dashboard.trend')}</h3>
             <div className="flex items-center text-xs text-slate-500">
                <span className="w-3 h-3 bg-primary-500 rounded-full mr-2"></span> Revenue
             </div>
          </div>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#0ea5e9" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                <XAxis 
                   dataKey="name" 
                   stroke="#94a3b8" 
                   fontSize={11} 
                   tickMargin={10} 
                   tickLine={false}
                   axisLine={false}
                />
                <YAxis 
                   stroke="#94a3b8" 
                   fontSize={11} 
                   tickFormatter={(val) => formatPrice(val).replace(/[^0-9.]/g, '')} 
                   tickLine={false}
                   axisLine={false}
                />
                <Tooltip 
                  formatter={(value: number) => [formatPrice(value), 'Revenue']}
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                  cursor={{ stroke: '#cbd5e1', strokeWidth: 1, strokeDasharray: '4 4' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="sales" 
                  stroke="#0ea5e9" 
                  strokeWidth={3} 
                  fillOpacity={1} 
                  fill="url(#colorSales)" 
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Category Pie & Payment Method */}
        <div className="flex flex-col gap-6">
           <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col flex-1">
             <h3 className="text-lg font-bold text-slate-800 mb-2">{t('dashboard.byCategory')}</h3>
             <div className="flex-1 min-h-[200px]">
                <ResponsiveContainer width="100%" height="100%">
                 <PieChart>
                   <Pie
                     data={categoryData}
                     cx="50%"
                     cy="50%"
                     innerRadius={40}
                     outerRadius={60}
                     fill="#8884d8"
                     paddingAngle={5}
                     dataKey="value"
                   >
                     {categoryData.map((entry, index) => (
                       <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                     ))}
                   </Pie>
                   <Tooltip 
                      formatter={(value: number) => formatPrice(value)}
                      contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', fontSize: '12px' }}
                   />
                 </PieChart>
               </ResponsiveContainer>
             </div>
           </div>

           <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col flex-1">
             <h3 className="text-lg font-bold text-slate-800 mb-2">Payment Methods</h3>
             <div className="flex-1 min-h-[150px]">
                <ResponsiveContainer width="100%" height="100%">
                   <BarChart data={paymentData} layout="vertical">
                      <XAxis type="number" hide />
                      <YAxis dataKey="name" type="category" width={60} fontSize={10} tickLine={false} axisLine={false} />
                      <Tooltip formatter={(value: number) => formatPrice(value)} />
                      <Bar dataKey="value" fill="#82ca9d" barSize={20} radius={[0, 4, 4, 0]} />
                   </BarChart>
                </ResponsiveContainer>
             </div>
           </div>
        </div>
      </div>

      {/* Top Products Table */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
         <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">{t('dashboard.topProducts')}</h3>
            <button className="text-sm text-primary-600 font-medium hover:underline">View Sales Report</button>
         </div>
         <div className="overflow-x-auto">
           <table className="w-full text-left">
             <thead className="bg-slate-50 border-b border-slate-100">
               <tr>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider pl-6">{t('inventory.productName')}</th>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">{t('dashboard.soldQty')}</th>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider text-right pr-6">{t('dashboard.revenue')}</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {topProducts.length === 0 ? (
                  <tr>
                     <td colSpan={3} className="text-center py-8 text-slate-400 text-sm">No sales data for this period.</td>
                  </tr>
               ) : (
                  topProducts.map((p, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-4 py-3 pl-6">
                         <div className="flex items-center">
                            <span className="w-6 h-6 rounded-full bg-slate-100 text-slate-500 flex items-center justify-center text-xs font-bold mr-3 group-hover:bg-primary-100 group-hover:text-primary-600 transition-colors">
                               {idx + 1}
                            </span>
                            <span className="font-medium text-slate-700">{p.name}</span>
                         </div>
                      </td>
                      <td className="px-4 py-3 text-right text-slate-600 font-mono text-sm">
                         {Math.round(p.qty)} <span className="text-[10px] text-slate-400 ml-1">{p.unit}</span>
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-slate-800 pr-6">
                         {formatPrice(p.revenue)}
                      </td>
                    </tr>
                  ))
               )}
             </tbody>
           </table>
         </div>
      </div>
    </div>
  );
};

export enum Category {
  CEMENT = 'Cement & Concrete',
  STEEL = 'Steel & Metal',
  WOOD = 'Wood & Lumber',
  PAINT = 'Paints & Finishes',
  TOOLS = 'Tools & Hardware',
  PLUMBING = 'Plumbing',
  ELECTRICAL = 'Electrical',
  CONSUMABLES = 'General Consumables'
}

export type UnitCategory = 'Weight' | 'Length' | 'Quantity';

export interface UnitDefinition {
  id: string;
  name: string;      // e.g. Kilogram
  symbol: string;    // e.g. kg
  category: UnitCategory;
  baseFactor: number; // 1 for base unit (e.g. g), 1000 for kg
  isBase: boolean;   // True if this is the reference unit
}

export interface CategoryItem {
  id: string;
  name: string;
  parentId: string | null; // null for root categories
  description?: string;
}

export interface ProductVariant {
  id: string;
  name: string;      // e.g., 'Piece', 'Small', 'Red' (Unit Name or Variant Name)
  code: string;      // SKU/Code for the variant
  barcode: string;   // Barcode for the variant
  conversionFactor: number; // How many variants in the main unit
  price: number;     // Price per variant
  color?: string;    // New: Color specification (e.g., 'Red', '#FF0000')
  size?: string;     // New: Size specification (e.g., 'XL', '10mm')
}

export interface ProductInventory {
  warehouseId: string;
  quantity: number;
}

export interface BranchPrice {
  branchId: string;
  price: number;
}

export interface ProductPhysical {
  weight?: number; // kg
  width?: number;  // cm
  height?: number; // cm
  depth?: number;  // cm (length)
}

export interface Product {
  id: string;
  name: string;
  category: Category | string; 
  price: number;     // Base Price (Global)
  branchPrices?: BranchPrice[]; // Overrides per branch
  stock: number;     // Stock count in MAIN units (Aggregate Total)
  minStock?: number; // Minimum stock threshold for alerts
  warehouseInventory?: ProductInventory[]; // Breakdown by warehouse
  unit: string;      // Name of the MAIN unit (e.g., 'bag', 'box')
  physical?: ProductPhysical; // New: Physical attributes
  imageUrl?: string;
  sku: string;       // SKU of MAIN unit
  barcode: string;   // Barcode of MAIN unit
