  INITIAL_TRANSFERS, INITIAL_COUNTS, INITIAL_RESERVATIONS, INITIAL_RECEIPTS, 
  INITIAL_ADJUSTMENTS, INITIAL_SALES, INITIAL_SYNC_LOGS, INITIAL_SHIFT_SCHEDULES 
} from '../services/data';
import { translations } from '../services/translations';

