                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Selling Price</label>
                                          <div className="relative">
                                            <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 text-xs">$</span>
