                  <div className="flex gap-4 flex-1">
                    <div className="flex-1 grid grid-cols-3 gap-3">
                      {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'BS'].map((num) => (<button key={num} onClick={() => handleNumPadClick(num.toString())} className="bg-white border border-slate-200 rounded-lg text-xl font-semibold text-slate-700 hover:bg-slate-50 active:bg-slate-100 transition-colors shadow-sm flex items-center justify-center">{num === 'BS' ? <ArrowLeft className="w-6 h-6" /> : num}</button>))}
                    </div>
                    <div className="w-1/3 flex flex-col gap-3">
                      <button onClick={() => handleQuickCash(Math.ceil(finalTotal))} className="flex-1 bg-blue-50 text-blue-700 font-bold rounded-lg hover:bg-blue-100 border border-blue-100 transition-colors">Exact</button>
                      <button onClick={() => handleQuickCash(10)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$10</button>
                      <button onClick={() => handleQuickCash(20)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$20</button>
                      <button onClick={() => handleQuickCash(50)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$50</button>
                      <button onClick={() => handleQuickCash(100)} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">$100</button>
                    </div>
                  </div>
                </div>
              ) : paymentMethod === 'qr' ? (
                <div className="flex-1 flex flex-col items-center justify-center text-center"><div className="bg-white p-4 rounded-xl border-2 border-slate-200 shadow-sm mb-4"><img src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=Payment_OnePay_${finalTotal}`} alt="Payment QR" className="w-48 h-48 object-contain" /></div><p className="font-bold text-slate-800 text-lg">Scan to Pay ${finalTotal.toFixed(2)}</p><p className="text-slate-500 text-sm mt-2">Use OnePay or compatible banking app</p></div>
              ) : paymentMethod === 'credit' ? (
                 <div className="flex-1 flex flex-col">
                    <div className="bg-orange-50 p-4 rounded-xl mb-4 border border-orange-100 flex justify-between items-center"><div><p className="text-xs text-orange-700 font-bold uppercase mb-1">Customer</p><p className="font-bold text-slate-800">{selectedCustomer?.name}</p></div><User className="w-5 h-5 text-orange-400" /></div>
                    <div className="bg-white p-4 rounded-xl mb-4 text-right border border-slate-200"><p className="text-sm text-slate-500 mb-1">Initial Deposit / Pay Now</p><div className="text-4xl font-bold text-slate-800 tracking-tight">${receivedAmountStr || '0'}</div></div>
                    <div className="flex justify-between items-center mb-6 px-2"><div><p className="text-sm text-slate-500">Total Bill</p><p className="text-lg font-bold text-slate-800">${finalTotal.toFixed(2)}</p></div><div className="text-right"><p className="text-sm text-slate-500">Remaining Debt</p><p className="text-xl font-bold text-red-600">${remainingDebt.toFixed(2)}</p></div></div>
                    <div className="flex gap-4 flex-1">
                       <div className="flex-1 grid grid-cols-3 gap-3">
                          {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'BS'].map((num) => (<button key={num} onClick={() => handleNumPadClick(num.toString())} className="bg-white border border-slate-200 rounded-lg text-xl font-semibold text-slate-700 hover:bg-slate-50 active:bg-slate-100 transition-colors shadow-sm flex items-center justify-center">{num === 'BS' ? <ArrowLeft className="w-6 h-6" /> : num}</button>))}
                       </div>
                       <div className="w-1/3 flex flex-col gap-3">
                          <button onClick={() => setReceivedAmountStr('0')} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">No Deposit</button>
                          <button onClick={() => handleQuickCash(Math.ceil(finalTotal * 0.1))} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">10%</button>
                          <button onClick={() => handleQuickCash(Math.ceil(finalTotal * 0.5))} className="flex-1 bg-white text-slate-600 font-bold rounded-lg border border-slate-200 hover:bg-slate-50">50%</button>
                       </div>
                    </div>
                 </div>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4"><div className="w-24 h-24 bg-blue-50 rounded-full flex items-center justify-center text-blue-500 mb-2"><CreditCard className="w-12 h-12" /></div><h4 className="text-xl font-bold text-slate-800">Ready for Card Payment</h4><p className="text-slate-500 max-w-xs">Please insert or swipe card on the terminal. Ensure the amount <strong className="text-slate-800">${finalTotal.toFixed(2)}</strong> is correct.</p></div>
              )}

              <button onClick={handleProcessPayment} disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < finalTotal) || (paymentMethod === 'credit' && receivedAmount > finalTotal)} className={`w-full py-4 mt-6 text-white rounded-xl font-bold text-xl disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg flex items-center justify-center ${paymentMethod === 'credit' ? 'bg-orange-600 hover:bg-orange-700' : 'bg-slate-900 hover:bg-slate-800'}`}>
                {isProcessing ? <span className="flex items-center"><Sparkles className="w-5 h-5 animate-spin mr-2" /> Processing...</span> : <><CheckCircle className="w-6 h-6 mr-2" /> {paymentMethod === 'cash' && change > 0 ? `Confirm & Return $${change.toFixed(2)}` : paymentMethod === 'credit' ? `Confirm Debt $${remainingDebt.toFixed(2)}` : `Confirm Payment $${finalTotal.toFixed(2)}`}</>}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Receipt Modal - OPTIMIZED FOR PRINT */}
      {isReceiptOpen && lastSale && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm flex flex-col overflow-hidden">
            <div className="p-4 bg-slate-800 text-white flex justify-between items-center print:hidden">
              <h3 className="font-bold flex items-center"><CheckCircle className="w-5 h-5 mr-2 text-green-400" /> Sale Completed</h3>
              <button onClick={() => setIsReceiptOpen(false)} className="text-slate-400 hover:text-white"><X className="w-5 h-5" /></button>
            </div>

            {/* 
                PRINTABLE AREA:
                We use an ID for strict CSS targeting in media queries. 
                We also apply specific width classes dynamically.
            */}
            <div className="p-6 bg-slate-50 flex-1 overflow-y-auto max-h-[60vh] print:p-0 print:max-h-none print:overflow-visible">
              <div 
                id="printable-receipt" 
                className={`bg-white p-4 shadow-sm border border-slate-200 text-xs font-mono text-black mx-auto ${receiptWidthClass}`}
              >
                <div className="text-center mb-4">
                  {settings?.receiptLogoUrl && (
                     <img src={settings.receiptLogoUrl} alt="Logo" className="h-12 w-auto mx-auto mb-2 object-contain" />
                  )}
                  <h2 className="text-lg font-bold mb-1">{settings?.companyName || 'BuildMaster Store'}</h2>
                  <p>{settings?.address}</p>
                  <p>{settings?.phone}</p>
                  {settings?.receiptShowTaxId && settings.taxId && <p>Tax ID: {settings.taxId}</p>}
                  <p className="mt-2">#{lastSale.id}</p>
                  <p>{new Date(lastSale.date).toLocaleString()}</p>
                </div>

                <div className="border-b border-dashed border-black my-2"></div>

                <div className="space-y-1 mb-2">
                  {lastSale.items.map((item, i) => (
                    <div key={i} className="flex justify-between">
                      <span className="truncate w-32">{item.name}</span>
                      <span className="text-right">
                        {item.quantity} x {item.sellPrice.toFixed(2)}
                      </span>
                      <span className="font-bold text-right w-16">
                        {(item.quantity * item.sellPrice).toFixed(2)}
                      </span>
                    </div>
                  ))}
                </div>

                <div className="border-b border-dashed border-black my-2"></div>

                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span>Subtotal</span>
                    <span>${(lastSale.subtotal || lastSale.total).toFixed(2)}</span>
                  </div>
                  {lastSale.discountAmount ? (
                    <div className="flex justify-between">
                      <span>Discount</span>
                      <span>-${lastSale.discountAmount.toFixed(2)}</span>
                    </div>
                  ) : null}

                  {settings?.tax.enabled && settings.tax.displayOnReceipt && (
                     <div className="flex justify-between">
                        <span>Tax ({settings.tax.rate}%)</span>
                        {/* Simplified calc for display if needed, realistically backend provides tax amount */}
                        <span>${(lastSale.total - (lastSale.subtotal || lastSale.total) + (lastSale.discountAmount || 0)).toFixed(2)}</span>
                     </div>
                  )}

                  <div className="flex justify-between font-bold text-sm mt-1 pt-1 border-t border-black">
                    <span>Total</span>
                    <span>${lastSale.total.toFixed(2)}</span>
                  </div>
                </div>

                <div className="border-b border-dashed border-black my-3"></div>

                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span className="capitalize">Paid via {lastSale.paymentMethod}</span>
                    <span>${(lastSale.amountReceived && lastSale.amountReceived > 0 ? lastSale.amountReceived : 0).toFixed(2)}</span>
                  </div>

                  {(lastSale.paymentStatus === 'unpaid' || lastSale.paymentStatus === 'partial') && (
                     <div className="flex justify-between font-bold">
                        <span>Balance Due</span>
                        <span>${(lastSale.remainingAmount || 0).toFixed(2)}</span>
                     </div>
                  )}

                  {lastSale.change !== undefined && lastSale.change > 0 && (
                    <div className="flex justify-between font-bold">
                      <span>Change</span>
                      <span>${lastSale.change.toFixed(2)}</span>
                    </div>
                  )}

                  {lastSale.pointsEarned ? (
                     <div className="mt-2 text-center font-bold border-t border-dashed border-black pt-2">
                        + {lastSale.pointsEarned} Points Earned!
                     </div>
                  ) : null}
                </div>

                <div className="mt-6 text-center italic">
                  <p className="mb-1">{settings?.receiptHeader}</p>
                  <p>{settings?.receiptFooter}</p>
                  {settings?.receiptShowCashier && <p className="text-[9px] mt-2">Cashier: Staff Name</p>}
                </div>

                {settings?.receiptQrCodeUrl && (
                   <div className="mt-4 flex flex-col items-center">
                      <img src={settings.receiptQrCodeUrl} alt="QR" className="w-24 h-24 object-contain" />
                      <span className="text-[10px] font-bold mt-1">Scan to Pay</span>
                   </div>
                )}
              </div>
            </div>

            <div className="p-4 bg-white border-t border-slate-100 flex gap-3 print:hidden">
              <button 
                onClick={() => window.print()}
                className="flex-1 py-3 bg-white border border-slate-300 text-slate-700 rounded-lg font-bold hover:bg-slate-50 flex items-center justify-center transition-colors"
              >
                <Printer className="w-5 h-5 mr-2" /> Print
              </button>
              <button 
                onClick={() => setIsReceiptOpen(false)}
                className="flex-1 py-3 bg-slate-900 text-white rounded-lg font-bold hover:bg-slate-800 flex items-center justify-center transition-colors"
              >
                <Plus className="w-5 h-5 mr-2" /> New Order
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export enum Category {
  CEMENT = 'Cement & Concrete',
  STEEL = 'Steel & Metal',
  WOOD = 'Wood & Lumber',
  PAINT = 'Paints & Finishes',
  TOOLS = 'Tools & Hardware',
  PLUMBING = 'Plumbing',
  ELECTRICAL = 'Electrical',
  CONSUMABLES = 'General Consumables'
}

export type UnitCategory = 'Weight' | 'Length' | 'Quantity';

export interface UnitDefinition {
  id: string;
  name: string;      // e.g. Kilogram
  symbol: string;    // e.g. kg
  category: UnitCategory;
  baseFactor: number; // 1 for base unit (e.g. g), 1000 for kg
  isBase: boolean;   // True if this is the reference unit
}

export interface CategoryItem {
  id: string;
  name: string;
  parentId: string | null; // null for root categories
  description?: string;
}

export interface ProductVariant {
  id: string;
  name: string;      // e.g., 'Piece', 'Small', 'Red' (Unit Name or Variant Name)
  code: string;      // SKU/Code for the variant
  barcode: string;   // Barcode for the variant
  conversionFactor: number; // How many variants in the main unit
  price: number;     // Price per variant
  costPrice?: number; // Cost price per variant
  color?: string;    // New: Color specification (e.g., 'Red', '#FF0000')
  size?: string;     // New: Size specification (e.g., 'XL', '10mm')
}

export interface ProductInventory {
  warehouseId: string;
  quantity: number;
}

export interface BranchPrice {
  branchId: string;
  price: number;
}

export interface ProductPhysical {
  weight?: number; // kg
  width?: number;  // cm
  height?: number; // cm
  depth?: number;  // cm (length)
}

export interface Product {
  id: string;
  name: string;
  category: Category | string; 
  price: number;     // Base Sell Price (Global)
  costPrice?: number; // Base Cost Price (For Profit Calc)
  branchPrices?: BranchPrice[]; // Overrides per branch
  stock: number;     // Stock count in MAIN units (Aggregate Total)
  minStock?: number; // Minimum stock threshold for alerts
  warehouseInventory?: ProductInventory[]; // Breakdown by warehouse
  unit: string;      // Name of the MAIN unit (e.g., 'bag', 'box')
  physical?: ProductPhysical; // New: Physical attributes
  imageUrl?: string;
  sku: string;       // SKU of MAIN unit
  barcode: string;   // Barcode of MAIN unit
  variants?: ProductVariant[]; // List of sub-products/variants
}

export interface CartItem extends Product {
  quantity: number;
  // Handling multi-unit/variant logic
  selectedVariantId?: string; // null if main unit, string if variant
  sellPrice: number; 
  sellUnit: string;  
  sellConversionFactor: number; // 1 for main, X for variant
}

export interface Sale {
  id: string;
  items: CartItem[];
  subtotal?: number; // Raw total before discount/tax
  discountAmount?: number; // Deduction amount
  total: number; // Final payable amount
  date: string;
  paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit';
  paymentStatus: 'paid' | 'unpaid' | 'partial'; // Track debt status
  amountReceived?: number; // Amount given by customer
  change?: number; // Change returned
  remainingAmount?: number; // Amount left to pay (for credit/partial)
  status: 'completed' | 'voided'; // Order status
  syncStatus?: 'synced' | 'pending' | 'failed'; // Track sync state
  customerId?: string; // Link to customer
  customerName?: string; // Snapshot of name
  pointsRedeemed?: number; // Points used
  pointsEarned?: number; // Points gained
}

export interface EstimateRequest {
  query: string;
}

export interface EstimateResultItem {
  productName: string;
  estimatedQuantity: number;
  unit: string;
  reasoning: string;
  matchedProductId?: string; // If found in inventory
}

// --- AI Inventory Analysis Types ---
export interface ReorderSuggestion {
  productId: string;
  productName: string;
  currentStock: number;
  suggestedReorderQty: number;
  priority: 'High' | 'Medium' | 'Low';
  reasoning: string;
}

export interface NewProductSuggestion {
  name: string;
  categoryName: string;
  estimatedPrice: number;
  reasoning: string;
  suggestedUnit: string;
}

export interface BundleSuggestion {
  bundleName: string;
  components: string[];
  estimatedPrice: number;
  reasoning: string;
  targetAudience: string;
}

export interface InventoryAnalysisResult {
  reorders: ReorderSuggestion[];
  newProducts: NewProductSuggestion[];
  bundles: BundleSuggestion[];
}

export interface Branch {
  id: string;
  name: string;
  address: string;
  phone: string;
  manager: string;
  isActive: boolean;
}

export interface PosMachine {
  id: string;
  branchId: string;
  machineNumber: string; // e.g., POS-01
  status: 'active' | 'maintenance' | 'inactive';
  lastActive?: string;
}

export interface Warehouse {
  id: string;
  branchId: string;
  name: string;
  code: string; // e.g., WH-01
  type: 'General' | 'Cold Storage' | 'Hazardous' | 'Showroom';
  description?: string;
}

export interface StorageLocation {
  id: string;
  warehouseId: string;
  zone: string;   // e.g., Zone A
  rack: string;   // e.g., Rack 01
  shelf: string;  // e.g., Shelf 03 (Level)
  bin: string;    // e.g., Bin B (Slot)
  fullCode: string; // Helper: A-01-03-B
  type?: 'Pallet' | 'Shelf' | 'Floor';
}

// --- Customer Types ---
export interface CustomerLevel {
  id: string;
  name: string;
  discountPercentage: number;
  color?: string;
}

export interface Customer {
  id: string;
  code: string; // Membership ID or Code
  name: string;
  phone: string;
  taxId?: string;
  address?: string;
  email?: string;
  loyaltyPoints: number;
  notes?: string;
  levelId?: string;
  level?: CustomerLevel;
}

// --- Stock Management Types ---

export type DocumentStatus = 'Draft' | 'Approved' | 'Completed' | 'Cancelled';

export interface StockItem {
  productId: string;
  variantId?: string; // Optional: if specific variant
  productName: string;
  unit: string;
  quantity: number;
  note?: string;
}

// 1. Transfer Request
export interface StockTransfer {
  id: string;
  date: string;
  sourceWarehouseId: string;
  targetWarehouseId: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 2. Stock Count
export interface StockCountItem extends StockItem {
  systemQuantity: number; // Snapshot of system stock
  countedQuantity: number; // Actual count
  diff: number; // Calculated diff
}

export interface StockCount {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockCountItem[];
  referenceNo: string;
  counterName: string; // Who counted
  reason: string; // Mandatory reason for adjustment
}

// 3. Stock Reservation
export interface StockReservation {
  id: string;
  date: string;
  expiryDate: string;
  warehouseId: string;
  customerName: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 4. Goods Receipt
export interface StockReceiptItem extends StockItem {
  costPrice: number; // Cost per unit
}

export interface StockReceipt {
  id: string;
  date: string;
  warehouseId: string;
  vendorName: string;
  vendorInvoiceNo?: string;
  status: DocumentStatus;
  items: StockReceiptItem[];
  referenceNo: string;
  totalCost: number;
}

// 5. Stock Adjustment
export interface StockAdjustment {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockItem[]; // Quantity can be negative (decrease) or positive (increase)
  referenceNo: string;
  reason: string; // Mandatory
}

// --- Sync Types ---
export interface SyncLog {
  id: string;
  timestamp: string;
  type: 'Auto' | 'Manual' | 'Push' | 'Pull';
  status: 'Success' | 'Failed' | 'Partial';
  details: string; // e.g., "5 Sales uploaded, 0 Products updated"
  durationMs: number;
}

// --- User & Roles ---

export type UserRole = 'Admin' | 'Manager' | 'Staff' | 'Cashier';

export interface User {
  id: string;
  username: string;
  password?: string; // Added for login
  email?: string;    // Optional
  name: string;
  role: UserRole;
  avatarUrl?: string;
  department?: string;
  branchId?: string;
}

// --- Shift Management ---
export interface Shift {
  id: string;
  userId: string;
  branchId: string;
  startTime: string;
  endTime?: string;
  startCash: number;
  endCash?: number;
  notes?: string;
  status: 'Open' | 'Closed';
  userName?: string; // Optional helper
  branchName?: string; // Optional helper
}

export interface ShiftSchedule {
  id: string;
  userId: string;
  branchId: string;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:mm (24hr)
  endTime: string; // HH:mm (24hr)
  note?: string;
}

// --- Settings & Promotions ---
export type Language = 'en' | 'th' | 'lo';

export interface Promotion {
  id: string;
  title: string;
  imageUrl: string;
  isActive: boolean;
  order?: number;
  startDate?: string; // ISO Date
  endDate?: string;   // ISO Date
}

export interface LocalDatabaseConfig {
  enabled: boolean;
  type: 'postgresql' | 'sqlite' | 'mysql';
  host: string;
  port: string;
  databaseName: string;
  username: string;
  password: string;
}

export interface TaxSettings {
  enabled: boolean;             
  rate: number;                 
  calculationMode: 'included' | 'excluded'; 
  displayOnReceipt: boolean;    
}

export interface CustomerDisplaySettings {
  enabled: boolean;
  welcomeMessage: string;
  promotionInterval: number; // Seconds
}

export interface SystemSettings {
  // Company Info
  companyName: string;
  taxId: string;
  address: string;
  phone: string;

  // Localization
  language: Language;
  currencySymbol: string;

  // Interface
  defaultItemsPerPage: number;

  // Tax / VAT
  tax: TaxSettings;

  // Customer Display
  customerDisplay: CustomerDisplaySettings;

  // Loyalty Settings
  loyaltyProgram: {
    enabled: boolean;
    earnRate: number; // Amount to spend to earn 1 point (e.g. $10 = 1 point)
    redeemRate: number; // Points needed for 1 currency unit discount (e.g. 100 points = $1)
  };

  // Receipt & Print
  receiptHeader: string;
  receiptFooter: string;
  receiptLogoUrl?: string;
  receiptQrCodeUrl?: string; // Bank QR Code for receipt
  receiptPaperSize: '58mm' | '80mm' | 'A4';
  receiptAutoPrint: boolean;
  receiptShowTaxId: boolean;
  receiptShowCashier: boolean;
  receiptCopies: number;

  // Device Configuration
  currentBranchId?: string;
  currentPosId?: string;
  deviceRole?: 'Master' | 'Slave';

  // Local Database (For Slave offline mode)
  localDatabase?: LocalDatabaseConfig;

  // Synchronization (Master/Slave)
  masterApiUrl?: string; // e.g., http://192.168.1.100:3000
  autoSyncInterval?: number; // In minutes, 0 for manual
  lastSyncTime?: string;
}

// --- Notifications & Audit ---
export interface AppNotification {
  id: string;
  title: string;
  message: string;
  type: 'info' | 'warning' | 'error' | 'success';
  timestamp: string;
  read: boolean;
  link?: string; // Optional link to navigate to (e.g. '/approvals')
}

export type AuditAction = 
  | 'SALE_VOID' 
  | 'USER_CREATE' 
  | 'USER_DELETE' 
  | 'SETTINGS_UPDATE' 
  | 'STOCK_APPROVE' 
  | 'STOCK_REJECT'
  | 'SHIFT_OVERRIDE'
  | 'LOGIN_FAILED';

export interface AuditLog {
  id: string;
  action: AuditAction;
  userId: string;
  userName: string;
  details: string;
  timestamp: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  resourceId?: string;
}

