  const [shiftSchedules, setShiftSchedules] = useState<ShiftSchedule[]>(INITIAL_SHIFT_SCHEDULES);
  const [promotions, setPromotions] = useState<Promotion[]>(INITIAL_PROMOTIONS);
  const [settings, setSettingsState] = useState<SystemSettings>(INITIAL_SETTINGS);

  // Notifications & Audit
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>(INITIAL_AUDIT_LOGS);

  // --- Real Data Loading ---
  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        // Parallel fetching
        const [
          fetchedProducts, fetchedSales, fetchedCustomers, fetchedSettings, 
          fetchedBranches, fetchedUsers, fetchedCategories, fetchedUnits, fetchedWarehouses
        ] = await Promise.all([
          apiRequest('/api/products'),
          apiRequest('/api/sales'),
          apiRequest('/api/customers'),
          apiRequest('/api/settings'),
          apiRequest('/api/branches'),
          apiRequest('/api/users'),
          apiRequest('/api/categories'),
          apiRequest('/api/units'),
          apiRequest('/api/warehouses')
        ]);

        if (fetchedProducts && Array.isArray(fetchedProducts)) setProducts(fetchedProducts);
        if (fetchedSales && Array.isArray(fetchedSales)) setSales(fetchedSales);
        if (fetchedCustomers && Array.isArray(fetchedCustomers)) setCustomers(fetchedCustomers);
        if (fetchedSettings && !fetchedSettings.error) setSettingsState(fetchedSettings);
        if (fetchedBranches && Array.isArray(fetchedBranches)) setBranches(fetchedBranches);
        if (fetchedUsers && Array.isArray(fetchedUsers)) setUsers(fetchedUsers);
        if (fetchedCategories && Array.isArray(fetchedCategories)) setCategories(fetchedCategories);
        if (fetchedUnits && Array.isArray(fetchedUnits)) setUnits(fetchedUnits);
        if (fetchedWarehouses && Array.isArray(fetchedWarehouses)) setWarehouses(fetchedWarehouses);

        fetchStockDocs();

      } catch (error) {
        // Silent catch for demo mode
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  const fetchStockDocs = async () => {
    try {
      const [tr, ct, rs, rc, aj] = await Promise.all([
        apiRequest('/api/stock/transfer'),
        apiRequest('/api/stock/count'),
        apiRequest('/api/stock/reservation'),
        apiRequest('/api/stock/receipt'),
        apiRequest('/api/stock/adjustment'),
      ]);
      if (tr) setTransfers(tr);
      if (ct) setCounts(ct);
      if (rs) setReservations(rs);
      if (rc) setReceipts(rc);
      if (aj) setAdjustments(aj);
    } catch (e) {}
  };

  // --- Automated Notifications Logic ---
  useEffect(() => {
    if (!products.length) return;

    // 1. Check Low Stock
    const lowStockItems = products.filter(p => p.stock <= (p.minStock || 20));
    if (lowStockItems.length > 0) {
       // Debounce check: Only add if not recently added (simplified logic here)
       // For this demo, we'll check if a 'low-stock' notification exists that is unread
       const hasUnread = notifications.some(n => n.type === 'warning' && n.title === 'Low Stock Alert' && !n.read);
       if (!hasUnread) {
          addNotification({
             title: 'Low Stock Alert',
             message: `${lowStockItems.length} items are below minimum stock level.`,
             type: 'warning',
             link: '/inventory'
          });
       }
    }
  }, [products]); // Re-run when products change

  useEffect(() => {
     // 2. Check Pending Approvals
     const pendingCount = [
        ...transfers, ...counts, ...receipts, ...adjustments, ...reservations
     ].filter(d => d.status === 'Draft').length;

     if (pendingCount > 0) {
        const hasUnread = notifications.some(n => n.type === 'info' && n.title === 'Pending Approvals' && !n.read);
        if (!hasUnread) {
           addNotification({
              title: 'Pending Approvals',
              message: `You have ${pendingCount} documents waiting for review.`,
              type: 'info',
              link: '/approvals'
           });
        }
     }
  }, [transfers, counts, receipts, adjustments, reservations]);


  const t = (key: string): string => {
    const keys = key.split('.');
    let current: any = translations[settings.language] || translations['en'];
    for (const k of keys) {
      if (current[k] === undefined) return key;
      current = current[k];
    }
    return typeof current === 'string' ? current : key;
  };

  const formatPrice = (amount: number): string => {
    const symbol = settings.currencySymbol || '$';
    return `${symbol}${amount.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const addNotification = (n: Omit<AppNotification, 'id' | 'timestamp' | 'read'>) => {
     const newNotif: AppNotification = {
        ...n,
        id: `notif-${Date.now()}-${Math.random()}`,
        timestamp: new Date().toISOString(),
        read: false
     };
     setNotifications(prev => [newNotif, ...prev]);
  };

  const markNotificationRead = (id: string) => {
     setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));
  };

  const clearAllNotifications = () => {
     setNotifications([]);
  };

  // --- Audit Logging ---
  const logAction = (action: AuditAction, details: string, severity: 'low' | 'medium' | 'high' | 'critical' = 'low', resourceId?: string) => {
    if (!currentUser) return;

    const newLog: AuditLog = {
      id: `aud-${Date.now()}`,
      action,
      userId: currentUser.id,
      userName: currentUser.name,
      details,
      timestamp: new Date().toISOString(),
      severity,
      resourceId
    };

    setAuditLogs(prev => [newLog, ...prev]);
  };

  // --- RESTORE DATA ---
  const restoreSystemData = (data: any) => {
    if (data.users) setUsers(data.users);
    if (data.products) setProducts(data.products);
    if (data.sales) setSales(data.sales);
    if (data.units) setUnits(data.units);
    if (data.categories) setCategories(data.categories);
    if (data.branches) setBranches(data.branches);
    if (data.posMachines) setPosMachines(data.posMachines);
    if (data.warehouses) setWarehouses(data.warehouses);
    if (data.locations) setLocations(data.locations);
    if (data.transfers) setTransfers(data.transfers);
    if (data.counts) setCounts(data.counts);
    if (data.reservations) setReservations(data.reservations);
    if (data.receipts) setReceipts(data.receipts);
    if (data.adjustments) setAdjustments(data.adjustments);
    if (data.customers) setCustomers(data.customers);
    if (data.customerLevels) setCustomerLevels(data.customerLevels);
    if (data.shifts) setShifts(data.shifts);
    if (data.shiftSchedules) setShiftSchedules(data.shiftSchedules);
    if (data.promotions) setPromotions(data.promotions);
    if (data.settings) setSettingsState(data.settings);

    logAction('SETTINGS_UPDATE', 'System data restored from backup', 'high');
  };

  // --- ACTIONS ---

  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number, 
    paymentMethod: any = 'cash',
    amountReceived?: number,
    change?: number,
    pointsRedeemed: number = 0
  ): Promise<Sale> => {

    // Calculate Earned Points
    let pointsEarned = 0;
    if (settings.loyaltyProgram?.enabled && customerId) {
       const earnRate = settings.loyaltyProgram.earnRate || 10;
       pointsEarned = Math.floor(total / earnRate);
    }

    const payload = {
      items: items.map(i => ({
        productId: i.id,
        variantId: i.selectedVariantId,
        quantity: i.quantity,
        sellPrice: i.sellPrice
      })),
      total,
      subtotal,
      discountAmount,
      paymentMethod,
      amountReceived,
      change,
      customerId,
      pointsRedeemed,
      pointsEarned
    };

    const newSale = await apiRequest('/api/sales', 'POST', payload);

    if (newSale && !newSale.error) {
      setSales(prev => [newSale, ...prev]);

      // Update Inventory
      setProducts(prevProducts => prevProducts.map(product => {
        const cartItem = items.find(item => item.id === product.id);
        if (cartItem) {
          return { ...product, stock: product.stock - cartItem.quantity };
        }
        return product;
      }));

      // Update Customer Points
      if (customerId) {
         setCustomers(prev => prev.map(c => {
            if (c.id === customerId) {
               return { 
                  ...c, 
                  loyaltyPoints: Math.max(0, (c.loyaltyPoints || 0) - pointsRedeemed + pointsEarned) 
               };
            }
            return c;
         }));
      }

      return newSale;
    } else {
      // Fallback
      const fallbackSale: Sale = {
        id: `S-${Date.now()}`,
        items, total, subtotal, discountAmount,
        date: new Date().toISOString(),
        paymentMethod, amountReceived, change, customerId,
        customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined,
        status: 'completed',
        paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
        remainingAmount: paymentMethod === 'credit' ? Math.max(0, total - (amountReceived || 0)) : 0,
        syncStatus: 'pending',
        pointsRedeemed,
        pointsEarned
      };

      setSales(prev => [fallbackSale, ...prev]);

      // Fallback Customer Point Update
      if (customerId) {
         setCustomers(prev => prev.map(c => {
            if (c.id === customerId) {
               return { 
                  ...c, 
                  loyaltyPoints: Math.max(0, (c.loyaltyPoints || 0) - pointsRedeemed + pointsEarned) 
               };
            }
            return c;
         }));
      }

      return fallbackSale;
    }
  };

  const handleVoidSale = async (saleId: string) => {
     const res = await apiRequest(`/api/sales/${saleId}`, 'PUT', { status: 'voided' });
     if (res && !res.error) {
       setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: 'voided' } : s));
       const updatedProducts = await apiRequest('/api/products');
       if (updatedProducts) setProducts(updatedProducts);
       logAction('SALE_VOID', `Voided sale ${saleId} and restored stock`, 'high', saleId);
     } else {
        setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: 'voided' } : s));
        logAction('SALE_VOID', `Voided sale ${saleId} (Offline/Fallback)`, 'high', saleId);
     }
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
     setSales(prev => prev.map(s => {
        if (s.id === saleId) {
           return {
              ...s,
              paymentStatus: 'paid',
              remainingAmount: 0,
              amountReceived: (s.amountReceived || 0) + amount
           };
        }
        return s;
     }));
  };

  // --- CRUD (Simplified wrapper) ---
  const addProduct = async (p: Product) => {
    const res = await apiRequest('/api/products', 'POST', p);
    setProducts(prev => [...prev, res || p]);
  };
  const updateProduct = async (p: Product) => {
    const res = await apiRequest(`/api/products/${p.id}`, 'PUT', p);
    setProducts(prev => prev.map(item => item.id === p.id ? (res || p) : item));
  };
  const deleteProduct = async (id: string) => {
    await apiRequest(`/api/products/${id}`, 'DELETE');
    setProducts(prev => prev.filter(item => item.id !== id));
  };

  const addCustomer = async (c: Customer) => {
    const res = await apiRequest('/api/customers', 'POST', c);
    setCustomers(prev => [...prev, res || c]);
  };
  const updateCustomer = async (c: Customer) => {
    const res = await apiRequest(`/api/customers/${c.id}`, 'PUT', c);
    setCustomers(prev => prev.map(item => item.id === c.id ? (res || c) : item));
  };
  const deleteCustomer = async (id: string) => {
    await apiRequest(`/api/customers/${id}`, 'DELETE');
    setCustomers(prev => prev.filter(item => item.id !== id));
  };

  const addUser = async (u: User) => {
    const res = await apiRequest('/api/users', 'POST', u);
    setUsers(prev => [...prev, res || u]);
    logAction('USER_CREATE', `Created user ${u.name} (${u.role})`, 'medium', res?.id || u.id);
  };
  const updateUser = async (u: User) => {
    const res = await apiRequest(`/api/users/${u.id}`, 'PUT', u);
    setUsers(prev => prev.map(item => item.id === u.id ? (res || u) : item));
  };
  const deleteUser = async (id: string) => {
    await apiRequest(`/api/users/${id}`, 'DELETE');
    setUsers(prev => prev.filter(item => item.id !== id));
    logAction('USER_DELETE', `Deleted user ID ${id}`, 'high', id);
  };

  const updateSettings = async (s: SystemSettings) => {
    setSettingsState(s);
    await apiRequest('/api/settings', 'POST', s);
    logAction('SETTINGS_UPDATE', 'Updated system settings', 'medium');
  };

  // ... (Other CRUD wrappers follow similar pattern, using local state as fallback)

  const addUnit = (u: any) => setUnits(p => [...p, u]);
  const updateUnit = (u: any) => setUnits(p => p.map(x => x.id === u.id ? u : x));
  const deleteUnit = (id: string) => setUnits(p => p.filter(x => x.id !== id));

  const addCategory = (c: any) => setCategories(p => [...p, c]);
  const updateCategory = (c: any) => setCategories(p => p.map(x => x.id === c.id ? c : x));
  const deleteCategory = (id: string) => setCategories(p => p.filter(x => x.id !== id));

  const addBranch = (b: any) => setBranches(p => [...p, b]);
  const updateBranch = (b: any) => setBranches(p => p.map(x => x.id === b.id ? b : x));
  const deleteBranch = (id: string) => setBranches(p => p.filter(x => x.id !== id));

  const addPos = (p: any) => setPosMachines(prev => [...prev, p]);
  const updatePos = (p: any) => setPosMachines(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePos = (id: string) => setPosMachines(prev => prev.filter(item => item.id !== id));

  const addWarehouse = (w: any) => setWarehouses(p => [...p, w]);
  const updateWarehouse = (w: any) => setWarehouses(p => p.map(x => x.id === w.id ? w : x));
  const deleteWarehouse = (id: string) => setWarehouses(p => p.filter(x => x.id !== id));

  const addLocation = (l: any) => setLocations(p => [...p, l]);
  const updateLocation = (l: any) => setLocations(p => p.map(x => x.id === l.id ? l : x));
  const deleteLocation = (id: string) => setLocations(p => p.filter(x => x.id !== id));

  const addCustomerLevel = (l: any) => setCustomerLevels(p => [...p, l]);
  const updateCustomerLevel = (l: any) => setCustomerLevels(p => p.map(x => x.id === l.id ? l : x));
  const deleteCustomerLevel = (id: string) => setCustomerLevels(p => p.filter(x => x.id !== id));

  const updateTransfer = (t: any) => setTransfers(p => { const idx = p.findIndex(x => x.id === t.id); return idx >= 0 ? p.map(x => x.id === t.id ? t : x) : [t, ...p]; });
  const deleteTransfer = (id: string) => setTransfers(p => p.filter(x => x.id !== id));

  const updateCount = (c: any) => setCounts(p => { const idx = p.findIndex(x => x.id === c.id); return idx >= 0 ? p.map(x => x.id === c.id ? c : x) : [c, ...p]; });
  const deleteCount = (id: string) => setCounts(p => p.filter(x => x.id !== id));

  const updateReservation = (r: any) => setReservations(p => { const idx = p.findIndex(x => x.id === r.id); return idx >= 0 ? p.map(x => x.id === r.id ? r : x) : [r, ...p]; });
  const deleteReservation = (id: string) => setReservations(p => p.filter(x => x.id !== id));

  const updateReceipt = (r: any) => setReceipts(p => { const idx = p.findIndex(x => x.id === r.id); return idx >= 0 ? p.map(x => x.id === r.id ? r : x) : [r, ...p]; });
  const deleteReceipt = (id: string) => setReceipts(p => p.filter(x => x.id !== id));

  const updateAdjustment = (a: any) => setAdjustments(p => { const idx = p.findIndex(x => x.id === a.id); return idx >= 0 ? p.map(x => x.id === a.id ? a : x) : [a, ...p]; });
  const deleteAdjustment = (id: string) => setAdjustments(p => p.filter(x => x.id !== id));

  const handleStockStatusChange = (type: string, id: string, status: any) => {
     if(type === 'transfer') updateTransfer({ ...transfers.find(t=>t.id===id), status });
     if(type === 'count') updateCount({ ...counts.find(c=>c.id===id), status });
     if(type === 'reservation') updateReservation({ ...reservations.find(r=>r.id===id), status });
     if(type === 'receipt') updateReceipt({ ...receipts.find(r=>r.id===id), status });
     if(type === 'adjustment') updateAdjustment({ ...adjustments.find(a=>a.id===id), status });

     if (status === 'Approved' || status === 'Completed') {
        logAction('STOCK_APPROVE', `${type.toUpperCase()} ${id} status changed to ${status}`, 'low', id);
     } else if (status === 'Cancelled') {
        logAction('STOCK_REJECT', `${type.toUpperCase()} ${id} was rejected`, 'medium', id);
     }
  };

  const handleSyncOperation = (type: any) => {
     setSyncLogs(prev => [{ id: `log-${Date.now()}`, type, status: 'Success', timestamp: new Date().toISOString(), details: 'Manual Sync', durationMs: 200 }, ...prev]);
  };

  const startShift = (branchId: string, startCash: number, notes?: string) => {
     if(!currentUser) return;
     const newShift = { id: `shift-${Date.now()}`, userId: currentUser.id, branchId, startCash, startTime: new Date().toISOString(), status: 'Open', notes };
     setShifts(prev => [newShift as any, ...prev]);
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
     setShifts(prev => prev.map(s => s.id === shiftId ? { ...s, endCash, endTime: new Date().toISOString(), status: 'Closed', notes: notes || s.notes } : s));
  };

  const addShiftSchedule = (s: any) => setShiftSchedules(p => [...p, s]);
  const deleteShiftSchedule = (id: string) => setShiftSchedules(p => p.filter(x => x.id !== id));

  const addPromotion = (p: any) => setPromotions(prev => [...prev, p]);
  const updatePromotion = (p: any) => setPromotions(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePromotion = (id: string) => setPromotions(prev => prev.filter(item => item.id !== id));

  return (
    <GlobalContext.Provider value={{
      currentUser, setCurrentUser, isLoading,
      users, products, sales, units, categories, branches, posMachines, warehouses, locations,
      transfers, counts, reservations, receipts, adjustments, syncLogs, customers, customerLevels,
      shifts, shiftSchedules, promotions, settings, notifications, auditLogs,
      processSale, addProduct, updateProduct, deleteProduct,
      addUnit, updateUnit, deleteUnit, addCategory, updateCategory, deleteCategory,
      addBranch, updateBranch, deleteBranch, addPos, updatePos, deletePos,
      addWarehouse, updateWarehouse, deleteWarehouse, addLocation, updateLocation, deleteLocation,
      addUser, updateUser, deleteUser, addCustomer, updateCustomer, deleteCustomer,
      addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,
      updateTransfer, deleteTransfer, updateCount, deleteCount, updateReservation, deleteReservation,
      updateReceipt, deleteReceipt, updateAdjustment, deleteAdjustment,
      handleStockStatusChange, handleSyncOperation,
      startShift, endShift, addShiftSchedule, deleteShiftSchedule,
      addPromotion, updatePromotion, deletePromotion,
      updateSettings, settleSaleDebt, handleVoidSale, t, formatPrice,
      addNotification, markNotificationRead, clearAllNotifications,
      restoreSystemData, logAction
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { Inventory } from './components/Inventory';
import { PosTerminal } from './components/PosTerminal';
import { UnitManagement } from './components/UnitManagement';
import { CategoryManagement } from './components/CategoryManagement';
import { BranchManagement } from './components/BranchManagement';
import { WarehouseManagement } from './components/WarehouseManagement';
import { StockManagement } from './components/StockManagement';
import { ApprovalManagement } from './components/ApprovalManagement';
import { UserManagement } from './components/UserManagement';
import { Settings } from './components/Settings';
import { SyncManagement } from './components/SyncManagement';
import { CustomerManagement } from './components/CustomerManagement';
import { ShiftManagement } from './components/ShiftManagement';
import { PromotionsManagement } from './components/PromotionsManagement';
import { ReportsManagement } from './components/ReportsManagement';
import LoginPage from './app/page';
import { useGlobal } from './context/GlobalContext';
import { UserRole } from './types';
import { LayoutDashboard, ShoppingCart, Package, ClipboardList, Contact, FileCheck, Tv, RefreshCw, FolderTree, Scale, Store, Container, Users, Settings as SettingsIcon, BarChart4, Clock } from 'lucide-react';

// Define Permissions Map (Duplicated logic from Sidebar for safety)
// In a real app, this should be a single source of truth configuration
const PERMISSIONS: Record<string, UserRole[]> = {
  'dashboard': ['Admin', 'Manager'],
  'reports': ['Admin', 'Manager'],
  'pos': ['Admin', 'Manager', 'Staff', 'Cashier'],
  'shifts': ['Admin', 'Manager', 'Staff', 'Cashier'],
  'inventory': ['Admin', 'Manager', 'Staff'],
  'stock': ['Admin', 'Manager', 'Staff'],
  'customers': ['Admin', 'Manager', 'Cashier', 'Staff'],
  'approvals': ['Admin', 'Manager'],
  'promotions': ['Admin', 'Manager', 'Staff'],
  'sync': ['Admin', 'Manager'],
  'categories': ['Admin', 'Staff', 'Manager'],
  'units': ['Admin', 'Staff', 'Manager'],
  'branches': ['Admin', 'Manager'],
  'warehouses': ['Admin', 'Staff', 'Manager'],
  'users': ['Admin', 'Manager'],
  'settings': ['Admin']
};

function App() {
  const {
    currentUser, setCurrentUser,
    users,
    products, sales, units, categories, branches, posMachines, warehouses, locations,
    transfers, counts, reservations, receipts, adjustments, syncLogs, customers, shifts, shiftSchedules, promotions,
    processSale, addProduct, updateProduct, deleteProduct,
    addUnit, updateUnit, deleteUnit, addCategory, updateCategory, deleteCategory,
    addBranch, updateBranch, deleteBranch, addPos, updatePos, deletePos,
    addWarehouse, updateWarehouse, deleteWarehouse, addLocation, updateLocation, deleteLocation,
    addUser, updateUser, deleteUser, addCustomer, updateCustomer, deleteCustomer,
    updateTransfer, deleteTransfer, updateCount, deleteCount, updateReservation, deleteReservation,
    updateReceipt, deleteReceipt, updateAdjustment, deleteAdjustment,
    handleStockStatusChange, handleSyncOperation,
    startShift, endShift,
    addPromotion, updatePromotion, deletePromotion,
    settings, updateSettings,
    t, handleVoidSale, settleSaleDebt
  } = useGlobal();

  const [activeTab, setActiveTab] = useState('dashboard');

  // Effect to redirect/set active tab based on role upon login
  useEffect(() => {
    if (currentUser) {
      // If current tab is not allowed, redirect to default safe tab
      if (PERMISSIONS[activeTab] && !PERMISSIONS[activeTab].includes(currentUser.role)) {
         if (currentUser.role === 'Cashier') setActiveTab('pos');
         else if (currentUser.role === 'Staff') setActiveTab('inventory');
         else setActiveTab('dashboard');
      }
    }
  }, [currentUser]); // activeTab dependency removed to prevent loop, only check on user change

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveTab('dashboard');
  };

  // Safe Navigation Handler
  const handleTabChange = (tabId: string) => {
    if (currentUser && PERMISSIONS[tabId]?.includes(currentUser.role)) {
      setActiveTab(tabId);
    } else {
      alert("Access Denied: You do not have permission to view this module.");
    }
  };

  // --- Render Login via app/page ---
  if (!currentUser) {
    return <LoginPage />;
  }

  // --- Main Render ---
  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={handleTabChange}
      currentUser={currentUser}
      onLogout={handleLogout}
    >
      {activeTab === 'dashboard' && <Dashboard sales={sales} products={products} />}

      {activeTab === 'reports' && (
        <ReportsManagement 
          sales={sales}
          products={products}
        />
      )}

      {activeTab === 'pos' && (
        <PosTerminal 
          products={products} 
          onProcessSale={processSale} 
          settings={settings}
        />
      )}

      {activeTab === 'shifts' && (
        <ShiftManagement 
          shifts={shifts}
          branches={branches}
          users={users}
          currentUser={currentUser}
          onStartShift={startShift}
          onEndShift={endShift}
        />
      )}

      {activeTab === 'inventory' && (
        <Inventory 
          products={products} 
          units={units} 
          categories={categories}
          warehouses={warehouses}
          sales={sales}
          onAddProduct={addProduct}
          onUpdateProduct={updateProduct}
          onDeleteProduct={deleteProduct}
        />
      )}

      {activeTab === 'stock' && (
        <StockManagement 
          warehouses={warehouses}
          products={products}
          transfers={transfers}
          counts={counts}
          reservations={reservations}
          receipts={receipts}
          adjustments={adjustments}
          defaultItemsPerPage={settings.defaultItemsPerPage}
          onUpdateTransfer={updateTransfer}
          onUpdateCount={updateCount}
          onUpdateReservation={updateReservation}
          onUpdateReceipt={updateReceipt}
          onUpdateAdjustment={updateAdjustment}
          onDeleteTransfer={deleteTransfer}
          onDeleteCount={deleteCount}
          onDeleteReservation={deleteReservation}
          onDeleteReceipt={deleteReceipt}
          onDeleteAdjustment={deleteAdjustment}
          onStatusChange={handleStockStatusChange}
        />
      )}

      {activeTab === 'approvals' && (
        <ApprovalManagement 
          transfers={transfers}
          counts={counts}
          reservations={reservations}
          receipts={receipts}
          adjustments={adjustments}
          warehouses={warehouses}
          onStatusChange={handleStockStatusChange}
        />
      )}

      {activeTab === 'promotions' && (
        <PromotionsManagement 
          promotions={promotions}
          onAddPromotion={addPromotion}
          onUpdatePromotion={updatePromotion}
          onDeletePromotion={deletePromotion}
        />
      )}

      {activeTab === 'customers' && (
        <CustomerManagement
          customers={customers}
          onAddCustomer={addCustomer}
          onUpdateCustomer={updateCustomer}
          onDeleteCustomer={deleteCustomer}
        />
      )}

      {activeTab === 'sync' && (
        <SyncManagement 
          settings={settings}
          logs={syncLogs}
          sales={sales}
          onSync={handleSyncOperation}
        />
      )}

      {activeTab === 'units' && (
        <UnitManagement 
          units={units} 
          onAddUnit={addUnit}
          onUpdateUnit={updateUnit} 
          onDeleteUnit={deleteUnit} 
        />
      )}

      {activeTab === 'categories' && (
        <CategoryManagement 
          categories={categories}
          onAddCategory={addCategory}
          onUpdateCategory={updateCategory}
          onDeleteCategory={deleteCategory}
        />
      )}

      {activeTab === 'branches' && (
        <BranchManagement
          branches={branches}
          posMachines={posMachines}
          onAddBranch={addBranch}
          onUpdateBranch={updateBranch}
          onDeleteBranch={deleteBranch}
          onAddPosMachine={addPos}
          onUpdatePosMachine={updatePos}
          onDeletePosMachine={deletePos}
        />
      )}

      {activeTab === 'warehouses' && (
        <WarehouseManagement
           branches={branches}
           warehouses={warehouses}
           locations={locations}
           onAddWarehouse={addWarehouse}
           onUpdateWarehouse={updateWarehouse}
           onDeleteWarehouse={deleteWarehouse}
           onAddLocation={addLocation}
           onUpdateLocation={updateLocation}
           onDeleteLocation={deleteLocation}
        />
      )}

      {activeTab === 'users' && (
        <UserManagement
          users={users}
          onAddUser={addUser}
          onUpdateUser={updateUser}
          onDeleteUser={deleteUser}
        />
      )}

      {activeTab === 'settings' && (
        <Settings 
          settings={settings} 
          onUpdateSettings={updateSettings} 
          branches={branches}
          posMachines={posMachines}
        />
      )}
    </Layout>
  );
}

export default App;

import React, { useMemo, useState } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  AreaChart,
  Area
} from 'recharts';
import { Sale, Product } from '../types';
import { TrendingUp, DollarSign, Package, AlertCircle, AlertTriangle, CalendarRange, Wallet, Calendar, Activity, ShieldAlert, User, Settings } from 'lucide-react';
import { INITIAL_CATEGORIES_TREE } from '../services/data';
import { useGlobal } from '../context/GlobalContext';

interface DashboardProps {
  sales: Sale[];
  products: Product[];
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d', '#ffc658'];

type TimeRange = '7d' | '30d' | '90d' | 'all';

export const Dashboard: React.FC<DashboardProps> = ({ sales, products }) => {
  const { t, formatPrice, auditLogs } = useGlobal();
  const [timeRange, setTimeRange] = useState<TimeRange>('30d');

  // 1. Filter Sales based on Time Range
  const dashboardMetrics = useMemo(() => {
    const today = new Date();
    let startDate = new Date();

    if (timeRange === '7d') startDate.setDate(today.getDate() - 7);
    else if (timeRange === '30d') startDate.setDate(today.getDate() - 30);
    else if (timeRange === '90d') startDate.setDate(today.getDate() - 90);
    else startDate = new Date(0); // Beginning of time

    // Filter sales strictly by date range and non-voided status
    const filteredSales = sales.filter(s => {
       const saleDate = new Date(s.date);
       return saleDate >= startDate && saleDate <= today && s.status !== 'voided';
    });

    const totalRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const totalOrders = filteredSales.length;

    // Average Order Value
    const aov = totalOrders > 0 ? totalRevenue / totalOrders : 0;

    return { filteredSales, totalRevenue, totalOrders, aov, startDate };
  }, [sales, timeRange]);

  // 2. Dynamic Trend Data
  const trendData = useMemo(() => {
    const dailyMap = new Map<string, number>();
    const today = new Date();

    let daysToGenerate = 30;
    if (timeRange === '7d') daysToGenerate = 7;
    else if (timeRange === '90d') daysToGenerate = 90;
    else if (timeRange === 'all') daysToGenerate = 60; 

    for(let i = daysToGenerate - 1; i >= 0; i--) {
        const d = new Date(today);
        d.setDate(d.getDate() - i);
        const key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        dailyMap.set(key, 0);
    }

    dashboardMetrics.filteredSales.forEach(sale => {
      const dateStr = new Date(sale.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      if (dailyMap.has(dateStr)) {
        dailyMap.set(dateStr, (dailyMap.get(dateStr) || 0) + sale.total);
      }
    });

    return Array.from(dailyMap).map(([name, sales]) => ({ name, sales }));
  }, [dashboardMetrics.filteredSales, timeRange]);

  // 3. Category Breakdown
  const categoryData = useMemo(() => {
    const catMap = new Map<string, number>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        let catName = item.category;
        const catObj = INITIAL_CATEGORIES_TREE.find(c => c.id === item.category);
        if (catObj) catName = catObj.name;

        const lineTotal = item.sellPrice * item.quantity;
        catMap.set(catName, (catMap.get(catName) || 0) + lineTotal);
      });
    });

    const result = Array.from(catMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    if (result.length > 5) {
       const top5 = result.slice(0, 5);
       const others = result.slice(5).reduce((sum, item) => sum + item.value, 0);
       return [...top5, { name: 'Others', value: others }];
    }
    return result;
  }, [dashboardMetrics.filteredSales]);

  // 4. Top Selling Products
  const topProducts = useMemo(() => {
    const prodMap = new Map<string, { name: string; revenue: number; qty: number; unit: string }>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        const existing = prodMap.get(item.id) || { name: item.name, revenue: 0, qty: 0, unit: item.unit };
        existing.revenue += (item.sellPrice * item.quantity);
        existing.qty += (item.quantity / (item.sellConversionFactor || 1));
        prodMap.set(item.id, existing);
      });
    });

    return Array.from(prodMap.values())
      .sort((a, b) => b.revenue - a.revenue)
      .slice(0, 5);
  }, [dashboardMetrics.filteredSales]);

  // Low Stock Logic
  const lowStockProducts = products.filter(p => p.stock < (p.minStock || 20)).sort((a, b) => a.stock - b.stock);
  const lowStockCount = lowStockProducts.length;

  // Outstanding Debt
  const totalOutstanding = useMemo(() => {
     return sales
        .filter(s => s.status !== 'voided' && (s.paymentStatus === 'unpaid' || s.paymentStatus === 'partial'))
        .reduce((acc, s) => acc + (s.remainingAmount || s.total), 0);
  }, [sales]);

  // Recent Logs (Latest 5)
  const recentLogs = useMemo(() => {
     return [...auditLogs].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).slice(0, 5);
  }, [auditLogs]);

  const StatCard = ({ title, value, icon: Icon, color, subtext, trend }: any) => (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col justify-between h-full">
      <div className="flex items-start justify-between mb-4">
        <div>
          <p className="text-sm font-medium text-slate-500">{title}</p>
          <h3 className="text-2xl font-bold text-slate-800 mt-1">{value}</h3>
        </div>
        <div className={`p-3 rounded-full ${color}`}>
          <Icon className="w-5 h-5 text-white" />
        </div>
      </div>
      {subtext && (
         <div className="mt-auto pt-2 border-t border-slate-50">
            <p className="text-xs text-slate-400 flex items-center">
               {trend === 'up' && <TrendingUp className="w-3 h-3 mr-1 text-green-500" />}
               {subtext}
            </p>
         </div>
      )}
    </div>
  );

  return (
    <div className="space-y-6 animate-fade-in pb-12">
      {/* Header & Filter */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">{t('dashboard.title')}</h2>
          <p className="text-slate-500 text-sm flex items-center mt-1">
            <CalendarRange className="w-4 h-4 mr-1" />
            Performance Overview
          </p>
        </div>

        <div className="bg-white p-1 rounded-lg border border-slate-200 flex shadow-sm overflow-x-auto">
           {(['7d', '30d', '90d', 'all'] as const).map((range) => (
              <button
                key={range}
                onClick={() => setTimeRange(range)}
                className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all whitespace-nowrap ${
                   timeRange === range 
                   ? 'bg-slate-800 text-white shadow-sm' 
                   : 'text-slate-600 hover:bg-slate-100'
                }`}
              >
                 {range === '7d' ? '7 Days' : range === '30d' ? '30 Days' : range === '90d' ? '3 Months' : 'All Time'}
              </button>
           ))}
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title={t('dashboard.revenue')}
          value={formatPrice(dashboardMetrics.totalRevenue)}
          icon={DollarSign} 
          color="bg-green-500" 
          subtext={`${dashboardMetrics.totalOrders} orders in period`}
          trend="up"
        />
        <StatCard 
          title="Avg. Order Value"
          value={formatPrice(dashboardMetrics.aov)}
          icon={TrendingUp} 
          color="bg-blue-500" 
          subtext="Per transaction average"
        />
        <StatCard 
          title="Outstanding Debt"
          value={formatPrice(totalOutstanding)}
          icon={Wallet} 
          color="bg-orange-500" 
          subtext="Total unpaid (All time)"
        />
        <StatCard 
          title="Low Stock Alerts"
          value={lowStockCount} 
          icon={AlertCircle} 
          color={lowStockCount > 0 ? "bg-red-500" : "bg-slate-400"} 
          subtext={`${products.length} total items`}
        />
      </div>

      {/* Low Stock Alert Section */}
      {lowStockProducts.length > 0 && (
        <div className="bg-red-50 border border-red-200 rounded-xl overflow-hidden shadow-sm">
          <div className="p-4 bg-red-100 border-b border-red-200 flex items-center justify-between">
            <h3 className="text-red-800 font-bold flex items-center text-sm uppercase tracking-wide">
              <AlertTriangle className="w-5 h-5 mr-2" />
              {t('dashboard.critical')} ({lowStockCount})
            </h3>
          </div>
          <div className="p-4 overflow-x-auto">
             <div className="flex space-x-4 pb-2">
               {lowStockProducts.map(p => (
                 <div key={p.id} className="min-w-[200px] bg-white p-3 rounded-lg border border-red-100 shadow-sm flex flex-col group hover:border-red-300 transition-colors cursor-pointer">
                    <div className="flex justify-between items-start mb-2">
                       <span className="font-semibold text-slate-700 truncate w-32 text-sm" title={p.name}>{p.name}</span>
                       <span className="text-[10px] font-mono bg-red-50 text-red-600 px-1.5 py-0.5 rounded border border-red-100">
                          {p.sku}
                       </span>
                    </div>
                    <div className="flex justify-between items-end mt-auto">
                      <div className="flex flex-col">
                        <span className="text-[10px] text-slate-400 uppercase">Current</span>
                        <span className="text-xl font-bold text-red-600">{p.stock}</span>
                      </div>
                      <div className="flex flex-col items-end">
                         <span className="text-[10px] text-slate-400 mb-0.5">Min: {p.minStock || 20}</span>
                         <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500 uppercase font-bold">
                           {p.unit}
                         </span>
                      </div>
                    </div>
                 </div>
               ))}
             </div>
          </div>
        </div>
      )}

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Sales Trend */}
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center justify-between mb-6">
             <h3 className="text-lg font-bold text-slate-800">{t('dashboard.trend')}</h3>
             <div className="flex items-center text-xs text-slate-500">
                <span className="w-3 h-3 bg-primary-500 rounded-full mr-2"></span> Revenue
             </div>
          </div>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#0ea5e9" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                <XAxis 
                   dataKey="name" 
                   stroke="#94a3b8" 
                   fontSize={11} 
                   tickMargin={10} 
                   tickLine={false}
                   axisLine={false}
                />
                <YAxis 
                   stroke="#94a3b8" 
                   fontSize={11} 
                   tickFormatter={(val) => formatPrice(val).replace(/[^0-9.]/g, '')} 
                   tickLine={false}
                   axisLine={false}
                />
                <Tooltip 
                  formatter={(value: number) => [formatPrice(value), 'Revenue']}
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                  cursor={{ stroke: '#cbd5e1', strokeWidth: 1, strokeDasharray: '4 4' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="sales" 
                  stroke="#0ea5e9" 
                  strokeWidth={3} 
                  fillOpacity={1} 
                  fill="url(#colorSales)" 
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Category Pie & Activity Feed */}
        <div className="flex flex-col gap-6">
           <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col flex-1">
             <h3 className="text-lg font-bold text-slate-800 mb-2">{t('dashboard.byCategory')}</h3>
             <div className="flex-1 min-h-[200px]">
                <ResponsiveContainer width="100%" height="100%">
                 <PieChart>
                   <Pie
                     data={categoryData}
                     cx="50%"
                     cy="50%"
                     innerRadius={40}
                     outerRadius={60}
                     fill="#8884d8"
                     paddingAngle={5}
                     dataKey="value"
                   >
                     {categoryData.map((entry, index) => (
                       <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                     ))}
                   </Pie>
                   <Tooltip 
                      formatter={(value: number) => formatPrice(value)}
                      contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', fontSize: '12px' }}
                   />
                 </PieChart>
               </ResponsiveContainer>
             </div>
           </div>

           {/* Activity Feed Widget */}
           <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col flex-1 overflow-hidden">
             <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
                <Activity className="w-5 h-5 mr-2 text-primary-500" />
                Live Activity Feed
             </h3>
             <div className="flex-1 overflow-y-auto space-y-3 pr-2" style={{ maxHeight: '200px' }}>
                {recentLogs.length === 0 ? (
                   <p className="text-sm text-slate-400 text-center py-4">No recent activity.</p>
                ) : (
                   recentLogs.map(log => (
                      <div key={log.id} className="flex items-start space-x-3 text-sm pb-3 border-b border-slate-50 last:border-0 last:pb-0">
                         <div className={`mt-0.5 w-2 h-2 rounded-full flex-shrink-0 ${
                            log.severity === 'critical' ? 'bg-red-500' :
                            log.severity === 'high' ? 'bg-orange-500' :
                            log.severity === 'medium' ? 'bg-blue-500' : 'bg-green-500'
                         }`} />
                         <div>
                            <p className="font-medium text-slate-700">
                               <span className="font-bold">{log.userName}</span>: {log.action.replace('_', ' ')}
                            </p>
                            <p className="text-xs text-slate-500">{log.details}</p>
                            <p className="text-[10px] text-slate-400 mt-0.5">{new Date(log.timestamp).toLocaleTimeString()}</p>
                         </div>
                      </div>
                   ))
                )}
             </div>
           </div>
        </div>
      </div>

      {/* Top Products Table */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
         <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">{t('dashboard.topProducts')}</h3>
            <button className="text-sm text-primary-600 font-medium hover:underline">View Sales Report</button>
         </div>
         <div className="overflow-x-auto">
           <table className="w-full text-left">
             <thead className="bg-slate-50 border-b border-slate-100">
               <tr>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider pl-6">{t('inventory.productName')}</th>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">{t('dashboard.soldQty')}</th>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider text-right pr-6">{t('dashboard.revenue')}</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {topProducts.length === 0 ? (
                  <tr>
                     <td colSpan={3} className="text-center py-8 text-slate-400 text-sm">No sales data for this period.</td>
                  </tr>
               ) : (
                  topProducts.map((p, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-4 py-3 pl-6">
                         <div className="flex items-center">
                            <span className="w-6 h-6 rounded-full bg-slate-100 text-slate-500 flex items-center justify-center text-xs font-bold mr-3 group-hover:bg-primary-100 group-hover:text-primary-600 transition-colors">
                               {idx + 1}
                            </span>
                            <span className="font-medium text-slate-700">{p.name}</span>
                         </div>
                      </td>
                      <td className="px-4 py-3 text-right text-slate-600 font-mono text-sm">
                         {Math.round(p.qty)} <span className="text-[10px] text-slate-400 ml-1">{p.unit}</span>
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-slate-800 pr-6">
                         {formatPrice(p.revenue)}
                      </td>
                    </tr>
                  ))
               )}
             </tbody>
           </table>
         </div>
      </div>
    </div>
  );
};

export enum Category {
  CEMENT = 'Cement & Concrete',
  STEEL = 'Steel & Metal',
  WOOD = 'Wood & Lumber',
  PAINT = 'Paints & Finishes',
  TOOLS = 'Tools & Hardware',
  PLUMBING = 'Plumbing',
  ELECTRICAL = 'Electrical',
  CONSUMABLES = 'General Consumables'
}

export type UnitCategory = 'Weight' | 'Length' | 'Quantity';

export interface UnitDefinition {
  id: string;
  name: string;      // e.g. Kilogram
  symbol: string;    // e.g. kg
  category: UnitCategory;
  baseFactor: number; // 1 for base unit (e.g. g), 1000 for kg
  isBase: boolean;   // True if this is the reference unit
}

export interface CategoryItem {
  id: string;
  name: string;
  parentId: string | null; // null for root categories
  description?: string;
}

export interface ProductVariant {
  id: string;
  name: string;      // e.g., 'Piece', 'Small', 'Red' (Unit Name or Variant Name)
  code: string;      // SKU/Code for the variant
  barcode: string;   // Barcode for the variant
  conversionFactor: number; // How many variants in the main unit
  price: number;     // Price per variant
  costPrice?: number; // Cost price per variant
  color?: string;    // New: Color specification (e.g., 'Red', '#FF0000')
  size?: string;     // New: Size specification (e.g., 'XL', '10mm')
}

export interface ProductInventory {
  warehouseId: string;
  quantity: number;
}

export interface BranchPrice {
  branchId: string;
  price: number;
}

export interface ProductPhysical {
  weight?: number; // kg
  width?: number;  // cm
  height?: number; // cm
  depth?: number;  // cm (length)
}

export interface Product {
  id: string;
  name: string;
  category: Category | string; 
  price: number;     // Base Sell Price (Global)
  costPrice?: number; // Base Cost Price (For Profit Calc)
  branchPrices?: BranchPrice[]; // Overrides per branch
  stock: number;     // Stock count in MAIN units (Aggregate Total)
  minStock?: number; // Minimum stock threshold for alerts
  warehouseInventory?: ProductInventory[]; // Breakdown by warehouse
  unit: string;      // Name of the MAIN unit (e.g., 'bag', 'box')
  physical?: ProductPhysical; // New: Physical attributes
  imageUrl?: string;
  sku: string;       // SKU of MAIN unit
  barcode: string;   // Barcode of MAIN unit
  variants?: ProductVariant[]; // List of sub-products/variants
}

export interface CartItem extends Product {
  quantity: number;
  // Handling multi-unit/variant logic
  selectedVariantId?: string; // null if main unit, string if variant
  sellPrice: number; 
  sellUnit: string;  
  sellConversionFactor: number; // 1 for main, X for variant
}

export interface Sale {
  id: string;
  items: CartItem[];
  subtotal?: number; // Raw total before discount/tax
  discountAmount?: number; // Deduction amount
  total: number; // Final payable amount
  date: string;
  paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit';
  paymentStatus: 'paid' | 'unpaid' | 'partial'; // Track debt status
  amountReceived?: number; // Amount given by customer
  change?: number; // Change returned
  remainingAmount?: number; // Amount left to pay (for credit/partial)
  status: 'completed' | 'voided'; // Order status
  syncStatus?: 'synced' | 'pending' | 'failed'; // Track sync state
  customerId?: string; // Link to customer
  customerName?: string; // Snapshot of name
  pointsRedeemed?: number; // Points used
  pointsEarned?: number; // Points gained
}

export interface EstimateRequest {
  query: string;
}

export interface EstimateResultItem {
  productName: string;
  estimatedQuantity: number;
  unit: string;
  reasoning: string;
  matchedProductId?: string; // If found in inventory
}

// --- AI Inventory Analysis Types ---
export interface ReorderSuggestion {
  productId: string;
  productName: string;
  currentStock: number;
  suggestedReorderQty: number;
  priority: 'High' | 'Medium' | 'Low';
  reasoning: string;
}

export interface NewProductSuggestion {
  name: string;
  categoryName: string;
  estimatedPrice: number;
  reasoning: string;
  suggestedUnit: string;
}

export interface BundleSuggestion {
  bundleName: string;
  components: string[];
  estimatedPrice: number;
  reasoning: string;
  targetAudience: string;
}

export interface InventoryAnalysisResult {
  reorders: ReorderSuggestion[];
  newProducts: NewProductSuggestion[];
  bundles: BundleSuggestion[];
}

export interface Branch {
  id: string;
  name: string;
  address: string;
  phone: string;
  manager: string;
  isActive: boolean;
}

export interface PosMachine {
  id: string;
  branchId: string;
  machineNumber: string; // e.g., POS-01
