  }, []);

  // --- Automated Notifications Logic ---
  useEffect(() => {
    if (!products.length) return;

    // 1. Check Low Stock
    const lowStockItems = products.filter(p => p.stock <= (p.minStock || 20));
    if (lowStockItems.length > 0) {
       const hasUnread = notifications.some(n => n.type === 'warning' && n.title === 'Low Stock Alert' && !n.read);
       if (!hasUnread) {
          addNotification({
             title: 'Low Stock Alert',
             message: `${lowStockItems.length} items are below minimum stock level.`,
             type: 'warning',
             link: '/inventory'
          });
       }
    }
  }, [products]); 

  useEffect(() => {
     // 2. Check Pending Approvals
     const pendingCount = [
        ...transfers, ...counts, ...receipts, ...adjustments, ...reservations
     ].filter(d => d.status === 'Draft').length;

     if (pendingCount > 0) {
        const hasUnread = notifications.some(n => n.type === 'info' && n.title === 'Pending Approvals' && !n.read);
        if (!hasUnread) {
           addNotification({
              title: 'Pending Approvals',
              message: `You have ${pendingCount} documents waiting for review.`,
              type: 'info',
              link: '/approvals'
           });
        }
     }
  }, [transfers, counts, receipts, adjustments, reservations]);


  const t = (key: string): string => {
    const keys = key.split('.');
    let current: any = translations[settings.language] || translations['en'];
    for (const k of keys) {
      if (current[k] === undefined) return key;
      current = current[k];
    }
    return typeof current === 'string' ? current : key;
  };

  const formatPrice = (amount: number): string => {
    const symbol = settings.currencySymbol || '$';
    return `${symbol}${amount.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const addNotification = (n: Omit<AppNotification, 'id' | 'timestamp' | 'read'>) => {
     const newNotif: AppNotification = {
        ...n,
        id: `notif-${Date.now()}-${Math.random()}`,
        timestamp: new Date().toISOString(),
        read: false
     };
     setNotifications(prev => [newNotif, ...prev]);
  };

  const markNotificationRead = (id: string) => {
     setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));
  };

  const clearAllNotifications = () => {
     setNotifications([]);
  };

  // --- Audit Logging ---
  const logAction = (action: AuditAction, details: string, severity: 'low' | 'medium' | 'high' | 'critical' = 'low', resourceId?: string) => {
    if (!currentUser) return;

    const newLog: AuditLog = {
      id: `aud-${Date.now()}`,
      action,
      userId: currentUser.id,
      userName: currentUser.name,
      details,
      timestamp: new Date().toISOString(),
      severity,
      resourceId
    };

    setAuditLogs(prev => [newLog, ...prev]);
  };

  // --- RESTORE DATA ---
  const restoreSystemData = (data: any) => {
    if (data.users) setUsers(data.users);
    if (data.products) setProducts(data.products);
    if (data.sales) setSales(data.sales);
    if (data.units) setUnits(data.units);
    if (data.categories) setCategories(data.categories);
    if (data.branches) setBranches(data.branches);
    if (data.posMachines) setPosMachines(data.posMachines);
    if (data.warehouses) setWarehouses(data.warehouses);
    if (data.locations) setLocations(data.locations);
    if (data.transfers) setTransfers(data.transfers);
    if (data.counts) setCounts(data.counts);
    if (data.reservations) setReservations(data.reservations);
    if (data.receipts) setReceipts(data.receipts);
    if (data.adjustments) setAdjustments(data.adjustments);
    if (data.customers) setCustomers(data.customers);
    if (data.customerLevels) setCustomerLevels(data.customerLevels);
    if (data.shifts) setShifts(data.shifts);
    if (data.shiftSchedules) setShiftSchedules(data.shiftSchedules);
    if (data.promotions) setPromotions(data.promotions);
    if (data.settings) setSettingsState(data.settings);

    logAction('SETTINGS_UPDATE', 'System data restored from backup', 'high');
  };

  // --- ACTIONS ---

  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number, 
    paymentMethod: any = 'cash',
    amountReceived?: number,
    change?: number,
    pointsRedeemed: number = 0
  ): Promise<Sale> => {

    // Calculate Earned Points
    let pointsEarned = 0;
    if (settings.loyaltyProgram?.enabled && customerId) {
       const earnRate = settings.loyaltyProgram.earnRate || 10;
       pointsEarned = Math.floor(total / earnRate);
    }

    const payload = {
      items: items.map(i => ({
        productId: i.id,
        variantId: i.selectedVariantId,
        quantity: i.quantity,
        sellPrice: i.sellPrice
      })),
      total,
      subtotal,
      discountAmount,
      paymentMethod,
      amountReceived,
      change,
      customerId,
      pointsRedeemed,
      pointsEarned
    };

    // Client-side logic for consistency with persistence
    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items, total, subtotal, discountAmount,
      date: new Date().toISOString(),
      paymentMethod, amountReceived, change, customerId,
      customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined,
      status: 'completed',
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      remainingAmount: paymentMethod === 'credit' ? Math.max(0, total - (amountReceived || 0)) : 0,
      syncStatus: 'pending',
      pointsRedeemed,
      pointsEarned
    };

    setSales(prev => [newSale, ...prev]);

    // Update Inventory
    setProducts(prevProducts => prevProducts.map(product => {
      const cartItem = items.find(item => item.id === product.id);
      if (cartItem) {
        return { ...product, stock: product.stock - cartItem.quantity };
      }
      return product;
    }));

    // Update Customer Points
    if (customerId) {
        setCustomers(prev => prev.map(c => {
          if (c.id === customerId) {
              return { 
                ...c, 
                loyaltyPoints: Math.max(0, (c.loyaltyPoints || 0) - pointsRedeemed + pointsEarned) 
              };
          }
          return c;
        }));
    }

    return newSale;
  };

  const handleVoidSale = async (saleId: string) => {
     setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: 'voided' } : s));

     // Restore stock
     const saleToVoid = sales.find(s => s.id === saleId);
     if (saleToVoid) {
        setProducts(prevProducts => prevProducts.map(product => {
           const soldItem = saleToVoid.items.find(item => item.id === product.id);
           if (soldItem) {
              // Simple restoration (doesn't handle complex variant logic perfectly in this demo)
              return { ...product, stock: product.stock + soldItem.quantity };
           }
           return product;
        }));
     }
     logAction('SALE_VOID', `Voided sale ${saleId} (Persistent)`, 'high', saleId);
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
     setSales(prev => prev.map(s => {
        if (s.id === saleId) {
           return {
              ...s,
              paymentStatus: 'paid',
              remainingAmount: 0,
              amountReceived: (s.amountReceived || 0) + amount
           };
        }
        return s;
     }));
  };

  // --- CRUD Wrappers (Direct State Manipulation for Persistence) ---
  const addProduct = (p: Product) => setProducts(prev => [...prev, p]);
  const updateProduct = (p: Product) => setProducts(prev => prev.map(item => item.id === p.id ? p : item));
  const deleteProduct = (id: string) => setProducts(prev => prev.filter(item => item.id !== id));

  const addCustomer = (c: Customer) => setCustomers(prev => [...prev, c]);
  const updateCustomer = (c: Customer) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item));
  const deleteCustomer = (id: string) => setCustomers(prev => prev.filter(item => item.id !== id));

  const addUser = (u: User) => {
    setUsers(prev => [...prev, u]);
    logAction('USER_CREATE', `Created user ${u.name} (${u.role})`, 'medium', u.id);
  };
  const updateUser = (u: User) => setUsers(prev => prev.map(item => item.id === u.id ? u : item));
  const deleteUser = (id: string) => {
    setUsers(prev => prev.filter(item => item.id !== id));
    logAction('USER_DELETE', `Deleted user ID ${id}`, 'high', id);
  };

  const updateSettings = (s: SystemSettings) => {
    setSettingsState(s);
    logAction('SETTINGS_UPDATE', 'Updated system settings', 'medium');
  };

  const addUnit = (u: any) => setUnits(p => [...p, u]);
  const updateUnit = (u: any) => setUnits(p => p.map(x => x.id === u.id ? u : x));
  const deleteUnit = (id: string) => setUnits(p => p.filter(x => x.id !== id));

  const addCategory = (c: any) => setCategories(p => [...p, c]);
  const updateCategory = (c: any) => setCategories(p => p.map(x => x.id === c.id ? c : x));
  const deleteCategory = (id: string) => setCategories(p => p.filter(x => x.id !== id));

  const addBranch = (b: any) => setBranches(p => [...p, b]);
  const updateBranch = (b: any) => setBranches(p => p.map(x => x.id === b.id ? b : x));
  const deleteBranch = (id: string) => setBranches(p => p.filter(x => x.id !== id));

  const addPos = (p: any) => setPosMachines(prev => [...prev, p]);
  const updatePos = (p: any) => setPosMachines(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePos = (id: string) => setPosMachines(prev => prev.filter(item => item.id !== id));

  const addWarehouse = (w: any) => setWarehouses(p => [...p, w]);
  const updateWarehouse = (w: any) => setWarehouses(p => p.map(x => x.id === w.id ? w : x));
  const deleteWarehouse = (id: string) => setWarehouses(p => p.filter(x => x.id !== id));

  const addLocation = (l: any) => setLocations(p => [...p, l]);
  const updateLocation = (l: any) => setLocations(p => p.map(x => x.id === l.id ? l : x));
  const deleteLocation = (id: string) => setLocations(p => p.filter(x => x.id !== id));

  const addCustomerLevel = (l: any) => setCustomerLevels(p => [...p, l]);
  const updateCustomerLevel = (l: any) => setCustomerLevels(p => p.map(x => x.id === l.id ? l : x));
  const deleteCustomerLevel = (id: string) => setCustomerLevels(p => p.filter(x => x.id !== id));

  const updateTransfer = (t: any) => setTransfers(p => { const idx = p.findIndex(x => x.id === t.id); return idx >= 0 ? p.map(x => x.id === t.id ? t : x) : [t, ...p]; });
  const deleteTransfer = (id: string) => setTransfers(p => p.filter(x => x.id !== id));

  const updateCount = (c: any) => setCounts(p => { const idx = p.findIndex(x => x.id === c.id); return idx >= 0 ? p.map(x => x.id === c.id ? c : x) : [c, ...p]; });
  const deleteCount = (id: string) => setCounts(p => p.filter(x => x.id !== id));

  const updateReservation = (r: any) => setReservations(p => { const idx = p.findIndex(x => x.id === r.id); return idx >= 0 ? p.map(x => x.id === r.id ? r : x) : [r, ...p]; });
  const deleteReservation = (id: string) => setReservations(p => p.filter(x => x.id !== id));

  const updateReceipt = (r: any) => setReceipts(p => { const idx = p.findIndex(x => x.id === r.id); return idx >= 0 ? p.map(x => x.id === r.id ? r : x) : [r, ...p]; });
  const deleteReceipt = (id: string) => setReceipts(p => p.filter(x => x.id !== id));

  const updateAdjustment = (a: any) => setAdjustments(p => { const idx = p.findIndex(x => x.id === a.id); return idx >= 0 ? p.map(x => x.id === a.id ? a : x) : [a, ...p]; });
  const deleteAdjustment = (id: string) => setAdjustments(p => p.filter(x => x.id !== id));

  const handleStockStatusChange = (type: string, id: string, status: any) => {
     if(type === 'transfer') updateTransfer({ ...transfers.find(t=>t.id===id), status });
     if(type === 'count') updateCount({ ...counts.find(c=>c.id===id), status });
     if(type === 'reservation') updateReservation({ ...reservations.find(r=>r.id===id), status });
     if(type === 'receipt') updateReceipt({ ...receipts.find(r=>r.id===id), status });
     if(type === 'adjustment') updateAdjustment({ ...adjustments.find(a=>a.id===id), status });

     if (status === 'Approved' || status === 'Completed') {
        logAction('STOCK_APPROVE', `${type.toUpperCase()} ${id} status changed to ${status}`, 'low', id);
     } else if (status === 'Cancelled') {
        logAction('STOCK_REJECT', `${type.toUpperCase()} ${id} was rejected`, 'medium', id);
     }
  };

  const handleSyncOperation = (type: any) => {
     setSyncLogs(prev => [{ id: `log-${Date.now()}`, type, status: 'Success', timestamp: new Date().toISOString(), details: 'Manual Sync', durationMs: 200 }, ...prev]);
  };

  const startShift = (branchId: string, startCash: number, notes?: string) => {
     if(!currentUser) return;
     const newShift = { id: `shift-${Date.now()}`, userId: currentUser.id, branchId, startCash, startTime: new Date().toISOString(), status: 'Open', notes };
     setShifts(prev => [newShift as any, ...prev]);
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
     setShifts(prev => prev.map(s => s.id === shiftId ? { ...s, endCash, endTime: new Date().toISOString(), status: 'Closed', notes: notes || s.notes } : s));
  };

  const addShiftSchedule = (s: any) => setShiftSchedules(p => [...p, s]);
  const deleteShiftSchedule = (id: string) => setShiftSchedules(p => p.filter(x => x.id !== id));

  const addPromotion = (p: any) => setPromotions(prev => [...prev, p]);
  const updatePromotion = (p: any) => setPromotions(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePromotion = (id: string) => setPromotions(prev => prev.filter(item => item.id !== id));

  return (
    <GlobalContext.Provider value={{
      currentUser, setCurrentUser, isLoading,
      users, products, sales, units, categories, branches, posMachines, warehouses, locations,
      transfers, counts, reservations, receipts, adjustments, syncLogs, customers, customerLevels,
      shifts, shiftSchedules, promotions, settings, notifications, auditLogs,
      processSale, addProduct, updateProduct, deleteProduct,
      addUnit, updateUnit, deleteUnit, addCategory, updateCategory, deleteCategory,
      addBranch, updateBranch, deleteBranch, addPos, updatePos, deletePos,
      addWarehouse, updateWarehouse, deleteWarehouse, addLocation, updateLocation, deleteLocation,
      addUser, updateUser, deleteUser, addCustomer, updateCustomer, deleteCustomer,
      addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,
      updateTransfer, deleteTransfer, updateCount, deleteCount, updateReservation, deleteReservation,
      updateReceipt, deleteReceipt, updateAdjustment, deleteAdjustment,
      handleStockStatusChange, handleSyncOperation,
      startShift, endShift, addShiftSchedule, deleteShiftSchedule,
      addPromotion, updatePromotion, deletePromotion,
      updateSettings, settleSaleDebt, handleVoidSale, t, formatPrice,
      addNotification, markNotificationRead, clearAllNotifications,
      restoreSystemData, logAction
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (context === undefined) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  LayoutDashboard, 
  ShoppingCart, 
  Package, 
  Hammer, 
  LogOut,
  Menu,
  Scale,
  FolderTree,
  Store,
  Container,
  ClipboardList,
  FileCheck,
  UserCircle,
  Users,
  Settings,
  RefreshCw,
  Contact,
  Clock,
  Tv,
  Bell,
  Search,
  ChevronDown,
  X,
  BarChart4,
  Keyboard
} from 'lucide-react';
import { User, UserRole } from '../types';
import { useGlobal } from '../context/GlobalContext';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  onTabChange: (tab: string) => void;
  currentUser: User | null;
  onLogout: () => void;
}

interface NavItemConfig {
  id: string;
  icon: any;
  label: string;
  allowedRoles: UserRole[];
}

const NAV_ITEMS: NavItemConfig[] = [
  { id: 'dashboard', icon: LayoutDashboard, label: 'Dashboard', allowedRoles: ['Admin', 'Manager'] },
  { id: 'reports', icon: BarChart4, label: 'Reports & Analytics', allowedRoles: ['Admin', 'Manager'] },
  { id: 'pos', icon: ShoppingCart, label: 'Point of Sale', allowedRoles: ['Admin', 'Manager', 'Staff', 'Cashier'] },
  { id: 'shifts', icon: Clock, label: 'My Shift', allowedRoles: ['Admin', 'Manager', 'Staff', 'Cashier'] },
  { id: 'inventory', icon: Package, label: 'Inventory', allowedRoles: ['Admin', 'Manager', 'Staff'] },
  { id: 'stock', icon: ClipboardList, label: 'Stock Mgmt', allowedRoles: ['Admin', 'Manager', 'Staff'] },
  { id: 'customers', icon: Contact, label: 'Customers', allowedRoles: ['Admin', 'Manager', 'Cashier', 'Staff'] },
  { id: 'approvals', icon: FileCheck, label: 'Approvals', allowedRoles: ['Admin', 'Manager'] },
  { id: 'promotions', icon: Tv, label: 'Promotions', allowedRoles: ['Admin', 'Manager', 'Staff'] },
  { id: 'sync', icon: RefreshCw, label: 'Data Sync', allowedRoles: ['Admin', 'Manager'] },
  { id: 'categories', icon: FolderTree, label: 'Categories', allowedRoles: ['Admin', 'Staff', 'Manager'] },
  { id: 'units', icon: Scale, label: 'Unit Mgmt', allowedRoles: ['Admin', 'Staff', 'Manager'] },
  { id: 'branches', icon: Store, label: 'Branches & POS', allowedRoles: ['Admin', 'Manager'] },
  { id: 'warehouses', icon: Container, label: 'Warehouse (WMS)', allowedRoles: ['Admin', 'Staff', 'Manager'] },
  { id: 'users', icon: Users, label: 'Users & Roles', allowedRoles: ['Admin', 'Manager'] },
  { id: 'settings', icon: Settings, label: 'Settings', allowedRoles: ['Admin'] },
];

export const Layout: React.FC<LayoutProps> = ({ children, activeTab, onTabChange, currentUser, onLogout }) => {
  const { t, notifications, markNotificationRead, clearAllNotifications } = useGlobal();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [showKeyboardHelp, setShowKeyboardHelp] = useState(false);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const notifRef = useRef<HTMLDivElement>(null);
  const userMenuRef = useRef<HTMLDivElement>(null);

  // Filter nav items based on user role
  const visibleNavItems = NAV_ITEMS.filter(item => 
    currentUser && item.allowedRoles.includes(currentUser.role)
  );

  const unreadCount = notifications.filter(n => !n.read).length;

  // Click outside to close dropdowns
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
      }
      if (userMenuRef.current && !userMenuRef.current.contains(event.target as Node)) {
        setShowUserMenu(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Global Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // F1 - Dashboard
      if (e.key === 'F1') {
        e.preventDefault();
        onTabChange('dashboard');
      }
      // F2 - POS
      if (e.key === 'F2') {
        e.preventDefault();
        onTabChange('pos');
      }
      // F3 - Inventory
      if (e.key === 'F3') {
        e.preventDefault();
        onTabChange('inventory');
      }
      // F4 / Ctrl+K / Cmd+K - Focus Search
      if (e.key === 'F4' || ((e.ctrlKey || e.metaKey) && e.key === 'k')) {
        e.preventDefault();
        searchInputRef.current?.focus();
      }
      // Shift + ? - Show Shortcuts
      if (e.shiftKey && e.key === '?') {
        e.preventDefault();
        setShowKeyboardHelp(prev => !prev);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onTabChange]);

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden">
      {/* Sidebar - Desktop */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 text-white transform transition-transform duration-300 ease-in-out
        md:relative md:translate-x-0
        ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="flex items-center justify-center h-20 border-b border-slate-800">
          <div className="flex items-center space-x-2">
            <div className="bg-construction-orange p-2 rounded-lg">
              <Hammer className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold tracking-tight">{t('app.name')}</h1>
          </div>
        </div>

        <nav className="p-4 mt-2 overflow-y-auto max-h-[calc(100vh-80px)] scrollbar-hide">
          {visibleNavItems.map(item => {
            const Icon = item.icon;
            return (
              <button
                key={item.id}
                onClick={() => {
                  onTabChange(item.id);
                  setMobileMenuOpen(false);
                }}
                className={`flex items-center w-full px-4 py-3 mb-2 rounded-lg transition-colors duration-200 ${
                  activeTab === item.id 
                    ? 'bg-primary-600 text-white shadow-md' 
                    : 'text-slate-400 hover:bg-slate-800 hover:text-white'
                }`}
              >
                <Icon className="w-5 h-5 mr-3" />
                <span className="font-medium">{t(`nav.${item.id}`)}</span>
                {item.id === 'dashboard' && <span className="ml-auto text-[10px] bg-slate-800 px-1.5 rounded text-slate-500 hidden xl:inline">F1</span>}
                {item.id === 'pos' && <span className="ml-auto text-[10px] bg-slate-800 px-1.5 rounded text-slate-500 hidden xl:inline">F2</span>}
                {item.id === 'inventory' && <span className="ml-auto text-[10px] bg-slate-800 px-1.5 rounded text-slate-500 hidden xl:inline">F3</span>}
              </button>
            );
          })}
        </nav>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden">

        {/* Desktop Header */}
        <header className="h-16 bg-white border-b border-slate-200 shadow-sm flex items-center justify-between px-4 md:px-6 z-20">
          {/* Mobile Menu Toggle */}
          <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="p-2 md:hidden text-slate-600">
            <Menu className="w-6 h-6" />
          </button>

          {/* Search Bar */}
          <div className="hidden md:flex items-center bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 w-64 lg:w-96 group focus-within:border-primary-500 focus-within:ring-2 focus-within:ring-primary-100 transition-all">
             <Search className="w-4 h-4 text-slate-400 mr-2 group-focus-within:text-primary-500" />
             <input 
               ref={searchInputRef}
               type="text" 
               placeholder="Global Search (Ctrl+K)..." 
               className="bg-transparent text-sm focus:outline-none w-full text-slate-600"
             />
             <kbd className="hidden lg:inline-block text-[10px] text-slate-400 bg-white border border-slate-300 rounded px-1.5 py-0.5 ml-2">
               ⌘K
             </kbd>
          </div>

          {/* Right Actions */}
          <div className="flex items-center space-x-2 md:space-x-4">
             {/* Shortcut Help Trigger */}
             <button 
                onClick={() => setShowKeyboardHelp(true)}
                className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full hidden md:block transition-colors"
                title="Keyboard Shortcuts (Shift+?)"
             >
                <Keyboard className="w-5 h-5" />
             </button>

             {/* Notifications */}
             <div className="relative" ref={notifRef}>
                <button 
                  onClick={() => setShowNotifications(!showNotifications)}
                  className="p-2 text-slate-500 hover:bg-slate-100 rounded-full relative transition-colors"
                >
                   <Bell className="w-6 h-6" />
                   {unreadCount > 0 && (
                      <span className="absolute top-1.5 right-1.5 w-2.5 h-2.5 bg-red-500 border-2 border-white rounded-full"></span>
                   )}
                </button>

                {showNotifications && (
                   <div className="absolute right-0 mt-3 w-80 bg-white rounded-xl shadow-2xl border border-slate-100 overflow-hidden z-50 animate-fade-in origin-top-right">
                      <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                         <h3 className="font-bold text-slate-700">Notifications</h3>
                         {notifications.length > 0 && (
                            <button onClick={clearAllNotifications} className="text-xs text-blue-600 hover:underline">Clear all</button>
                         )}
                      </div>
                      <div className="max-h-[300px] overflow-y-auto">
                         {notifications.length === 0 ? (
                            <div className="p-8 text-center text-slate-400">
                               <Bell className="w-8 h-8 mx-auto mb-2 opacity-20" />
                               <p className="text-sm">No new notifications</p>
                            </div>
                         ) : (
                            <div className="divide-y divide-slate-100">
                               {notifications.map(n => (
                                  <div 
                                    key={n.id} 
                                    className={`p-4 hover:bg-slate-50 transition-colors cursor-pointer ${!n.read ? 'bg-blue-50/30' : ''}`}
                                    onClick={() => {
                                       markNotificationRead(n.id);
                                       if(n.link) onTabChange(n.link.replace('/', ''));
                                    }}
                                  >
                                     <div className="flex justify-between items-start mb-1">
                                        <h4 className={`text-sm font-semibold ${!n.read ? 'text-slate-800' : 'text-slate-600'}`}>{n.title}</h4>
                                        {!n.read && <span className="w-2 h-2 bg-blue-500 rounded-full"></span>}
                                     </div>
                                     <p className="text-xs text-slate-500 mb-1">{n.message}</p>
                                     <span className="text-[10px] text-slate-400">{new Date(n.timestamp).toLocaleTimeString()}</span>
                                  </div>
                               ))}
                            </div>
                         )}
                      </div>
                   </div>
                )}
             </div>

             {/* User Profile */}
             <div className="relative" ref={userMenuRef}>
                <button 
                  onClick={() => setShowUserMenu(!showUserMenu)}
                  className="flex items-center space-x-2 hover:bg-slate-50 p-1.5 rounded-lg transition-colors border border-transparent hover:border-slate-100"
                >
                   <div className="w-8 h-8 rounded-full bg-slate-200 overflow-hidden flex items-center justify-center border border-slate-300">
                      {currentUser?.avatarUrl ? (
                         <img src={currentUser.avatarUrl} alt={currentUser.name} className="w-full h-full object-cover" />
                      ) : (
                         <UserCircle className="w-5 h-5 text-slate-400" />
                      )}
                   </div>
                   <div className="hidden md:block text-left">
                      <p className="text-sm font-bold text-slate-700 leading-none">{currentUser?.name}</p>
                      <p className="text-[10px] text-slate-500 uppercase font-bold mt-0.5">{currentUser?.role}</p>
                   </div>
                   <ChevronDown className="w-4 h-4 text-slate-400 hidden md:block" />
                </button>

                {showUserMenu && (
                   <div className="absolute right-0 mt-3 w-48 bg-white rounded-xl shadow-xl border border-slate-100 overflow-hidden z-50 animate-fade-in origin-top-right">
                      <div className="p-3 border-b border-slate-100 md:hidden">
                         <p className="font-bold text-slate-800">{currentUser?.name}</p>
                         <p className="text-xs text-slate-500">{currentUser?.role}</p>
                      </div>
                      <div className="p-1">
                         <button 
                           onClick={() => { onTabChange('settings'); setShowUserMenu(false); }}
                           className="flex items-center w-full px-3 py-2 text-sm text-slate-600 hover:bg-slate-50 hover:text-slate-900 rounded-lg transition-colors"
                         >
                            <Settings className="w-4 h-4 mr-2" /> Settings
                         </button>
                         <button 
                           onClick={onLogout}
                           className="flex items-center w-full px-3 py-2 text-sm text-red-600 hover:bg-red-50 rounded-lg transition-colors mt-1"
                         >
                            <LogOut className="w-4 h-4 mr-2" /> Logout
                         </button>
                      </div>
                   </div>
                )}
             </div>
          </div>
        </header>

        {/* Content Area */}
        <main className="flex-1 overflow-y-auto p-4 md:p-6 bg-slate-50 relative">
          {children}
        </main>
      </div>

      {/* Overlay for mobile menu */}
      {mobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 z-40 md:hidden"
          onClick={() => setMobileMenuOpen(false)}
        />
      )}

      {/* Keyboard Shortcuts Modal */}
      {showKeyboardHelp && (
         <div className="fixed inset-0 bg-black bg-opacity-50 z-[60] flex items-center justify-center p-4 backdrop-blur-sm" onClick={() => setShowKeyboardHelp(false)}>
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden animate-fade-in" onClick={e => e.stopPropagation()}>
               <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                  <h3 className="font-bold text-slate-800 flex items-center">
                     <Keyboard className="w-5 h-5 mr-2 text-slate-500" />
                     Keyboard Shortcuts
                  </h3>
                  <button onClick={() => setShowKeyboardHelp(false)} className="text-slate-400 hover:text-slate-600"><X className="w-5 h-5" /></button>
               </div>
               <div className="p-4 space-y-2">
                  {[
                     { keys: ['F1'], label: 'Go to Dashboard' },
                     { keys: ['F2'], label: 'Go to POS Terminal' },
                     { keys: ['F3'], label: 'Go to Inventory' },
                     { keys: ['F4', 'Ctrl', 'K'], label: 'Focus Search' },
                     { keys: ['Shift', '?'], label: 'Show this help' },
                  ].map((sc, i) => (
                     <div key={i} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-0">
                        <span className="text-sm text-slate-600 font-medium">{sc.label}</span>
                        <div className="flex space-x-1">
                           {sc.keys.map((k, j) => (
                              <span key={j} className="px-2 py-1 bg-slate-100 border border-slate-200 rounded text-xs font-mono font-bold text-slate-500 min-w-[24px] text-center">
                                 {k}
                              </span>
                           ))}
                        </div>
                     </div>
                  ))}
               </div>
               <div className="p-4 bg-slate-50 text-center text-xs text-slate-400">
                  Press <span className="font-bold">Esc</span> to close dialogs
               </div>
            </div>
         </div>
      )}
    </div>
  );
};

export enum Category {
  CEMENT = 'Cement & Concrete',
  STEEL = 'Steel & Metal',
  WOOD = 'Wood & Lumber',
  PAINT = 'Paints & Finishes',
  TOOLS = 'Tools & Hardware',
  PLUMBING = 'Plumbing',
  ELECTRICAL = 'Electrical',
  CONSUMABLES = 'General Consumables'
}

export type UnitCategory = 'Weight' | 'Length' | 'Quantity';

export interface UnitDefinition {
  id: string;
  name: string;      // e.g. Kilogram
  symbol: string;    // e.g. kg
  category: UnitCategory;
  baseFactor: number; // 1 for base unit (e.g. g), 1000 for kg
  isBase: boolean;   // True if this is the reference unit
}

export interface CategoryItem {
  id: string;
  name: string;
  parentId: string | null; // null for root categories
  description?: string;
}

export interface ProductVariant {
  id: string;
  name: string;      // e.g., 'Piece', 'Small', 'Red' (Unit Name or Variant Name)
  code: string;      // SKU/Code for the variant
  barcode: string;   // Barcode for the variant
  conversionFactor: number; // How many variants in the main unit
  price: number;     // Price per variant
  costPrice?: number; // Cost price per variant
  color?: string;    // New: Color specification (e.g., 'Red', '#FF0000')
  size?: string;     // New: Size specification (e.g., 'XL', '10mm')
}

export interface ProductInventory {
  warehouseId: string;
  quantity: number;
}

export interface BranchPrice {
  branchId: string;
  price: number;
}

export interface ProductPhysical {
  weight?: number; // kg
  width?: number;  // cm
  height?: number; // cm
  depth?: number;  // cm (length)
}

export interface Product {
  id: string;
  name: string;
  category: Category | string; 
  price: number;     // Base Sell Price (Global)
  costPrice?: number; // Base Cost Price (For Profit Calc)
  branchPrices?: BranchPrice[]; // Overrides per branch
  stock: number;     // Stock count in MAIN units (Aggregate Total)
  minStock?: number; // Minimum stock threshold for alerts
  warehouseInventory?: ProductInventory[]; // Breakdown by warehouse
  unit: string;      // Name of the MAIN unit (e.g., 'bag', 'box')
  physical?: ProductPhysical; // New: Physical attributes
  imageUrl?: string;
  sku: string;       // SKU of MAIN unit
  barcode: string;   // Barcode of MAIN unit
  variants?: ProductVariant[]; // List of sub-products/variants
}

export interface CartItem extends Product {
  quantity: number;
  // Handling multi-unit/variant logic
  selectedVariantId?: string; // null if main unit, string if variant
  sellPrice: number; 
  sellUnit: string;  
  sellConversionFactor: number; // 1 for main, X for variant
}

export interface Sale {
  id: string;
  items: CartItem[];
  subtotal?: number; // Raw total before discount/tax
  discountAmount?: number; // Deduction amount
  total: number; // Final payable amount
  date: string;
  paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit';
  paymentStatus: 'paid' | 'unpaid' | 'partial'; // Track debt status
  amountReceived?: number; // Amount given by customer
  change?: number; // Change returned
  remainingAmount?: number; // Amount left to pay (for credit/partial)
  status: 'completed' | 'voided'; // Order status
  syncStatus?: 'synced' | 'pending' | 'failed'; // Track sync state
  customerId?: string; // Link to customer
  customerName?: string; // Snapshot of name
  pointsRedeemed?: number; // Points used
  pointsEarned?: number; // Points gained
  userId?: string; // ID of the staff who processed the sale
  userName?: string; // Name of the staff who processed the sale
}

export interface EstimateRequest {
  query: string;
}

export interface EstimateResultItem {
  productName: string;
  estimatedQuantity: number;
  unit: string;
  reasoning: string;
  matchedProductId?: string; // If found in inventory
}

// --- AI Inventory Analysis Types ---
export interface ReorderSuggestion {
  productId: string;
  productName: string;
  currentStock: number;
  suggestedReorderQty: number;
  priority: 'High' | 'Medium' | 'Low';
  reasoning: string;
}

export interface NewProductSuggestion {
  name: string;
  categoryName: string;
  estimatedPrice: number;
  reasoning: string;
  suggestedUnit: string;
}

export interface BundleSuggestion {
  bundleName: string;
  components: string[];
  estimatedPrice: number;
  reasoning: string;
  targetAudience: string;
}

export interface InventoryAnalysisResult {
  reorders: ReorderSuggestion[];
  newProducts: NewProductSuggestion[];
  bundles: BundleSuggestion[];
}

export interface Branch {
  id: string;
  name: string;
  address: string;
  phone: string;
  manager: string;
  isActive: boolean;
}

export interface PosMachine {
  id: string;
  branchId: string;
  machineNumber: string; // e.g., POS-01
  status: 'active' | 'maintenance' | 'inactive';
  lastActive?: string;
}

export interface Warehouse {
  id: string;
  branchId: string;
  name: string;
  code: string; // e.g., WH-01
  type: 'General' | 'Cold Storage' | 'Hazardous' | 'Showroom';
  description?: string;
}

export interface StorageLocation {
  id: string;
  warehouseId: string;
  zone: string;   // e.g., Zone A
  rack: string;   // e.g., Rack 01
  shelf: string;  // e.g., Shelf 03 (Level)
  bin: string;    // e.g., Bin B (Slot)
  fullCode: string; // Helper: A-01-03-B
  type?: 'Pallet' | 'Shelf' | 'Floor';
}

// --- Customer Types ---
export interface CustomerLevel {
  id: string;
  name: string;
  discountPercentage: number;
  color?: string;
}

export interface Customer {
  id: string;
  code: string; // Membership ID or Code
  name: string;
  phone: string;
  taxId?: string;
  address?: string;
  email?: string;
  loyaltyPoints: number;
  notes?: string;
  levelId?: string;
  level?: CustomerLevel;
}

// --- Stock Management Types ---

export type DocumentStatus = 'Draft' | 'Approved' | 'Completed' | 'Cancelled';

export interface StockItem {
  productId: string;
  variantId?: string; // Optional: if specific variant
  productName: string;
  unit: string;
  quantity: number;
  note?: string;
}

// 1. Transfer Request
export interface StockTransfer {
  id: string;
  date: string;
  sourceWarehouseId: string;
  targetWarehouseId: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 2. Stock Count
export interface StockCountItem extends StockItem {
  systemQuantity: number; // Snapshot of system stock
  countedQuantity: number; // Actual count
  diff: number; // Calculated diff
}

export interface StockCount {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockCountItem[];
  referenceNo: string;
  counterName: string; // Who counted
  reason: string; // Mandatory reason for adjustment
}

// 3. Stock Reservation
export interface StockReservation {
  id: string;
  date: string;
  expiryDate: string;
  warehouseId: string;
  customerName: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 4. Goods Receipt
export interface StockReceiptItem extends StockItem {
  costPrice: number; // Cost per unit
}

export interface StockReceipt {
  id: string;
  date: string;
  warehouseId: string;
  vendorName: string;
  vendorInvoiceNo?: string;
  status: DocumentStatus;
  items: StockReceiptItem[];
  referenceNo: string;
  totalCost: number;
}

// 5. Stock Adjustment
export interface StockAdjustment {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockItem[]; // Quantity can be negative (decrease) or positive (increase)
  referenceNo: string;
  reason: string; // Mandatory
}

// --- Sync Types ---
export interface SyncLog {
  id: string;
  timestamp: string;
  type: 'Auto' | 'Manual' | 'Push' | 'Pull';
  status: 'Success' | 'Failed' | 'Partial';
  details: string; // e.g., "5 Sales uploaded, 0 Products updated"
  durationMs: number;
}

// --- User & Roles ---

export type UserRole = 'Admin' | 'Manager' | 'Staff' | 'Cashier';

export interface User {
  id: string;
  username: string;
  password?: string; // Added for login
  email?: string;    // Optional
  name: string;
  role: UserRole;
  avatarUrl?: string;
  department?: string;
  branchId?: string;
}

// --- Shift Management ---
export interface Shift {
  id: string;
  userId: string;
  branchId: string;
  startTime: string;
  endTime?: string;
  startCash: number;
  endCash?: number;
  notes?: string;
  status: 'Open' | 'Closed';
  userName?: string; // Optional helper
  branchName?: string; // Optional helper
}

export interface ShiftSchedule {
  id: string;
  userId: string;
  branchId: string;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:mm (24hr)
  endTime: string; // HH:mm (24hr)
  note?: string;
}

// --- Settings & Promotions ---
export type Language = 'en' | 'th' | 'lo';

export interface Promotion {
  id: string;
  title: string;
  imageUrl: string;
  isActive: boolean;
  order?: number;
  startDate?: string; // ISO Date
  endDate?: string;   // ISO Date
}

export interface LocalDatabaseConfig {
  enabled: boolean;
  type: 'postgresql' | 'sqlite' | 'mysql';
  host: string;
  port: string;
  databaseName: string;
  username: string;
  password: string;
}

export interface TaxSettings {
  enabled: boolean;             
  rate: number;                 
  calculationMode: 'included' | 'excluded'; 
  displayOnReceipt: boolean;    
}

export interface CustomerDisplaySettings {
  enabled: boolean;
  welcomeMessage: string;
  promotionInterval: number; // Seconds
}

export interface SystemSettings {
  // Company Info
  companyName: string;
  taxId: string;
  address: string;
  phone: string;

  // Localization
  language: Language;
  currencySymbol: string;

  // Interface
  defaultItemsPerPage: number;

  // Tax / VAT
  tax: TaxSettings;

  // Customer Display
  customerDisplay: CustomerDisplaySettings;

  // Loyalty Settings
  loyaltyProgram: {
    enabled: boolean;
    earnRate: number; // Amount to spend to earn 1 point (e.g. $10 = 1 point)
    redeemRate: number; // Points needed for 1 currency unit discount (e.g. 100 points = $1)
  };

  // Receipt & Print
  receiptHeader: string;
  receiptFooter: string;
  receiptLogoUrl?: string;
  receiptQrCodeUrl?: string; // Bank QR Code for receipt
  receiptPaperSize: '58mm' | '80mm' | 'A4';
  receiptAutoPrint: boolean;
  receiptShowTaxId: boolean;
  receiptShowCashier: boolean;
  receiptCopies: number;

  // Device Configuration
  currentBranchId?: string;
  currentPosId?: string;
  deviceRole?: 'Master' | 'Slave';

  // Local Database (For Slave offline mode)
  localDatabase?: LocalDatabaseConfig;

  // Synchronization (Master/Slave)
  masterApiUrl?: string; // e.g., http://192.168.1.100:3000
  autoSyncInterval?: number; // In minutes, 0 for manual
  lastSyncTime?: string;
}

// --- Notifications & Audit ---
export interface AppNotification {
  id: string;
  title: string;
  message: string;
  type: 'info' | 'warning' | 'error' | 'success';
  timestamp: string;
  read: boolean;
  link?: string; // Optional link to navigate to (e.g. '/approvals')
}

export type AuditAction = 
  | 'SALE_VOID' 
  | 'USER_CREATE' 
  | 'USER_DELETE' 
  | 'SETTINGS_UPDATE' 
  | 'STOCK_APPROVE' 
  | 'STOCK_REJECT'
  | 'SHIFT_OVERRIDE'
  | 'LOGIN_FAILED';

export interface AuditLog {
  id: string;
  action: AuditAction;
  userId: string;
  userName: string;
  details: string;
  timestamp: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  resourceId?: string;
}

