  }
  return context;
};

// Helper for persistence
const usePersistedState = <T,>(key: string, initialValue: T): [T, React.Dispatch<React.SetStateAction<T>>] => {
  const [state, setState] = useState<T>(() => {
    try {
      if (typeof window !== 'undefined') {
        const item = window.localStorage.getItem(key);
        return item ? JSON.parse(item) : initialValue;
      }
    } catch (error) {
      console.warn(`Error reading localStorage key "${key}":`, error);
    }
    return initialValue;
  });

  useEffect(() => {
    try {
      if (typeof window !== 'undefined') {
        window.localStorage.setItem(key, JSON.stringify(state));
      }
    } catch (error) {
      console.warn(`Error saving localStorage key "${key}":`, error);
    }
  }, [key, state]);

  return [state, setState];
};

// Helper for API calls with silent fallback
const apiRequest = async (url: string, method: string = 'GET', body?: any) => {
  try {
    const options: RequestInit = {
      method,
      headers: { 'Content-Type': 'application/json' },
    };
    if (body) options.body = JSON.stringify(body);

    const res = await fetch(url, options);

    if (res.status === 404) {
      return null;
    }

    if (!res.ok) {
      throw new Error(`API Error: ${res.statusText}`);
    }

    return await res.json();
  } catch (error) {
    return null;
  }
};

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null); // Session only
  const [isLoading, setIsLoading] = useState(true);

  // Persisted State
  const [users, setUsers] = usePersistedState<User[]>('bm_users', INITIAL_USERS);
  const [products, setProducts] = usePersistedState<Product[]>('bm_products', INITIAL_PRODUCTS);
  const [sales, setSales] = usePersistedState<Sale[]>('bm_sales', INITIAL_SALES);
  const [units, setUnits] = usePersistedState<UnitDefinition[]>('bm_units', INITIAL_UNITS);
  const [categories, setCategories] = usePersistedState<CategoryItem[]>('bm_categories', INITIAL_CATEGORIES_TREE);
  const [branches, setBranches] = usePersistedState<Branch[]>('bm_branches', INITIAL_BRANCHES);
  const [posMachines, setPosMachines] = usePersistedState<PosMachine[]>('bm_pos', INITIAL_POS_MACHINES);
  const [warehouses, setWarehouses] = usePersistedState<Warehouse[]>('bm_warehouses', INITIAL_WAREHOUSES);
  const [locations, setLocations] = usePersistedState<StorageLocation[]>('bm_locations', INITIAL_LOCATIONS);

  // Stock Docs
  const [transfers, setTransfers] = usePersistedState<StockTransfer[]>('bm_transfers', INITIAL_TRANSFERS);
  const [counts, setCounts] = usePersistedState<StockCount[]>('bm_counts', INITIAL_COUNTS);
  const [reservations, setReservations] = usePersistedState<StockReservation[]>('bm_reservations', INITIAL_RESERVATIONS);
  const [receipts, setReceipts] = usePersistedState<StockReceipt[]>('bm_receipts', INITIAL_RECEIPTS);
  const [adjustments, setAdjustments] = usePersistedState<StockAdjustment[]>('bm_adjustments', INITIAL_ADJUSTMENTS);

  const [syncLogs, setSyncLogs] = usePersistedState<SyncLog[]>('bm_logs', INITIAL_SYNC_LOGS);
  const [customers, setCustomers] = usePersistedState<Customer[]>('bm_customers', INITIAL_CUSTOMERS);
  const [customerLevels, setCustomerLevels] = usePersistedState<CustomerLevel[]>('bm_levels', INITIAL_CUSTOMER_LEVELS);

  const [shifts, setShifts] = usePersistedState<Shift[]>('bm_shifts', []);
  const [shiftSchedules, setShiftSchedules] = usePersistedState<ShiftSchedule[]>('bm_schedules', INITIAL_SHIFT_SCHEDULES);
  const [promotions, setPromotions] = usePersistedState<Promotion[]>('bm_promotions', INITIAL_PROMOTIONS);
  const [settings, setSettingsState] = usePersistedState<SystemSettings>('bm_settings', INITIAL_SETTINGS);

  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [auditLogs, setAuditLogs] = usePersistedState<AuditLog[]>('bm_audit', INITIAL_AUDIT_LOGS);

  // Fake "loading" to simulate system init
  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 500);
    return () => clearTimeout(timer);
  }, []);

  // --- Automated Notifications Logic ---
  useEffect(() => {
    if (!products.length) return;

    // 1. Check Low Stock
    const lowStockItems = products.filter(p => p.stock <= (p.minStock || 20));
    if (lowStockItems.length > 0) {
       const hasUnread = notifications.some(n => n.type === 'warning' && n.title === 'Low Stock Alert' && !n.read);
       if (!hasUnread) {
          addNotification({
             title: 'Low Stock Alert',
             message: `${lowStockItems.length} items are below minimum stock level.`,
             type: 'warning',
             link: '/inventory'
          });
       }
    }
  }, [products]); 

  useEffect(() => {
     // 2. Check Pending Approvals
     const pendingCount = [
        ...transfers, ...counts, ...receipts, ...adjustments, ...reservations
     ].filter(d => d.status === 'Draft').length;

     if (pendingCount > 0) {
        const hasUnread = notifications.some(n => n.type === 'info' && n.title === 'Pending Approvals' && !n.read);
        if (!hasUnread) {
           addNotification({
              title: 'Pending Approvals',
              message: `You have ${pendingCount} documents waiting for review.`,
              type: 'info',
              link: '/approvals'
           });
        }
     }
  }, [transfers, counts, receipts, adjustments, reservations]);


  const t = (key: string): string => {
    const keys = key.split('.');
    let current: any = translations[settings.language] || translations['en'];
    for (const k of keys) {
      if (current[k] === undefined) return key;
      current = current[k];
    }
    return typeof current === 'string' ? current : key;
  };

  const formatPrice = (amount: number): string => {
    const symbol = settings.currencySymbol || '$';
    return `${symbol}${amount.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const addNotification = (n: Omit<AppNotification, 'id' | 'timestamp' | 'read'>) => {
     const newNotif: AppNotification = {
        ...n,
        id: `notif-${Date.now()}-${Math.random()}`,
        timestamp: new Date().toISOString(),
        read: false
     };
     setNotifications(prev => [newNotif, ...prev]);
  };

  const markNotificationRead = (id: string) => {
     setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));
  };

  const clearAllNotifications = () => {
     setNotifications([]);
  };

  // --- Audit Logging ---
  const logAction = (action: AuditAction, details: string, severity: 'low' | 'medium' | 'high' | 'critical' = 'low', resourceId?: string) => {
    if (!currentUser) return;

    const newLog: AuditLog = {
      id: `aud-${Date.now()}`,
      action,
      userId: currentUser.id,
      userName: currentUser.name,
      details,
      timestamp: new Date().toISOString(),
      severity,
      resourceId
    };

    setAuditLogs(prev => [newLog, ...prev]);
  };

  // --- RESTORE DATA ---
  const restoreSystemData = (data: any) => {
    if (data.users) setUsers(data.users);
    if (data.products) setProducts(data.products);
    if (data.sales) setSales(data.sales);
    if (data.units) setUnits(data.units);
    if (data.categories) setCategories(data.categories);
    if (data.branches) setBranches(data.branches);
    if (data.posMachines) setPosMachines(data.posMachines);
    if (data.warehouses) setWarehouses(data.warehouses);
    if (data.locations) setLocations(data.locations);
    if (data.transfers) setTransfers(data.transfers);
    if (data.counts) setCounts(data.counts);
    if (data.reservations) setReservations(data.reservations);
    if (data.receipts) setReceipts(data.receipts);
    if (data.adjustments) setAdjustments(data.adjustments);
    if (data.customers) setCustomers(data.customers);
    if (data.customerLevels) setCustomerLevels(data.customerLevels);
    if (data.shifts) setShifts(data.shifts);
    if (data.shiftSchedules) setShiftSchedules(data.shiftSchedules);
    if (data.promotions) setPromotions(data.promotions);
    if (data.settings) setSettingsState(data.settings);

    logAction('SETTINGS_UPDATE', 'System data restored from backup', 'high');
  };

  // --- ACTIONS ---

  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number, 
    paymentMethod: any = 'cash',
    amountReceived?: number,
    change?: number,
    pointsRedeemed: number = 0
  ): Promise<Sale> => {

    // Calculate Earned Points
    let pointsEarned = 0;
    if (settings.loyaltyProgram?.enabled && customerId) {
       const earnRate = settings.loyaltyProgram.earnRate || 10;
       pointsEarned = Math.floor(total / earnRate);
    }

    const payload = {
      items: items.map(i => ({
        productId: i.id,
        variantId: i.selectedVariantId,
        quantity: i.quantity,
        sellPrice: i.sellPrice
      })),
      total,
      subtotal,
      discountAmount,
      paymentMethod,
      amountReceived,
      change,
      customerId,
      pointsRedeemed,
      pointsEarned
    };

    // Client-side logic for consistency with persistence
    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items, total, subtotal, discountAmount,
      date: new Date().toISOString(),
      paymentMethod, amountReceived, change, customerId,
      customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined,
      status: 'completed',
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      remainingAmount: paymentMethod === 'credit' ? Math.max(0, total - (amountReceived || 0)) : 0,
      syncStatus: 'pending',
      pointsRedeemed,
      pointsEarned,
      userId: currentUser?.id,
      userName: currentUser?.name
    };

    setSales(prev => [newSale, ...prev]);

    // Update Inventory
    setProducts(prevProducts => prevProducts.map(product => {
      const cartItem = items.find(item => item.id === product.id);
      if (cartItem) {
        return { ...product, stock: product.stock - cartItem.quantity };
      }
      return product;
    }));

    // Update Customer Points
    if (customerId) {
        setCustomers(prev => prev.map(c => {
          if (c.id === customerId) {
              return { 
                ...c, 
                loyaltyPoints: Math.max(0, (c.loyaltyPoints || 0) - pointsRedeemed + pointsEarned) 
              };
          }
          return c;
        }));
    }

    return newSale;
  };

  const handleVoidSale = async (saleId: string) => {
     setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: 'voided' } : s));

     // Restore stock
     const saleToVoid = sales.find(s => s.id === saleId);
     if (saleToVoid) {
        setProducts(prevProducts => prevProducts.map(product => {
           const soldItem = saleToVoid.items.find(item => item.id === product.id);
           if (soldItem) {
              // Simple restoration (doesn't handle complex variant logic perfectly in this demo)
              return { ...product, stock: product.stock + soldItem.quantity };
           }
           return product;
        }));
     }
     logAction('SALE_VOID', `Voided sale ${saleId} (Persistent)`, 'high', saleId);
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
     setSales(prev => prev.map(s => {
        if (s.id === saleId) {
           return {
              ...s,
              paymentStatus: 'paid',
              remainingAmount: 0,
              amountReceived: (s.amountReceived || 0) + amount
           };
        }
        return s;
     }));
  };

  // --- CRUD Wrappers (Direct State Manipulation for Persistence) ---
  const addProduct = (p: Product) => setProducts(prev => [...prev, p]);
  const updateProduct = (p: Product) => setProducts(prev => prev.map(item => item.id === p.id ? p : item));
  const deleteProduct = (id: string) => setProducts(prev => prev.filter(item => item.id !== id));

  const addCustomer = (c: Customer) => setCustomers(prev => [...prev, c]);
  const updateCustomer = (c: Customer) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item));
  const deleteCustomer = (id: string) => setCustomers(prev => prev.filter(item => item.id !== id));

  const addCustomerLevel = (l: CustomerLevel) => setCustomerLevels(prev => [...prev, l]);
  const updateCustomerLevel = (l: CustomerLevel) => setCustomerLevels(prev => prev.map(item => item.id === l.id ? l : item));
  const deleteCustomerLevel = (id: string) => setCustomerLevels(prev => prev.filter(item => item.id !== id));

  const addUser = (u: User) => {
    setUsers(prev => [...prev, u]);
    logAction('USER_CREATE', `Created user ${u.name} (${u.role})`, 'medium', u.id);
  };
  const updateUser = (u: User) => setUsers(prev => prev.map(item => item.id === u.id ? u : item));
  const deleteUser = (id: string) => {
    setUsers(prev => prev.filter(item => item.id !== id));
    logAction('USER_DELETE', `Deleted user ID ${id}`, 'high', id);
  };

  const updateSettings = (s: SystemSettings) => {
    setSettingsState(s);
    logAction('SETTINGS_UPDATE', 'Updated system settings', 'medium');
  };

  const addUnit = (u: any) => setUnits(p => [...p, u]);
  const updateUnit = (u: any) => setUnits(p => p.map(x => x.id === u.id ? u : x));
  const deleteUnit = (id: string) => setUnits(p => p.filter(x => x.id !== id));

  const addCategory = (c: any) => setCategories(p => [...p, c]);
  const updateCategory = (c: any) => setCategories(p => p.map(x => x.id === c.id ? c : x));
  const deleteCategory = (id: string) => setCategories(p => p.filter(x => x.id !== id));

  const addBranch = (b: any) => setBranches(p => [...p, b]);
  const updateBranch = (b: any) => setBranches(p => p.map(x => x.id === b.id ? b : x));
  const deleteBranch = (id: string) => setBranches(p => p.filter(x => x.id !== id));

  const addPos = (pos: any) => setPosMachines(p => [...p, pos]);
  const updatePos = (pos: any) => setPosMachines(p => p.map(x => x.id === pos.id ? pos : x));
  const deletePos = (id: string) => setPosMachines(p => p.filter(x => x.id !== id));

  const addWarehouse = (w: any) => setWarehouses(p => [...p, w]);
  const updateWarehouse = (w: any) => setWarehouses(p => p.map(x => x.id === w.id ? w : x));
  const deleteWarehouse = (id: string) => setWarehouses(p => p.filter(x => x.id !== id));

  const addLocation = (l: any) => setLocations(p => [...p, l]);
  const updateLocation = (l: any) => setLocations(p => p.map(x => x.id === l.id ? l : x));
  const deleteLocation = (id: string) => setLocations(p => p.filter(x => x.id !== id));

  // --- Stock Docs ---
  const updateTransfer = (t: StockTransfer) => {
    if (transfers.find(x => x.id === t.id)) {
      setTransfers(prev => prev.map(item => item.id === t.id ? t : item));
    } else {
      setTransfers(prev => [t, ...prev]);
    }
  };
  const deleteTransfer = (id: string) => setTransfers(prev => prev.filter(item => item.id !== id));

  const updateCount = (c: StockCount) => {
    if (counts.find(x => x.id === c.id)) {
      setCounts(prev => prev.map(item => item.id === c.id ? c : item));
    } else {
      setCounts(prev => [c, ...prev]);
    }
  };
  const deleteCount = (id: string) => setCounts(prev => prev.filter(item => item.id !== id));

  const updateReservation = (r: StockReservation) => {
    if (reservations.find(x => x.id === r.id)) {
      setReservations(prev => prev.map(item => item.id === r.id ? r : item));
    } else {
      setReservations(prev => [r, ...prev]);
    }
  };
  const deleteReservation = (id: string) => setReservations(prev => prev.filter(item => item.id !== id));

  const updateReceipt = (r: StockReceipt) => {
    if (receipts.find(x => x.id === r.id)) {
      setReceipts(prev => prev.map(item => item.id === r.id ? r : item));
    } else {
      setReceipts(prev => [r, ...prev]);
    }
  };
  const deleteReceipt = (id: string) => setReceipts(prev => prev.filter(item => item.id !== id));

  const updateAdjustment = (a: StockAdjustment) => {
    if (adjustments.find(x => x.id === a.id)) {
      setAdjustments(prev => prev.map(item => item.id === a.id ? a : item));
    } else {
      setAdjustments(prev => [a, ...prev]);
    }
  };
  const deleteAdjustment = (id: string) => setAdjustments(prev => prev.filter(item => item.id !== id));

  // --- Status Change Logic (Simplified Client-side simulation) ---
  const handleStockStatusChange = (
    type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', 
    id: string, 
    status: DocumentStatus
  ) => {

    // Helper to update specific doc
    const updateDocStatus = (list: any[], setList: any) => {
       const doc = list.find(x => x.id === id);
       if (doc) {
          // If moving to Completed, update inventory
          if (status === 'Completed' && doc.status !== 'Completed') {
             // Basic inventory update logic
             if (type === 'transfer') {
               // Decrement Source, Increment Target
               // Simulation: We are updating products globally in this context
               // Real App: Update specific Warehouse Inventory
             } else if (type === 'receipt') {
               // Increment
               const items = doc.items;
               setProducts(prev => prev.map(p => {
                  const item = items.find((i: any) => i.productId === p.id);
                  if (item) return { ...p, stock: p.stock + item.quantity };
                  return p;
               }));
             } else if (type === 'adjustment') {
               // Increment (quantity can be negative)
               const items = doc.items;
               setProducts(prev => prev.map(p => {
                  const item = items.find((i: any) => i.productId === p.id);
                  if (item) return { ...p, stock: p.stock + item.quantity };
                  return p;
               }));
             } else if (type === 'count') {
               // Set absolute
               const items = doc.items;
               setProducts(prev => prev.map(p => {
                  const item = items.find((i: any) => i.productId === p.id);
                  if (item && item.countedQuantity !== undefined) return { ...p, stock: item.countedQuantity };
                  return p;
               }));
             }
          }
          setList((prev: any[]) => prev.map(item => item.id === id ? { ...item, status } : item));
          logAction('STOCK_APPROVE', `${type.toUpperCase()} ${doc.referenceNo} updated to ${status}`, 'medium', id);
       }
    };

    switch(type) {
      case 'transfer': updateDocStatus(transfers, setTransfers); break;
      case 'count': updateDocStatus(counts, setCounts); break;
      case 'reservation': updateDocStatus(reservations, setReservations); break;
      case 'receipt': updateDocStatus(receipts, setReceipts); break;
      case 'adjustment': updateDocStatus(adjustments, setAdjustments); break;
    }
  };

  const handleSyncOperation = (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
     // Mock Sync
     const newLog: SyncLog = {
        id: `sync-${Date.now()}`,
        timestamp: new Date().toISOString(),
        type,
        status: 'Success',
        details: 'Simulated sync completed successfully.',
        durationMs: Math.floor(Math.random() * 1000) + 200
     };
     setSyncLogs(prev => [newLog, ...prev]);
  };

  // --- Shifts ---
  const startShift = (branchId: string, startCash: number, notes?: string) => {
    if (!currentUser) return;
    const newShift: Shift = {
      id: `sh-${Date.now()}`,
      userId: currentUser.id,
      branchId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open'
    };
    setShifts(prev => [newShift, ...prev]);
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
    setShifts(prev => prev.map(s => {
      if (s.id === shiftId) {
        return {
          ...s,
          endTime: new Date().toISOString(),
          endCash,
          notes: notes ? (s.notes ? s.notes + '\n' + notes : notes) : s.notes,
          status: 'Closed'
        };
      }
      return s;
    }));
  };

  const addShiftSchedule = (s: ShiftSchedule) => setShiftSchedules(prev => [...prev, s]);
  const deleteShiftSchedule = (id: string) => setShiftSchedules(prev => prev.filter(x => x.id !== id));

  // --- Promotions ---
  const addPromotion = (p: Promotion) => setPromotions(prev => [...prev, p]);
  const updatePromotion = (p: Promotion) => setPromotions(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePromotion = (id: string) => setPromotions(prev => prev.filter(item => item.id !== id));

  const value: GlobalContextType = {
    currentUser, setCurrentUser, users, products, sales, units, categories, branches, posMachines, warehouses, locations,
    transfers, counts, reservations, receipts, adjustments, syncLogs, customers, customerLevels, shifts, shiftSchedules, promotions, settings, isLoading,
    notifications, auditLogs,
    processSale, addProduct, updateProduct, deleteProduct, addUnit, updateUnit, deleteUnit,
    addCategory, updateCategory, deleteCategory, addBranch, updateBranch, deleteBranch,
    addPos, updatePos, deletePos, addWarehouse, updateWarehouse, deleteWarehouse,
    addLocation, updateLocation, deleteLocation, addUser, updateUser, deleteUser,
    addCustomer, updateCustomer, deleteCustomer, addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,
    updateTransfer, deleteTransfer, updateCount, deleteCount, updateReservation, deleteReservation,
    updateReceipt, deleteReceipt, updateAdjustment, deleteAdjustment,
    handleStockStatusChange, handleSyncOperation,
    startShift, endShift, addShiftSchedule, deleteShiftSchedule,
    addPromotion, updatePromotion, deletePromotion,
    updateSettings,
    settleSaleDebt, handleVoidSale,
    t, formatPrice,
    addNotification, markNotificationRead, clearAllNotifications,
    restoreSystemData, logAction
  };

  return (
    <GlobalContext.Provider value={value}>
      {children}
    </GlobalContext.Provider>
  );
};

import React, { useState, useMemo } from 'react';
import { Sale, Product, ProductVariant } from '../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend, LineChart, Line, AreaChart, Area
} from 'recharts';
import { 
  Download, 
  Calendar, 
  TrendingUp, 
  DollarSign, 
  Package, 
  AlertTriangle,
  FileText,
  Filter,
  Users,
  Clock,
  Award,
  Activity
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

interface ReportsManagementProps {
  sales: Sale[];
  products: Product[];
}

type ReportType = 'sales' | 'inventory' | 'low-stock' | 'staff' | 'hourly';

export const ReportsManagement: React.FC<ReportsManagementProps> = ({ sales, products }) => {
  const { formatPrice, t, settings } = useGlobal();
  const [activeTab, setActiveTab] = useState<ReportType>('sales');

  // Date Filters
  const [startDate, setStartDate] = useState(new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);

  // --- Filtered Sales Helper ---
  const filteredSales = useMemo(() => {
    const start = new Date(startDate);
    const end = new Date(endDate);
    end.setHours(23, 59, 59, 999);

    return sales.filter(s => {
      const d = new Date(s.date);
      return d >= start && d <= end && s.status !== 'voided';
    });
  }, [sales, startDate, endDate]);

  // --- Sales Report Logic ---
  const salesReportData = useMemo(() => {
    // Group by Day
    const dailyData = new Map<string, { date: string; revenue: number; profit: number; count: number }>();
    let totalRevenue = 0;
    let totalProfit = 0;
    let totalCost = 0;

    filteredSales.forEach(sale => {
      const dateKey = new Date(sale.date).toLocaleDateString('en-US');

      let saleCost = 0;
      sale.items.forEach(item => {
         // Find original product to get Cost Price
         const product = products.find(p => p.id === item.id);
         let unitCost = product?.costPrice || 0;

         // If variant selected, try to find specific variant cost
         if (item.selectedVariantId && product?.variants) {
            const variant = product.variants.find(v => v.id === item.selectedVariantId);
            if (variant && variant.costPrice) {
               unitCost = variant.costPrice;
            } else if (variant && variant.conversionFactor) {
               // Fallback: Calculate from base cost
               unitCost = (product?.costPrice || 0) / variant.conversionFactor;
            }
         }

         saleCost += unitCost * item.quantity;
      });

      const saleProfit = sale.total - saleCost;
      totalRevenue += sale.total;
      totalCost += saleCost;
      totalProfit += saleProfit;

      const existing = dailyData.get(dateKey) || { date: dateKey, revenue: 0, profit: 0, count: 0 };
      existing.revenue += sale.total;
      existing.profit += saleProfit;
      existing.count += 1;
      dailyData.set(dateKey, existing);
    });

    const chartData = Array.from(dailyData.values()).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    return { totalRevenue, totalCost, totalProfit, chartData };
  }, [filteredSales, products]);

  // --- Inventory Report Logic ---
  const inventoryReportData = useMemo(() => {
    let totalStockValue = 0; // At Cost
    let totalRetailValue = 0; // At Selling Price
    let totalItems = 0;

    const reportItems = products.map(p => {
      const stockVal = p.stock * (p.costPrice || 0);
      const retailVal = p.stock * p.price;

      totalStockValue += stockVal;
      totalRetailValue += retailVal;
      totalItems += p.stock;

      return {
        ...p,
        stockValue: stockVal,
        retailValue: retailVal,
        margin: p.costPrice ? ((p.price - p.costPrice) / p.price) * 100 : 100
      };
    });

    return { reportItems, totalStockValue, totalRetailValue, totalItems };
  }, [products]);

  // --- Staff Performance Logic ---
  const staffReportData = useMemo(() => {
    const staffMap = new Map<string, { id: string; name: string; revenue: number; count: number }>();

    filteredSales.forEach(s => {
        const uid = s.userId || 'unknown';
        const uName = s.userName || 'Unknown Staff';

        const existing = staffMap.get(uid) || { id: uid, name: uName, revenue: 0, count: 0 };
        existing.revenue += s.total;
        existing.count += 1;
        staffMap.set(uid, existing);
    });

    return Array.from(staffMap.values()).sort((a, b) => b.revenue - a.revenue);
  }, [filteredSales]);

  // --- Hourly Heatmap Logic ---
  const hourlyReportData = useMemo(() => {
    const hours = Array(24).fill(0).map((_, i) => ({ 
        hour: i, 
        label: `${String(i).padStart(2, '0')}:00`, 
        revenue: 0, 
        count: 0 
    }));

    filteredSales.forEach(s => {
        const h = new Date(s.date).getHours();
        if (hours[h]) {
            hours[h].revenue += s.total;
            hours[h].count += 1;
        }
    });

    return hours;
  }, [filteredSales]);

  // --- CSV Export Logic ---
  const handleExport = () => {
    let csvContent = "data:text/csv;charset=utf-8,";

    if (activeTab === 'sales') {
      csvContent += "Date,Invoice ID,Customer,Items,Total,Profit,Payment Method\n";
      filteredSales.forEach(s => {
        let cost = 0;
        s.items.forEach(i => {
           const p = products.find(prod => prod.id === i.id);
           cost += (p?.costPrice || 0) * i.quantity;
        });
        const profit = s.total - cost;
        csvContent += `${new Date(s.date).toLocaleDateString()},${s.id},"${s.customerName || 'Walk-in'}",${s.items.length},${s.total},${profit},${s.paymentMethod}\n`;
      });
    } else if (activeTab === 'inventory' || activeTab === 'low-stock') {
      csvContent += "Name,SKU,Category,Stock,Unit,Cost Price,Sell Price,Total Cost Value,Total Retail Value\n";
      const targetList = activeTab === 'low-stock' 
        ? inventoryReportData.reportItems.filter(p => p.stock <= (p.minStock || 0))
        : inventoryReportData.reportItems;

      targetList.forEach(p => {
        csvContent += `"${p.name}",${p.sku},${p.category},${p.stock},${p.unit},${p.costPrice || 0},${p.price},${p.stockValue},${p.retailValue}\n`;
      });
    } else if (activeTab === 'staff') {
      csvContent += "Staff Name,Transactions,Revenue,Avg Ticket\n";
      staffReportData.forEach(s => {
        csvContent += `"${s.name}",${s.count},${s.revenue},${s.count > 0 ? s.revenue/s.count : 0}\n`;
      });
    }

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `${activeTab}_report_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 h-full flex flex-col pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Reports & Analytics</h2>
          <p className="text-slate-500">Business intelligence and financial insights.</p>
        </div>
        <button 
          onClick={handleExport}
          className="flex items-center justify-center px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors font-medium shadow-sm"
        >
          <Download className="w-4 h-4 mr-2" />
          Export CSV
        </button>
      </div>

      {/* Tabs - Scrollable */}
      <div className="overflow-x-auto pb-2 -mx-4 px-4 md:mx-0 md:px-0 md:pb-0 scrollbar-hide">
        <div className="flex space-x-1 bg-slate-100 p-1 rounded-lg w-fit min-w-max">
          <button
            onClick={() => setActiveTab('sales')}
            className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'sales' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <TrendingUp className="w-4 h-4 mr-2" /> Sales
          </button>
          <button
            onClick={() => setActiveTab('staff')}
            className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'staff' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <Users className="w-4 h-4 mr-2" /> Staff
          </button>
          <button
            onClick={() => setActiveTab('hourly')}
            className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'hourly' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <Clock className="w-4 h-4 mr-2" /> Hourly
          </button>
          <button
            onClick={() => setActiveTab('inventory')}
            className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'inventory' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <Package className="w-4 h-4 mr-2" /> Valuation
          </button>
          <button
            onClick={() => setActiveTab('low-stock')}
            className={`flex items-center px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'low-stock' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <AlertTriangle className="w-4 h-4 mr-2" /> Low Stock
          </button>
        </div>
      </div>

      {/* Date Filters (Hidden for Inventory/Low Stock) */}
      {(activeTab === 'sales' || activeTab === 'staff' || activeTab === 'hourly') && (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-4 flex-wrap animate-fade-in">
           <div className="flex items-center space-x-2">
              <Calendar className="w-5 h-5 text-slate-400" />
              <input 
                type="date" 
                value={startDate} 
                onChange={e => setStartDate(e.target.value)} 
                className="px-3 py-2 border border-slate-200 rounded-lg text-sm"
              />
              <span className="text-slate-400">-</span>
              <input 
                type="date" 
                value={endDate} 
                onChange={e => setEndDate(e.target.value)} 
                className="px-3 py-2 border border-slate-200 rounded-lg text-sm"
              />
           </div>
        </div>
      )}

      {/* SALES REPORT */}
      {activeTab === 'sales' && (
        <div className="space-y-6 animate-fade-in">
          {/* Metrics */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
             <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                <p className="text-sm text-slate-500 font-medium mb-1">Total Revenue</p>
                <h3 className="text-3xl font-bold text-slate-800">{formatPrice(salesReportData.totalRevenue)}</h3>
             </div>
             <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                <p className="text-sm text-slate-500 font-medium mb-1">Total Cost (COGS)</p>
                <h3 className="text-3xl font-bold text-slate-700">{formatPrice(salesReportData.totalCost)}</h3>
             </div>
             <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                <p className="text-sm text-slate-500 font-medium mb-1">Gross Profit</p>
                <h3 className={`text-3xl font-bold ${salesReportData.totalProfit >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                   {formatPrice(salesReportData.totalProfit)}
                </h3>
                <p className="text-xs text-slate-400 mt-1">Margin: {salesReportData.totalRevenue ? ((salesReportData.totalProfit / salesReportData.totalRevenue) * 100).toFixed(1) : 0}%</p>
             </div>
          </div>

          {/* Chart */}
          <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm h-[400px]">
             <h4 className="font-bold text-slate-700 mb-6">Revenue vs Profit</h4>
             <ResponsiveContainer width="100%" height="90%">
                <BarChart data={salesReportData.chartData}>
                   <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                   <XAxis dataKey="date" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
                   <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(val) => `$${val}`} />
                   <Tooltip 
                      contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                      formatter={(val: number) => formatPrice(val)}
                   />
                   <Legend />
                   <Bar dataKey="revenue" name="Revenue" fill="#0ea5e9" radius={[4, 4, 0, 0]} />
                   <Bar dataKey="profit" name="Profit" fill="#22c55e" radius={[4, 4, 0, 0]} />
                </BarChart>
             </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* STAFF REPORT */}
      {activeTab === 'staff' && (
        <div className="space-y-6 animate-fade-in">
           <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <h4 className="font-bold text-slate-800 mb-6 flex items-center">
                 <Award className="w-5 h-5 mr-2 text-yellow-500" />
                 Top Performing Staff
              </h4>
              <div className="overflow-x-auto">
                 <table className="w-full text-left">
                    <thead className="bg-slate-50 text-xs text-slate-500 uppercase font-semibold">
                       <tr>
                          <th className="px-6 py-4 rounded-l-lg">Rank</th>
                          <th className="px-6 py-4">Staff Name</th>
                          <th className="px-6 py-4 text-center">Transactions</th>
                          <th className="px-6 py-4 text-right">Avg. Ticket</th>
                          <th className="px-6 py-4 text-right rounded-r-lg">Total Revenue</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {staffReportData.map((staff, idx) => (
                          <tr key={staff.id} className="hover:bg-slate-50 transition-colors">
                             <td className="px-6 py-4">
                                <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${idx === 0 ? 'bg-yellow-100 text-yellow-700' : idx === 1 ? 'bg-slate-200 text-slate-700' : idx === 2 ? 'bg-orange-100 text-orange-700' : 'bg-slate-50 text-slate-500'}`}>
                                   {idx + 1}
                                </div>
                             </td>
                             <td className="px-6 py-4 font-medium text-slate-700">{staff.name}</td>
                             <td className="px-6 py-4 text-center text-slate-600">{staff.count}</td>
                             <td className="px-6 py-4 text-right text-slate-600 font-mono">
                                {formatPrice(staff.count > 0 ? staff.revenue / staff.count : 0)}
                             </td>
                             <td className="px-6 py-4 text-right font-bold text-green-600">
                                {formatPrice(staff.revenue)}
                             </td>
                          </tr>
                       ))}
                       {staffReportData.length === 0 && (
                          <tr><td colSpan={5} className="text-center py-8 text-slate-400">No data available for this period.</td></tr>
                       )}
                    </tbody>
                 </table>
              </div>
           </div>
        </div>
      )}

      {/* HOURLY REPORT */}
      {activeTab === 'hourly' && (
         <div className="space-y-6 animate-fade-in">
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm h-[500px]">
               <h4 className="font-bold text-slate-800 mb-2 flex items-center">
                  <Activity className="w-5 h-5 mr-2 text-blue-500" />
                  Hourly Sales Distribution (Traffic)
               </h4>
               <p className="text-xs text-slate-500 mb-6">Aggregated data for the selected period.</p>

               <ResponsiveContainer width="100%" height="90%">
                  <AreaChart data={hourlyReportData}>
                     <defs>
                        <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                           <stop offset="5%" stopColor="#8884d8" stopOpacity={0.8}/>
                           <stop offset="95%" stopColor="#8884d8" stopOpacity={0}/>
                        </linearGradient>
                     </defs>
                     <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                     <XAxis dataKey="label" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
                     <YAxis yAxisId="left" stroke="#8884d8" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(val) => `$${val}`} />
                     <YAxis yAxisId="right" orientation="right" stroke="#82ca9d" fontSize={12} tickLine={false} axisLine={false} />
                     <Tooltip 
                        contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                        formatter={(val: number, name: string) => [name === 'revenue' ? formatPrice(val) : val, name === 'revenue' ? 'Revenue' : 'Transactions']}
                     />
                     <Legend />
                     <Area yAxisId="left" type="monotone" dataKey="revenue" name="Revenue" stroke="#8884d8" fillOpacity={1} fill="url(#colorRevenue)" />
                     <Line yAxisId="right" type="monotone" dataKey="count" name="Transactions" stroke="#82ca9d" strokeWidth={2} dot={{r: 4}} />
                  </AreaChart>
               </ResponsiveContainer>
            </div>
         </div>
      )}

      {/* INVENTORY REPORT */}
      {(activeTab === 'inventory' || activeTab === 'low-stock') && (
         <div className="space-y-6 animate-fade-in">
            {activeTab === 'inventory' && (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col">
                     <div className="flex justify-between items-start mb-4">
                        <div>
                           <p className="text-sm text-slate-500 font-medium">Inventory Valuation (Cost)</p>
                           <h3 className="text-3xl font-bold text-slate-800">{formatPrice(inventoryReportData.totalStockValue)}</h3>
                        </div>
                        <div className="p-3 bg-blue-50 rounded-lg text-blue-600">
                           <DollarSign className="w-6 h-6" />
                        </div>
                     </div>
                     <p className="text-xs text-slate-400">Total value of assets based on cost price.</p>
                  </div>
                  <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col">
                     <div className="flex justify-between items-start mb-4">
                        <div>
                           <p className="text-sm text-slate-500 font-medium">Potential Retail Value</p>
                           <h3 className="text-3xl font-bold text-green-600">{formatPrice(inventoryReportData.totalRetailValue)}</h3>
                        </div>
                        <div className="p-3 bg-green-50 rounded-lg text-green-600">
                           <Users className="w-6 h-6" />
                        </div>
                     </div>
                     <p className="text-xs text-slate-400">Projected revenue if all stock is sold.</p>
                  </div>
               </div>
            )}

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
               <div className="p-4 border-b border-slate-100 bg-slate-50">
                  <h3 className="font-bold text-slate-700">
                     {activeTab === 'low-stock' ? 'Low Stock Alerts' : 'Detailed Inventory Asset Report'}
                  </h3>
               </div>
               <div className="overflow-x-auto">
                  <table className="w-full text-left">
                     <thead className="bg-slate-50 text-xs text-slate-500 uppercase font-semibold">
                        <tr>
                           <th className="px-6 py-3">Product Name</th>
                           <th className="px-6 py-3 text-right">Stock Level</th>
                           <th className="px-6 py-3 text-right">Cost Price</th>
                           <th className="px-6 py-3 text-right">Selling Price</th>
                           <th className="px-6 py-3 text-right">Total Asset Value</th>
                           {activeTab === 'inventory' && <th className="px-6 py-3 text-right">Margin</th>}
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-100 text-sm">
                        {inventoryReportData.reportItems
                           .filter(p => activeTab === 'inventory' ? true : p.stock <= (p.minStock || 0))
                           .map((item) => (
                           <tr key={item.id} className="hover:bg-slate-50">
                              <td className="px-6 py-4">
                                 <div className="font-medium text-slate-800">{item.name}</div>
                                 <div className="text-xs text-slate-500">{item.sku}</div>
                              </td>
                              <td className="px-6 py-4 text-right">
                                 <span className={`font-bold ${item.stock <= (item.minStock || 0) ? 'text-red-600' : 'text-slate-700'}`}>
                                    {item.stock} {item.unit}
                                 </span>
                              </td>
                              <td className="px-6 py-4 text-right font-mono text-slate-600">{formatPrice(item.costPrice || 0)}</td>
                              <td className="px-6 py-4 text-right font-mono text-slate-600">{formatPrice(item.price)}</td>
                              <td className="px-6 py-4 text-right font-bold text-slate-800">{formatPrice(item.stockValue)}</td>
                              {activeTab === 'inventory' && (
                                 <td className="px-6 py-4 text-right">
                                    <span className={`px-2 py-1 rounded text-xs font-bold ${item.margin > 30 ? 'bg-green-100 text-green-700' : item.margin > 15 ? 'bg-yellow-100 text-yellow-700' : 'bg-red-100 text-red-700'}`}>
                                       {item.margin.toFixed(1)}%
                                    </span>
                                 </td>
                              )}
                           </tr>
                        ))}
                     </tbody>
                  </table>
               </div>
            </div>
         </div>
      )}
    </div>
  );
};

export enum Category {
  CEMENT = 'Cement & Concrete',
  STEEL = 'Steel & Metal',
  WOOD = 'Wood & Lumber',
  PAINT = 'Paints & Finishes',
  TOOLS = 'Tools & Hardware',
  PLUMBING = 'Plumbing',
  ELECTRICAL = 'Electrical',
  CONSUMABLES = 'General Consumables'
}

export type UnitCategory = 'Weight' | 'Length' | 'Quantity';

export interface UnitDefinition {
  id: string;
  name: string;      // e.g. Kilogram
  symbol: string;    // e.g. kg
  category: UnitCategory;
  baseFactor: number; // 1 for base unit (e.g. g), 1000 for kg
  isBase: boolean;   // True if this is the reference unit
}

export interface CategoryItem {
  id: string;
  name: string;
  parentId: string | null; // null for root categories
  description?: string;
}

export interface ProductVariant {
  id: string;
  name: string;      // e.g., 'Piece', 'Small', 'Red' (Unit Name or Variant Name)
  code: string;      // SKU/Code for the variant
  barcode: string;   // Barcode for the variant
  conversionFactor: number; // How many variants in the main unit
  price: number;     // Price per variant
  costPrice?: number; // Cost price per variant
  color?: string;    // New: Color specification (e.g., 'Red', '#FF0000')
  size?: string;     // New: Size specification (e.g., 'XL', '10mm')
}

export interface ProductInventory {
  warehouseId: string;
  quantity: number;
}

export interface BranchPrice {
  branchId: string;
  price: number;
}

export interface ProductPhysical {
  weight?: number; // kg
  width?: number;  // cm
  height?: number; // cm
  depth?: number;  // cm (length)
}

export interface Product {
  id: string;
  name: string;
  category: Category | string; 
  price: number;     // Base Sell Price (Global)
  costPrice?: number; // Base Cost Price (For Profit Calc)
  branchPrices?: BranchPrice[]; // Overrides per branch
  stock: number;     // Stock count in MAIN units (Aggregate Total)
  minStock?: number; // Minimum stock threshold for alerts
  warehouseInventory?: ProductInventory[]; // Breakdown by warehouse
  unit: string;      // Name of the MAIN unit (e.g., 'bag', 'box')
  physical?: ProductPhysical; // New: Physical attributes
  imageUrl?: string;
  sku: string;       // SKU of MAIN unit
  barcode: string;   // Barcode of MAIN unit
  variants?: ProductVariant[]; // List of sub-products/variants
}

export interface CartItem extends Product {
  quantity: number;
  // Handling multi-unit/variant logic
  selectedVariantId?: string; // null if main unit, string if variant
  sellPrice: number; 
  sellUnit: string;  
  sellConversionFactor: number; // 1 for main, X for variant
}

export interface Sale {
  id: string;
  items: CartItem[];
  subtotal?: number; // Raw total before discount/tax
  discountAmount?: number; // Deduction amount
  total: number; // Final payable amount
  date: string;
  paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit';
  paymentStatus: 'paid' | 'unpaid' | 'partial'; // Track debt status
  amountReceived?: number; // Amount given by customer
  change?: number; // Change returned
  remainingAmount?: number; // Amount left to pay (for credit/partial)
  status: 'completed' | 'voided'; // Order status
  syncStatus?: 'synced' | 'pending' | 'failed'; // Track sync state
  customerId?: string; // Link to customer
  customerName?: string; // Snapshot of name
  pointsRedeemed?: number; // Points used
  pointsEarned?: number; // Points gained
  userId?: string; // ID of the staff who processed the sale
  userName?: string; // Name of the staff who processed the sale
}

export interface EstimateRequest {
  query: string;
}

export interface EstimateResultItem {
  productName: string;
  estimatedQuantity: number;
  unit: string;
  reasoning: string;
  matchedProductId?: string; // If found in inventory
}

// --- AI Inventory & Business Analysis Types ---
export interface ReorderSuggestion {
  productId: string;
  productName: string;
  currentStock: number;
  suggestedReorderQty: number;
  priority: 'High' | 'Medium' | 'Low';
  reasoning: string;
}

export interface NewProductSuggestion {
  name: string;
  categoryName: string;
  estimatedPrice: number;
  reasoning: string;
  suggestedUnit: string;
}

export interface BundleSuggestion {
  bundleName: string;
  components: string[];
  estimatedPrice: number;
  reasoning: string;
  targetAudience: string;
}

export interface InventoryAnalysisResult {
  reorders: ReorderSuggestion[];
  newProducts: NewProductSuggestion[];
  bundles: BundleSuggestion[];
}

export interface BusinessInsight {
  summary: string;
  trendDirection: 'up' | 'down' | 'stable';
  actionItems: string[];
  predictedRevenueNextWeek: number;
  topPerformingCategory: string;
}

export interface Branch {
  id: string;
  name: string;
  address: string;
  phone: string;
  manager: string;
  isActive: boolean;
}

export interface PosMachine {
  id: string;
  branchId: string;
  machineNumber: string; // e.g., POS-01
  status: 'active' | 'maintenance' | 'inactive';
  lastActive?: string;
}

export interface Warehouse {
  id: string;
  branchId: string;
  name: string;
  code: string; // e.g., WH-01
  type: 'General' | 'Cold Storage' | 'Hazardous' | 'Showroom';
  description?: string;
}

export interface StorageLocation {
  id: string;
  warehouseId: string;
  zone: string;   // e.g., Zone A
  rack: string;   // e.g., Rack 01
  shelf: string;  // e.g., Shelf 03 (Level)
  bin: string;    // e.g., Bin B (Slot)
  fullCode: string; // Helper: A-01-03-B
  type?: 'Pallet' | 'Shelf' | 'Floor';
}

// --- Customer Types ---
export interface CustomerLevel {
  id: string;
  name: string;
  discountPercentage: number;
  color?: string;
}

export interface Customer {
  id: string;
  code: string; // Membership ID or Code
  name: string;
  phone: string;
  taxId?: string;
  address?: string;
  email?: string;
  loyaltyPoints: number;
  notes?: string;
  levelId?: string;
  level?: CustomerLevel;
}

// --- Stock Management Types ---

export type DocumentStatus = 'Draft' | 'Approved' | 'Completed' | 'Cancelled';

export interface StockItem {
  productId: string;
  variantId?: string; // Optional: if specific variant
  productName: string;
  unit: string;
  quantity: number;
  note?: string;
}

// 1. Transfer Request
export interface StockTransfer {
  id: string;
  date: string;
  sourceWarehouseId: string;
  targetWarehouseId: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 2. Stock Count
export interface StockCountItem extends StockItem {
  systemQuantity: number; // Snapshot of system stock
  countedQuantity: number; // Actual count
  diff: number; // Calculated diff
}

export interface StockCount {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockCountItem[];
  referenceNo: string;
  counterName: string; // Who counted
  reason: string; // Mandatory reason for adjustment
}

// 3. Stock Reservation
export interface StockReservation {
  id: string;
  date: string;
  expiryDate: string;
  warehouseId: string;
  customerName: string;
  status: DocumentStatus;
  items: StockItem[];
  referenceNo: string;
}

// 4. Goods Receipt
export interface StockReceiptItem extends StockItem {
  costPrice: number; // Cost per unit
}

export interface StockReceipt {
  id: string;
  date: string;
  warehouseId: string;
  vendorName: string;
  vendorInvoiceNo?: string;
  status: DocumentStatus;
  items: StockReceiptItem[];
  referenceNo: string;
  totalCost: number;
}

// 5. Stock Adjustment
export interface StockAdjustment {
  id: string;
  date: string;
  warehouseId: string;
  status: DocumentStatus;
  items: StockItem[]; // Quantity can be negative (decrease) or positive (increase)
  referenceNo: string;
  reason: string; // Mandatory
}

// --- Sync Types ---
export interface SyncLog {
  id: string;
  timestamp: string;
  type: 'Auto' | 'Manual' | 'Push' | 'Pull';
  status: 'Success' | 'Failed' | 'Partial';
  details: string; // e.g., "5 Sales uploaded, 0 Products updated"
  durationMs: number;
}

// --- User & Roles ---

export type UserRole = 'Admin' | 'Manager' | 'Staff' | 'Cashier';

export interface User {
  id: string;
  username: string;
  password?: string; // Added for login
  email?: string;    // Optional
  name: string;
  role: UserRole;
  avatarUrl?: string;
  department?: string;
  branchId?: string;
}

// --- Shift Management ---
export interface Shift {
  id: string;
  userId: string;
  branchId: string;
  startTime: string;
  endTime?: string;
  startCash: number;
  endCash?: number;
  notes?: string;
  status: 'Open' | 'Closed';
  userName?: string; // Optional helper
  branchName?: string; // Optional helper
}

export interface ShiftSchedule {
  id: string;
  userId: string;
  branchId: string;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:mm (24hr)
  endTime: string; // HH:mm (24hr)
  note?: string;
}

// --- Settings & Promotions ---
export type Language = 'en' | 'th' | 'lo';

export interface Promotion {
  id: string;
  title: string;
  imageUrl: string;
  isActive: boolean;
  order?: number;
  startDate?: string; // ISO Date
  endDate?: string;   // ISO Date
}

export interface LocalDatabaseConfig {
  enabled: boolean;
  type: 'postgresql' | 'sqlite' | 'mysql';
  host: string;
  port: string;
  databaseName: string;
  username: string;
  password: string;
}

export interface TaxSettings {
  enabled: boolean;             
  rate: number;                 
  calculationMode: 'included' | 'excluded'; 
  displayOnReceipt: boolean;    
}

export interface CustomerDisplaySettings {
  enabled: boolean;
  welcomeMessage: string;
  promotionInterval: number; // Seconds
}

export interface SystemSettings {
  // Company Info
  companyName: string;
  taxId: string;
  address: string;
  phone: string;
  monthlyTarget: number; // New: Revenue target

  // Localization
  language: Language;
  currencySymbol: string;

  // Interface
  defaultItemsPerPage: number;

  // Tax / VAT
  tax: TaxSettings;

  // Customer Display
  customerDisplay: CustomerDisplaySettings;

  // Loyalty Settings
  loyaltyProgram: {
    enabled: boolean;
    earnRate: number; // Amount to spend to earn 1 point (e.g. $10 = 1 point)
    redeemRate: number; // Points needed for 1 currency unit discount (e.g. 100 points = $1)
  };

  // Receipt & Print
  receiptHeader: string;
  receiptFooter: string;
  receiptLogoUrl?: string;
  receiptQrCodeUrl?: string; // Bank QR Code for receipt
  receiptPaperSize: '58mm' | '80mm' | 'A4';
  receiptAutoPrint: boolean;
  receiptShowTaxId: boolean;
  receiptShowCashier: boolean;
  receiptCopies: number;

  // Device Configuration
  currentBranchId?: string;
  currentPosId?: string;
  deviceRole?: 'Master' | 'Slave';

  // Local Database (For Slave offline mode)
  localDatabase?: LocalDatabaseConfig;

  // Synchronization (Master/Slave)
  masterApiUrl?: string; // e.g., http://192.168.1.100:3000
  autoSyncInterval?: number; // In minutes, 0 for manual
  lastSyncTime?: string;
}

// --- Notifications & Audit ---
export interface AppNotification {
  id: string;
  title: string;
  message: string;
  type: 'info' | 'warning' | 'error' | 'success';
  timestamp: string;
  read: boolean;
  link?: string; // Optional link to navigate to (e.g. '/approvals')
}

export type AuditAction = 
  | 'SALE_VOID' 
  | 'USER_CREATE' 
  | 'USER_DELETE' 
  | 'SETTINGS_UPDATE' 
  | 'STOCK_APPROVE' 
  | 'STOCK_REJECT'
  | 'SHIFT_OVERRIDE'
  | 'LOGIN_FAILED';

export interface AuditLog {
