import { GoogleGenAI, Type } from "@google/genai";
import { EstimateResultItem, Product, InventoryAnalysisResult, Sale, BusinessInsight } from "../types";

const API_KEY = process.env.API_KEY || '';

// Initialize the client only if the key is present to avoid runtime crashes on empty keys
const ai = API_KEY ? new GoogleGenAI({ apiKey: API_KEY }) : null;

export const getConstructionEstimate = async (
  query: string, 
  inventory: Product[]
): Promise<EstimateResultItem[]> => {
  if (!ai) {
    console.warn("Gemini API Key is missing.");
    return [
      {
        productName: "System Error",
        estimatedQuantity: 0,
        unit: "N/A",
        reasoning: "API Key not configured. Please check metadata or environment."
      }
    ];
  }

  const inventoryList = inventory.map(p => `${p.name} (ID: ${p.id}, Unit: ${p.unit})`).join(', ');

  const systemInstruction = `
    You are an expert construction estimator and civil engineer. 
    Your goal is to analyze a user's construction project request (e.g., "build a 3x3m brick wall") and calculate the required materials.

    You have access to the following current store inventory:
    [${inventoryList}]

    Rules:
    1. Estimate the quantities realistically including a 10% waste margin.
    2. Try to match the materials to the 'matchedProductId' from the provided inventory list if possible.
    3. If a required item is NOT in the inventory, suggest it anyway but leave 'matchedProductId' null.
    4. Provide brief reasoning for the calculation.
    5. Return the result strictly as a JSON array.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: query,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              productName: { type: Type.STRING },
              estimatedQuantity: { type: Type.NUMBER },
              unit: { type: Type.STRING },
              reasoning: { type: Type.STRING },
              matchedProductId: { type: Type.STRING, nullable: true },
            },
            required: ['productName', 'estimatedQuantity', 'unit', 'reasoning']
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as EstimateResultItem[];
    }
    return [];
  } catch (error) {
    console.error("Gemini Estimate Error:", error);
    throw error;
  }
};

export const analyzeInventory = async (products: Product[], sales: Sale[]): Promise<InventoryAnalysisResult | null> => {
  if (!ai) {
    console.warn("Gemini API Key is missing.");
    return null;
  }

  // Create a condensed view of inventory
  const productSummary = products.map(p => ({
    id: p.id,
    name: p.name,
    stock: p.stock,
    min: p.minStock || 20,
    unit: p.unit,
    category: p.category
  }));

  // Create a summary of sales transactions (condensed to save tokens)
  // We only send the last 20 transactions to analyze recent trends
  const recentSales = sales.slice(0, 20).map(s => ({
    items: s.items.map(i => i.name)
  }));

  const systemInstruction = `
    You are an intelligent retail inventory manager for a construction materials store.

    Data Provided:
    1. Current Product Inventory (Stock levels).
    2. Recent Sales Transactions (Items bought together).

    Your tasks:
    1. REORDERS: Identify items critically low (stock <= minStock) and suggest reorder qty.
    2. NEW PRODUCTS: Suggest NEW products we should add based on gaps in our catalog.
    3. BUNDLES: Analyze the sales transactions. If certain items are frequently bought together (e.g. Cement + Sand), suggest a "Bundle" or "Combo Pack" product we could create to simplify purchasing or offer a deal.

    Return the result strictly as a JSON object with 'reorders', 'newProducts', and 'bundles' arrays.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: JSON.stringify({ inventory: productSummary, sales: recentSales }),
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            reorders: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  productId: { type: Type.STRING },
                  productName: { type: Type.STRING },
                  currentStock: { type: Type.NUMBER },
                  suggestedReorderQty: { type: Type.NUMBER },
                  priority: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] },
                  reasoning: { type: Type.STRING }
                }
              }
            },
            newProducts: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  categoryName: { type: Type.STRING },
                  estimatedPrice: { type: Type.NUMBER },
                  suggestedUnit: { type: Type.STRING },
                  reasoning: { type: Type.STRING }
                }
              }
            },
            bundles: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  bundleName: { type: Type.STRING },
                  components: { type: Type.ARRAY, items: { type: Type.STRING } },
                  estimatedPrice: { type: Type.NUMBER },
                  reasoning: { type: Type.STRING },
                  targetAudience: { type: Type.STRING }
                }
              }
            }
          },
          required: ['reorders', 'newProducts', 'bundles']
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as InventoryAnalysisResult;
    }
    return null;
  } catch (error) {
    console.error("Gemini Inventory Analysis Error:", error);
    return null;
  }
};

export const generateBusinessInsights = async (sales: Sale[], products: Product[]): Promise<BusinessInsight | null> => {
  if (!ai) {
    // Return dummy data if no key, ensuring UI works
    return {
      summary: "Simulated Insight: Revenue is trending positively. Consider restocking fast-moving items like Cement.",
      trendDirection: "up",
      actionItems: ["Restock Cement", "Review pricing for Red Brick", "Promote slow-moving Tiles"],
      predictedRevenueNextWeek: 12500,
      topPerformingCategory: "Cement & Concrete"
    };
  }

  // Summarize daily sales for the last 30 days
  const dailyRevenue: Record<string, number> = {};
  const categoryRevenue: Record<string, number> = {};

  sales.forEach(s => {
    const date = new Date(s.date).toISOString().split('T')[0];
    dailyRevenue[date] = (dailyRevenue[date] || 0) + s.total;

    s.items.forEach(item => {
       // Simplified category tracking using item name keywords or ID if available
       // In production, map ID to Category Name properly
       const cat = item.category || 'General'; 
       categoryRevenue[cat] = (categoryRevenue[cat] || 0) + (item.sellPrice * item.quantity);
    });
  });

  const lowStockCount = products.filter(p => p.stock <= (p.minStock || 0)).length;

  const context = {
    dailySales: dailyRevenue,
    categoryPerformance: categoryRevenue,
    lowStockItemsCount: lowStockCount,
    totalProducts: products.length
  };

  const systemInstruction = `
    You are a senior business analyst for a retail store.
    Analyze the provided sales data (Daily Revenue map) and Inventory status.

    Tasks:
    1. Write a 1-sentence Executive Summary of performance.
    2. Determine the trend direction ('up', 'down', 'stable').
    3. List 3 actionable bullet points for the manager (e.g., restock, run promo, cut costs).
    4. Predict the TOTAL revenue for the NEXT 7 DAYS based on the recent daily trend.
    5. Identify the top performing category name.

    Return JSON matching the BusinessInsight interface.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: JSON.stringify(context),
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            trendDirection: { type: Type.STRING, enum: ['up', 'down', 'stable'] },
            actionItems: { type: Type.ARRAY, items: { type: Type.STRING } },
            predictedRevenueNextWeek: { type: Type.NUMBER },
            topPerformingCategory: { type: Type.STRING }
          },
          required: ['summary', 'trendDirection', 'actionItems', 'predictedRevenueNextWeek', 'topPerformingCategory']
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as BusinessInsight;
    }
    return null;
  } catch (error) {
    console.error("Gemini Business Insight Error:", error);
    return null;
  }
};

import React, { useMemo, useState } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  AreaChart,
  Area,
  ReferenceLine
} from 'recharts';
import { Sale, Product, BusinessInsight } from '../types';
import { TrendingUp, DollarSign, Package, AlertCircle, AlertTriangle, CalendarRange, Wallet, Calendar, Activity, ShieldAlert, User, Settings, Sparkles, TrendingDown, Minus, Target } from 'lucide-react';
import { INITIAL_CATEGORIES_TREE } from '../services/data';
import { useGlobal } from '../context/GlobalContext';
import { generateBusinessInsights } from '../services/geminiService';

interface DashboardProps {
  sales: Sale[];
  products: Product[];
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d', '#ffc658'];

type TimeRange = '7d' | '30d' | '90d' | 'all';

export const Dashboard: React.FC<DashboardProps> = ({ sales, products }) => {
  const { t, formatPrice, auditLogs, settings } = useGlobal();
  const [timeRange, setTimeRange] = useState<TimeRange>('30d');

  // AI State
  const [insight, setInsight] = useState<BusinessInsight | null>(null);
  const [loadingInsight, setLoadingInsight] = useState(false);

  // 1. Filter Sales based on Time Range
  const dashboardMetrics = useMemo(() => {
    const today = new Date();
    let startDate = new Date();

    if (timeRange === '7d') startDate.setDate(today.getDate() - 7);
    else if (timeRange === '30d') startDate.setDate(today.getDate() - 30);
    else if (timeRange === '90d') startDate.setDate(today.getDate() - 90);
    else startDate = new Date(0); // Beginning of time

    // Filter sales strictly by date range and non-voided status
    const filteredSales = sales.filter(s => {
       const saleDate = new Date(s.date);
       return saleDate >= startDate && saleDate <= today && s.status !== 'voided';
    });

    const totalRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const totalOrders = filteredSales.length;

    // Average Order Value
    const aov = totalOrders > 0 ? totalRevenue / totalOrders : 0;

    return { filteredSales, totalRevenue, totalOrders, aov, startDate };
  }, [sales, timeRange]);

  // 2. Dynamic Trend Data
  const trendData = useMemo(() => {
    const dailyMap = new Map<string, number>();
    const today = new Date();

    let daysToGenerate = 30;
    if (timeRange === '7d') daysToGenerate = 7;
    else if (timeRange === '90d') daysToGenerate = 90;
    else if (timeRange === 'all') daysToGenerate = 60; 

    for(let i = daysToGenerate - 1; i >= 0; i--) {
        const d = new Date(today);
        d.setDate(d.getDate() - i);
        const key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        dailyMap.set(key, 0);
    }

    dashboardMetrics.filteredSales.forEach(sale => {
      const dateStr = new Date(sale.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      if (dailyMap.has(dateStr)) {
        dailyMap.set(dateStr, (dailyMap.get(dateStr) || 0) + sale.total);
      }
    });

    const data = Array.from(dailyMap).map(([name, sales]) => ({ name, sales, projected: 0 }));

    // Inject Projection if available
    if (insight && insight.predictedRevenueNextWeek > 0) {
       const dailyAvg = insight.predictedRevenueNextWeek / 7;
       // Add 3 days of projection to end of chart
       for (let i = 1; i <= 3; i++) {
          const d = new Date();
          d.setDate(d.getDate() + i);
          const key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
          data.push({ name: key + ' (Est)', sales: 0, projected: dailyAvg });
       }
    }

    return data;
  }, [dashboardMetrics.filteredSales, timeRange, insight]);

  // 3. Category Breakdown
  const categoryData = useMemo(() => {
    const catMap = new Map<string, number>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        let catName = item.category;
        const catObj = INITIAL_CATEGORIES_TREE.find(c => c.id === item.category);
        if (catObj) catName = catObj.name;

        const lineTotal = item.sellPrice * item.quantity;
        catMap.set(catName, (catMap.get(catName) || 0) + lineTotal);
      });
    });

    const result = Array.from(catMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    if (result.length > 5) {
       const top5 = result.slice(0, 5);
       const others = result.slice(5).reduce((sum, item) => sum + item.value, 0);
       return [...top5, { name: 'Others', value: others }];
    }
    return result;
  }, [dashboardMetrics.filteredSales]);

  // 4. Top Selling Products
  const topProducts = useMemo(() => {
    const prodMap = new Map<string, { name: string; revenue: number; qty: number; unit: string }>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        const existing = prodMap.get(item.id) || { name: item.name, revenue: 0, qty: 0, unit: item.unit };
        existing.revenue += (item.sellPrice * item.quantity);
        existing.qty += (item.quantity / (item.sellConversionFactor || 1));
        prodMap.set(item.id, existing);
      });
    });

    return Array.from(prodMap.values())
      .sort((a, b) => b.revenue - a.revenue)
      .slice(0, 5);
  }, [dashboardMetrics.filteredSales]);

  // Low Stock Logic
  const lowStockProducts = products.filter(p => p.stock < (p.minStock || 20)).sort((a, b) => a.stock - b.stock);
  const lowStockCount = lowStockProducts.length;

  // Outstanding Debt
  const totalOutstanding = useMemo(() => {
     return sales
        .filter(s => s.status !== 'voided' && (s.paymentStatus === 'unpaid' || s.paymentStatus === 'partial'))
        .reduce((acc, s) => acc + (s.remainingAmount || s.total), 0);
  }, [sales]);

  // Recent Logs (Latest 5)
  const recentLogs = useMemo(() => {
     return [...auditLogs].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).slice(0, 5);
  }, [auditLogs]);

  // AI Handler
  const handleGenerateInsight = async () => {
    setLoadingInsight(true);
    // Use last 30 days data for analysis regardless of filter to get meaningful trends
    const recentSales = sales.filter(s => {
       const d = new Date(s.date);
       const thirtyDaysAgo = new Date();
       thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
       return d >= thirtyDaysAgo && s.status !== 'voided';
    });
    const result = await generateBusinessInsights(recentSales, products);
    setInsight(result);
    setLoadingInsight(false);
  };

  const StatCard = ({ title, value, icon: Icon, color, subtext, trend, progress }: any) => (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col justify-between h-full relative overflow-hidden">
      <div className="flex items-start justify-between mb-4 relative z-10">
        <div>
          <p className="text-sm font-medium text-slate-500">{title}</p>
          <h3 className="text-2xl font-bold text-slate-800 mt-1">{value}</h3>
        </div>
        <div className={`p-3 rounded-full ${color}`}>
          <Icon className="w-5 h-5 text-white" />
        </div>
      </div>

      {progress !== undefined && (
         <div className="mb-2 relative z-10">
            <div className="flex justify-between text-xs mb-1">
               <span className="text-slate-500">Monthly Target</span>
               <span className="font-bold text-slate-700">{progress.toFixed(0)}%</span>
            </div>
            <div className="w-full bg-slate-100 rounded-full h-2">
               <div className="bg-green-500 h-2 rounded-full transition-all duration-1000" style={{ width: `${Math.min(progress, 100)}%` }}></div>
            </div>
         </div>
      )}

      {subtext && (
         <div className="mt-auto pt-2 border-t border-slate-50 relative z-10">
            <p className="text-xs text-slate-400 flex items-center">
               {trend === 'up' && <TrendingUp className="w-3 h-3 mr-1 text-green-500" />}
               {subtext}
            </p>
         </div>
      )}
    </div>
  );

  // Calculate Target Progress (Monthly)
  const currentMonthRevenue = useMemo(() => {
     const now = new Date();
     return sales.filter(s => {
        const d = new Date(s.date);
        return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear() && s.status !== 'voided';
     }).reduce((acc, s) => acc + s.total, 0);
  }, [sales]);

  const targetProgress = settings.monthlyTarget ? (currentMonthRevenue / settings.monthlyTarget) * 100 : 0;

  return (
    <div className="space-y-6 animate-fade-in pb-12">
      {/* Header & Filter */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">{t('dashboard.title')}</h2>
          <p className="text-slate-500 text-sm flex items-center mt-1">
            <CalendarRange className="w-4 h-4 mr-1" />
            Performance Overview
          </p>
        </div>

        <div className="flex items-center gap-3">
           <button 
             onClick={handleGenerateInsight}
             disabled={loadingInsight}
             className="flex items-center px-4 py-2 bg-gradient-to-r from-violet-600 to-indigo-600 text-white rounded-lg shadow-md hover:shadow-lg transition-all text-sm font-medium disabled:opacity-70"
           >
             <Sparkles className={`w-4 h-4 mr-2 ${loadingInsight ? 'animate-spin' : ''}`} />
             {loadingInsight ? 'Analyzing...' : 'AI Analyst'}
           </button>

           <div className="bg-white p-1 rounded-lg border border-slate-200 flex shadow-sm overflow-x-auto">
              {(['7d', '30d', '90d', 'all'] as const).map((range) => (
                 <button
                   key={range}
                   onClick={() => setTimeRange(range)}
                   className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all whitespace-nowrap ${
                      timeRange === range 
                      ? 'bg-slate-800 text-white shadow-sm' 
                      : 'text-slate-600 hover:bg-slate-100'
                   }`}
                 >
                    {range === '7d' ? '7 Days' : range === '30d' ? '30 Days' : range === '90d' ? '3 Months' : 'All Time'}
                 </button>
              ))}
           </div>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title={t('dashboard.revenue')}
          value={formatPrice(dashboardMetrics.totalRevenue)}
          icon={DollarSign} 
          color="bg-green-500" 
          subtext={`${dashboardMetrics.totalOrders} orders in period`}
          trend="up"
          progress={timeRange === '30d' ? targetProgress : undefined}
        />
        <StatCard 
          title="Avg. Order Value"
          value={formatPrice(dashboardMetrics.aov)}
          icon={TrendingUp} 
          color="bg-blue-500" 
          subtext="Per transaction average"
        />
        <StatCard 
          title="Outstanding Debt"
          value={formatPrice(totalOutstanding)}
          icon={Wallet} 
          color="bg-orange-500" 
          subtext="Total unpaid (All time)"
        />
        <StatCard 
          title="Low Stock Alerts"
          value={lowStockCount} 
          icon={AlertCircle} 
          color={lowStockCount > 0 ? "bg-red-500" : "bg-slate-400"} 
          subtext={`${products.length} total items`}
        />
      </div>

      {/* AI Insight Panel */}
      {insight && (
         <div className="bg-gradient-to-r from-violet-600 to-indigo-600 rounded-xl shadow-lg p-6 text-white relative overflow-hidden animate-fade-in">
            <div className="absolute top-0 right-0 p-4 opacity-10">
               <Sparkles className="w-32 h-32" />
            </div>

            <div className="relative z-10">
               <div className="flex items-center justify-between mb-4">
                  <h3 className="text-xl font-bold flex items-center">
                     <Sparkles className="w-6 h-6 mr-2" /> AI Business Analysis
                  </h3>
                  <span className="bg-white/20 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wide">
                     Gemini Powered
                  </span>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="md:col-span-2">
                     <p className="text-lg font-medium leading-relaxed opacity-90 mb-4">
                        "{insight.summary}"
                     </p>
                     <div className="space-y-2">
                        <p className="text-xs font-bold uppercase opacity-70 tracking-wider">Recommended Actions</p>
                        <ul className="space-y-1">
                           {insight.actionItems.map((item, idx) => (
                              <li key={idx} className="flex items-center text-sm bg-white/10 px-3 py-2 rounded-lg backdrop-blur-sm">
                                 <CheckCircle className="w-4 h-4 mr-2 text-green-300" />
                                 {item}
                              </li>
                           ))}
                        </ul>
                     </div>
                  </div>

                  <div className="flex flex-col gap-4">
                     <div className="bg-white/10 rounded-xl p-4 backdrop-blur-md">
                        <p className="text-xs opacity-70 mb-1">Projected Revenue (7 Days)</p>
                        <p className="text-2xl font-bold">{formatPrice(insight.predictedRevenueNextWeek)}</p>
                     </div>
                     <div className="bg-white/10 rounded-xl p-4 backdrop-blur-md">
                        <p className="text-xs opacity-70 mb-1">Trend Direction</p>
                        <div className="flex items-center font-bold text-lg capitalize">
                           {insight.trendDirection === 'up' && <TrendingUp className="w-5 h-5 mr-2 text-green-300" />}
                           {insight.trendDirection === 'down' && <TrendingDown className="w-5 h-5 mr-2 text-red-300" />}
                           {insight.trendDirection === 'stable' && <Minus className="w-5 h-5 mr-2 text-yellow-300" />}
                           {insight.trendDirection}
                        </div>
                     </div>
                     <div className="bg-white/10 rounded-xl p-4 backdrop-blur-md">
                        <p className="text-xs opacity-70 mb-1">Top Category</p>
                        <p className="font-bold text-lg truncate">{insight.topPerformingCategory}</p>
                     </div>
                  </div>
               </div>
            </div>
         </div>
      )}

      {/* Low Stock Alert Section */}
      {lowStockProducts.length > 0 && (
        <div className="bg-red-50 border border-red-200 rounded-xl overflow-hidden shadow-sm">
          <div className="p-4 bg-red-100 border-b border-red-200 flex items-center justify-between">
            <h3 className="text-red-800 font-bold flex items-center text-sm uppercase tracking-wide">
              <AlertTriangle className="w-5 h-5 mr-2" />
              {t('dashboard.critical')} ({lowStockCount})
            </h3>
          </div>
          <div className="p-4 overflow-x-auto">
             <div className="flex space-x-4 pb-2">
               {lowStockProducts.map(p => (
                 <div key={p.id} className="min-w-[200px] bg-white p-3 rounded-lg border border-red-100 shadow-sm flex flex-col group hover:border-red-300 transition-colors cursor-pointer">
                    <div className="flex justify-between items-start mb-2">
                       <span className="font-semibold text-slate-700 truncate w-32 text-sm" title={p.name}>{p.name}</span>
                       <span className="text-[10px] font-mono bg-red-50 text-red-600 px-1.5 py-0.5 rounded border border-red-100">
                          {p.sku}
                       </span>
                    </div>
                    <div className="flex justify-between items-end mt-auto">
                      <div className="flex flex-col">
                        <span className="text-[10px] text-slate-400 uppercase">Current</span>
                        <span className="text-xl font-bold text-red-600">{p.stock}</span>
                      </div>
                      <div className="flex flex-col items-end">
                         <span className="text-[10px] text-slate-400 mb-0.5">Min: {p.minStock || 20}</span>
                         <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500 uppercase font-bold">
                           {p.unit}
                         </span>
                      </div>
                    </div>
                 </div>
               ))}
             </div>
          </div>
        </div>
      )}

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Sales Trend */}
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center justify-between mb-6">
             <h3 className="text-lg font-bold text-slate-800">{t('dashboard.trend')}</h3>
             <div className="flex items-center text-xs text-slate-500 space-x-3">
                <span className="flex items-center"><span className="w-3 h-3 bg-primary-500 rounded-full mr-2"></span> Revenue</span>
                {insight && <span className="flex items-center"><span className="w-3 h-3 bg-violet-400 rounded-full mr-2 border border-dashed border-violet-600"></span> Forecast</span>}
             </div>
          </div>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#0ea5e9" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorProjected" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                <XAxis 
                   dataKey="name" 
                   stroke="#94a3b8" 
                   fontSize={11} 
                   tickMargin={10} 
                   tickLine={false}
                   axisLine={false}
                />
                <YAxis 
                   stroke="#94a3b8" 
                   fontSize={11} 
                   tickFormatter={(val) => formatPrice(val).replace(/[^0-9.]/g, '')} 
                   tickLine={false}
                   axisLine={false}
                />
                <Tooltip 
                  formatter={(value: number, name: string) => [formatPrice(value), name === 'projected' ? 'Forecast' : 'Revenue']}
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                  cursor={{ stroke: '#cbd5e1', strokeWidth: 1, strokeDasharray: '4 4' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="sales" 
                  stroke="#0ea5e9" 
                  strokeWidth={3} 
                  fillOpacity={1} 
                  fill="url(#colorSales)" 
                />
                <Area 
                  type="monotone" 
                  dataKey="projected" 
                  stroke="#8b5cf6" 
                  strokeWidth={2} 
                  strokeDasharray="5 5"
                  fillOpacity={1} 
                  fill="url(#colorProjected)" 
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Category Pie & Activity Feed */}
        <div className="flex flex-col gap-6">
           <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col flex-1">
             <h3 className="text-lg font-bold text-slate-800 mb-2">{t('dashboard.byCategory')}</h3>
             <div className="flex-1 min-h-[200px]">
                <ResponsiveContainer width="100%" height="100%">
                 <PieChart>
                   <Pie
                     data={categoryData}
                     cx="50%"
                     cy="50%"
                     innerRadius={40}
                     outerRadius={60}
                     fill="#8884d8"
                     paddingAngle={5}
                     dataKey="value"
                   >
                     {categoryData.map((entry, index) => (
                       <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                     ))}
                   </Pie>
                   <Tooltip 
                      formatter={(value: number) => formatPrice(value)}
                      contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', fontSize: '12px' }}
                   />
                 </PieChart>
               </ResponsiveContainer>
             </div>
           </div>

           {/* Activity Feed Widget */}
           <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col flex-1 overflow-hidden">
             <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
                <Activity className="w-5 h-5 mr-2 text-primary-500" />
                Live Activity Feed
             </h3>
             <div className="flex-1 overflow-y-auto space-y-3 pr-2" style={{ maxHeight: '200px' }}>
                {recentLogs.length === 0 ? (
                   <p className="text-sm text-slate-400 text-center py-4">No recent activity.</p>
                ) : (
                   recentLogs.map(log => (
                      <div key={log.id} className="flex items-start space-x-3 text-sm pb-3 border-b border-slate-50 last:border-0 last:pb-0">
                         <div className={`mt-0.5 w-2 h-2 rounded-full flex-shrink-0 ${
                            log.severity === 'critical' ? 'bg-red-500' :
                            log.severity === 'high' ? 'bg-orange-500' :
                            log.severity === 'medium' ? 'bg-blue-500' : 'bg-green-500'
                         }`} />
                         <div>
                            <p className="font-medium text-slate-700">
                               <span className="font-bold">{log.userName}</span>: {log.action.replace('_', ' ')}
                            </p>
                            <p className="text-xs text-slate-500">{log.details}</p>
                            <p className="text-[10px] text-slate-400 mt-0.5">{new Date(log.timestamp).toLocaleTimeString()}</p>
                         </div>
                      </div>
                   ))
                )}
             </div>
           </div>
        </div>
      </div>

      {/* Top Products Table */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
         <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">{t('dashboard.topProducts')}</h3>
            <button className="text-sm text-primary-600 font-medium hover:underline">View Sales Report</button>
         </div>
         <div className="overflow-x-auto">
           <table className="w-full text-left">
             <thead className="bg-slate-50 border-b border-slate-100">
               <tr>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider pl-6">{t('inventory.productName')}</th>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">{t('dashboard.soldQty')}</th>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider text-right pr-6">{t('dashboard.revenue')}</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {topProducts.length === 0 ? (
                  <tr>
                     <td colSpan={3} className="text-center py-8 text-slate-400 text-sm">No sales data for this period.</td>
                  </tr>
               ) : (
                  topProducts.map((p, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-4 py-3 pl-6">
                         <div className="flex items-center">
                            <span className="w-6 h-6 rounded-full bg-slate-100 text-slate-500 flex items-center justify-center text-xs font-bold mr-3 group-hover:bg-primary-100 group-hover:text-primary-600 transition-colors">
                               {idx + 1}
                            </span>
                            <span className="font-medium text-slate-700">{p.name}</span>
                         </div>
                      </td>
                      <td className="px-4 py-3 text-right text-slate-600 font-mono text-sm">
                         {Math.round(p.qty)} <span className="text-[10px] text-slate-400 ml-1">{p.unit}</span>
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-slate-800 pr-6">
                         {formatPrice(p.revenue)}
                      </td>
                    </tr>
                  ))
               )}
             </tbody>
           </table>
         </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { SystemSettings, Language, Branch, PosMachine } from '../types';
import { useGlobal } from '../context/GlobalContext';
import { 
  Save, 
  Globe, 
  Building, 
  Printer, 
  Percent, 
  Monitor, 
  Database, 
  LayoutList, 
  CheckCircle, 
  X, 
  ImageIcon, 
  QrCode, 
  Copy, 
  RefreshCw, 
  Activity, 
  Wifi, 
  Server, 
  Link, 
  Tv, 
  HardDrive, 
  ShieldAlert, 
  Lock, 
  AlertTriangle,
  Loader2,
  Download,
  Upload,
  Target
} from 'lucide-react';

interface SettingsProps {
  settings: SystemSettings;
  onUpdateSettings: (settings: SystemSettings) => void;
  branches?: Branch[];
  posMachines?: PosMachine[];
}

type SettingsTab = 'company' | 'receipt' | 'tax' | 'device' | 'database' | 'localization' | 'interface' | 'customer_display';

const TABS: { id: SettingsTab; label: string; icon: any }[] = [
  { id: 'company', label: 'Company Information', icon: Building },
  { id: 'receipt', label: 'Receipt & Print Settings', icon: Printer },
  { id: 'tax', label: 'Tax & VAT Configuration', icon: Percent },
  { id: 'customer_display', label: 'Customer Display Configuration', icon: Tv },
  { id: 'device', label: 'Device Configuration', icon: Monitor },
  { id: 'database', label: 'Database & Backup', icon: Database },
  { id: 'localization', label: 'Localization & Language', icon: Globe },
  { id: 'interface', label: 'Interface & Display', icon: LayoutList },
];

export const Settings: React.FC<SettingsProps> = ({ settings, onUpdateSettings, branches = [], posMachines = [] }) => {
  // Access global context for export/import
  const { 
    products, sales, customers, users, units, categories, 
    branches: allBranches, posMachines: allPos, warehouses, 
    locations, transfers, counts, reservations, receipts, 
    adjustments, shifts, shiftSchedules, promotions,
    restoreSystemData 
  } = useGlobal();

  const [formData, setFormData] = useState<SystemSettings>(settings);
  const [activeTab, setActiveTab] = useState<SettingsTab>('company');
  const [successMsg, setSuccessMsg] = useState('');
  const importFileRef = useRef<HTMLInputElement>(null);

  // Test Connection State
  const [connectionStatus, setConnectionStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');
  const [localDbStatus, setLocalDbStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');

  // POS Availability Check State
  const [posCheckStatus, setPosCheckStatus] = useState<'idle' | 'checking' | 'available' | 'taken'>('idle');

  // Sync state when props change (e.g. data load from mock or API)
  useEffect(() => {
    setFormData(settings);
  }, [settings]);

  // Handle Tab Change with Auto-Reset Logic
  const handleTabChange = (newTab: SettingsTab) => {
    // If we are leaving the 'device' tab AND the ID is currently invalid (taken) OR checking
    if (activeTab === 'device' && (posCheckStatus === 'taken' || posCheckStatus === 'checking')) {
        // Reset Device fields back to original saved settings
        setFormData(prev => ({
            ...prev,
            currentBranchId: settings.currentBranchId,
            currentPosId: settings.currentPosId,
            deviceRole: settings.deviceRole,
            masterApiUrl: settings.masterApiUrl,
            autoSyncInterval: settings.autoSyncInterval
        }));
        // Clear the error status
        setPosCheckStatus('idle');
    }

    setActiveTab(newTab);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // Strict Block: Prevent saving ONLY if on Device tab AND (ID is duplicate OR Checking)
    if (activeTab === 'device') {
       if (posCheckStatus === 'taken') {
          alert("Error: Cannot save settings. The selected POS Terminal ID is already in use.");
          return;
       }
       if (posCheckStatus === 'checking') {
          return; // Silently block or show toast "Please wait..."
       }
    }

    onUpdateSettings(formData);
    setSuccessMsg('Settings saved successfully!');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleLangChange = (lang: Language) => {
    setFormData({ ...formData, language: lang });
  };

  // --- Export / Import Logic ---
  const handleExportData = () => {
    const exportData = {
      meta: {
        exportedAt: new Date().toISOString(),
        version: '1.0'
      },
      settings: formData,
      products,
      sales,
      customers,
      users,
      units,
      categories,
      branches: allBranches,
      posMachines: allPos,
      warehouses,
      locations,
      transfers,
      counts,
      reservations,
      receipts,
      adjustments,
      shifts,
      shiftSchedules,
      promotions
    };

    const jsonString = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = `buildmaster_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const jsonData = JSON.parse(event.target?.result as string);
        if (confirm("This will overwrite your current system data. Are you sure?")) {
           restoreSystemData(jsonData);
           alert("System data restored successfully!");
        }
      } catch (err) {
        alert("Failed to parse backup file. Invalid JSON.");
      }
      // Reset input
      if (importFileRef.current) importFileRef.current.value = '';
    };
    reader.readAsText(file);
  };

  // ... (Test Connection, Local DB, Check POS Availability logic same as before) ...
  const handleTestConnection = () => {
    if (!formData.masterApiUrl) {
       setConnectionStatus('error');
       return;
    }
    setConnectionStatus('testing');
    setTimeout(() => {
       if (formData.masterApiUrl && (formData.masterApiUrl.includes('http') || formData.masterApiUrl.includes('192') || formData.masterApiUrl.includes('localhost'))) {
          setConnectionStatus('success');
       } else {
          setConnectionStatus('error');
       }
    }, 1500);
  };

  const handleTestLocalDb = () => {
    setLocalDbStatus('testing');
    setTimeout(() => {
      if (formData.localDatabase?.host) {
        setLocalDbStatus('success');
      } else {
        setLocalDbStatus('error');
      }
    }, 1500);
  };

  const checkPosAvailability = (posId: string) => {
     if (!posId) {
        setPosCheckStatus('idle');
        return;
     }
     setPosCheckStatus('checking');
     setTimeout(() => {
        if (posId === 'pm2') { 
           setPosCheckStatus('taken');
        } else {
           setPosCheckStatus('available');
        }
     }, 1000); 
  };

  const availablePosMachines = posMachines.filter(p => p.branchId === formData.currentBranchId);

  const calculatePreviewTax = (price: number) => {
    if (!formData.tax.enabled) return { subtotal: price, tax: 0, total: price };
    const rate = formData.tax.rate / 100;
    if (formData.tax.calculationMode === 'excluded') {
      const tax = price * rate;
      return { subtotal: price, tax: tax, total: price + tax };
    } else {
      const tax = price - (price / (1 + rate));
      return { subtotal: price - tax, tax: tax, total: price };
    }
  };

  const isMasterNode = formData.deviceRole === 'Master';
  const isSaveDisabled = activeTab === 'device' && (posCheckStatus === 'taken' || posCheckStatus === 'checking');

  return (
    <div className="flex flex-col h-full">
      {/* ... Header and Tabs ... */}
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">System Settings</h2>
          <p className="text-slate-500">Manage configuration, preferences, and connections.</p>
        </div>
        {successMsg && (
          <div className="bg-green-100 border border-green-200 text-green-700 px-4 py-2 rounded-lg flex items-center shadow-sm animate-fade-in">
            <CheckCircle className="w-5 h-5 mr-2" />
            {successMsg}
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 min-h-0">
        {/* Sidebar Tabs */}
        <div className="w-full md:w-72 bg-slate-50 border-b md:border-b-0 md:border-r border-slate-200 flex flex-row md:flex-col overflow-x-auto md:overflow-y-auto shrink-0">
          {TABS.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;

            let label = tab.label;
            if (tab.id === 'database') {
                label = 'Database & Backup';
            }

            return (
              <button
                key={tab.id}
                onClick={() => handleTabChange(tab.id)}
                className={`flex items-center px-6 py-4 text-sm font-medium transition-all whitespace-nowrap md:whitespace-normal text-left
                  ${isActive 
                    ? 'bg-white text-construction-orange border-b-2 md:border-b-0 md:border-l-4 border-construction-orange shadow-sm md:shadow-none' 
                    : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900 border-l-4 border-transparent'
                  } ${
                    tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' ? 'text-red-500 hover:text-red-600' : ''
                  }`}
              >
                <Icon className={`w-5 h-5 mr-3 shrink-0 ${isActive ? 'text-construction-orange' : (tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' ? 'text-red-500' : 'text-slate-400')}`} />
                {label}
                {tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' && (
                   <AlertTriangle className="w-4 h-4 ml-auto text-red-500" />
                )}
                {tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'checking' && (
                   <Loader2 className="w-4 h-4 ml-auto text-slate-400 animate-spin" />
                )}
              </button>
            );
          })}
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-6 md:p-8 bg-white relative">
          <form onSubmit={handleSave} className="max-w-4xl mx-auto pb-20">

            {/* Company Info */}
            {activeTab === 'company' && (
              <div className="space-y-6 animate-fade-in">
                <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Company Information</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Company Name</label>
                    <input
                      type="text"
                      value={formData.companyName}
                      onChange={e => setFormData({ ...formData, companyName: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Tax ID / Registration No.</label>
                    <input
                      type="text"
                      value={formData.taxId}
                      onChange={e => setFormData({ ...formData, taxId: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                  </div>
                  <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-slate-700 mb-1">Address</label>
                    <textarea
                      value={formData.address}
                      onChange={e => setFormData({ ...formData, address: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 resize-none h-24"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Phone</label>
                    <input
                      type="text"
                      value={formData.phone}
                      onChange={e => setFormData({ ...formData, phone: e.target.value })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                    />
                  </div>

                  {/* Monthly Target Input */}
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center">
                       <Target className="w-4 h-4 mr-1 text-slate-500" />
                       Monthly Revenue Target ($)
                    </label>
                    <input
                      type="number"
                      min="0"
                      value={formData.monthlyTarget || 0}
                      onChange={e => setFormData({ ...formData, monthlyTarget: parseFloat(e.target.value) })}
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-bold"
                    />
                    <p className="text-xs text-slate-400 mt-1">Used for dashboard progress tracking.</p>
                  </div>
                </div>
              </div>
            )}

            {/* Other Tabs Logic */}

            {activeTab === 'customer_display' && (
              <div className="space-y-6 animate-fade-in">
                <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Customer Facing Display Configuration</h3>
                <div className="p-4 bg-slate-50 border border-slate-200 rounded-xl flex items-center justify-between mb-6">
                  <div>
                    <h4 className="font-bold text-slate-800">Enable Customer Screen</h4>
                    <p className="text-xs text-slate-500">Allow customers to view cart and pay on a secondary screen</p>
                  </div>
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input type="checkbox" className="sr-only peer" checked={formData.customerDisplay?.enabled} onChange={e => setFormData({ ...formData, customerDisplay: { ...formData.customerDisplay, enabled: e.target.checked } })} />
                    <div className="w-11 h-6 bg-slate-300 peer-focus:outline-none rounded-full peer peer-checked:bg-green-600"></div>
                  </label>
                </div>
                {formData.customerDisplay?.enabled && (
                  <div className="space-y-6">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Welcome Message</label>
                      <input type="text" value={formData.customerDisplay.welcomeMessage} onChange={e => setFormData({ ...formData, customerDisplay: { ...formData.customerDisplay, welcomeMessage: e.target.value } })} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Slide Interval (Seconds)</label>
                      <input type="number" min="3" max="60" value={formData.customerDisplay.promotionInterval} onChange={e => setFormData({ ...formData, customerDisplay: { ...formData.customerDisplay, promotionInterval: parseInt(e.target.value) || 5 } })} className="w-full md:w-32 px-4 py-2 border border-slate-300 rounded-lg" />
                    </div>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'receipt' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Receipt & Print Settings</h3>
                  <div className="flex flex-col xl:flex-row gap-8">
                     <div className="flex-1 space-y-6">
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">Paper Size</label>
                           <select value={formData.receiptPaperSize} onChange={e => setFormData({ ...formData, receiptPaperSize: e.target.value as any })} className="w-full px-4 py-2 border border-slate-300 rounded-lg">
                              <option value="58mm">Thermal 58mm</option>
                              <option value="80mm">Thermal 80mm (Standard)</option>
                              <option value="A4">A4 (Full Invoice)</option>
                           </select>
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">Header Message</label>
                          <input type="text" value={formData.receiptHeader} onChange={e => setFormData({ ...formData, receiptHeader: e.target.value })} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">Footer Message</label>
                          <input type="text" value={formData.receiptFooter} onChange={e => setFormData({ ...formData, receiptFooter: e.target.value })} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                        </div>
                     </div>
                     <div className="w-full xl:w-[320px] shrink-0">
                        <div className="bg-slate-200 p-6 rounded-xl flex justify-center items-start min-h-[450px]">
                           <div className={`bg-white shadow-lg p-4 text-xs font-mono text-slate-800 flex flex-col items-center transition-all duration-300 ${formData.receiptPaperSize === '58mm' ? 'w-[200px]' : formData.receiptPaperSize === '80mm' ? 'w-[280px]' : 'w-full h-[380px]'}`} style={{ minHeight: '300px' }}>
                              <h3 className="font-bold text-center text-sm">{formData.companyName}</h3>
                              <p className="italic mb-1 text-center">{formData.receiptHeader}</p>
                              <div className="w-full border-b border-dashed border-slate-300 my-3"></div>
                              <div className="w-full flex justify-between font-bold"><span>TOTAL</span><span>$107.00</span></div>
                              <div className="w-full border-b border-dashed border-slate-300 my-3"></div>
                              <p className="text-center">{formData.receiptFooter}</p>
                           </div>
                        </div>
                     </div>
                  </div>
               </div>
            )}

            {activeTab === 'tax' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Tax & VAT Configuration</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-2">Tax Rate (%)</label>
                        <input type="number" value={formData.tax.rate} onChange={e => setFormData({...formData, tax: { ...formData.tax, rate: parseFloat(e.target.value) || 0 }})} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                     </div>
                     <div className="flex items-center mt-6">
                        <input type="checkbox" checked={formData.tax.enabled} onChange={e => setFormData({...formData, tax: { ...formData.tax, enabled: e.target.checked }})} className="w-4 h-4 text-primary-600 rounded" />
                        <span className="ml-2 text-sm text-slate-700">Enable Tax</span>
                     </div>
                  </div>
               </div>
            )}

            {activeTab === 'device' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Device Configuration</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-2">Branch Location</label>
                        <select value={formData.currentBranchId || ''} onChange={e => { setFormData({ ...formData, currentBranchId: e.target.value, currentPosId: '' }); setPosCheckStatus('idle'); }} className="w-full px-4 py-2 border border-slate-300 rounded-lg">
                           <option value="">Select Branch</option>
                           {branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
                        </select>
                     </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-2">POS Terminal ID</label>
                        <select value={formData.currentPosId || ''} onChange={e => { const newId = e.target.value; setFormData({ ...formData, currentPosId: newId }); checkPosAvailability(newId); }} disabled={!formData.currentBranchId} className="w-full px-4 py-2 border border-slate-300 rounded-lg">
                           <option value="">Select POS Machine</option>
                           {availablePosMachines.map(p => <option key={p.id} value={p.id}>{p.machineNumber}</option>)}
                        </select>
                     </div>
                  </div>
               </div>
            )}

            {activeTab === 'database' && (
              <div className="space-y-6 animate-fade-in">
                <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">
                   {isMasterNode ? 'Primary System Database' : 'Local Database & Backup'}
                </h3>

                <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 mb-8">
                   <h4 className="font-bold text-slate-800 mb-4 flex items-center">
                      <HardDrive className="w-5 h-5 mr-2 text-slate-500" />
                      Data Management
                   </h4>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="p-4 bg-white rounded-lg border border-slate-200 shadow-sm">
                         <h5 className="font-bold text-slate-700 mb-2">Backup System Data</h5>
                         <p className="text-xs text-slate-500 mb-4">
                            Export all system data (Products, Sales, Settings, Customers) as a JSON file. Useful for migration or manual backup.
                         </p>
                         <button 
                            type="button"
                            onClick={handleExportData}
                            className="flex items-center justify-center w-full px-4 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors text-sm font-medium"
                         >
                            <Download className="w-4 h-4 mr-2" /> Export JSON
                         </button>
                      </div>

                      <div className="p-4 bg-white rounded-lg border border-slate-200 shadow-sm">
                         <h5 className="font-bold text-slate-700 mb-2">Restore System Data</h5>
                         <p className="text-xs text-slate-500 mb-4">
                            Import a previously exported JSON file. <span className="text-red-500 font-bold">Warning: This will overwrite existing data.</span>
                         </p>
                         <button 
                            type="button"
                            onClick={() => importFileRef.current?.click()}
                            className="flex items-center justify-center w-full px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors text-sm font-medium"
                         >
                            <Upload className="w-4 h-4 mr-2" /> Import JSON
                         </button>
                         <input 
                            type="file" 
                            ref={importFileRef}
                            className="hidden"
                            accept=".json"
                            onChange={handleImportData}
                         />
                      </div>
                   </div>
                </div>

                <div className={`p-4 border rounded-xl flex items-center justify-between mb-6 ${isMasterNode ? 'bg-purple-50 border-purple-100' : 'bg-indigo-50 border-indigo-100'}`}>
                  <div>
                    <h4 className={`font-bold ${isMasterNode ? 'text-purple-900' : 'text-indigo-900'}`}>
                       {isMasterNode ? 'Enable Database Engine' : 'Enable Local Database'}
                    </h4>
                    <p className={`text-xs ${isMasterNode ? 'text-purple-700' : 'text-indigo-700'}`}>
                       {isMasterNode 
                          ? 'Configure the main database connection for this Master Node' 
                          : 'Cache data locally for offline operations'
                       }
                    </p>
                  </div>
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input type="checkbox" className="sr-only peer" checked={formData.localDatabase?.enabled} onChange={e => setFormData({ ...formData, localDatabase: { ...formData.localDatabase!, enabled: e.target.checked } })} />
                    <div className={`w-11 h-6 bg-slate-300 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all ${isMasterNode ? 'peer-checked:bg-purple-600' : 'peer-checked:bg-indigo-600'}`}></div>
                  </label>
                </div>

                {formData.localDatabase?.enabled && (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Database Type</label>
                      <select
                        value={formData.localDatabase.type}
                        onChange={e => setFormData({ ...formData, localDatabase: { ...formData.localDatabase!, type: e.target.value as any } })}
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 bg-white"
                      >
                        <option value="postgresql">PostgreSQL</option>
                        <option value="mysql">MySQL</option>
                        <option value="sqlite">SQLite</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Host</label>
                      <input type="text" value={formData.localDatabase.host} onChange={e => setFormData({ ...formData, localDatabase: { ...formData.localDatabase!, host: e.target.value } })} className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500" placeholder="localhost" />
                    </div>
                    <div className="md:col-span-2 pt-4 border-t border-slate-100 flex justify-end">
                       <button 
                          type="button"
                          onClick={handleTestLocalDb}
                          disabled={localDbStatus === 'testing'}
                          className={`px-4 py-2 rounded-lg font-medium flex items-center transition-all ${localDbStatus === 'success' ? 'bg-green-100 text-green-700 border border-green-200' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}`}
                       >
                          {localDbStatus === 'testing' ? <RefreshCw className="w-4 h-4 animate-spin mr-2" /> : <HardDrive className="w-4 h-4 mr-2" />}
                          {localDbStatus === 'testing' ? 'Connecting...' : localDbStatus === 'success' ? 'Connected Successfully' : 'Test Connection'}
                       </button>
                    </div>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'localization' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Localization</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-3">System Language</label>
                        <div className="grid grid-cols-3 gap-3">
                           {[{ code: 'en', flag: '🇺🇸', label: 'English' }, { code: 'th', flag: '🇹🇭', label: 'ไทย' }, { code: 'lo', flag: '🇱🇦', label: 'ລາວ' }].map((lang) => (
                              <button key={lang.code} type="button" onClick={() => handleLangChange(lang.code as any)} className={`flex flex-col items-center justify-center p-4 rounded-xl border-2 transition-all ${formData.language === lang.code ? 'border-primary-500 bg-primary-50 text-primary-700' : 'border-slate-200 hover:bg-slate-50 text-slate-600'}`}>
                                 <span className="text-3xl mb-2">{lang.flag}</span>
                                 <span className="text-sm font-bold">{lang.label}</span>
                              </button>
                           ))}
                        </div>
                     </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-3">Currency Symbol</label>
                        <select value={formData.currencySymbol} onChange={e => setFormData({ ...formData, currencySymbol: e.target.value })} className="w-full px-4 py-2 border border-slate-300 rounded-lg">
                           <option value="$">USD ($)</option>
                           <option value="฿">Thai Baht (฿)</option>
                           <option value="₭">Lao Kip (₭)</option>
                        </select>
                     </div>
                  </div>
               </div>
            )}

            {activeTab === 'interface' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Interface & Display</h3>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-2">Default Items Per Page</label>
                     <select value={formData.defaultItemsPerPage} onChange={e => setFormData({ ...formData, defaultItemsPerPage: parseInt(e.target.value) })} className="w-full md:w-64 px-4 py-2 border border-slate-300 rounded-lg">
                        <option value={10}>10 items</option>
                        <option value={20}>20 items</option>
                        <option value={50}>50 items</option>
                     </select>
                  </div>
               </div>
            )}

            {/* Floating Save Button */}
            <div className="fixed bottom-6 right-6 md:absolute md:bottom-0 md:right-0 md:p-8 md:bg-transparent pointer-events-none">
                <button
                  type="submit"
                  disabled={isSaveDisabled}
                  className={`pointer-events-auto px-6 py-3 font-bold rounded-full md:rounded-lg shadow-lg flex items-center transform transition-all ${
                    isSaveDisabled 
                      ? 'bg-slate-300 text-slate-500 cursor-not-allowed' 
                      : 'bg-construction-orange text-white hover:bg-orange-600 hover:scale-105'
                  }`}
                >
                  {isSaveDisabled && <AlertTriangle className="w-5 h-5 mr-2" />}
                  {!isSaveDisabled && <Save className="w-5 h-5 mr-2" />}
                  {isSaveDisabled 
                     ? (posCheckStatus === 'checking' ? 'Checking ID...' : 'Cannot Save (Invalid ID)') 
                     : 'Save Settings'}
                </button>
            </div>

          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  AreaChart,
  Area,
  ReferenceLine
} from 'recharts';
import { Sale, Product, BusinessInsight } from '../types';
import { TrendingUp, DollarSign, Package, AlertCircle, AlertTriangle, CalendarRange, Wallet, Calendar, Activity, ShieldAlert, User, Settings, Sparkles, TrendingDown, Minus, Target, CheckCircle } from 'lucide-react';
import { INITIAL_CATEGORIES_TREE } from '../services/data';
import { useGlobal } from '../context/GlobalContext';
import { generateBusinessInsights } from '../services/geminiService';

interface DashboardProps {
  sales: Sale[];
  products: Product[];
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d', '#ffc658'];

type TimeRange = '7d' | '30d' | '90d' | 'all';

export const Dashboard: React.FC<DashboardProps> = ({ sales, products }) => {
  const { t, formatPrice, auditLogs, settings } = useGlobal();
  const [timeRange, setTimeRange] = useState<TimeRange>('30d');

  // AI State
  const [insight, setInsight] = useState<BusinessInsight | null>(null);
  const [loadingInsight, setLoadingInsight] = useState(false);

  // 1. Filter Sales based on Time Range
  const dashboardMetrics = useMemo(() => {
    const today = new Date();
    let startDate = new Date();

    if (timeRange === '7d') startDate.setDate(today.getDate() - 7);
    else if (timeRange === '30d') startDate.setDate(today.getDate() - 30);
    else if (timeRange === '90d') startDate.setDate(today.getDate() - 90);
    else startDate = new Date(0); // Beginning of time

    // Filter sales strictly by date range and non-voided status
    const filteredSales = sales.filter(s => {
       const saleDate = new Date(s.date);
       return saleDate >= startDate && saleDate <= today && s.status !== 'voided';
    });

    const totalRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const totalOrders = filteredSales.length;

    // Average Order Value
    const aov = totalOrders > 0 ? totalRevenue / totalOrders : 0;

    return { filteredSales, totalRevenue, totalOrders, aov, startDate };
  }, [sales, timeRange]);

  // 2. Dynamic Trend Data
  const trendData = useMemo(() => {
    const dailyMap = new Map<string, number>();
    const today = new Date();

    let daysToGenerate = 30;
    if (timeRange === '7d') daysToGenerate = 7;
    else if (timeRange === '90d') daysToGenerate = 90;
    else if (timeRange === 'all') daysToGenerate = 60; 

    for(let i = daysToGenerate - 1; i >= 0; i--) {
        const d = new Date(today);
        d.setDate(d.getDate() - i);
        const key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        dailyMap.set(key, 0);
    }

    dashboardMetrics.filteredSales.forEach(sale => {
      const dateStr = new Date(sale.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      if (dailyMap.has(dateStr)) {
        dailyMap.set(dateStr, (dailyMap.get(dateStr) || 0) + sale.total);
      }
    });

    const data = Array.from(dailyMap).map(([name, sales]) => ({ name, sales, projected: 0 }));

    // Inject Projection if available
    if (insight && insight.predictedRevenueNextWeek > 0) {
       const dailyAvg = insight.predictedRevenueNextWeek / 7;
       // Add 3 days of projection to end of chart
       for (let i = 1; i <= 3; i++) {
          const d = new Date();
          d.setDate(d.getDate() + i);
          const key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
          data.push({ name: key + ' (Est)', sales: 0, projected: dailyAvg });
       }
    }

    return data;
  }, [dashboardMetrics.filteredSales, timeRange, insight]);

  // 3. Category Breakdown
  const categoryData = useMemo(() => {
    const catMap = new Map<string, number>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        let catName = item.category;
        const catObj = INITIAL_CATEGORIES_TREE.find(c => c.id === item.category);
        if (catObj) catName = catObj.name;

        const lineTotal = item.sellPrice * item.quantity;
        catMap.set(catName, (catMap.get(catName) || 0) + lineTotal);
      });
    });

    const result = Array.from(catMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    if (result.length > 5) {
       const top5 = result.slice(0, 5);
       const others = result.slice(5).reduce((sum, item) => sum + item.value, 0);
       return [...top5, { name: 'Others', value: others }];
    }
    return result;
  }, [dashboardMetrics.filteredSales]);

  // 4. Top Selling Products
  const topProducts = useMemo(() => {
    const prodMap = new Map<string, { name: string; revenue: number; qty: number; unit: string }>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        const existing = prodMap.get(item.id) || { name: item.name, revenue: 0, qty: 0, unit: item.unit };
        existing.revenue += (item.sellPrice * item.quantity);
        existing.qty += (item.quantity / (item.sellConversionFactor || 1));
        prodMap.set(item.id, existing);
      });
    });

    return Array.from(prodMap.values())
      .sort((a, b) => b.revenue - a.revenue)
      .slice(0, 5);
  }, [dashboardMetrics.filteredSales]);

  // Low Stock Logic
  const lowStockProducts = products.filter(p => p.stock < (p.minStock || 20)).sort((a, b) => a.stock - b.stock);
  const lowStockCount = lowStockProducts.length;

  // Outstanding Debt
  const totalOutstanding = useMemo(() => {
     return sales
        .filter(s => s.status !== 'voided' && (s.paymentStatus === 'unpaid' || s.paymentStatus === 'partial'))
        .reduce((acc, s) => acc + (s.remainingAmount || s.total), 0);
  }, [sales]);

  // Recent Logs (Latest 5)
  const recentLogs = useMemo(() => {
     return [...auditLogs].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).slice(0, 5);
  }, [auditLogs]);

  // AI Handler
  const handleGenerateInsight = async () => {
    setLoadingInsight(true);
    // Use last 30 days data for analysis regardless of filter to get meaningful trends
    const recentSales = sales.filter(s => {
       const d = new Date(s.date);
       const thirtyDaysAgo = new Date();
       thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
       return d >= thirtyDaysAgo && s.status !== 'voided';
    });
    const result = await generateBusinessInsights(recentSales, products);
    setInsight(result);
    setLoadingInsight(false);
  };

  const StatCard = ({ title, value, icon: Icon, color, subtext, trend, progress }: any) => (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col justify-between h-full relative overflow-hidden">
      <div className="flex items-start justify-between mb-4 relative z-10">
        <div>
          <p className="text-sm font-medium text-slate-500">{title}</p>
          <h3 className="text-2xl font-bold text-slate-800 mt-1">{value}</h3>
        </div>
        <div className={`p-3 rounded-full ${color}`}>
          <Icon className="w-5 h-5 text-white" />
        </div>
      </div>

      {progress !== undefined && (
         <div className="mb-2 relative z-10">
            <div className="flex justify-between text-xs mb-1">
               <span className="text-slate-500">Monthly Target</span>
               <span className="font-bold text-slate-700">{progress.toFixed(0)}%</span>
            </div>
            <div className="w-full bg-slate-100 rounded-full h-2">
               <div className="bg-green-500 h-2 rounded-full transition-all duration-1000" style={{ width: `${Math.min(progress, 100)}%` }}></div>
            </div>
         </div>
      )}

      {subtext && (
         <div className="mt-auto pt-2 border-t border-slate-50 relative z-10">
            <p className="text-xs text-slate-400 flex items-center">
               {trend === 'up' && <TrendingUp className="w-3 h-3 mr-1 text-green-500" />}
               {subtext}
            </p>
         </div>
      )}
    </div>
  );

  // Calculate Target Progress (Monthly)
  const currentMonthRevenue = useMemo(() => {
     const now = new Date();
     return sales.filter(s => {
        const d = new Date(s.date);
        return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear() && s.status !== 'voided';
     }).reduce((acc, s) => acc + s.total, 0);
  }, [sales]);

  const targetProgress = settings.monthlyTarget ? (currentMonthRevenue / settings.monthlyTarget) * 100 : 0;

  return (
    <div className="space-y-6 animate-fade-in pb-12">
      {/* Header & Filter */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">{t('dashboard.title')}</h2>
          <p className="text-slate-500 text-sm flex items-center mt-1">
            <CalendarRange className="w-4 h-4 mr-1" />
            Performance Overview
          </p>
        </div>

        <div className="flex items-center gap-3">
           <button 
             onClick={handleGenerateInsight}
             disabled={loadingInsight}
             className="flex items-center px-4 py-2 bg-gradient-to-r from-violet-600 to-indigo-600 text-white rounded-lg shadow-md hover:shadow-lg transition-all text-sm font-medium disabled:opacity-70"
           >
             <Sparkles className={`w-4 h-4 mr-2 ${loadingInsight ? 'animate-spin' : ''}`} />
             {loadingInsight ? 'Analyzing...' : 'AI Analyst'}
           </button>

           <div className="bg-white p-1 rounded-lg border border-slate-200 flex shadow-sm overflow-x-auto">
              {(['7d', '30d', '90d', 'all'] as const).map((range) => (
                 <button
                   key={range}
                   onClick={() => setTimeRange(range)}
                   className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all whitespace-nowrap ${
                      timeRange === range 
                      ? 'bg-slate-800 text-white shadow-sm' 
                      : 'text-slate-600 hover:bg-slate-100'
                   }`}
                 >
                    {range === '7d' ? '7 Days' : range === '30d' ? '30 Days' : range === '90d' ? '3 Months' : 'All Time'}
                 </button>
              ))}
           </div>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title={t('dashboard.revenue')}
          value={formatPrice(dashboardMetrics.totalRevenue)}
          icon={DollarSign} 
          color="bg-green-500" 
          subtext={`${dashboardMetrics.totalOrders} orders in period`}
          trend="up"
          progress={timeRange === '30d' ? targetProgress : undefined}
        />
        <StatCard 
          title="Avg. Order Value"
          value={formatPrice(dashboardMetrics.aov)}
          icon={TrendingUp} 
          color="bg-blue-500" 
          subtext="Per transaction average"
        />
        <StatCard 
          title="Outstanding Debt"
          value={formatPrice(totalOutstanding)}
          icon={Wallet} 
          color="bg-orange-500" 
          subtext="Total unpaid (All time)"
        />
        <StatCard 
          title="Low Stock Alerts"
          value={lowStockCount} 
          icon={AlertCircle} 
          color={lowStockCount > 0 ? "bg-red-500" : "bg-slate-400"} 
          subtext={`${products.length} total items`}
        />
      </div>

      {/* AI Insight Panel */}
      {insight && (
         <div className="bg-gradient-to-r from-violet-600 to-indigo-600 rounded-xl shadow-lg p-6 text-white relative overflow-hidden animate-fade-in">
            <div className="absolute top-0 right-0 p-4 opacity-10">
               <Sparkles className="w-32 h-32" />
            </div>

            <div className="relative z-10">
               <div className="flex items-center justify-between mb-4">
                  <h3 className="text-xl font-bold flex items-center">
                     <Sparkles className="w-6 h-6 mr-2" /> AI Business Analysis
                  </h3>
                  <span className="bg-white/20 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wide">
                     Gemini Powered
                  </span>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="md:col-span-2">
                     <p className="text-lg font-medium leading-relaxed opacity-90 mb-4">
                        "{insight.summary}"
                     </p>
                     <div className="space-y-2">
                        <p className="text-xs font-bold uppercase opacity-70 tracking-wider">Recommended Actions</p>
                        <ul className="space-y-1">
                           {insight.actionItems.map((item, idx) => (
                              <li key={idx} className="flex items-center text-sm bg-white/10 px-3 py-2 rounded-lg backdrop-blur-sm">
                                 <CheckCircle className="w-4 h-4 mr-2 text-green-300" />
                                 {item}
                              </li>
                           ))}
                        </ul>
                     </div>
                  </div>

                  <div className="flex flex-col gap-4">
                     <div className="bg-white/10 rounded-xl p-4 backdrop-blur-md">
                        <p className="text-xs opacity-70 mb-1">Projected Revenue (7 Days)</p>
                        <p className="text-2xl font-bold">{formatPrice(insight.predictedRevenueNextWeek)}</p>
                     </div>
                     <div className="bg-white/10 rounded-xl p-4 backdrop-blur-md">
                        <p className="text-xs opacity-70 mb-1">Trend Direction</p>
                        <div className="flex items-center font-bold text-lg capitalize">
                           {insight.trendDirection === 'up' && <TrendingUp className="w-5 h-5 mr-2 text-green-300" />}
                           {insight.trendDirection === 'down' && <TrendingDown className="w-5 h-5 mr-2 text-red-300" />}
                           {insight.trendDirection === 'stable' && <Minus className="w-5 h-5 mr-2 text-yellow-300" />}
                           {insight.trendDirection}
                        </div>
                     </div>
                     <div className="bg-white/10 rounded-xl p-4 backdrop-blur-md">
                        <p className="text-xs opacity-70 mb-1">Top Category</p>
                        <p className="font-bold text-lg truncate">{insight.topPerformingCategory}</p>
                     </div>
                  </div>
               </div>
            </div>
         </div>
      )}

      {/* Low Stock Alert Section */}
      {lowStockProducts.length > 0 && (
        <div className="bg-red-50 border border-red-200 rounded-xl overflow-hidden shadow-sm">
          <div className="p-4 bg-red-100 border-b border-red-200 flex items-center justify-between">
            <h3 className="text-red-800 font-bold flex items-center text-sm uppercase tracking-wide">
              <AlertTriangle className="w-5 h-5 mr-2" />
              {t('dashboard.critical')} ({lowStockCount})
            </h3>
          </div>
          <div className="p-4 overflow-x-auto">
             <div className="flex space-x-4 pb-2">
               {lowStockProducts.map(p => (
                 <div key={p.id} className="min-w-[200px] bg-white p-3 rounded-lg border border-red-100 shadow-sm flex flex-col group hover:border-red-300 transition-colors cursor-pointer">
                    <div className="flex justify-between items-start mb-2">
                       <span className="font-semibold text-slate-700 truncate w-32 text-sm" title={p.name}>{p.name}</span>
                       <span className="text-[10px] font-mono bg-red-50 text-red-600 px-1.5 py-0.5 rounded border border-red-100">
                          {p.sku}
                       </span>
                    </div>
                    <div className="flex justify-between items-end mt-auto">
                      <div className="flex flex-col">
                        <span className="text-[10px] text-slate-400 uppercase">Current</span>
                        <span className="text-xl font-bold text-red-600">{p.stock}</span>
                      </div>
                      <div className="flex flex-col items-end">
                         <span className="text-[10px] text-slate-400 mb-0.5">Min: {p.minStock || 20}</span>
                         <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500 uppercase font-bold">
                           {p.unit}
                         </span>
                      </div>
                    </div>
                 </div>
               ))}
             </div>
          </div>
        </div>
      )}

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Sales Trend */}
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center justify-between mb-6">
             <h3 className="text-lg font-bold text-slate-800">{t('dashboard.trend')}</h3>
             <div className="flex items-center text-xs text-slate-500 space-x-3">
                <span className="flex items-center"><span className="w-3 h-3 bg-primary-500 rounded-full mr-2"></span> Revenue</span>
                {insight && <span className="flex items-center"><span className="w-3 h-3 bg-violet-400 rounded-full mr-2 border border-dashed border-violet-600"></span> Forecast</span>}
             </div>
          </div>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#0ea5e9" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorProjected" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                <XAxis 
                   dataKey="name" 
                   stroke="#94a3b8" 
                   fontSize={11} 
                   tickMargin={10} 
                   tickLine={false}
                   axisLine={false}
                />
                <YAxis 
                   stroke="#94a3b8" 
                   fontSize={11} 
                   tickFormatter={(val) => formatPrice(val).replace(/[^0-9.]/g, '')} 
                   tickLine={false}
                   axisLine={false}
                />
                <Tooltip 
                  formatter={(value: number, name: string) => [formatPrice(value), name === 'projected' ? 'Forecast' : 'Revenue']}
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                  cursor={{ stroke: '#cbd5e1', strokeWidth: 1, strokeDasharray: '4 4' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="sales" 
                  stroke="#0ea5e9" 
                  strokeWidth={3} 
                  fillOpacity={1} 
                  fill="url(#colorSales)" 
                />
                <Area 
                  type="monotone" 
                  dataKey="projected" 
                  stroke="#8b5cf6" 
                  strokeWidth={2} 
                  strokeDasharray="5 5"
                  fillOpacity={1} 
                  fill="url(#colorProjected)" 
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Category Pie & Activity Feed */}
        <div className="flex flex-col gap-6">
           <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col flex-1">
             <h3 className="text-lg font-bold text-slate-800 mb-2">{t('dashboard.byCategory')}</h3>
             <div className="flex-1 min-h-[200px]">
                <ResponsiveContainer width="100%" height="100%">
                 <PieChart>
                   <Pie
                     data={categoryData}
                     cx="50%"
                     cy="50%"
                     innerRadius={40}
                     outerRadius={60}
                     fill="#8884d8"
                     paddingAngle={5}
                     dataKey="value"
                   >
                     {categoryData.map((entry, index) => (
                       <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                     ))}
                   </Pie>
                   <Tooltip 
                      formatter={(value: number) => formatPrice(value)}
                      contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', fontSize: '12px' }}
                   />
                 </PieChart>
               </ResponsiveContainer>
             </div>
           </div>

           {/* Activity Feed Widget */}
           <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col flex-1 overflow-hidden">
             <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
                <Activity className="w-5 h-5 mr-2 text-primary-500" />
                Live Activity Feed
             </h3>
             <div className="flex-1 overflow-y-auto space-y-3 pr-2" style={{ maxHeight: '200px' }}>
                {recentLogs.length === 0 ? (
                   <p className="text-sm text-slate-400 text-center py-4">No recent activity.</p>
                ) : (
                   recentLogs.map(log => (
                      <div key={log.id} className="flex items-start space-x-3 text-sm pb-3 border-b border-slate-50 last:border-0 last:pb-0">
                         <div className={`mt-0.5 w-2 h-2 rounded-full flex-shrink-0 ${
                            log.severity === 'critical' ? 'bg-red-500' :
                            log.severity === 'high' ? 'bg-orange-500' :
                            log.severity === 'medium' ? 'bg-blue-500' : 'bg-green-500'
                         }`} />
                         <div>
                            <p className="font-medium text-slate-700">
                               <span className="font-bold">{log.userName}</span>: {log.action.replace('_', ' ')}
                            </p>
                            <p className="text-xs text-slate-500">{log.details}</p>
                            <p className="text-[10px] text-slate-400 mt-0.5">{new Date(log.timestamp).toLocaleTimeString()}</p>
                         </div>
                      </div>
                   ))
                )}
             </div>
           </div>
        </div>
      </div>

      {/* Top Products Table */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
         <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">{t('dashboard.topProducts')}</h3>
            <button className="text-sm text-primary-600 font-medium hover:underline">View Sales Report</button>
         </div>
         <div className="overflow-x-auto">
           <table className="w-full text-left">
             <thead className="bg-slate-50 border-b border-slate-100">
               <tr>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider pl-6">{t('inventory.productName')}</th>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">{t('dashboard.soldQty')}</th>
                 <th className="px-4 py-3 text-xs font-bold text-slate-500 uppercase tracking-wider text-right pr-6">{t('dashboard.revenue')}</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {topProducts.length === 0 ? (
                  <tr>
                     <td colSpan={3} className="text-center py-8 text-slate-400 text-sm">No sales data for this period.</td>
                  </tr>
               ) : (
                  topProducts.map((p, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-4 py-3 pl-6">
                         <div className="flex items-center">
                            <span className="w-6 h-6 rounded-full bg-slate-100 text-slate-500 flex items-center justify-center text-xs font-bold mr-3 group-hover:bg-primary-100 group-hover:text-primary-600 transition-colors">
                               {idx + 1}
                            </span>
                            <span className="font-medium text-slate-700">{p.name}</span>
                         </div>
                      </td>
                      <td className="px-4 py-3 text-right text-slate-600 font-mono text-sm">
                         {Math.round(p.qty)} <span className="text-[10px] text-slate-400 ml-1">{p.unit}</span>
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-slate-800 pr-6">
                         {formatPrice(p.revenue)}
                      </td>
                    </tr>
                  ))
               )}
             </tbody>
           </table>
         </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, UnitDefinition, CategoryItem, Warehouse, InventoryAnalysisResult, Sale, Branch } from '../types';
import { Search, Plus, Edit2, Trash2, X, Check, Layers, Box, ArrowRight, ArrowLeftRight, RefreshCw, Info, Building2, AlertTriangle, Bell, Sparkles, Loader2, TrendingUp, AlertCircle, PackagePlus, Scale, DollarSign, Store, ChevronLeft, ChevronRight, ShoppingBag, Image as ImageIcon, Upload, Palette, Ruler, ScanBarcode } from 'lucide-react';
import { analyzeInventory } from '../services/geminiService';
import { useGlobal } from '../context/GlobalContext';
import { BarcodeScanner } from './BarcodeScanner';

interface InventoryProps {
  products: Product[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  warehouses?: Warehouse[];
  sales: Sale[];
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onAddProduct: (product: Product) => void;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const Inventory: React.FC<InventoryProps> = ({ products, units, categories, warehouses = [], sales, onUpdateProduct, onDeleteProduct, onAddProduct }) => {
  const { branches, settings, t } = useGlobal();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = settings.defaultItemsPerPage || 10;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'general' | 'physical' | 'pricing' | 'variants'>('general');
  const [editingId, setEditingId] = useState<string | null>(null);

  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiResult, setAiResult] = useState<InventoryAnalysisResult | null>(null);
  const [activeAiTab, setActiveAiTab] = useState<'reorder' | 'new' | 'bundles'>('reorder');

  // Scanner State
  const [isScannerOpen, setIsScannerOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    sku: '',
    barcode: '',
    category: '',
    price: 0,
    costPrice: 0,
    stock: 0,
    minStock: 20,
    unit: '',
    physical: { weight: 0, width: 0, height: 0, depth: 0 },
    branchPrices: [],
    imageUrl: ''
  });

  const [variants, setVariants] = useState<Partial<ProductVariant>[]>([]);

  const getFlattenedCategories = () => {
    const options: { id: string; name: string; level: number }[] = [];
    const buildOptions = (parentId: string | null, level: number) => {
      const children = categories.filter(c => c.parentId === parentId);
      children.forEach(c => {
        options.push({ id: c.id, name: c.name, level });
        buildOptions(c.id, level + 1);
      });
    };
    buildOptions(null, 0);
    return options;
  };

  const categoryOptions = getFlattenedCategories();

  const getCategoryName = (idOrName: string) => {
    const cat = categories.find(c => c.id === idOrName);
    return cat ? cat.name : idOrName; 
  };

  const filteredProducts = products.filter(p => {
    const searchLower = searchTerm.toLowerCase();
    const matchesSearch = 
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) || 
      p.barcode?.includes(searchLower) ||
      (p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      ));

    const pCatName = getCategoryName(p.category);
    const filterCatName = filterCategory === 'all' ? 'all' : getCategoryName(filterCategory);
    const matchesCategory = filterCategory === 'all' || p.category === filterCategory || pCatName === filterCatName;

    return matchesSearch && matchesCategory;
  });

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory]);

  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedProducts = filteredProducts.slice(startIndex, startIndex + itemsPerPage);

  const unitsByCategory = units.reduce((acc, unit) => {
    if (!acc[unit.category]) acc[unit.category] = [];
    acc[unit.category].push(unit);
    return acc;
  }, {} as Record<string, UnitDefinition[]>);

  const handleOpenAddModal = () => {
    setEditingId(null);
    setActiveTab('general');
    setFormData({
      name: '',
      sku: '',
      barcode: '',
      category: categoryOptions[0]?.id || '',
      price: 0,
      costPrice: 0,
      stock: 0,
      minStock: 20,
      unit: units[0]?.symbol || 'pc',
      physical: { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: [],
      imageUrl: ''
    });
    setVariants([]);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (product: Product) => {
    setEditingId(product.id);
    setActiveTab('general');
    setFormData({
      name: product.name,
      sku: product.sku,
      barcode: product.barcode,
      category: product.category,
      price: product.price,
      costPrice: product.costPrice || 0,
      stock: product.stock,
      minStock: product.minStock || 20,
      unit: product.unit,
      physical: product.physical || { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: product.branchPrices || [],
      imageUrl: product.imageUrl || ''
    });
    setVariants(product.variants ? product.variants.map(v => ({...v})) : []);
    setIsModalOpen(true);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, imageUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  useEffect(() => {
    if (isAiModalOpen && !aiResult && !aiLoading) {
      const performAnalysis = async () => {
        setAiLoading(true);
        const result = await analyzeInventory(products, sales);
        setAiResult(result);
        setAiLoading(false);
      };
      performAnalysis();
    }
  }, [isAiModalOpen, products, sales, aiResult, aiLoading]);

  const handleOpenAiInsights = () => setIsAiModalOpen(true);

  const handleAddSuggestedProduct = (suggestion: any) => {
    setIsAiModalOpen(false);
    setEditingId(null);
    setActiveTab('general');

    const matchedCat = categories.find(c => c.name.toLowerCase().includes(suggestion.categoryName?.toLowerCase() || ''))?.id || '';
    const unitSearch = suggestion.suggestedUnit?.toLowerCase();
    let matchedUnit = units.find(u => u.symbol.toLowerCase() === unitSearch || u.name.toLowerCase() === unitSearch)?.symbol;
    if (!matchedUnit && unitSearch === 'set') matchedUnit = 'set'; 
    if (!matchedUnit) matchedUnit = 'pc';

    let productName = suggestion.name || suggestion.bundleName;
    if (suggestion.components && Array.isArray(suggestion.components) && suggestion.components.length > 0) {
       productName = `${productName} (Includes: ${suggestion.components.join(', ')})`;
    }

    setFormData({
      name: productName,
      sku: '',
      barcode: '',
      category: matchedCat,
      price: suggestion.estimatedPrice,
      costPrice: 0,
      stock: 0,
      minStock: 20,
      unit: matchedUnit,
      physical: { weight: 0, width: 0, height: 0, depth: 0 },
      branchPrices: [],
      imageUrl: ''
    });
    setVariants([]);
    setIsModalOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const isNum = ['price', 'costPrice', 'stock', 'minStock'].includes(name);

    setFormData(prev => ({
      ...prev,
      [name]: isNum ? (parseFloat(value) || 0) : value
    }));

    if (name === 'price') {
      const newMainPrice = parseFloat(value) || 0;
      setVariants(prev => prev.map(v => {
         const factor = v.conversionFactor || 1;
         return { ...v, price: factor !== 0 ? newMainPrice / factor : 0 };
      }));
    }
  };

  const handlePhysicalChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev,
      physical: {
        ...prev.physical,
        [field]: parseFloat(value) || 0
      }
    }));
  };

  const generateVariantCodes = (index: number) => {
    const suffix = (index + 1).toString().padStart(3, '0');
    const skuBase = formData.sku || 'SKU';
    return { code: `${skuBase}-${suffix}`, barcode: formData.barcode ? `${formData.barcode}${suffix}` : '' };
  };

  const handleAddVariant = () => {
    const { code, barcode } = generateVariantCodes(variants.length);
    setVariants(prev => [...prev, {
      id: `v-${Date.now()}`,
      name: '', 
      code,
      barcode,
      conversionFactor: 1, 
      price: formData.price,
      costPrice: formData.costPrice,
      color: '',
      size: ''
    }]);
  };

  const handleRemoveVariant = (index: number) => setVariants(prev => prev.filter((_, i) => i !== index));

  const handleVariantChange = (index: number, field: keyof ProductVariant, value: any) => {
    setVariants(prev => {
      const newVariants = [...prev];
      let updatedVariant = { ...newVariants[index], [field]: value };

      if (field === 'name') {
        const mainUnitDef = units.find(u => u.symbol === formData.unit);
        const variantUnitDef = units.find(u => u.symbol === value);
        if (mainUnitDef && variantUnitDef && mainUnitDef.category === variantUnitDef.category) {
          const factor = mainUnitDef.baseFactor / variantUnitDef.baseFactor;
          updatedVariant.conversionFactor = factor;
          updatedVariant.price = (formData.price || 0) / factor;
          updatedVariant.costPrice = (formData.costPrice || 0) / factor;
        }
      }
      if (field === 'price' || field === 'costPrice' || field === 'conversionFactor') {
        updatedVariant[field] = parseFloat(value) || 0;
      }
      newVariants[index] = updatedVariant;
      return newVariants;
    });
  };

  const handleVariantRelationChange = (index: number, ratio: number, mode: 'sub' | 'bundle') => {
    const factor = mode === 'sub' ? ratio : (1 / ratio);
    setVariants(prev => {
      const newVariants = [...prev];
      newVariants[index] = { 
        ...newVariants[index], 
        conversionFactor: factor,
        price: factor !== 0 ? ((formData.price || 0) / factor) : 0,
        costPrice: factor !== 0 ? ((formData.costPrice || 0) / factor) : 0
      };
      return newVariants;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.unit) {
      const productData: Product = {
        id: editingId || `P-${Date.now()}`,
        name: formData.name!,
        category: formData.category || 'Uncategorized',
        price: formData.price || 0,
        costPrice: formData.costPrice || 0,
        stock: formData.stock || 0,
        minStock: formData.minStock || 20,
        unit: formData.unit!,
        sku: formData.sku || '',
        barcode: formData.barcode || '',
        physical: formData.physical,
        branchPrices: formData.branchPrices,
        variants: variants.length > 0 ? variants as ProductVariant[] : undefined,
        warehouseInventory: editingId 
          ? products.find(p => p.id === editingId)?.warehouseInventory 
          : [{ warehouseId: 'wh1', quantity: formData.stock || 0 }],
        imageUrl: formData.imageUrl
      };

      if (editingId) onUpdateProduct(productData);
      else onAddProduct(productData);
      setIsModalOpen(false);
    }
  };

  const handleScan = (code: string) => {
    setSearchTerm(code);
    setIsScannerOpen(false);
  };

  return (
    <div className="space-y-6 h-full flex flex-col relative pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">{t('inventory.title')}</h2>
          <p className="text-slate-500">{t('inventory.subtitle')}</p>
        </div>
        <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 scrollbar-hide">
          <button 
            onClick={handleOpenAiInsights}
            className="flex items-center justify-center px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-lg hover:shadow-lg transition-all font-medium shadow-sm whitespace-nowrap"
          >
            <Sparkles className="w-4 h-4 mr-2" />
            {t('inventory.aiInsights')}
          </button>
          <button 
            onClick={handleOpenAddModal}
            className="hidden md:flex items-center justify-center px-4 py-2 bg-construction-orange text-white rounded-lg hover:bg-orange-600 transition-colors font-medium shadow-sm whitespace-nowrap"
          >
            <Plus className="w-4 h-4 mr-2" />
            {t('inventory.addProduct')}
          </button>
        </div>
      </div>

      {/* Search Bar & Table */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4">
        <div className="relative flex-1 flex gap-2">
          <div className="relative flex-1">
             <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
             <input
               type="text"
               placeholder={t('inventory.searchPlaceholder')}
               className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700"
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
             />
          </div>
          <button
             onClick={() => setIsScannerOpen(true)}
             className="px-3 py-2 bg-slate-100 rounded-lg border border-slate-200 hover:bg-slate-200 text-slate-600"
             title="Scan Barcode"
          >
             <ScanBarcode className="w-5 h-5" />
          </button>
        </div>
        <select
          value={filterCategory}
          onChange={(e) => setFilterCategory(e.target.value)}
          className="px-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 bg-white"
        >
          <option value="all">{t('inventory.allCategories')}</option>
          {categoryOptions.map(cat => (
             <option key={cat.id} value={cat.id}>
                {'\u00A0'.repeat(cat.level * 3)}{cat.name}
             </option>
          ))}
        </select>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col relative">
        {/* DESKTOP TABLE VIEW */}
        <div className="hidden md:block overflow-x-auto flex-1">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 sticky top-0 z-10">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider whitespace-nowrap">{t('inventory.productName')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider whitespace-nowrap">{t('inventory.sku')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider whitespace-nowrap">{t('inventory.category')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-right whitespace-nowrap">{t('inventory.price')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-right whitespace-nowrap">{t('inventory.stock')}</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-center whitespace-nowrap">{t('common.actions')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {paginatedProducts.map((product) => {
                const isLowStock = product.stock < (product.minStock || 20);
                return (
                  <tr key={product.id} className={`hover:bg-slate-50 transition-colors group ${isLowStock ? 'bg-red-50 border-l-4 border-red-500' : ''}`}>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center space-x-3">
                        {product.imageUrl && (
                          <div className="w-10 h-10 rounded-lg overflow-hidden border border-slate-200 bg-white shrink-0">
                            <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                          </div>
                        )}
                        <div>
                          <div className="font-medium text-slate-800 truncate max-w-[200px]" title={product.name}>{product.name}</div>
                          <div className="text-xs text-slate-400 mt-0.5">ID: {product.id}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="mb-2">
                         <div className="flex items-center text-xs">
                           <span className="w-10 text-slate-400 font-semibold uppercase">{product.unit}</span>
                           <span className="font-mono bg-slate-100 px-1.5 rounded text-slate-600 mr-2">{product.sku}</span>
                           <span className="font-mono text-slate-500">{product.barcode}</span>
                         </div>
                      </div>
                      {product.variants?.map((v) => (
                        <div key={v.id} className="flex items-center text-xs pl-2 border-l-2 border-construction-orange/30 mb-1">
                           <span className="w-12 text-construction-orange font-semibold uppercase truncate" title={v.name}>{v.name}</span>
                           <span className="font-mono bg-orange-50 px-1.5 rounded text-orange-700 mr-2">{v.code}</span>
                           {v.color && (
                             <span className="inline-block w-3 h-3 rounded-full border border-slate-200 mr-1 shadow-sm" style={{ backgroundColor: v.color }}></span>
                           )}
                           {v.size && (
                             <span className="text-slate-500 mr-1">[{v.size}]</span>
                           )}
                         </div>
                      ))}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="px-2 py-1 text-xs font-medium bg-slate-100 text-slate-600 rounded-full">
                        {getCategoryName(product.category)}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right font-medium text-slate-700 whitespace-nowrap">
                       <div className="text-sm">${product.price.toFixed(2)} <span className="text-slate-400 text-xs">/{product.unit}</span></div>
                       {product.branchPrices && product.branchPrices.length > 0 && (
                         <div className="text-[10px] text-blue-600 mt-1 flex items-center justify-end">
                           <Store className="w-3 h-3 mr-1" />
                           Multi-price
                         </div>
                       )}
                    </td>
                    <td className="px-6 py-4 text-right whitespace-nowrap">
                      <div className="flex flex-col items-end">
                        <div className={`font-bold flex items-center justify-end ${isLowStock ? 'text-red-600' : 'text-slate-700'}`}>
                          {isLowStock && (
                            <div className="flex items-center mr-2 bg-red-100 text-red-700 px-1.5 py-0.5 rounded text-[10px] uppercase font-bold tracking-wide shadow-sm">
                              <AlertTriangle className="w-3 h-3 mr-1" />
                              Low
                            </div>
                          )}
                          {product.stock} <span className="text-xs font-normal text-slate-500 ml-1">{product.unit}s</span>
                        </div>
                        <span className="text-[10px] text-slate-400">Min: {product.minStock || 20}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center whitespace-nowrap">
                      <div className="flex items-center justify-center space-x-2 opacity-50 group-hover:opacity-100 transition-opacity">
                        <button 
                          onClick={() => handleOpenEditModal(product)}
                          className="p-1.5 text-slate-500 hover:text-primary-600 hover:bg-primary-50 rounded transition-colors"
                        >
                          <Edit2 className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => onDeleteProduct(product.id)}
                          className="p-1.5 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {paginatedProducts.length === 0 && (
                <tr>
                  <td colSpan={6} className="text-center py-8 text-slate-400">
                    No products found matching your filters.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* MOBILE CARD VIEW */}
        <div className="md:hidden flex-1 overflow-y-auto bg-slate-50 p-4 space-y-3">
           {paginatedProducts.map((product) => {
              const isLowStock = product.stock < (product.minStock || 20);
              return (
                 <div 
                    key={product.id}
                    className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden relative"
                 >
                    {isLowStock && <div className="absolute top-0 right-0 w-3 h-3 bg-red-500 rounded-bl-lg z-10" />}

                    <div className="flex p-3 gap-3">
                       {/* Image */}
                       <div className="w-20 h-20 bg-slate-100 rounded-lg flex-shrink-0 overflow-hidden border border-slate-100">
                          {product.imageUrl ? (
                             <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                          ) : (
                             <div className="w-full h-full flex items-center justify-center text-slate-300">
                                <Box className="w-8 h-8" />
                             </div>
                          )}
                       </div>

                       {/* Content */}
                       <div className="flex-1 min-w-0 flex flex-col justify-between">
                          <div>
                             <h3 className="font-bold text-slate-800 text-sm truncate">{product.name}</h3>
                             <p className="text-xs text-slate-500 truncate">{getCategoryName(product.category)}</p>
                             <div className="flex items-center gap-2 mt-1">
                                <span className="text-xs font-mono bg-slate-100 px-1.5 rounded text-slate-600">{product.sku}</span>
                                {product.variants && product.variants.length > 0 && (
                                   <span className="text-[10px] bg-orange-100 text-orange-700 px-1.5 rounded font-bold">
                                      {product.variants.length} Variants
                                   </span>
                                )}
                             </div>
                          </div>

                          <div className="flex justify-between items-end mt-2">
                             <div>
                                <span className="text-lg font-bold text-primary-600">${product.price}</span>
                                <span className="text-xs text-slate-400 ml-1">/{product.unit}</span>
                             </div>
                             <div className={`text-sm font-bold ${isLowStock ? 'text-red-600' : 'text-slate-700'}`}>
                                {product.stock} {product.unit}
                             </div>
                          </div>
                       </div>
                    </div>

                    {/* Actions Footer */}
                    <div className="grid grid-cols-2 border-t border-slate-100 divide-x divide-slate-100">
                       <button 
                          onClick={() => handleOpenEditModal(product)}
                          className="py-2.5 flex items-center justify-center text-slate-600 hover:bg-slate-50 text-sm font-medium"
                       >
                          <Edit2 className="w-4 h-4 mr-2" /> Edit
                       </button>
                       <button 
                          onClick={() => onDeleteProduct(product.id)}
                          className="py-2.5 flex items-center justify-center text-red-600 hover:bg-red-50 text-sm font-medium"
                       >
                          <Trash2 className="w-4 h-4 mr-2" /> Delete
                       </button>
                    </div>
                 </div>
              );
           })}
           {paginatedProducts.length === 0 && (
              <div className="text-center py-10 text-slate-400">
                 <Box className="w-12 h-12 mx-auto mb-2 opacity-20" />
                 <p>No products found.</p>
              </div>
           )}
        </div>
      </div>

      {/* Mobile FAB */}
      <button 
          onClick={handleOpenAddModal}
          className="md:hidden fixed bottom-20 right-6 w-14 h-14 bg-construction-orange text-white rounded-full shadow-lg flex items-center justify-center z-40 hover:bg-orange-600 active:scale-95 transition-all"
      >
          <Plus className="w-8 h-8" />
      </button>

      <BarcodeScanner 
         isOpen={isScannerOpen} 
         onClose={() => setIsScannerOpen(false)} 
         onScan={handleScan}
         dummyCodes={products.map(p => p.barcode).filter(Boolean) as string[]}
      />

      {/* AI Modal - Included in existing code, ensured presence */}

      {/* Main Add/Edit Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
              <h3 className="text-xl font-bold text-slate-800">
                {editingId ? t('common.edit') : t('common.add')} Product
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="flex border-b border-slate-200 bg-white overflow-x-auto no-scrollbar">
               {[
                 { id: 'general', label: 'General Info', icon: Box },
                 { id: 'physical', label: 'Physical Attributes', icon: Scale },
                 { id: 'pricing', label: 'Pricing & Branches', icon: DollarSign },
                 { id: 'variants', label: 'Variants', icon: Layers },
               ].map(tab => {
                 const Icon = tab.icon;
                 return (
                   <button
                     key={tab.id}
                     onClick={() => setActiveTab(tab.id as any)}
                     className={`flex-1 flex items-center justify-center px-6 py-5 text-lg font-semibold transition-all whitespace-nowrap min-w-fit outline-none focus:outline-none select-none ${
                       activeTab === tab.id 
                         ? 'border-b-4 border-construction-orange text-construction-orange bg-orange-50' 
                         : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50 border-b-4 border-transparent'
                     }`}
                   >
                     <Icon className="w-6 h-6 mr-3" />
                     {tab.label}
                   </button>
                 );
               })}
            </div>

            <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 bg-slate-50/50">
              {activeTab === 'general' && (
                <div className="space-y-6 animate-fade-in">
                   <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* Image Upload Section */}
                        <div className="md:col-span-2 flex justify-center">
                           <div className="relative group w-32 h-32 rounded-xl overflow-hidden border-2 border-dashed border-slate-300 hover:border-primary-500 transition-colors bg-slate-50">
                              {formData.imageUrl ? (
                                 <img src={formData.imageUrl} alt="Product" className="w-full h-full object-cover" />
                              ) : (
                                 <div className="w-full h-full flex flex-col items-center justify-center text-slate-400">
                                    <ImageIcon className="w-8 h-8 mb-1" />
                                    <span className="text-xs">Upload</span>
                                 </div>
                              )}
                              <input 
                                 type="file" 
                                 ref={fileInputRef} 
                                 className="absolute inset-0 opacity-0 cursor-pointer" 
                                 accept="image/*"
                                 onChange={handleImageUpload}
                              />
                              {formData.imageUrl && (
                                 <button 
                                    type="button" 
                                    onClick={handleRemoveImage} 
                                    className="absolute top-1 right-1 bg-white rounded-full p-1 shadow-sm text-red-500 hover:bg-red-50"
                                 >
                                    <X className="w-3 h-3" />
                                 </button>
                              )}
                           </div>
                        </div>

                        <div className="md:col-span-2">
                          <label className="block text-sm font-medium text-slate-700 mb-1">{t('inventory.productName')} *</label>
                          <input
                            type="text"
                            name="name"
                            required
                            value={formData.name}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">{t('inventory.category')} *</label>
                          <select
                            name="category"
                            required
                            value={formData.category}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white"
                          >
                             <option value="">Select</option>
                             {categoryOptions.map(cat => (
                               <option key={cat.id} value={cat.id}>
                                  {'\u00A0'.repeat(cat.level * 3)}{cat.name}
                               </option>
                             ))}
                          </select>
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">{t('inventory.sku')}</label>
                           <input
                            type="text"
                            name="sku"
                            value={formData.sku}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-mono"
                          />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">Barcode</label>
                           <input
                            type="text"
                            name="barcode"
                            value={formData.barcode}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 font-mono"
                          />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">{t('inventory.stock')}</label>
                           <input
                            type="number"
                            name="stock"
                            min="0"
                            value={formData.stock}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                          />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">Min Stock</label>
                           <input
                            type="number"
                            name="minStock"
                            min="0"
                            value={formData.minStock}
                            onChange={handleInputChange}
                            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
                          />
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-slate-700 mb-1">Unit</label>
                           <select
                              name="unit"
                              required
                              value={formData.unit}
                              onChange={handleInputChange}
                              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white"
                           >
                              <option value="">Select</option>
                              {units.map(u => (
                                 <option key={u.id} value={u.symbol}>{u.name} ({u.symbol})</option>
                              ))}
                           </select>
                        </div>
                      </div>
                   </div>
                </div>
              )}

              {activeTab === 'physical' && (
                 <div className="space-y-6 animate-fade-in">
                    <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                       <h4 className="font-bold text-slate-800 mb-4 flex items-center"><Ruler className="w-5 h-5 mr-2" /> Dimensions & Weight</h4>
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div>
                             <label className="block text-sm font-medium text-slate-700 mb-1">Weight (kg)</label>
                             <input type="number" value={formData.physical?.weight || 0} onChange={e => handlePhysicalChange('weight', e.target.value)} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                          </div>
                          <div className="grid grid-cols-3 gap-2">
                             <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Length (cm)</label>
                                <input type="number" value={formData.physical?.depth || 0} onChange={e => handlePhysicalChange('depth', e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg" />
                             </div>
                             <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Width (cm)</label>
                                <input type="number" value={formData.physical?.width || 0} onChange={e => handlePhysicalChange('width', e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg" />
                             </div>
                             <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Height (cm)</label>
                                <input type="number" value={formData.physical?.height || 0} onChange={e => handlePhysicalChange('height', e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg" />
                             </div>
                          </div>
                       </div>
                    </div>
                 </div>
              )}

              {activeTab === 'pricing' && (
                <div className="space-y-6 animate-fade-in">
                   <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                         <div>
                            <label className="block text-sm font-bold text-slate-800 mb-2">{t('inventory.price')} (Selling Price)</label>
                            <div className="relative">
                               <span className="absolute left-3 top-2.5 text-slate-400 font-bold">$</span>
                               <input
                                 type="number"
                                 name="price"
                                 required
                                 min="0"
                                 step="0.01"
                                 value={formData.price}
                                 onChange={handleInputChange}
                                 className="w-full pl-8 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 text-lg font-bold text-slate-800"
                               />
                            </div>
                         </div>
                         <div>
                            <label className="block text-sm font-bold text-slate-800 mb-2">Cost Price (For Profit Calc)</label>
                            <div className="relative">
                               <span className="absolute left-3 top-2.5 text-slate-400 font-bold">$</span>
                               <input
                                 type="number"
                                 name="costPrice"
                                 min="0"
                                 step="0.01"
                                 value={formData.costPrice}
                                 onChange={handleInputChange}
                                 className="w-full pl-8 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 text-lg font-medium text-slate-600"
                               />
                            </div>
                         </div>
                      </div>
                   </div>
                </div>
              )}

              {activeTab === 'variants' && (
                <div className="space-y-6 animate-fade-in">
                   <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                      <div className="flex justify-between items-center mb-4">
                        <h4 className="font-bold text-slate-800">Product Variants</h4>
                        <button 
                          type="button" 
                          onClick={handleAddVariant}
                          className="text-sm flex items-center text-primary-600 font-medium hover:text-primary-700 bg-primary-50 px-3 py-1.5 rounded-lg transition-colors"
                        >
                          <Plus className="w-4 h-4 mr-1" /> {t('common.add')} Variant
                        </button>
                      </div>

                      {variants.length === 0 ? (
                        <div className="text-center py-8 text-slate-400 border-2 border-dashed border-slate-100 rounded-lg">
                          No variants added.
                        </div>
                      ) : (
                        <div className="space-y-4">
                           {variants.map((variant, index) => {
                              const factor = variant.conversionFactor || 1;
                              const isBundle = factor > 0 && factor < 1;
                              const displayRatio = isBundle ? Math.round(1/factor) : factor;

                              return (
                                <div key={index} className="bg-slate-50 p-4 rounded-xl border border-slate-200 relative group">
                                   <button 
                                      type="button"
                                      onClick={() => handleRemoveVariant(index)}
                                      className="absolute top-2 right-2 p-1 text-slate-400 hover:text-red-50 opacity-0 group-hover:opacity-100 transition-opacity"
                                    >
                                      <Trash2 className="w-4 h-4" />
                                    </button>

                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-3">
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Variant Unit</label>
                                          <select
                                            value={variant.name}
                                            onChange={e => handleVariantChange(index, 'name', e.target.value)}
                                            className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm bg-white"
                                          >
                                            <option value="">Select</option>
                                            {Object.entries(unitsByCategory).map(([cat, catUnits]) => (
                                              <optgroup key={cat} label={cat}>
                                                {(catUnits as UnitDefinition[]).map(u => (
                                                  <option key={u.id} value={u.symbol}>{u.name} ({u.symbol})</option>
                                                ))}
                                              </optgroup>
                                            ))}
                                          </select>
                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Code / SKU</label>
                                          <input type="text" value={variant.code} onChange={e => handleVariantChange(index, 'code', e.target.value)} className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm bg-white font-mono" />
                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Color (Hex)</label>
                                          <div className="flex items-center">
                                             <input type="color" value={variant.color || '#000000'} onChange={e => handleVariantChange(index, 'color', e.target.value)} className="h-8 w-8 mr-2 p-0 border-0 rounded overflow-hidden" />
                                             <input type="text" value={variant.color || ''} onChange={e => handleVariantChange(index, 'color', e.target.value)} className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm bg-white" placeholder="#RRGGBB" />
                                          </div>
                                       </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                                       <div className="bg-white p-2 rounded border border-slate-200 flex items-center text-sm">
                                          <span className="text-slate-500 mr-2 text-xs uppercase font-bold">Ratio:</span>
                                          <select
                                              value={isBundle ? 'bundle' : 'sub'}
                                              onChange={(e) => handleVariantRelationChange(index, displayRatio, e.target.value as 'bundle' | 'sub')}
                                              className="px-2 py-1 text-xs border rounded bg-slate-50 mr-2"
                                            >
                                              <option value="sub">Sub-unit</option>
                                              <option value="bundle">Bundle</option>
                                            </select>
                                            <input 
                                              type="number" 
                                              min="1"
                                              value={displayRatio}
                                              onChange={(e) => handleVariantRelationChange(index, parseFloat(e.target.value) || 1, isBundle ? 'bundle' : 'sub')}
                                              className="w-16 px-1 py-0.5 border rounded text-center font-bold mx-1"
                                            />
                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Selling Price</label>
                                          <div className="relative">
                                            <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 text-xs">$</span>
                                            <input
                                              type="number"
                                              value={variant.price}
                                              onChange={e => handleVariantChange(index, 'price', e.target.value)}
                                              className="w-full pl-6 px-3 py-1.5 border border-slate-300 rounded text-sm font-bold text-slate-700"
                                              placeholder="Price"
                                            />
                                          </div>
                                       </div>
                                       <div>
                                          <label className="block text-xs font-medium text-slate-500 mb-1">Cost Price</label>
                                          <div className="relative">
                                            <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 text-xs">$</span>
                                            <input
                                              type="number"
                                              value={variant.costPrice || 0}
                                              onChange={e => handleVariantChange(index, 'costPrice', e.target.value)}
                                              className="w-full pl-6 px-3 py-1.5 border border-slate-300 rounded text-sm font-medium text-slate-600"
                                              placeholder="Cost"
                                            />
                                          </div>
                                       </div>
                                    </div>
                                </div>
                              );
                           })}
                        </div>
                      )}
                   </div>
                </div>
              )}

            </form>

            <div className="p-4 border-t border-slate-100 flex justify-end items-center bg-white shrink-0 space-x-3">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-5 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  {t('common.cancel')}
                </button>
                <button
                  type="button"
                  onClick={handleSubmit}
                  className="px-5 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 transition-colors shadow-sm flex items-center"
                >
                  <Check className="w-4 h-4 mr-2" />
                  {t('common.save')}
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export enum Category {
  CEMENT = 'Cement & Concrete',
  STEEL = 'Steel & Metal',
  WOOD = 'Wood & Lumber',
  PAINT = 'Paints & Finishes',
  TOOLS = 'Tools & Hardware',
  PLUMBING = 'Plumbing',
  ELECTRICAL = 'Electrical',
  CONSUMABLES = 'General Consumables'
}

export type UnitCategory = 'Weight' | 'Length' | 'Quantity';

export interface UnitDefinition {
  id: string;
  name: string;      // e.g. Kilogram
  symbol: string;    // e.g. kg
  category: UnitCategory;
  baseFactor: number; // 1 for base unit (e.g. g), 1000 for kg
  isBase: boolean;   // True if this is the reference unit
}

export interface CategoryItem {
  id: string;
  name: string;
  parentId: string | null; // null for root categories
  description?: string;
}

export interface ProductVariant {
  id: string;
  name: string;      // e.g., 'Piece', 'Small', 'Red' (Unit Name or Variant Name)
  code: string;      // SKU/Code for the variant
  barcode: string;   // Barcode for the variant
  conversionFactor: number; // How many variants in the main unit
  price: number;     // Price per variant
  costPrice?: number; // Cost price per variant
  color?: string;    // New: Color specification (e.g., 'Red', '#FF0000')
  size?: string;     // New: Size specification (e.g., 'XL', '10mm')
}

export interface ProductInventory {
  warehouseId: string;
  quantity: number;
}

export interface BranchPrice {
  branchId: string;
  price: number;
}

export interface ProductPhysical {
  weight?: number; // kg
  width?: number;  // cm
  height?: number; // cm
  depth?: number;  // cm (length)
}

export interface Product {
  id: string;
  name: string;
  category: Category | string; 
  price: number;     // Base Sell Price (Global)
  costPrice?: number; // Base Cost Price (For Profit Calc)
  branchPrices?: BranchPrice[]; // Overrides per branch
  stock: number;     // Stock count in MAIN units (Aggregate Total)
  minStock?: number; // Minimum stock threshold for alerts
  warehouseInventory?: ProductInventory[]; // Breakdown by warehouse
  unit: string;      // Name of the MAIN unit (e.g., 'bag', 'box')
  physical?: ProductPhysical; // New: Physical attributes
  imageUrl?: string;
  sku: string;       // SKU of MAIN unit
  barcode: string;   // Barcode of MAIN unit
  variants?: ProductVariant[]; // List of sub-products/variants
}

export interface CartItem extends Product {
  quantity: number;
  // Handling multi-unit/variant logic
  selectedVariantId?: string; // null if main unit, string if variant
  sellPrice: number; 
  sellUnit: string;  
  sellConversionFactor: number; // 1 for main, X for variant
}

export interface Sale {
  id: string;
  items: CartItem[];
  subtotal?: number; // Raw total before discount/tax
  discountAmount?: number; // Deduction amount
  total: number; // Final payable amount
  date: string;
  paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit';
  paymentStatus: 'paid' | 'unpaid' | 'partial'; // Track debt status
  amountReceived?: number; // Amount given by customer
  change?: number; // Change returned
  remainingAmount?: number; // Amount left to pay (for credit/partial)
  status: 'completed' | 'voided'; // Order status
  syncStatus?: 'synced' | 'pending' | 'failed'; // Track sync state
  customerId?: string; // Link to customer
  customerName?: string; // Snapshot of name
  pointsRedeemed?: number; // Points used
  pointsEarned?: number; // Points gained
  userId?: string; // ID of the staff who processed the sale
  userName?: string; // Name of the staff who processed the sale
}

export interface EstimateRequest {
  query: string;
}

export interface EstimateResultItem {
  productName: string;
  estimatedQuantity: number;
  unit: string;
  reasoning: string;
  matchedProductId?: string; // If found in inventory
}

// --- AI Inventory & Business Analysis Types ---
export interface ReorderSuggestion {
  productId: string;
  productName: string;
  currentStock: number;
  suggestedReorderQty: number;
  priority: 'High' | 'Medium' | 'Low';
  reasoning: string;
}

export interface NewProductSuggestion {
  name: string;
  categoryName: string;
  estimatedPrice: number;
  reasoning: string;
  suggestedUnit: string;
}

export interface BundleSuggestion {
  bundleName: string;
  components: string[];
  estimatedPrice: number;
  reasoning: string;
  targetAudience: string;
}

export interface InventoryAnalysisResult {
  reorders: ReorderSuggestion[];
  newProducts: NewProductSuggestion[];
  bundles: BundleSuggestion[];
}

export interface BusinessInsight {
  summary: string;
  trendDirection: 'up' | 'down' | 'stable';
  actionItems: string[];
  predictedRevenueNextWeek: number;
