  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false); 

  // Discount State
  const [manualDiscount, setManualDiscount] = useState<{ type: 'percent' | 'fixed', value: number } | null>(null);
  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);

  // Loyalty State
  const [redeemPoints, setRedeemPoints] = useState<number>(0);

  // Checkout & Payment State
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  // Receipt State
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);

  // Customer & Recall State
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [customerSearch, setCustomerSearch] = useState('');
  const [isRecallModalOpen, setIsRecallModalOpen] = useState(false);

  // --- Calculations ---
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);

  // 1. Apply Discounts
  // A. Customer Level Discount
  const customerDiscountPercent = customerLevel?.discountPercentage || 0;
  const customerDiscountAmount = customerDiscountPercent > 0 
    ? rawSubtotal * (customerDiscountPercent / 100) 
    : 0;

  // B. Manual Discount
  let manualDiscountAmount = 0;
  if (manualDiscount) {
    if (manualDiscount.type === 'percent') {
      manualDiscountAmount = rawSubtotal * (manualDiscount.value / 100);
    } else {
      manualDiscountAmount = manualDiscount.value;
    }
  }

  // C. Loyalty Discount
  const redeemRate = settings?.loyaltyProgram?.redeemRate || 100;
  const loyaltyDiscountAmount = redeemPoints > 0 ? redeemPoints / redeemRate : 0;

  // Total Discount
  let discountAmount = Math.min(customerDiscountAmount + manualDiscountAmount + loyaltyDiscountAmount, rawSubtotal);
  let discountedSubtotal = rawSubtotal - discountAmount;

  // 2. Apply Tax
  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       finalTotal = discountedSubtotal;
    }
  }

  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - finalTotal);
  const remainingCash = Math.max(0, finalTotal - receivedAmount);
  const remainingDebt = Math.max(0, finalTotal - receivedAmount);

  // --- Broadcast Channel for Customer Display ---
  const getDisplayPayload = () => {
    const now = new Date();
    const activePromotions = promotions?.filter(p => {
      if (!p.isActive) return false;
      const start = p.startDate ? new Date(p.startDate) : null;
      const end = p.endDate ? new Date(p.endDate) : null;
      if (end) end.setHours(23, 59, 59, 999);
      if (start && now < start) return false;
      if (end && now > end) return false;
      return true;
    }) || [];

    return {
      type: isCheckoutOpen ? 'CHECKOUT' : (cart.length === 0 ? 'RESET' : 'UPDATE'),
      cart: cart,
      subtotal: rawSubtotal,
      discount: discountAmount,
      tax: taxAmount,
      total: finalTotal,
      customer: selectedCustomer,
      paymentMethod: paymentMethod,
      amountReceived: receivedAmount,
      change: change,
      companyName: settings?.companyName,
      settings: settings?.customerDisplay,
      activePromotions: activePromotions
    };
  };

  useEffect(() => {
    if (settings?.customerDisplay?.enabled) {
      const channel = new BroadcastChannel('customer_display_channel');
      const payload = getDisplayPayload();
      channel.postMessage(payload);
      channel.onmessage = (event) => {
        if (event.data && event.data.type === 'REQUEST_INITIAL_STATE') {
           channel.postMessage(getDisplayPayload());
        }
      };
      return () => channel.close();
    }
  }, [cart, rawSubtotal, discountAmount, taxAmount, finalTotal, selectedCustomer, isCheckoutOpen, paymentMethod, receivedAmount, change, settings, promotions]);

  const handleOpenCustomerDisplay = () => {
    window.open('/customer-display', 'CustomerDisplay', 'width=1024,height=768,menubar=no,toolbar=no,location=no,status=no');
    setTimeout(() => {
       const channel = new BroadcastChannel('customer_display_channel');
       channel.postMessage(getDisplayPayload());
       channel.close();
    }, 1000);
  };

  useEffect(() => {
     setRedeemPoints(0);
  }, [selectedCustomer]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  const filteredCustomers = useMemo(() => {
    return customers.filter(c => 
      c.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      c.phone.includes(customerSearch) ||
      c.code.toLowerCase().includes(customerSearch.toLowerCase())
    );
  }, [customers, customerSearch]);

  const handleBarcodeScan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;
    performScan(searchTerm);
  };

  const performScan = (code: string) => {
    const mainMatch = products.find(p => p.barcode === code || p.sku === code);
    if (mainMatch) {
      addToCart(mainMatch, 1, undefined);
      setSearchTerm(''); 
      return;
    }

    for (const p of products) {
      if (p.variants) {
        const variantMatch = p.variants.find(v => v.barcode === code || v.code === code);
        if (variantMatch) {
          addToCart(p, 1, variantMatch.id);
          setSearchTerm('');
          return;
        }
      }
    }
    if (isScannerOpen) alert(`Product not found: ${code}`);
  };

  const handleAiItemsAdded = (items: EstimateResultItem[]) => {
    items.forEach(est => {
      if (est.matchedProductId) {
        const product = products.find(p => p.id === est.matchedProductId);
        if (product) {
          addToCart(product, Math.ceil(est.estimatedQuantity), undefined);
        }
      }
    });
  };

  // --- Hold & Recall Logic ---
  const handleHoldOrder = () => {
    if (cart.length === 0) return;
    const note = prompt("Optional note for this hold (e.g., 'Forgot Wallet'):");
    holdCurrentOrder(selectedCustomer, note || undefined);
    setSelectedCustomer(null);
    setManualDiscount(null);
    setRedeemPoints(0);
  };

  const handleRecall = (orderId: string) => {
    const restored = recallOrder(orderId);
    if (restored) {
      setSelectedCustomer(restored.customer || null);
      setIsRecallModalOpen(false);
    }
  };

  const handleCheckoutClick = () => {
    setReceivedAmountStr('');
    setPaymentMethod('cash');
    setIsCheckoutOpen(true);
  };

  const handlePaymentMethodChange = (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => {
    if (method === 'credit' && !selectedCustomer) {
      alert("Please select a customer first to use Credit/Debt.");
      return;
    }
    setPaymentMethod(method);
    setReceivedAmountStr('');
  };

  const handleProcessPayment = async () => {
    if (paymentMethod === 'cash' && receivedAmount < finalTotal) {
      alert("Insufficient amount received!");
      return;
    }

    if (paymentMethod === 'credit') {
        if (!selectedCustomer) {
            alert("Credit payment requires a registered customer!");
            return;
        }
        if (receivedAmount > finalTotal) {
            alert("Deposit cannot be more than the total amount.");
            return;
        }
    }

    setIsProcessing(true);

    let finalReceived = 0;
    let finalChange = 0;

    if (paymentMethod === 'cash') {
        finalReceived = receivedAmount;
        finalChange = change;
    } else if (paymentMethod === 'credit') {
        finalReceived = receivedAmount;
        finalChange = 0;
    } else {
        finalReceived = finalTotal;
        finalChange = 0;
    }

    try {
      const sale = await onProcessSale(
        cart, 
        finalTotal, 
        selectedCustomer?.id, 
        discountAmount, 
        rawSubtotal,
        paymentMethod,
        finalReceived,
        finalChange,
        redeemPoints
      );

      if (settings?.customerDisplay?.enabled) {
        const channel = new BroadcastChannel('customer_display_channel');
        channel.postMessage({
          type: 'SUCCESS',
          total: finalTotal,
          change: finalChange,
          paymentMethod: paymentMethod,
          companyName: settings?.companyName
        });
        setTimeout(() => channel.close(), 100);
      }

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setManualDiscount(null); 
      setRedeemPoints(0);
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleNumPadClick = (val: string) => {
    if (val === 'C') {
      setReceivedAmountStr('');
    } else if (val === 'BS') {
      setReceivedAmountStr(prev => prev.slice(0, -1));
    } else if (val === '.') {
      if (!receivedAmountStr.includes('.')) {
        setReceivedAmountStr(prev => (prev === '' ? '0' : prev) + '.');
      }
    } else {
      setReceivedAmountStr(prev => {
        if (prev === '0') return val;
        return prev + val;
      });
    }
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const [tempDiscount, setTempDiscount] = useState<{ type: 'percent' | 'fixed', value: number }>({ type: 'percent', value: 0 });
  const barcodeList = useMemo(() => products.map(p => p.barcode).filter(Boolean), [products]);
  const receiptWidthClass = settings?.receiptPaperSize === '58mm' ? 'print-w-58mm' : settings?.receiptPaperSize === 'A4' ? 'print-w-A4' : 'print-w-80mm';

  return (
    <div className="flex flex-col lg:flex-row h-full gap-6 relative">
      <div className="flex-1 flex flex-col min-w-0 h-full">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-slate-800">{t('pos.newOrder')}</h2>
          <div className="flex space-x-2">
             {/* Recall Button */}
             <button 
               onClick={() => setIsRecallModalOpen(true)}
               className={`flex items-center px-3 py-2 rounded-lg transition-colors shadow-sm text-sm font-medium border relative ${
                 heldOrders.length > 0 
                   ? 'bg-orange-50 text-orange-700 border-orange-200 hover:bg-orange-100' 
                   : 'bg-white text-slate-400 border-slate-200 cursor-not-allowed'
               }`}
               disabled={heldOrders.length === 0}
               title="Recall Held Orders"
             >
               <ClipboardList className="w-4 h-4 mr-2" />
               <span className="hidden xl:inline">Recall</span>
               {heldOrders.length > 0 && (
                 <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[10px] w-5 h-5 flex items-center justify-center rounded-full font-bold shadow-sm">
                   {heldOrders.length}
                 </span>
               )}
             </button>

             {settings?.customerDisplay?.enabled && (
               <button 
                 onClick={handleOpenCustomerDisplay}
                 className="flex items-center px-3 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors shadow-sm text-sm font-medium"
                 title="Open Customer Facing Display"
               >
                 <Monitor className="w-4 h-4 mr-2" />
                 <span className="hidden xl:inline">Customer Screen</span>
               </button>
             )}
             <button 
              onClick={() => setIsCustomerModalOpen(true)}
              className={`flex items-center px-4 py-2 rounded-lg shadow-sm transition-all duration-200 font-medium text-sm border ${
                selectedCustomer 
                  ? 'bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100' 
                  : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
              }`}
            >
              <User className="w-4 h-4 mr-2" />
              {selectedCustomer ? (
                <span className="flex items-center">
                  {selectedCustomer.name}
                  {customerLevel && (
                    <span className="ml-2 flex items-center bg-white/50 px-1.5 py-0.5 rounded text-[10px] border border-blue-200">
                      <Star className="w-3 h-3 mr-1 fill-current text-yellow-500" />
                      {customerLevel.name}
                    </span>
                  )}
                </span>
              ) : t('pos.selectCustomer')}
            </button>
            <button 
              onClick={() => setIsAiModalOpen(true)}
              className="flex items-center px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-lg shadow-md hover:shadow-lg transition-all duration-200 font-medium text-sm"
            >
              <Sparkles className="w-4 h-4 mr-2" />
              <span className="hidden md:inline">{t('pos.aiEstimate')}</span>
              <span className="md:hidden">AI</span>
            </button>
          </div>
        </div>

        {/* ... Search Form & Product Grid ... */}
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 space-y-4">
          <form onSubmit={handleBarcodeScan} className="relative flex gap-2">
            <div className="relative flex-1">
               <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
               <input
                 type="text"
                 placeholder={t('pos.scanPlaceholder')}
                 className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 bg-slate-50 font-medium"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
                 autoFocus
               />
            </div>
            <button 
               type="button"
               onClick={() => setIsScannerOpen(true)}
               className="bg-slate-800 text-white px-4 rounded-lg hover:bg-slate-900 transition-colors flex items-center shadow-sm"
            >
               <ScanBarcode className="w-6 h-6" />
            </button>
          </form>

          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide -mx-1 px-1">
            <button
              onClick={() => setSelectedCategory('all')}
              className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors flex-shrink-0 ${
                selectedCategory === 'all' 
                  ? 'bg-slate-800 text-white' 
                  : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
              }`}
            >
              {t('pos.allItems')}
            </button>
            {Object.values(Category).map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors flex-shrink-0 ${
                  selectedCategory === cat 
                    ? 'bg-construction-orange text-white' 
                    : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto pr-1">
          {filteredProducts.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-slate-400">
              <Box className="w-12 h-12 mb-4 opacity-50" />
              <p>No products found.</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-20 md:pb-0">
              {filteredProducts.map((product) => {
                const hasVariants = product.variants && product.variants.length > 0;
                return (
                  <div 
                    key={product.id} 
                    onClick={() => !hasVariants && addToCart(product)}
                    className={`bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow flex flex-col ${!hasVariants ? 'cursor-pointer' : ''}`}
                  >
                    <div className="h-32 bg-slate-100 relative overflow-hidden">
                      {product.imageUrl ? (
                        <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                          <Box className="w-12 h-12" />
                        </div>
                      )}
                      <div className="absolute top-2 right-2 bg-white/90 backdrop-blur-sm px-2 py-1 rounded text-xs font-bold text-slate-700 shadow-sm">
                        {product.stock} {product.unit}
                      </div>
                      {product.sku && (
                         <div className="absolute bottom-2 left-2 bg-black/50 backdrop-blur-sm px-2 py-0.5 rounded text-[10px] text-white font-mono">
                           {product.sku}
                         </div>
                      )}
                    </div>
                    <div className="p-4 flex-1 flex flex-col">
                      <h3 className="font-bold text-slate-800 line-clamp-2 text-sm mb-1">{product.name}</h3>
                      <p className="text-xs text-slate-500 mb-3 line-clamp-1">{product.category}</p>

                      <div className="mt-auto">
                        <div className="flex justify-between items-center mb-3">
                          <span className="text-lg font-bold text-primary-600">${product.price.toFixed(2)}</span>
                        </div>
                        {hasVariants ? (
                          <div className="space-y-1">
                             <button onClick={(e) => { e.stopPropagation(); addToCart(product); }} className="w-full py-1.5 bg-slate-100 text-slate-700 rounded text-xs font-medium hover:bg-slate-200 transition-colors flex justify-between px-3"><span>{product.unit}</span><span>${product.price}</span></button>
                             {product.variants!.map(v => (
                               <button key={v.id} onClick={(e) => { e.stopPropagation(); addToCart(product, 1, v.id); }} className="w-full py-1.5 bg-orange-50 text-orange-700 rounded text-xs font-medium hover:bg-orange-100 transition-colors flex justify-between px-3"><span>{v.name}</span><span>${v.price}</span></button>
                             ))}
                          </div>
                        ) : (
                          <button className="w-full py-2 bg-slate-800 text-white rounded-lg text-sm font-medium hover:bg-slate-900 transition-colors flex items-center justify-center">
                            <Plus className="w-4 h-4 mr-1" /> {t('common.add')}
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {cartItemCount > 0 && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="lg:hidden fixed bottom-4 right-4 left-4 bg-slate-900 text-white p-4 rounded-xl shadow-2xl flex justify-between items-center z-30"
        >
          <div className="flex items-center">
            <div className="bg-orange-500 rounded-full w-8 h-8 flex items-center justify-center font-bold text-sm mr-3">
              {cartItemCount}
            </div>
            <span className="font-bold">{t('pos.viewCart')}</span>
          </div>
          <span className="font-bold text-lg">${finalTotal.toFixed(2)}</span>
        </button>
      )}

      {/* Cart Sidebar */}
      <div className={`
        fixed inset-y-0 right-0 z-40 w-full md:w-[400px] bg-white shadow-2xl transform transition-transform duration-300 ease-in-out lg:relative lg:translate-x-0 lg:shadow-none lg:w-[380px] lg:border-l lg:border-slate-200 flex flex-col
        ${isCartOpen ? 'translate-x-0' : 'translate-x-full'}
      `}>
        {/* Cart Header */}
        <div className="p-5 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
          <div className="flex items-center">
            <ShoppingCart className="w-5 h-5 text-slate-700 mr-2" />
            <h3 className="font-bold text-slate-800 text-lg">{t('pos.currentOrder')}</h3>
          </div>
          <div className="flex items-center space-x-2">
             <button 
                onClick={handleHoldOrder} 
                disabled={cart.length === 0}
                className="p-2 bg-orange-100 text-orange-700 rounded-lg hover:bg-orange-200 disabled:opacity-50 transition-colors"
                title="Hold / Suspend Order"
             >
                <PauseCircle className="w-5 h-5" />
             </button>
             <button 
               onClick={() => setIsCartOpen(false)}
               className="lg:hidden p-2 text-slate-500 hover:bg-slate-200 rounded-full"
             >
               <X className="w-6 h-6" />
             </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-4">
              <ShoppingCart className="w-16 h-16 opacity-20" />
              <p className="text-sm font-medium">{t('pos.emptyCart')}</p>
              <p className="text-xs text-center max-w-[200px]">{t('pos.emptyCartDesc')}</p>
            </div>
          ) : (
            cart.map((item, index) => (
              <div key={`${item.id}-${item.selectedVariantId || 'main'}`} className="flex items-center bg-white p-3 rounded-lg border border-slate-100 shadow-sm animate-fade-in">
                <div className="flex-1 min-w-0">
                  <h4 className="font-bold text-slate-800 text-sm truncate">{item.name}</h4>
                  <div className="flex items-center text-xs text-slate-500 mt-1">
                    <span className="bg-slate-100 px-1.5 py-0.5 rounded mr-2">{item.sellUnit}</span>
                    <span>${item.sellPrice.toFixed(2)}</span>
                  </div>
                </div>
                <div className="flex items-center space-x-1 mx-2">
                  <button onClick={() => updateQuantity(index, -1)} className="w-7 h-7 flex items-center justify-center rounded bg-slate-100 hover:bg-slate-200 text-slate-600 transition-colors"><Minus className="w-3 h-3" /></button>
                  <input type="number" min="1" value={item.quantity.toString()} onChange={(e) => { const val = parseInt(e.target.value); if (!isNaN(val) && val >= 1) { setQuantity(index, val); } }} className="w-12 h-7 text-center text-sm font-bold text-slate-800 bg-transparent border border-slate-200 rounded focus:border-primary-500 focus:outline-none mx-1" />
                  <button onClick={() => updateQuantity(index, 1)} className="w-7 h-7 flex items-center justify-center rounded bg-slate-100 hover:bg-slate-200 text-slate-600 transition-colors"><Plus className="w-3 h-3" /></button>
                </div>
                <div className="text-right min-w-[60px]">
                  <p className="font-bold text-slate-800 text-sm">${(item.sellPrice * item.quantity).toFixed(2)}</p>
                  <button onClick={() => removeFromCart(index)} className="text-xs text-red-400 hover:text-red-600 mt-1">{t('common.delete')}</button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-200 space-y-3">
          {selectedCustomer && (
             <div className="flex justify-between items-center p-3 bg-blue-50 border border-blue-100 rounded-lg text-sm text-blue-900 mb-2">
                <div className="flex items-center">
                   <User className="w-4 h-4 mr-2 text-blue-600" />
                   <div>
                      <span className="font-bold block">{selectedCustomer.name}</span>
                      <div className="flex items-center space-x-2">
                        {customerLevel && <span className="text-xs text-blue-600 flex items-center"><Star className="w-3 h-3 mr-1 fill-current" />{customerLevel.name}</span>}
                        <span className="text-xs font-medium bg-blue-100 text-blue-800 px-1.5 rounded">{selectedCustomer.loyaltyPoints} pts</span>
                      </div>
                   </div>
                </div>
                <button onClick={() => setSelectedCustomer(null)} className="text-blue-400 hover:text-blue-600"><X className="w-4 h-4" /></button>
             </div>
          )}

          <div className="space-y-2 text-sm text-slate-600">
