  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 500);
    return () => clearTimeout(timer);
  }, []);

  // --- Automated Notifications Logic ---
  useEffect(() => {
    if (!products.length) return;

    // 1. Check Low Stock
    const lowStockItems = products.filter(p => p.stock <= (p.minStock || 20));
    if (lowStockItems.length > 0) {
       const hasUnread = notifications.some(n => n.type === 'warning' && n.title === 'Low Stock Alert' && !n.read);
       if (!hasUnread) {
          addNotification({
             title: 'Low Stock Alert',
             message: `${lowStockItems.length} items are below minimum stock level.`,
             type: 'warning',
             link: '/inventory'
          });
       }
    }
  }, [products]); 

  useEffect(() => {
     // 2. Check Pending Approvals
     const pendingCount = [
        ...transfers, ...counts, ...receipts, ...adjustments, ...reservations
     ].filter(d => d.status === 'Draft').length;

     if (pendingCount > 0) {
        const hasUnread = notifications.some(n => n.type === 'info' && n.title === 'Pending Approvals' && !n.read);
        if (!hasUnread) {
           addNotification({
              title: 'Pending Approvals',
              message: `You have ${pendingCount} documents waiting for review.`,
              type: 'info',
              link: '/approvals'
           });
        }
     }
  }, [transfers, counts, receipts, adjustments, reservations]);


  const t = (key: string): string => {
    const keys = key.split('.');
    let current: any = translations[settings.language] || translations['en'];
    for (const k of keys) {
      if (current[k] === undefined) return key;
      current = current[k];
    }
    return typeof current === 'string' ? current : key;
  };

  const formatPrice = (amount: number): string => {
    const symbol = settings.currencySymbol || '$';
    return `${symbol}${Math.abs(amount).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const addNotification = (n: Omit<AppNotification, 'id' | 'timestamp' | 'read'>) => {
     const newNotif: AppNotification = {
        ...n,
        id: `notif-${Date.now()}-${Math.random()}`,
        timestamp: new Date().toISOString(),
        read: false
     };
     setNotifications(prev => [newNotif, ...prev]);
  };

  const markNotificationRead = (id: string) => {
     setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));
  };

  const clearAllNotifications = () => {
     setNotifications([]);
  };

  // --- Audit Logging ---
  const logAction = (action: AuditAction, details: string, severity: 'low' | 'medium' | 'high' | 'critical' = 'low', resourceId?: string) => {
    if (!currentUser) return;

    const newLog: AuditLog = {
      id: `aud-${Date.now()}`,
      action,
      userId: currentUser.id,
      userName: currentUser.name,
      details,
      timestamp: new Date().toISOString(),
      severity,
      resourceId
    };

    setAuditLogs(prev => [newLog, ...prev]);
  };

  // --- RESTORE DATA ---
  const restoreSystemData = (data: any) => {
    if (data.users) setUsers(data.users);
    if (data.products) setProducts(data.products);
    if (data.sales) setSales(data.sales);
    if (data.units) setUnits(data.units);
    if (data.categories) setCategories(data.categories);
    if (data.branches) setBranches(data.branches);
    if (data.posMachines) setPosMachines(data.posMachines);
    if (data.warehouses) setWarehouses(data.warehouses);
    if (data.locations) setLocations(data.locations);
    if (data.transfers) setTransfers(data.transfers);
    if (data.counts) setCounts(data.counts);
    if (data.reservations) setReservations(data.reservations);
    if (data.receipts) setReceipts(data.receipts);
    if (data.adjustments) setAdjustments(data.adjustments);
    if (data.customers) setCustomers(data.customers);
    if (data.customerLevels) setCustomerLevels(data.customerLevels);
    if (data.shifts) setShifts(data.shifts);
    if (data.shiftSchedules) setShiftSchedules(data.shiftSchedules);
    if (data.promotions) setPromotions(data.promotions);
    if (data.settings) setSettingsState(data.settings);

    logAction('SETTINGS_UPDATE', 'System data restored from backup', 'high');
  };

  // --- ACTIONS ---

  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number, 
    paymentMethod: any = 'cash',
    amountReceived?: number,
    change?: number,
    pointsRedeemed: number = 0
  ): Promise<Sale> => {

    // Calculate Earned Points
    let pointsEarned = 0;
    if (settings.loyaltyProgram?.enabled && customerId) {
       const earnRate = settings.loyaltyProgram.earnRate || 10;
       pointsEarned = Math.floor(total / earnRate);
    }

    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items, total, subtotal, discountAmount,
      date: new Date().toISOString(),
      paymentMethod, amountReceived, change, customerId,
      customerName: customerId ? customers.find(c => c.id === customerId)?.name : undefined,
      status: 'completed',
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      remainingAmount: paymentMethod === 'credit' ? Math.max(0, total - (amountReceived || 0)) : 0,
      syncStatus: 'pending',
      pointsRedeemed,
      pointsEarned,
      userId: currentUser?.id,
      userName: currentUser?.name,
      type: 'sale'
    };

    setSales(prev => [newSale, ...prev]);

    // Update Inventory
    setProducts(prevProducts => prevProducts.map(product => {
      const cartItem = items.find(item => item.id === product.id);
      if (cartItem) {
        return { ...product, stock: product.stock - cartItem.quantity };
      }
      return product;
    }));

    // Update Customer Points
    if (customerId) {
        setCustomers(prev => prev.map(c => {
          if (c.id === customerId) {
              return { 
                ...c, 
                loyaltyPoints: Math.max(0, (c.loyaltyPoints || 0) - pointsRedeemed + pointsEarned) 
              };
          }
          return c;
        }));
    }

    return newSale;
  };

  const processReturn = async (originalSale: Sale, itemsToReturn: { itemIndex: number, quantity: number }[], paymentMethod: string): Promise<Sale> => {
    // 1. Calculate Refund Total
    let refundTotal = 0;
    const returnedItems: CartItem[] = [];

    itemsToReturn.forEach(({ itemIndex, quantity }) => {
      const originalItem = originalSale.items[itemIndex];
      if (originalItem && quantity > 0) {
        // Simple logic: Refund amount is proportional to sell price * quantity
        // Advanced logic would prorate discount, tax, etc.
        refundTotal += originalItem.sellPrice * quantity;
        returnedItems.push({ ...originalItem, quantity });
      }
    });

    // 2. Create Refund Record (Negative Sale)
    const refundSale: Sale = {
      id: `R-${Date.now()}`,
      originalSaleId: originalSale.id,
      items: returnedItems,
      total: -refundTotal, // Negative indicates money out
      subtotal: -refundTotal,
      discountAmount: 0, // Ignoring prorated discount logic for simplicity
      date: new Date().toISOString(),
      paymentMethod: paymentMethod as any,
      paymentStatus: 'paid', // Refund is immediate usually
      amountReceived: -refundTotal,
      change: 0,
      remainingAmount: 0,
      status: 'completed',
      syncStatus: 'pending',
      customerId: originalSale.customerId,
      customerName: originalSale.customerName,
      userId: currentUser?.id,
      userName: currentUser?.name,
      type: 'return'
    };

    setSales(prev => [refundSale, ...prev]);

    // 3. Restore Inventory
    setProducts(prevProducts => prevProducts.map(product => {
      const returnedItem = returnedItems.find(item => item.id === product.id);
      if (returnedItem) {
        // Handle variant logic if necessary, here we assume quantity is in Base Units or managed by CartItem logic
        return { ...product, stock: product.stock + returnedItem.quantity };
      }
      return product;
    }));

    logAction('SALE_RETURN', `Processed refund for Sale #${originalSale.id}`, 'medium', refundSale.id);

    return refundSale;
  };

  const handleVoidSale = async (saleId: string) => {
     setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: 'voided' } : s));

     // Restore stock
     const saleToVoid = sales.find(s => s.id === saleId);
     if (saleToVoid) {
        setProducts(prevProducts => prevProducts.map(product => {
           const soldItem = saleToVoid.items.find(item => item.id === product.id);
           if (soldItem) {
              return { ...product, stock: product.stock + soldItem.quantity };
           }
           return product;
        }));
     }
     logAction('SALE_VOID', `Voided sale ${saleId} (Persistent)`, 'high', saleId);
  };

  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
     setSales(prev => prev.map(s => {
        if (s.id === saleId) {
           return {
              ...s,
              paymentStatus: 'paid',
              remainingAmount: 0,
              amountReceived: (s.amountReceived || 0) + amount
           };
        }
        return s;
     }));
  };

  // --- CRUD Wrappers (Direct State Manipulation for Persistence) ---
  const addProduct = (p: Product) => setProducts(prev => [...prev, p]);
  const updateProduct = (p: Product) => setProducts(prev => prev.map(item => item.id === p.id ? p : item));
  const deleteProduct = (id: string) => setProducts(prev => prev.filter(item => item.id !== id));

  const addCustomer = (c: Customer) => setCustomers(prev => [...prev, c]);
  const updateCustomer = (c: Customer) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item));
  const deleteCustomer = (id: string) => setCustomers(prev => prev.filter(item => item.id !== id));

  const addCustomerLevel = (l: CustomerLevel) => setCustomerLevels(prev => [...prev, l]);
  const updateCustomerLevel = (l: CustomerLevel) => setCustomerLevels(prev => prev.map(item => item.id === l.id ? l : item));
  const deleteCustomerLevel = (id: string) => setCustomerLevels(prev => prev.filter(item => item.id !== id));

  const addUser = (u: User) => {
    setUsers(prev => [...prev, u]);
    logAction('USER_CREATE', `Created user ${u.name} (${u.role})`, 'medium', u.id);
  };
  const updateUser = (u: User) => setUsers(prev => prev.map(item => item.id === u.id ? u : item));
  const deleteUser = (id: string) => {
    setUsers(prev => prev.filter(item => item.id !== id));
    logAction('USER_DELETE', `Deleted user ID ${id}`, 'high', id);
  };

  const updateSettings = (s: SystemSettings) => {
    setSettingsState(s);
    logAction('SETTINGS_UPDATE', 'Updated system settings', 'medium');
  };

  const addUnit = (u: any) => setUnits(p => [...p, u]);
  const updateUnit = (u: any) => setUnits(p => p.map(x => x.id === u.id ? u : x));
  const deleteUnit = (id: string) => setUnits(p => p.filter(x => x.id !== id));

  const addCategory = (c: any) => setCategories(p => [...p, c]);
  const updateCategory = (c: any) => setCategories(p => p.map(x => x.id === c.id ? c : x));
  const deleteCategory = (id: string) => setCategories(p => p.filter(x => x.id !== id));

  const addBranch = (b: any) => setBranches(p => [...p, b]);
  const updateBranch = (b: any) => setBranches(p => p.map(x => x.id === b.id ? b : x));
  const deleteBranch = (id: string) => setBranches(p => p.filter(x => x.id !== id));

  const addPos = (pos: any) => setPosMachines(p => [...p, pos]);
  const updatePos = (pos: any) => setPosMachines(p => p.map(x => x.id === pos.id ? pos : x));
  const deletePos = (id: string) => setPosMachines(p => p.filter(x => x.id !== id));

  const addWarehouse = (w: any) => setWarehouses(p => [...p, w]);
  const updateWarehouse = (w: any) => setWarehouses(p => p.map(x => x.id === w.id ? w : x));
  const deleteWarehouse = (id: string) => setWarehouses(p => p.filter(x => x.id !== id));

  const addLocation = (l: any) => setLocations(p => [...p, l]);
  const updateLocation = (l: any) => setLocations(p => p.map(x => x.id === l.id ? l : x));
  const deleteLocation = (id: string) => setLocations(p => p.filter(x => x.id !== id));

  // --- Stock Docs ---
  const updateTransfer = (t: StockTransfer) => {
    if (transfers.find(x => x.id === t.id)) {
      setTransfers(prev => prev.map(item => item.id === t.id ? t : item));
    } else {
      setTransfers(prev => [t, ...prev]);
    }
  };
  const deleteTransfer = (id: string) => setTransfers(prev => prev.filter(item => item.id !== id));

  const updateCount = (c: StockCount) => {
    if (counts.find(x => x.id === c.id)) {
      setCounts(prev => prev.map(item => item.id === c.id ? c : item));
    } else {
      setCounts(prev => [c, ...prev]);
    }
  };
  const deleteCount = (id: string) => setCounts(prev => prev.filter(item => item.id !== id));

  const updateReservation = (r: StockReservation) => {
    if (reservations.find(x => x.id === r.id)) {
      setReservations(prev => prev.map(item => item.id === r.id ? r : item));
    } else {
      setReservations(prev => [r, ...prev]);
    }
  };
  const deleteReservation = (id: string) => setReservations(prev => prev.filter(item => item.id !== id));

  const updateReceipt = (r: StockReceipt) => {
    if (receipts.find(x => x.id === r.id)) {
      setReceipts(prev => prev.map(item => item.id === r.id ? r : item));
    } else {
      setReceipts(prev => [r, ...prev]);
    }
  };
  const deleteReceipt = (id: string) => setReceipts(prev => prev.filter(item => item.id !== id));

  const updateAdjustment = (a: StockAdjustment) => {
    if (adjustments.find(x => x.id === a.id)) {
      setAdjustments(prev => prev.map(item => item.id === a.id ? a : item));
    } else {
      setAdjustments(prev => [a, ...prev]);
    }
  };
  const deleteAdjustment = (id: string) => setAdjustments(prev => prev.filter(item => item.id !== id));

  // --- Status Change Logic (Simplified Client-side simulation) ---
  const handleStockStatusChange = (
    type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', 
    id: string, 
    status: DocumentStatus
  ) => {

    // Helper to update specific doc
    const updateDocStatus = (list: any[], setList: any) => {
       const doc = list.find(x => x.id === id);
       if (doc) {
          // If moving to Completed, update inventory
          if (status === 'Completed' && doc.status !== 'Completed') {
             // Basic inventory update logic
             if (type === 'transfer') {
               // Decrement Source, Increment Target
               // Simulation: We are updating products globally in this context
               // Real App: Update specific Warehouse Inventory
             } else if (type === 'receipt') {
               // Increment
               const items = doc.items;
               setProducts(prev => prev.map(p => {
                  const item = items.find((i: any) => i.productId === p.id);
                  if (item) return { ...p, stock: p.stock + item.quantity };
                  return p;
               }));
             } else if (type === 'adjustment') {
               // Increment (quantity can be negative)
               const items = doc.items;
               setProducts(prev => prev.map(p => {
                  const item = items.find((i: any) => i.productId === p.id);
                  if (item) return { ...p, stock: p.stock + item.quantity };
                  return p;
               }));
             } else if (type === 'count') {
               // Set absolute
               const items = doc.items;
               setProducts(prev => prev.map(p => {
                  const item = items.find((i: any) => i.productId === p.id);
                  if (item && item.countedQuantity !== undefined) return { ...p, stock: item.countedQuantity };
                  return p;
               }));
             }
          }
          setList((prev: any[]) => prev.map(item => item.id === id ? { ...item, status } : item));
          logAction('STOCK_APPROVE', `${type.toUpperCase()} ${doc.referenceNo} updated to ${status}`, 'medium', id);
       }
    };

    switch(type) {
      case 'transfer': updateDocStatus(transfers, setTransfers); break;
      case 'count': updateDocStatus(counts, setCounts); break;
      case 'reservation': updateDocStatus(reservations, setReservations); break;
      case 'receipt': updateDocStatus(receipts, setReceipts); break;
      case 'adjustment': updateDocStatus(adjustments, setAdjustments); break;
    }
  };

  const handleSyncOperation = (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
     // Mock Sync
     const newLog: SyncLog = {
        id: `sync-${Date.now()}`,
        timestamp: new Date().toISOString(),
        type,
        status: 'Success',
        details: 'Simulated sync completed successfully.',
        durationMs: Math.floor(Math.random() * 1000) + 200
     };
     setSyncLogs(prev => [newLog, ...prev]);
  };

  // --- Shifts ---
  const startShift = (branchId: string, startCash: number, notes?: string) => {
    if (!currentUser) return;
    const newShift: Shift = {
      id: `sh-${Date.now()}`,
      userId: currentUser.id,
      branchId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open'
    };
    setShifts(prev => [newShift, ...prev]);
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
    setShifts(prev => prev.map(s => {
      if (s.id === shiftId) {
        return {
          ...s,
          endTime: new Date().toISOString(),
          endCash,
          notes: notes ? (s.notes ? s.notes + '\n' + notes : notes) : s.notes,
          status: 'Closed'
        };
      }
      return s;
    }));
  };

  const addShiftSchedule = (s: ShiftSchedule) => setShiftSchedules(prev => [...prev, s]);
  const deleteShiftSchedule = (id: string) => setShiftSchedules(prev => prev.filter(x => x.id !== id));

  // --- Promotions ---
  const addPromotion = (p: Promotion) => setPromotions(prev => [...prev, p]);
  const updatePromotion = (p: Promotion) => setPromotions(prev => prev.map(item => item.id === p.id ? p : item));
  const deletePromotion = (id: string) => setPromotions(prev => prev.filter(item => item.id !== id));

  const value: GlobalContextType = {
    currentUser, setCurrentUser, users, products, sales, units, categories, branches, posMachines, warehouses, locations,
    transfers, counts, reservations, receipts, adjustments, syncLogs, customers, customerLevels, shifts, shiftSchedules, promotions, settings, isLoading,
    notifications, auditLogs,
    processSale, processReturn, addProduct, updateProduct, deleteProduct, addUnit, updateUnit, deleteUnit,
    addCategory, updateCategory, deleteCategory, addBranch, updateBranch, deleteBranch,
    addPos, updatePos, deletePos, addWarehouse, updateWarehouse, deleteWarehouse,
    addLocation, updateLocation, deleteLocation, addUser, updateUser, deleteUser,
    addCustomer, updateCustomer, deleteCustomer, addCustomerLevel, updateCustomerLevel, deleteCustomerLevel,
    updateTransfer, deleteTransfer, updateCount, deleteCount, updateReservation, deleteReservation,
    updateReceipt, deleteReceipt, updateAdjustment, deleteAdjustment,
    handleStockStatusChange, handleSyncOperation,
    startShift, endShift, addShiftSchedule, deleteShiftSchedule,
    addPromotion, updatePromotion, deletePromotion,
    updateSettings,
    settleSaleDebt, handleVoidSale,
    t, formatPrice,
    addNotification, markNotificationRead, clearAllNotifications,
    restoreSystemData, logAction
  };

  return (
    <GlobalContext.Provider value={value}>
      {children}
    </GlobalContext.Provider>
  );
};

import React, { useState, useMemo } from 'react';
import { Sale, CartItem } from '../types';
import { 
  Search, 
  Calendar, 
  Filter, 
  Eye, 
  RotateCcw, 
  Ban, 
  Printer, 
  CheckCircle, 
  XCircle,
  AlertTriangle,
  History,
  DollarSign,
  Wallet,
  ArrowLeftRight,
  Reply
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

interface SalesHistoryProps {
  sales: Sale[];
  onVoidSale: (id: string) => void;
}

export const SalesHistory: React.FC<SalesHistoryProps> = ({ sales, onVoidSale }) => {
  const { currentUser, settleSaleDebt, processReturn } = useGlobal();
  const [searchTerm, setSearchTerm] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'completed' | 'voided' | 'unpaid'>('all');

  // Modal State
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [isReturnMode, setIsReturnMode] = useState(false);
  const [returnQuantities, setReturnQuantities] = useState<Record<number, number>>({});

  const filteredSales = useMemo(() => {
    return sales.filter(sale => {
      const matchesSearch = 
        sale.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (sale.customerName && sale.customerName.toLowerCase().includes(searchTerm.toLowerCase()));

      let matchesStatus = true;
      if (statusFilter === 'completed') matchesStatus = sale.status === 'completed' && sale.paymentStatus === 'paid';
      else if (statusFilter === 'unpaid') matchesStatus = sale.paymentStatus === 'unpaid' || sale.paymentStatus === 'partial';
      else if (statusFilter === 'voided') matchesStatus = sale.status === 'voided';

      let matchesDate = true;
      if (startDate) {
        matchesDate = matchesDate && new Date(sale.date) >= new Date(startDate);
      }
      if (endDate) {
        // End of day
        const end = new Date(endDate);
        end.setHours(23, 59, 59, 999);
        matchesDate = matchesDate && new Date(sale.date) <= end;
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [sales, searchTerm, startDate, endDate, statusFilter]);

  const handleVoid = () => {
    if (!selectedSale) return;
    if (confirm(`Are you sure you want to VOID Sale #${selectedSale.id}? This will restore items to stock automatically.`)) {
      onVoidSale(selectedSale.id);
      setSelectedSale(null);
    }
  };

  const handleSettleDebt = async () => {
    if (!selectedSale) return;
    const debt = selectedSale.remainingAmount || selectedSale.total;
    if (confirm(`Confirm full payment of $${debt.toFixed(2)} for this invoice?`)) {
       await settleSaleDebt(selectedSale.id, debt, 'cash');
       // Refresh or close modal logic handled by context update
       setSelectedSale(prev => prev ? ({...prev, paymentStatus: 'paid', remainingAmount: 0, amountReceived: (prev.amountReceived || 0) + debt}) : null); 
    }
  };

  // --- Return Logic ---
  const toggleReturnMode = () => {
    setIsReturnMode(!isReturnMode);
    setReturnQuantities({});
  };

  const handleReturnQtyChange = (index: number, qty: number) => {
    const max = selectedSale?.items[index].quantity || 0;
    const val = Math.min(Math.max(0, qty), max);
    setReturnQuantities(prev => ({ ...prev, [index]: val }));
  };

  const calculateReturnTotal = () => {
    if (!selectedSale) return 0;
    return selectedSale.items.reduce((acc, item, index) => {
      const qty = returnQuantities[index] || 0;
      return acc + (item.sellPrice * qty);
    }, 0);
  };

  const handleSubmitReturn = async () => {
    if (!selectedSale) return;
    const itemsToReturn = Object.entries(returnQuantities)
      .filter(([_, qty]) => qty > 0)
      .map(([index, quantity]) => ({ itemIndex: parseInt(index), quantity }));

    if (itemsToReturn.length === 0) {
      alert("Please select at least one item to return.");
      return;
    }

    if (confirm(`Confirm refund of $${calculateReturnTotal().toFixed(2)}? This will restore stock.`)) {
      await processReturn(selectedSale, itemsToReturn, 'cash'); // Defaulting to cash refund
      setIsReturnMode(false);
      setSelectedSale(null);
      alert("Return processed successfully.");
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const isAdminOrManager = currentUser?.role === 'Admin' || currentUser?.role === 'Manager';

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Sales History & Audit</h2>
          <p className="text-slate-500">Manage invoices, credit sales, and void transactions.</p>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-end">
        <div className="flex-1 w-full">
           <label className="block text-xs font-medium text-slate-500 mb-1">Search</label>
           <div className="relative">
              <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder="Invoice ID or Customer Name"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
              />
           </div>
        </div>

        <div>
           <label className="block text-xs font-medium text-slate-500 mb-1">Start Date</label>
           <input
             type="date"
             value={startDate}
             onChange={e => setStartDate(e.target.value)}
             className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
           />
        </div>

        <div>
           <label className="block text-xs font-medium text-slate-500 mb-1">End Date</label>
           <input
             type="date"
             value={endDate}
             onChange={e => setEndDate(e.target.value)}
             className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
           />
        </div>

        <div>
           <label className="block text-xs font-medium text-slate-500 mb-1">Status</label>
           <select
             value={statusFilter}
             onChange={e => setStatusFilter(e.target.value as any)}
             className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white min-w-[120px]"
           >
             <option value="all">All Status</option>
             <option value="completed">Paid / Completed</option>
             <option value="unpaid">Unpaid / Credit</option>
             <option value="voided">Voided</option>
           </select>
        </div>
      </div>

      {/* List */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Date / ID</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Customer</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Items</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Total</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Status</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredSales.length === 0 ? (
                <tr>
                  <td colSpan={6} className="text-center py-8 text-slate-400">
                    No sales found matching your filters.
                  </td>
                </tr>
              ) : (
                filteredSales.map((sale) => (
                  <tr key={sale.id} className={`hover:bg-slate-50 transition-colors ${sale.type === 'return' ? 'bg-red-50/50' : ''}`}>
                    <td className="px-6 py-4">
                      <div className="font-bold text-slate-800">{new Date(sale.date).toLocaleDateString()}</div>
                      <div className="text-xs text-slate-500 font-mono mt-0.5">{sale.id}</div>
                      {sale.type === 'return' && <span className="text-[10px] bg-red-100 text-red-700 px-1.5 py-0.5 rounded font-bold uppercase mt-1 inline-block">Refund</span>}
                    </td>
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-700">{sale.customerName || 'Walk-in Customer'}</div>
                      <div className="text-xs text-slate-500 capitalize">{sale.paymentMethod}</div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <span className="bg-slate-100 px-2 py-1 rounded text-xs font-bold text-slate-600">
                        {sale.items.length} items
                      </span>
                    </td>
                    <td className={`px-6 py-4 text-right font-bold ${sale.type === 'return' ? 'text-red-600' : 'text-slate-800'}`}>
                      ${Math.abs(sale.total).toFixed(2)}
                    </td>
                    <td className="px-6 py-4 text-center">
                      {sale.status === 'voided' ? (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-red-100 text-red-700">
                          <Ban className="w-3 h-3 mr-1" /> Voided
                        </span>
                      ) : sale.paymentStatus === 'unpaid' ? (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-red-100 text-red-700">
                          <AlertTriangle className="w-3 h-3 mr-1" /> UNPAID
                        </span>
                      ) : sale.paymentStatus === 'partial' ? (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-orange-100 text-orange-700">
                          <History className="w-3 h-3 mr-1" /> Partial
                        </span>
                      ) : (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-green-100 text-green-700">
                          <CheckCircle className="w-3 h-3 mr-1" /> Paid
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => { setSelectedSale(sale); setIsReturnMode(false); setReturnQuantities({}); }}
                        className="p-2 bg-slate-100 text-slate-600 rounded hover:bg-slate-200 transition-colors"
                      >
                        <Eye className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Sale Detail Modal */}
      {selectedSale && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg max-h-[90vh] flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <div>
                 <h3 className="text-xl font-bold text-slate-800">
                    {isReturnMode ? 'Select Items to Return' : 'Invoice Details'}
                 </h3>
                 <p className="text-sm text-slate-500 font-mono">#{selectedSale.id}</p>
              </div>
              <div className="flex items-center space-x-2">
                 {selectedSale.status === 'voided' && (
                    <span className="px-3 py-1 bg-red-100 text-red-700 rounded-full text-xs font-bold uppercase tracking-wide flex items-center">
                       <RotateCcw className="w-3 h-3 mr-1" /> Stock Restored
                    </span>
                 )}
                 <button onClick={() => setSelectedSale(null)} className="text-slate-400 hover:text-slate-600">
                   <XCircle className="w-6 h-6" />
                 </button>
              </div>
            </div>

            <div className="p-6 overflow-y-auto flex-1">
               {!isReturnMode && (
                  <div className="flex justify-between mb-4 text-sm">
                     <div className="text-slate-500">
                        <p>Date: <span className="font-medium text-slate-700">{new Date(selectedSale.date).toLocaleString()}</span></p>
                        <p>Customer: <span className="font-medium text-slate-700">{selectedSale.customerName || 'Walk-in'}</span></p>
                     </div>
                     <div className="text-right text-slate-500">
                        <p>Method: <span className="font-medium text-slate-700 capitalize">{selectedSale.paymentMethod}</span></p>
                        <p>Status: <span className={`font-bold capitalize ${selectedSale.paymentStatus === 'paid' ? 'text-green-600' : 'text-orange-600'}`}>{selectedSale.paymentStatus || 'Paid'}</span></p>
                     </div>
                  </div>
               )}

               <div className="border rounded-lg overflow-hidden mb-6">
                  <table className="w-full text-sm">
                     <thead className="bg-slate-50 text-slate-500">
                        <tr>
                           {isReturnMode && <th className="px-4 py-2 w-16">Return</th>}
                           <th className="px-4 py-2 text-left">Item</th>
                           <th className="px-4 py-2 text-right">Qty</th>
                           <th className="px-4 py-2 text-right">Price</th>
                           <th className="px-4 py-2 text-right">Total</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-100">
                        {selectedSale.items.map((item, idx) => (
                           <tr key={idx} className={returnQuantities[idx] > 0 ? 'bg-red-50' : ''}>
                              {isReturnMode && (
                                 <td className="px-4 py-2">
                                    <input 
                                       type="number" 
                                       min="0" 
                                       max={item.quantity}
                                       value={returnQuantities[idx] || 0}
                                       onChange={(e) => handleReturnQtyChange(idx, parseInt(e.target.value) || 0)}
                                       className="w-16 border rounded p-1 text-center font-bold"
                                    />
                                 </td>
                              )}
                              <td className="px-4 py-2">
                                 <div className="font-medium text-slate-800">{item.name}</div>
                                 {item.selectedVariantId && <div className="text-xs text-slate-400">Variant</div>}
                              </td>
                              <td className="px-4 py-2 text-right">{item.quantity}</td>
                              <td className="px-4 py-2 text-right">${item.sellPrice.toFixed(2)}</td>
                              <td className="px-4 py-2 text-right font-bold">${(item.sellPrice * item.quantity).toFixed(2)}</td>
                           </tr>
                        ))}
                     </tbody>
                     <tfoot className="bg-slate-50 font-bold text-slate-800">
                        {!isReturnMode ? (
                           <>
                              <tr>
                                 <td colSpan={3} className="px-4 py-3 text-right">Subtotal</td>
                                 <td className="px-4 py-3 text-right">${(selectedSale.subtotal || selectedSale.total).toFixed(2)}</td>
                              </tr>
                              {selectedSale.discountAmount && selectedSale.discountAmount > 0 && (
                                 <tr className="text-green-600">
                                    <td colSpan={3} className="px-4 py-1 text-right">Discount</td>
                                    <td className="px-4 py-1 text-right">-${selectedSale.discountAmount.toFixed(2)}</td>
                                 </tr>
                              )}
                              <tr className="border-t border-slate-200">
                                 <td colSpan={3} className="px-4 py-3 text-right text-lg">Grand Total</td>
                                 <td className="px-4 py-3 text-right text-lg">${Math.abs(selectedSale.total).toFixed(2)}</td>
                              </tr>
                           </>
                        ) : (
                           <tr className="bg-red-50 text-red-700 border-t border-red-200">
                              <td colSpan={4} className="px-4 py-3 text-right text-lg">Refund Total</td>
                              <td className="px-4 py-3 text-right text-lg">${calculateReturnTotal().toFixed(2)}</td>
                           </tr>
                        )}
                     </tfoot>
                  </table>
               </div>

               {/* Debt Settlement Actions */}
               {(selectedSale.paymentStatus === 'unpaid' || selectedSale.paymentStatus === 'partial') && selectedSale.status !== 'voided' && !isReturnMode && (
                  <div className="mb-4 bg-orange-50 p-4 rounded-lg border border-orange-200">
                     <h4 className="font-bold text-orange-800 text-sm mb-2 flex items-center">
                        <Wallet className="w-4 h-4 mr-2" /> 
                        Outstanding Payment
                     </h4>
                     <p className="text-xs text-orange-700 mb-3">
                        This invoice has an outstanding balance of <span className="font-bold">${(selectedSale.remainingAmount || 0).toFixed(2)}</span>.
                     </p>
                     <button
                        onClick={handleSettleDebt}
                        className="w-full py-2 bg-slate-800 text-white rounded-lg text-sm font-bold hover:bg-slate-900 shadow-sm flex items-center justify-center"
                     >
                        <DollarSign className="w-4 h-4 mr-1" />
                        Settle Debt (Receive Full Payment)
                     </button>
                  </div>
               )}

               {selectedSale.status !== 'voided' && selectedSale.type !== 'return' && isAdminOrManager && !isReturnMode && (
                  <div className="grid grid-cols-2 gap-4">
                     <button 
                        onClick={toggleReturnMode}
                        className="py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-xs font-bold uppercase tracking-wide hover:bg-slate-50 shadow-sm flex items-center justify-center"
                     >
                        <Reply className="w-4 h-4 mr-2" /> Return / Refund
                     </button>
                     <button 
                        onClick={handleVoid}
                        className="py-2 bg-red-600 text-white rounded-lg text-xs font-bold uppercase tracking-wide hover:bg-red-700 shadow-sm flex items-center justify-center"
                     >
                        <Ban className="w-4 h-4 mr-2" /> Void Transaction
                     </button>
                  </div>
               )}
            </div>

            <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 rounded-b-xl">
               {isReturnMode ? (
                  <>
                     <button 
                        onClick={toggleReturnMode}
                        className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50"
                     >
                        Cancel Return
                     </button>
                     <button 
                        onClick={handleSubmitReturn}
                        className="px-6 py-2 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700 shadow-sm"
                     >
                        Confirm Refund
                     </button>
                  </>
               ) : (
                  <>
                     <button 
                        onClick={handlePrint}
                        className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50 flex items-center shadow-sm"
                     >
                        <Printer className="w-4 h-4 mr-2" />
                        Reprint Bill
                     </button>
                     <button 
                        onClick={() => setSelectedSale(null)}
                        className="px-4 py-2 bg-slate-800 text-white font-medium rounded-lg hover:bg-slate-900"
                     >
                        Close
                     </button>
                  </>
               )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Sale, CartItem } from '../types';
import { 
  Search, 
  Calendar, 
  Filter, 
  Eye, 
  RotateCcw, 
  Ban, 
  Printer, 
  CheckCircle, 
  XCircle, 
  AlertTriangle,
  History,
  DollarSign,
  Wallet,
  ArrowLeftRight,
  Reply
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

interface SalesHistoryProps {
  sales: Sale[];
  onVoidSale: (id: string) => void;
}

export const SalesHistory: React.FC<SalesHistoryProps> = ({ sales, onVoidSale }) => {
  const { currentUser, settleSaleDebt, processReturn } = useGlobal();
  const [searchTerm, setSearchTerm] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'completed' | 'voided' | 'unpaid'>('all');

  // Modal State
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [isReturnMode, setIsReturnMode] = useState(false);
  const [returnQuantities, setReturnQuantities] = useState<Record<number, number>>({});

  const filteredSales = useMemo(() => {
    return sales.filter(sale => {
      const matchesSearch = 
        sale.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (sale.customerName && sale.customerName.toLowerCase().includes(searchTerm.toLowerCase()));

      let matchesStatus = true;
      if (statusFilter === 'completed') matchesStatus = sale.status === 'completed' && sale.paymentStatus === 'paid';
      else if (statusFilter === 'unpaid') matchesStatus = sale.paymentStatus === 'unpaid' || sale.paymentStatus === 'partial';
      else if (statusFilter === 'voided') matchesStatus = sale.status === 'voided';

      let matchesDate = true;
      if (startDate) {
        matchesDate = matchesDate && new Date(sale.date) >= new Date(startDate);
      }
      if (endDate) {
        // End of day
        const end = new Date(endDate);
        end.setHours(23, 59, 59, 999);
        matchesDate = matchesDate && new Date(sale.date) <= end;
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [sales, searchTerm, startDate, endDate, statusFilter]);

  const handleVoid = () => {
    if (!selectedSale) return;
    if (confirm(`Are you sure you want to VOID Sale #${selectedSale.id}? This will restore items to stock automatically.`)) {
      onVoidSale(selectedSale.id);
      setSelectedSale(null);
    }
  };

  const handleSettleDebt = async () => {
    if (!selectedSale) return;
    const debt = selectedSale.remainingAmount || selectedSale.total;
    if (confirm(`Confirm full payment of $${debt.toFixed(2)} for this invoice?`)) {
       await settleSaleDebt(selectedSale.id, debt, 'cash');
       // Refresh or close modal logic handled by context update
       setSelectedSale(prev => prev ? ({...prev, paymentStatus: 'paid', remainingAmount: 0, amountReceived: (prev.amountReceived || 0) + debt}) : null); 
    }
  };

  // --- Return Logic ---
  const toggleReturnMode = () => {
    setIsReturnMode(!isReturnMode);
    setReturnQuantities({});
  };

  const handleReturnQtyChange = (index: number, qty: number) => {
    const max = selectedSale?.items[index].quantity || 0;
    const val = Math.min(Math.max(0, qty), max);
    setReturnQuantities(prev => ({ ...prev, [index]: val }));
  };

  const calculateReturnTotal = () => {
    if (!selectedSale) return 0;
    return selectedSale.items.reduce((acc, item, index) => {
      const qty = returnQuantities[index] || 0;
      return acc + (item.sellPrice * qty);
    }, 0);
  };

  const handleSubmitReturn = async () => {
    if (!selectedSale) return;
    const itemsToReturn = Object.entries(returnQuantities)
      .filter(([_, qty]) => (qty as number) > 0)
      .map(([index, quantity]) => ({ itemIndex: parseInt(index), quantity: quantity as number }));

    if (itemsToReturn.length === 0) {
      alert("Please select at least one item to return.");
      return;
    }

    if (confirm(`Confirm refund of $${calculateReturnTotal().toFixed(2)}? This will restore stock.`)) {
      await processReturn(selectedSale, itemsToReturn, 'cash'); // Defaulting to cash refund
      setIsReturnMode(false);
      setSelectedSale(null);
      alert("Return processed successfully.");
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const isAdminOrManager = currentUser?.role === 'Admin' || currentUser?.role === 'Manager';

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Sales History & Audit</h2>
          <p className="text-slate-500">Manage invoices, credit sales, and void transactions.</p>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-end">
        <div className="flex-1 w-full">
           <label className="block text-xs font-medium text-slate-500 mb-1">Search</label>
           <div className="relative">
              <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder="Invoice ID or Customer Name"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
              />
           </div>
        </div>

        <div>
           <label className="block text-xs font-medium text-slate-500 mb-1">Start Date</label>
           <input
             type="date"
             value={startDate}
             onChange={e => setStartDate(e.target.value)}
             className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
           />
        </div>

        <div>
           <label className="block text-xs font-medium text-slate-500 mb-1">End Date</label>
           <input
             type="date"
             value={endDate}
             onChange={e => setEndDate(e.target.value)}
             className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500"
           />
        </div>

        <div>
           <label className="block text-xs font-medium text-slate-500 mb-1">Status</label>
           <select
             value={statusFilter}
             onChange={e => setStatusFilter(e.target.value as any)}
             className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 bg-white min-w-[120px]"
           >
             <option value="all">All Status</option>
             <option value="completed">Paid / Completed</option>
             <option value="unpaid">Unpaid / Credit</option>
             <option value="voided">Voided</option>
           </select>
        </div>
      </div>

      {/* List */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Date / ID</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Customer</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Items</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Total</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Status</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredSales.length === 0 ? (
                <tr>
                  <td colSpan={6} className="text-center py-8 text-slate-400">
                    No sales found matching your filters.
                  </td>
                </tr>
              ) : (
                filteredSales.map((sale) => (
                  <tr key={sale.id} className={`hover:bg-slate-50 transition-colors ${sale.type === 'return' ? 'bg-red-50/50' : ''}`}>
                    <td className="px-6 py-4">
                      <div className="font-bold text-slate-800">{new Date(sale.date).toLocaleDateString()}</div>
                      <div className="text-xs text-slate-500 font-mono mt-0.5">{sale.id}</div>
                      {sale.type === 'return' && <span className="text-[10px] bg-red-100 text-red-700 px-1.5 py-0.5 rounded font-bold uppercase mt-1 inline-block">Refund</span>}
                    </td>
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-700">{sale.customerName || 'Walk-in Customer'}</div>
                      <div className="text-xs text-slate-500 capitalize">{sale.paymentMethod}</div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <span className="bg-slate-100 px-2 py-1 rounded text-xs font-bold text-slate-600">
                        {sale.items.length} items
                      </span>
                    </td>
                    <td className={`px-6 py-4 text-right font-bold ${sale.type === 'return' ? 'text-red-600' : 'text-slate-800'}`}>
                      ${Math.abs(sale.total).toFixed(2)}
                    </td>
                    <td className="px-6 py-4 text-center">
                      {sale.status === 'voided' ? (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-red-100 text-red-700">
                          <Ban className="w-3 h-3 mr-1" /> Voided
                        </span>
                      ) : sale.paymentStatus === 'unpaid' ? (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-red-100 text-red-700">
                          <AlertTriangle className="w-3 h-3 mr-1" /> UNPAID
                        </span>
                      ) : sale.paymentStatus === 'partial' ? (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-orange-100 text-orange-700">
                          <History className="w-3 h-3 mr-1" /> Partial
                        </span>
                      ) : (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-green-100 text-green-700">
                          <CheckCircle className="w-3 h-3 mr-1" /> Paid
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => { setSelectedSale(sale); setIsReturnMode(false); setReturnQuantities({}); }}
                        className="p-2 bg-slate-100 text-slate-600 rounded hover:bg-slate-200 transition-colors"
                      >
                        <Eye className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
