                        Confirm Refund
                     </button>
                  </>
               ) : (
                  <>
                     <button 
                        onClick={handlePrint}
                        className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50 flex items-center shadow-sm"
