                              <tr className="border-t border-slate-200">
                                 <td colSpan={3} className="px-4 py-3 text-right text-lg">Grand Total</td>
                                 <td className="px-4 py-3 text-right text-lg">${Math.abs(selectedSale.total).toFixed(2)}</td>
                              </tr>
                           </>
                        ) : (
                           <tr className="bg-red-50 text-red-700 border-t border-red-200">
                              <td colSpan={4} className="px-4 py-3 text-right text-lg">Refund Total</td>
                              <td className="px-4 py-3 text-right text-lg">${calculateReturnTotal().toFixed(2)}</td>
                           </tr>
                        )}
                     </tfoot>
                  </table>
               </div>

               {/* Debt Settlement Actions */}
               {(selectedSale.paymentStatus === 'unpaid' || selectedSale.paymentStatus === 'partial') && selectedSale.status !== 'voided' && !isReturnMode && (
                  <div className="mb-4 bg-orange-50 p-4 rounded-lg border border-orange-200">
                     <h4 className="font-bold text-orange-800 text-sm mb-2 flex items-center">
                        <Wallet className="w-4 h-4 mr-2" /> 
                        Outstanding Payment
                     </h4>
                     <p className="text-xs text-orange-700 mb-3">
                        This invoice has an outstanding balance of <span className="font-bold">${(selectedSale.remainingAmount || 0).toFixed(2)}</span>.
                     </p>
                     <button
                        onClick={handleSettleDebt}
                        className="w-full py-2 bg-slate-800 text-white rounded-lg text-sm font-bold hover:bg-slate-900 shadow-sm flex items-center justify-center"
                     >
                        <DollarSign className="w-4 h-4 mr-1" />
                        Settle Debt (Receive Full Payment)
                     </button>
                  </div>
               )}

               {selectedSale.status !== 'voided' && selectedSale.type !== 'return' && isAdminOrManager && !isReturnMode && (
                  <div className="grid grid-cols-2 gap-4">
                     <button 
                        onClick={toggleReturnMode}
                        className="py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-xs font-bold uppercase tracking-wide hover:bg-slate-50 shadow-sm flex items-center justify-center"
                     >
                        <Reply className="w-4 h-4 mr-2" /> Return / Refund
                     </button>
                     <button 
                        onClick={handleVoid}
                        className="py-2 bg-red-600 text-white rounded-lg text-xs font-bold uppercase tracking-wide hover:bg-red-700 shadow-sm flex items-center justify-center"
                     >
                        <Ban className="w-4 h-4 mr-2" /> Void Transaction
                     </button>
                  </div>
               )}
            </div>

            <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 rounded-b-xl">
               {isReturnMode ? (
                  <>
                     <button 
                        onClick={toggleReturnMode}
                        className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50"
                     >
                        Cancel Return
                     </button>
                     <button 
                        onClick={handleSubmitReturn}
                        className="px-6 py-2 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700 shadow-sm"
                     >
                        Confirm Refund
                     </button>
                  </>
               ) : (
                  <>
                     <button 
                        onClick={handlePrint}
                        className="px-4 py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50 flex items-center shadow-sm"
                     >
                        <Printer className="w-4 h-4 mr-2" />
                        Reprint Bill
                     </button>
                     <button 
                        onClick={() => setSelectedSale(null)}
                        className="px-4 py-2 bg-slate-800 text-white font-medium rounded-lg hover:bg-slate-900"
                     >
                        Close
                     </button>
                  </>
               )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

'use client';
import { CustomerManagement } from '../../components/CustomerManagement';
import { useGlobal } from '../../context/GlobalContext';

export default function CustomersPage() {
  const { customers, sales, addCustomer, updateCustomer, deleteCustomer } = useGlobal();

  return (
    <CustomerManagement
      customers={customers}
      sales={sales}
      onAddCustomer={addCustomer}
      onUpdateCustomer={updateCustomer}
      onDeleteCustomer={deleteCustomer}
    />
  );
}

import React, { useState, useMemo } from 'react';
import { Customer, CustomerLevel, Sale } from '../types';
import { 
  Plus, Edit2, Trash2, Search, User, Phone, MapPin, Mail, Award, X, 
  Check, Tag, Star, AlertCircle, ArrowLeft, TrendingUp, Wallet, Clock, 
  ShoppingBag, CheckCircle, History
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

interface CustomerManagementProps {
  customers: Customer[];
  sales?: Sale[]; // Optional for backward compat, but expected
  onAddCustomer: (customer: Customer) => void;
  onUpdateCustomer: (customer: Customer) => void;
  onDeleteCustomer: (id: string) => void;
}

export const CustomerManagement: React.FC<CustomerManagementProps> = ({
  customers = [],
  sales = [],
  onAddCustomer,
  onUpdateCustomer,
  onDeleteCustomer
}) => {
  const { customerLevels, addCustomerLevel, updateCustomerLevel, deleteCustomerLevel, formatPrice } = useGlobal();
  const safeLevels = customerLevels || []; 

  const [activeTab, setActiveTab] = useState<'customers' | 'levels'>('customers');
  const [searchTerm, setSearchTerm] = useState('');

  // View State
  const [viewingCustomer, setViewingCustomer] = useState<Customer | null>(null);

  // Customer Modal
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<Customer>>({
    name: '',
    code: '',
    phone: '',
    taxId: '',
    address: '',
    email: '',
    loyaltyPoints: 0,
    notes: '',
    levelId: ''
  });

  // Level Modal
  const [isLevelModalOpen, setIsLevelModalOpen] = useState(false);
  const [editingLevelId, setEditingLevelId] = useState<string | null>(null);
  const [levelForm, setLevelForm] = useState<Partial<CustomerLevel>>({
    name: '',
    discountPercentage: 0,
    color: '#64748b'
  });

  // Filtering
  const filteredCustomers = (customers || []).filter(c => {
    if (!c) return false;
    const term = searchTerm.toLowerCase();
    const nameMatch = (c.name || '').toLowerCase().includes(term);
    const phoneMatch = (c.phone || '').toLowerCase().includes(term);
    const codeMatch = (c.code || '').toLowerCase().includes(term);
    return nameMatch || phoneMatch || codeMatch;
  });

  // Customer Analytics
  const customerStats = useMemo(() => {
    if (!viewingCustomer) return null;

    const customerSales = sales.filter(s => s.customerId === viewingCustomer.id && s.status !== 'voided');
    const totalSpent = customerSales.reduce((acc, s) => acc + s.total, 0);
    const totalDebt = customerSales
      .filter(s => s.paymentStatus === 'unpaid' || s.paymentStatus === 'partial')
      .reduce((acc, s) => acc + (s.remainingAmount || 0), 0);
    const lastVisit = customerSales.length > 0 ? new Date(customerSales[0].date) : null;
    const avgOrderValue = customerSales.length > 0 ? totalSpent / customerSales.length : 0;

    return {
      history: customerSales,
      totalSpent,
      totalDebt,
      lastVisit,
      avgOrderValue,
      visitCount: customerSales.length
    };
  }, [viewingCustomer, sales]);

  const handleOpenModal = (customer?: Customer) => {
    if (customer) {
      setEditingId(customer.id);
      setFormData(customer);
    } else {
      setEditingId(null);
      setFormData({
        name: '',
        code: `CUST-${String((customers || []).length + 1).padStart(3, '0')}`,
        phone: '',
        taxId: '',
        address: '',
        email: '',
        loyaltyPoints: 0,
        notes: '',
        levelId: ''
      });
    }
    setIsModalOpen(true);
  };

  const handleOpenLevelModal = (level?: CustomerLevel) => {
    if (level) {
      setEditingLevelId(level.id);
      setLevelForm(level);
    } else {
      setEditingLevelId(null);
      setLevelForm({
        name: '',
        discountPercentage: 0,
        color: '#64748b'
      });
    }
    setIsLevelModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    if (editingId) {
      onUpdateCustomer({ ...formData, id: editingId } as Customer);
    } else {
      onAddCustomer({ ...formData, id: `c-${Date.now()}` } as Customer);
    }
    setIsModalOpen(false);
  };

  const handleLevelSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!levelForm.name) return;

    if (editingLevelId) {
      updateCustomerLevel({ ...levelForm, id: editingLevelId } as CustomerLevel);
    } else {
      addCustomerLevel({ ...levelForm, id: `lvl-${Date.now()}` } as CustomerLevel);
    }
    setIsLevelModalOpen(false);
  };

  if (viewingCustomer && customerStats) {
    const level = viewingCustomer.level || safeLevels.find(l => l.id === viewingCustomer.levelId);

    return (
      <div className="space-y-6 h-full flex flex-col animate-fade-in">
        {/* Detail Header */}
        <div className="flex items-center justify-between">
          <button 
            onClick={() => setViewingCustomer(null)}
            className="flex items-center text-slate-500 hover:text-slate-800 transition-colors"
          >
            <ArrowLeft className="w-5 h-5 mr-2" /> Back to List
          </button>
          <div className="flex space-x-2">
            <button onClick={() => handleOpenModal(viewingCustomer)} className="px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 font-medium hover:bg-slate-50 flex items-center">
              <Edit2 className="w-4 h-4 mr-2" /> Edit Profile
            </button>
          </div>
        </div>

        {/* Profile Card */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
           <div className="flex flex-col md:flex-row gap-6">
              <div className="flex items-start">
                 <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center text-slate-400 border-2 border-white shadow-sm">
                    <User className="w-10 h-10" />
                 </div>
                 <div className="ml-4">
                    <h2 className="text-2xl font-bold text-slate-800">{viewingCustomer.name}</h2>
                    <p className="text-slate-500 text-sm flex items-center mt-1">
                       <span className="font-mono bg-slate-100 px-1.5 rounded text-slate-600 mr-2">{viewingCustomer.code}</span>
                       {viewingCustomer.phone && <span className="flex items-center mr-3"><Phone className="w-3 h-3 mr-1" /> {viewingCustomer.phone}</span>}
                       {viewingCustomer.email && <span className="flex items-center"><Mail className="w-3 h-3 mr-1" /> {viewingCustomer.email}</span>}
                    </p>
                    {level && (
                       <div className="mt-3 inline-flex items-center px-3 py-1 rounded-full text-xs font-bold text-white shadow-sm" style={{ backgroundColor: level.color || '#64748b' }}>
                          <Star className="w-3 h-3 mr-1" fill="currentColor" />
                          {level.name} Member ({level.discountPercentage}% Off)
                       </div>
                    )}
                 </div>
              </div>

              {/* Key Stats */}
              <div className="flex-1 grid grid-cols-2 md:grid-cols-4 gap-4">
                 <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                    <p className="text-xs text-blue-600 uppercase font-bold mb-1">Total Spent</p>
                    <p className="text-2xl font-bold text-blue-900">{formatPrice(customerStats.totalSpent)}</p>
                 </div>
                 <div className="bg-orange-50 p-4 rounded-xl border border-orange-100">
                    <p className="text-xs text-orange-600 uppercase font-bold mb-1">Outstanding Debt</p>
                    <p className="text-2xl font-bold text-orange-900">{formatPrice(customerStats.totalDebt)}</p>
                 </div>
                 <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100">
                    <p className="text-xs text-yellow-600 uppercase font-bold mb-1">Loyalty Points</p>
                    <p className="text-2xl font-bold text-yellow-900">{viewingCustomer.loyaltyPoints}</p>
                 </div>
                 <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                    <p className="text-xs text-slate-500 uppercase font-bold mb-1">Last Visit</p>
                    <p className="text-lg font-bold text-slate-700">
                       {customerStats.lastVisit ? customerStats.lastVisit.toLocaleDateString() : 'Never'}
                    </p>
                 </div>
              </div>
           </div>

           {viewingCustomer.address && (
              <div className="mt-6 pt-4 border-t border-slate-100 text-sm text-slate-600 flex items-start">
                 <MapPin className="w-4 h-4 mr-2 mt-0.5 text-slate-400" />
                 {viewingCustomer.address}
              </div>
           )}
        </div>

        {/* Sales History */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 flex flex-col overflow-hidden">
           <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
              <h3 className="font-bold text-slate-700 flex items-center">
                 <History className="w-5 h-5 mr-2 text-slate-500" />
                 Transaction History
              </h3>
              <span className="text-xs font-medium bg-white px-2 py-1 rounded border border-slate-200 text-slate-500">
                 {customerStats.visitCount} orders
              </span>
           </div>
           <div className="overflow-y-auto flex-1">
              {customerStats.history.length === 0 ? (
                 <div className="text-center py-12 text-slate-400">
                    <ShoppingBag className="w-12 h-12 mx-auto mb-2 opacity-20" />
                    <p>No purchase history found.</p>
                 </div>
              ) : (
                 <table className="w-full text-left">
                    <thead className="bg-slate-50 text-xs text-slate-500 uppercase font-semibold sticky top-0">
                       <tr>
                          <th className="px-6 py-3">Date / Invoice</th>
                          <th className="px-6 py-3">Items</th>
                          <th className="px-6 py-3 text-right">Total</th>
                          <th className="px-6 py-3 text-center">Status</th>
                          <th className="px-6 py-3 text-center">Payment</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {customerStats.history.map(sale => (
                          <tr key={sale.id} className="hover:bg-slate-50 transition-colors">
                             <td className="px-6 py-4">
                                <div className="font-medium text-slate-800">{new Date(sale.date).toLocaleDateString()}</div>
                                <div className="text-xs text-slate-500 font-mono">{sale.id}</div>
                             </td>
                             <td className="px-6 py-4 text-slate-600 text-sm">
                                {sale.items.length} items
                                <div className="text-xs text-slate-400 truncate max-w-[200px]">
                                   {sale.items.map(i => i.name).join(', ')}
                                </div>
                             </td>
                             <td className="px-6 py-4 text-right font-bold text-slate-800">
                                {formatPrice(sale.total)}
                             </td>
                             <td className="px-6 py-4 text-center">
                                <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-bold ${
                                   sale.paymentStatus === 'paid' ? 'bg-green-100 text-green-700' :
                                   sale.paymentStatus === 'partial' ? 'bg-orange-100 text-orange-700' :
                                   'bg-red-100 text-red-700'
                                }`}>
                                   {sale.paymentStatus === 'paid' && <CheckCircle className="w-3 h-3 mr-1" />}
                                   {sale.paymentStatus === 'unpaid' && <AlertCircle className="w-3 h-3 mr-1" />}
                                   {sale.paymentStatus}
                                </span>
                             </td>
                             <td className="px-6 py-4 text-center text-sm capitalize text-slate-600">
                                {sale.paymentMethod}
                             </td>
                          </tr>
                       ))}
                    </tbody>
                 </table>
              )}
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Customer Management</h2>
          <p className="text-slate-500">Manage customer profiles and membership tiers.</p>
        </div>
        <div className="flex space-x-2 overflow-x-auto pb-1 md:pb-0">
           <button 
            onClick={() => setActiveTab('customers')}
            className={`px-4 py-2 rounded-lg font-medium transition-colors whitespace-nowrap ${activeTab === 'customers' ? 'bg-slate-800 text-white' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'}`}
          >
            Customers
          </button>
          <button 
            onClick={() => setActiveTab('levels')}
            className={`px-4 py-2 rounded-lg font-medium transition-colors whitespace-nowrap ${activeTab === 'levels' ? 'bg-slate-800 text-white' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'}`}
          >
            Membership Levels
          </button>
        </div>
      </div>

      {activeTab === 'customers' && (
        <>
          <div className="flex flex-col md:flex-row gap-4">
            <div className="relative flex-1 bg-white p-4 rounded-xl shadow-sm border border-slate-200">
              <Search className="absolute left-7 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
              <input
                type="text"
                placeholder="Search by Name, Phone or Code..."
                className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <button 
              onClick={() => handleOpenModal()}
              className="flex items-center justify-center px-6 py-4 bg-construction-orange text-white rounded-xl hover:bg-orange-600 transition-colors font-medium shadow-sm whitespace-nowrap"
            >
              <Plus className="w-5 h-5 mr-2" />
              Add Customer
            </button>
          </div>

          <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 border-b border-slate-100">
                  <tr>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase whitespace-nowrap">Customer</th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase whitespace-nowrap">Contact</th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase whitespace-nowrap">Membership</th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center whitespace-nowrap">Loyalty</th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right whitespace-nowrap">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {filteredCustomers.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="text-center py-8 text-slate-400">
                        {customers && customers.length > 0 
                          ? `No customers found matching "${searchTerm}"`
                          : "No customers yet. Click 'Add Customer' to start."}
                      </td>
                    </tr>
                  ) : (
                    filteredCustomers.map((customer) => {
                      const level = customer.level || safeLevels.find(l => l.id === customer.levelId);

                      return (
                        <tr key={customer.id} className="hover:bg-slate-50 transition-colors cursor-pointer group" onClick={() => setViewingCustomer(customer)}>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center space-x-3">
                              <div className="p-2 bg-blue-50 text-blue-600 rounded-full group-hover:bg-blue-100 transition-colors">
                                <User className="w-5 h-5" />
                              </div>
                              <div>
                                <div className="font-bold text-slate-800">{customer.name}</div>
                                <div className="text-xs text-slate-500 font-mono bg-slate-100 px-1.5 py-0.5 rounded inline-block mt-1">
                                  {customer.code}
                                </div>
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 text-sm text-slate-600">
                            <div className="flex flex-col space-y-1">
                              {customer.phone && (
                                <div className="flex items-center">
                                  <Phone className="w-3 h-3 mr-1.5 text-slate-400" />
                                  {customer.phone}
                                </div>
                              )}
                              {customer.email && (
                                <div className="flex items-center">
                                  <Mail className="w-3 h-3 mr-1.5 text-slate-400" />
                                  {customer.email}
                                </div>
                              )}
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                             {level ? (
                               <span 
                                className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold text-white shadow-sm"
                                style={{ backgroundColor: level.color || '#64748b' }}
                               >
                                 <Star className="w-3 h-3 mr-1" fill="currentColor" />
                                 {level.name} ({level.discountPercentage}%)
                               </span>
                             ) : (
                               <span className="text-xs text-slate-400 italic">No Level</span>
                             )}
                          </td>
                          <td className="px-6 py-4 text-center whitespace-nowrap">
                            <div className="inline-flex items-center px-3 py-1 bg-yellow-50 text-yellow-700 rounded-full text-xs font-bold border border-yellow-200">
                              <Award className="w-3 h-3 mr-1" />
                              {customer.loyaltyPoints || 0} pts
                            </div>
                          </td>
                          <td className="px-6 py-4 text-right whitespace-nowrap">
                            <div className="flex justify-end space-x-2">
                              <button onClick={(e) => { e.stopPropagation(); handleOpenModal(customer); }} className="p-1.5 text-slate-400 hover:text-primary-600 hover:bg-slate-100 rounded transition-colors">
                                <Edit2 className="w-4 h-4" />
                              </button>
                              <button 
                                onClick={(e) => {
                                   e.stopPropagation();
                                   if(confirm(`Delete customer ${customer.name}?`)) onDeleteCustomer(customer.id);
                                }} 
                                className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-slate-100 rounded transition-colors"
                              >
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}

      {activeTab === 'levels' && (
        <div className="flex flex-col md:flex-row gap-6 h-full">
           <div className="w-full md:w-1/3 flex flex-col gap-4">
              <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                 <h3 className="font-bold text-slate-800 mb-2">About Membership Levels</h3>
                 <p className="text-sm text-slate-500 mb-4">
                    Create tiers to automatically apply discounts at the POS. Assign customers to tiers to reward loyalty.
                 </p>
                 <button 
                    onClick={() => handleOpenLevelModal()}
                    className="w-full py-3 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors font-medium flex items-center justify-center"
                 >
                    <Plus className="w-4 h-4 mr-2" />
                    Create New Level
                 </button>
              </div>
           </div>

           <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
              <div className="p-4 border-b border-slate-100 bg-slate-50">
                 <h3 className="font-bold text-slate-700">Active Membership Tiers</h3>
              </div>
              <div className="overflow-y-auto flex-1 p-4 space-y-3">
                 {safeLevels.length === 0 ? (
                    <div className="text-center py-10 text-slate-400">
                       <AlertCircle className="w-10 h-10 mx-auto mb-2 opacity-30" />
                       <p>No membership levels defined.</p>
                    </div>
                 ) : (
                    safeLevels.map(level => (
                       <div key={level.id} className="flex items-center justify-between p-4 border border-slate-200 rounded-xl hover:border-blue-300 hover:shadow-sm transition-all bg-white">
                          <div className="flex items-center">
                             <div 
                                className="w-10 h-10 rounded-full flex items-center justify-center text-white font-bold shadow-sm mr-4"
                                style={{ backgroundColor: level.color || '#64748b' }}
                             >
                                {level.discountPercentage}%
                             </div>
                             <div>
                                <h4 className="font-bold text-slate-800">{level.name}</h4>
                                <p className="text-xs text-slate-500">Auto-applies {level.discountPercentage}% discount</p>
                             </div>
                          </div>
                          <div className="flex space-x-2">
                             <button onClick={() => handleOpenLevelModal(level)} className="p-2 text-slate-400 hover:text-blue-600 rounded hover:bg-blue-50">
                                <Edit2 className="w-4 h-4" />
                             </button>
                             <button 
